const C: Record<string, string[]> = {"Mishneh Torah, Admission into the Sanctuary 7":["כָּל הַמּוּמִין הַפּוֹסְלִים בָּאָדָם וּבַבְּהֵמָה חֲמִשִּׁים וְזֶהוּ פְּרָטָן:","חֲמִשָּׁה בָּאֹזֶן. וְאֵלּוּ הֵן. מִי שֶׁנִּפְגַּם סְחוּס אָזְנוֹ כְּדֵי שֶׁתַּחְגֹּר הַצִּפֹּרֶן בַּפְּגָם. אֲבָל הָעוֹר הַמֻּקָּף לִסְחוּס הָאֹזֶן אֵין בּוֹ מוּם בֵּין נִקַּב בֵּין נִסְדַּק:","מִי שֶׁנִּסְדַּק סְחוּס אָזְנוֹ בְּכָל שֶׁהוּא אַף עַל פִּי שֶׁלֹּא חָסֵר. מִי שֶׁנִּקַּב סְחוּס אָזְנוֹ כְּכַרְשִׁינָה בֵּין נֶקֶב עָגֹל בֵּין נֶקֶב אָרֹךְ אִם מִצְטָרֵף לְכַרְשִׁינָה הֲרֵי זֶה מוּם. מִי שֶׁיָּבְשָׁה אָזְנוֹ כְּדֵי שֶׁתִּנָּקֵב וְלֹא תּוֹצִיא דָּם. מִי שֶׁהָיְתָה אָזְנוֹ כְּפוּלָה לִשְׁתַּיִם. אֲפִלּוּ הַגְּדִי שֶׁדֶּרֶךְ אָזְנָיו לִהְיוֹתָן נוֹטוֹת וּכְפוּלוֹת וּבִלְבַד שֶׁיִּהְיוּ לוֹ שְׁנֵי סְחוּסִין. אֲבָל אִם אֵין לָהּ אֶלָּא סְחוּס אֶחָד וַהֲרֵי הוּא כְּגוּף אֶחָד שֶׁנִּכְפַּל כָּשֵׁר:","שְׁלֹשָׁה בְּרִיס שֶׁל עַיִן וְאֵלּוּ הֵן. מִי שֶׁנִּקַּב רִיס מֵרִיסֵי עֵינָיו בְּכָל שֶׁהוּא. מִי שֶׁנִּסְדַּק רִיס מֵרִיסֵי עֵינָיו בְּכָל שֶׁהוּא. [מִי שֶׁנִּפְגַּם רִיס מֵרִיסֵי עֵינָיו בְּכָל שֶׁהוּא]. וּשְׁלֹשָׁה מוּמִין אֵלּוּ בִּכְלַל (ויקרא כב כב) \"חָרוּץ\" הָאָמוּר בַּתּוֹרָה:","שְׁמוֹנָה בָּעַיִן וְאֵלּוּ הֵן. הָעִוֵּר בֵּין בְּאֶחָד מֵעֵינָיו בֵּין מִשְּׁתֵּיהֶן. מִי שֶׁאֵינוֹ רוֹאֶה בִּשְׁתֵּי עֵינָיו אוֹ בְּאַחַת מֵהֶן. אַף עַל פִּי שֶׁאֵין נִרְאָה בָּהֶן שִׁנּוּי כְּלָל מֵחֲמַת שֶׁיָּרְדוּ מַיִם קְבוּעִים כְּנֶגֶד רוֹאוֹתָיו. מִי שֶׁאֵינוֹ רוֹאֶה בְּעֵינָיו אוֹ בְּאַחַת מֵהֶן רְאִיָּה בְּרוּרָה מֵחֲמַת שֶׁהָיָה בָּהּ סַנְוֵרִים קְבוּעִים. מִי שֶׁבְּעֵינוֹ כְּמוֹ עֵנָב אַף עַל פִּי שֶׁהוּא רוֹאֶה. מִי שֶׁיָּצָא בָּשָׂר יָתֵר בְּעֵינוֹ עַד שֶׁחִפָּה מְעַט מִן הַשָּׁחֹר שֶׁל עַיִן. מִי שֶׁנִּמְשַׁךְ הַלֹּבֶן שֶׁל עַיִן וְנִכְנַס מִמֶּנּוּ מְעַט בַּשָּׁחֹר עַד שֶׁנִּמְצָא הַשָּׁחֹר מְעֹרָב בַּלֹּבֶן וְהוּא (ויקרא כא כ) \"תְּבַלֻּל\" הָאָמוּר בַּתּוֹרָה. אֲבָל אִם יָצָא מִן הַשָּׁחֹר לְתוֹךְ הַלָּבָן אֵינוֹ מוּם שֶׁאֵין מוּמִין בְּלָבָן. מִי שֶׁהָיְתָה נְקֻדָּה לְבָנָה בְּתוֹךְ הַשָּׁחֹר וְזֶהוּ (ויקרא כא כ) \"דַּק\" הָאָמוּר בַּתּוֹרָה וְהוּא שֶׁתִּהְיֶה צָפָה עַל גַּבֵּי הַשָּׁחֹר. אֲבָל אִם לֹא הָיְתָה צָפָה אוֹ שֶׁהָיְתָה מְשֻׁקַּעַת בְּשָׁחֹר אֵינוֹ מוּם. וְכֵן אִם הָיְתָה נְקֻדָּה שְׁחֹרָה בְּתוֹךְ הַלֹּבֶן אֲפִלּוּ צָפָה אֵינוֹ מוּם שֶׁאֵין מוּמִים בְּלָבָן. הָיְתָה נְקֻדָּה שְׁחוֹרָה שׁוֹקַעַת בְּתוֹךְ הַשָּׁחֹר אַף זֶה נִקְרָא דַּק. אֲבָל אִם הָיְתָה צָפָה הוֹאִיל וְהִיא שְׁחֹרָה בְּשָׁחֹר אֵינוֹ מוּם:","שְׁלֹשָׁה בַּחֹטֶם. וְאֵלּוּ הֵן. מִי שֶׁנִּקַּב חָטְמוֹ אֲפִלּוּ מִצַּד אֶחָד. מִי שֶׁנִּסְדַּק חָטְמוֹ. מִי שֶׁנִּפְגַּם חָטְמוֹ:","שִׁשָּׁה בַּפֶּה. וְאֵלּוּ הֵן. מִי שֶׁנִּקַּב שְׂפָתוֹ אֲפִלּוּ אַחַת מֵהֶן. מִי שֶׁנִּפְגְּמָה שְׂפָתוֹ. מִי שֶׁנִּסְדְּקָה שְׂפָתוֹ וְהוּא שֶׁנִּסְדַּק מִזֵּר שֶׁלָּהּ עַד שֶׁתֵּחָלֵק לִשְׁנֵי רָאשִׁים. מִי שֶׁעֶצֶם לֶחְיוֹ הַתַּחְתּוֹן עוֹדֵף עַל הָעֶלְיוֹן כָּל שֶׁהוּא. מִי שֶׁפִּיו נִבְלַם מֵחֲמַת גּוּפוֹ וּבְרִיָּתוֹ. אֲבָל אִם נִבְלַם מֵחֲמַת הָרוּחַ אֵינוֹ מוּם. מִי שֶׁנִּטַּל רֹב הַמְדַבֵּר שֶׁל לְשׁוֹנוֹ:","שְׁנֵים עָשָׂר בְּאֵיבְרֵי הַזֶּרַע וְאֵלּוּ הֵן. מִי שֶׁנִּמְעַךְ הַגִּיד שֶׁלּוֹ. אוֹ נִכְתַּת. אוֹ נִתַּק. אוֹ נִכְרַת. מִי שֶׁנִּמְעֲכוּ הַבֵּיצִים שֶׁלּוֹ אוֹ אַחַת מֵהֶן. אוֹ נִכְתְּתוּ אוֹ אַחַת מֵהֶן. אוֹ נִתְּקוּ אוֹ אַחַת מֵהֶן. אוֹ נִכְרְתוּ אוֹ אַחַת מֵהֶן. מִי שֶׁאֵין לוֹ אֶלָּא בֵּיצָה אַחַת אַף עַל פִּי שֶׁיֵּשׁ לוֹ שְׁנֵי כִּיסִין. מִי שֶׁשְּׁתֵּי בֵּיצָיו בְּכִיס אֶחָד. הַטֻּמְטוּם. הָאַנְדְּרוֹגִינוּס:","שִׁשָּׁה בַּיָּדַיִם וּבָרַגְלַיִם וְאֵלּוּ הֵן. הַפִּסֵּחַ. וּמִי שֶׁנִּשְׁמְטָה יְרֵכוֹ הוּא (ויקרא כא יח) (ויקרא כב כג) \"שָׂרוּעַ\" הָאָמוּר בַּתּוֹרָה. מִי שֶׁאַחַת מִיַּרְכוֹתָיו גְּבוֹהָה מֵחֲבֶרְתָּהּ. מִי שֶׁנִּשְׁבַּר עֶצֶם יָדוֹ וְהוּא שֶׁיִּהְיֶה נִכָּר. מִי שֶׁנִּשְׁבַּר עֶצֶם רַגְלוֹ וְהוּא שֶׁיִּהְיֶה נִכָּר. אַף עַל פִּי שֶׁאֵינוֹ נִכָּר כְּשֶׁעוֹמֵד אִם נִכָּר כְּשֶׁיְּהַלֵּךְ הֲרֵי זֶה מוּם. מִי שֶׁרַגְלָיו מְבֻלָּמוֹת מֵחֲמַת עַצְמָן וּבְרִיָּתָן. אֲבָל אִם הָיוּ מְבֻלָּמוֹת מֵחֲמַת הָרוּחַ אֵינוֹ מוּם:","אַרְבָּעָה רְאוּיִין לִהְיוֹת בְּכָל הַגּוּף וְאֵלּוּ הֵן. מִי שֶׁיֵּשׁ בּוֹ גָּרָב יָבֵשׁ כָּל שֶׁהוּא וְזֶהוּ הַ (ויקרא כא כ) (ויקרא כב כב) \"גָּרָב\" הָאָמוּר בַּתּוֹרָה. מִי שֶׁיֵּשׁ בּוֹ יַבֶּלֶת שֶׁיֵּשׁ בָּהּ עֶצֶם וְזֶה הוּא (ויקרא כב כב) \"יַבֶּלֶת\" הָאֲמוּרָה בַּתּוֹרָה. מִי שֶׁיֵּשׁ בּוֹ חֲזָזִית מִצְרִית כָּל שֶׁהִיא וְהִיא חֲזָזִית קָשָׁה וּכְעוּרָה וְזוֹ הוּא (ויקרא כא כ) (ויקרא כב כב) \"יַלֶּפֶת\" הָאֲמוּרָה בַּתּוֹרָה:","כָּל עֶצֶם שֶׁבְּגָלוּי שֶׁנֶּחְרַץ בּוֹ חָרִיץ הֲרֵי זֶה מוּם וְהוּא בִּכְלַל (ויקרא כב כב) \"חָרוּץ\" הָאֲמוּרָה בַּתּוֹרָה. וְאֵין הַצְּלָעוֹת בִּכְלַל עֲצָמוֹת שֶׁבְּגָלוּי:","וְעוֹד יֵשׁ שָׁם שְׁלֹשָׁה מוּמִין אֲחֵרִים וְאֵלּוּ הֵן. הַזָּקֵן שֶׁהִגִּיעַ לִהְיוֹת רוֹתֵת וְרוֹעֵד כְּשֶׁהוּא עוֹמֵד. הַחוֹלֶה כְּשֶׁהוּא רוֹעֵד מִפְּנֵי חָלְיוֹ וְכִשְׁלוֹן כֹּחוֹ. אֲבָל הַטְּרֵפָה כָּשֵׁר בָּאָדָם וּפָסוּל בִּבְהֵמָה. וְכֵן יוֹצֵא דֹּפֶן כָּשֵׁר בָּאָדָם וּפָסוּל בִּבְהֵמָה:","הַמְזֹהָם וְכֹהֵן שֶׁהוּא מְזֹהָם בְּזֵעָתוֹ רוֹחֵץ וְשָׁף כָּל גּוּפוֹ בְּבשֶֹׁם וְעוֹבֵד. הָיָה רֵיחַ פִּיו רַע נוֹתֵן בְּפִיו פִּלְפֵּל אוֹ זַנְגְּבִיל וְכַיּוֹצֵא בָּהֶן וְעוֹבֵד. וְאִם עָבַד בְּזִהוּם זֵעָתוֹ אוֹ בְּזִהוּם פִּיו הֲרֵי חִלֵּל עֲבוֹדָתוֹ כִּשְׁאָר אֵלּוּ הַבַּעֲלֵי מוּמִין כֻּלָּם:"],"Mishneh Torah, Agents and Partners 9":["הַשֻׁתָּפִין כֻּלָּן וְהָאֲרִיסִין וְהָאַפּוֹטְרוֹפִּין שֶׁמִּנּוּ אוֹתָם בֵּית דִּין עַל הַיְתוֹמִים וְהָאִשָּׁה שֶׁהִיא נוֹשֵׂאת וְנוֹתֶנֶת בְּתוֹךְ הַבַּיִת אוֹ שֶׁהוֹשִׁיבָהּ בַּעְלָהּ חֶנְוָנִית וּבֶן הַבַּיִת. כָּל אֶחָד מֵאֵלּוּ נִשְׁבָּע מִדִּבְרֵיהֶם בְּטַעֲנַת סָפֵק שֶׁמָּא גָּזַל חֲבֵרוֹ בְּמַשָּׂא וּמַתָּן אוֹ שֶׁמָּא לֹא דִּקְדֵּק בַּחֶשְׁבּוֹן שֶׁבֵּינֵיהֶם. וְלָמָּה תִּקְּנוּ חֲכָמִים שְׁבוּעָה זוֹ מִפְּנֵי שֶׁאֵלּוּ מוֹרִין לְעַצְמָן שֶׁכָּל מַה שֶּׁיִּקְּחוּ מִנִּכְסֵי בַּעַל הַמָּעוֹת רָאוּי הוּא לָהֶם מִפְּנֵי שֶׁנּוֹשְׂאִין וְנוֹתְנִין וְטוֹרְחִין. לְפִיכָךְ תִּקְּנוּ לָהֶם חֲכָמִים שֶׁחַיָּבִין שְׁבוּעָה בְּטַעֲנַת סָפֵק כְּדֵי שֶׁיַּעֲשׂוּ כָּל מַעֲשֵׂיהֶן בְּצֶדֶק וֶאֱמוּנָה:","וְאֵין כָּל אֶחָד מֵאֵלּוּ נִשְׁבָּע בְּטַעֲנַת סָפֵק עַד שֶׁיַּחְשֹׁד הַמַּשְׁבִּיעַ אוֹתָן בִּשְׁתֵּי כֶּסֶף שֶׁהֵן שְׁתֵּי מָעִין שֶׁל כֶּסֶף כְּמוֹ שֶׁיִּתְבָּאֵר. אֲבָל אִם חוֹשְׁדָן בְּפָחוֹת מִזֶּה אֵינָם נִשְׁבָּעִין:","מִכָּאן הוֹרוּ רַבּוֹתַי שֶׁאִם מֵת הַשֻׁתָּף הָאֶחָד אֵין הַיּוֹרֵשׁ יָכוֹל לְהַשְׁבִּיעַ שֻׁתָּפוֹ שֶׁל אָבִיו בְּטַעֲנַת שֶׁמָּא שֶׁהֲרֵי אֵינוֹ יוֹדֵעַ הַדָּבָר שֶׁחֲשָׁדוֹ בּוֹ אָבִיו בְּוַדַּאי כְּדֵי שֶׁיַּחְשֹׁד אוֹתוֹ זֶה הַיּוֹרֵשׁ בִּשְׁתֵּי כֶּסֶף. וְיֵשׁ מִי שֶׁהוֹרָה שֶׁמַּשְׁבִּיעַ אוֹתוֹ הַיּוֹרֵשׁ בְּטַעֲנַת שֶׁמָּא וְכָזֶה רָאוּי לָדוּן שֶׁהֲרֵי הַיּוֹרְשִׁין מַשְׁבִּיעִין אֶת הָאִשָּׁה שֶׁנַּעֲשֵׂת אַפּוֹטְרוֹפָּא בְּחַיֵּי בַּעְלָהּ:","אַף עַל פִּי שֶׁאֵין שָׁם עֵדִים שֶׁזֶּה אֲרִיסוֹ אוֹ שֻׁתָּפוֹ אֶלָּא הוּא מוֹדֶה מִפִּי עַצְמוֹ וְאָמַר שֻׁתָּפוֹ אוֹ אֲרִיסוֹ אוֹ בֶּן בֵּיתוֹ אֲנִי אֲבָל לֹא גָּזַלְתִּי כְּלוּם הֲרֵי זֶה נִשְׁבָּע בִּנְקִיטַת חֵפֶץ שֶׁאֵין אוֹמְרִים מִגּוֹ לְפָטְרוֹ שְׁבוּעָה אֶלָּא לְפָטְרוֹ מָמוֹן. אֵיזֶהוּ בֶּן הַבַּיִת שֶׁיֵּשׁ לוֹ לְהַשְׁבִּיעַ בְּטַעֲנַת סָפֵק. זֶה שֶׁמַּכְנִיס פּוֹעֲלִים וּמוֹצִיא פּוֹעֲלִים וּמַכְנִיס לוֹ פֵּרוֹת וּמוֹצִיא לוֹ פֵּרוֹת. אֲבָל בֶּן הַבַּיִת שֶׁאֵינוֹ נוֹשֵׂא וְנוֹתֵן אֶלָּא נִכְנָס בְּרַגְלוֹ וְיוֹצֵא בִּלְבַד אֵינוֹ יָכוֹל לְהַשְׁבִּיעַ מִסָּפֵק. וְכֵן אַפּוֹטְרוֹפּוֹס שֶׁמִּנָּהוּ אֲבִי יְתוֹמִים אֵין הַיְתוֹמִים מַשְׁבִּיעִין אוֹתוֹ בְּטַעֲנַת סָפֵק. וְכֵן הָאִשָּׁה שֶׁלֹּא נַעֲשֵׂת אַפּוֹטְרוֹפָּא בְּחַיֵּי בַּעְלָהּ וְלֹא נָשְׂאָה וְלֹא נָתְנָה לְאַחַר קְבוּרַת בַּעְלָהּ אֵין מַשְׁבִּיעִין אוֹתָהּ מִסָּפֵק. וְכֵן אִם נָשְׂאָה וְנָתְנָה בֵּין מִיתָה וּקְבוּרָה אֵין מַשְׁבִּיעִין עַל זֶה שֶׁנִּשְׁתַּמֵּשׁ בֵּין מִיתָה לִקְבוּרָה. שֶׁאִם אַתָּה אוֹמֵר שֶׁתִּשָּׁבַע עַל זֶה לֹא תִּמְכֹּר לִקְבוּרָה וְנִמְצָא הַמֵּת מִתְנַוֵּל:","הַמְשַׁלֵּחַ בְּיַד חֲבֵרוֹ חֵפֶץ לְמָכְרוֹ אוֹ שֶׁשָּׁלַח מָעוֹת בְּיָדוֹ לִקְנוֹת לוֹ פֵּרוֹת אוֹ סְחוֹרָה אַף עַל פִּי שֶׁלֹּא נָתַן לוֹ שָׂכָר עַל זֶה וְאֵין לוֹ חֵלֶק וְלֹא הֲנָאָה בִּשְׁלִיחוּת זוֹ הוֹאִיל וְנָשָׂא וְנָתַן בְּמָמוֹן חֲבֵרוֹ הֲרֵי זֶה כְּבֶן בַּיִת. וְיֵשׁ לוֹ לְהַשְׁבִּיעַ מִסָּפֵק שֶׁלֹּא גָּזַל לוֹ כְּלוּם בְּעֵת שֶׁהֵבִיא לוֹ הַסְּחוֹרָה שֶׁקָּנָה אוֹ מִקְּצָתָהּ אוֹ הַמָּעוֹת שֶׁמָּכַר לוֹ מֵהֶן:","הַשֻּׁתָּפִין שֶׁנּוֹשְׂאִין וְנוֹתְנִין בְּיַחַד אוֹ שֶׁהָיָה הָאֶחָד נוֹשֵׂא וְנוֹתֵן וּמַפְקִיד הַסְּחוֹרָה אוֹ מִקְּצָתָהּ אוֹ הַמָּעוֹת עִם הַשֵּׁנִי בְּלֹא מִשְׁקָל וְלֹא מִדָּה וְלֹא מִנְיָן הֲרֵי שְׁנֵיהֶם נִכְנָסִין לְסָפֵק וְיֵשׁ לְכָל אֶחָד מֵהֶן לְהַשְׁבִּיעַ אֶת חֲבֵרוֹ שְׁבוּעַת הַשֻּׁתָּפִין. אֲבָל אִם הָיָה הָאֶחָד הוּא שֶׁנּוֹשֵׂא וְנוֹתֵן וְהַשֵּׁנִי לֹא נִתְעַסֵּק עִמּוֹ כְּלָל אֵין נִשְׁבָּע אֶלָּא זֶה שֶׁנָּשָׂא וְנָתַן:","חָלְקוּ הַשֻּׁתָּפִין וְהָאֲרִיסִין וְנִתְגָרְשָׁה הָאִשָּׁה וְנִפְרַד מֵעָלָיו בֶּן הַבַּיִת וְהֵבִיא לוֹ הַשָּׁלִיחַ סְחוֹרָה שֶׁקָּנָה לוֹ אוֹ מָעוֹת שֶׁמָּכַר לוֹ בָּהֶן וְשָׁתַק וְהָלְכוּ לָהֶם וְלֹא תְבָעָם מִיָּד אֵינוֹ יָכוֹל לַחְזֹר וּלְהַשְׁבִּיעוֹ בְּטַעֲנַת סָפֵק. אֲבָל אִם הָיְתָה לוֹ טַעֲנַת וַדַּאי מַשְׁבִּיעוֹ עָלֶיהָ וּמְגַלְגֵּל בָּהּ כָּל מַה שֶּׁיִּרְצֶה. וְכֵן אִם נִתְחַיֵּב לוֹ שְׁבוּעָה אַחַר זְמַן בֵּין שֶׁל תּוֹרָה בֵּין שֶׁל דִּבְרֵיהֶם כְּגוֹן שֶׁנַּעֲשָׂה לוֹ שֻׁתָּף אוֹ בֶּן בַּיִת פַּעַם אַחֶרֶת הֲרֵי זֶה יָכוֹל לְגַלְגֵּל עָלָיו שֶׁלֹּא גְּזָלְתַּנִי בְּשֻׁתָּפוּת זוֹ שֶׁבֵּינֵינוּ וְלֹא כְּשֶׁהָיִיתָ שֻׁתָּפִי אוֹ אֲרִיסִי אוֹ בֶּן בֵּיתִי אוֹ אַפּוֹטְרוֹפִּי בָּרִאשׁוֹנָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַשֻּׁתָּפִין שֶׁחָלְקוּ וְנִשְׁאַר לָהֶם חוֹבוֹת אֵצֶל אֲחֵרִים אֵינָן יְכוֹלִין לְהַשְׁבִּיעַ זֶה אֶת זֶה מִסָּפֵק שֶׁהֲרֵי חָלְקוּ וְהַחוֹב שֶׁנִּשְׁאַר דָּבָר יָדוּעַ הוּא בְּכָל מַה שֶּׁיִּפְרְעוּ יִקַּח זֶה חֶלְקוֹ מִן הַחוֹב וְזֶה חֶלְקוֹ מִן הַחוֹב. וְכֵן אִם נִשְׁאַר לָהֶם מָעוֹת בַּכִּיס וּכְבָר יָדְעוּ אוֹתָן וַעֲדַיִן לֹא נָטְלוּ כָּל אֶחָד חֶלְקוֹ אֵין מַשְׁבִּיעִין זֶה אֶת זֶה שֶׁהַמָּעוֹת כַּחֲלוּקִין הֵם. וְכֵן אִם עָשׂוּ חֶשְׁבּוֹן כָּל הַשֻּׁתָּפִין וְנִשְׁאַר לְאֶחָד מֵהֶן אֵצֶל חֲבֵרוֹ דָּבָר קָצוּב וְיָדוּעַ אַף עַל פִּי שֶׁעֲדַיִן לֹא נָטְלוּ הֲרֵי חָלְקוּ. אֲבָל אִם נִשְׁאַר בֵּינֵיהֶם כָּל שֶׁהוּא מִן הַפֵּרוֹת וַעֲדַיִן לֹא חָלְקוּ אוֹתָן וְלֹא יָדְעוּ מִשְׁקָלָם אוֹ שֶׁנִּשְׁאַר בֵּינֵיהֶם צַד מִן הַשֻּׁתָּפוּת שֶׁלֹּא עָשׂוּ בּוֹ חֶשְׁבּוֹן וְלֹא יָדַע כָּל אֶחָד מֵהֶן כַּמָּה חֶלְקוֹ הַמַּגִּיעוֹ הֲרֵי הַשֻּׁתָּפוּת קַיֶּמֶת עֲדַיִן וּמַשְׁבִּיעִין זֶה אֶת זֶה:","מִי שֶׁתָּבַע אֶת חֲבֵרוֹ אַחַר חֲלוּקָה אֵינוֹ יָכוֹל לְהַשְׁבִּיעוֹ אֶלָּא עַל יְדֵי גִּלְגּוּל כְּמוֹ שֶׁבֵּאַרְנוּ אֲבָל יֵשׁ לוֹ לְהַחֲרִים סְתָם עַל מִי שֶׁגְּזָלוֹ כְּלוּם כְּשֶׁהָיָה שֻׁתָּפוֹ אוֹ אֲרִיסוֹ אוֹ בֶּן בֵּיתוֹ וְלֹא יוֹדֶה בְּמַה שֶּׁגָּזַל:"],"Mishneh Torah, Blessings 2":["סֵדֶר בִּרְכַּת הַמָּזוֹן כָּךְ הִיא. רִאשׁוֹנָה בִּרְכַּת הַזָּן. שְׁנִיָּה בִּרְכַּת הָאָרֶץ. שְׁלִישִׁית בּוֹנֵה יְרוּשָׁלָיִם. רְבִיעִית הַטּוֹב וְהַמֵּטִיב. בְּרָכָה רִאשׁוֹנָה משֶׁה רַבֵּנוּ תִּקְּנָהּ. שְׁנִיָּה תִּקֵּן יְהוֹשֻׁעַ. שְׁלִישִׁית תִּקֵּן דָּוִד וּשְׁלֹמֹה בְּנוֹ. רְבִיעִית חַכְמֵי מִשְׁנָה תִּקְּנוּהָ:","הַפּוֹעֲלִים שֶׁהָיוּ עוֹשִׂין מְלָאכָה אֵצֶל בַּעַל הַבַּיִת וְאָכְלוּ פִּתָּן אֵין מְבָרְכִין לְפָנֶיהָ. וּמְבָרְכִין לְאַחַר סְעֻדָּתָן שְׁתֵּי בְּרָכוֹת בִּלְבַד כְּדֵי שֶׁלֹּא יְבַטְּלוּ מְלֶאכֶת בַּעַל הַבַּיִת. בְּרָכָה רִאשׁוֹנָה כְּתִקּוּנָהּ. שְׁנִיָּה פּוֹתֵחַ בְּבִרְכַּת הָאָרֶץ וְכוֹלֵל בָּהּ בּוֹנֵה יְרוּשָׁלַיִם וְחוֹתֵם בְּבִרְכַּת הָאָרֶץ. וְאִם הָיוּ עוֹשִׂין בִּסְעֻדָּתָן בִּלְבַד אוֹ שֶׁהָיָה בַּעַל הַבַּיִת מֵסֵב עִמָּהֶן מְבָרְכִין אַרְבַּע בְּרָכוֹת כְּתִקּוּנָן כִּשְׁאָר כָּל אָדָם:","בִּרְכַּת הָאָרֶץ צָרִיךְ לוֹמַר הוֹדָיָה בִּתְחִלָּתָהּ וּבְסוֹפָהּ וְחוֹתֵם בָּהּ עַל הָאָרֶץ וְעַל הַמָּזוֹן. וְכָל שֶׁלֹּא אָמַר אֶרֶץ חֶמְדָּה טוֹבָה וּרְחָבָה בְּבִרְכַּת הָאָרֶץ לֹא יָצָא יְדֵי חוֹבָתוֹ. וְצָרִיךְ לְהַזְכִּיר בָּהּ בְּרִית וְתוֹרָה וּלְהַקְדִּים בְּרִית לְתוֹרָה. שֶׁהַבְּרִית הַזֹּאת שֶׁאוֹמְרִים בְּבִרְכַּת הָאָרֶץ הִיא בְּרִית מִילָה שֶׁנִּכְרְתוּ עָלֶיהָ שְׁלֹשׁ עֶשְׂרֵה בְּרִיתוֹת וְהַתּוֹרָה כֻּלָּהּ נִכְרְתוּ עָלֶיהָ שָׁלֹשׁ בְּרִיתוֹת שֶׁנֶּאֱמַר (דברים כח סט) ״אֵלֶּה דִבְרֵי הַבְּרִית״ וְגוֹ׳‎, (דברים כח סט) ״מִלְּבַד הַבְּרִית אֲשֶׁר כָּרַת אִתָּם בְּחֹרֵב״, (דברים כט ט) ״אַתֶּם נִצָּבִים״ וְגוֹ׳‎ (דברים כט יא) ״לְעָבְרְךָ בִּבְרִית״ וְגוֹ׳‎:","בְּרָכָה שְׁלִישִׁית פּוֹתֵחַ בָּהּ רַחֵם יְיָ׳‎ אֱלֹהֵינוּ עָלֵינוּ וְעַל יִשְׂרָאֵל עַמֶּךָ וְעַל יְרוּשָׁלַיִם עִירֶךָ וְעַל צִיּוֹן מִשְׁכַּן כְּבוֹדֶךָ. אוֹ נַחֲמֵנוּ יְיָ׳‎ אֱלֹהֵינוּ בִּירוּשָׁלַיִם עִירֶךָ וְחוֹתֵם בָּהּ בּוֹנֵה יְרוּשָׁלָיִם אוֹ מְנַחֵם עַמּוֹ יִשְׂרָאֵל בְּבִנְיַן יְרוּשָׁלָיִם. וּלְפִיכָךְ נִקְרֵאת בְּרָכָה זוֹ נֶחָמָה. וְכָל מִי שֶׁלֹּא אָמַר מַלְכוּת בֵּית דָּוִד בִּבְרָכָה זוֹ לֹא יָצָא יְדֵי חוֹבָתוֹ מִפְּנֵי שֶׁהִיא עִנְיַן הַבְּרָכָה, שֶׁאֵין נֶחָמָה גְּמוּרָה אֶלָּא בַּחֲזָרַת מַלְכוּת בֵּית דָּוִד:","בְּשַׁבָּתוֹת וּבְיָמִים טוֹבִים מַתְחִיל בְּנֶחָמָה וּמְסַיֵּם בְּנֶחָמָה וְאוֹמֵר קְדֻשַּׁת הַיּוֹם בָּאֶמְצַע. כֵּיצַד מַתְחִיל. נַחֲמֵנוּ יְיָ׳‎ אֱלֹהֵינוּ בְּצִיּוֹן עִירֶךָ אוֹ רַחֵם יְיָ׳‎ אֱלֹהֵינוּ עַל יִשְׂרָאֵל עַמֶּךָ וְעַל יְרוּשָׁלַיִם עִירֶךָ. וּמְסַיֵּם מְנַחֵם עַמּוֹ יִשְׂרָאֵל בְּבִנְיַן יְרוּשָׁלַיִם אוֹ בּוֹנֵה יְרוּשָׁלָיִם. וְאוֹמֵר בָּאֶמְצַע בְּשַׁבָּת אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ רְצֵה וְהַחֲלִיצֵנוּ יְיָ׳‎ אֱלֹהֵינוּ בְּמִצְוֹתֶיךָ וּבְמִצְוַת יוֹם הַשְּׁבִיעִי הַגָּדוֹל וְהַקָּדוֹשׁ הַזֶּה כִּי יוֹם זֶה גָּדוֹל וְקָדוֹשׁ הוּא מִלְּפָנֶיךָ נִשְׁבֹּת בּוֹ וְנָנוּחַ בּוֹ בְּאַהֲבָה כְּמִצְוַת רְצוֹנֶךָ בִּרְצוֹנְךָ הָנַח לָנוּ יְיָ׳‎ אֱלֹהֵינוּ וְאַל תְּהֵא עָלֵינוּ צָרָה וְרָעָה וְיָגוֹן וַאֲנָחָה בְּיוֹם מְנוּחָתֵנוּ. וּבְיָמִים טוֹבִים אוֹמֵר יַעֲלֶה וְיָבוֹא. וְכֵן בְּרָאשֵׁי חֳדָשִׁים וּבְחֻלּוֹ שֶׁל מוֹעֵד מוֹסִיף בְּאֶמְצַע בְּרָכָה שְׁלִישִׁית יַעֲלֶה וְיָבוֹא:","בַּחֲנֻכָּה וּבְפוּרִים מוֹסִיף בְּאֶמְצַע בִּרְכַּת הָאָרֶץ עַל הַנִּסִּים כְּדֶרֶךְ שֶּׁמּוֹסִיף בַּתְּפִלָּה. וְיוֹם טוֹב אוֹ רֹאשׁ חֹדֶשׁ שֶׁחָל לִהְיוֹת בְּשַׁבָּת מַזְכִּיר רְצֵה וְהַחֲלִיצֵנוּ תְּחִלָּה וְאַחַר כָּךְ יַעֲלֶה וְיָבוֹא. וְכֵן רֹאשׁ חֹדֶשׁ טֵבֵת שֶׁחָל לִהְיוֹת בְּשַׁבָּת מַזְכִּיר עַל הַנִּסִּים בְּבִרְכַּת הָאָרֶץ וּרְצֵה וְהַחֲלִיצֵנוּ וְיַעֲלֶה וְיָבוֹא בְּנֶחָמָה:","בְּרָכָה רְבִיעִית צָרִיךְ לְהַזְכִּיר בָּהּ שָׁלֹשׁ מַלְכֻיּוֹת. וּכְשֶׁמְּבָרֵךְ הָאוֹרֵחַ אֵצֶל בַּעַל הַבַּיִת מוֹסִיף בָּהּ בְּרָכָה לְבַעַל הַבַּיִת. כֵּיצַד. אוֹמֵר יְהִי רָצוֹן שֶׁלֹּא יֵבוֹשׁ בַּעַל הַבַּיִת בָּעוֹלָם הַזֶּה וְלֹא יִכָּלֵם לָעוֹלָם הַבָּא וְכוּ׳‎. וְיֵשׁ לוֹ רְשׁוּת לְהוֹסִיף בְּבִרְכַּת בַּעַל הַבַּיִת וּלְהַאֲרִיךְ בָּהּ:","וּכְשֶׁמְּבָרְכִין בְּבֵית הָאָבֵל אוֹמֵר בִּבְרָכָה רְבִיעִית הַמֶּלֶךְ הַחַי הַטּוֹב וְהַמֵּטִיב אֵל אֱמֶת דַּיַן אֱמֶת שׁוֹפֵט בְּצֶדֶק שַׁלִּיט בְּעוֹלָמוֹ לַעֲשׂוֹת בּוֹ כִּרְצוֹנוֹ שֶׁאֲנַחְנוּ עַמּוֹ וַעֲבָדָיו וּבַכּל אֲנַחְנוּ חַיָּבִין לְהוֹדוֹת לוֹ וּלְבָרְכוֹ. וּמְבַקֵּשׁ רַחֲמִים עַל הָאָבֵל לְנַחֲמוֹ כְּפִי מַה שֶּׁיִּרְצֶה. וְגוֹמֵר הָרַחֲמָן כוּ׳‎:","בְּבֵית חֲתָנִים מְבָרְכִין בִּרְכַּת חֲתָנִים אַחַר אַרְבַּע בְּרָכוֹת אֵלּוּ בְּכָל סְעֻדָּה וּסְעֻדָּה שֶׁאוֹכְלִים שָׁם. וְאֵין מְבָרְכִין בְּרָכָה זוֹ לֹא עֲבָדִים וְלֹא קְטַנִּים. עַד כַּמָּה מְבָרְכִין בְּרָכָה זוֹ. אִם הָיָה אַלְמוֹן שֶׁנָּשָׂא אַלְמָנָה מְבָרְכִין אוֹתָהּ בְּיוֹם רִאשׁוֹן בִּלְבַד. וְאִם בָּחוּר שֶׁנָּשָׂא אַלְמָנָה אוֹ אַלְמוֹן שֶׁנָּשָׂא בְּתוּלָה מְבָרְכִין אוֹתָהּ כָּל שִׁבְעַת יְמֵי הַמִּשְׁתֶּה:","בְּרָכָה זוֹ שֶׁמּוֹסִיפִין בְּבֵית חֲתָנִים הִיא בְּרָכָה אַחֲרוֹנָה מִשֶּׁבַע בְּרָכוֹת שֶׁל נִשּׂוּאִין. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיוּ הָאוֹכְלִין הֵם שֶׁעָמְדוּ בְּבִרְכַּת נִשּׂוּאִין וְשָׁמְעוּ הַבְּרָכוֹת אֲבָל אִם הָיוּ הָאוֹכְלִין אֲחֵרִים שֶׁלֹּא שָׁמְעוּ בִּרְכַּת נִשּׂוּאִין בִּשְׁעַת נִשּׂוּאִין מְבָרְכִין בִּשְׁבִילָם אַחַר בִּרְכַּת מָזוֹן שֶׁבַע בְּרָכוֹת כְּדֶרֶךְ שֶׁמְּבָרְכִין בִּשְׁעַת נִשּׂוּאִין. וְהוּא שֶׁיִּהְיוּ עֲשָׂרָה. וַחֲתָנִים מִן הַמִּנְיָן:","וְאֵלּוּ הֵן שֶׁבַע בְּרָכוֹת. בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם יוֹצֵר הָאָדָם. בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁהַכּל בָּרָא לִכְבוֹדוֹ. בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר יָצַר אֶת הָאָדָם בְּצַלְמוֹ בְּצֶלֶם דְּמוּת תַּבְנִיתוֹ וְהִתְקִין לוֹ מִמֶּנּוּ בִּנְיַן עֲדֵי עַד בָּרוּךְ אַתָּה יְיָ׳‎ יוֹצֵר הָאָדָם. שׂוֹשׂ תָּשִׂישׂ וְתָגֵל עֲקָרָה בְּקִבּוּץ בָּנֶיהָ לְתוֹכָהּ בְּשִׂמְחָה בָּרוּךְ [אַתָּה] יְיָ׳‎ מְשַׂמֵּחַ צִיּוֹן בְּבָנֶיהָ. שַׂמֵּחַ תְּשַׂמַּח רֵעִים וַאֲהוּבִים כְּשַׂמֵּחֲךָ יְצִירְךָ בְּגַן עֵדֶן מִקֶּדֶם בָּרוּךְ אַתָּה יְיָ׳‎ מְשַׂמֵּחַ חָתָן וְכַלָּה. בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר בָּרָא שָׂשׂוֹן וְשִׂמְחָה חָתָן וְכַלָּה גִּילָה וְרִנָּה דִּיצָה וְחֶדְוָה אַהֲבָה אַחֲוָה שָׁלוֹם וְרֵעוּת מְהֵרָה יְיָ׳‎ אֱלֹהֵינוּ יִשָּׁמַע בְּעָרֵי יְהוּדָה וּבְחוּצוֹת יְרוּשָׁלַיִם קוֹל שָׂשׂוֹן וְקוֹל שִׂמְחָה קוֹל חָתָן וְקוֹל כַּלָּה קוֹל מִצְהֲלוֹת חֲתָנִים [מֵחֻפָּתָם] וּנְעָרִים מִנְּגִינָתָם בָּרוּךְ אַתָּה יְיָ׳‎ מְשַׂמֵּחַ חָתָן עִם הַכַּלָּה:","שָׁכַח וְלֹא הִזְכִּיר בְּשַׁבָּת אוֹ בְּיוֹם טוֹב קְדֻשַּׁת הַיּוֹם. אִם נִזְכַּר קֹדֶם שֶׁיַּתְחִיל בִּבְרָכָה רְבִיעִית בְּשַׁבָּת אוֹמֵר בָּרוּךְ יְיָ׳‎ אֲשֶׁר נָתַן מְנוּחָה לְעַמּוֹ יִשְׂרָאֵל לְאוֹת וְלִבְרִית קֹדֶשׁ בָּרוּךְ אַתָּה יְיָ׳‎ מְקַדֵּשׁ הַשַּׁבָּת. בְּיוֹם טוֹב אוֹמֵר בָּרוּךְ אֲשֶׁר נָתַן יָמִים טוֹבִים לְעַמּוֹ יִשְׂרָאֵל לְשָׂשוֹן וּלְשִׂמְחָה בָּרוּךְ אַתָּה יְיָ׳‎ מְקַדֵּשׁ יִשְׂרָאֵל וְהַזְּמַנִּים. וּמַתְחִיל בְּבִרְכַּת רְבִיעִית וְגוֹמֵר. וְאִם נִזְכַּר אַחַר שֶׁהִתְחִיל בִּבְרָכָה רְבִיעִית פּוֹסֵק וְחוֹזֵר לָרֹאשׁ שֶׁהוּא בִּרְכַּת הַזָּן:","בְּרָאשֵׁי חֳדָשִׁים שָׁכַח וְלֹא אָמַר יַעֲלֶה וְיָבוֹא אִם נִזְכַּר קֹדֶם שֶׁיַּתְחִיל בְּרָכָה רְבִיעִית אוֹמֵר בָּרוּךְ אֲשֶׁר נָתַן רָאשֵׁי חֳדָשִׁים לְעַמּוֹ יִשְׂרָאֵל לְזִכָּרוֹן וְאֵינוֹ חוֹתֵם בָּהּ וּמַתְחִיל בִּבְרָכָה רְבִיעִית וְגוֹמֵר. וְאִם נִזְכַּר אַחַר שֶׁהִתְחִיל בִּבְרָכָה רְבִיעִית גּוֹמֵר אוֹתָהּ וְאֵינוֹ חוֹזֵר. וְכֵן בְּחֻלּוֹ שֶׁל מוֹעֵד וּבַחֲנֻכָּה וּבְפוּרִים, שָׁכַח וְלֹא הִזְכִּיר הָעִנְיָן בְּבִרְכַּת הַמָּזוֹן אֵינוֹ חוֹזֵר:","מִי שֶׁאָכַל וְשָׁכַח וְלֹא בֵּרֵךְ. אִם נִזְכַּר קֹדֶם שֶׁיִּתְעַכֵּל הַמַּאֲכָל שֶׁבְּמֵעָיו חוֹזֵר וּמְבָרֵךְ. נִתְעַכֵּל הַמָּזוֹן שֶׁבְּמֵעָיו אֵינוֹ חוֹזֵר וּמְבָרֵךְ. וְכֵן אִם נֶעֱלַם מִמֶּנּוּ וְלֹא יָדַע אִם בֵּרֵךְ אוֹ לֹא בֵּרֵךְ חוֹזֵר וּמְבָרֵךְ וְהוּא שֶׁלֹּא נִתְעַכֵּל הַמָּזוֹן שֶׁבְּמֵעָיו:"],"Mishneh Torah, Borrowing and Deposit 5":["מִי שֶׁהִפְקִידוּ אֶצְלוֹ מָעוֹת שֶׁל עֲנִיִּים אוֹ שֶׁל פִּדְיוֹן שְׁבוּיִים וּפָשַׁע בָּהֶם וְנִגְנְבוּ פָּטוּר שֶׁנֶּאֱמַר (שמות כב ו) \"לִשְׁמֹר\" וְלֹא לְחַלֵּק לָעֲנִיִּים וַהֲרֵי הוּא מָמוֹן שֶׁאֵין לוֹ תּוֹבְעִים. אֲפִלּוּ בָּאוּ עָלָיו גַּנָּבִים וְקָדַם וְהִצִּיל עַצְמוֹ בְּמָמוֹן שְׁבוּיִים פָּטוּר. אֵין לְךָ פִּדְיוֹן שְׁבוּיִים גָּדוֹל מִזֶּה. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁאֵין זֶה הַמָּמוֹן מֻפְקָד לַעֲנִיֵּי מָקוֹם זֶה אוֹ לִשְׁבוּיִים [אֵלּוּ]. אֲבָל אִם הָיוּ לַעֲנִיִּים אֵלּוּ אוֹ לִשְׁבוּיִים אֵלּוּ וַהֲרֵי הוּא קָצוּץ לָהֶן הֲרֵי זֶה הַמָּמוֹן שֶׁיֵּשׁ לוֹ תּוֹבְעִין וִישַׁלֵּם אִם פָּשַׁע אוֹ יִשָּׁבַע שֶׁלֹּא פָּשַׁע כְּדֶרֶךְ כָּל הַשּׁוֹמְרִים:","הַמַּפְקִיד אֵצֶל חֲבֵרוֹ מָמוֹן אוֹ כֵּלִים חֲשׁוּבִין וּבָאוּ עָלָיו גַּנָּבִים וְקָדַם וְנָתַן לָהֶם הַפִּקָּדוֹן לְהַצִּיל עַצְמוֹ אִם הָיָה אָמוּד שֶׁהוּא בַּעַל מָמוֹן חַיָּב שֶׁחֶזְקָתוֹ שֶׁבִּגְלָלוֹ בָּאוּ הַגַּנָּבִים וְנִמְצָא זֶה מַצִּיל עַצְמוֹ בְּמָמוֹן חֲבֵרוֹ. וְאִם אֵינוֹ אָמוּד חֶזְקָתוֹ שֶׁלֹּא בָּאוּ אֶלָּא לְשֵׁם הַפִּקָּדוֹן וּפָטוּר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַמַּפְקִיד אֵצֶל חֲבֵרוֹ כֵּלִים אוֹ פֵּרוֹת וּבָאוּ גַּנָּבִים וּגְנָבוּם בְּפָנָיו וְאִלּוּ הָיָה צוֹוֵחַ הָיוּ בָּאִין בְּנֵי אָדָם וּמַצִּילִין אוֹתָן הוֹאִיל וְלֹא צָוַח הֲרֵי זֶה פּוֹשֵׁעַ וְחַיָּב לְשַׁלֵּם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","שְׁנַיִם שֶׁהִפְקִידוּ אֵצֶל אֶחָד זֶה מֵאָה וְזֶה מָאתַיִם וְכָל אֶחָד מִשְּׁנֵיהֶם אוֹמֵר אֲנִי הוּא שֶׁהִפְקַדְתִּי הַמָּאתַיִם וְהַשּׁוֹמֵר אוֹמֵר אֵינִי יוֹדֵעַ יִשָּׁבַע כָּל אֶחָד מֵהֶן שֶׁהִפְקִיד מָאתַיִם וְנוֹטֵל כְּדִין כָּל נִשְׁבָּע וְנוֹטֵל. וְיִתֵּן מָאתַיִם לָזֶה וּמָאתַיִם לָזֶה וּמַפְסִיד מֵאָה מִבֵּיתוֹ שֶׁהֲרֵי הוּא פּוֹשֵׁעַ שֶׁהָיָה לוֹ לִכְתֹּב שֵׁם כָּל אֶחָד עַל כִּיס שֶׁלּוֹ. לְפִיכָךְ אִם הֵבִיאוּ לוֹ הַשְּׁנַיִם כְּאֶחָד שְׁלֹשׁ מֵאוֹת בְּכֶרֶךְ אֶחָד וּבָאוּ וְתָבְעוּ וְכָל אֶחָד אוֹמֵר הַמָּאתַיִם שֶׁלִּי נוֹתֵן מָנֶה לָזֶה וּמָנֶה לָזֶה וְהַשְּׁאָר יִהְיֶה מֻנָּח אֶצְלוֹ עַד לְעוֹלָם אוֹ עַד שֶׁיּוֹדֶה הָאֶחָד לַחֲבֵרוֹ. שֶׁהֲרֵי הוּא אוֹמֵר לָהֶם כֵּיוָן שֶׁרָאִיתִי שֶׁאֵין אַתֶּם מַקְפִּידִין זֶה עַל זֶה וַהֲבֵאתֶם בְּכֶרֶךְ אֶחָד לֹא הִטְרַחְתִּי עַצְמִי לֵידַע וְלִזְכֹּר תָּמִיד מִי בַּעַל הַמֵּאָה וּמִי בַּעַל הַמָּאתַיִם. וְכֵן אִם הִפְקִידוּ אֶצְלוֹ שְׁנֵי כֵּלִים אֶחָד גָּדוֹל וְאֶחָד קָטָן וְכָל אֶחָד וְאֶחָד אוֹמֵר אֲנִי הוּא בַּעַל הַגָּדוֹל וְהַשּׁוֹמֵר אוֹמֵר אֵינִי יוֹדֵעַ יִשָּׁבְעוּ שְׁנֵיהֶם וְיִתֵּן הַגָּדוֹל לְאֶחָד מֵהֶם וּדְמֵי הַגָּדוֹל לַשֵּׁנִי וְיִשָּׁאֵר לוֹ הַקָּטָן. וְאִם הֱבִיאוּם בְּכֶרֶךְ אֶחָד כְּאֶחָד נוֹתֵן הַקָּטָן לָאֶחָד וּדְמֵי הַקָּטָן לַשֵּׁנִי וְהַשְּׁאָר יִהְיֶה מֻנָּח אֶצְלוֹ עַד שֶׁיּוֹדֶה הָאֶחָד לַחֲבֵרוֹ אוֹ עַד לְעוֹלָם. וְכֵן מִי שֶׁתְּבָעוּהוּ שְׁנַיִם זֶה אוֹמֵר אֲנִי הוּא בַּעַל הַפִּקָּדוֹן וְזֶה אוֹמֵר אֲנִי הוּא וְהַשּׁוֹמֵר אוֹמֵר אֶחָד מִכֶּם הוּא וְאֵינִי יוֹדֵעַ מִי הוּא יְשַׁלֵּם לִשְׁנֵיהֶם. וְכֵן שְׁנַיִם שֶׁהִפְקִידוּ שְׁתֵּי בְּהֵמוֹת אֵצֶל רוֹעֶה וּמֵתָה אַחַת מֵהֶן וְאֵינוֹ יוֹדֵעַ שֶׁל מִי הָיְתָה יְשַׁלֵּם לִשְׁנֵיהֶם. וְאִם הִפְקִידוּ בְּעֶדְרוֹ שֶׁלֹּא מִדַּעְתּוֹ מַנִּיחַ הַבְּהֵמָה בֵּינֵיהֶם וּמִסְתַּלֵּק וְתִהְיֶה מֻנַּחַת עַד שֶׁיּוֹדֶה הָאֶחָד לַחֲבֵרוֹ אוֹ עַד שֶׁיִּרְצוּ לַחֲלֹק אוֹתָהּ:","הַמַּפְקִיד פֵּרוֹת אֵצֶל חֲבֵרוֹ הֲרֵי זֶה לֹא יְעָרְבֵם עִם פֵּרוֹתָיו. עָבַר וְעֵרֵב יַחְשֹׁב כַּמָּה הָיָה הַפִּקָּדוֹן וְיִרְאֶה כַּמָּה חָסֵר הַכּל וְיַחְשֹׁב חֶסְרוֹן הַפִּקָּדוֹן וְיִתֵּן לוֹ אַחַר שֶׁיִּשָּׁבַע. נִסְתַּפֵּק מֵהֶן וְלֹא יָדַע כַּמָּה נִסְתַּפֵּק יוֹצִיא לוֹ חֶסְרוֹנוֹ לְחִטִּים וּלְאֹרֶז קָלוּף אַרְבָּעָה קַבִּין וּמֶחֱצָה לְכָל כּוֹר. לִשְׂעוֹרִים וּלְדֹחַן תִּשְׁעָה קַבִּין לְכָל כּוֹר. לְכֻסְּמִין וּלְזֶרַע פִּשְׁתָּן בְּגִבְעוֹלָיו וּלְאֹרֶז שֶׁאֵינוֹ קָלוּף שָׁלֹשׁ סְאִין לְכָל כּוֹר. וְכַמִּדָּה הַזֹּאת לְכָל שָׁנָה וְשָׁנָה. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁמָּדַד לוֹ בִּימוֹת הַגֹּרֶן וְהֶחֱזִיר לוֹ בִּימוֹת הַגֹּרֶן. אֲבָל מָדַד בִּימוֹת הַגֹּרֶן וְהֶחְזִיר לוֹ בִּימוֹת הַגְּשָׁמִים אֵינוֹ מוֹצִיא לוֹ חֶסְרוֹנוֹ מִפְּנֵי שֶׁהֵן מוֹתִירוֹת. וְכֵן מוֹצִיא לוֹ שְׁתוּת לְיַיִן וּשְׁלֹשֶׁת לוֹגִין שֶׁמֶן לְמֵאָה לוֹגִין לוֹג וּמֶחֱצָה שְׁמָרִים וְלוֹג וּמֶחֱצָה בֶּלַע. אִם הָיָה מְזֻקָּק אֵינוֹ מוֹצִיא לוֹ שְׁמָרִים. וְאִם הָיוּ הַקַּנְקַנִּים יְשָׁנִים אֵינוֹ מוֹצִיא לוֹ בֶּלַע:","הִפְקִיד אֶצְלוֹ פֵּרוֹת שֶׁאֵינָן מְדוּדִין וְעֵרְבָן עִם פֵּרוֹתָיו וְלֹא מְדָדָן הֲרֵי זֶה פּוֹשֵׁעַ. בַּעַל הַפִּקָּדוֹן אוֹמֵר כָּךְ וְכָךְ הָיוּ וְהַשּׁוֹמֵר אוֹמֵר אֵינִי יוֹדֵעַ יְשַׁלֵּם בְּלֹא שְׁבוּעָה שֶׁהֲרֵי חִיֵּב עַצְמוֹ בְּתַשְׁלוּמִין וְאֵינוֹ יוֹדֵעַ כַּמָּה הוּא חַיָּב וְנִמְצָא חַיָּב שְׁבוּעָה שֶׁאֵינוֹ יָכוֹל לְהִשָּׁבַע. וְכָזֶה הוֹרוּ רַבּוֹתַי הָרַב רַבֵּנוּ יוֹסֵף הַלֵּוִי וְרַבּוֹ זַ\"ל. וְכֵן כָּל שׁוֹמֵר שֶׁנִּתְחַיֵּב לְשַׁלֵּם וְאָמַר אֵינִי יוֹדֵעַ כַּמָּה דָּמִים אֲנִי חַיָּב לְשַׁלֵּם וְהַבְּעָלִים אוֹמְרִים אָנוּ יוֹדְעִין וְכָךְ וְכָךְ הָיָה שָׁוֶה יִטְּלוּ בְּלֹא שְׁבוּעָה וְהוּא שֶׁיִּטְעֲנוּ דָּבָר שֶׁהֵן אֲמוּדִין בּוֹ. וְיֵשׁ לַשּׁוֹמֵר לְהַחֲרִים עַל מִי שֶׁלָּקַח מִמֶּנּוּ יֶתֶר מִן הָרָאוּי לוֹ. וּמִנַּיִן שֶׁהַדִּין כָּךְ הוּא הַגַּע עַצְמְךָ שֶׁהִפְקִיד אֶצְלוֹ כִּיס מָלֵא זְהוּבִים וּפָשַׁע בּוֹ הַבְּעָלִים אוֹמְרִים מָאתַיִם דִּינָר הָיוּ וְהַשּׁוֹמֵר אוֹמֵר וַדַּאי שֶׁהָיָה בּוֹ דִּינָרִים אֲבָל אֵינִי יוֹדֵעַ כַּמָּה הָיוּ נִמְצָא זֶה כְּטוֹעֵן מָאתַיִם וְהוֹדָה לוֹ בְּמִקְצָת וְאָמַר הַשְּׁאָר אֵינִי יוֹדֵעַ שֶׁהוּא מְחֻיָּב שְׁבוּעָה וְאֵינוֹ יָכוֹל לִשָּׁבַע וּמְשַׁלֵּם כְּמוֹ שֶׁיִּתְבָּאֵר:","מֵת אָבִיו וְהִנִּיחַ לוֹ שַׂק צָרוּר וְהִפְקִידוֹ אֶצְלוֹ חֲבֵרוֹ וּפָשַׁע בּוֹ הַמַּפְקִיד אוֹמֵר אֵינִי יוֹדֵעַ מֶה הָיוּ בּוֹ שֶׁמָּא מַרְגָּלִיּוֹת הָיוּ בּוֹ וְכֵן הַשּׁוֹמֵר אוֹמֵר אֵינִי יוֹדֵעַ כַּמָּה אֲנִי חַיָּב לְשַׁלֵּם שֶׁמָּא זְכוּכִית הָיָה מָלֵא. שׁוּרַת הַדִּין שֶׁאֲנִי אוֹמֵר בְּטַעֲנָה זוֹ שֶׁיִּשָּׁבַע הַשּׁוֹמֵר בְּתַקָּנַת חֲכָמִים שֶׁאֵינוֹ בִּרְשׁוּתוֹ וְיִכְלל בִּשְׁבוּעָתוֹ שֶׁאֵינוֹ יוֹדֵעַ בְּוַדַּאי שֶׁהָיָה בּוֹ יֶתֶר עַל שְׁוֵה כָּךְ וְכָךְ וִישַׁלֵּם מַה שֶּׁהוֹדָה בּוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. מַעֲשֶׂה בְּאֶחָד שֶׁהִפְקִיד שַׂק צָרוּר אֵצֶל חֲבֵרוֹ וּפָשַׁע בּוֹ. הַמַּפְקִיד אוֹמֵר חֲלִי זָהָב וּמַרְגָּלִיּוֹת וְכַיּוֹצֵא בָּהֶן הָיוּ בּוֹ וְהַשּׁוֹמֵר אוֹמֵר אֵינִי יוֹדֵעַ שֶׁמָּא סִיגִים אוֹ חוֹל הָיוּ בּוֹ. וְאָמְרוּ חֲכָמִים יִשָּׁבַע בַּעַל הַפִּקָּדוֹן וְיִטּל וְהוּא שֶׁיִּטְעֹן דָּבָר שֶׁהוּא אָמוּד בּוֹ אוֹ אָמוּד לְהַפְקִידוֹ אֶצְלוֹ. וְלָמָּה נִשְׁבָּע כָּאן בַּעַל הַפִּקָּדוֹן לְפִי שֶׁאֵין הַשּׁוֹמֵר מְחֻיָּב שְׁבוּעָה שֶׁאֲפִלּוּ הוֹדָה וְאָמַר בָּרִי לִי שֶׁהָיָה מָלֵא סִיגִים וְהַמַּפְקִיד אוֹמֵר מַרְגָּלִיּוֹת הָיוּ הַשּׁוֹמֵר נִשְׁבָּע הֶסֵּת וְנִפְטָר כְּמוֹ שֶׁטְּעָנוֹ חִטִּים וְהוֹדָה לוֹ בִּשְׂעוֹרִים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וּבְהִלְכוֹת טוֹעֵן וְנִטְעָן יִתְבָּאֲרוּ עִקְּרֵי הַדְּבָרִים:"],"Mishneh Torah, Creditor and Debtor 14":["הַפּוֹגֵם אֶת שְׁטָרוֹ. אוֹ שֶׁעֵד אֶחָד מֵעִיד עַל שְׁטָרוֹ שֶׁהוּא פָּרוּעַ. וְהַבָּא לִפָּרַע שֶׁלֹּא בִּפְנֵי הַלּוֶֹה. וְהַטּוֹרֵף מִיַּד הַלּוֹקֵחַ. וְהַנִּפְרָעִים מִן הַיּוֹרֵשׁ בֵּין קָטָן בֵּין גָּדוֹל. לֹא יִפָּרַע אֶלָּא בִּשְׁבוּעָה כְּעֵין שֶׁל תּוֹרָה. (וְאוֹמֵר) לוֹ כְּשֶׁיִּתְבַּע הִשָּׁבַע וְאַחַר כָּךְ תִּטּל. וְאִם הָיָה הַחוֹב לִזְמַן וְתָבַע בִּזְמַנּוֹ יִפָּרַע שֶׁלֹּא בִּשְׁבוּעָה. עָבַר זְמַנּוֹ לֹא יִגְבֶּה אֶלָּא בִּשְׁבוּעָה:","הַתּוֹבֵעַ אֶת חֲבֵרוֹ לְפָרְעוֹ וְטָעַן הַלּוֶֹה שֶׁפָּרַע שְׁטָר זֶה אוֹ מִקְצָתוֹ וּבַעַל הַשְּׁטָר אוֹמֵר לֹא פָּרַעְתָּ כְּלוּם אוֹמְרִים לוֹ שַׁלֵּם לוֹ. טָעַן הַלּוֶֹה וְאָמַר יִשָּׁבַע לִי שֶׁלֹּא פְּרַעְתִּיו וְיִטּל מַשְׁבִּיעִין אוֹתוֹ בִּנְקִיטַת חֵפֶץ שֶׁלֹּא פְּרָעוֹ כְּלוּם אוֹ שֶׁלֹּא פְּרָעוֹ אֶלָּא כָּךְ וְכָךְ וְאַחַר כָּךְ יִטּל. וְאִם הָיָה הַמַּלְוֶה תַּלְמִיד חָכָם אֵין נִזְקָקִין לִשְׁבוּעָתוֹ:","הוֹצִיא עָלָיו שְׁטָר מְקֻיָּם וְהַלּוֶֹה טוֹעֵן וְאוֹמֵר שְׁטָר מְזֻיָּף הוּא וּמֵעוֹלָם לֹא כָּתַבְתִּי שְׁטָר זֶה. אוֹ שֶׁטָּעַן שֶׁחוֹב זֶה רִבִּית הוּא אוֹ אֲבַק רִבִּית. אוֹ שֶׁטָּעַן שֶׁהוּא שְׁטַר אֲמָנָה אוֹ שֶׁאָמַר כָּתַבְתִּי לִלְווֹת וְלֹא לָוִיתִי. כְּלָלוֹ שֶׁל דָּבָר טוֹעֵן טַעֲנָה שֶׁאִם הוֹדָה בַּעַל הַשְּׁטָר הָיָה הַשְּׁטָר בָּטֵל וְהַמַּלְוֶה עוֹמֵד בִּשְׁטָרוֹ וְאוֹמֵר שֶׁזֶּה שֶׁקֶר טוֹעֵן וְאָמַר הַלּוֶֹה יִשָּׁבַע לִי וְיִטּל הֲרֵי זוֹ מַחְלֹקֶת בֵּין הַגְּאוֹנִים יֵשׁ מִי שֶׁהוֹרָה שֶׁחַיָּב בַּעַל הַשְּׁטָר לְהִשָּׁבַע כְּעֵין שֶׁל תּוֹרָה כְּמִי שֶׁטָּעַן עָלָיו שֶׁפְּרָעוֹ. וְרַבּוֹתַי הוֹרוּ שֶׁלֹּא יִשָּׁבַע הַמַּלְוֶה אֶלָּא אִם טָעַן עָלָיו הַלּוֶֹה שֶׁפְּרָעוֹ בִּלְבַד. שֶׁהֲרֵי הוֹדָה בַּשְּׁטָר וּלְפֵרָעוֹן הוּא עוֹמֵד. אֲבָל כָּל אֵלּוּ הַטְּעָנוֹת לֹא כָּל הֵימֶנּוּ לְבַטֵּל שְׁטָר מְקֻיָּם אֶלָּא יְשַׁלֵּם וְאַחַר כָּךְ יִטְעֹן עַל הַמַּלְוֶה בְּמַה שֶּׁיִּרְצֶה שֶׁאִם יוֹדֶה יַחְזִיר לוֹ וְאִם כָּפַר יִשָּׁבַע הֶסֵּת. וְלָזֶה דַּעְתִּי נוֹטָה:","הַמּוֹצִיא שְׁטַר חוֹב עַל חֲבֵרוֹ מַלְוֶה אוֹמֵר לֹא נִפְרַעְתִּי כְּלוּם וְלוֶֹה אוֹמֵר פָּרַעְתִּי מֶחֱצָה וְהָעֵדִים מְעִידִים שֶׁפְּרָעוֹ כֻּלּוֹ נִשְׁבָּע הַלּוֶֹה וְנוֹתֵן מֶחֱצָה שֶׁהֲרֵי הוֹדָה בְּמִקְצָת וְאֵינוֹ כְּמֵשִׁיב אֲבֵדָה מִפְּנֵי שֶׁאֵימַת הַשְּׁטָר עָלָיו. וְאֵין הַמַּלְוֶה גּוֹבֶה הַמֶּחֱצָה אֶלָּא מִבְּנֵי חוֹרִין שֶׁהֲרֵי הַלָּקוֹחוֹת אוֹמְרִים אָנוּ עַל הָעֵדִים נִסְמֹךְ וַהֲרֵי בִּטְּלוּ שְׁטָר זֶה:","הוֹצִיא עָלָיו שְׁטַר חוֹב שֶׁאֵינוֹ יָכוֹל לְקַיְּמוֹ וְאָמַר הַלּוֶֹה אֱמֶת שֶׁאֲנִי כָּתַבְתִּי שְׁטָר זֶה אֲבָל פְּרַעְתִּיו אוֹ אֲמָנָה הוּא אוֹ כָּתַבְתִּי לִלְווֹת וַעֲדַיִן לֹא לָוִיתִי וְכָל כַּיּוֹצֵא בָּזֶה הוֹאִיל וְאִם רָצָה אָמַר לֹא הָיוּ דְּבָרִים מֵעוֹלָם וַהֲרֵי מִפִּיו נִתְקַיֵּם הֲרֵי זֶה נֶאֱמָן וְיִשָּׁבַע הֶסֵּת וְיִפָּטֵר. וְאִם קִיְּמוֹ הַמַּלְוֶה אַחַר כָּךְ בְּבֵית דִּין הֲרֵי הוּא כִּשְׁאָר הַשְּׁטָרוֹת:","הוֹצִיא עָלָיו שְׁטָר מְקֻיָּם וְאָמַר הַלּוֶֹה מְזֻיָּף הוּא וּמֵעוֹלָם לֹא כְּתַבְתִּיו אוֹ שְׁטַר אֲמָנָה הוּא וְאָמַר הַמַּלְוֶה כֵּן הַדְּבָרִים אֲבָל שְׁטָר כָּשֵׁר הָיָה לִי וְאָבַד אַף עַל פִּי שֶׁהַמַּלְוֶה הוּא שֶׁשָּׁבַר אֶת שְׁטָרוֹ וְאִלּוּ רָצָה אָמַר אֵינוֹ מְזֻיָּף שֶׁהֲרֵי נִתְקַיֵּם בְּבֵית דִּין אֵינוֹ גּוֹבֶה בּוֹ כְּלוּם אֶלָּא נִשְׁבָּע הַלּוֶֹה הֶסֵּת וְנִפְטָר שֶׁהֲרֵי זֶה הַשְּׁטָר כְּחֶרֶס הוּא חָשׁוּב:","שְׁטָר שֶׁלָּוָה בּוֹ וּפְרָעוֹ אֵינוֹ חוֹזֵר וְלוֶֹה בּוֹ שֶׁכְּבָר נִמְחַל שִׁעְבּוּדוֹ וְנַעֲשָׂה כְּחֶרֶס:","הַמּוֹצִיא שְׁטַר חוֹב מְקֻיָּם עַל חֲבֵרוֹ וְאָמַר הַלּוֶֹה הֲלֹא פְּרָעְתִּיךָ וְאָמַר לוֹ הַמַּלְוֶה כֵּן הָיָה אֲבָל חָזַרְתִּי וְהֶחְזַרְתִּי לְךָ הַמָּעוֹת וְהִלְוֵיתִי אוֹתְךָ פַּעַם שְׁנִיָּה הֲרֵי בָּטֵל הַשְּׁטָר שֶׁנִּפְרַע וַהֲרֵי הוּא כְּחֶרֶס. אֲבָל אִם אָמַר לוֹ הֶחְזַרְתִּי לְךָ הַמָּעוֹת מִפְּנֵי שֶׁלֹּא הָיוּ טוֹבוֹת עַד שֶׁתַּחֲלִיפֵם לֹא בָּטֵל הַשְּׁטָר וַעֲדַיִן שִׁעְבּוּדוֹ קַיָּם:","הוֹצִיא עָלָיו שְׁטָר מְקֻיָּם שֶׁיֵּשׁ לוֹ עָלָיו מָנֶה וְאָמַר לוֹ הַלּוֶֹה הֲלֹא פְּרָעתִיךָ בִּפְנֵי פְּלוֹנִי וּפְלוֹנִי וּבָאוּ אֵלּוּ וְהֵעִידוּ שֶׁפְּרָעוֹ אֲבָל לֹא הִזְכִּיר לוֹ אֶת הַשְּׁטָר וְאָמַר לוֹ הַמַּלְוֶה כֵּן הוּא שֶׁפָּרַעְתָּ אֲבָל חוֹב אַחֵר פָּרַעְתָּ שֶׁהָיָה לִי אֶצְלְךָ הֲרֵי בָּטֵל הַשְּׁטָר. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהֵעִידוּ שֶׁנָּתַן לוֹ בְּתוֹרַת פֵּרָעוֹן אֲבָל אִם רָאוּהוּ נוֹתֵן לוֹ מָעוֹת וְלֹא יָדְעוּ אִם הוּא בְּתוֹרַת פֵּרָעוֹן אוֹ בְּתוֹרַת פִּקָּדוֹן אוֹ בְּתוֹרַת מַתָּנָה. אִם אָמַר בַּעַל הַשְּׁטָר לֹא הָיוּ דְּבָרִים מֵעוֹלָם הֲרֵי הֻחְזַק כַּפְרָן וּבָטֵל הַשְּׁטָר. וְאִם אָמַר פֵּרָעוֹן שֶׁל חוֹב אַחֵר הוּא הֲרֵי זֶה נֶאֱמָן וְנִשְׁבָּע וְנוֹטֵל מַה שֶׁבַּשְּׁטָר שֶׁהֲרֵי לֹא פְּרָעוֹ בְּעֵדִים. מִתּוֹךְ שֶׁיָּכוֹל לוֹמַר מַתָּנָה נְתָנָם לִי נֶאֱמָן לוֹמַר פֵּרָעוֹן שֶׁל חוֹב אַחֵר הֵן. אָמַר לוֹ הַלּוֶֹה וַהֲלֹא שְׁטַר חוֹב זֶה דְּמֵי שׁוֹר שֶׁלָּקַחְתִּי מִמְּךָ הוּא וְאַתָּה גָּבִיתָ דְּמֵי בְּשָׂרוֹ. וְאָמַר לוֹ בַּעַל הַשְּׁטָר כֵּן אֲנִי גָּבִיתִי אֶת דָּמָיו מֵחוֹב אַחֵר שֶׁהָיָה לִי אֶצְלְךָ. הוֹאִיל וְהוֹדָה מֵעַצְמוֹ שֶׁדְּמֵי הַשּׁוֹר הוּא הַחוֹב וּמִדָּמָיו נִפְרַע בָּטֵל הַשְּׁטָר. וְאַף עַל פִּי שֶׁאֵין עָלָיו עֵדִים שֶׁפָּרַע מִדָּמָיו יִשָּׁבַע הַלּוֶֹה הֶסֵּת שֶׁפְּרָעוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הוֹצִיא עָלָיו שְׁטַר חוֹב בְּעֵד אֶחָד וְלוֶֹה טוֹעֵן פָּרַעְתִּי הֲרֵי זֶה מְחֻיָּב שְׁבוּעָה וְאֵינוֹ יָכוֹל לִשָּׁבַע וּמְשַׁלֵּם. טָעַן וְאָמַר יִשָּׁבַע לִי שֶׁלֹּא פְּרַעְתִּיו הֲרֵי זֶה נִשְׁבָּע שֶׁאֲפִלּוּ הָיוּ בַּשְּׁטָר שְׁנֵי עֵדִים וְאָמַר יִשָּׁבַע לִי שֶׁלֹּא פְּרַעְתִּיו הֲרֵי זֶה נִשְׁבָּע כְּמוֹ שֶׁבֵּאַרְנוּ:","וְכֵן הוֹרוּ רַבּוֹתַי שֶׁהַכּוֹפֵר בְּמִלְוֶה עַל פֶּה בְּבֵית דִּין וּבָא עֵד אֶחָד שֶׁלָּוָה הֲרֵי זֶה יִשָּׁבַע שְׁבוּעַת הַתּוֹרָה. חָזַר וְאָמַר כֵּן הָיָה לָוִיתִי וּפָרַעְתִּי אוֹ מָחַל לִי אוֹ נִתְחַיֵּב לִי מִמָּקוֹם אַחֵר הֲרֵי זֶה מְחֻיָּב שְׁבוּעָה וְאֵינוֹ יָכוֹל לִשָּׁבַע וּמְשַׁלֵּם:","מִי שֶׁטָּעַן שֶׁפָּרַע הַשְּׁטָר וְאָמַר יִשָּׁבַע הַמַּלְוֶה וְיִטּל אוֹמְרִים לוֹ הָבֵא מְעוֹתָיו וְאַחַר כָּךְ יִשָּׁבַע וְיִטּל. אִם אֵין לוֹ כְּלוּם לְשַׁלֵּם מַשְׁבִּיעִין אוֹתוֹ כְּתַקָּנַת הַגְּאוֹנִים שֶׁאֵין לוֹ וְלִכְשֶׁתַּשִּׂיג יָדוֹ יִתֵּן לְבַעַל חוֹבוֹ וְיַשְׁבִּיעוֹ שֶׁלֹּא פָּרַע וְאַחַר כָּךְ יִתֵּן לוֹ:","מִי שֶׁהָיָה לוֹ חוֹב עַל חֲבֵרוֹ בִּשְׁטָר וְאָבַד הַשְּׁטָר וַהֲרֵי הָעֵדִים קַיָּמִין אַף עַל פִּי שֶׁקָּנוּ מִיָּדוֹ וְטָעַן שֶׁפָּרַע הֲרֵי זֶה נִשְׁבָּע הֶסֵּת. וְהוֹרוּ רַבּוֹתַי שֶׁאֲפִלּוּ הָיָה הַחוֹב לִזְמַן וַעֲדַיִן לֹא הִגִּיעַ זְמַנּוֹ לְהִפָּרַע הוֹאִיל וְכָתְבוּ לוֹ הַשְּׁטָר וְאֵין בְּיָדוֹ שְׁטָר וְהַלּוֶֹה טוֹעֵן פָּרַעְתִּי נֶאֱמָן וְנִשְׁבָּע הֶסֵּת שֶׁפְּרָעוֹ שֶׁאָנוּ חוֹשְׁשִׁין שֶׁמָּא פְּרָעוֹ וּלְפִיכָךְ קָרַע הַשְּׁטָר אוֹ שְׂרָפוֹ. וְכֵן הוֹרוּ רַבּוֹתַי שֶׁאֲפִלּוּ הָיָה הַשְּׁטָר יוֹצֵא מִתַּחַת יְדֵי אַחֵר וְהַלּוֶֹה טוֹעֵן מִמֶּנִּי נָפַל אַחַר שֶׁפָּרַעְתִּי אַף עַל פִּי שֶׁהוּא בְּתוֹךְ זְמַנּוֹ נִשְׁבָּע הֶסֵּת וְנִפְטָר שֶׁכֵּיוָן שֶׁאֵין הַשְּׁטָר בְּיַד הַמַּלְוֶה אֵין שָׁם חֲזָקָה:","שְׁנַיִם שֶׁהֵן אוֹחֲזִין בִּשְׁטָר הַמַּלְוֶה אוֹמֵר שֶׁלִּי הוּא וְהוֹצֵאתִיו לְהִפָּרַע בּוֹ מִמְּךָ וְהַלּוֶֹה אוֹמֵר פְּרַעְתִּיו וּמִמֶּנִּי נָפַל. אִם הָיָה הַשְּׁטָר שֶׁיָּכוֹל לְקַיְּמוֹ זֶה יִשָּׁבַע שֶׁאֵין לוֹ בְּדָמִים אֵלּוּ פָּחוֹת מֵחֶצְיָן וְזֶה יִשָּׁבַע שֶׁאֵין לוֹ בַּדָּמִים פָּחוֹת מֵחֶצְיָן וִישַׁלֵּם הַלּוֶֹה מֶחֱצָה. וְאִם אֵינוֹ יָכוֹל לְקַיְּמוֹ יִשָּׁבַע הַלּוֶֹה הֶסֵּת שֶׁפְּרָעוֹ וְיֵלֵךְ לוֹ:","הָאוֹמֵר לַחֲבֵרוֹ מָנֶה יֵשׁ לִי בְּיָדְךָ וְהַלָּה אוֹמֵר אֵין לְךָ בְּיָדִי כְּלוּם אוֹ שֶׁאוֹמֵר פְּרַעְתִּיךָ. אָמַר לוֹ הַתּוֹבֵעַ הִשָּׁבַע לִי הֶסֵּת. אָמַר לוֹ הַנִּתְבָּע וַהֲלֹא שְׁטָר יֵשׁ לְךָ עָלַי וְאַתָּה רוֹצֶה לְהַשְׁבִּיעַ אוֹתִי תְּחִלָּה וְאַחַר כָּךְ תּוֹצִיא הַשְּׁטָר הַפָּרוּעַ וְתִגְבֶּה בּוֹ. אוֹמְרִים לוֹ הָבֵא הַשְּׁטָר. אָמַר הַמַּלְוֶה אֵין לִי שְׁטָר עָלָיו מֵעוֹלָם אוֹ שְׁטָר הָיָה לִי וְאָבַד הוֹרוּ רַבּוֹתַי שֶׁאוֹמְרִים לַמַּלְוֶה בַּטֵּל כָּל שְׁטָר שֶׁיֵּשׁ לְךָ קֹדֶם זְמַן זֶה וְאַחַר כָּךְ תַּשְׁבִּיעֵהוּ הֶסֵּת אוֹ הַחֲרֵם חֵרֶם סְתָם וְלֵךְ וּבַקֵּשׁ עַד שֶׁתִּמְצָא הַשְּׁטָר:"],"Mishneh Torah, Creditor and Debtor 25":["הַמַּלְוֶה אֶת חֲבֵרוֹ וְאַחַר שֶׁהִלְוָהוּ אָמַר לוֹ אֶחָד אֲנִי עָרֵב. אוֹ שֶׁתָּבַע אֶת הַלּוֶֹה בַּדִּין וְאָמַר לוֹ אַחֵר הַנַּח וַאֲנִי עָרֵב. אוֹ שֶׁהָיָה חוֹנֵק אֶת חֲבֵרוֹ בַּשּׁוּק לִתֵּן לוֹ וְאָמַר לוֹ הַנַּח וַאֲנִי עָרֵב. אֵין הֶעָרֵב חַיָּב כְּלוּם. וַאֲפִלּוּ אָמַר אֲנִי עָרֵב בִּפְנֵי בֵּית דִּין. אֲבָל אִם קָנוּ מִיָּדוֹ שֶׁהוּא עָרֵב מָמוֹן זֶה כָּל אֵלּוּ הַפָּנִים בֵּין בִּפְנֵי בֵּית דִּין בֵּין בֵּינוֹ לְבֵין הַמַּלְוֶה נִשְׁתַּעְבֵּד:","אָמַר לוֹ בִּשְׁעַת מַתַּן מָעוֹת הַלְוֵהוּ וַאֲנִי עָרֵב נִשְׁתַּעְבֵּד הֶעָרֵב וְאֵינוֹ צָרִיךְ קִנְיָן. וְכֵן אִם בֵּית דִּין עָשׂוּ אוֹתוֹ עָרֵב נִשְׁתַּעְבֵּד אַף עַל פִּי שֶׁלֹּא קָנוּ מִיָּדוֹ. כְּגוֹן שֶׁהָיוּ בֵּית דִּין רוֹצִין לִגְבּוֹת מִן הַלּוֶֹה וְאָמַר לָהֶם הַנִּיחוּהוּ וַאֲנִי עָרֵב לָכֶם הוֹאִיל וְיֵשׁ לוֹ הֲנָאָה שֶׁהֶאֱמִינוּהוּ בֵּית דִּין בְּאוֹתָהּ הֲנָיָה שִׁעְבֵּד עַצְמוֹ:","הַמַּלְוֶה אֶת חֲבֵרוֹ עַל יְדֵי עָרֵב אַף עַל פִּי שֶׁהֶעָרֵב מִשְׁתַּעְבֵּד לַמַּלְוֶה לֹא יִתְבַּע אֶת הֶעָרֵב תְּחִלָּה אֶלָּא תּוֹבֵעַ אֶת הַלּוֶֹה תְּחִלָּה. אִם לֹא נָתַן לוֹ חוֹזֵר אֵצֶל הֶעָרֵב וְנִפְרָע מִמֶּנּוּ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁאֵין נְכָסִים לַלּוֶֹה. אֲבָל אִם יֵשׁ נְכָסִים לַלּוֶֹה לֹא יִפָּרַע מִן הֶעָרֵב כְּלָל אֶלָּא מִן הַלּוֶֹה. הָיָה הַלּוֶֹה אַלָּם וְאֵין בֵּית דִּין יְכוֹלִין לְהוֹצִיא מִיָּדוֹ אוֹ שֶׁלֹּא בָּא לַדִּין הֲרֵי זֶה נִפְרָע מִן הֶעָרֵב תְּחִלָּה וְאַחַר כָּךְ יַעֲשֶׂה הֶעָרֵב דִּין עִם הַלּוֶֹה אִם יָכוֹל לְהוֹצִיאוֹ מִיָּדוֹ יוֹצִיא אוֹ יְשַׁמְּתוּהוּ בֵּית דִּין עַד שֶׁיִּתֵּן לוֹ:","הִתְנָה הַמַּלְוֶה עַל הֶעָרֵב וְאָמַר לוֹ עַל מְנָת שֶׁאֶפָּרַע מִמִּי שֶׁאֶרְצֶה אִם יֵשׁ נְכָסִים לַלּוֶֹה לֹא יִפָּרַע מִן הֶעָרֵב. אָמַר עַל מְנָת שֶׁאֶפָּרַע מִמִּי שֶׁאֶרְצֶה תְּחִלָּה אוֹ שֶׁהָיָה קַבְּלָן הֲרֵי זֶה יִתְבַּע אֶת הֶעָרֵב הַזֶּה אוֹ אֶת הַקַּבְּלָן תְּחִלָּה וְיִפָּרַע מֵהֶן אַף עַל פִּי שֶׁיֵּשׁ נְכָסִים לַלּוֶֹה:","אֵיזֶהוּ עָרֵב וְאֵיזֶהוּ קַבְּלָן. אָמַר לוֹ תֵּן לוֹ וַאֲנִי נוֹתֵן לְךָ זֶהוּ קַבְּלָן שֶׁיֵּשׁ לַמַּלְוֶה לְהִפָּרַע מִמֶּנּוּ תְּחִלָּה אַף עַל פִּי שֶׁלֹּא פֵּרֵשׁ וְלֹא אָמַר עַל מְנָת שֶׁאֶפָּרַע מִמִּי שֶׁאֶרְצֶה. אֲבָל אִם אָמַר לוֹ הַלְוֵהוּ וַאֲנִי עָרֵב הַלְוֵהוּ וַאֲנִי פּוֹרֵעַ הַלְוֵהוּ וַאֲנִי חַיָּב הַלְוֵהוּ וַאֲנִי נוֹתֵן הַלְוֵהוּ וַאֲנִי קַבְּלָן. תֵּן לוֹ וַאֲנִי קַבְּלָן תֵּן לוֹ וַאֲנִי פּוֹרֵעַ תֵּן לוֹ וַאֲנִי חַיָּב תֵּן לוֹ וַאֲנִי עָרֵב. כֻּלָּן לָשׁוֹן עַרְבָנוּת הֵן וְאֵינוֹ תּוֹבְעוֹ תְּחִלָּה וְלֹא נִפְרַע מִמֶּנּוּ בְּמָקוֹם שֶׁיֵּשׁ נְכָסִים לַלּוֶֹה עַד שֶׁיְּפָרֵשׁ וְיֹאמַר מִמִּי שֶׁאֶרְצֶה אֶפָּרַע:","עָרֵב שֶׁל כְּתֻבָּה אַף עַל פִּי שֶׁקָּנוּ מִיָּדוֹ פָּטוּר מִלְּשַׁלֵּם שֶׁהֲרֵי מִצְוָה עָשָׂה וְלֹא חָסַר מָמוֹן. וְאִם הָיָה הָאָב עָרֵב לִכְתֻבַּת בְּנוֹ וְקָנוּ מִיָּדוֹ חַיָּב. וְקַבְּלָן שֶׁל כְּתֻבָּה חַיָּב:","רְאוּבֵן שֶׁמָּכַר לְשִׁמְעוֹן שָׂדֶה וּבָא לֵוִי וְקִבֵּל אַחֲרָיוּת עָלָיו לֹא נִשְׁתַּעְבֵּד לֵוִי שֶׁזּוֹ אַסְמַכְתָּא הִיא. וְאִם קָנוּ מִיָּדוֹ שֶׁהוּא עָרֵב לְשַׁלֵּם דְּמֵי מֶכֶר זֶה כָּל עֵת שֶׁיִּרְצֶה שֶׁיִּתְבָּעֶנּוּ לְשִׁמְעוֹן הֲרֵי זֶה חַיָּב וְכָזֶה הוֹרוּ רַבּוֹתַי:","וְכֵן הֶעָרֵב אוֹ הַקַּבְּלָן שֶׁחִיְּבוּ עַצְמָן עַל תְּנַאי אַף עַל פִּי שֶׁקָּנוּ מִיָּדוֹ לֹא נִשְׁתַּעְבֵּד מִפְּנֵי שֶׁהוּא אַסְמַכְתָּא. כֵּיצַד. כְּגוֹן שֶׁאָמַר לוֹ תֵּן לוֹ וַאֲנִי אֶתֵּן לְךָ אִם יִהְיֶה כָּךְ וְכָךְ אוֹ אִם לֹא יִהְיֶה. שֶׁכָּל הַתּוֹלֶה שִׁעְבּוּד שֶׁאֵינוֹ חַיָּב בּוֹ בְּאִם יִהְיֶה וְאִם לֹא יִהְיֶה לֹא גָּמַר וְהִקְנָה קִנְיָן שָׁלֵם וּלְפִיכָךְ לֹא נִשְׁתַּעְבֵּד:","שְׁנַיִם שֶׁלָּווּ בִּשְׁטָר אֶחָד אוֹ שֶׁלָּקְחוּ מִקָּח אֶחָד. וְכֵן הַשֻּׁתָּפִין שֶׁלָּוָה אֶחָד מֵהֶן אוֹ לָקַח בְּשֻׁתָּפוּת הֲרֵי הֵן עַרְבָאִין זֶה לָזֶה אַף עַל פִּי שֶׁלֹּא פֵּרֵשׁ:","שְׁנַיִם שֶׁעָרְבוּ לָאֶחָד כְּשֶׁיָּבוֹא הַמַּלְוֶה לִפָּרַע מִן הֶעָרֵב יִפָּרַע מֵאֵי זֶה מֵהֶן שֶׁיִּרְצֶה. וְאִם לֹא הָיָה לְאֶחָד כְּדֵי הַחוֹב חוֹזֵר וְתוֹבֵעַ הַשֵּׁנִי בִּשְׁאָר הַחוֹב:","וְאֶחָד שֶׁעָרַב לִשְׁנַיִם כְּשֶׁיִּפְרַע לַמַּלְוֶה יוֹדִיעוֹ עַל חוֹב אֵיזֶה מִשְּׁנֵיהֶם פּוֹרֵעַ כְּדֵי שֶׁיַּחֲזֹר עָלָיו:","הָאוֹמֵר לַחֲבֵרוֹ עֲרֹב לִפְלוֹנִי כָּךְ וְכָךְ וַאֲנִי עָרֵב לְךָ הֲרֵי זֶה כְּמִי שֶׁאָמַר לוֹ הַלְוֵהוּ וַאֲנִי עָרֵב. וּכְשֵׁם שֶׁנִּשְׁתַּעְבֵּד הֶעָרֵב לַמַּלְוֶה כָּךְ נִשְׁתַּעְבֵּד עָרֵב לָעָרֵב רִאשׁוֹן. וְדִין הֶעָרֵב עִם הַמַּלְוֶה וְדִין עָרֵב רִאשׁוֹן עִם הַשֵּׁנִי דִּין אֶחָד הוּא:","מִי שֶׁלֹּא פֵּרֵשׁ קֶצֶב הַדָּבָר שֶׁעָרַב כְּגוֹן שֶׁאָמַר לוֹ כָּל מַה שֶּׁתִּתֵּן תֵּן לוֹ וַאֲנִי עָרֵב אוֹ מְכֹר לוֹ וַאֲנִי עָרֵב אוֹ הַלְוֵהוּ וַאֲנִי עָרֵב יֵשׁ מִן הַגְּאוֹנִים שֶׁהוֹרָה אֲפִלּוּ מָכַר לוֹ בַּעֲשֶׂרֶת אֲלָפִים אוֹ הִלְוָהוּ מֵאָה אֶלֶף נִשְׁתַּעְבֵּד הֶעָרֵב בַּכּל. וְיֵרָאֶה לִי שֶׁאֵין זֶה הֶעָרֵב חַיָּב כְּלוּם שֶׁכֵּיוָן שֶׁאֵינוֹ יוֹדֵעַ הַדָּבָר שֶׁשִּׁעְבֵּד עַצְמוֹ בּוֹ לֹא סָמְכָה דַּעְתּוֹ וְלֹא שִׁעְבֵּד עַצְמוֹ וּדְבָרִים שֶׁל טַעַם הֵם לַמֵּבִין:","מִי שֶׁאָמַר לַחֲבֵרוֹ הַלְוֵהוּ וַאֲנִי עָרֵב לְגוּפוֹ שֶׁל לוֶֹה זֶה לֹא עָרַב לְעַצְמוֹ שֶׁל מָמוֹן אֶלָּא כָּל זְמַן שֶׁתִּרְצֶה אֲבִיאֶנּוּ לְךָ. וְכֵן אִם אָמַר לוֹ אַחַר שֶׁהִלְוָהוּ וּתְבָעוֹ הַנִּיחֵהוּ כָּל זְמַן שֶׁתִּתְבָּעֶנּוּ אֲבִיאֶנּוּ לְךָ וְקָנוּ מִיָּדוֹ עַל זֶה אִם לֹא יָבִיא זֶה הַלּוֶֹה יֵשׁ מִן הַגְּאוֹנִים שֶׁהוֹרָה שֶׁהוּא חַיָּב לְשַׁלֵּם. וְיֵשׁ מִי שֶׁהוֹרָה שֶׁאֲפִלּוּ הִתְנָה וְאָמַר אִם לֹא אֲבִיאֶנּוּ אוֹ שֶׁמֵּת אוֹ שֶׁבָּרַח אֶהְיֶה חַיָּב לְשַׁלֵּם הֲרֵי זוֹ אַסְמַכְתָּא וְלֹא נִשְׁתַּעְבֵּד. וְלָזֶה דַּעְתִּי נוֹטָה:"],"Mishneh Torah, Daily Offerings and Additional Offerings 2":["מִצְוַת עֲשֵׂה לִהְיוֹת אֵשׁ יְקוּדָה עַל הַמִּזְבֵּחַ תָּמִיד שֶׁנֶּאֱמַר (ויקרא ו ו) \"אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ\". אַף עַל פִּי שֶׁהָאֵשׁ יָרְדָה מִן הַשָּׁמַיִם מִצְוָה לְהָבִיא אֵשׁ מִן הַהֶדְיוֹט שֶׁנֶּאֱמַר (ויקרא א ז) \"וְנָתְנוּ בְּנֵי אַהֲרֹן הַכֹּהֲנִים אֵשׁ עַל הַמִּזְבֵּחַ\":","בַּבֹּקֶר עוֹרְכִין עֵצִים וְעוֹרְכִין בְּרֹאשׁ הַמִּזְבֵּחַ מַעֲרָכָה גְּדוֹלָה שֶׁל אֵשׁ שֶׁנֶּאֱמַר (ויקרא ו ה) \"וּבִעֵר עָלֶיהָ הַכֹּהֵן עֵצִים בַּבֹּקֶר בַּבֹּקֶר\". וְכֵן מִצְוָה לְהַעֲלוֹת שְׁנֵי גְּזָרִים שֶׁל עֵץ עִם תָּמִיד שֶׁל שַׁחַר יוֹתֵר עַל עֲצֵי הַמַּעֲרָכָה שֶׁנֶּאֱמַר וּבִעֵר עָלֶיהָ הַכֹּהֵן עֵצִים בַּבֹּקֶר. וְכֵן מוֹסִיפִין שְׁנֵי גְּזָרִים עִם תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם שֶׁנֶּאֱמַר (ויקרא א ז) \"וְעָרְכוּ עֵצִים עַל הָאֵשׁ\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁבְּתָמִיד שֶׁל בֵּין הָעַרְבַּיִם הַכָּתוּב מְדַבֵּר:","שְׁנֵי גְּזָרִים שֶׁל בֵּין הָעַרְבַּיִם מַעֲלִין אוֹתָן שְׁנֵי כֹּהֲנִים. כָּל אֶחָד וְאֶחָד בְּעֵץ יְחִידִי בְּיָדוֹ שֶׁנֶּאֱמַר (ויקרא א ז) \"וְעָרְכוּ\" הֲרֵי כָּאן שְׁנַיִם. אֲבָל שֶׁל שַׁחַר בְּכֹהֵן אֶחָד:","שָׁלֹשׁ מַעֲרָכוֹת שֶׁל אֵשׁ עוֹשִׂין בְּרֹאשׁ הַמִּזְבֵּחַ בְּכָל יוֹם. רִאשׁוֹנָה מַעֲרָכָה גְּדוֹלָה שֶׁעָלֶיהָ מַקְרִיבִין הַתָּמִיד עִם שְׁאָר הַקָּרְבָּנוֹת. שְׁנִיָּה בְּצִדָּהּ קְטַנָּה שֶׁמִּמֶּנָּה לוֹקְחִין אֵשׁ בְּמַחְתָּה לְהַקְטִיר קְטֹרֶת בְּכָל יוֹם. שְׁלִישִׁית אֵין עָלֶיהָ כְּלוּם אֶלָּא לְקַיֵּם מִצְוַת הָאֵשׁ שֶׁנֶּאֱמַר (ויקרא ו ו) \"אֵשׁ תָּמִיד תּוּקַד\":","מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזֶּה שֶׁנֶּאֱמַר (ויקרא ו ב) \"עַל מוֹקְדָה עַל הַמִּזְבֵּחַ\" זוֹ מַעֲרָכָה גְּדוֹלָה. (ויקרא ו ב) \"וְאֵשׁ הַמִּזְבֵּחַ תּוּקַד בּוֹ\" זוֹ מַעֲרָכָה שְׁנִיָּה שֶׁל קְטֹרֶת. (ויקרא ו ה) \"וְהָאֵשׁ עַל הַמִּזְבֵּחַ תּוּקַד בּוֹ\" זוֹ מַעֲרָכָה שְׁלִישִׁית שֶׁל קִיּוּם הָאֵשׁ. אֲבָל אֵיבָרִים וּפְדָרִים שֶׁלֹּא נִתְאַכְּלוּ מִבָּעֶרֶב נוֹתְנִין אוֹתָן בְּצִדֵּי מַעֲרָכָה גְּדוֹלָה:","הַמְכַבֶּה אֵשׁ הַמִּזְבֵּחַ לוֹקֶה שֶׁנֶּאֱמַר (ויקרא ו ה ו) \"לֹא תִכְבֶּה\". אֲפִלּוּ גַּחֶלֶת אַחַת וַאֲפִלּוּ הוֹרִידָהּ מֵעַל הַמִּזְבֵּחַ וְכִבָּה לוֹקֶה. אֲבָל אֵשׁ מַחְתָּה וְאֵשׁ מְנוֹרָה שֶׁהֱכִינָהּ בַּמִּזְבֵּחַ לְהַדְלִיק מִמֶּנָּה אַף עַל פִּי שֶׁכִּבָּה אוֹתָן בְּרֹאשׁ הַמִּזְבֵּחַ פָּטוּר שֶׁהֲרֵי נִתְּקָהּ לְמִצְוָה אַחֶרֶת וְאֵין אֲנִי קוֹרֵא בָּהֶן אֵשׁ הַמִּזְבֵּחַ:","כְּשֶׁמְּסַדֵּר עֲצֵי מַעֲרָכָה גְּדוֹלָה מְסַדְּרָהּ בְּמִזְרַח הַמִּזְבֵּחַ. וְיִהְיֶה מַרְאֶה שֶׁהִתְחִיל לְסַדֵּר מִן הַמִּזְרָח. וְרֶוַח הָיָה בֵּין הַגְּזָרִים. וְרָאשֵׁי הַגְּזָרִים הַפְּנִימִיִּים הָיוּ נוֹגְעִין בַּדֶּשֶׁן שֶׁבְּאֶמְצַע הַמִּזְבֵּחַ וְהוּא הַנִּקְרָא תַּפּוּחַ:","וְאַחַר שֶׁמְּסַדֵּר מַעֲרָכָה גְּדוֹלָה חוֹזֵר וּבוֹרֵר עֲצֵי תְּאֵנָה יָפִים וּמְסַדֵּר מַעֲרָכָה שְׁנִיָּה שֶׁל קְטֹרֶת מִכְּנֶגֶד קֶרֶן מַעֲרָבִית דְּרוֹמִית מְשׁוּכָה מִן הַקֶּרֶן כְּלַפֵּי צָפוֹן אַרְבַּע אַמּוֹת וּבָהּ כְּמוֹ חָמֵשׁ סְאִין גֶּחָלִים. וּבְשַׁבָּת עוֹשִׂין בָּהּ כְּמוֹ שְׁמוֹנֶה סְאִין גֶּחָלִים מִפְּנֵי שֶׁעָלֶיהָ מַקְטִירִין בְּכָל שַׁבָּת שְׁנֵי בְּזִיכֵי לְבוֹנָה שֶׁל לֶחֶם הַפָּנִים:","מַעֲרָכָה שְׁלִישִׁית שֶׁל קִיּוּם הָאֵשׁ עוֹשֶׂה אוֹתָהּ בְּכָל מָקוֹם שֶׁיִּרְצֶה מִן הַמִּזְבֵּחַ. וּמַצִּית בָּהּ אֶת הָאֵשׁ. וְלֹא יַצִּית הָאֵשׁ לְמַטָּה וְיַעֲלֶה אוֹתָהּ לַמִּזְבֵּחַ אֶלָּא בַּמִּזְבֵּחַ עַצְמוֹ מַצִּיתִין שֶׁנֶּאֱמַר (ויקרא ו ב) \"וְאֵשׁ הַמִּזְבֵּחַ תּוּקַד בּוֹ\". מִכָּאן לְהַצָּתָה שֶׁלֹּא תִּהְיֶה אֶלָּא בְּרֹאשׁוֹ שֶׁל מִזְבֵּחַ:","הֲרָמַת הַדֶּשֶׁן מֵעַל הַמִּזְבֵּחַ בְּכָל יוֹם מִצְוַת עֲשֵׂה שֶׁנֶּאֱמַר וְהֵרִים אֶת הַדֶּשֶׁן. וְהִיא עֲבוֹדָה מֵעֲבוֹדוֹת כְּהֻנָּה. וּבִגְדֵי כְּהֻנָּה שֶׁתּוֹרֵם בָּהֶן הַדֶּשֶׁן יִהְיוּ פְּחוּתִין מִן הַבְּגָדִים שֶׁמְּשַׁמֵּשׁ בָּהֶם בִּשְׁאָר עֲבוֹדוֹת שֶׁנֶּאֱמַר (ויקרא ו ד) \"וּפָשַׁט אֶת בְּגָדָיו וְלָבַשׁ בְּגָדִים אֲחֵרִים וְהֵרִים אֶת הַדֶּשֶׁן\". אֵינוֹ אוֹמֵר אֲחֵרִים שֶׁיִּהְיוּ בִּגְדֵי חֹל אֶלָּא שֶׁיִּהְיוּ פְּחוּתִין מִן הָרִאשׁוֹנִים. לְפִי שֶׁאֵינוֹ דֶּרֶךְ אֶרֶץ שֶׁיִּמְזֹג כּוֹס לְרַבּוֹ בִּבְגָדִים שֶׁבִּשֵּׁל בָּהֶם קְדֵרָה לְרַבּוֹ:","אֵימָתַי תּוֹרְמִין הַדֶּשֶׁן בְּכָל יוֹם. מִשֶּׁיַּעֲלֶה עַמּוּד הַשַּׁחַר. וּבָרְגָלִים מִתְּחִלַּת שְׁלִישׁ אֶמְצָעִי שֶׁל לַיְלָה. וּבְיוֹם הַכִּפּוּרִים מֵחֲצוֹת הַלַּיְלָה:","כֵּיצַד תּוֹרְמִין. מִי שֶׁזָּכָה לִתְרֹם טוֹבֵל וְלוֹבֵשׁ בִּגְדֵי הֲרָמָה. וּמְקַדֵּשׁ יָדָיו וְרַגְלָיו וְאוֹמְרִים לוֹ הִזָּהֵר שֶׁמָּא תִּגַּע בִּכְלִי עַד שֶׁתְּקַדֵּשׁ יָדֶיךָ וְרַגְלֶיךָ. וְאַחַר כָּךְ לוֹקֵחַ הַמַּחְתָּה וְשֶׁל כֶּסֶף הָיְתָה. וְהִיא הָיְתָה נְתוּנָה בְּמִקְצוֹעַ בֵּין כֶּבֶשׁ לַמִּזְבֵּחַ בְּמַעֲרָבוֹ שֶׁל כֶּבֶשׁ. וְנוֹטֵל אֶת הַמַּחְתָּה וְעוֹלֶה לְרֹאשׁ הַמִּזְבֵּחַ וּמְפַנֶּה אֶת הַגֶּחָלִים אֵילָךְ וְאֵילָךְ וְחוֹתֶה מִן הַגֶּחָלִים שֶׁנִּתְאַכְּלוּ בְּלֵב הָאֵשׁ וְיוֹרֵד לְמַטָּה לָאָרֶץ. וְהוֹפֵךְ פָּנָיו לְצָפוֹן וּמְהַלֵּךְ בָּאָרֶץ לְמִזְרַח הַכֶּבֶשׁ כְּמוֹ עֶשֶׂר אַמּוֹת כְּלַפֵּי הַצָּפוֹן. וְצוֹבֵר אֶת הַגֶּחָלִים שֶׁחָתָה עַל גַּבֵּי הָרִצְפָּה רָחוֹק מִן הַכֶּבֶשׁ שְׁלֹשָׁה טְפָחִים. בְּמָקוֹם שֶׁנּוֹתְנִים מֻרְאַת הָעוֹף וְדִשׁוּן הַמִּזְבֵּחַ הַפְּנִימִי וְהַמְּנוֹרָה. וַחֲתִיָּה זוֹ שֶׁחוֹתֶה בַּמַּחְתָּה וּמוֹרִיד לָרִצְפָּה אֵצֶל הַמִּזְבֵּחַ הִיא הַמִּצְוָה שֶׁל כָּל יוֹם:","אַחַר שֶׁיָּרַד זֶה שֶׁתָּרַם רָצִים אֶחָיו הַכֹּהֲנִים וּמְקַדְּשִׁין יְדֵיהֶם וְרַגְלֵיהֶם בִּמְהֵרָה. וְנוֹטְלִין אֶת הַמַּגְּרֵפוֹת וְאֶת הַצִּנּוֹרוֹת וְעוֹלִין לְרֹאשׁ הַמִּזְבֵּחַ. וְכָל אֵיבְרֵי הָעוֹלוֹת וְאֵימוּרֵי הַקָּרְבָּנוֹת שֶׁלֹּא נִתְאַכְּלוּ כָּל הַלַּיְלָה מַחֲזִירִין אוֹתָם לְצִדְדֵי הַמִּזְבֵּחַ. אִם אֵין הַצְּדָדִין מַחֲזִיקִין סוֹדְרִים אוֹתָם בַּכֶּבֶשׁ כְּנֶגֶד הַסּוֹבֵב. וְאַחַר כָּךְ גּוֹרְפִין אֶת הַדֶּשֶׁן בְּמַגְרֵפוֹת מִכָּל צִדְדֵי הַמִּזְבֵּחַ. וּמַעֲלִין אוֹתוֹ עֲרֵמָה עַל גַּבֵּי הַתַּפּוּחַ. וְגוֹרְפִין אוֹתָהּ הָעֲרֵמָה בִּפְסַכְתֵּר. וְהוּא כְּלִי גָּדוֹל שֶׁמַּחְזִיק לֶתֶךְ. וּמוֹרִידִין אוֹתוֹ לְמַטָּה. וּבָרְגָלִים לֹא הָיוּ מוֹרִידִין אוֹתוֹ אֶלָּא מַנִּיחִין הָעֲרֵמָה גְּבוֹהָה בְּאֶמְצַע הַמִּזְבֵּחַ מִפְּנֵי שֶׁהוּא נוֹי לַמִּזְבֵּחַ:","כָּל מִי שֶׁיִּרְצֶה מִן הַכֹּהֲנִים מְמַלֵּא מִן הַדֶּשֶׁן שֶׁהוֹרִידוּ לְמַטָּה וּמוֹצִיא חוּץ לָעִיר לְשֶׁפֶךְ הַדֶּשֶׁן. וְאֵין לְהוֹצָאַת הַדֶּשֶׁן לַחוּץ פִּיּוּס אֶלָּא כָּל הָרוֹצֶה. וּמֵעוֹלָם לֹא נִתְעַצֵּל כֹּהֵן מִלְּהוֹצִיא אֶת הַדֶּשֶׁן:","וְאַף עַל פִּי שֶׁאֵין הוֹצָאָתוֹ לַחוּץ עֲבוֹדָה. אֵין בַּעֲלֵי מוּמִין מוֹצִיאִין אוֹתוֹ. וּכְשֶׁמּוֹצִיאִין אוֹתוֹ לְחוּץ לָעִיר מַנִּיחִין אוֹתוֹ בְּמָקוֹם שֶׁאֵין הָרוּחוֹת מְנַשְּׁבוֹת בּוֹ בְּחָזְקָה. וְלֹא חֲזִירִים גּוֹרְפִים אוֹתוֹ. וְלֹא יְפַזְּרֶנּוּ שָׁם שֶׁנֶּאֱמַר (ויקרא ו ג) \"וְשָׂמוֹ\". שֶׁיַּנִּיחֶנּוּ בְּנַחַת. וְאָסוּר לֵהָנוֹת בּוֹ:"],"Mishneh Torah, Damages to Property 13":["כֵּלִים שֶׁנָּפְלוּ לַבּוֹר וְנִשְׁתַּבְּרוּ בַּעַל הַבּוֹר פָּטוּר שֶׁנֶּאֱמַר (שמות כא לג) \"וְנָפַל שָׁמָּה שּׁוֹר אוֹ חֲמוֹר\" מִפִּי הַשְּׁמוּעָה לָמְדוּ שׁוֹר וְלֹא אָדָם חֲמוֹר וְלֹא כֵּלִים. אֲפִלּוּ נָפַל שׁוֹר בְּכֵלָיו וּמֵת הַשּׁוֹר וְנִשְׁתַּבְּרוּ כֵּלָיו חַיָּב עַל הַבְּהֵמָה וּפָטוּר עַל הַכֵּלִים:","הַבּוֹר מֵאֲבוֹת נְזִיקִין הוּא וְתוֹלְדוֹתָיו כָּמוֹהוּ מוּעָדִין מִתְּחִלָּתָן. וְכָל הַמַּנִּיחַ תַּקָּלָה הֲרֵי זוֹ תּוֹלֶדֶת הַבּוֹר וְאִם הֻזַּק בָּהּ אָדָם אוֹ בְּהֵמָה מְשַׁלֵּם זֶה שֶׁהִנִּיחַ הַתַּקָּלָה נֵזֶק שָׁלֵם בֵּין הִפְקִיר הַתַּקָּלָה בֵּין לֹא הִפְקִירָהּ. וְאִם הֻזְּקוּ בָּהּ כֵּלִים פָּטוּר:","כֵּיצַד. הַמַּנִּיחַ אַבְנוֹ אוֹ סַכִּינוֹ אוֹ תִּבְנוֹ אוֹ מַשָּׂאוֹ וְכַיּוֹצֵא בָּהֶן בִּרְשׁוּת הָרַבִּים וְהֻזְּקוּ בָּהֶן בֵּין אָדָם בֵּין בְּהֵמָה חַיָּב נֵזֶק שָׁלֵם. וְכֵן אִם הִנִּיחָן בִּרְשׁוּתוֹ וְהִפְקִיר רְשׁוּתוֹ וְלֹא הִפְקִירָן נִתְקָל בַּקַּרְקַע וְנֶחְבָּט בְּתַקָּלָה זוֹ וְהֻזַּק בָּהּ חַיָּב בַּעַל הַתַּקָּלָה. וְאִם הֻזְּקוּ כֵּלִים בְּכָל אֵלּוּ אוֹ נִטַּנְּפוּ פָּטוּר:","הִכְנִיס שׁוֹרוֹ לַחֲצַר בַּעַל הַבַּיִת שֶׁלֹּא בִּרְשׁוּת וְהִרְבִּיץ גְּלָלִים וְנִטַּנְּפוּ בָּהֶן כֵּלָיו שֶׁל בַּעַל הַבַּיִת פָּטוּר. שֶׁהַגָּלָל זֶה תּוֹלֶדֶת בּוֹר הוּא וְלֹא מָצָאנוּ בּוֹר שֶׁחִיֵּב בּוֹ עַל הַכֵּלִים:","הַמַּנִּיחַ אֶת הַכַּד בִּרְשׁוּת הָרַבִּים וְהָלַךְ [הַמְהַלֵּךְ] וְנִתְקַל בָּהּ וּשְׁבָרָהּ פָּטוּר לְפִי שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לְהִתְבּוֹנֵן בַּדֶּרֶךְ כְּשֶׁהֵן מְהַלְּכִין. וְאִם הֻזַּק בָּהּ הֲרֵי בַּעַל הַכַּד חַיָּב בִּנְזָקָיו וַאֲפִלּוּ הִפְקִיר הַכַּד. שֶׁכָּל הַמַּפְקִיר נְזָקָיו בְּמָקוֹם שֶׁאֵין לוֹ רְשׁוּת לַעֲשׂוֹתָהּ מִתְּחִלָּה חַיָּב כְּאִלּוּ לֹא הִפְקִירָן:","הִנִּיחַ אֶת הַכַּד בְּמָקוֹם שֶׁיֵּשׁ לוֹ רְשׁוּת לְהַנִּיחָהּ שָׁם כְּגוֹן מְקוֹם הַקְּרָנוֹת שֶׁל גִּתּוֹת וְכַיּוֹצֵא בָּהֶן וְנִתְקַל בָּהּ וּשְׁבָרָהּ חַיָּב. וְאִם הֻזַּק בָּהּ הַמְהַלֵּךְ בַּעַל הַכַּד פָּטוּר מִפְּנֵי שֶׁהָיָה לוֹ לְהִסְתַּכֵּל. וְאִם הָיְתָה אֲפֵלָה אוֹ שֶׁמִּלֵּא כָּל הַדֶּרֶךְ כַּדִּים פָּטוּר עַל שְׁבִירָתָהּ. וְאִם נִתְקַל בָּהּ הֲרֵי בַּעַל הַכַּד חַיָּב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","נִשְׁבְּרָה כַּדּוֹ בִּרְשׁוּת הָרַבִּים וְהֻחְלַק אֶחָד בַּמַּיִם אוֹ שֶׁלָּקָה בַּחֲרָסֶיהָ פָּטוּר מִדִּינֵי אָדָם לְפִי שֶׁאָנוּס הוּא. וְחַיָּב בְּדִינֵי שָׁמַיִם מִפְּנֵי שֶׁלֹּא סִלֵּק הַחֲרָסִים. וַהֲרֵי הַחֲרָסִים וְהַמַּיִם כְּהֶפְקֵר וְלֹא הִפְקִיר אֶלָּא אַחַר שֶׁנֶּאֱנַס וּלְפִיכָךְ פָּטוּר. וְאִם נִתְכַּוֵּן לִזְכּוֹת בַּחֲרָסֶיהָ וְהֻזַּק בָּהֶן אַחֵר חַיָּב. וְהוּא הַדִּין לְנָפְלָה גְּמַלּוֹ וְלֹא הֶעֱמִידָהּ וְכָל כַּיּוֹצֵא בָּהּ. וְאִם הֻזְּקוּ כֵּלִים בְּכָל אֵלּוּ פָּטוּר בֵּין הִפְקִיר בֵּין לֹא הִפְקִיר כְּמוֹ שֶׁבֵּאַרְנוּ:","שְׁנֵי קַדָּרִין שֶׁהָיוּ מְהַלְּכִין בַּדֶּרֶךְ זֶה אַחַר זֶה וְנִתְקַל הָרִאשׁוֹן וְנָפַל וְנִתְקַל הַשֵּׁנִי בָּרִאשׁוֹן. אִם הָיָה לָרִאשׁוֹן לַעֲמֹד וְלֹא עָמַד חַיָּב הָרִאשׁוֹן בְּנִזְקֵי שֵׁנִי שֶׁאַף עַל פִּי שֶׁהוּא אָנוּס בִּשְׁעַת נְפִילָה אֵינוֹ אָנוּס בִּהְיוֹתוֹ מֻטָּל בַּדֶּרֶךְ וַהֲרֵי הוּא יָכוֹל לַעֲמֹד. וְאִם לֹא הָיָה לוֹ לַעֲמֹד פָּטוּר וְאַף עַל פִּי שֶׁלֹּא הִזְהִיר לָזֶה שֶׁנִּתְקַל בּוֹ מִפְּנֵי שֶׁהוּא טָרוּד בְּנַפְשׁוֹ:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהוּא חַיָּב בִּנְזָקָיו שֶׁל שֵׁנִי כְּשֶׁהֻזַּק גּוּפוֹ שֶׁל שֵׁנִי. אֲבָל אִם הֻזְּקוּ כֵּלָיו פָּטוּר שֶׁאֵינוֹ חַיָּב עַל הַכֵּלִים בַּבּוֹר וְכָל תַּקָּלָה תּוֹלֶדֶת בּוֹר הוּא כְּמוֹ שֶׁבֵּאַרְנוּ:","הַקַּדָרִים וְהַזַּגָּגִים וְכַיּוֹצֵא בָּהֶן שֶׁהָיוּ מְהַלְּכִין זֶה אַחַר זֶה וְנִתְקַל הָרִאשׁוֹן וְנָפַל וְנִתְקַל הַשֵּׁנִי בָּרִאשׁוֹן וְהַשְּׁלִישִׁי בַּשֵּׁנִי וְכָל אֶחָד מֵהֶן יֵשׁ לוֹ לַעֲמֹד וְלֹא עָמַד. הָרִאשׁוֹן חַיָּב בְּנִזְקֵי גּוּפוֹ שֶׁל שֵׁנִי בֵּין שֶׁהֻזַּק בְּגוּפוֹ שֶׁל רִאשׁוֹן הַמֻּטָּל בָּאָרֶץ בֵּין שֶׁהֻזַּק בְּמַשָּׂאוֹ. וְהַשֵּׁנִי חַיָּב בְּנִזְקֵי גּוּפוֹ שֶׁל שְׁלִישִׁי אִם הֻזַּק בְּגוּפוֹ שֶׁל שֵׁנִי. אֲבָל אִם הֻזַּק בְּמַשָּׂאוֹ שֶׁל שֵׁנִי שֶׁנָּפַל פָּטוּר. שֶׁהֲרֵי אוֹמֵר לוֹ הַשֵּׁנִי בּוֹר זֶה שֶׁהוּא מַשָּׂאִי אֵין אֲנִי הַכּוֹרֶה אוֹתוֹ שֶׁהֲרֵי הָרִאשׁוֹן הִפִּיל הַשֵּׁנִי עִם מַשָּׂאוֹ. וְאִם הִזְהִירוּ זֶה אֶת זֶה כֻּלָּן פְּטוּרִין:","נָפַל הָרִאשׁוֹן וְהָיָה מֻטָּל לְרֹחַב הַדֶּרֶךְ וְנִתְקַל אֶחָד בְּרֹאשׁוֹ וְאֶחָד בְּרַגְלָיו וְאֶחָד בְּבִטְנוֹ הֲרֵי הוּא חַיָּב בְּנִזְקֵי כֻּלָּן הוֹאִיל וְהָיָה לוֹ לַעֲמֹד וְלֹא עָמַד:","הַשּׁוֹפֵךְ אֶת הַמַּיִם בִּרְשׁוּת הָרַבִּים וְהֻזַּק בָּהֶן אַחֵר חַיָּב בִּנְזָקָיו. וְאִם נִטַּנְפוּ כֵּלָיו פָּטוּר כְּמוֹ שֶׁבֵּאַרְנוּ. נִבְלְעוּ הַמַּיִם בָּאָרֶץ וְנִשְׁאֲרָה הָאָרֶץ חֲלָקָה וְהֻחְלַק וְנָפַל וְהֻזַּק בַּקַּרְקַע הֲרֵי זֶה חַיָּב בִּנְזָקָיו:","כָּל אֵלּוּ שֶׁפּוֹתְקִין בִּיבוֹתֵיהֶן וְגוֹרְפִין מְעָרוֹתֵיהֶן אֵין לָהֶן רְשׁוּת לִשְׁפֹּךְ הַמַּיִם בִּרְשׁוּת הָרַבִּים בִּימוֹת הַחַמָּה אֲבָל בִּימוֹת הַגְּשָׁמִים יֵשׁ לָהֶן רְשׁוּת. וְאַף עַל פִּי כֵן אִם הֻזַּק אָדָם אוֹ בְּהֵמָה בַּמַּיִם חַיָּבִין נֵזֶק שָׁלֵם:","לֹא יוֹצִיא אָדָם תִּבְנוֹ וְקַשּׁוֹ לִרְשׁוּת הָרַבִּים כְּדֵי שֶׁיָּדוּשׁוּ וְיַעֲשׂוּ לוֹ זֶבֶל. וְאִם הוֹצִיא קְנָסוּהוּ חֲכָמִים שֶׁיִּהְיוּ כְּהֶפְקֵר וְכָל הַקּוֹדֵם בָּהֶן זָכָה מֵעֵת שֶׁנִּדּוֹשׁוּ וְהִשְׁבִּיחוּ. וְאִם קָדַם אָדָם וְזָכָה בָּהֶן מִשְּׁעַת הוֹצָאָה לִרְשׁוּת הָרַבִּים אֵין מוֹצִיאִין מִיָּדוֹ. וְאַף עַל פִּי שֶׁהֵן כְּהֶפְקֵר אִם הֻזַּק בָּהֶן אָדָם אוֹ בְּהֵמָה הֲרֵי זֶה הַמּוֹצִיא חַיָּב לְשַׁלֵּם:","יֵשׁ לְכָל אָדָם לְהוֹצִיא אֶת הַזֶּבֶל וְהַגְּלָלִים לִרְשׁוּת הָרַבִּים בִּשְׁעַת הוֹצָאַת זְבָלִים וְלִצְבֹּר אוֹתָן שָׁם שְׁלֹשִׁים יוֹם כְּדֵי שֶׁיִּהְיֶה נִשּׁוֹף בְּרַגְלֵי אָדָם [וְרַגְלֵי בְּהֵמָה]. וְאַף עַל פִּי כֵן אִם הִזִּיק חַיָּב לְשַׁלֵּם. וְחַיָּבִין עַל זֶה הַגָּלָל מִשּׁוּם גֵּזֶל כֵּיוָן שֶׁאֵין בּוֹ שֶׁבַח אִם נִדּוֹשׁ לֹא קָנְסוּ בּוֹ:","אֵין שׁוֹרִין טִיט בִּרְשׁוּת הָרַבִּים וְאֵין לוֹבְנִים לְבֵנִים. אֲבָל גּוֹבְלִין טִיט בִּרְשׁוּת הָרַבִּים אֲבָל לֹא לְבֵנִים:","הַבּוֹנֶה בִּרְשׁוּת הָרַבִּים הַמֵּבִיא אֲבָנִים מֵבִיא וְהַבּוֹנֶה בּוֹנֶה. וְכֻלָּן שֶׁהִזִּיקוּ חַיָּבִין לְשַׁלֵּם נֵזֶק שָׁלֵם:","הַחוֹצֵב שֶׁחָצַב אֶבֶן וּמְסָרָהּ לְסַתָּת וְהֻזַּק בָּהּ אָדָם אוֹ בְּהֵמָה הַסַּתָּת חַיָּב. וְסַתָּת שֶׁמָּסַר לְחַמָּר הַחַמָּר חַיָּב. מָסַר חַמָּר לְכַתָּף הַכַּתָּף חַיָּב. מָסַר כַּתָּף לְבוֹנֶה הַבּוֹנֶה חַיָּב. מְסָרָהּ הַבּוֹנֶה לְזֶה שֶׁמְּתַקֵּן יְשִׁיבָתָהּ בַּבִּנְיָן הַמְתַקֵּן חַיָּב. וְאִם אַחַר שֶׁהֶעֱלוּהָ עַל גַּבֵּי הַדִּימוֹס נָפְלָה וְהִזִּיקָה וְהָיוּ עוֹשִׂין בְּקַבְּלָנוּת כֻּלָּן חַיָּבִין. וּבִשְׂכִירוּת הָאַחֲרוֹן חַיָּב וְכֻלָּן פְּטוּרִין:","הַכֹּתֶל וְהָאִילָן שֶׁנָּפְלוּ לִרְשׁוּת הָרַבִּים וְהִזִּיקוּ פָּטוּר מִלְּשַׁלֵּם וְאַף עַל פִּי שֶׁהִפְקִירָן. לְפִי שֶׁאֵינָן דּוֹמִים לַבּוֹר שֶׁהֲרֵי אֵין תְּחִלָּתָן לְהַזִּיק. וְאִם הָיוּ רְעוּעִין בֵּית דִּין קוֹבְעִין לוֹ זְמַן לָקֹץ אֶת הָאִילָן וְלִסְתֹּר אֶת הַכֹּתֶל. וְכַמָּה הַזְּמַן שְׁלֹשִׁים יוֹם. נָפְלוּ בְּתוֹךְ הַזְּמַן וְהִזִּיקוּ פָּטוּר לְאַחַר הַזְּמַן חַיָּב מִפְּנֵי שֶׁשִּׁהָה אוֹתָן:","הַמַּצְנִיעַ אֶת הַקּוֹץ וְאֶת הַזְּכוּכִית וְהַגּוֹדֵר גְּדֵרוֹ בְּקוֹצִים וְהִפְרִיחַ לִרְשׁוּת הָרַבִּים וְהֻזַּק אֶחָד בָּהֶן חַיָּב נֵזֶק שָׁלֵם. וְאִם גָּדַר בְּקוֹצִים בְּצִמְצוּם בְּתוֹךְ רְשׁוּתוֹ פָּטוּר לְפִי שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לְהִתְחַכֵּךְ בַּכְּתָלִים:","הַמַּצְנִיעַ קוֹצָיו וּזְכוּכִיּוֹתָיו בְּתוֹךְ כָּתְלוֹ שֶׁל חֲבֵרוֹ וּבָא בַּעַל הַכֹּתֶל וְסָתַר אֶת כָּתְלוֹ וְנָפַל לִרְשׁוּת הָרַבִּים וְהִזִּיק. אִם כֹּתֶל רָעוּעַ הָיָה הַמַּצְנִיעַ חַיָּב. וְאִם כֹּתֶל בָּרִיא הוּא בַּעַל הַכֹּתֶל חַיָּב:","חֲסִידִים הָרִאשׁוֹנִים הָיוּ מַצְנִיעִין אֶת הַקּוֹצִים וְאֶת הַזְּכוּכִיּוֹת בְּתוֹךְ שְׂדוֹתֵיהֶם בְּעֹמֶק שְׁלֹשָׁה טְפָחִים בָּאָרֶץ כְּדֵי שֶׁלֹּא תַּעֲלֵם הַמַּחֲרֵשָׁה. וַאֲחֵרִים שׂוֹרְפִים אוֹתָן בְּאֵשׁ. וַאֲחֵרִים מַשְׁלִיכִים אוֹתָן לַיָּם אוֹ לַנָּהָר כְּדֵי שֶׁלֹּא יֻזַּק בָּהֶן אָדָם:","לֹא יְסַקֵּל אָדָם מֵרְשׁוּתוֹ לִרְשׁוּת הָרַבִּים. ואֵין עוֹשִׂין חָלָל תַּחַת רְשׁוּת הָרַבִּים וְלֹא בּוֹרוֹת וְלֹא שִׁיחִין וְלֹא מְעָרוֹת וְאַף עַל פִּי שֶׁהָעֲגָלָה יְכוֹלָה לְהַלֵּךְ עַל גַּבֵּיהֶן וְהִיא טְעוּנָה אֲבָנִים שֶׁמָּא תִּפָּחֵת מִלְּמַטָּה שֶׁלֹּא מִדַּעְתּוֹ. וְהַחוֹפֵר בּוֹר לְצָרְכֵי רַבִּים מֻתָּר:","אֵין מוֹצִיאִין זִיזִין וּגְזוּזְטְרָאוֹת לִרְשׁוּת הָרַבִּים אֶלָּא אִם כֵּן הָיוּ לְמַעְלָה מִגָּמָל וְרוֹכְבוֹ. וְהוּא שֶׁלֹּא יַאֲפִיל הַדֶּרֶךְ עַל בְּנֵי רְשׁוּת הָרַבִּים. וְאִם רָצָה כּוֹנֵס לְתוֹךְ שֶׁלּוֹ וּמוֹצִיאוֹ. כָּנַס וְלֹא הוֹצִיא הֲרֵי זֶה מוֹצִיא כָּל זְמַן שֶׁיִּרְצֶה. אֲבָל אֵינוֹ יָכוֹל לְהַחְזִיר כְּתָלִים לִמְקוֹמָן לְעוֹלָם. שֶׁכָּל מֵצַר שֶׁהֶחְזִיקוּ בּוֹ רַבִּים אָסוּר לְקַלְקְלוֹ:","לָקַח חָצֵר וּבָהּ זִיזִין וּגְזֻזְטְרָאוֹת יוֹצְאוֹת לִרְשׁוּת הָרַבִּים הֲרֵי זוֹ בְּחֶזְקָתָהּ וְאִם נָפְלָה חוֹזֵר וּבוֹנֶה אוֹתָהּ כְּשֶׁהָיְתָה:","אִילָן שֶׁהוּא נוֹטֶה לִרְשׁוּת הָרַבִּים קוֹצֵץ כְּדֵי שֶׁיִּהְיֶה הַגָּמָל עוֹבֵר בְּרוֹכְבוֹ. וּמַנִּיחִין מָקוֹם פָּנוּי מִשְּׁתֵי שִׂפְתוֹת הַנָּהָר כְּרֹחַב כִּתְפֵי הַמַּלָּחִים שֶׁיּוֹרְדִין שָׁם וּמוֹשְׁכִין הַסְּפִינָה. וְכָל אִילָן הַנִּמְצָא בְּרֹחַב זֶה קוֹצְצִין אוֹתוֹ מִיָּד וְאֵין מַתְרִין בִּבְעָלָיו שֶׁהֲרֵי מְעַכֵּב מוֹשְׁכֵי הַסְּפִינָה:","מִי שֶׁהָיְתָה דֶּרֶךְ הָרַבִּים עוֹבֶרֶת בְּתוֹךְ שָׂדֵהוּ נְטָלָהּ וּנְתָנָהּ לָהֶם מִן הַצַּד מַה שֶּׁנָּתַן נָתַן וְזָכוּ בּוֹ וְזֶה שֶׁנָּטַל לֹא זָכָה בּוֹ. וְכַמָּה רֹחַב דֶּרֶךְ הָרַבִּים אֵין פָּחוֹת מִשֵּׁשׁ עֶשְׂרֵה אַמּוֹת:"],"Mishneh Torah, Defilement by Leprosy 11":["טָהֳרַת מְצֹרָע מִצְוַת עֲשֵׂה. וְתִגְלַחְתּוֹ כְּשֶׁיִּטְהַר מִצְוַת עֲשֵׂה. כֵּיצַד מְטַהֲרִין אֶת הַמְצֹרָע. מֵבִיא מִזְרָק שֶׁל חֶרֶשׂ חָדָשׁ וְקַבָּלָה הִיא שֶׁיִּהְיֶה [חָדָשׁ] וְנוֹתֵן לְתוֹכוֹ רְבִיעִית מַיִם חַיִּים הָרְאוּיִין לְקַדֵּשׁ אוֹתָן מֵי חַטָּאת. וְשִׁעוּר זֶה מִדִּבְרֵי סוֹפְרִים. וּמֵבִיא שְׁתֵּי צִפֳּרִים דְּרוֹר טְהוֹרוֹת לְשֵׁם טָהֳרַת צָרַעַת שֶׁנֶּאֱמַר (ויקרא יד ד) \"וְלָקַח לַמִּטַּהֵר\". וְשׁוֹחֵט אֶת הַבְּרוּרָה שֶׁבִּשְׁתֵּיהֶן עַל הַמַּיִם שֶׁבַּכְּלִי חֶרֶס וּמְמַצֶּה עַד שֶׁיִּהְיֶה הַדָּם נִכָּר בַּמַּיִם. וְחוֹפֵר וְקוֹבֵר הַצִּפּוֹר הַשְּׁחוּטָה בְּפָנָיו. וְדָבָר זֶה קַבָּלָה מִפִּי הַשְּׁמוּעָה. וְנוֹטֵל עֵץ אֶרֶז וּמִצְוָתוֹ שֶׁיִּהְיֶה אָרְכּוֹ אַמָּה וְעָבְיוֹ כִּרְבִיעַ כֶּרַע מִכִּרְעֵי הַמִּטָּה. וְאֵזוֹב שֶׁאֵין לוֹ שֵׁם לְוַוי כְּמוֹ שֶׁבֵּאַרְנוּ. אֵין פָּחוּת מִטֶּפַח. וּשְׁנִי תּוֹלַעַת מִשְׁקָלוֹ שֶׁקֶל. וְאִם טִעֲמוֹ פְּסָלוֹ כִּצְבִיעַת הַתְּכֵלֶת. וְכָל הַשִּׁעוּרִים הֲלָכָה. וְלוֹקֵחַ עִם שְׁלָשְׁתָּן הַצִּפּוֹר הַחַיָּה. וְאַרְבָּעָה מִינִין אֵלּוּ מְעַכְּבִין זֶה אֶת זֶה. וְעֵץ אֶרֶז וְאֵזוֹב שֶׁנִּתְקַלְּפוּ פְּסוּלִין. וְכוֹרֵךְ הָאֵזוֹב עִם הָאֶרֶז בְּלָשׁוֹן שֶׁל זְהוֹרִית וּמַקִּיף לָהֶן רָאשֵׁי אֲגַפַּיִים וְרֹאשׁ הַזָּנָב שֶׁל צִפּוֹר הַחַיָּה. וְטוֹבֵל אַרְבַּעְתָּן בַּמַּיִם שֶׁבַּכְּלִי וּבַדָּם שֶׁעֲלֵיהֶן. וּמַזֶּה שֶׁבַע פְּעָמִים עַל אַחַר יָדוֹ שֶׁל מְצֹרָע וּמְשַׁלֵּחַ אֶת הַצִּפּוֹר. וכֵּיצַד מְשַׁלְּחָהּ. עוֹמֵד בָּעִיר וְזוֹרְקָהּ חוּץ לַחוֹמָה. וְאֵינוֹ הוֹפֵךְ פָּנָיו לֹא לַיָּם וְלֹא לָעִיר וְלֹא לַמִּדְבָּר. שֶׁנֶּאֱמַר (ויקרא יד נג) \"מִחוּץ לָעִיר אֶל פְּנֵי הַשָּׂדֶה\". שְׁלָחָהּ וְחָזְרָה חוֹזֵר וּמְשַׁלְּחָהּ אֲפִלּוּ מֵאָה פְּעָמִים. וְאַחַר כָּךְ מְגַלֵּחַ הַכֹּהֵן אֶת הַמְצֹרָע. כֵּיצַד מְגַלְּחוֹ. מַעֲבִיר תַּעַר עַל כָּל בְּשָׂרוֹ הַנִּרְאֶה אֲפִלּוּ בֵּית הַשֶּׁחִי וּבֵית הָעֶרְוָה שֵׂעָר שֶׁעַל כָּל הַגּוּף עַד שֶׁיֵּעָשֶׂה כִּדְלַעַת שֶׁנֶּאֱמַר (ויקרא יד ח) \"אֶת כָּל שְׂעָרוֹ\". אִם כֵּן לָמָּה נֶאֱמַר (ויקרא יד ט) \"רֹאשׁוֹ\" (ויקרא יד ט) \"וּזְקָנוֹ\" (ויקרא יד ט) \"וְגַבּוֹת עֵינָיו\" לְרַבּוֹת כָּל כַּיּוֹצֵא בָּהֶן וּלְמַעֵט שֵׂעָר שֶׁבְּתוֹךְ הַחֹטֶם לְפִי שֶׁאֵינוֹ נִרְאֶה. וְאַחַר כָּךְ מְכַבֵּס בְּגָדָיו וְטוֹבֵל וְיִטְהַר מִלְּטַמֵּא בְּבִיאָה וּמִלְּטַמֵּא מִשְׁכָּב וּמוֹשָׁב. וְיִכָּנֵס לְפָנִים מִן הַחוֹמָה וּמוֹנֶה שִׁבְעַת יָמִים וְאָסוּר בָּהֶן בְּתַשְׁמִישׁ הַמִּטָּה שֶׁנֶּאֱמַר (ויקרא יד ח) \"מִחוּץ לְאָהֳלוֹ\" מְלַמֵּד שֶׁאָסוּר בְּתַשְׁמִישׁ הַמִּטָּה. וְהַמְצֹרַעַת מֻתֶּרֶת בְּתַשְׁמִישׁ הַמִּטָּה:","כָּל שִׁבְעַת הַיָּמִים הָאֵלּוּ עֲדַיִן הוּא אַב הַטֻּמְאָה מְטַמֵּא אָדָם וְכֵלִים בְּמַגָּע לֹא בְּמַשָּׂא שֶׁהֲרֵי הוּא אוֹמֵר (ויקרא יד ט) \"וְהָיָה בַיּוֹם הַשְּׁבִיעִי\" (ויקרא יד ט) \"וְכִבֶּס אֶת בְּגָדָיו\" וְגוֹ' מְלַמֵּד שֶׁהָיָה מְטַמֵּא בְּגָדִים וּכְשֵׁם שֶׁהָיָה מְטַמֵּא בְּגָדִים בְּמַגָּע כָּךְ מְטַמֵּא אָדָם בְּמַגָּע שֶׁכָּל הַמְטַמֵּא בְּגָדִים מְטַמֵּא אָדָם. וּבַיּוֹם הַשְּׁבִיעִי מְגַלְּחוֹ הַכֹּהֵן תִּגְלַחַת שְׁנִיָּה כָּרִאשׁוֹנָה וּמְכַבֵּס בְּגָדָיו וְטוֹבֵל וְיִטְהַר מִלְּטַמֵּא אֲחֵרִים. וַהֲרֵי הוּא כְּכָל טְבוּלֵי יוֹם וְאוֹכֵל בְּמַעֲשֵׂר. הֶעֱרִיב שִׁמְשׁוֹ אוֹכֵל בִּתְרוּמָה. הֵבִיא כַּפָּרָתוֹ אוֹכֵל בְּקָדָשִׁים כְּמוֹ שֶׁבֵּאַרְנוּ:","כְּשֶׁהוּא מְגַלֵּחַ בִּשְׁתֵּי הַתִּגְלָחוֹת אֵינוֹ מְגַלֵּחַ אֶלָּא בְּתַעַר. וְאִם גִּלֵּחַ שֶׁלֹּא בְּתַעַר אוֹ שֶׁהִנִּיחַ שְׁתֵּי שְׂעָרוֹת לֹא עָשָׂה כְּלוּם. וְאֵינוֹ מְגַלְּחוֹ אֶלָּא כֹּהֵן. וְאִם שִׁיֵּר שְׁתֵּי שְׂעָרוֹת בְּתִגְלַחַת רִאשׁוֹנָה וְגִלְּחָן בַּשְּׁנִיָּה לֹא עָלְתָה לוֹ אֶלָּא תִּגְלַחַת אַחַת בִּלְבַד וַהֲרֵי הִיא רִאשׁוֹנָה. וְכָל הַיּוֹם כָּשֵׁר לְטָהֳרַת הַמְצֹרָע:","תִּגְלַחַת הַמְצֹרָע וּטְבִילָתוֹ וְהַזָּאָתוֹ אֵינָן מְעַכְּבוֹת זוֹ אֶת זוֹ. וּשְׁאָר כָּל מַעֲשָׂיו מְעַכְּבִים:","שְׁחִיטַת הַצִּפּוֹר וְהַתִּגְלַחַת וְהַהַזָּיָה בַּיּוֹם וּשְׁאָר כָּל מַעֲשָׂיו בֵּין בַּיּוֹם בֵּין בַּלַּיְלָה. אֵלּוּ בַּאֲנָשִׁים וּשְׁאָר כָּל מַעֲשָׂיו בֵּין בַּאֲנָשִׁים בֵּין בְּנָשִׁים. אֵלּוּ בְּכֹהֲנִים וּשְׁאָר כָּל מַעֲשָׂיו בֵּין בְּכֹהֲנִים בֵּין בְּיִשְׂרָאֵל:","טָהֳרַת מְצֹרָע זוֹ נוֹהֶגֶת בָּאָרֶץ וּבְחוּצָה לָאָרֶץ. בִּפְנֵי הַבַּיִת וְשֶׁלֹּא בִּפְנֵי הַבַּיִת. וְכֹהֵן שֶׁטִּמְּאוֹ מִצְוָה לְטַהֲרוֹ שֶׁנֶּאֱמַר (ויקרא יג נט) \"לְטַהֲרוֹ אוֹ לְטַמְּאוֹ\". וְהַכּל כְּשֵׁרִין לְטַהֵר אֶת הַמְצֹרָע אֲפִלּוּ זָב וַאֲפִלּוּ טְמֵא מֵת. וְאֵין מְצֹרָע מְטַהֵר מְצֹרָע. וְאֵין מְטַהֲרִין שְׁנֵי מְצֹרָעִין כְּאַחַת שֶׁאֵין עוֹשִׂין מִצְוֹת חֲבִילוֹת:","עֵץ אֶרֶז וְאֵזוֹב וּשְׁנִי תּוֹלַעַת שֶׁטָּהַר בָּהֶן מְצֹרָע זֶה מְטַהֵר בָּהֶן מְצֹרָעִים אֲחֵרִים. וְכֵן צִפּוֹר הַמִּשְׁתַּלַּחַת מֻתָּר לְטַהֵר בָּהּ מְצֹרָעִים אֲחֵרִים מֵאַחַר שֶׁנִּשְׁתַּלְּחָה וּמֻתֶּרֶת בַּאֲכִילָה. אֲבָל הַצִּפּוֹר הַשְּׁחוּטָה אֲסוּרָה בַּהֲנָאָה. וּמֵאֵימָתַי תֵּאָסֵר, מִשְּׁעַת שְׁחִיטָתָהּ. שְׁחָטָהּ וְאֵין שָׁם אֵזוֹב וְלֹא עֵץ אֶרֶז וְלֹא שְׁנִי תּוֹלַעַת הֲרֵי זוֹ אֲסוּרָה בַּהֲנָאָה שֶׁשְּׁחִיטָה שֶׁאֵינָהּ רְאוּיָה שְׁמָהּ שְׁחִיטָה. וְהָאוֹכֵל כְּזַיִת מִצִּפּוֹר הַשְּׁחוּטָה עָבַר עַל עֲשֵׂה וְעַל לֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים יד יב) \"וְזֶה אֲשֶׁר לֹא תֹאכְלוּ מֵהֶם\" מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזֶּה לְרַבּוֹת הַצִּפּוֹר הַשְּׁחוּטָה. וְנֶאֱמַר (דברים יד יא) \"טְהֹרָה תֹּאכֵלוּ\" הָא אַחֶרֶת לֹא תֹּאכְלוּ וְלָאו הַבָּא מִכְּלַל עֲשֵׂה עֲשֵׂה:","אֵין לוֹקְחִין שְׁתֵּי הַצִּפֳּרִים מִצִּפֳּרֵי עִיר הַנִּדַּחַת וְלֹא מִצִּפֳּרִים שֶׁהֶחְלִיפָן בַּעֲבוֹדָה זָרָה וְלֹא מִצִּפֳּרִים שֶׁהָרְגוּ אֶת הַנֶּפֶשׁ. וּמִצְוָתָן שֶׁיִּהְיוּ שְׁתֵּיהֶן שָׁווֹת בְּמַרְאֶה בְּקוֹמָה וּבְדָמִים וּלְקִיחָתָן כְּאַחַת. אַף עַל פִּי שֶׁאֵינָן שָׁווֹת אוֹ שֶׁלָּקַח אַחַת הַיּוֹם וְאַחַת לְמָחָר כְּשֵׁרוֹת. לָקַח שְׁתֵּי הַצִּפֳּרִים לְשֵׁם אִישׁ כְּשֵׁרוֹת לְטַהֵר בָּהֶן אִשָּׁה. לְשֵׁם אִשָּׁה כְּשֵׁרוֹת לְטַהֵר בָּהֶן אִישׁ. לְטַהֵר בָּהֶן בַּיִת מְנֻגָּע כְּשֵׁרוֹת לְטַהֵר אָדָם. לְקָחָן לְאָדָם כְּשֵׁרוֹת לְבַיִת מְנֻגָּע שֶׁנֶּאֱמַר (ויקרא יד ד) \"וְלָקַח לַמִּטַּהֵר\":","שָׁחַט אַחַת מֵהֶן וְנִמְצֵאת שֶׁלֹּא הָיְתָה דְּרוֹר יִקַּח זוּג לַשְּׁנִיָּה וְהָרִאשׁוֹנָה מֻתֶּרֶת בַּאֲכִילָה. שָׁחַט הָאַחַת וְנִמְצֵאת טְרֵפָה יִקַּח זוּג לַשְּׁנִיָּה וְהָרִאשׁוֹנָה מֻתֶּרֶת בַּהֲנָאָה:","נִשְׁפַּךְ הַדָּם מַנִּיחִין אֶת הַמִּשְׁתַּלַּחַת עַד שֶׁתָּמוּת. מֵתָה הַמִּשְׁתַּלַּחַת יִשָּׁפֵךְ הַדָּם וְיִקַּח שְׁתַּיִם אֲחֵרוֹת:"],"Mishneh Torah, Defilement by Leprosy 8":["נִגְעֵי הָרֹאשׁ וְהַזָּקָן הוּא שֶׁיִּפּל הַשֵּׂעָר שֶׁבָּהֶן מֵעִקָּרוֹ וְיִשָּׁאֵר מְקוֹם הַשֵּׂעָר פָּנוּי וְזֶה הוּא הַנִּקְרָא נֶתֶק. וְאֵין נֶתֶק פָּחוֹת מִכִּגְרִיס הַמְרֻבָּע בֵּין שֶׁהָיָה מַרְאֵהוּ עָמֹק בֵּין שֶׁלֹּא הָיָה עָמֹק. וְלֹא נֶאֱמַר עָמֹק בִּנְתָקִין אֶלָּא לוֹמַר לְךָ מַה מַּרְאֶה עָמֹק בִּידֵי שָׁמַיִם אַף נֶתֶק הַמִּטַמֵא בִּידֵי שָׁמַיִם לְהוֹצִיא שֶׁנִּתְּקוֹ אָדָם שֶׁהוּא טָהוֹר. וְהָאִשָּׁה וְהַסָּרִיס שֶׁהֶעֱלָה זְקָנָם שֵׂעָר הֲרֵי זֶה מִטַּמֵּא בִּנְתָקִים:","הַנְּתָקִין מִטַמְּאִין בִּשְׁנֵי סִימָנִים בְּשֵׂעָר צָהֹב דַּק וּבְפִשְׂיוֹן וְיֵשׁ בָּהֶן הֶסְגֵּר שְׁנֵי שָׁבוּעוֹת וְכָל זֶה מְפֹרָשׁ בַּתּוֹרָה. כֵּיצַד. מִי שֶׁנּוֹלַד לוֹ נֶתֶק בְּרֹאשׁוֹ אוֹ בִּזְקָנוֹ אִם הָיוּ בּוֹ שְׁתֵּי שְׂעָרוֹת צְהֻבּוֹת דַּקּוֹת וְלֹא יוֹתֵר וְאֵין שָׁם בַּנֶּתֶק שֵׂעָר שָׁחֹר כְּלָל יַחְלִיט. לֹא הָיָה בּוֹ שֵׂעָר לֹא שָׁחֹר וְלֹא צָהֹב יַסְגִּיר שָׁבוּעַ אֶחָד וּבַשְּׁבִיעִי רוֹאֵהוּ אִם נוֹלַד בּוֹ שֵׂעָר צָהֹב דַּק אוֹ שֶׁפָּשָׂה הַנֶּתֶק יַחְלִיט נוֹלְדוּ בּוֹ שְׁתֵּי שְׂעָרוֹת שְׁחוֹרוֹת יִפְטֹר אוֹתוֹ. לֹא פָּשָׂה וְלֹא נוֹלַד בּוֹ שֵׂעָר צָהֹב וְלֹא שֵׂעָר שָׁחֹר יְגַלֵּחַ סְבִיבוֹת הַנֶּתֶק וְלֹא יְגַלֵּחַ הַנֶּתֶק וְיַסְגִּיר שָׁבוּעַ שֵׁנִי וְחוֹזֵר וְרוֹאֵהוּ בְּסוֹף שָׁבוּעַ שֵׁנִי. אִם פָּשָׂה הַנֶּתֶק אוֹ נוֹלַד בּוֹ שֵׂעָר צָהֹב דַּק יַחְלִיט. לֹא נוֹלַד בּוֹ כְּלוּם יִפְטֹר שֶׁאֵין הֶסְגֵּר בִּנְתָקִין יֶתֶר עַל שְׁנֵי שָׁבוּעוֹת. וְאִם אַחַר שֶׁפְּטָרוֹ נוֹלַד בּוֹ שֵׂעָר צָהֹב אוֹ פָּשָׂה יַחְלִיט:","כֵּיצַד מְגַלְּחִין אֶת הַנֶּתֶק. מְגַלֵּחַ חוּצָה לוֹ וּמַנִּיחַ שְׁתֵּי שְׂעָרוֹת סָמוּךְ לוֹ כְּדֵי שֶׁיִּהְיֶה נִכָּר הַפִּשְׂיוֹן. וְתִגְלַחְתּוֹ כְּשֵׁרָה בְּכָל אָדָם שֶׁנֶּאֱמַר (ויקרא יג לג) \"וְהִתְגַּלָּח\" וְכֵן כְּשֵׁרָה בְּכָל דָּבָר וַאֲפִלּוּ הָיָה נָזִיר הֲרֵי זֶה מְגַלֵּחַ. הִסְגִּירוֹ וְלֹא גִּלְּחוֹ הֲרֵי זֶה מֻסְגָּר:","(ויקרא יג ל) \"שֵׂעָר צָהֹב\" הָאָמוּר בַּתּוֹרָה הוּא שֶׁיִּהְיֶה כְּתַבְנִית הַזָּהָב. וְזֶה שֶׁנֶּאֱמַר (ויקרא יג ל) \"דַּק\" הוּא שֶׁיִּהְיֶה קָצָר אֲבָל אִם הָיָה אָרֹךְ אַף עַל פִּי שֶׁהוּא צָהֹב כְּתַבְנִית הַזָּהָב אֵינוֹ סִימַן טֻמְאָה:","שְׁתֵּי שְׂעָרוֹת הַצְּהֻבּוֹת הַדַּקּוֹת סִימַן טֻמְאָה. בֵּין שֶׁהָיוּ זוֹ בְּצַד זוֹ בֵּין שֶׁהָיוּ מְרֻחָקוֹת זוֹ מִזּוֹ. בֵּין שֶׁהָיוּ בְּאֶמְצַע הַנֶּתֶק בֵּין שֶׁהָיוּ בְּסוֹף הַנֶּתֶק. בֵּין שֶׁקָּדַם הַנֶּתֶק אֶת הַשֵּׂעָר הַצָּהֹב בֵּין שֶׁקָּדַם הַשֵּׂעָר הַצָּהֹב אֶת הַנֶּתֶק. הֲרֵי הוּא סִימַן טֻמְאָה. וְהוּא שֶׁיִּהְיוּ נִטָּלוֹת בְּזוּג כְּמוֹ שֶׁבֵּאַרְנוּ בַּשֵּׂעָר הַלָּבָן:","הַשֵּׂעָר הַשָּׁחֹר הַמַּצִּיל בִּנְתָקִין אֵין פָּחוֹת מִשְּׁתֵי שְׂעָרוֹת. וְאֵינָן מַצִּילוֹת עַד שֶׁיִּהְיוּ אָרְכָּן כְּדֵי לָכֹף רֹאשָׁן לְעִקָּרָן. בֵּין שֶׁהָיוּ זוֹ בְּצַד זוֹ בֵּין שֶׁהָיוּ מְפֻזָּרוֹת וְהוּא שֶׁיִּהְיוּ בְּאֶמְצַע הַנֶּתֶק וְיִשָּׁאֵר מִן הַנֶּתֶק פָּנוּי בֵּין הַשֵּׂעָר הַשָּׁחֹר שֶׁבְּתוֹכוֹ וּבֵין הַשֵּׂעָר שֶׁחוּצָה לוֹ כְּדֵי צְמִיחַת שְׁתֵּי שְׂעָרוֹת. אֲבָל אִם נִשְׁאֲרוּ הַשְּׁתֵּי שְׂעָרוֹת הַשְּׁחֹרוֹת בְּצַד הַנֶּתֶק בְּסוֹפוֹ אֵינָן מַצִּילוֹת. כֵּיצַד מַצִּילוֹת. שֶׁאִם נִשְׁאַר בְּתוֹךְ הַנֶּתֶק שְׁתֵּי שְׂעָרוֹת שְׁחוֹרוֹת אַף עַל פִּי שֶׁנּוֹלְדָה בַּנֶּתֶק שֵׂעָר צָהֹב דַּק אוֹ שֶׁפָּשָׂה הֲרֵי זֶה טָהוֹר. הֶחְלִיטוֹ בְּשֵׂעָר צָהֹב אוֹ בְּפִשְׂיוֹן וְצָמַח בַּנֶּתֶק שְׁתֵּי שְׂעָרוֹת שְׁחֹרוֹת טִהֵר הַנֶּתֶק וּמַצִּילוֹת מִיַּד הַפִּשְׂיוֹן וּמִיַּד הַשֵּׂעָר הַצָּהֹב. בֵּין שֶׁצָּמְחוּ בְּאֶמְצַע הַנֶּתֶק בֵּין שֶׁצָּמְחוּ בְּסוֹפוֹ. שֶׁהַצּוֹמֵחַ מַצִּיל בְּכָל מָקוֹם וְהַנִּשְׁאָר אֵינוֹ מַצִּיל עַד שֶׁיִּהְיֶה רָחוֹק מִן הַקָּמָה שְׁתֵּי שְׂעָרוֹת:","שְׁתֵּי שְׂעָרוֹת שֶׁצָּמְחוּ אַחַת שְׁחוֹרָה וְאַחַת לְבָנָה אוֹ צְהֻבָּה אַחַת אֲרֻכָּה וְאַחַת קְצָרָה אֵינָן מַצִּילוֹת:","נֶתֶק שֶׁהֻחְלַט בְּשֵׂעָר צָהֹב אוֹ בְּפִשְׂיוֹן וְנוֹלַד בּוֹ שֵׂעָר שָׁחוֹר וְטִהֵר. אַף עַל פִּי שֶׁהָלַךְ הַשֵּׂעָר הַשָּׁחוֹר הֲרֵי זֶה טָהוֹר עַד שֶׁיִּוָּלֵד בּוֹ שֵׂעָר צָהֹב אַחֵר אוֹ יִפְשֶׂה פִּשְׂיוֹן אַחֵר מֵאַחַר שֶׁהָלַךְ הַשֵּׂעָר הַשָּׁחֹר. שֶׁנֶּאֱמַר (ויקרא יג לז) \"נִרְפָּא הַנֶּתֶק טָהוֹר הוּא\" כֵּיוָן שֶׁנִּתְרַפֵּא טָהוֹר הוּא אַף עַל פִּי שֶׁסִּימָנֵי טֻמְאָה בִּמְקוֹמָן:","הֶחְלִיטוֹ בְּשֵׂעָר צָהֹב בֵּין שֶׁהֶחְלִיטוֹ בַּתְּחִלָּה בֵּין שֶׁהֶחְלִיטוֹ בְּסוֹף שָׁבוּעַ רִאשׁוֹן אוֹ בְּסוֹף שָׁבוּעַ שֵׁנִי אוֹ שֶׁהֶחְלִיטוֹ אַחַר הַפִּטּוּר וְהָלַךְ הַשֵּׂעָר הַצָּהֹב וְנוֹלַד בּוֹ שֵׂעָר צָהֹב אַחֵר אוֹ שֶׁנּוֹלַד לוֹ פִּשְׂיוֹן הֲרֵי זֶה מֻחְלָט כְּשֶׁהָיָה. וְכֵן אִם הֶחְלִיטוֹ בְּפִשְׂיוֹן בֵּין בְּסוֹף שָׁבוּעַ רִאשׁוֹן אוֹ בְּסוֹף שָׁבוּעַ שֵׁנִי אוֹ אַחַר הַפִּטּוּר וְהָלַךְ הַפִּשְׂיוֹן וְחָזַר פִּשְׂיוֹן אַחֵר אוֹ שֶׁנּוֹלַד לוֹ שֵׂעָר צָהֹב הֲרֵי זֶה מֻחְלָט כְּשֶׁהָיָה עַד שֶׁלֹּא יִשָּׁאֵר סִימַן טֻמְאָה אוֹ עַד שֶׁיַּצְמִיחַ בּוֹ שְׁתֵּי שְׂעָרוֹת שְׁחוֹרוֹת:","שְׁנֵי נְתָקִים זֶה בְּצַד זֶה וְשִׁיטָה שֶׁל שֵׂעָר שָׁחוֹר מַפְסֶקֶת בֵּינֵיהֶן וְנִפְרַץ הַשֵּׂעָר הַשָּׁחוֹר (וְנִתַּק) מִמָּקוֹם אֶחָד הֲרֵי הוּא כְּמוֹת שֶׁהָיָה שֶׁהַשֵּׂעָר הַשָּׁחוֹר הַנִּשְׁאָר בֵּינֵיהֶן הֲרֵי הוּא בְּצַד הַנֶּתֶק. נִפְרְצָה הַשִּׁטָּה מִשְּׁנֵי מְקוֹמוֹת טָהוֹר שֶׁהֲרֵי הַנִּשְׁאָר מִן הַשִּׁטָּה בְּאֶמְצַע הַנֶּתֶק. וְכַמָּה יִהְיֶה בְּכָל פִּרְצָה מֵהֶן. אֵין פָּחוֹת מִמְּקוֹם צְמִיחַת שְׁתֵּי שְׂעָרוֹת. וְאִם הָיְתָה פִּרְצָה מִמָּקוֹם אֶחָד כִּגְרִיס הֲרֵי זֶה טָמֵא שֶׁהַפִּרְצָה עַצְמָהּ נֶתֶק אַחֵר. וַהֲרֵי שֵׂעָר שָׁחוֹר בְּצִדּוֹ וְאֵינוֹ כָּנוּס לְתוֹכוֹ. נֶתֶק שֶׁהַשֵּׂעָר הַשָּׁחוֹר מַקִּיפוֹ וְנֶתֶק אַחֵר מַקִּיף אֶת הַשֵּׂעָר הַשָּׁחוֹר. נִפְרַץ הַשֵּׂעָר שֶׁבֵּינֵיהֶן מִמָּקוֹם אֶחָד טָמֵא שֶׁהַנֶּתֶק הַפְּנִימִי לֹא נִצַּל שֶׁהֲרֵי הַשֵּׂעָר הַשָּׁחֹר בְּצִדּוֹ לֹא בְּתוֹכוֹ. נִפְרָץ הַשֵּׂעָר מִשְּׁנֵי מְקוֹמוֹת טָהוֹר וַאֲפִלּוּ הָיְתָה פִּרְצָה כִּגְרִיס. שֶׁהֲרֵי הַנֶּתֶק הַפְּנִימִי וְהַחִיצוֹן נַעֲשׂוּ נֶתֶק אֶחָד וְשֵׂעָר שָׁחוֹר בָּאֶמְצַע. וְהוּא שֶׁתִּהְיֶה הַפִּרְצָה כְּדֵי צְמִיחַת שְׁתֵּי שְׂעָרוֹת אוֹ יֶתֶר:","נֶתֶק שֶׁהָיָה חוּט יוֹצֵא מִמֶּנּוּ וְכֵן שְׁנֵי נְתָקִין שֶׁחוּט יוֹצֵא מִזֶּה לָזֶה. אִם יֵשׁ בְּרֹחַב הַחוּט הַנָּתוּק כְּדֵי צְמִיחַת שְׁתֵּי שְׂעָרוֹת זוֹקְקִין לִטַּמֵּא בְּשֵׂעָר צָהֹב דַּק וּפִשְׂיוֹן וּמַצִּילִין בַּצּוֹמֵחַ בּוֹ. אֲבָל שֵׂעָר שָׁחוֹר הַנִּשְׁאָר בְּאוֹתוֹ הַחוּט אֵינוֹ מַצִּיל עַד שֶׁיִּהְיֶה רֹחַב הַחוּט כִּגְרִיס:","מִי שֶׁהָיָה בְּרֹאשׁוֹ נֶתֶק כִּגְרִיס וּפָשָׂה הַנֶּתֶק [עַל] כָּל רֹאשׁוֹ וְלֹא נִשְׁאַר שָׁם שֵׂעָר כְּלָל אֶלָּא פָּחוֹת מִשְּׁתֵי שְׂעָרוֹת הֲרֵי זֶה טָהוֹר. בֵּין שֶׁנִּתַּק כֻּלּוֹ מִתּוֹךְ הֶסְגֵּר אוֹ מִתּוֹךְ הֶחְלֵט אוֹ אַחַר הַפִּטּוּר שֶׁנֶּאֱמַר (ויקרא יג מ) \"קֵרֵחַ הוּא טָהוֹר הוּא\". וְכֵן אִם הָיָה הַנֶּתֶק בִּזְקָנוֹ וְנִתַּק כָּל זְקָנוֹ הֲרֵי זֶה טָהוֹר. וְאַף עַל פִּי שֶׁאֵין זֶה מְפֹרָשׁ בַּתּוֹרָה שֶׁבִּכְתָב קַבָּלָה הִיא שֶׁאִם הָלַךְ כָּל שֵׂעָר הַזָּקָן טָהוֹר הוּא. וְיִתְטַמֵּא עוֹר הַזָּקָן שֶׁקָּרַח בְּנִגְעֵי עוֹר הַבָּשָׂר כְּמוֹ שֶׁבֵּאַרְנוּ:","הַבָּא בַּתְּחִלָּה וְכָל רֹאשׁוֹ נָתוּק אוֹ כָּל זְקָנוֹ נָתוּק יַסְגִּיר שָׁבוּעַ אֶחָד. אִם לֹא נוֹלַד לוֹ שֵׂעָר צָהֹב יַסְגִּיר שָׁבוּעַ שֵׁנִי. אִם נוֹלַד לוֹ שֵׂעָר צָהֹב דַּק טָמֵא. לֹא נוֹלַד לוֹ יִפָּטֵר. נוֹלַד לוֹ אַחַר הַפִּטּוּר שֵׂעָר צָהֹב הֲרֵי זֶה מֻחְלָט. נוֹלַד לוֹ שֵׂעָר שָׁחוֹר הֲרֵי זֶה טָהוֹר. הַבָּא כֻּלּוֹ נָתוּק רֹאשׁ אוֹ זָקָן וְנוֹלַד לוֹ שֵׂעָר שָׁחוֹר טָהוֹר כְּמוֹ שֶׁבֵּאַרְנוּ. הָלַךְ הַשֵּׂעָר הַשָּׁחוֹר טָמֵא מִשּׁוּם פִּשְׂיוֹן:","הָרֹאשׁ וְהַזָּקָן אֵינָן מְעַכְּבִין זֶה אֶת זֶה וְאֵינָן מִצְטָרְפִין זֶה עִם זֶה וְאֵין פּוֹשִׂין מִזֶּה לָזֶה שֶׁנֶּאֱמַר (ויקרא יג ל) \"צָרַעַת הָרֹאשׁ אוֹ הַזָּקָן\" מְלַמֵּד שֶׁהֵן חֲשׁוּבִין שְׁנַיִם. וְאֵי זֶהוּ זָקָן. מֵהַפֶּרֶק שֶׁל לֶחִי הָעֶלְיוֹן עַד פִּיקָה שֶׁל גְּרֹגֶרֶת. מוֹתֵחַ אֶת הַחוּט מֵאֹזֶן לְאֹזֶן. כָּל שֶׁמִּן הַחוּט וּלְמַעְלָה הֲרֵי הוּא מִכְּלַל הָרֹאשׁ. וּמִן הַחוּט וּלְמַטָּה מִכְּלַל הַזָּקָן:"],"Mishneh Torah, Defilement by a Corpse 19":["כַּוְּרֶת שְׁהִיא מֻטֶּלֶת בָּאָרֶץ וְהִיא בְּתוֹךְ פֶּתַח הַבַּיִת וּפִיהָ לַחוּץ וּכְזַיִת מִן הַמֵּת נָתוּן תַּחְתֶּיהָ אוֹ עַל גַּבָּהּ מִבַּחוּץ. כָּל שֶׁהוּא כְּנֶגֶד הַזַּיִת בְּתַחְתֶּיהָ אוֹ בָּגֹבַהּ טָמֵא וְכָל מַה שֶּׁבַּאֲוִיר תּוֹכָהּ טָהוֹר חוּץ מִכְּלִי שֶׁהוּא כְּנֶגֶד הַטֻּמְאָה וְהַבַּיִת טָהוֹר. הָיְתָה הַטֻּמְאָה בַּבַּיִת אֵין טָמֵא אֶלָּא הַבַּיִת אֲבָל כֵּלִים שֶׁבְּתוֹכָהּ תַּחְתֶּיהָ אוֹ עַל גַּבָּהּ טְהוֹרִים. הָיְתָה הַטֻּמְאָה בְּתוֹכָהּ הַכּל טָמֵא כָּל שֶׁבַּבַּיִת וְכָל שֶׁבְּתוֹכָהּ וְכָל שֶׁעַל גַּבָּהּ וְכָל שֶׁתַּחְתֶּיהָ כְּנֶגֶד הַטֻּמְאָה כְּמוֹ שֶׁבֵּאַרְנוּ. הָיְתָה גְּבוֹהָה מִן הָאָרֶץ טֶפַח וְטֻמְאָה תַּחְתֶּיהָ אוֹ בַּבַּיִת אוֹ עַל גַּבָּהּ הַכּל טָמֵא כָּל שֶׁבַּבַּיִת וְכָל שֶׁתַּחְתֶּיהָ וְכָל שֶׁעַל גַּבָּהּ אֲבָל כָּל שֶׁבַּאֲוִיר תּוֹכָהּ טָהוֹר חוּץ מִכְּלִי שֶׁהוּא כְּנֶגֶד הַטֻּמְאָה. הָיְתָה הַטֻּמְאָה בְּתוֹכָהּ הַכּל טָמֵא כָּל שֶׁבְּתוֹכָהּ וְכָל שֶׁבַּבַּיִת וְכָל שֶׁתַּחְתֶּיהָ וְכָל שֶׁעַל גַּבָּהּ. שֶׁהַכֵּלִים אוֹ הָאָדָם שֶׁנַּעֲשׂוּ אֹהֶל עַל הַטֻּמְאָה אוֹ שֶׁהָיְתָה הַטֻּמְאָה עַל גַּבֵּיהֶן מְבִיאִין וְלֹא חוֹצְצִין כְּמוֹ שֶׁבֵּאַרְנוּ. בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁהִיא כְּלִי וּמְחֻלְחֶלֶת. אֲבָל אִם הָיְתָה פְּחוּתָה וְסָתַם הַמָּקוֹם הַנִּפְחָת בְּקַשׁ שֶׁהֲרֵי אֵינָהּ כְּלִי. אוֹ שֶׁהָיְתָה אֲפוּצָה עַד שֶׁלֹּא יִהְיֶה בָּהּ חֲלַל טֶפַח אֶלָּא אֲטוּמָה כְּדֵי שֶׁלֹּא יִמָּצֵא בָּהּ חֲלַל טֶפַח בְּמָקוֹם אֶחָד. הָיְתָה גְּבוֹהָה מִן הָאָרֶץ טֶפַח וְטֻמְאָה תַּחְתֶּיהָ אוֹ בַּבַּיִת. הֲרֵי הַבַּיִת וְכָל שֶׁתַּחְתֶּיהָ טְמֵאִין מִפְּנֵי שֶׁהוּא אֹהֶל אֶחָד וְתוֹכָהּ וְגַבָּהּ טָהוֹר מִפְּנֵי שֶׁהוּא אֹהֶל שֶׁל עֵץ וְאֵינוֹ כְּלִי. הָיְתָה טֻמְאָה בְּתוֹכָהּ אֵין טָמֵא אֶלָּא תּוֹכָהּ. הָיְתָה עַל גַּבָּהּ כְּנֶגְדּוֹ עַד לָרָקִיעַ טָמֵא. הָיְתָה מֻנַּחַת עַל הָאָרֶץ וּפִיהָ לַחוּץ וּכְזַיִת מִן הַמֵּת נָתוּן תַּחְתֶּיהָ כְּנֶגְדּוֹ עַד הַתְּהוֹם טָמֵא. הָיְתָה עַל גַּבָּיו כְּנֶגְדּוֹ עַד הָרָקִיעַ טָמֵא. הָיְתָה טֻמְאָה בַּבַּיִת אֵין טָמֵא אֶלָּא הַבַּיִת בִּלְבַד. הָיְתָה טֻמְאָה בְּתוֹכָהּ אֵין טָמֵא אֶלָּא תּוֹכָהּ:","כַּוֶּרֶת הַמֻּטֶּלֶת בָּאָרֶץ בְּתוֹךְ הַפֶּתַח וּפִיהָ לְפָנִים וְהִיא כְּלִי שָׁלֵם וַחֲלוּלָה וּכְזַיִת מִן הַמֵּת נָתוּן תַּחְתֶּיהָ אוֹ עַל גַּבָּהּ מִבַּחוּץ כָּל שֶׁהוּא כְּנֶגֶד הַזַּיִת בְּתַחְתֶּיהָ אוֹ עַל גַּבָּהּ טָמֵא. וְכָל מַה שֶּׁבַּאֲוִיר תּוֹכָהּ טָהוֹר חוּץ מִכְּנֶגֶד הַטֻּמְאָה. וְהַבַּיִת טָהוֹר. הָיְתָה טֻמְאָה בְּתוֹכָהּ אוֹ בַּבַּיִת הַכּל טָמֵא. הָיְתָה גְּבוֹהָה מִן הָאָרֶץ טֶפַח וְטֻמְאָה תַּחְתֶּיהָ אוֹ בְּתוֹכָהּ אוֹ עַל גַּבָּהּ אוֹ בַּבַּיִת הַכּל טָמֵא כָּל שֶׁבַּבַּיִת וְכָל שֶׁתַּחְתֶּיהָ מִפְּנֵי שֶׁהִיא וְהַבַּיִת כְּאֹהֶל אֶחָד. וְכָל שֶׁעַל גַּבָּהּ וְכָל שֶׁבְּתוֹכָהּ טָמֵא שֶׁהַכְּלִי מֵבִיא אֶת הַטֻּמְאָה וְאֵינוֹ חוֹצֵץ כְּמוֹ שֶׁנִּתְבָּאֵר. הָיְתָה פְּחוּתָה וּפְקוּקָה בְּקַשׁ אוֹ אֲפוּצָה וּגְבוֹהָה מִן הָאָרֶץ טֶפַח וְטֻמְאָה תַּחְתֶּיהָ אוֹ בַּבַּיִת אוֹ בְּתוֹכָהּ הַכּל טָמֵא חוּץ מֵעַל גַּבָּהּ. הָיְתָה טֻמְאָה עַל גַּבָּהּ כְּנֶגְדּוֹ בִּלְבַד עַד לָרָקִיעַ טָמֵא אֲבָל תּוֹכָהּ טָהוֹר וְתַחְתֶּיהָ וְהַבַּיִת כָּל מַה שֶּׁבָּהֶן טָהוֹר מִפְּנֵי שֶׁאֵינָהּ כְּלִי חוֹצֶצֶת. הָיְתָה מֻנַּחַת עַל הָאָרֶץ וּפִיהָ לְפָנִים וּכְזַיִת מִן הַמֵּת נָתוּן תַּחְתֶּיהָ כְּנֶגְדּוֹ עַד הַתְּהוֹם טָמֵא. הָיְתָה עַל גַּבָּהּ כְּנֶגְדּוֹ עַד לָרָקִיעַ טָמֵא. הָיְתָה הַטֻּמְאָה בְּתוֹכָהּ אוֹ בַּבַּיִת תּוֹכָהּ וְהַבַּיִת טָמֵא:","כַּוֶּרֶת שֶׁהִיא בְּתוֹךְ הַבַּיִת וְהִיא מְמַלְּאָה אֶת כָּל גֹּבַהּ הַבַּיִת וּפִיהָ לְמַעְלָה לְקוֹרוֹת הַבַּיִת וְאֵין בֵּינָהּ לְבֵין הַקּוֹרוֹת פּוֹתֵחַ טֶפַח וְטֻמְאָה בְּתוֹכָהּ הַבַּיִת טָמֵא. טֻמְאָה בַּבַּיִת מַה שֶּׁבְּתוֹכָהּ טָהוֹר. שֶׁדֶּרֶךְ הַטֻּמְאָה לָצֵאת לְתוֹךְ הַבַּיִת בְּפָחוֹת מִטֶּפַח וְאֵין דַּרְכָּהּ לְהִכָּנֵס. בֵּין שֶׁהָיְתָה מֻטָּה עַל צִדָּה וּפִיהָ לַכֹּתֶל וּבֵינוֹ וּבֵין הַכֹּתֶל פָּחוֹת מִטֶּפַח בֵּין שֶׁהָיְתָה כַּוֶּרֶת אַחַת בֵּין שֶׁהָיוּ שְׁתַּיִם זוֹ עַל גַּבֵּי זוֹ וְאֵין בֵּין הָעֶלְיוֹנָה לַקּוֹרוֹת אוֹ לַכֹּתֶל פּוֹתֵחַ טֶפַח. הָיְתָה עוֹמֶדֶת בְּתוֹךְ הַפֶּתַח וּפִיהָ לְמַעְלָה וְאֵין בֵּינוֹ לְבֵין הַמַּשְׁקוֹף פּוֹתֵחַ טֶפַח וְטֻמְאָה בְּתוֹכָהּ הַבַּיִת טָהוֹר. טֻמְאָה בַּבַּיִת מַה שֶּׁבְּתוֹכָהּ טָמֵא שֶׁדֶּרֶךְ טֻמְאָה לָצֵאת וְאֵין דַּרְכָּהּ לְהִכָּנֵס:","כַּוֶּרֶת חֲלוּלָה שֶׁהִיא כְּלִי שָׁלֵם וְהָיְתָה מֻנַּחַת עַל צִדֶּיהָ בָּאֲוִיר וּכְזַיִת מִן הַמֵּת נָתוּן תַּחְתֶּיהָ אוֹ עַל גַּבָּהּ כָּל שֶׁהוּא כְּנֶגֶד הַזַּיִת בְּתַחְתֶּיהָ וּבְגַבָּהּ טָמֵא. וְכָל מַה שֶּׁבַּאֲוִיר תּוֹכָהּ טָהוֹר אֶלָּא כְּנֶגֶד הַטֻּמְאָה. וְכָל שֶׁאֵינוֹ כְּנֶגֶד הַטֻּמְאָה בְּתוֹכָהּ טָהוֹר. הָיְתָה טֻמְאָה בְּתוֹכָהּ הַכּל טָמֵא כָּל מַה שֶּׁבְּתוֹכָהּ וְכָל שֶׁכְּנֶגֶד הַטֻּמְאָה לְמַעְלָה עַל גַּבָּהּ אוֹ לְמַטָּה תַּחְתֶּיהָ. הָיְתָה גְּבוֹהָה מִן הָאָרֶץ טֶפַח וְטֻמְאָה תַּחְתֶּיהָ אוֹ עַל גַּבָּהּ כָּל שֶׁתַּחְתֶּיהָ טָמֵא וְכָל שֶׁעַל גַּבָּהּ טָמֵא. אֲבָל כָּל שֶׁבְּתוֹכָהּ טָהוֹר חוּץ מִכְּלִי שֶׁהוּא כְּנֶגֶד הַטֻּמְאָה. הָיְתָה טֻמְאָה בְּתוֹכָהּ הַכּל טָמֵא כָּל מַה שֶּׁבְּתוֹכָהּ וְכָל שֶׁתַּחְתֶּיהָ וְכָל שֶׁלְּמַעְלָה עַל גַּבָּהּ שֶׁהַכֵּלִים מְבִיאִין וְאֵינָן חוֹצְצִין כְּמוֹ שֶׁבֵּאַרְנוּ. לְפִיכָךְ אִם הָיְתָה כַּוֶּרֶת זוֹ הַמֻּטֶּלֶת עַל הָאָרֶץ פְּחוּתָה וּפְקוּקָה בְּקַשׁ אוֹ שֶׁהָיְתָה בָּאָה בְּמִדָּה וּכְזַיִת מִן הַמֵּת נָתוּן תַּחְתֶּיהָ כְּנֶגְדּוֹ עַד הַתְּהוֹם טָמֵא. עַל גַּבָּהּ כְּנֶגְדּוֹ עַד לָרָקִיעַ טָמֵא. בְּתוֹכָהּ אֵינוֹ טָמֵא אֶלָּא תּוֹכָהּ. הָיְתָה גְּבוֹהָה טֶפַח מֵעַל הָאָרֶץ וְטֻמְאָה תַּחְתֶּיהָ תַּחְתֶּיהָ בִּלְבַד טָמֵא. בְּתוֹכָהּ תּוֹכָהּ בִּלְבַד טָמֵא. עַל גַּבָּהּ כְּנֶגְדּוֹ עַד לָרָקִיעַ טָמֵא. שֶׁכְּבָר בֵּאַרְנוּ שֶׁכְּלִי עֵץ הַבָּא בְּמִדָּה כְּאֹהֶל הוּא חָשׁוּב לֹא כְּכֵלִים וּלְפִיכָךְ חוֹצֵץ:","כַּוֶּרֶת שֶׁהִיא כְּלִי שָׁלֵם וְהִיא יוֹשֶׁבֶת עַל שׁוּלֶיהָ לָאֲוִיר וְטֻמְאָה תַּחְתֶּיהָ אוֹ בְּתוֹכָהּ אוֹ עַל גַּבָּהּ. טֻמְאָה בּוֹקַעַת וְעוֹלָה בּוֹקַעַת וְיוֹרֶדֶת. אֲבָל אִם הָיְתָה גְּבוֹהָה מִן הָאָרֶץ טֶפַח אוֹ מְכֻסָּה אוֹ כְּפוּיָה עַל פִּיהָ וְטֻמְאָה תַּחְתֶּיהָ אוֹ בְּתוֹכָהּ אוֹ עַל גַּבָּהּ הַכּל טָמֵא כָּל שֶׁבְּתוֹכָהּ וְכָל שֶׁתַּחְתֶּיהָ וְכָל שֶׁעַל גַּבָּהּ אִם הָיְתָה הַטֻּמְאָה לְמַטָּה. שֶׁהַכְּלִי הַמַּאֲהִיל מֵבִיא אֶת הַטֻּמְאָה וְאֵינוֹ חוֹצֵץ כְּמוֹ שֶׁבֵּאַרְנוּ. לְפִיכָךְ אִם הָיְתָה פְּחוּתָה וּפְקוּקָה בְּקַשׁ אוֹ בָּאָה בְּמִדָּה טֻמְאָה תַּחְתֶּיהָ אוֹ בְּתוֹכָהּ אוֹ עַל גַּבָּהּ טֻמְאָה בּוֹקַעַת וְעוֹלָה בּוֹקַעַת וְיוֹרֶדֶת. וְאִם הָיְתָה גְּבוֹהָה טֶפַח וְטֻמְאָה תַּחְתֶּיהָ תַּחְתֶּיהָ בִּלְבַד טָמֵא. הָיְתָה טֻמְאָה בְּתוֹכָהּ אוֹ עַל גַּבָּהּ כְּנֶגְדּוֹ עַד לָרָקִיעַ טָמֵא וְכֵלִים שֶׁתַּחְתֶּיהָ טְהוֹרִין מִפְּנֵי שֶׁהִיא אֹהֶל וְחוֹצֶצֶת:","גָּמָל שֶׁהוּא עוֹמֵד בַּאֲוִיר טֻמְאָה תַּחְתָּיו כֵּלִים שֶׁעַל גַּבָּיו טְהוֹרִים. טֻמְאָה עַל גַּבָּיו כֵּלִים שֶׁתַּחְתָּיו טְהוֹרִין. הָיָה רוֹבֵץ וְטֻמְאָה תַּחְתָּיו הֲרֵי זוֹ בּוֹקַעַת וְעוֹלָה בּוֹקַעַת וְיוֹרֶדֶת. וְכֵן אִם הָיְתָה טֻמְאָה רְצוּצָה תַּחַת רַגְלוֹ אוֹ עַל גַּבֵּי רַגְלוֹ הֲרֵי זוֹ בּוֹקַעַת וְעוֹלָה וּבוֹקַעַת וְיוֹרֶדֶת. כְּבָר בֵּאַרְנוּ בִּנְזִירוּת שֶׁאִם הָיָה הַנָּזִיר וּכְזַיִת מִן הַמֵּת תַּחַת הַגָּמָל אוֹ תַּחַת הַמִּטָּה וְכַיּוֹצֵא בָּהּ מִשְּׁאָר הַכֵּלִים אַף עַל פִּי שֶׁנִּטְמָא טֻמְאַת שִׁבְעָה אֵינוֹ מְגַלֵּחַ. וּמִשָּׁם אַתָּה לָמֵד שֶׁכָּל אֵלּוּ הַהֲלָכוֹת הָאֲמוּרוֹת בְּטֻמְאַת אֹהָלִים הַנַּעֲשִׂים מִן הָאָדָם אוֹ מִן הַבְּהֵמָה אוֹ מִן הַכֵּלִים הַכּל מִדִּבְרֵי סוֹפְרִים. מֵהֶן דִּבְרֵי קַבָּלָה. וּמֵהֶן גְּזֵרוֹת וְהַרְחָקוֹת. וּלְפִיכָךְ אֵין הַנָּזִיר מְגַלֵּחַ עֲלֵיהֶן וְאֵין חַיָּבִין עֲלֵיהֶן כָּרֵת עַל בִּיאַת מִקְדָּשׁ אוֹ אֲכִילַת קֳדָשָׁיו. וְאֵין הַדְּבָרִים כֻּלָּן אֲמוּרִין אֶלָּא לְעִנְיַן טֻמְאַת תְּרוּמָה וְקָדָשִׁים בִּלְבַד כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Defilement by a Corpse 7":["בַּיִת סָתוּם שֶׁהַמֵּת בְּתוֹכוֹ אוֹ שֶׁהָיָה לוֹ פֶּתַח [וּפָרַץ אֶת פְּצִימָיו] וּסְתָמוֹ מְטַמֵּא מִכָּל סְבִיבָיו וְהַנּוֹגֵעַ בּוֹ מֵאֲחוֹרָיו אוֹ מִגַּגּוֹ טָמֵא שִׁבְעָה מִפְּנֵי שֶׁהוּא כְּקֶבֶר סָתוּם. נִפְתַּח בּוֹ פֶּתַח אֲפִלּוּ סְתָמוֹ אִם לֹא פָּרַץ פְּצִימָיו הַנּוֹגֵעַ בּוֹ מֵאֲחוֹרָיו וּמִגַּגּוֹ טָהוֹר וְאֵין טָמֵא אֶלָּא כְּנֶגֶד הַפֶּתַח. וְכַמָּה יִהְיֶה שִׁעוּר הַפֶּתַח. שָׁלֵם הַמֵּת פִּתְחוֹ בְּאַרְבָּעָה טְפָחִים. וּכְזַיִת מִן הַמֵּת פִּתְחוֹ בְּטֶפַח. וְגָדוֹל מִכְּזַיִת הֲרֵי הוּא כְּמֵת וּפִתְחוֹ בְּאַרְבָּעָה:","הַמֵּת בְּתוֹךְ הַבַּיִת וּבוֹ פְּתָחִים הַרְבֵּה בִּזְמַן שֶׁכֻּלָּם נְעוּלִים כֻּלָּם טְמֵאִים וְהַיּוֹשֵׁב בְּצַד כָּל פֶּתַח מֵהֶן תַּחַת הַתִּקְרָה הַיּוֹצֵא עַל הַפֶּתַח נִטְמָא. נִפְתַּח אֶחָד מֵהֶן אוֹ שֶׁחָשַׁב לְהוֹצִיאוֹ בְּאֶחָד מֵהֶן וְאַף עַל פִּי שֶׁחָשַׁב אַחַר שֶׁמֵּת הַמֵּת אֲפִלּוּ חָשַׁב לְהוֹצִיאוֹ בְּחַלּוֹן שֶׁהִיא אַרְבָּעָה עַל אַרְבָּעָה הִצִּיל עַל הַפְּתָחִים כֻּלָּן וְאֵין טָמֵא אֶלָּא כְּנֶגֶד הַפֶּתַח שֶׁנִּפְתַּח אוֹ שֶׁחָשַׁב עָלָיו וְהַשְּׁאָר טְהוֹרִין מִפְּנֵי שֶׁהֵן נְעוּלִין וַהֲרֵי אֵין הַבַּיִת כְּקֶבֶר סָתוּם. וְכֵן אִם הִתְחִיל לַחְתֹּר פֶּתַח לְהוֹצִיאוֹ בּוֹ מִשֶּׁיַּחְתֹּר אַרְבָּעָה עַל אַרְבָּעָה הִצִּיל עַל הַפְּתָחִים כֻּלָּן. הָיָה שָׁם פֶּתַח סָתוּם וְחָשַׁב לְהוֹצִיאוֹ וְהִתְחִיל לְפָתְחוֹ מִשֶּׁיַּתְחִיל לִפְתֹּחַ הִצִּיל עַל הַפְּתָחִים כֻּלָּן. הָיוּ בּוֹ חַלּוֹנוֹת הַרְבֵּה וְכֻלָּן מֻגָּפוֹת כֻּלָּן טְהוֹרוֹת. נִפְתְּחוּ כֻּלָּן טְמֵאוֹת וְלֹא הִצִּילוּ עַל הַפְּתָחִים. פֶּתַח קָטָן בְּתוֹךְ פֶּתַח גָּדוֹל הַמַּאֲהִיל עַל גַּבֵּי שְׁנֵיהֶם טָמֵא. חָשַׁב לְהוֹצִיאוֹ בַּקָּטָן טִהֵר קָטָן אֶת הַגָּדוֹל. הָיוּ שְׁנֵיהֶן מַתְאִימִין הַמַּאֲהִיל עַל גַּבֵּי שְׁנֵיהֶם טָמֵא. חָשַׁב לְהוֹצִיאוֹ בְּאֶחָד מֵהֶן טִהֵר אֶת חֲבֵרוֹ. הָיָה לַבַּיִת פֶּתַח אֶחָד לְצָפוֹן וּפֶתַח לְדָרוֹם וְחָשַׁב לְהוֹצִיאוֹ בַּצְּפוֹנִי וְאַחַר כָּךְ בָּאוּ אֶחָיו אוֹ קְרוֹבָיו וְאָמְרוּ אֵין מוֹצִיאִין אוֹתוֹ אֶלָּא בַּדְּרוֹמִי טִהֵר דְּרוֹמִי אֶת הַצְּפוֹנִי. וּבִלְבַד שֶׁלֹּא יַעֲרִים. וְאִם הֶעֱרִים שְׁנֵיהֶן טְמֵאִים:","בָּתִּים הַפְּתוּחִין לְאַכְסַדְרָה וְהַמֵּת בְּאֶחָד מֵהֶן אִם הָיָה דַּרְכּוֹ שֶׁל מֵת לָצֵאת בָּאַכְסַדְרָה הֲרֵי הַבֵּית שַׁעַר וְהַבָּתִּים טְמֵאִים וְאִם לָאו בֵּית שַׁעַר טָמֵא וְהַבַּיִת טָהוֹר. הַחֶדֶר שֶׁלִּפְנִים מִן הַבַּיִת מוּגָף וְנִכְנְסָה טֻמְאָה לְפָנִים דֶּרֶךְ חַלּוֹן הַבַּיִת הַחִיצוֹן טָהוֹר מִפְּנֵי שֶׁהַטֻּמְאָה חוֹזֶרֶת וְיוֹצֵאת דֶּרֶךְ הַחַלּוֹן שֶׁנִּכְנְסָה בּוֹ:","אֵין הַקֶּבֶר מְטַמֵּא מִכָּל סְבִיבָיו עַד שֶׁיִּהְיֶה שָׁם חֲלַל טֶפַח עַל טֶפַח עַל רוּם טֶפַח. אֲפִלּוּ הִגְבִּיהַּ הַבִּנְיָן עַל גַּבֵּי חֲלַל טֶפַח עַד לָרָקִיעַ הַכּל טָמֵא לְפִי שֶׁהַכּל כְּקֶבֶר. הָיְתָה טֻמְאָה רְצוּצָה וְלֹא הָיָה שָׁם חֲלַל טֶפַח טֻמְאָה בּוֹקַעַת וְעוֹלָה בּוֹקַעַת וְיוֹרֶדֶת וְאֵין טָמֵא אֶלָּא הַנּוֹגֵעַ כְּנֶגֶד הַטֻּמְאָה מִלְּמַעְלָה אוֹ הַמַּאֲהִיל עָלֶיהָ מִלְּמַעְלָה אוֹ הַנּוֹגֵעַ כְּנֶגְדָּהּ מִלְּמַטָּה אוֹ מַה שֶּׁהֶאֱהִיל עָלָיו מִלְּמַטָּה אֲבָל הַנּוֹגֵעַ בְּצִדֵּי הַבִּנְיָן טָהוֹר:","זֶה כְּלָל גָּדוֹל בְּטֻמְאַת מֵת שֶׁכָּל דָּבָר הַמְטַמֵּא בְּאֹהֶל מִן הַמֵּת אִם הָיָה רָצוּץ שֶׁאֵין לוֹ חֲלַל טֶפַח הֲרֵי הַטֻּמְאָה בּוֹקַעַת וְעוֹלָה עַד לָרָקִיעַ בּוֹקַעַת וְיוֹרֶדֶת עַד הַתְּהוֹם וְאֵינָהּ מְטַמְּאָה מִן הַצְּדָדִין. כֵּיצַד. כְּרִי שֶׁל תְּבוּאָה אוֹ גַּל שֶׁל אֲבָנִים וּכְזַיִת מִן הַמֵּת בְּתוֹכוֹ וְכֵלִים בְּצַד הַטֻּמְאָה וְאֵינָן נוֹגְעִין בָּהּ כֵּלִים טְהוֹרִין וְכָל כְּלִי שֶׁבְּתוֹךְ הַגַּל מְכֻוָּן כְּנֶגֶד הַטֻּמְאָה מִלְּמַעְלָה אוֹ מִלְּמַטָּה טָמֵא שֶׁהַטֻּמְאָה בּוֹקַעַת וְעוֹלָה וּבוֹקַעַת וְיוֹרֶדֶת. וְאִם הָיָה מְקוֹם הַטֻּמְאָה חָלוּל טֶפַח עַל טֶפַח עַל רוּם טֶפַח הוּא כְּקֶבֶר סָתוּם וּמְטַמֵּא מִכָּל סְבִיבָיו:","בַּיִת שֶׁמִּלְּאוֹ עָפָר אוֹ צְרוֹרוֹת הֲרֵי זֶה בִּטֵּל הַבַּיִת וַהֲרֵי הוּא כְּגַל שֶׁל עָפָר אוֹ צְרוֹרוֹת וְאִם הָיְתָה טֻמְאָה בְּתוֹךְ הֶעָפָר בּוֹקַעַת וְעוֹלָה בּוֹקַעַת וְיוֹרֶדֶת וְכֵלִים שֶׁבְּצִדֶּיהָ בְּתוֹךְ הֶעָפָר טְהוֹרִים:","טֻמְאָה שֶׁהִיא רְצוּצָה בְּכֹתֶל וְסָמַךְ סֻכָּה לַכֹּתֶל הַסֻּכָּה טְמֵאָה שֶׁהֲרֵי נַעֲשָׂה הַכֹּתֶל צַד מִצִּדֵּי הָאֹהֶל. וְאַף עַל פִּי שֶׁהַצְּדָדִין טְהוֹרִים לַנּוֹגֵעַ אִלּוּ לֹא הָיָה עֲלֵיהֶן אֹהֶל אֲבָל מִשֶּׁנַּעֲשָׂה עֲלֵיהֶן אֹהֶל הָאֹהֶל כֻּלּוֹ טָמֵא שֶׁהֲרֵי הַטֻּמְאָה בְּתוֹכוֹ:"],"Mishneh Torah, Defilement of Foods 3":["כְּבָר בֵּאַרְנוּ שֶׁאֵין הָאֳכָלִין מִתְטַמְּאִין עַד שֶׁיֻּכְשְׁרוּ. וְשֶׁכָּל אֹכֶל שֶׁאֵינוֹ מְיֻחָד לְמַאֲכַל אָדָם אֵינוֹ מְקַבֵּל טֻמְאָה עַד שֶׁיְּיַחֲדוֹ לְאָדָם:","אֹכֶל שֶׁהוּא מְיֻחָד לָאָדָם בַּמָּקוֹם הַזֶּה וְאֵינוֹ מְיֻחָד לְאָדָם בְּמָקוֹם אַחֵר בְּמָקוֹם שֶׁהוּא מְיֻחָד בּוֹ אֵינוֹ צָרִיךְ מַחֲשָׁבָה לְיַחֲדוֹ לְאָדָם וּבְמָקוֹם שֶׁאֵינוֹ מְיֻחָד בּוֹ צָרִיךְ מַחֲשָׁבָה לְיַחֲדוֹ לְאָדָם וְאַחַר כָּךְ יְקַבֵּל טֻמְאָה. וְכָל אֹכֶל שֶׁסּוֹפוֹ לְטַמֵּא אָדָם וְכֵלִים אֵינוֹ צָרִיךְ הֶכְשֵׁר:","יֵשׁ אֳכָלִין שֶׁצְּרִיכִין הֶכְשֵׁר וְאֵינָן צְרִיכִין מַחֲשָׁבָה וְיֵשׁ שֶׁצְּרִיכִין מַחֲשָׁבָה וְאֵינָן צְרִיכִין הֶכְשֵׁר וְיֵשׁ שֶׁצְּרִיכִין מַחֲשָׁבָה וְהֶכְשֵׁר וְיֵשׁ שֶׁאֵין צְרִיכִין לֹא מַחֲשָׁבָה וְלֹא הֶכְשֵׁר. כֵּיצַד. כָּל הָאֳכָלִין הַמְיֻחָדִין לְאָדָם בְּכָל מָקוֹם צְרִיכִין הֶכְשֵׁר וְאֵין צְרִיכִין מַחֲשָׁבָה. דָּגִים טְהוֹרִים וַחֲגָבִים טְהוֹרִים בְּכָל מָקוֹם וַחֲגָבִים טְמֵאִים וְדָגִים טְמֵאִים בַּכְּפָרִים הֲרֵי הֵן מְיֻחָדִין לְאָדָם וּצְרִיכִין הֶכְשֵׁר וְלֹא מַחֲשָׁבָה. וְכֵן חֵלֶב בְּהֵמָה טְהוֹרָה שֶׁמֵּתָה צָרִיךְ הֶכְשֵׁר וְלֹא מַחֲשָׁבָה בְּכָל מָקוֹם. וְאֵלּוּ צְרִיכִין מַחֲשָׁבָה וְהֶכְשֵׁר. בָּשָׂר הַפּוֹרֵשׁ מִן הַחַי בֵּין מִן הָאָדָם בֵּין מִן הַבְּהֵמָה בֵּין מִן הָעוֹף וְנִבְלַת הָעוֹף הַטָּמֵא וְחֵלֶב בְּהֵמָה טְהוֹרָה שְׁחוּטָה בַּכְּפָרִים אַף עַל פִּי שֶׁהֻכְשַׁר בִּשְׁחִיטָה צָרִיךְ הֶכְשֵׁר שֵׁנִי אַחַר הַמַּחְשָׁבָה. וּשְׁאָר כָּל יַרְקוֹת הַשָּׂדֶה כְּגוֹן הַבְּצָלִים הַקָּשִׁים בְּיוֹתֵר וְהַפִּטְרִיּוֹת וְכֵן חֲגָבִים וְדָגִים קְטַנִּים צְרִיכִין מַחֲשָׁבָה בַּכְּפָרִים. עֻלְשִׁין שֶׁזְּרָעָן לִבְהֵמָה וְנִמְלַךְ עֲלֵיהֶן לְאָדָם אֵינָן מְקַבְּלִין טֻמְאָה עַד שֶׁיַּחְשֹׁב עֲלֵיהֶן אַחַר שֶׁיִּתָּלְשׁוּ שֶׁמַּחְשֶׁבֶת חִבּוּר אֵינָהּ מַחֲשָׁבָה. עֵלְשִׁין שֶׁלִּקְּטָן לִבְהֶמְתּוֹ וֶהֱדִיחָן וְנִמְלַךְ עֲלֵיהֶן לְאָדָם צְרִיכִין הֶכְשֵׁר שֵׁנִי אַחַר הַמַּחְשָׁבָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. הָאָלָל אִם חָשַׁב עָלָיו לַאֲכִילָה מְקַבֵּל טֻמְאַת אֳכָלִין. וְאִם לָאו הֲרֵי הוּא כְּעֵץ וְאֵינוֹ מְקַבֵּל טֻמְאָה. וְכֵן הָעֲצָמוֹת הַמְחֻבָּרִין בַּבָּשָׂר וְהַגִּידִים וְהַמְּקוֹמוֹת הָרַכִּים מִן הַקַּרְנַיִם וּמִן הַטְּלָפַיִם וְהַכְּנָפַיִם וְהַנּוֹצָה וְהַמְּקוֹמוֹת הָרַכִּים מִן הַצִּפָּרְנַיִם וּמִן הַחַרְטֹם הַמֻּבְלָעִין בַּבָּשָׂר צְרִיכִין הֶכְשֵׁר וּמַחְשָׁבָה. וְאֵלּוּ שֶׁאֵין צְרִיכִין לֹא מַחֲשָׁבָה וְלֹא הֶכְשֵׁר. נִבְלַת בְּהֵמָה טְהוֹרָה בְּכָל מָקוֹם וְנִבְלַת הָעוֹף הַטָּהוֹר וְחֵלֶב בְּהֵמָה טְהוֹרָה בַּכְּרַכִּים לְפִי שֶׁהֵן מְיֻחָדִין לְמַאֲכַל אָדָם אֵין אֶחָד מֵאֵלּוּ צָרִיךְ מַחֲשָׁבָה וְאֵינָן צְרִיכִין הֶכְשֵׁר מִפְּנֵי שֶׁסּוֹפָן לְטַמֵּא אָדָם וְכֵלִים בִּכְזַיִת וְכָל הַמְטַמֵּא טֻמְאָה חֲמוּרָה אֵינוֹ צָרִיךְ הֶכְשֵׁר. וְאֵלּוּ צְרִיכִים מַחֲשָׁבָה וְאֵינָן צְרִיכִין הֶכְשֵׁר. נִבְלַת הָעוֹף הַטָּהוֹר בַּכְּפָרִים וְנִבְלַת בְּהֵמָה טְמֵאָה בְּכָל מָקוֹם וְהוּא שֶׁחָשַׁב עַל פָּחוֹת מִכְּזַיִת אֲבָל כְּזַיִת אַב טֻמְאָה הוּא:","יִשְׂרָאֵל שֶׁשָּׁחַט בְּהֵמָה טְמֵאָה לְנָכְרִי וְשָׁחַט בָּהּ שְׁנַיִם [אוֹ רֹב שְׁנַיִם] הֲרֵי זוֹ מִתְטַמְּאָה טֻמְאַת אֳכָלִין כָּל זְמַן שֶׁהִיא מְפַרְכֶּסֶת וְאֵין צְרִיכָה מַחֲשָׁבָה שֶׁהֲרֵי יִשְׂרָאֵל שְׁחָטָהּ לַאֲכִילַת הָעַכּוּ\"ם וְאֵין לְךָ מַחֲשָׁבָה גְּדוֹלָה מִזּוֹ וְאֵינָהּ צְרִיכָה הֶכְשֵׁר לְפִי שֶׁסּוֹפָהּ לְטַמֵּא טֻמְאָה חֲמוּרָה. שָׁחַט בָּהּ אֶחָד אוֹ שֶׁנְּחָרָהּ אֵינָהּ מְטַמְּאָה טֻמְאַת אֳכָלִין. וְכֵן עַכּוּ\"ם שֶׁשָּׁחַט בְּהֵמָה טְהוֹרָה לְיִשְׂרָאֵל וְשָׁחַט בָּהּ שְׁנַיִם אוֹ רֹב שְׁנַיִם מִתְטַמֵּא טֻמְאַת אֳכָלִין כָּל זְמַן שֶׁהִיא מְפַרְכֶּסֶת וְאֵינָהּ צְרִיכָה הֶכְשֵׁר. שָׁחַט בָּהּ אֶחָד אוֹ נְחָרָהּ אֵינָהּ מִטַּמְּאָה טֻמְאַת אֳכָלִין וַהֲרֵי הִיא כִּשְׁאָר הַנְּבֵלוֹת:","הַחוֹתֵךְ בָּשָׂר מֵאֵיבָר מִן הַחַי שֶׁל בְּהֵמָה וְאַחַר כָּךְ חִשֵּׁב עָלָיו צָרִיךְ הֶכְשֵׁר. חִשֵּׁב עָלָיו וְאַחַר כָּךְ חֲתָכוֹ אֵינוֹ צָרִיךְ הֶכְשֵׁר מִפְּנֵי שֶׁמְּטַמֵּא טֻמְאָה חֲמוּרָה כִּנְבֵלָה וְכָל הַמְטַמֵּא טֻמְאָה חֲמוּרָה אֵינוֹ צָרִיךְ הֶכְשֵׁר:","פָּחוֹת מִכְּזַיִת מִנִּבְלַת בְּהֵמָה טְמֵאָה שֶׁחִשֵּׁב עָלָיו וְהִשְׁלִים עָלָיו כְּבֵיצָה מֵאֳכָלִים אֲחֵרִים אֵין הַכּל צָרִיךְ הֶכְשֵׁר הוֹאִיל וּפָחוֹת מִכְּזַיִת שֶׁבְּכָל הַבֵּיצָה אִם הִשְׁלִימוֹ לִכְזַיִת מְטַמֵּא טֻמְאָה חֲמוּרָה. וְכֵן כְּזַיִת מִנִּבְלַת בְּהֵמָה טְמֵאָה שֶׁחִשֵּׁב עָלָיו וְהִנִּיחָהּ בַּבָּצֵק עַד שֶׁהִשְׁלִים לִכְבֵיצָה הוֹאִיל וְאֵינוֹ מְטַמֵּא בְּמַגָּע מִפְּנֵי הַבָּצֵק הֲרֵי זֶה צָרִיךְ מַחֲשָׁבָה וְאֵין הַבָּצֵק הַזֶּה צָרִיךְ הֶכְשֵׁר הוֹאִיל וְכָל הַשִּׁעוּר הַזֶּה מְטַמֵּא בְּמַשָּׂא מִפְּנֵי כְּזַיִת נְבֵלָה שֶׁבְּתוֹכוֹ אַף עַל פִּי שֶׁאֵינוֹ מְטַמֵּא בְּמַגָּע הֲרֵי סוֹפוֹ לְטַמֵּא טֻמְאָה חֲמוּרָה לְפִיכָךְ אֵין צָרִיךְ הֶכְשֵׁר:","פָּחוֹת מִכְּזַיִת מִבְּשַׂר הַמֵּת שֶׁהִשְׁלִים עָלָיו כְּבֵיצָה מִשְּׁאָר אֳכָלִין הַכּל צָרִיךְ מַחֲשָׁבָה שֶׁהֲרֵי בָּטֵל הַכּל אֵצֶל כָּל אָדָם. וְאֵין הַכּל צָרִיךְ הֶכְשֵׁר מִפְּנֵי בְּשַׂר הַמֵּת שֶׁבִּכְלָלוֹ:","כְּזַיִת מִן הַמֵּת שֶׁחִפָּהוּ בְּבָצֵק הַכּל מִתְטַמֵּא טֻמְאָה חֲמוּרָה:","הַחוֹתֵךְ בָּשָׂר מֵאָדָם חַי לְהַאֲכִילוֹ לְכֶלֶב. אִם חִשֵּׁב עָלָיו לְמַאֲכַל אָדָם הֲרֵי זֶה צָרִיךְ מַחֲשָׁבָה וְאֵינוֹ צָרִיךְ הֶכְשֵׁר:","גּוֹזָל שֶׁנָּפַל לַגַּת וּמֵת אַף עַל פִּי שֶׁהַגַּת בַּמְּדִינָה הֲרֵי נִמְאַס בַּגַּת וּלְפִיכָךְ צָרִיךְ מַחֲשָׁבָה. חִשֵּׁב עָלָיו כְּשֶׁהֶעֱלָהוּ לְהַאֲכִילוֹ לְנָכְרִי הֲרֵי זֶה מִטַּמֵּא שֶׁהֲרֵי חִשֵּׁב עָלָיו לְמַאֲכַל אָדָם. חִשֵּׁב עָלָיו לְהַאֲכִילוֹ לְכֶלֶב אֵינוֹ מִתְטַמֵּא טֻמְאַת אֳכָלִים. הָיָה זֶה שֶׁחִשֵּׁב עָלָיו לְהַאֲכִילוֹ לְאָדָם חֵרֵשׁ שׁוֹטֶה וְקָטָן הֲרֵי זֶה טָהוֹר. הֶעֱלוּהוּ כְּדֵי לְהַאֲכִילוֹ לְאָדָם הֲרֵי זֶה טָמֵא שֶׁיֵּשׁ לָהֶן מַעֲשֶׂה וְאֵין לָהֶן מַחֲשָׁבָה:"],"Mishneh Torah, Diverse Species 5":["הַזּוֹרֵעַ שְׁנֵי מִינֵי תְּבוּאָה אוֹ שְׁנֵי מִינֵי יְרָקוֹת עִם זֶרַע הַכֶּרֶם הֲרֵי זֶה לוֹקֶה שְׁתַּיִם. אַחַת מִשּׁוּם (ויקרא יט יט) \"שָׂדְךָ לֹא תִזְרַע כִּלְאָיִם\" וְאַחַת מִשּׁוּם (דברים כב ט) \"לֹא תִזְרַע כַּרְמְךָ כִּלְאָיִם\":","וְאֵינוֹ לוֹקֶה מִשּׁוּם זוֹרֵעַ כִּלְאֵי הַכֶּרֶם עַד שֶׁיִּזְרַע בְּאֶרֶץ יִשְׂרָאֵל חִטָּה וּשְׂעוֹרָה וְחַרְצָן בְּמַפּלֶת יָד. וְכֵן אִם חִפָּה אוֹתָם בְּעָפָר לוֹקֶה. וְכֵן אִם זָרַע שְׁנֵי מִינֵי יָרָק וְחַרְצָן אוֹ זֶרַע אֶחָד יָרָק וְזֶרַע אֶחָד מִין תְּבוּאָה וְחַרְצָן בְּמַפּלֶת יָד הֲרֵי זֶה לוֹקֶה:","וְאֵינוֹ חַיָּב מִן הַתּוֹרָה אֶלָּא עַל קַנְבּוֹס וְלוּף וְכַיּוֹצֵא בָּהֶן מִזְּרָעִים שֶׁנִּגְמָרִים עִם תְּבוּאַת הַכֶּרֶם אֲבָל שְׁאָר הַזְּרָעִים אֲסוּרִים מִדִּבְרֵיהֶם. וְכֵן אָסוּר מִדִּבְרֵיהֶם לִזְרֹעַ כִּלְאֵי הַכֶּרֶם בְּחוּצָה לָאָרֶץ:","וְלָמָּה אָסְרוּ כִּלְאֵי הַכֶּרֶם [בְּחוּצָה לָאָרֶץ וְלֹא אָסְרוּ כִּלְאֵי זְרָעִים] מִפְּנֵי שֶׁכִּלְאֵי הַכֶּרֶם חֲמוּרִין הֵם שֶׁאִם נִזְרְעוּ בְּאֶרֶץ יִשְׂרָאֵל הֲרֵי הֵן אֲסוּרִין בַּהֲנָאָה וְכֵיוָן שֶׁהֵן אֲסוּרִין בַּהֲנָאָה בָּאָרֶץ אָסְרוּ לְזָרְעָן בְּחוּצָה לָאָרֶץ:","וְאֵין עוֹדְרִין עִם הַנָּכְרִי בְּכִלְאַיִם אֲבָל עוֹקְרִין עִמּוֹ כְּדֵי לְמַעֵט הַתִּפְלָה:","אֵין אָסוּר מִשּׁוּם כִּלְאֵי הַכֶּרֶם אֶלָּא מִינֵי תְּבוּאָה וּמִינֵי יְרָקוֹת בִּלְבַד. אֲבָל שְׁאָר מִינֵי זְרָעִים מֻתָּר לְזָרְעָם בְּכֶרֶם וְאֵין צָרִיךְ לוֹמַר שְׁאָר אִילָנוֹת:","אָסוּר לִזְרֹעַ יְרָקוֹת אוֹ תְּבוּאָה בְּצַד הַגְּפָנִים אוֹ לִטַּע גֶּפֶן בְּצַד הַיָּרָק אוֹ תְּבוּאָה. וְאִם עָשָׂה כֵּן אַף עַל פִּי שֶׁאֵינוֹ לוֹקֶה הֲרֵי זֶה קִדֵּשׁ וְנֶאֶסְרוּ שְׁנֵיהֶם בַּהֲנָאָה הַיָּרָק אוֹ הַתְּבוּאָה אוֹ הַגְּפָנִים. וְשׂוֹרְפִין אֶת שְׁנֵיהֶן שֶׁנֶּאֱמַר (דברים כב ט) \"פֶּן תִּקְדַּשׁ הַמְלֵאָה הַזֶּרַע\". וַאֲפִלּוּ הַקַּשׁ שֶׁל תְּבוּאָה וְהָעֵצִים שֶׁל גְּפָנִים הָאֵלּוּ אֲסוּרִין בַּהֲנָאָה וְשׂוֹרְפִין אוֹתָם וְלֹא יַסִּיק בָּהֶן תַּנּוּר וְכִירַיִם וְלֹא יְבַשֵּׁל בָּהֶם בְּעֵת שְׂרֵפָתָן:","אֶחָד הַנּוֹטֵעַ וְאֶחָד הַמְקַיֵּם כֵּיוָן שֶׁרָאָה כִּלְאַיִם צָמְחוּ בְּכַרְמוֹ וְהִנִּיחָם הֲרֵי זֶה קִדֵּשׁ. וְאֵין אָדָם מְקַדֵּשׁ דָּבָר שֶׁאֵינוֹ שֶׁלּוֹ. לְפִיכָךְ הַמְסַכֵּךְ גַּפְנוֹ עַל גַּבֵּי תְּבוּאָתוֹ שֶׁל חֲבֵרוֹ קִדֵּשׁ גַּפְנוֹ וְלֹא נִתְקַדְּשָׁה הַתְּבוּאָה. סִכֵּךְ גֶּפֶן חֲבֵרוֹ עַל תְּבוּאָתוֹ קִדֵּשׁ תְּבוּאָה וְלֹא קִדֵּשׁ גֶּפֶן חֲבֵרוֹ. סִכֵּךְ גֶּפֶן חֲבֵרוֹ עַל תְּבוּאַת חֲבֵרוֹ לֹא קִדֵּשׁ אֶחָד מֵהֶן. וּמִפְּנֵי זֶה הַזּוֹרֵעַ כַּרְמוֹ בַּשְּׁבִיעִית לֹא קִדֵּשׁ:","הָרוֹאֶה כִּלְאַיִם בְּכֶרֶם חֲבֵרוֹ וְקִיְּמָן הֲרֵי זֶה הָרוֹאֶה אָסוּר בַּהֲנָיָתָן וְכָל אָדָם מֻתָּרִין בָּהֶן. וְאִלּוּ קִיְּמָן בַּעַל הַכֶּרֶם הָיָה מְקַדֵּשׁ אוֹתָן לְכָל אָדָם כְּמוֹ שֶׁבֵּאַרְנוּ:","הָאַנָּס שֶׁזָּרַע כִּלְאַיִם בְּכֶרֶם חֲבֵרוֹ אִם נִשְׁתַּקְּעוּ הַבְּעָלִים אַף עַל פִּי שֶׁלֹּא נִתְיָאֲשׁוּ הֲרֵי זֶה קִדֵּשׁ מִן הַתּוֹרָה. וְאִם לֹא נִשְׁתַּקְּעוּ הַבְּעָלִים אַף עַל פִּי שֶׁנִּתְיָאֲשׁוּ אֵינוֹ מְקַדֵּשׁ אֶלָּא מִדִּבְרֵי סוֹפְרִים:","הָרוּחַ שֶׁעָקְרָה פְּאֵרוֹת הַגֶּפֶן וְשִׁלְּחָה אוֹתָן עַל הַתְּבוּאָה יִגְדֹּד אוֹתָן מִיָּד. וְאִם אֵרְעוֹ אֹנֶס וְלֹא סִלְּקָן הֲרֵי אֵלּוּ מֻתָּרִין וְלֹא נִתְקַדְּשׁוּ:","אַנָּס שֶׁזָּרַע הַכֶּרֶם כְּשֶׁיָּצָא הָאַנָּס יִקְצֹר הַזֶּרַע מִיָּד וַאֲפִלּוּ בְּחֻלּוֹ שֶׁל מוֹעֵד. וְאִם לֹא מָצָא פּוֹעֲלִין יוֹסִיף לָהֶן עַד שְׁלִישׁ בִּשְׂכָרָן. בִּקְּשׁוּ מִמֶּנּוּ יוֹתֵר מִכֵּן אוֹ שֶׁלֹּא מָצָא פּוֹעֲלִים הֲרֵי זֶה מְבַקֵּשׁ בְּנַחַת וְקוֹצֵר. וְאִם נִשְׁתַּהָא הַזֶּרַע עַד שֶׁהִגִּיעַ לְעוֹנַת שֶׁיִּקְדַּשׁ הֲרֵי זֶה יִקְדַּשׁ וְיֵאָסְרוּ שְׁנֵיהֶם:","מֵאֵימָתַי תְּבוּאָה אוֹ יָרָק מִתְקַדְּשִׁין מִשֶּׁיַּשְׁרִישׁוּ. עֲנָבִים מִשֶּׁיֵּעָשׂוּ כְּפוֹל הַלָּבָן. שֶׁנֶּאֱמַר (דברים כב ט) \"הַמְלֵאָה הַזֶּרַע אֲשֶׁר תִּזְרָע וּתְבוּאַת הַכָּרֶם\" עַד שֶׁיִּזְרַע זֶה וְיִהְיֶה זֶה תְּבוּאָה. אֲבָל תְּבוּאָה שֶׁיָּבְשָׁה כָּל צָרְכָּהּ וַעֲנָבִים שֶׁבָּשְׁלוּ כָּל צָרְכָּן אֵינָן מִתְקַדְּשׁוֹת. [כֵּיצַד. תְּבוּאָה שֶׁיָּבְשָׁה כָּל צָרְכָּהּ וּבָא וְנָטַע גֶּפֶן בְּתוֹכָהּ וְכֵן עֲנָבִים שֶׁבָּשְׁלוּ כָּל צָרְכָּן וְזָרַע תְּבוּאָה אוֹ יָרָק בְּצִדָּן אַף עַל פִּי שֶׁזֶּה אָסוּר אֵינָן מִתְקַדְּשׁוֹת]:","כֶּרֶם שֶׁלֹּא הִגִּיעוּ עֲנָבָיו לִהְיוֹת כְּפוֹל הַלָּבָן אֶלָּא עֲדַיִן הֵן בֹּסֶר וְזָרַע בְּתוֹכוֹ יָרָק אוֹ תְּבוּאָה וְהִשְׁרִישׁוּ הֲרֵי זֶה לֹא קִדֵּשׁ. וְאַף עַל פִּי כֵן קוֹנְסִין אוֹתוֹ וְאוֹסְרִין הַזֶּרַע. אֲבָל הַבֹּסֶר מֻתָּר וְאִם עָקַר הַזֶּרַע קֹדֶם שֶׁיֵּעָשׂוּ הָעֲנָבִים כְּפוֹל הַלָּבָן הֲרֵי זֶה מֻתָּר בַּהֲנָיָה. מִקְצָתָן נַעֲשׂוּ כְּפוֹל הַלָּבָן וּמִקְצָתָן לֹא נַעֲשׂוּ. אֶת שֶׁנַּעֲשׂוּ נִתְקַדְּשׁוּ וְאֶת שֶׁלֹּא נַעֲשׂוּ מֻתָּרִין:","עֲנָבִים שֶׁנַּעֲשׂוּ כְּפוֹל הַלָּבָן וְזָרַע בְּצִדָּן תְּבוּאָה אוֹ מִינֵי יְרָקוֹת וְלָקַט הַזֶּרַע קֹדֶם שֶׁיַּשְׁרִישׁ הֲרֵי זֶה מֻתָּר בַּהֲנָאָה וְאִם הִשְׁרִישׁ אָסוּר:","גֶּפֶן שֶׁיָּבְשׁוּ הֶעָלִין שֶׁלָּהּ וְנָפְלוּ כְּדֶרֶךְ שֶׁתִּיבַשׁ הַגֶּפֶן בִּימֵי הַקֹּר אָסוּר לִזְרֹעַ בְּצִדָּהּ יָרָק אוֹ תְּבוּאָה וְאִם זָרַע לֹא קָדְשׁוּ. וְכֵן הַזּוֹרֵעַ בְּעָצִיץ שֶׁאֵינוֹ נָקוּב הַמֻּנָּח בַּכֶּרֶם לֹא קִדֵּשׁ וּמַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. אֲבָל עָצִיץ נָקוּב הֲרֵי הוּא כְּאֶרֶץ:","הָיָה עוֹבֵר בַּכֶּרֶם וְנָפְלוּ מִמֶּנּוּ זְרָעִים אוֹ שֶׁיָּצְאוּ עִם הַזְּבָלִים אוֹ עִם הַמַּיִם אוֹ שֶׁהָיָה זוֹרֵעַ אוֹ זוֹרֶה בְּשָׂדֶה לָבָן וּסְעָרַתּוּ הָרוּחַ לַאֲחוֹרָיו וְנָפְלוּ הַזְּרָעִים בַּכֶּרֶם וְצָמְחוּ הֲרֵי זֶה לֹא נִתְקַדֵּשׁ שֶׁנֶּאֱמַר (דברים כב ט) \"אֲשֶׁר תִזְרַע\" וְזֶה לֹא זָרַע. וְחַיָּב לַעֲקֹר כְּשֶׁיִּרְאֶה. וְאִם קִיְּמָן הֲרֵי זֶה קִדֵּשׁ. סְעָרַתּוּ הָרוּחַ לְפָנָיו וְרוֹאֶה הַזְּרָעִים שֶׁנָּפְלוּ לַכֶּרֶם הֲרֵי זֶה כְּזוֹרֵעַ. וְכֵיצַד יַעֲשֶׂה. אִם צָמְחוּ הָעֲשָׂבִים יַהַפְכֵם בְּמַחְרֵשָׁה וְדַיּוֹ. וְאִם מְצָאָן שֶׁנַּעֲשׂוּ אָבִיב יְנַפֵּץ אוֹתוֹ אָבִיב כְּדֵי לְהַשְׁחִיתוֹ שֶׁהַכּל אָסוּר בַּהֲנָאָה. וְאִם מְצָאָהּ שֶׁנַּעֲשֵׂית דָּגָן הֲרֵי זוֹ תִּשָּׂרֵף. וְאִם רָאָה אוֹתָן וְקִיְּמָן הֲרֵי אֵלּוּ יִשָּׂרְפוּ עִם הַגְּפָנִים הַסְּמוּכוֹת לָהֶן:","הָרוֹאֶה בַּכֶּרֶם עֵשֶׂב שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לְזָרְעוֹ אַף עַל פִּי שֶׁהוּא רוֹצֶה בְּקִיּוּמוֹ לִבְהֵמָה אוֹ לִרְפוּאָה הֲרֵי זֶה לֹא קִדֵּשׁ. עַד שֶׁיְּקַיֵּם דָּבָר שֶׁכָּמוֹהוּ מְקַיְּמִין רֹב הָעָם בְּאוֹתוֹ מָקוֹם. כֵּיצַד. הַמְקַיֵּם קוֹצִים בַּכֶּרֶם בַּעֲרָב שֶׁרוֹצִים בַּקּוֹצִים לִגְמַלֵּיהֶם הֲרֵי זֶה קִדֵּשׁ:","הָאִרוּס וְהַקִּיסוֹס וְשׁוֹשַׁנַּת הַמֶּלֶךְ וּשְׁאָר מִינֵי זְרָעִים אֵינָן כִּלְאַיִם בַּכֶּרֶם. הַקַּנְבּוֹס וְהַקִּנְרָס וְצֶמֶר גֶּפֶן הֲרֵי הֵן כִּשְׁאָר מִינֵי יְרָקוֹת וּמְקַדְּשִׁים בַּכֶּרֶם. וְכֵן כָּל מִינֵי דְּשָׁאִים שֶׁעוֹלִין מֵאֲלֵיהֶן בַּשָּׂדֶה הֲרֵי הֵן מְקַדְּשִׁין בַּכֶּרֶם. וּפוֹל הַמִּצְרִי מִין זְרָעִים הוּא וְאֵינוֹ מְקַדֵּשׁ. הַקָּנִים וְהַוֶּרֶד וְהָאַטָּדִין מִינֵי אִילָן הֵן וְאֵינָן כִּלְאַיִם בַּכֶּרֶם:","זֶה הַכְּלָל כָּל הַמּוֹצִיא עָלִין מֵעִקָּרוֹ הֲרֵי זֶה יָרָק וְכָל שֶׁאֵינוֹ מוֹצִיא עָלִין הֲרֵי זֶה אִילָן. וְהַצָּלָף אִילָן לְכָל דָּבָר:","הָרוֹאֶה יָרָק בַּכֶּרֶם וְאָמַר כְּשֶׁאַגִּיעַ לוֹ אֶלְקְטֵנוּ מֻתָּר. הִגִּיעַ לוֹ וְעָבַר מֵעָלָיו וְאָמַר כְּשֶׁאֶחֱזֹר לוֹ אֶלְקְטֵנוּ אִם שָׁהָה עַד שֶׁהוֹסִיף אֶחָד מִמָּאתַיִם הֲרֵי זֶה קִדֵּשׁ:","וְכֵיצַד מְשַׁעֲרִין שִׁעוּר זֶה. רוֹאִין אִם נֶחְתַּךְ יָרָק זֶה אוֹ מִין תְּבוּאָה זֶה מִן הָאָרֶץ בְּכַמָּה זְמַן יִיבַשׁ. הַגַּע בְּעַצְמְךָ שֶׁיִּיבַשׁ עַד שֶׁלֹּא תִּשָּׁאֵר בּוֹ לֵחָה בְּמֵאָה שָׁעָה. אִם נִשְׁתַּהָה בָּאָרֶץ מִשֶּׁהִגִּיעַ לוֹ חֲצִי שָׁעָה הֲרֵי הוֹסִיף בְּמָאתַיִם לֶאֱסוֹר. וְאִם שָׁהָה פָּחוֹת מֵחֲצִי שָׁעָה מֻתָּר:","אָסוּר לַעֲבֹר בְּעָצִיץ נָקוּב שֶׁזָּרוּעַ בּוֹ יָרָק בְּתוֹךְ הַכֶּרֶם. וְאִם הִנִּיחוֹ תַּחַת הַגֶּפֶן וְנִשְׁתַּהָה שָׁם בָּאָרֶץ כְּדֵי לְהוֹסִיף אֶחָד מִמָּאתַיִם הֲרֵי זֶה קִדֵּשׁ:","בָּצָל שֶׁנְּטָעוֹ בַּכֶּרֶם וְאַחַר כָּךְ נֶעֱקַר הַכֶּרֶם וְאַחַר כָּךְ צָמְחוּ בְּצָלִים מִן הָעִקָּר הַנָּטוּעַ אַף עַל פִּי שֶׁרַבּוּ הַגִּדּוּלִים עַל עִקָּרוֹ בְּמָאתַיִם הֲרֵי אוֹתוֹ הָעִקָּר בְּאִסּוּרוֹ שֶׁאֵין גִּדּוּלֵי הֶתֵּר מַעֲלִין אֶת הָעִקָּר הָאָסוּר:"],"Mishneh Torah, Divorce 4":["אֵין כּוֹתְבִין אֶת הַגֵּט אֶלָּא בְּדָבָר שֶׁרִשּׁוּמוֹ עוֹמֵד כְּגוֹן דְּיוֹ וְסִקְרָא וְקוֹמוֹס וְקַנְקַנְתּוֹם וְכַיּוֹצֵא בָּהֶן. אֲבָל אִם כְּתָבוֹ בְּדָבָר שֶׁאֵינוֹ עוֹמֵד כְּגוֹן מַשְׁקִין וּמֵי פֵּרוֹת וְכַיּוֹצֵא בָּהֶן אֵינוֹ גֵּט. כְּתָבוֹ בַּאֲבַר בְּשָׁחוֹר וּבְשִׁיחוֹר כָּשֵׁר. וְאֵין כּוֹתְבִין בָּהֶן לְכַתְּחִלָּה:","כּוֹתְבִין בְּמֵי עַפְּצָא לְכַתְּחִלָּה עַל גַּב הַנְּיָר וְהָעוֹר וְכַיּוֹצֵא בָּהֶן אֲבָל לֹא עַל גַּבֵּי מְגִלָּה עֲפוּצָה מִפְּנֵי שֶׁאֵינוֹ נִכָּר. וְאִם כָּתַב אֵינוֹ גֵּט. וְכֵן כָּל כַּיּוֹצֵא בּוֹ. עַל הַכּל כּוֹתְבִין אֶת הַגֵּט וַאֲפִלּוּ עַל אִסּוּרֵי הֲנָאָה. וְכוֹתְבִין עַל דָּבָר שֶׁיָּכוֹל לְהִזְדַּיֵּף וְהוּא שֶׁיִּתְּנוֹ לָהּ בְּעֵדֵי מְסִירָה:","כֵּיצַד כּוֹתֵב (אוֹתוֹ). עַל הַנְּיָר הַמָּחוּק וְעַל הַדִּפְתְּרָא וְעַל הַחֶרֶס וְעַל הֶעָלִין וְעַל יָדוֹ שֶׁל עֶבֶד וְעַל קֶרֶן שֶׁל פָּרָה. וּמוֹסֵר לָהּ הָעֶבֶד וְהַפָּרָה אוֹ הַנְּיָר הַמָּחוּק וְהַדִּפְתְּרָא וְכַיּוֹצֵא בּוֹ בִּפְנֵי עֵדִים:","הָיָה הַגֵּט חָקוּק עַל יָדוֹ שֶׁל עֶבֶד בִּכְתֹבֶת קַעֲקַע וְהָיָה יוֹצֵא מִתַּחַת יָדָהּ וְהָיוּ הָעֵדִים חֲקוּקִים עַל יָדוֹ הֲרֵי זוֹ מְגֹרֶשֶׁת אַף עַל פִּי שֶׁאֵין לָהּ עֵדֵי מְסִירָה. שֶׁהֲרֵי אֵין יָכוֹל לְהִזְדַּיֵּף. אֲפִלּוּ הָיוּ מֻחְזָקִין בְּעֶבֶד שֶׁהוּא שֶׁלּוֹ וְגֵט חָקוּק עַל יָדוֹ וְהוּא יוֹצֵא מִתַּחַת יָדָהּ וְהִיא אוֹמֶרֶת בְּעֵדִים נִמְסַר לִי הֲרֵי זוֹ סָפֵק מְגֹרֶשֶׁת שֶׁמָּא מֵעַצְמוֹ נִכְנַס לָהּ שֶׁהַגּוֹדְרוֹת אֵין לָהֶן חֲזָקָה:","הָיָה הַגֵּט חָקוּק עַל הַטַּבְלָא וְהָעֵדִים עָלָיו וְהוּא יוֹצֵא מִתַּחַת יָדָהּ אַף עַל פִּי שֶׁהֵן מֻחְזָקִין בְּטַבְלָא שֶׁהוּא שֶׁלָּהּ הֲרֵי זוֹ מְגֹרֶשֶׁת, שֶׁהָאִשָּׁה עַצְמָהּ כּוֹתֶבֶת אֶת גִּטָּהּ. שֶׁאֵין קִיּוּם הַגֵּט אֶלָּא בְּחוֹתְמָיו אִם אֵין שָׁם עֵדֵי מְסִירָה:","חָקַק הַגֵּט עַל הַלּוּחַ אוֹ עַל הָאֶבֶן אוֹ עַל טַס שֶׁל מַתֶּכֶת אִם חָפַר יַרְכֵי הָאוֹתִיּוֹת כָּשֵׁר. שֶׁזֶּה כְּתָב הוּא. הֲרֵי הוּא אוֹמֵר (ירמיה יז א) \"כְּתוּבָה בְּעֵט בַּרְזֶל\" כְּלוֹמַר שֶׁהוּא חֲפָרוֹ. וְכֵן אִם חָקַק הַיְרֵכוֹת מֵאֲחוֹרֵי הַטַּס עַד שֶׁבָּלְטוּ בִּפְנֵי הַטַּס. אֲבָל אִם חָפַר תּוֹךְ הָאוֹת עַד שֶׁיֵּרָאוּ הַיְרֵכוֹת גְּבוֹהוֹת מִכָּאן וּמִכָּאן כִּכְתַב דִּינַר זָהָב שֶׁהַכְּתָב בּוֹלֵט אֵינוֹ גֵּט שֶׁאֵין זֶה כְּתָב:","הַמְקָרֵעַ עַל הָעוֹר תַּבְנִית כְּתָב אוֹ שֶׁרָשַׁם עַל הָעוֹר תַּבְנִית כְּתָב הֲרֵי זֶה כָּשֵׁר. כּוֹתְבִין אֶת הַגֵּט בְּכָל כְּתָב וּבְכָל לָשׁוֹן. גֵּט שֶׁנִּכְתַּב בִּכְתָב מִן הַלְּשׁוֹנוֹת וְעֵדָיו חֲתוּמִין בִּכְתָב אַחֵר כָּשֵׁר. וְהוּא שֶׁיְּהוּ הָעֵדִים מַכִּירִין לְשׁוֹן הַכְּתָב וְהַכְּתִיבָה","אֶחָד מִן הָעֵדִים חָתַם בִּכְתָב (לָשׁוֹן אַחַת) וְהָעֵד הַשֵּׁנִי בִּכְתַב לָשׁוֹן אַחֶרֶת כָּשֵׁר. אֲבָל אִם הָיָה מִקְצָת הַגֵּט כָּתוּב בְּלָשׁוֹן אַחַת וּמִקְצָתוֹ בְּלָשׁוֹן אַחֶרֶת פָּסוּל:","כָּל לָשׁוֹן שֶׁיִּכָּתֵב בָּהּ הַגֵּט צָרִיךְ שֶׁיִּזָהֵר הַסּוֹפֵר בְּדִבְרֵי הַגֵּט שֶׁלֹּא יְהֵא מַשְׁמָעָן שְׁנֵי עִנְיָנִים עַד שֶׁנִּמְצָא הַקּוֹרֵא אוֹמֵר שֶׁמָּא לְכָךְ וּלְכָךְ נִתְכַּוֵּן שֶׁאֵין מַשְׁמָעוֹ לְשׁוֹן גֵּרוּשִׁין אוֹ שֶׁמָּא לְעִנְיָן זֶה נִתְכַּוֵּן שֶׁמַּשְׁמָעוֹ לְשׁוֹן גֵּרוּשִׁין. אֶלָּא יִהְיוּ הַדְּבָרִים שֶׁאֵין בָּהֶן סָפֵק בְּאוֹתוֹ הַלָּשׁוֹן אֶלָּא מַשְׁמָעָן עִנְיָן אֶחָד שֶׁגֵּרֵשׁ וְשָׁלַח פְּלוֹנִי אֶת פְּלוֹנִית:","וְכֵן צָרִיךְ שֶׁיִּהְיֶה אוֹתוֹ הַכְּתָב מְבֹאָר הֵיטֵב בְּאוֹתוֹ הַכְּתָב שֶׁיִּכְתֹּב בּוֹ עַד שֶׁיֵּדְעוּ הַקְּטַנִּים לִקְרוֹתוֹ שֶׁמַּכִּירִים אוֹתוֹ כְּתָב שֶׁאֵינָן לֹא נְבוֹנִים וְלֹא סְכָלִים (וְלֹא בִּקְטַנִּים) אֶלָּא בֵּינוֹנִים. וְלֹא יִהְיֶה כְּתָב מְעֻקָּם וּמְבֻלְבָּל שֶׁמָּא תִּדְמֶה אוֹת לְאוֹת וְנִמְצָא הָעִנְיָן מִשְׁתַּנֶּה:","הָיָה בּוֹ מַשְׁמָעוּת שְׁנֵי עִנְיָנִים אוֹ שֶׁהָיָה בִּכְתָבוֹ עִקּוּם אוֹ בִּלְבּוּל עַד שֶׁאֶפְשָׁר שֶׁיִּקְרָא מִמֶּנּוּ עִנְיָן אַחֵר. הוֹאִיל וְנִקְרָא לְעִנְיַן הַגֵּרוּשִׁין וְיֵשׁ בּוֹ מַשְׁמַע גֵּרוּשִׁין הֲרֵי זֶה פָּסוּל. כְּבָר נָהֲגוּ כָּל עַם יִשְׂרָאֵל לִכְתֹּב הַגֵּט לְשׁוֹן אֲרָמִי וּכְנֹסַח זֶה אַף עַל פִּי שֶׁמֻּתָּר לְכָתְבוֹ בְּכָל לָשׁוֹן לְכַתְּחִלָּה:","וזה הוא נוסח הגטבְּכָךְ בְּשַׁבָּת בְּכָךְ וְכָךְ לְיֶרַח פְּלוֹנִי בִּשְׁנַת כָּךְ וְכָךְ לַיְצִירָה אוֹ לַשְּׁטָרוֹת לְמִנְיָנָא דְּרָגִילְנָא לְמִימְנֵי בָּהּ הָכָא בְּמָקוֹם פְּלוֹנִי אֵיךְ אֲנָא פְּלוֹנִי בַּר פְּלוֹנִי דְּמִמָּקוֹם פְּלוֹנִי וְכָל שׁוּם אָחֳרָן וַחֲנִיכָה דְּאִית לִי וְלַאֲבָהָתִי וּלְאַתְרִי וּלְאַתְרֵיהוֹן דַּאֲבָהָתִי צָבִיתִי בִּרְעוּת נַפְשִׁי בִּדְלָא אֲנִיסְנָא וּפַטְרִית וְשַׁבְקִית וּתְרוּכִית יָתִיכִי לֵיכִי אַנְתְּ פְּלוֹנִית בַּת פְּלוֹנִי דְּמִמָּתָא פְּלוֹנִית וְכָל שׁוּם אָחֳרָן וַחֲנִיכָה דְּאִית לֵיכִי וְלַאֲבָהָתִיכִי וּלְאַתְרִיכִי וּלְאַתְרֵיהוֹן דַּאֲבָהָתִיכִי דִּי הֲוִית אִנְתָּתִי מִן קַדְמַת דְּנָא. וּכְדוֹ פַּטְרִית וְשַׁבְקִית וּתְרוּכִית יָתִיכִי לֵיכִי דְּיִתְהַוְיָין רַשָּׁאָה וְשַׁלְטָאָה בְּנַפְשִׁיכִי לִמְהָךְ לְהִתְנַסְבָּא לְכָל גְּבַר דְּיִתְצַבְיָין וְאִינַשׁ לֹא יִמְחֶה בְּיָדִיכִי (מִן שְׁמִי) מִן יוֹמָא דְּנָן וּלְעָלַם וַהֲרֵי אַתְּ מֻתֶּרֶת לְכָל אָדָם וְדֵן דִּי יֶהֱוֵי לֵיכִי מִנָּאִי סֵפֶר תֵּרוּכִין וְגֵט פִּטּוּרִין וְאִגֶּרֶת שִׁבוּקִין כְּדַת משֶׁה וְיִשְׂרָאֵל. וְהָעֵדִים חוֹתְמִים לְמַטָּה כְּמוֹ שֶׁבֵּאַרְנוּ. פְּלוֹנִי בֶּן פְּלוֹנִי עֵד. פְּלוֹנִי בֶּן פְּלוֹנִי עֵד:","כְּשֶׁיִּכְתֹּב הַגֵּט בַּלָּשׁוֹן הַזֶּה וּבְנֹסַח זֶה לֹא יִכְתֹּב וְדֵין בְּיוּ״‎ד שֶׁמָּא יִקְרָא הַקּוֹרֵא וְדִין כְּלוֹמַר מִשְׁפָּט יִהְיֶה בֵּינִי וּבֵינֵךְ. וְלֹא יִכְתֹּב וְאִגֶּרֶת בְּיוּ״‎ד שֶׁמָּא יִקְרָא הַקּוֹרֵא וְאִי גָרַת כְּלוֹמַר אִם זָנִית. לֹא יִכְתֹּב לִימְהָךְ בְּיוּ״‎ד שֶׁמָּא יִקְרָא הַקּוֹרֵא לִי מֵהַךְ [וְכֵן יַרְחִיק רֶגֶל הַהֵ״‎א מִגַּגָּהּ שֶׁמָּא יִקְרָא לִמְחַךְ] כְּלוֹמַר לִשְׂחוֹק. וְלֹא יִכְתֹּב תֶּהֱוְיָן וְתִצְבְּיָן בִּשְׁתֵּי יוּדִי״‎ן שֶׁמָּא יִקְרָא הַקּוֹרֵא תֶּהֱוְיָין וְתִצְבְּיָין כְּלוֹמַר שֶׁהוּא מְדַבֵּר עִם שְׁתֵּי נָשִׁים וְנִמְצָא שֶׁאֵינוֹ מְגָרֵשׁ לָזוֹ אֶלָּא לִשְׁתַּיִם אֲחֵרוֹת. וְכֵן יַאֲרִיךְ לְוָי״‎ו דְּוּכְדוֹ שֶׁמָּא תִּדְמֶה לְיוּ״‎ד וְיִהְיֶה מַשְׁמָעוֹ וּכְדִי כְּלוֹמַר בִּתְנַאי זֶה אֶפְטֹר אוֹתָךְ. וְכֵן יַאֲרִיךְ לְוָי״‎ו דְּתֵרוּכִין וְשִׁבוּקִין שֶׁמָּא תִּדְמֶה לְיוּ״‎ד וְיִהְיֶה מַשְׁמָע תְּרִיכִין וּשְׁבִיקִין כְּלוֹמַר שֶׁהוּא אוֹמֵר לָהּ שֶׁהִיא שָׁבְקָה וְגֵרְשָׁה אוֹתוֹ. וְעַל דֶּרֶךְ זֶה צָרִיךְ לְהִזָּהֵר בְּכָל לָשׁוֹן וּבְכָל כְּתָב שֶׁיִּכְתֹּב שֶׁלֹּא יִהְיֶה בּוֹ מַשְׁמַע שְׁתֵּי עִנְיָנוֹת:","הֲרֵי שֶׁכָּתַב בְּנֹסַח זֶה וְלֹא הֶאֱרִיךְ וָוִי״‎ן אֵלּוּ אוֹ לֹא כָּתַב הַיּוּדִי״‎ן הַיְתֵרוֹת אוֹ שֶׁכָּתַב הַיּוּדִי״‎ן שֶׁאָמַרְנוּ שֶׁלֹּא יִכָּתְבוּ הֲרֵי זֶה גֵּט פָּסוּל. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה בְּכָל לָשׁוֹן פָּסוּל:","גֵּט שֶׁמָּחַק בּוֹ אוֹת אוֹ תֵּבָה אוֹ שֶׁתָּלָה בֵּין הַשִּׁיטִין. אִם מִטֹּפֶס הַגֵּט הֲרֵי זֶה כָּשֵׁר. וְאִם מִן הַתֹּרֶף אֵינוֹ גֵּט. וְאִם חָזַר וּפֵרֵשׁ בְּסוֹף הַגֵּט שֶׁאוֹת פְּלוֹנִית תְּלוּיָה אוֹ עַל מַחַק אֲפִלּוּ מִתֹּרֶף הַגֵּט כָּשֵׁר כִּשְׁאָר שְׁטָרוֹת. וְכֵן גֵּט שֶׁנִּמְצָא קָרוּעַ שְׁתִי וָעֵרֶב שֶׁהוּא קֶרַע שֶׁל בֵּית דִּין הֲרֵי זֶה גֵּט בָּטֵל כִּשְׁאָר הַשְּׁטָרוֹת. אֲבָל אִם נִקְרַע וְאֵינוֹ קֶרַע שֶׁל בֵּית דִּין כָּשֵׁר:","נִמֹּק אוֹ שֶׁהִרְקִיב אוֹ שֶׁנַּעֲשָׂה כִּכְבָרָה כָּשֵׁר. נִמְחַק אוֹ נִטַּשְׁטֵשׁ וּבָבוּאָה שֶׁלּוֹ קַיֶּמֶת אִם יָכוֹל לִקְרוֹת כָּשֵׁר וְאִם לָאו אֵינוֹ גֵּט:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה הַגֵּט יוֹצֵא מִתַּחַת יָדָהּ בְּעֵדֵי חֲתִימָה וְאֵין שָׁם עֵדֵי מְסִירָה. אֲבָל אִם יֵשׁ שָׁם עֵדִים שֶׁנִּמְסַר לָהּ הַגֵּט בִּפְנֵיהֶם וְהָיָה כָּשֵׁר הֲרֵי זֶה כָּשֵׁר. אַף עַל פִּי שֶׁהָיָה תֹּרֶף הַגֵּט עַל הַמַּחַק אוֹ בֵּין הַשִּׁיטִין אוֹ שֶׁהָיָה קָרוּעַ שְׁתִי וָעֵרֶב כְּשֶׁנָּתַן לָהּ בִּפְנֵיהֶם:","חֲמִשָּׁה שֶׁכָּתְבוּ גֵּט אֶחָד לַחֲמֵשׁ נְשׁוֹתֵיהֶן. אִם כְּתָבוּהוּ בַּכְּלָל כְּגוֹן שֶׁכָּתְבוּ בְּכָךְ בְּשַׁבָּת גֵּרֵשׁ פְּלוֹנִי לִפְלוֹנִית וּפְלוֹנִי לִפְלוֹנִית וְכֵן אָמַר כָּל אֶחָד מֵהֶן לְאִשְׁתּוֹ לֵיכִי דִּי תֶּהֱוְיָן וְכָל טֹפֶס הַגֵּט וּשְׁנֵי עֵדִים חוֹתְמִין מִלְּמַטָּה הֲרֵי זֶה גֵּט כָּשֵׁר וְיִנָּתֵן לְכָל אַחַת מֵהֶן בְּעֵדֵי מְסִירָה. וְאִם אֵין שָׁם עֵדֵי מְסִירָה כְּלָל כָּל מִי שֶׁתֵּצֵא מְגִלָּה זוֹ מִתַּחַת יָדָהּ מְגֹרֶשֶׁת. אֲבָל אִם כָּתַב בְּכָךְ בְּשַׁבָּת גֵּרֵשׁ פְּלוֹנִי לִפְלוֹנִית וְהִשְׁלִים הַגֵּט וְהִתְחִיל תַּחְתָּיו גֵּט אַחֵר בְּאוֹתָהּ מְגִלָּה וְכָתַב וּבְיוֹם זֶה אוֹ בְּכָךְ בְּשַׁבָּת גֵּרֵשׁ פְּלוֹנִי לִפְלוֹנִית וְהִשְׁלִים הַגֵּט הַשֵּׁנִי. וְכֵן עַד שֶׁהִשְׁלִים כָּל הַגִּטִּין וְהָעֵדִים מִלְּמַטָּה. אִם נִתְּנָה מְגִלָּה זוֹ לְכָל אַחַת מֵהֶן בְּעֵדֵי מְסִירָה הֲרֵי כֻּלָּן מְגֹרָשׁוֹת. וְאִם אֵין שָׁם עֵדֵי מְסִירָה וְהָיְתָה מְגִלָּה זוֹ יוֹצְאָה מִתַּחַת יַד אַחַת מֵהֶן. אִם הָיְתָה זוֹ שֶׁגִּטָּהּ בָּאַחֲרוֹנָה שֶׁהָעֵדִים נִקְרָאִין עִמּוֹ הֲרֵי זוֹ מְגֹרֶשֶׁת. וְאִם הָיְתָה הַמְּגִלָּה יוֹצְאָה מִתַּחַת יַד אַחַת מִן הָרִאשׁוֹנוֹת הֲרֵי זוֹ סָפֵק מְגֹרֶשֶׁת:","כָּתַב אָנוּ פְּלוֹנִי וּפְלוֹנִי גֵּרַשְׁנוּ נְשׁוֹתֵינוּ פְּלוֹנִית וּפְלוֹנִית וְהִשְׁלִים הַגֵּט אַף עַל פִּי שֶׁנִּמְסַר לְכָל אַחַת מֵהֶן בְּעֵדֵי מְסִירָה אֵינוֹ גֵּט שֶׁאֵין שְׁתֵּי נָשִׁים מִתְגָּרְשׁוֹת בְּגֵט אֶחָד שֶׁנֶּאֱמַר (דברים כד א) \"וְכָתַב לָהּ\" וְלֹא לָהּ וְלַחֲבֶרְתָּהּ. חָזַר וּפְרָטָן בְּתוֹךְ הַגֵּט וְכָתַב פְּלוֹנִי גֵּרֵשׁ פְּלוֹנִית וּפְלוֹנִי גֵּרֵשׁ פְּלוֹנִית בִּזְמַן פְּלוֹנִי הֲרֵי אֵלּוּ כְּשֵׁרִים:","כָּתַב שְׁנֵי גִּטִּין בִּשְׁנֵי דַּפִּין בִּמְגִלָּה אַחַת זֶה בְּצַד זֶה. אִם יֵשׁ שָׁם שְׁנֵי עֵדִים נִקְרָאִים בְּסוֹף גֵּט זֶה וּשְׁנֵי עֵדִים בְּסוֹף גֵּט זֶה הֲרֵי זֶה כָּשֵׁר. וְכָל שֶׁתֵּצֵא מְגִלָּה זוֹ מִתַּחַת יָדָהּ מְגֹרֶשֶׁת:","הָיוּ שָׁם שְׁנֵי עֵדִים בִּלְבַד בָּאִים מִתַּחַת גֵּט זֶה לְתַחַת גֵּט זֶה. אִם יָצָא מִתַּחַת יָד זוֹ שֶׁהָעֵדִים נִקְרָאִים עִם גִּטָּהּ הֲרֵי זוֹ מְגֹרֶשֶׁת. וְאִם יָצָא מִתַּחַת יָד שְׁנִיָּה שֶׁאֵין הָעֵדִים נִקְרָאִים עִמּוֹ אֵינוֹ גֵּט עַד שֶׁיִּמְסֹר לָהּ בְּעֵדִים:","כָּתַב שְׁנֵי גִּטִּין בִּשְׁנֵי דַּפִּין זֶה לְמַעְלָה מִזֶּה וְהָעֵדִים בֵּין שְׁנֵי הַגִּטִּין שֶׁנִּמְצְאוּ בְּסוֹף הָרִאשׁוֹן וּלְמַעְלָה מִן הַשֵּׁנִי. אִם הָיָה יוֹצֵא מִתַּחַת יָד זוֹ שֶׁהָעֵדִים נִקְרָאִין בְּסוֹף גִּטָּהּ הֲרֵי זוֹ מְגֹרֶשֶׁת. וְזוֹ שֶׁהָעֵדִים נִקְרָאִין בְּרֹאשׁ גִּטָּהּ מִלְּמַעְלָה אֵינָהּ מְגֹרֶשֶׁת. הָעֵדִים שֶׁחָתְמוּ בְּרֹאשׁ הַדַּף שֶׁל גֵּט אוֹ מִצִּדּוֹ אוֹ מֵאֲחוֹרָיו אֵינוֹ גֵּט. וְאִם נִמְסַר לָהּ בְּעֵדִים כָּשֵׁר:","הִקִּיף רֹאשׁ הַדַּף זֶה לְרֹאשׁ דַּף זֶה וְהָעֵדִים בָּאֶמְצַע שֶׁנִּמְצְאוּ הָעֵדִים בְּרֹאשׁ שְׁנֵי הַגִּטִּין שְׁנֵיהֶם בְּטֵלִין. וְאִם נִמְסְרוּ לָהֶן בְּעֵדִים שְׁנֵיהֶם כְּשֵׁרִים:","שִׁיֵּר מִקְצָת הַגֵּט וּכְתָבוֹ בַּדַּף הַשֵּׁנִי וְהָעֵדִים מִלְּמַטָּה בְּסוֹף הַדַּף הַשֵּׁנִי כָּשֵׁר. וְהוּא שֶׁיִּהְיֶה נִכָּר בַּמְּגִלָּה שֶׁלֹּא נֶחְתַּךְ וְשֶׁלְּכָךְ נִתְכַּוֵּן הַסּוֹפֵר שֶׁיַּשְׁלִים בַּדַּף הַשֵּׁנִי. אֲבָל אִם אֵינוֹ נִכָּר אַף עַל פִּי שֶׁנִּמְסַר בְּעֵדִים הֲרֵי זוֹ סָפֵק מְגֹרֶשֶׁת. שֶׁמָּא שְׁנֵי גִּטִּין הָיוּ וְנֶחְתַּךְ מִקְצָת זֶה מִסּוֹף הַדַּף וּמִקְצָת הַשֵּׁנִי מֵרֹאשׁ הַדַּף:","הֲרֵי שֶׁכָּתַב הַגֵּט וְאַחַר שֶׁגָּמַר כָּתַב שַׁאֲלוּ בִּשְׁלוֹם פְּלוֹנִי אוֹ שָׁלוֹם עָלֶיךָ פְּלוֹנִי רֵעִי וְכַיּוֹצֵא בָּזֶה וְחָתְמוּ הָעֵדִים מִלְּמַטָּה וַהֲרֵי גֵּט זֶה יוֹצֵא מִתַּחַת יָדָהּ הֲרֵי זוֹ סָפֵק מְגֹרֶשֶׁת. שֶׁמָּא לֹא חָתְמוּ הָעֵדִים אֶלָּא עַל שְׁאִילַת שָׁלוֹם. אֲבָל אִם כָּתַב וְשַׁאֲלוּ בִּשְׁלוֹם פְּלוֹנִי אוֹ וְשָׁלוֹם עָלֶיךָ רֵעִי וְכַיּוֹצֵא בָּזֶה שֶׁהֲרֵי לִוָּה דְּבָרִים אֵלּוּ עַל דִּבְרֵי הַגֵּט וְעַל שְׁנֵיהֶם חָתְמוּ הֲרֵי זוֹ מְגֹרֶשֶׁת. וְאִם נִמְסַר לָהּ בְּעֵדִים בֵּין כָּךְ וּבֵין כָּךְ הֲרֵי זֶה גֵּט כָּשֵׁר:"],"Mishneh Torah, Eruvin 7":["מִי שֶׁיָּצָא מֵעֶרֶב שַׁבָּת חוּץ לַמְּדִינָה וְעָמַד בְּמָקוֹם יָדוּעַ בְּתוֹךְ הַתְּחוּם אוֹ בְּסוֹפוֹ וְאָמַר שְׁבִיתָתִי בְּמָקוֹם זֶה וְחָזַר לְעִירוֹ וְלָן שָׁם. יֵשׁ לוֹ לְהַלֵּךְ לְמָחָר מֵאוֹתוֹ מָקוֹם אַלְפַּיִם אַמָּה לְכָל רוּחַ. וְזֶה הוּא עִקַּר עֵרוּבֵי תְּחוּמִין לְעָרֵב בְּרַגְלָיו. וְלֹא אָמְרוּ לְעָרֵב בְּהַנָּחַת מְזוֹן שְׁתֵּי סְעֻדּוֹת בִּלְבַד בַּמָּקוֹם אַף עַל פִּי שֶׁלֹּא יָצָא וְלֹא עָמַד שָׁם אֶלָּא לְהָקֵל עַל הֶעָשִׁיר שֶׁלֹּא יֵצֵא אֶלָּא יִשְׁלַח עֵרוּבוֹ בְּיַד אַחֵר וְיַנִּיחוּ לוֹ:","וְכֵן אִם נִתְכַּוֵּן לִקְבֹּעַ שְׁבִיתָתוֹ בְּמָקוֹם יָדוּעַ אֶצְלוֹ כְּגוֹן אִילָן אוֹ בַּיִת אוֹ גָּדֵר שֶׁהוּא מַכִּיר מְקוֹמוֹ וְיֵשׁ בֵּינוֹ וּבֵינוֹ כְּשֶׁחָשְׁכָה אַלְפַּיִם אַמָּה אוֹ פָּחוֹת וְהֶחֱזִיק בַּדֶּרֶךְ וְהָלַךְ כְּדֵי שֶׁיַּגִּיעַ לְאוֹתוֹ מָקוֹם וְיִקְנֶה בּוֹ שְׁבִיתָה אַף עַל פִּי שֶׁלֹּא הִגִּיעַ וְלֹא עָמַד שָׁם אֶלָּא הֶחְזִירוֹ חֲבֵרוֹ לָלוּן אֶצְלוֹ אוֹ שֶׁחָזַר מֵעַצְמוֹ לָלוּן אוֹ נִתְעַכֵּב. לְמָחָר יֵשׁ לוֹ לְהַלֵּךְ עַד מָקוֹם שֶׁנִּתְכַּוֵּן לוֹ וּמֵאוֹתוֹ הַמָּקוֹם אַלְפַּיִם אַמָּה לְכָל רוּחַ. שֶׁכֵּיוָן שֶׁגָּמַר בְּלִבּוֹ לִקְבֹּעַ שָׁם שְׁבִיתָתוֹ וְהֶחֱזִיק בַּדֶּרֶךְ נַעֲשָׂה כְּמִי שֶׁעָמַד שָׁם אוֹ שֶׁהִנִּיחַ עֵרוּבוֹ שָׁם:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּעָנִי שֶׁאֵין מַטְרִיחִין אוֹתוֹ לְהַנִּיחַ עֵרוּב אוֹ בְּרָחוֹק כְּגוֹן מִי שֶׁהָיָה בָּא בַּדֶּרֶךְ וְהָיָה יָרֵא שֶׁמָּא תֶּחְשַׁךְ. וְהוּא שֶׁיִּשָּׁאֵר מִן הַיּוֹם כְּדֵי לְהַגִּיעַ לְאוֹתוֹ מָקוֹם שֶׁקָּנָה בּוֹ שְׁבִיתָה קֹדֶם שֶׁתֶּחְשַׁךְ אִם רָץ בְּכָל כֹּחוֹ וְהָיָה בֵּינוֹ וּבֵין אוֹתוֹ מָקוֹם כְּשֶׁתֶּחְשַׁךְ אַלְפַּיִם אַמָּה אוֹ פָּחוֹת. אֲבָל אִם לֹא הָיָה רָחוֹק וְלֹא עָנִי אוֹ שֶׁלֹּא נִשְׁאַר מִן הַיּוֹם כְּדֵי שֶׁיַּגִּיעַ אֲפִלּוּ רָץ בְּכָל כֹּחוֹ אוֹ שֶׁהָיָה בֵּין הַמָּקוֹם שֶׁנִּתְכַּוֵּן לִשְׁבֹּת בּוֹ וּבֵין הַמָּקוֹם שֶׁהוּא עוֹמֵד בּוֹ כְּשֶׁחָשְׁכָה יֶתֶר מֵאַלְפַּיִם אַמָּה אוֹ שֶׁלֹּא כִּוֵּן הַמָּקוֹם שֶׁקָּנָה בּוֹ שְׁבִיתָה. הֲרֵי זֶה לֹא קָנָה שְׁבִיתָה בְּרִחוּק מָקוֹם וְאֵין לוֹ אֶלָּא אַלְפַּיִם אַמָּה לְכָל רוּחַ מִמָּקוֹם שֶׁהוּא עוֹמֵד בּוֹ כְּשֶׁחָשְׁכָה:","מִי שֶׁעָמַד מִבְּעוֹד יוֹם בִּרְשׁוּת הַיָּחִיד וְקָנָה שָׁם שְׁבִיתָה אוֹ שֶׁהָיָה בָּא בַּדֶּרֶךְ וְנִתְכַּוֵּן לִשְׁבֹּת בִּרְשׁוּת הַיָּחִיד הַיָּדוּעַ אֶצְלוֹ וְקָנָה שָׁם שְׁבִיתָתוֹ הֲרֵי זֶה מְהַלֵּךְ אֶת כֻּלָּהּ וְחוּצָה לָהּ אַלְפַּיִם אַמָּה לְכָל רוּחַ. וְאִם הָיְתָה רְשׁוּת הַיָּחִיד זוֹ מָקוֹם שֶׁלֹּא הֻקַּף לְדִירָה אוֹ תֵּל אוֹ בִּקְעָה אִם הָיָה בָּהּ בֵּית סָאתַיִם אוֹ פָּחוֹת מְהַלֵּךְ אֶת כֻּלָּהּ וְחוּצָה לָהּ אַלְפַּיִם אַמָּה לְכָל רוּחַ. וְאִם הָיְתָה יוֹתֵר עַל בַּיִת סָאתַיִם אֵין לוֹ בָּהּ אֶלָּא אַרְבַּע אַמּוֹת וְחוּצָה מֵהֶן אַלְפַּיִם אַמָּה לְכָל רוּחַ. וְכֵן אִם הִנִּיחַ עֵרוּבוֹ בְּמָקוֹם שֶׁלֹּא הֻקַּף לְדִירָה:","הַקּוֹנֶה שְׁבִיתָה בְּרִחוּק מָקוֹם וְלֹא סִיֵּם מְקוֹם שְׁבִיתָתוֹ לֹא קָנָה שְׁבִיתָה שָׁם. כֵּיצַד. הָיָה בָּא בַּדֶּרֶךְ וְאָמַר שְׁבִיתָתִי בְּמָקוֹם פְּלוֹנִי אוֹ בְּשָׂדֶה פְּלוֹנִית אוֹ בְּבִקְעָה פְּלוֹנִית אוֹ בְּרִחוּק אֶלֶף אַמָּה אוֹ אַלְפַּיִם מִמְּקוֹמִי זֶה הֲרֵי זֶה לֹא קָנָה שְׁבִיתָה בְּרָחוֹק וְאֵין לוֹ אֶלָּא אַלְפַּיִם אַמָּה לְכָל רוּחַ מִמָּקוֹם שֶׁהוּא עוֹמֵד בּוֹ כְּשֶׁחָשְׁכָה:","אָמַר שְׁבִיתָתִי תַּחַת אִילָן פְּלוֹנִי אוֹ תַּחַת סֶלַע פְּלוֹנִי אִם יֵשׁ תַּחַת אוֹתוֹ אִילָן אוֹ אוֹתוֹ סֶלַע שְׁמוֹנֶה אַמּוֹת אוֹ יָתֵר לֹא קָנָה שְׁבִיתָה שֶׁהֲרֵי לֹא כִּוֵּן מְקוֹם שְׁבִיתָתוֹ. שֶׁאִם בָּא לִשְׁבֹּת בְּתוֹךְ אַרְבַּע אַמּוֹת אֵלּוּ שֶׁמָּא בְּאַרְבַּע אַמּוֹת הָאֲחֵרוֹת הוּא שֶׁקָּנָה שְׁבִיתָה:","לְפִיכָךְ צָרִיךְ לְהִתְכַּוֵּן לִשְׁבֹּת בְּעִקָּרוֹ אוֹ בְּאַרְבַּע אַמּוֹת שֶׁבִּדְרוֹמוֹ אוֹ שֶׁבִּצְפוֹנוֹ. וְאִם הָיָה תַּחְתָּיו פָּחוֹת מִשְּׁמוֹנֶה אַמּוֹת וְנִתְכַּוֵּן לִשְׁבֹּת תַּחְתָּיו קָנָה שֶׁהֲרֵי אֵין שָׁם שִׁעוּר שְׁנֵי מְקוֹמוֹת וַהֲרֵי מִקְצָת מְקוֹמוֹ מְסֻיָּם. הָיוּ שְׁנַיִם בָּאִים בַּדֶּרֶךְ אֶחָד מֵהֶן מַכִּיר אִילָן אוֹ גָּדֵר אוֹ מָקוֹם שֶׁהוּא קוֹבֵעַ בּוֹ שְׁבִיתָה וְהַשֵּׁנִי אֵינוֹ מַכִּיר. זֶה שֶׁאֵינוֹ מַכִּיר מוֹסֵר שְׁבִיתָתוֹ לַמַּכִּיר וְהַמַּכִּיר מִתְכַּוֵּן לִשְׁבֹּת הוּא וַחֲבֵרוֹ בַּמָּקוֹם שֶׁהוּא מַכִּיר:","אַנְשֵׁי הָעִיר שֶׁשָּׁלְחוּ אֶחָד מֵהֶן לְהוֹלִיךְ לָהֶן עֵרוּבָן לְמָקוֹם יָדוּעַ וְהֶחֱזִיק בַּדֶּרֶךְ וְהֶחְזִירוֹ חֲבֵרוֹ וְלֹא הוֹלִיךְ עֵרוּבָן. הֵן לֹא קָנוּ שְׁבִיתָה בְּאוֹתוֹ מָקוֹם שֶׁהֲרֵי לֹא הֻנַּח שָׁם עֵרוּבָן וְאֵין לָהֶן לְהַלֵּךְ מִמְּדִינָתָן אֶלָּא אַלְפַּיִם אַמָּה לְכָל רוּחַ. וְהוּא קָנָה שָׁם עֵרוּב שֶׁהֲרֵי הוּא בָּא בַּדֶּרֶךְ וְנִתְכַּוֵּן לִשְׁבֹּת שָׁם וְהֶחֱזִיק בַּדֶּרֶךְ. לְפִיכָךְ יֵשׁ לוֹ לְהַלֵּךְ לְאוֹתוֹ מָקוֹם לְמָחָר וּלְהַלֵּךְ מִמֶּנּוּ אַלְפַּיִם אַמָּה לְכָל רוּחַ:","זֶה שֶׁאָמַרְנוּ שֶׁצָּרִיךְ הַקּוֹנֶה שְׁבִיתָה בְּרִחוּק מָקוֹם שֶׁיַּחֲזִיק בַּדֶּרֶךְ. לֹא שֶׁיֵּצֵא וְיֵלֵךְ בַּשָּׂדֶה אֶלָּא אֲפִלּוּ יֵרֵד מִן הָעֲלִיָּה לֵילֵךְ לְאוֹתוֹ מָקוֹם וְקֹדֶם שֶׁיֵּצֵא מִפֶּתַח הֶחָצֵר הֶחְזִירוֹ חֲבֵרוֹ הֲרֵי זֶה הֶחֱזִיק וְקָנָה שְׁבִיתָה. וְכָל הַקּוֹנֶה שְׁבִיתָה בְּרִחוּק מָקוֹם אֵינוֹ צָרִיךְ לוֹמַר שְׁבִיתָתִי בְּמָקוֹם פְּלוֹנִי אֶלָּא כֵּיוָן שֶׁגָּמַר בְּלִבּוֹ וְהֶחֱזִיק בְּדֶרֶךְ כָּל שֶׁהוּא קָנָה שָׁם שְׁבִיתָה. וְאֵין צָרִיךְ לוֹמַר מִי שֶׁיָּצָא בְּרַגְלָיו וְעָמַד בְּמָקוֹם שֶׁקּוֹנֶה בּוֹ שְׁבִיתָה שֶׁאֵינוֹ צָרִיךְ לוֹמַר כְּלוּם אֶלָּא כֵּיוָן שֶׁגָּמַר בְּלִבּוֹ קָנָה:","הַתַּלְמִידִים שֶׁהוֹלְכִין וְאוֹכְלִין בְּלֵילֵי שַׁבָּת בַּשָּׂדוֹת וּבַכְּרָמִים אֵצֶל בַּעֲלֵי הַבָּתִּים שֶׁפִּתָּן מְצוּיָה לְעוֹבְרֵי דְּרָכִים הַבָּאִים שָׁם וּבָאִים וְלָנִים בְּבֵית הַמִּדְרָשׁ. מְהַלְּכִין אַלְפַּיִם אַמָּה לְכָל רוּחַ מִבֵּית הַמִּדְרָשׁ לֹא מִמְּקוֹם הָאֲכִילָה. שֶׁאִלּוּ מָצְאוּ סְעֻדָּתָן בְּבֵית הַמִּדְרָשׁ לֹא הָיוּ יוֹצְאִין לַשָּׂדֶה וְאֵין דַּעְתָּן סוֹמֶכֶת לַדִּירָה אֶלָּא עַל בֵּית מִדְרָשָׁם:"],"Mishneh Torah, First Fruits and other Gifts to Priests Outside the Sanctuary 11":["מִצְוַת עֲשֵׂה לִפְדּוֹת כָּל אִישׁ מִיִּשְׂרָאֵל בְּנוֹ שֶׁהוּא בְּכוֹר לְאִמּוֹ הַיִּשְׂרְאֵלִית שֶׁנֶּאֱמַר (שמות לד יט) \"כָּל פֶּטֶר רֶחֶם לִי\". וְנֶאֱמַר (במדבר יח טו) \"אַךְ פָּדֹה תִפְדֶּה אֵת בְּכוֹר הָאָדָם\":","וְאֵין הָאִשָּׁה חַיֶּבֶת לִפְדּוֹת אֶת בְּנָהּ. שֶׁהַחַיָּב לִפְדּוֹת אֶת עַצְמוֹ הוּא שֶׁחַיָּב לִפְדּוֹת אֶת בְּנוֹ. עָבַר הָאָב וְלֹא פָּדָהוּ כְּשֶׁיִּגְדַּל יִפְדֶּה אֶת עַצְמוֹ:","הָיָה הוּא לִפְדּוֹת וּבְנוֹ לִפְדּוֹת יִפְדֶּה עַצְמוֹ תְּחִלָּה וְאַחַר כָּךְ בְּנוֹ. וְאִם אֵין לוֹ אֶלָּא כְּדֵי פִּדְיוֹן אֶחָד יִפְדֶּה עַצְמוֹ:","הָיָה בְּנוֹ לִפְדּוֹת וְהִגִּיעַ עֵת לַעֲלוֹת לָרֶגֶל וְאֵין לוֹ כְּדֵי לָזֶה וְלָזֶה. פּוֹדֶה אֶת בְּנוֹ וְאַחַר כָּךְ עוֹלֶה לָרֶגֶל שֶׁנֶּאֱמַר (שמות לד כ) \"כּל בְּכוֹר בָּנֶיךָ תִּפְדֶּה\" וְאַחַר כָּךְ (שמות לד כ) \"וְלֹא יֵרָאוּ פָנַי רֵיקָם\":","הַפּוֹדֶה אֶת בְּנוֹ מְבָרֵךְ אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל פִּדְיוֹן הַבֵּן. וְחוֹזֵר וּמְבָרֵךְ שֶׁהֶחֱיָינוּ. וְאַחַר כָּךְ נוֹתֵן הַפִּדְיוֹן לַכֹּהֵן. וְאִם פָּדָה עַצְמוֹ מְבָרֵךְ לִפְדּוֹת הַבְּכוֹר וּמְבָרֵךְ שֶׁהֶחֱיָינוּ:","מִצְוָה זוֹ נוֹהֶגֶת בְּכָל מָקוֹם וּבְכָל זְמַן. וּבְכַמָּה פּוֹדֵהוּ בְּחָמֵשׁ סְלָעִים שֶׁנֶּאֱמַר (במדבר יח טז) \"וּפְדוּיָו מִבֶּן חֹדֶשׁ תִּפְדֶּה\". בֵּין בְּכֶסֶף בֵּין בִּשְׁוֵה כֶּסֶף מִן הַמִּטַּלְטְלִין שֶׁגּוּפָן מָמוֹן כְּעִנְיַן הַשְּׁקָלִים. לְפִיכָךְ אֵין פּוֹדִין בְּקַרְקָעוֹת וְלֹא בַּעֲבָדִים מִפְּנֵי שֶׁהֵן כְּקַרְקָעוֹת וְלֹא בִּשְׁטָרוֹת לְפִי שֶׁאֵין גּוּפָן מָמוֹן. וְאִם פָּדָהוּ בָּהֶן אֵינוֹ פָּדוּי:","כָּתַב הָאָב לַכֹּהֵן שֶׁהוּא חַיָּב לוֹ חֲמִשָּׁה סְלָעִים חַיָּב לִתֵּן לוֹ וּבְנוֹ אֵינוֹ פָּדוּי. נָתַן לוֹ כְּלִי שֶׁאֵינוֹ שָׁוֶה בַּשּׁוּק חֲמִשָּׁה סְלָעִים וְקִבְּלוֹ הַכֹּהֵן בַּחֲמִשָּׁה סְלָעִים הֲרֵי בְּנוֹ פָּדוּי. נָתַן חֲמִשָּׁה סְלָעִים לַעֲשָׂרָה כֹּהֲנִים בֵּין בְּבַת אַחַת בֵּין בָּזֶה אַחַר זֶה יָצָא:","רָצָה הַכֹּהֵן לְהַחְזִיר לוֹ הַפִּדְיוֹן מַחְזִיר. וְלֹא יִתֵּן לוֹ הוּא וְדַעְתּוֹ שֶׁיַּחְזִיר. וְאִם עָשָׂה כֵּן וְהֶחְזִיר לוֹ אֵין בְּנוֹ פָּדוּי עַד שֶׁיִּגְמֹר בְּלִבּוֹ לִתֵּן לוֹ מַתָּנָה גְּמוּרָה. וְאִם רָצָה הַכֹּהֵן אַחַר כָּךְ לְהַחְזִיר יַחְזִיר. וְכֵן אִם פֵּרֵשׁ וְנָתַן לוֹ עַל מְנָת לְהַחְזִיר הֲרֵי בְּנוֹ פָּדוּי:","כֹּהֲנִים וּלְוִיִּם פְּטוּרִים מִפִּדְיוֹן הַבֵּן מִקַּל וָחֹמֶר. אִם פָּטְרוּ שֶׁל יִשְׂרָאֵל בַּמִּדְבָּר דִּין הוּא שֶׁיִּפְטְרוּ עַצְמָן:","יִשְׂרָאֵל הַבָּא מִן הַכֹּהֶנֶת וּמִן הַלְּוִיָּה פָּטוּר. שֶׁאֵין הַדָּבָר תָּלוּי בָּאָב אֶלָּא בָּאֵם שֶׁנֶּאֱמַר פֶּטֶר רֶחֶם בְּיִשְׂרָאֵל:","לְוִיָּה הַמְעֻבֶּרֶת מֵעַכּוּ\"ם בְּנָהּ פָּטוּר. וְכֹהֶנֶת הַמְעֻבֶּרֶת מֵעַכּוּ\"ם בְּנָהּ חַיָּב שֶׁהֲרֵי נִפְסְלָה אִמּוֹ מִן הַכְּהֻנָּה בִּבְעִילַת הָעַכּוּ\"ם:","כֹּהֵן שֶׁנּוֹלַד לוֹ בֶּן חָלָל. מֵת הָאָב בְּתוֹךְ שְׁלֹשִׁים יוֹם הַבֵּן חַיָּב לִפְדּוֹת אֶת עַצְמוֹ. שֶׁלֹּא זָכָה הָאָב בְּפִדְיוֹנוֹ. מֵת אַחַר שְׁלֹשִׁים יוֹם אֵינוֹ חַיָּב הַבֵּן לִפְדּוֹת אֶת עַצְמוֹ. שֶׁהֲרֵי זָכָה הָאָב בְּפִדְיוֹנוֹ:","הַשִּׁפְחָה שֶׁנִּשְׁתַּחְרְרָה וְכוּתִית שֶׁנִּתְגַּיְּרָה כְּשֶׁהֵן מְעֻבָּרוֹת וְיָלְדוּ. אַף עַל פִּי שֶׁהוֹרָתוֹ שֶׁלֹּא בִּקְדֻשָּׁה הוֹאִיל וְנוֹלַד בִּקְדֻשָּׁה חַיָּב. שֶׁנֶּאֱמַר פֶּטֶר רֶחֶם בְּיִשְׂרָאֵל וַהֲרֵי פֶּטֶר וְרֶחֶם בְּיִשְׂרָאֵל. אֵין יָדוּעַ אִם קֹדֶם שֶׁנִּתְגַּיְּרָה יָלְדָה אוֹ אַחַר שֶׁנִּתְגַּיְּרָה יָלְדָה הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה:","הַכּוּתִית וְהַשִּׁפְחָה שֶׁיָּלְדוּ וְאַחַר כָּךְ נִתְגַּיְּרוּ וְנִשְׁתַּחְרְרוּ וְיָלְדוּ וָלָד אַחֵר הֲרֵי זֶה פָּטוּר שֶׁנֶּאֱמַר (במדבר ג יב) (במדבר יח טו) \"פֶּטֶר רֶחֶם\" וְאֵין זֶה פֶּטֶר רֶחֶם. וְכֵן הַבָּא אַחַר הַנְּפָלִים כָּל נֵפֶל שֶׁאִמּוֹ טְמֵאָה לֵדָה הַבָּא אַחֲרָיו אֵינוֹ פֶּטֶר רֶחֶם. וְכָל נֵפֶל שֶׁאֵין אִמּוֹ טְמֵאָה לֵדָה כְּמוֹ הַמַּפֶּלֶת כְּמִין דָּגִים וַחֲגָבִים אוֹ הַמַּפֶּלֶת יוֹם אַרְבָּעִים וְכַיּוֹצֵא בָּהֶן הַבָּא אַחֲרָיו בְּכוֹר לַכֹּהֵן וְחַיָּב לִפְדּוֹת:","חָתַךְ הָעֻבָּר בְּמֵעֶיהָ וְהוֹצִיאוֹ אֵיבָר אֵיבָר הַבָּא אַחֲרָיו אֵינוֹ פֶּטֶר רֶחֶם. בֶּן שְׁמוֹנָה חֳדָשִׁים שֶׁהוֹצִיא רֹאשׁוֹ וְהוּא חַי וְהֶחֱזִירוֹ וָמֵת. וְכֵן בֶּן תִּשְׁעָה שֶׁמֵּת וְיָצָא רֹאשׁוֹ וְהֶחֱזִירוֹ וְאַחַר כָּךְ יָצָא אָחִיו וְיָלְדָה. זֶה שֶׁיָּלְדָה אֵינוֹ פֶּטֶר רֶחֶם. שֶׁהֲרֵי נִפְטַר בְּרֹאשׁוֹ שֶׁל רִאשׁוֹן. וּמִשֶּׁתֵּצֵא פַּדַּחְתּוֹ פּוֹטֵר הַבָּא אַחֲרָיו:","יוֹצֵא דֹּפֶן וְהַבָּא אַחֲרָיו כְּדַרְכּוֹ שְׁנֵיהֶם פְּטוּרִים. הָרִאשׁוֹן לְפִי שֶׁלֹּא יָצָא מִן הָרֶחֶם וְהַשֵּׁנִי מִפְּנֵי שֶׁקְּדָמוֹ אַחֵר:","מֵאֵימָתַי יִתְחַיֵּב בְּפִדְיוֹן. מִשֶּׁיַּשְׁלִים שְׁלֹשִׁים יוֹם שֶׁנֶּאֱמַר (במדבר יח טז) \"וּפְדוּיָו מִבֶּן חֹדֶשׁ תִּפְדֶּה\". מֵת הַבֵּן בְּתוֹךְ שְׁלֹשִׁים וַאֲפִלּוּ בְּיוֹם שְׁלֹשִׁים. וְכֵן אִם נַעֲשָׂה טְרֵפָה. אֵינוֹ חַיָּב בַּחֲמִשָּׁה סְלָעִים. וְאִם הִקְדִּים וְנָתַן לַכֹּהֵן יַחְזִיר לוֹ הַפִּדְיוֹן. [וְאִם מֵת אַחַר שְׁלֹשִׁים יוֹם חַיָּב בְּפִדְיוֹן] וְאִם לֹא נָתַן יִתֵּן:","מִי שֶׁפָּדָה בְּנוֹ בְּתוֹךְ שְׁלֹשִׁים יוֹם אִם אָמַר לוֹ מֵעַכְשָׁו אֵין בְּנוֹ פָּדוּי. וְאִם אָמַר לוֹ לְאַחַר שְׁלֹשִׁים יוֹם בְּנוֹ פָּדוּי וְאַף עַל פִּי שֶׁאֵין הַמָּעוֹת קַיָּמִין לְאַחַר שְׁלֹשִׁים יוֹם:","מִי שֶׁהוּא סָפֵק אִם חַיָּב בְּפִדְיוֹן אוֹ לֹא הֲרֵי זֶה פָּטוּר שֶׁהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. מֵת הָאָב בְּתוֹךְ שְׁלֹשִׁים יוֹם הֲרֵי הַבֵּן בְּחֶזְקַת שֶׁלֹּא נִפְדָּה עַד שֶׁיָּבִיא רְאָיָה מֵאָבִיו שֶׁפָּדָהוּ קֹדֶם שֶׁיָּמוּת. מֵת הָאָב לְאַחַר שְׁלֹשִׁים יוֹם הֲרֵי הוּא בְּחֶזְקַת פָּדוּי עַד שֶׁיּוֹדִיעוּהוּ שֶׁלֹּא נִפְדָּה:","מִי שֶׁלֹּא בִּכְּרָה אִשְׁתּוֹ וְיָלְדָה זָכָר וּנְקֵבָה וְאֵין יָדוּעַ אֵי זֶה מֵהֶן יָצָא רִאשׁוֹן אֵין כָּאן לַכֹּהֵן כְּלוּם. יָלְדָה שְׁנֵי זְכָרִים אַף עַל פִּי שֶׁאֵין יָדוּעַ אֵי זֶה מֵהֶן הַבְּכוֹר נוֹתֵן חֲמִשָּׁה סְלָעִים לַכֹּהֵן. מֵת אֶחָד מֵהֶן בְּתוֹךְ שְׁלֹשִׁים יוֹם פָּטוּר שֶׁהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. מֵת הָאָב בֵּין בְּתוֹךְ שְׁלֹשִׁים יוֹם בֵּין אַחַר שְׁלֹשִׁים יוֹם. בֵּין שֶׁלֹּא חָלְקוּ הָאַחִים בֵּין שֶׁחָלְקוּ. יִנָּתֵן מִן הַנְּכָסִים חֲמִשָּׁה סְלָעִים לַכֹּהֵן שֶׁכְּבָר נִתְחַיְּבוּ הַנְּכָסִים:","שְׁתֵּי נָשָׁיו שֶׁלֹּא בִּכְּרוּ וְיָלְדוּ שְׁנֵי זְכָרִים נוֹתֵן עֲשָׂרָה סְלָעִים לַכֹּהֵן. מֵת אֶחָד מֵהֶן בְּתוֹךְ שְׁלֹשִׁים יוֹם אִם לְכֹהֵן אֶחָד נָתַן יַחְזִיר לוֹ חֲמִשָּׁה סְלָעִים. וְאִם לִשְׁנֵי כֹּהֲנִים נָתַן אֵינוֹ יָכוֹל לְהוֹצִיא מֵהֶן שֶׁהֲרֵי לֹא צִיֵּן פִּדְיוֹן זֶה עַל בֵּן זֶה. וְכָל אֶחָד מֵהֶן יָכוֹל לוֹמַר הַחֲזִיר מֵחֲבֵרִי:","שְׁתֵּי נָשָׁיו שֶׁלֹּא בִּכְּרוּ שֶׁיָּלְדוּ זָכָר וּנְקֵבָה אוֹ שְׁנֵי זְכָרִים וּנְקֵבָה נוֹתֵן חֲמִשָּׁה סְלָעִים לַכֹּהֵן. שֶׁאִי אֶפְשָׁר שֶׁלֹּא יִהְיֶה זָכָר אֶחָד מֵהֶן פֶּטֶר רֶחֶם:","יָלְדוּ שְׁתֵּי נְקֵבוֹת וְזָכָר. אוֹ שְׁנֵי זְכָרִים וּשְׁתֵּי נְקֵבוֹת. וְאֵין יָדוּעַ אֵי זֶה נוֹלַד רִאשׁוֹן. אֵין כָּאן לַכֹּהֵן כְּלוּם שֶׁאֲנִי אוֹמֵר נְקֵבָה נוֹלְדָה תְּחִלָּה וְאַחֲרֶיהָ זָכָר:","שְׁתֵּי נָשָׁיו אַחַת בִּכְּרָה וְאַחַת לֹא בִּכְּרָה וְיָלְדוּ שְׁנֵי זְכָרִים וְנִתְעָרְבוּ. נוֹתֵן חֲמִשָּׁה סְלָעִים לַכֹּהֵן. מֵת אֶחָד מֵהֶם בְּתוֹךְ שְׁלֹשִׁים יוֹם הָאָב פָּטוּר. מֵת הָאָב יִנָּתֵן מִן הַנְּכָסִים חֲמִשָּׁה סְלָעִים:","יָלְדוּ זָכָר וּנְקֵבָה אוֹ שְׁנֵי זְכָרִים וּנְקֵבָה אֵין כָּאן לַכֹּהֵן כְּלוּם. שֶׁאֲנִי אוֹמֵר זוֹ שֶׁלֹּא בִּכְּרָה יָלְדָה נְקֵבָה תְּחִלָּה וְאַחֲרֶיהָ זָכָר וְזוֹ שֶׁבִּכְּרָה יָלְדָה זָכָר:","שְׁתֵּי נָשִׁים שֶׁל שְׁנֵי אֲנָשִׁים שֶׁלֹּא בִּכְּרוּ וְיָלְדוּ שְׁנֵי זְכָרִים וְנִתְעָרְבוּ זֶה נוֹתֵן חֲמִשָּׁה סְלָעִים וְזֶה נוֹתֵן חֲמִשָּׁה סְלָעִים. נָתְנוּ וְאַחַר כָּךְ מֵת אֶחָד מִן הַבָּנִים בְּתוֹךְ שְׁלֹשִׁים יוֹם. אִם לִשְׁנֵי כֹּהֲנִים נָתְנוּ אֵינָן יְכוֹלִין לְהוֹצִיא מִיָּדָן. וְאִם לְכֹהֵן אֶחָד נָתְנוּ כּוֹתֵב אֶחָד מֵהֶן לַחֲבֵרוֹ הַרְשָׁאָה וְיֵלֵךְ זֶה בְּהַרְשָׁאָה וְיַחְזִיר מִן הַכֹּהֵן חֲמִשָּׁה סְלָעִים:","יָלְדוּ זָכָר וּנְקֵבָה וְנִתְעָרְבוּ הָאָבוֹת פְּטוּרִין וְהַבֵּן חַיָּב לִפְדּוֹת אֶת עַצְמוֹ. וְכֵן מְבַכֶּרֶת שֶׁלֹּא שָׁהֲתָה אַחַר בַּעְלָהּ שְׁלֹשָׁה חֳדָשִׁים וְיָלְדָה וְאֵין יָדוּעַ אִם בֶּן תִּשְׁעָה לָרִאשׁוֹן אוֹ בֶּן שִׁבְעָה לָאַחֲרוֹן שְׁנֵיהֶן פְּטוּרִין. וְהַבֵּן חַיָּב לִפְדּוֹת אֶת עַצְמוֹ:","יָלְדוּ שְׁתֵּי נְקֵבוֹת וְזָכָר אוֹ שְׁתֵּי נְקֵבוֹת וּשְׁנֵי זְכָרִים אֵין כָּאן לַכֹּהֵן כְּלוּם:","שְׁתֵּי נָשִׁים שֶׁל שְׁנֵי אֲנָשִׁים אַחַת בִּכְּרָה וְאַחַת לֹא בִּכְּרָה וְיָלְדוּ שְׁנֵי זְכָרִים. זֶה שֶׁלֹּא בִּכְּרָה אִשְׁתּוֹ נוֹתֵן חָמֵשׁ סְלָעִים לַכֹּהֵן. יָלְדוּ זָכָר וּנְקֵבָה אֵין כָּאן לַכֹּהֵן כְּלוּם:","יָלְדוּ שְׁנֵי זְכָרִים וּנְקֵבָה זֶה שֶׁלֹּא בִּכְּרָה אִשְׁתּוֹ נוֹתֵן חֲמִשָּׁה סְלָעִים. שֶׁלֹּא נִפְטַר אֶלָּא בִּשְׁנֵי סְפֵקוֹת אִם אִשְׁתּוֹ יָלְדָה זָכָר בִּלְבַד חַיָּב וְאִם הִיא יָלְדָה הַזָּכָר וְהַנְּקֵבָה חַיָּב אֶלָּא אִם כֵּן יָלְדָה נְקֵבָה תְּחִלָּה. וְהוֹאִיל וְהַדָּבָר רָחוֹק יִתֵּן פִּדְיוֹנוֹ:"],"Mishneh Torah, Firstlings 3":["אֵין שׁוֹחֲטִין אֶת הַבְּכוֹר אֶלָּא עַל פִּי מֻמְחֶה שֶׁנָּתַן לוֹ הַנָּשִׂיא שֶׁבְּאֶרֶץ יִשְׂרָאֵל רְשׁוּת וְאָמַר לוֹ הַתֵּר בְּכוֹרוֹת בְּמוּמָן. אֲפִלּוּ הָיָה מוּם גָּדוֹל וְגָלוּי לַכּל לֹא יַתִּירוֹ אֶלָּא מֻמְחֶה שֶׁנָּטַל רְשׁוּת. וְכָל הַבְּכוֹרוֹת אָדָם רוֹאֶה חוּץ מִבְּכוֹרֵי עַצְמוֹ:","אִם אֵין שָׁם מֻמְחֶה וְהָיָה הַמּוּם מִן הַמּוּמִין הַגְּלוּיִין הַמֻּבְהָקִין. כְּגוֹן שֶׁנִּסְמֵית עֵינוֹ. אוֹ נִקְטְעָה יָדוֹ. אוֹ נִשְׁבְּרָה רַגְלוֹ. הֲרֵי זֶה יִשָּׁחֵט עַל פִּי שְׁלֹשָׁה בְּנֵי הַכְּנֶסֶת. וְכֵן בְּכוֹר שֶׁיָּצָא לְחוּצָה לָאָרֶץ וְנָפַל בּוֹ מוּם מֻבְהָק. הֲרֵי זֶה יֻתַּר עַל פִּי שְׁלֹשָׁה בְּנֵי הַכְּנֶסֶת:","אֵין רוֹאִין אֶת הַבְּכוֹר לְיִשְׂרָאֵל עַד שֶׁיִּהְיֶה כֹּהֵן עִמּוֹ. שֶׁמָּא יֹאמַר לוֹ הַמֻּמְחֶה מוּם הוּא וּמֻתָּר לִשְׁחֹט עָלָיו וְיֵלֵךְ וְיִשְׁחָטֶנּוּ לְעַצְמוֹ וְלֹא יִתְּנֶנּוּ לַכֹּהֵן. שֶׁאַף עַל פִּי שֶׁאֵינוֹ חָשׁוּד לֶאֱכל קָדָשִׁים בַּחוּץ. חָשׁוּד הוּא לִגְזל מַתְּנוֹת כְּהֻנָּה. לְפִיכָךְ אִם הָיָה חָכָם וְיָדוּעַ שֶׁהוּא מְדַקְדֵּק עַל עַצְמוֹ רוֹאִין לוֹ. הָיָה הַמּוּם גָּלוּי לַכּל כְּגוֹן שֶׁנִּקְטְעָה יָדוֹ אוֹ רַגְלוֹ. הוֹאִיל וֶהֱבִיאוֹ לְחָכָם הַמֻּמְחֶה הֲרֵי זֶה בְּחֶזְקַת מְדַקְדֵּק עַל עַצְמוֹ לְפִיכָךְ רוֹאִין לוֹ אַף עַל פִּי שֶׁאֵין עִמּוֹ כֹּהֵן:","הַשּׁוֹחֵט אֶת הַבְּכוֹר וְאַחַר כָּךְ הֶרְאָה אֶת מוּמוֹ אַף עַל פִּי שֶׁהוּא מוּם גָּלוּי שֶׁאֵינוֹ מִשְׁתַּנֶּה בִּשְׁחִיטָה כְּגוֹן שֶׁנֶּחְתְּכָה יָדוֹ אוֹ רַגְלוֹ הוֹאִיל וְנִשְׁחַט שֶׁלֹּא עַל פִּי מֻמְחֶה הֲרֵי זֶה אָסוּר וְיִקָּבֵר כִּבְכוֹר שֶׁמֵּת:","בְּכוֹר שֶׁהָיְתָה לוֹ בֵּיצָה אַחַת וּשְׁנֵי כִּיסִים. וּבְדָקוֹ הַמֻּמְחֶה וְהוֹשִׁיבוּהוּ עַל הַרְגּוֹזוֹ וּמִעֲכוּ וְלֹא יָצָאת בֵּיצָה שְׁנִיָּה וְהִתִּירוֹ הַמֻּמְחֶה וְנִשְׁחַט וְנִמְצָא הַשְּׁנִיָּה דְּבוּקָה בַּכְּסָלִים הֲרֵי זֶה מֻתָּר הוֹאִיל וּמִעֲכוּ. אֲבָל אִם לֹא נִמְעַךְ אַף עַל פִּי שֶׁנִּשְׁחַט עַל פִּי מֻמְחֶה הֲרֵי זֶה יִקָּבֵר:","מִי שֶׁאֵינוֹ מֻמְחֶה וְרָאָה אֶת הַבְּכוֹר וְנִשְׁחַט עַל פִּיו. הֲרֵי זֶה יִקָּבֵר וִישַׁלֵּם מִבֵּיתוֹ. וְכַמָּה מְשַׁלֵּם. רְבִיעַ לְדַקָּה וּמֶחֱצָה לְגַסָּה. וּמִפְּנֵי מָה לֹא יְשַׁלֵּם כָּל דָּמָיו מִפְּנֵי שֶׁקָּנְסוּ אֶת בַּעַל הַבְּהֵמָה כְּדֵי שֶׁלֹּא יַשְׁהֶנָּה וְלֹא יְגַדֵּל בְּהֵמָה דַּקָּה בְּאֶרֶץ יִשְׂרָאֵל:","הַנּוֹטֵל שְׂכָרוֹ לִהְיוֹת רוֹאֶה בְּכוֹרוֹת אֵין שׁוֹחֲטִין עַל פִּיו אֶלָּא אִם כֵּן הָיָה מֻמְחֶה גָּדוֹל וְיָדְעוּ בּוֹ חֲכָמִים שֶׁאֵין כְּמוֹתוֹ וּפָסְקוּ לוֹ שָׂכָר עַל הָרְאִיָּה וְהַבִּקּוּר בֵּין שֶּׁנִּמְצָא בּוֹ מוּם בֵּין שֶּׁנִּמְצָא תָּמִים. וְלֹא יִטּל שָׂכָר עַל בְּהֵמָה זוֹ חוּץ מִפַּעַם אַחַת וְרוֹאֶה אוֹתָהּ לְעוֹלָם כָּל זְמַן שֶׁמְּבִיאִין אוֹתָהּ כְּדֵי שֶׁלֹּא יָבוֹא לִידֵי חֲשָׁד:","הֶחָשׁוּד עַל הַבְּכוֹרוֹת לְמָכְרָן לְשֵׁם חֻלִּין אֵין לוֹקְחִין מִמֶּנּוּ אֲפִלּוּ בְּשַׂר צְבָאִים מִפְּנֵי שֶׁהוּא דּוֹמֶה לִבְשַׂר עֵגֶל. וְאֵין לוֹקְחִים מִמֶּנּוּ עוֹרוֹת שֶׁאֵינָן עֲבוּדִים אֲפִלּוּ שֶׁל נְקֵבָה שֶׁמָּא יַחְתֹּךְ זִכְרוּתוֹ וְיֹאמַר עוֹר נְקֵבָה הוּא. וְאֵין לוֹקְחִין מִמֶּנּוּ צֶמֶר אֲפִלּוּ מְלֻבָּן וְאֵין צָרִיךְ לוֹמַר צוֹאִי. אֲבָל לוֹקְחִין מִמֶּנּוּ טָוּוּי וּלְבָדִין וְעוֹרוֹת עֲבוּדִים. שֶׁאֵינוֹ מְעַבֵּד עוֹר בְּכוֹר תָּמִים מִפְּנֵי שֶׁהוּא מְפַחֵד לַשְׁהוֹתוֹ אֶצְלוֹ שֶׁמָּא יִשְׁמְעוּ הַדַּיָּנִים וְיִקְנְסוּהוּ כְּפִי רִשְׁעוֹ:","הַשּׁוֹחֵט אֶת הַבְּכוֹר וּמְכָרוֹ וְנוֹדַע שֶׁלֹּא הֶרְאָהוּ לְמֻמְחֶה. מַה שֶּׁאָכְלוּ אָכְלוּ וְיַחְזִיר לָהֶם אֶת הַדָּמִים. וּמַה שֶּׁלֹּא נֶאֱכַל יִקָּבֵר וְיַחְזִיר אֶת הַדָּמִים. וְכֵן הַדִּין בְּמַאֲכִיל אֶת הַטְּרֵפָה כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת מִקָּח וּמִמְכָּר:","בְּכוֹר שֶׁנִּמְצָא טְרֵפָה אִם תָּמִים הוּא וְנִמְצָא טְרֵפָה אַחַר שֶׁהֻפְשַׁט הָעוֹר יִשָּׂרֵף כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת פְּסוּלֵי הַמֻּקְדָּשִׁין וְהַבָּשָׂר יִקָּבֵר. וְאִם בְּמוּמוֹ נִשְׁחַט הַבָּשָׂר יִקָּבֵר וְיֵהָנוּ הַכֹּהֲנִים בְּעוֹרוֹ. וְהוּא שֶׁנִּשְׁחַט עַל פִּי מֻמְחֶה:","הַבְּכוֹר שֶׁנֶּאֱכַל בְּשָׂרוֹ כַּהֲלָכָה בֵּין תָּמִים בֵּין בַּעַל מוּם. כְּשֵׁם שֶׁמֻּתָּר לֵהָנוֹת בְּעוֹרוֹ כָּךְ נֶהֱנִין בְּגִזּוֹתָיו. אֲבָל כָּל צֶמֶר שֶׁנִּגְזַז מִמֶּנּוּ כְּשֶׁהוּא חַי אֲפִלּוּ נָשַׁר הֲרֵי הוּא אָסוּר בַּהֲנָאָה. וַאֲפִלּוּ נָשַׁר מִמֶּנּוּ אַחַר שֶׁנָּפַל בּוֹ מוּם. וַאֲפִלּוּ אַחַר שְׁחִיטָתוֹ וְאֵין צָרִיךְ לוֹמַר אַחַר מִיתָתוֹ שֶׁהֲרֵי אוֹתוֹ הַצֶּמֶר שֶׁנָּשַׁר מִמֶּנּוּ מֵחַיִּים בְּאִסּוּרוֹ עוֹמֵד. וְכֵן בְּמַעֲשַׂר בְּהֵמָה. וּכְבָר בֵּאַרְנוּ בְּהִלְכוֹת מְעִילָה שֶׁלֹּא גָּזְרוּ גְּזֵרָה זוֹ אֶלָּא עַל הַבְּכוֹר וְעַל הַמַּעֲשֵׂר בִּלְבַד מִפְּנֵי שֶׁאֵינָן בָּאִין לְכַפָּרָה שֶׁמָּא יַשְׁהֵם אֶצְלוֹ כְּדֵי לִקַּח כָּל הַצֶּמֶר שֶׁיִּנְשֹׁר מֵהֶם. וּכְבָר בֵּאַרְנוּ שֶׁמִּצְוָה לְאָכְלוֹ תּוֹךְ שְׁנָתוֹ בֵּין תָּמִים בֵּין בַּעַל מוּם:","בְּכוֹר שֶׁהָיָה בּוֹ צֶמֶר מְדֻבְלָל וּשְׁחָטוֹ. אֶת שֶׁהוּא נִרְאֶה עִמּוֹ מִן הַגִּזָּה מֻתָּר בַּהֲנָאָה. וְאֶת שֶׁאֵינוֹ נִרְאֶה עִמּוֹ וְהוּא הַצֶּמֶר שֶׁעִקָּרוֹ הָפוּךְ כְּלַפֵּי רֹאשׁוֹ אָסוּר. שֶׁזֶּה כְּמוֹ שֶׁנָּשַׁר מֵחַיִּים:","גִּזַּת בְּכוֹר אֲפִלּוּ בַּעַל מוּם שֶׁנִּתְעָרְבָה בְּגִזֵּי חֻלִּין אֲפִלּוּ אַחַת בְּכַמָּה אֲלָפִים הַכּל אֲסוּרִים. הֲרֵי הוּא דָּבָר חָשׁוּב וּמְקַדֵּשׁ בְּכָל שֶׁהוּא. הָאוֹרֵג מְלֹא הַסִּיט מִצֶּמֶר הַבְּכוֹר בְּבֶגֶד יִדָּלֵק. מִצֶּמֶר הַמֻּקְדָּשִׁין מְקַדֵּשׁ בְּכָל שֶׁהוּא:"],"Mishneh Torah, Forbidden Foods 15":["דָבָר אָסוּר שֶׁנִּתְעָרֵב בְּדָבָר מֻתָּר מִין בְּשֶׁאֵינוֹ מִינוֹ בְּנוֹתֵן טַעַם. וּמִין בְּמִינוֹ שֶׁאִי אֶפְשָׁר לַעֲמֹד עַל טַעֲמוֹ יִבָּטֵל בְּרֹב:","כֵּיצַד. חֵלֶב הַכְּלָיוֹת שֶׁנָּפַל לְתוֹךְ הַגְּרִיסִין וְנִמּוֹחַ הַכּל. טוֹעֲמִין אֶת הַגְּרִיסִין. אִם לֹא נִמְצָא בָּהֶן טַעַם חֵלֶב הֲרֵי אֵלּוּ מֻתָּרִין. וְאִם נִמְצָא בָּהֶם טַעַם חֵלֶב וְהָיָה בָּהֶן מַמָּשׁוֹ הֲרֵי אֵלּוּ אֲסוּרִין מִן הַתּוֹרָה. נִמְצָא בָּהֶן טַעֲמוֹ וְלֹא הָיָה בָּהֶן מַמָּשׁוֹ הֲרֵי אֵלּוּ אֲסוּרִין מִדִּבְרֵי סוֹפְרִים:","כֵּיצַד הוּא מַמָּשׁוֹ. כְּגוֹן שֶׁהָיָה מִן הַחֵלֶב כְּזַיִת בְּכָל שָׁלֹשׁ בֵּיצִים מִן הַתַּעֲרֹבֶת. אִם אָכַל מִן הַגְּרִיסִין הָאֵלּוּ כְּשָׁלֹשׁ בֵּיצִים הוֹאִיל וְיֵשׁ בָּהֶן כְּזַיִת מִן הַחֵלֶב לוֹקֶה שֶׁהֲרֵי טַעַם הָאִסּוּר וּמַמָּשׁוֹ קַיָּם. אֲבָל פָּחוֹת מִשָּׁלֹשׁ בֵּיצִים מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת מִדִּבְרֵיהֶם. וְכֵן אִם לֹא הָיָה בַּתַּעֲרֹבֶת כְּזַיִת בְּכָל שָׁלֹשׁ בֵּיצִים אַף עַל פִּי שֶׁיֵּשׁ בָּהֶן טַעַם חֵלֶב וְאָכַל כָּל הַקְּדֵרָה אֵינוֹ לוֹקֶה אֶלָּא מַכַּת מַרְדּוּת:","נָפַל חֵלֶב כְּלָיוֹת לְחֵלֶב הָאַלְיָה וְנִמּוֹחַ הַכּל. אִם הָיָה חֵלֶב הָאַלְיָה כִּשְׁנַיִם בְּחֵלֶב הַכְּלָיוֹת הֲרֵי הַכּל מֻתָּר מִן הַתּוֹרָה. אֲפִלּוּ חֲתִיכַת נְבֵלָה שֶׁנִּתְעָרְבָה בִּשְׁתֵּי חֲתִיכוֹת שֶׁל שְׁחוּטָה הַכּל מֻתָּר מִן הַתּוֹרָה. אֲבָל מִדִּבְרֵי סוֹפְרִים הַכּל אָסוּר עַד שֶׁיֹאבַד דָּבָר הָאָסוּר מֵעֹצֶם מִעוּטוֹ וְלֹא יִהְיֶה דָּבָר חָשׁוּב שֶׁעֵינוֹ עוֹמֶדֶת כְּמוֹ שֶׁיִּתְבָּאֵר:","וּבְכַמָּה יִתְעָרֵב דָּבָר הָאָסוּר וְיֹאבַד בְּעֹצֶם מִעוּטוֹ. כַּשִּׁעוּר שֶׁנָּתְנוּ בּוֹ חֲכָמִים. יֵשׁ דָּבָר שֶׁשִּׁעוּרוֹ בְּשִׁשִּׁים. וְיֵשׁ שֶׁשִּׁעוּרוֹ בְּמֵאָה. וְיֵשׁ שֶׁשִּׁעוּרוֹ בְּמָאתַיִם:","נִמְצֵאתָ לָמֵד שֶׁכָּל אִסּוּרִין שֶׁבַּתּוֹרָה. בֵּין אִסּוּרֵי מַלְקוֹת. בֵּין אִסּוּרֵי כָּרֵת. בֵּין אִסּוּרֵי הֲנָיָה. שֶׁנִּתְעָרְבוּ בַּמַּאֲכָל הַמֻּתָּר מִין בְּשֶׁאֵינוֹ מִינוֹ בְּנוֹתֵן טַעַם. מִין בְּמִינוֹ שֶׁאִי אֶפְשָׁר לַעֲמֹד עַל הַטַּעַם שִׁעוּרוֹ בְּשִׁשִּׁים אוֹ בְּמֵאָה אוֹ בְּמָאתַיִם. חוּץ מִיֵּין נֶסֶךְ מִפְּנֵי חֻמְרַת עַבוֹדָה זָרָה. וְחוּץ מִטֶּבֶל שֶׁהֲרֵי אֶפְשָׁר לְתַקְּנוֹ. וּמִפְּנֵי זֶה אוֹסְרִין בְּמִינָן בְּכָל שֶׁהֵן. וְשֶׁלֹּא בְּמִינָן בְּנוֹתֵן טַעַם כִּשְׁאָר כָּל הָאִסּוּרִין:","כֵּיצַד. טִפַּת יֵין נֶסֶךְ שֶׁנָּפְלוּ עָלֶיהָ כַּמָּה חָבִיּוֹת שֶׁל יַיִן הַכּל אָסוּר כְּמוֹ שֶׁיִּתְבָּאֵר. וְכֵן כּוֹס שֶׁל יֵין טֶבֶל שֶׁנִּתְעָרֵב בְּחָבִית הַכּל טֶבֶל עַד שֶׁיַּפְרִישׁ תְּרוּמוֹת וּמַעַשְׂרוֹת הָרְאוּיִין לְתַעֲרֹבֶת כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:","פֵּרוֹת שְׁבִיעִית אַף עַל פִּי שֶׁאִם נִתְעָרְבוּ בְּמִינָן בְּכָל שֶׁהוּא וְשֶׁלֹּא בְּמִינָן בְּנוֹתֵן טַעַם אֵינָן בִּכְלָל אִסּוּרֵי תּוֹרָה שֶׁאֵין אוֹתָהּ הַתַּעֲרֹבֶת אֲסוּרָה. אֶלָּא חַיָּב לֶאֱכל כָּל הַתַּעֲרֹבֶת בִּקְדֻשַּׁת שְׁבִיעִית כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:","חָמֵץ בְּפֶסַח אַף עַל פִּי שֶׁהוּא מֵאִסּוּרֵי תּוֹרָה אֵינוֹ בִּכְלָלוֹת אֵלּוּ. לְפִי שֶׁאֵין הַתַּעֲרֹבֶת אֲסוּרָה לְעוֹלָם שֶׁהֲרֵי לְאַחַר הַפֶּסַח תִּהְיֶה כָּל הַתַּעֲרֹבֶת מֻתֶּרֶת כְּמוֹ שֶׁבֵּאַרְנוּ. לְפִיכָךְ אוֹסֵר בְּכָל שֶׁהוּא בֵּין בְּמִינוֹ בֵּין שֶׁלֹּא בְּמִינוֹ:","וְהוּא הַדִּין לִתְבוּאָה חֲדָשָׁה שֶׁנִּתְעָרְבָה בִּישָׁנָה מִלִּפְנֵי הָעֹמֶר אוֹסֶרֶת בְּכָל שֶׁהוּא. שֶׁהֲרֵי יֵשׁ לָהּ מַתִּירִין שֶׁלְּאַחַר הָעֹמֶר יֻתַּר הַכּל. וְכֵן כָּל דָּבָר שֶׁיֵּשׁ לוֹ מַתִּירִין וַאֲפִלּוּ הָיָה אִסּוּרוֹ מִדִּבְרֵיהֶם כְּגוֹן אִסּוּר מֻקְצֶה וְנוֹלָד בְּיוֹם טוֹב לֹא נָתְנוּ בּוֹ חֲכָמִים שִׁעוּר אֶלָּא אֲפִלּוּ אֶחָד בְּכַמָּה אֲלָפִים אֵינוֹ בָּטֵל. שֶׁהֲרֵי יֵשׁ דֶּרֶךְ שֶׁיֻּתַּר בָּהּ כְּגוֹן הֶקְדֵּשׁ וּמַעֲשֵׂר שֵׁנִי וְכַיּוֹצֵא בָּהֶן:","אֲבָל הָעָרְלָה וְכִלְאֵי הַכֶּרֶם וְחֵלֶב וְדָם וְכַיּוֹצֵא בָּהֶן וְכֵן תְּרוּמוֹת נָתְנוּ חֲכָמִים בָּהֶן שִׁעוּר שֶׁאֵין בָּהֶן דֶּרֶךְ הֶתֵּר לְכָל אָדָם:","יֵרָאֶה לִי שֶׁאֲפִלּוּ דָּבָר שֶׁיֵּשׁ לוֹ מַתִּירִין אִם נִתְעָרֵב בְּשֶׁאֵינוֹ מִינוֹ וְלֹא נָתַן טַעַם מֻתָּר. לֹא יִהְיֶה זֶה שֶׁיֵּשׁ לוֹ מַתִּירִין חָמוּר מִטֶּבֶל שֶׁהֲרֵי אֶפְשָׁר לְתַקְּנוֹ וְאַף עַל פִּי כֵּן שֶׁלֹּא בְּמִינוֹ בְּנוֹתֵן טַעַם כְּמוֹ שֶׁבֵּאַרְנוּ. וְאַל תִּתְמַהּ עַל חָמֵץ בְּפֶסַח שֶׁהַתּוֹרָה אָמְרָה (שמות יב כ) \"כָּל מַחְמֶצֶת לֹא תֹאכֵלוּ\" לְפִיכָךְ הֶחְמִירוּ בּוֹ כְּמוֹ שֶׁבֵּאַרְנוּ:","וְאֵלּוּ הֵן הַשִּׁעוּרִין שֶׁנָּתְנוּ חֲכָמִים. הַתְּרוּמָה וּתְרוּמַת מַעֲשֵׂר וְהַחַלָּה וְהַבִּכּוּרִים עוֹלִין בְּאֶחָד וּמֵאָה וְצָרִיךְ לְהָרִים וּמִצְטָרְפִין זֶה עִם זֶה. וְכֵן פְּרוּסָה שֶׁל לֶחֶם הַפָּנִים לְתוֹךְ פְּרוּסוֹת שֶׁל חֻלִּין עוֹלִין בְּאֶחָד וּמֵאָה. כֵּיצַד. סְאָה קֶמַח מֵאֶחָד מֵאֵלּוּ. אוֹ סְאָה מִכֻּלָּם שֶׁנָּפְלָה לְמֵאָה סְאָה קֶמַח שֶׁל חֻלִּין וְנִתְעָרֵב הַכּל. מֵרִים מִן הַכּל סְאָה אַחַת כְּנֶגֶד סְאָה שֶׁנָּפְלָה וְהַשְּׁאָר מֻתָּר לְכָל אָדָם. נָפְלָה לְפָחוֹת מִמֵּאָה נַעֲשֶׂה הַכּל מְדֻמָּע:","הָעָרְלָה וְכִלְאֵי הַכֶּרֶם עוֹלִין בְּאֶחָד וּמָאתַיִם וּמִצְטָרְפִין זֶה עִם זֶה וְאֵינוֹ צָרִיךְ לְהָרִים. כֵּיצַד. רְבִיעִית שֶׁל יֵין עָרְלָה אוֹ כִּלְאֵי הַכֶּרֶם אוֹ שֶׁהָיְתָה הָרְבִיעִית מִצְטָרֶפֶת מִשְּׁנֵיהֶם שֶׁנָּפְלָה לְתוֹךְ מָאתַיִם רְבִיעִיּוֹת שֶׁל יַיִן הַכּל מֻתָּר וְאֵינוֹ צָרִיךְ לְהָרִים כְּלוּם. נָפְלָה לְפָחוֹת מִמָּאתַיִם הַכּל אָסוּר בַּהֲנָיָה:","וְלָמָּה צָרִיךְ לְהָרִים הַתְּרוּמָה וְלֹא יָרִים עָרְלָה וְכִלְאֵי הַכֶּרֶם. שֶׁהַתְּרוּמָה מָמוֹן כֹּהֲנִים. לְפִיכָךְ כָּל תְּרוּמָה שֶׁאֵין הַכֹּהֲנִים מַקְפִּידִין עָלֶיהָ כְּגוֹן תְּרוּמַת הַכְּלִיסִין וְהַחֲרוּבִין וּשְׂעוֹרִין שֶׁבֶּאֱדוֹם אֵינוֹ צָרִיךְ לְהָרִים:","וְלָמָּה כָּפְלוּ שִׁעוּר עָרְלָה וְכִלְאֵי הַכֶּרֶם מִפְּנֵי שֶׁהֵן אֲסוּרִין בַּהֲנָיָה. וְלָמָּה סָמְכוּ עַל שִׁעוּר מֵאָה בִּתְרוּמוֹת שֶׁהֲרֵי תְּרוּמַת מַעֲשֵׂר אֶחָד מִמֵּאָה וּמְקַדֵּשׁ הַכּל שֶׁנֶּאֱמַר (במדבר יח כט) \"אֶת מִקְדְּשׁוֹ מִמֶּנּוּ\" אָמְרוּ חֲכָמִים דָּבָר שֶׁאַתָּה מֵרִים מִמֶּנּוּ אִם חָזַר לְתוֹכוֹ מְקַדְּשׁוֹ:","שְׁאָר אִסּוּרִין שֶׁבַּתּוֹרָה כֻּלָּן כְּגוֹן בְּשַׂר שְׁקָצִים וּרְמָשִׂים וְחֵלֶב וְדָם וְכַיּוֹצֵא בָּהֶן שִׁעוּרָן בְּשִׁשִּׁים. כֵּיצַד. כְּזַיִת חֵלֶב כְּלָיוֹת שֶׁנָּפַל לְתוֹךְ שִׁשִּׁים כְּזַיִת מֵחֵלֶב הָאַלְיָה הַכּל מֻתָּר. נָפַל לְפָחוֹת מִשִּׁשִּׁים הַכּל אָסוּר. וְכֵן אִם נָפַל כִּשְׂעוֹרָה חֵלֶב צָרִיךְ שֶׁיִּהְיֶה שָׁם כְּמוֹ שִׁשִּׁים שְׂעוֹרָה. וְכֵן בִּשְׁאָר אִסּוּרִין. וְכֵן שֻׁמָּן שֶׁל גִּיד הַנָּשֶׁה שֶׁנָּפַל לִקְדֵרָה שֶׁל בָּשָׂר מְשַׁעֲרִין אוֹתוֹ בְּשִׁשִּׁים. וְאֵין שֻׁמַּן הַגִּיד מִן הַמִּנְיָן. וְאַף עַל פִּי שֶׁשֻּׁמַּן גִּיד הַנָּשֶׁה מִדִּבְרֵיהֶם כְּמוֹ שֶׁבֵּאַרְנוּ. הוֹאִיל וְגִיד הַנָּשֶׁה בְּרִיָּה בִּפְנֵי עַצְמָהּ הֶחְמִירוּ בּוֹ כְּאִסּוּרֵי תּוֹרָה. וְהַגִּיד עַצְמוֹ אֵין מְשַׁעֲרִין בּוֹ וְאֵינוֹ אוֹסֵר שֶׁאֵין בַּגִּידִים בְּנוֹתֵן טַעַם:","אֲבָל כְּחַל שֶׁנִתְבַּשֵּׁל עִם הַבָּשָׂר בְּשִׁשִּׁים וּכְחַל מִן הַמִּנְיָן. הוֹאִיל וְהַכְּחַל מִדִּבְרֵיהֶם כְּמוֹ שֶׁבֵּאַרְנוּ הֵקֵלּוּ בְּשִׁעוּרוֹ:","בֵּיצָה שֶׁנִּמְצָא בָּהּ אֶפְרוֹחַ שֶׁנִּשְׁלְקָה עִם בֵּיצִים הַמֻּתָּרוֹת אִם הָיְתָה עִם שִׁשִּׁים וְאַחַת וְהִיא הֲרֵי הֵן מֻתָּרוֹת. הָיְתָה עִם שִׁשִּׁים בִּלְבַד נֶאֶסְרוּ הַכּל מִפְּנֵי שֶׁהִיא בְּרִיָּה בִּפְנֵי עַצְמָהּ עָשׂוּ הֶכֵּר בָּהּ וְהוֹסִיפוּ בְּשִׁעוּרָהּ:","אֲבָל בֵּיצַת עוֹף טָמֵא שֶׁנִּשְׁלְקָה עִם בֵּיצֵי עוֹף טָהוֹר לֹא אָסְרָה אוֹתָם. וְאִם טָרַף אֵלּוּ עִם אֵלּוּ. אוֹ שֶׁנִּתְעָרְבָה בֵּיצַת עוֹף טָמֵא אוֹ בֵּיצַת טְרֵפָה עִם בֵּיצִים אֲחֵרוֹת שִׁעוּרָן בְּשִׁשִּׁים:","וּמִנַּיִן סָמְכוּ חֲכָמִים עַל שִׁעוּר שִׁשִּׁים. שֶׁהֲרֵי הַמּוּרָם מֵאֵיל נָזִיר וְהִיא הַזְּרוֹעַ אֶחָד מִשִּׁשִּׁים מִשְּׁאָר הָאַיִל וְהִיא מִתְבַּשֶּׁלֶת עִמּוֹ וְאֵינָהּ אוֹסֶרֶת אוֹתוֹ שֶׁנֶּאֱמַר (במדבר ו יט) \"וְלָקַח הַכֹּהֵן אֶת הַזְּרֹעַ בְּשֵׁלָה מִן הָאַיִל\":","מִין בְּמִינוֹ וְדָבָר אַחֵר שֶׁנִּתְעָרְבוּ כְּגוֹן קְדֵרָה שֶׁהָיָה בָּהּ חֵלֶב אַלְיָה וּגְרִיסִין וְנָפַל לְתוֹכָהּ חֵלֶב הַכְּלָיוֹת וְנִמְחָה הַכּל וְנַעֲשָׂה גּוּף אֶחָד. רוֹאִין אֶת חֵלֶב הָאַלְיָה וְאֶת הַגְּרִיסִין כְּאִלּוּ הֵן גּוּף אֶחָד וּמְשַׁעֲרִין חֵלֶב הַכְּלָיוֹת בִּגְרִיסִין וּבְאַלְיָּה. אִם הָיָה אֶחָד מִשִּׁשִּׁים מֻתָּר. שֶׁהֲרֵי אִי אֶפְשָׁר כָּאן לַעֲמֹד עַל הַטַּעַם:","וְהוּא הַדִּין לַתְּרוּמוֹת שֶׁנִּתְעָרְבוּ לְשַׁעֲרָן בְּמֵאָה. וְכִלְאֵי הַכֶּרֶם אוֹ עָרְלָה לְשַׁעֵר אוֹתָן בְּמָאתַיִם:","כְּשֶׁמְּשַׁעֲרִין בְּכָל הָאִסּוּרִין בֵּין בְּשִׁשִּׁים בֵּין בְּמֵאָה בֵּין בְּמָאתַיִם. מְשַׁעֲרִין בַּמָּרָק וּבַתַּבְלִין וּבְכָל שֶׁיֵּשׁ בַּקְּדֵרָה וּבְמַה שֶּׁבָּלְעָה קְדֵרָה מֵאַחַר שֶׁנָּפַל הָאִסּוּר לְפִי אֹמֶד הַדַּעַת. שֶׁהֲרֵי אִי אֶפְשָׁר לַעֲמֹד עַל מַה שֶּׁבָּלְעָה בְּצִמְצוּם:","אָסוּר לְבַטֵּל אִסּוּרִין שֶׁל תּוֹרָה לְכַתְּחִלָּה. וְאִם בִּטֵּל הֲרֵי זֶה מֻתָּר. וְאַף עַל פִּי כֵן קָנְסוּ אוֹתוֹ חֲכָמִים וְאָסְרוּ הַכּל. וְיֵרָאֶה לִי שֶׁכֵּיוָן שֶׁהוּא קְנָס אֵין אוֹסְרִין תַּעֲרֹבֶת זוֹ אֶלָּא עַל זֶה הָעוֹבֵר שֶׁבִּטֵּל הָאִסּוּר. אֲבָל לַאֲחֵרִים הַכּל מֻתָּר:","כֵּיצַד. הֲרֵי שֶׁנָּפְלָה סְאָה שֶׁל עָרְלָה לְתוֹךְ מֵאָה סְאָה שֶׁהֲרֵי נֶאֱסַר הַכּל. לֹא יָבִיא מֵאָה סְאָה אֲחֵרוֹת וִיצָרֵף כְּדֵי שֶׁתַּעֲלֶה בְּאֶחָד וּמָאתַיִם. וְאִם עָבַר וְעָשָׂה כֵּן הַכּל מֻתָּר. אֲבָל בְּאִסּוּר שֶׁל דִּבְרֵיהֶם מְבַטְּלִין הָאִסּוּר לְכַתְּחִלָּה:","כֵּיצַד. חָלָב שֶׁנָּפַל לִקְדֵרָה שֶׁיֵּשׁ בָּהּ בְּשַׂר עוֹף וְנָתַן טַעַם בַּקְּדֵרָה מַרְבֶּה עָלָיו בְּשַׂר עוֹף אַחֵר עַד שֶׁיִּבָּטֵל הַטַּעַם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כְּבָר בֵּאַרְנוּ שֶׁאִם נָתַן דָּבָר הָאָסוּר טַעֲמוֹ בְּדָבָר הַמֻּתָּר נֶאֱסַר הַכּל. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהִשְׁבִּיחוֹ. אֲבָל אִם פָּגַם זֶה הָאָסוּר לַמֻּתָּר וְהִפְסִיד טַעֲמוֹ הֲרֵי זֶה מֻתָּר. וְהוּא שֶׁיִּהְיֶה פּוֹגֵם מִתְּחִלָּה וְעַד סוֹף. אֲבָל אִם פָּגַם בַּתְּחִלָּה וְסוֹפוֹ לְהַשְׁבִּיחַ. אוֹ הִשְׁבִּיחַ בַּתְּחִלָּה אַף עַל פִּי שֶׁסּוֹפוֹ לִפְגֹּם הֲרֵי זֶה אָסוּר:","וּמִי יִטְעֹם אֶת הַתַּעֲרֹבֶת. אִם הָיָה הַמְעֹרָב תְּרוּמוֹת עִם הַחֻלִּין טוֹעֵם אוֹתָן הַכֹּהֵן. אִם הָיָה טַעַם הַתְּרוּמָה נִכָּר הַכּל מְדֻמָּע. וּבְהִלְכוֹת תְּרוּמוֹת יִתְבָּאֵר דִּין הַמְדֻמָּע:","וְאִם הָיָה בָּשָׂר בְּחָלָב אוֹ יֵין נֶסֶךְ וְיֵין עָרְלָה וְכִלְאֵי הַכֶּרֶם שֶׁנָּפְלוּ לִדְבַשׁ. אוֹ בְּשַׂר שְׁקָצִים וּרְמָשִׂים שֶׁנִּתְבַּשֵּׁל עִם הָיָּרָק וְכַיּוֹצֵא בָּהֶן. טוֹעֵם אוֹתָן הָעַכּוּ\"ם וְסוֹמְכִין עַל פִּיו. אִם אָמַר אֵין בּוֹ טַעַם אוֹ שֶׁאָמַר יֵשׁ בּוֹ טַעַם וּמִטַּעַם רַע הוּא וַהֲרֵי פְּגָמוֹ הַכּל מֻתָּר. וְהוּא שֶׁלֹּא יִהְיֶה סוֹפוֹ לְהַשְׁבִּיחַ כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִם אֵין שָׁם עַכּוּ\"ם לִטְעֹם מְשַׁעֲרִין אוֹתוֹ בְּשִׁעוּרוֹ בְּשִׁשִּׁים אוֹ בַּמֵּאָה אוֹ בְּמָאתַיִם:","עַכְבָּר שֶׁנָּפַל לְשֵׁכָר אוֹ לְחֹמֶץ מְשַׁעֲרִין אוֹתוֹ בְּשִׁשִּׁים. שֶׁאָנוּ חוֹשְׁשִׁין שֶׁמָּא טַעֲמוֹ בַּשֵּׁכָר וּבַחֹמֶץ מַשְׁבִּיחַ. אֲבָל אִם נָפַל לְיַיִן אוֹ לְשֶׁמֶן אוֹ לִדְבַשׁ מֻתָּר וַאֲפִלּוּ נָתַן טַעַם מִפְּנֵי שֶׁטַּעֲמוֹ פּוֹגֵם. שֶׁכָּל אֵלּוּ צְרִיכִין לִהְיוֹתָן מְבֻשָּׂמִים וְזֶה מַסְרִיחָן וּמַפְסִיד טַעֲמָן:","גְּדִי שֶׁצְּלָאוֹ בְּחֶלְבּוֹ אָסוּר לֶאֱכל אֲפִלּוּ מִקְצֵה אָזְנוֹ. שֶׁהָחֵלֶב נִבְלָע בְּאֵיבָרָיו וְהוּא מַשְׁבִּיחוֹ וְנוֹתֵן בּוֹ טַעַם. לְפִיכָךְ אִם הָיָה כָּחוּשׁ וְלֹא הָיָה בּוֹ חֵלֶב כְּלָיוֹת וְלֹא חֵלֶב קֶרֶב אֶלָּא מְעַט כְּאֶחָד מִשִּׁשִּׁים קוֹלֵף וְאוֹכֵל עַד שֶׁמַּגִּיעַ לַחֵלֶב. וְכֵן יָרֵךְ שֶׁצְּלָאָהּ בְּגִיד הַנָּשֶׁה שֶׁבָּהּ קוֹלֵף וְאוֹכֵל עַד שֶׁהוּא מַגִּיעַ לַגִּיד וּמַשְׁלִיכוֹ. וְכֵן בְּהֵמָה שֶׁצְּלָאָהּ שְׁלֵמָה וְלֹא הֵסִיר לֹא חוּטִין וְלֹא קְרוּמוֹת הָאֲסוּרוֹת קוֹלֵף וְאוֹכֵל. וְכֵיוָן שֶׁיַּגִּיעַ לְדָבָר אָסוּר חוֹתְכוֹ וּמַשְׁלִיכוֹ שֶׁאֵין בַּגִּידִים בְּנוֹתֵן טַעַם כְּדֵי לְשַׁעֵר בָּהֶן:","אֵין צוֹלִין בְּשַׂר שְׁחוּטָה עִם בְּשַׂר נְבֵלָה אוֹ בְּהֵמָה טְמֵאָה בְּתַנּוּר אֶחָד. וְאַף עַל פִּי שֶׁאֵין נוֹגְעִין זֶה בָּזֶה. וְאִם צְלָאָן הֲרֵי זֶה מֻתָּר. וַאֲפִלּוּ הָיְתָה הָאֲסוּרָה שְׁמֵנָה הַרְבֵּה וְהַמֻּתֶּרֶת רָזָה שֶׁהָרֵיחַ אֵינוֹ אוֹסֵר. וְאֵינוֹ אוֹסֵר אֶלָּא טַעֲמוֹ שֶׁל אִסּוּר:","בְּשַׂר נְבֵלָה מָלִיחַ שֶׁנִּבְלַל עִמּוֹ בְּשַׂר שְׁחוּטָה הֲרֵי זֶה נֶאֱסַר. מִפְּנֵי שֶׁתַּמְצִית הַנְּבֵלָה נִבְלַעַת בְּגוּף בְּשַׂר הַשְּׁחוּטָה וְאִי אֶפְשָׁר לַעֲמֹד כָּאן לֹא עַל הַטַּעַם וְלֹא עַל הַשִּׁעוּר. וְכֵן בְּשַׂר דָּג טָמֵא מָלִיחַ שֶׁנִּבְלַל עִמּוֹ דָּג תָּפֵל טָהוֹר נֶאֱסַר מִפְּנֵי צִירוֹ. אֲבָל אִם הָיָה הַמָּלִיחַ טָהוֹר וְהַתָּפֵל דָּג טָמֵא לֹא נֶאֱסַר הַמָּלִיחַ [אַף עַל פִּי] שֶׁהַתָּפֵל בּוֹלֵעַ מִן הַמָּלִיחַ [ אֵינוֹ בּוֹלֵעַ כָּל כָּךְ שֶׁיַּחְזֹר וְיִפְלֹט]. דָּג טָמֵא שֶׁכְּבָשׁוֹ עִם דָּג טָהוֹר הַכּל אָסוּר אֶלָּא אִם כֵּן הָיָה הַטָּמֵא אֶחָד מִמָּאתַיִם מִן הַטָּהוֹר:"],"Mishneh Torah, Forbidden Intercourse 10":["כָּל יוֹלֶדֶת טְמֵאָה כְּנִדָּה וְאַף עַל פִּי שֶׁלֹּא רָאֲתָה דָּם. וְאֶחָד הַיּוֹלֶדֶת חַי אוֹ מֵת אוֹ אֲפִלּוּ נֵפֶל. אִם זָכָר יוֹשֶׁבֶת לְזָכָר וְאִם נְקֵבָה יוֹשֶׁבֶת לִנְקֵבָה וְהוּא שֶׁתִּגָּמֵר צוּרָתוֹ. וְאֵין צוּרַת הַוָּלָד נִגְמֶרֶת לְפָחוֹת מֵאַרְבָּעִים יוֹם אֶחָד הַזָּכָר וְאֶחָד הַנְּקֵבָה:","וְהַמַּפֶּלֶת בְּתוֹךְ אַרְבָּעִים יוֹם אֵינָהּ טְמֵאָה לֵדָה אֲפִלּוּ בְּיוֹם אַרְבָּעִים. הִפִּילָה בְּיוֹם אַרְבָּעִים וְאֶחָד מֵאַחַר הַתַּשְׁמִישׁ הֲרֵי זוֹ סְפֵק יוֹלֶדֶת וְתֵשֵׁב לְזָכָר וְלִנְקֵבָה וּלְנִדָּה. הָיְתָה צוּרַת הָאָדָם דַּקָּה בְּיוֹתֵר וְאֵינָהּ נִכֶּרֶת בַּעֲלִיל הֲרֵי זוֹ תֵּשֵׁב לְזָכָר וְלִנְקֵבָה וְזֶהוּ הַנִּקְרָא שַׁפִּיר מְרֻקָּם:","אֵי זֶה הוּא שַׁפִּיר מְרֻקָּם. תְּחִלַּת בְּרִיָּתוֹ שֶׁל אָדָם גּוּפוֹ כַּעֲדָשָׁה. שְׁתֵּי עֵינָיו כִּשְׁתֵּי טִפֵּי זְבוּב מְרֻחָקוֹת זוֹ מִזּוֹ. שְׁנֵי חֳטָמָיו כִּשְׁתֵּי טִפֵּי זְבוּב מְקֹרָבוֹת זֶה לָזֶה. פִּיו פָּתוּחַ כְּחוּט הַשַּׂעֲרָה. וְחִתּוּךְ יָדַיִם וְרַגְלַיִם אֵין לוֹ. נִתְבָּאֲרָה צוּרָתוֹ יֶתֶר מִזֶּה וַעֲדַיִן אֵינוֹ נִכָּר בֵּין זָכָר לִנְקֵבָה אֵין בּוֹדְקִין אוֹתוֹ בְּמַיִם אֶלָּא בְּשֶׁמֶן שֶׁהַשֶּׁמֶן מְצַחְצְחוֹ. וּמֵבִיא קֵיסָם שֶׁרֹאשׁוֹ חָלָק וּמְנַעְנֵעַ בְּאוֹתוֹ מָקוֹם מִלְּמַעְלָה לְמַטָּה אִם מְסַכְסֵךְ בְּיָדוּעַ שֶׁהוּא זָכָר. וְאִם רָאָה אוֹתוֹ מָקוֹם כִּשְׂעוֹרָה סְדוּקָה הֲרֵי זוֹ נְקֵבָה וְאֵינָהּ צְרִיכָה בְּדִיקָה. וְכָל אֵלּוּ הָרְקִימוֹת שֶׁל נְפָלִים אֵין נוֹתְנִין לָהֶן יְמֵי טֹהַר עַד שֶׁיַּשְׂעִיר הַוָּלָד:","הִפִּילָה חֲתִיכָה לְבָנָה אִם נִקְרְעָה וְנִמְצָא בָּהּ עֶצֶם הֲרֵי זוֹ טְמֵאָה לֵדָה. הִפִּילָה שַׁפִּיר מָלֵא מַיִם מָלֵא דָּם מָלֵא גִּנּוּנִים מָלֵא בָּשָׂר הוֹאִיל וְאֵינוֹ מְרֻקָּם אֵינָהּ חוֹשֶׁשֶׁת לְוָלָד:","יוֹצֵא דֹּפֶן אֵין אִמּוֹ טְמֵאָה לֵדָה וְאֵין לָהּ יְמֵי טֻמְאָה וִימֵי טָהֳרָה שֶׁנֶּאֱמַר (ויקרא יב ב) \"אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר\" עַד שֶׁתֵּלֵד מִמָּקוֹם שֶׁמַּזְרַעַת. הַמַּקְשָׁה וְיָלְדָה וָלָד דֶּרֶךְ הַדֹּפֶן הֲרֵי דַּם הַקֹּשִׁי הַבָּא דֶּרֶךְ הָרֶחֶם זִיבוּת אוֹ נִדָּה וְדָם הַיּוֹצֵא דֶּרֶךְ הַדֹּפֶן טָמֵא. וְאִם לֹא יָצָא דָּם דֶּרֶךְ הָרֶחֶם הֲרֵי הָאִשָּׁה טְהוֹרָה. אַף עַל פִּי שֶׁהַדָּם שֶׁיָּצָא מִדָּפְנָהּ טָמֵא. שֶׁאֵין הָאִשָּׁה טְמֵאָה עַד שֶׁיֵּצֵא מַדְוֶהָ דֶּרֶךְ עֶרְוָתָהּ:","נֶחְתַּךְ הַוָּלָד בְּמֵעֶיהָ וְיָצָא אֵיבָר אֵיבָר. בֵּין שֶׁיָּצָא עַל סֵדֶר הָאֵיבָרִים כְּגוֹן שֶׁיָּצְאָה הָרֶגֶל וְאַחֲרֶיהָ הַשּׁוֹק וְאַחֲרֶיהָ הַיָּרֵךְ. בֵּין שֶׁיָּצָא שֶׁלֹּא עַל הַסֵּדֶר אֵינָהּ טְמֵאָה לֵדָה עַד שֶׁיֵּצֵא רֻבּוֹ. וְאִם יָצָא רֹאשׁוֹ כֻּלּוֹ כְּאֶחָד הֲרֵי זֶה כְּרֻבּוֹ. וְאִם לֹא נֶחְתַּךְ וְיָצָא כְּדַרְכּוֹ מִשֶּׁתֵּצֵא רֹב פַּדַּחְתּוֹ הֲרֵי זֶה כְּיָלוּד אַף עַל פִּי שֶׁנֶּחְתַּךְ אַחַר כָּךְ:","הוֹצִיא הָעֻבָּר אֶת יָדוֹ וְהֶחֱזִירָהּ אִמּוֹ טְמֵאָה לֵדָה מִדִּבְרֵי סוֹפְרִים. וְאֵין לָהּ יְמֵי טֹהַר עַד שֶׁיֵּצֵא הַוָּלָד כֻּלּוֹ אוֹ רֻבּוֹ כְּמוֹ שֶׁאָמַרְנוּ:","הַמַּפֶּלֶת כְּמִין בְּהֵמָה חַיָּה אוֹ עוֹף אִם הָיוּ פָּנָיו כִּפְנֵי אָדָם הֲרֵי זֶה וָלָד. אִם זָכָר תֵּשֵׁב לְזָכָר וְאִם נְקֵבָה תֵּשֵׁב לִנְקֵבָה. וְאִם אֵינוֹ נִכָּר בֵּין זָכָר לִנְקֵבָה תֵּשֵׁב לְזָכָר וְלִנְקֵבָה אַף עַל פִּי שֶׁשְּׁאָר הַגּוּף דּוֹמֶה לִבְהֵמָה אוֹ לְחַיָּה אוֹ לְעוֹף. וְאִם אֵין פָּנָיו כְּצוּרַת פְּנֵי הָאָדָם אַף עַל פִּי שֶׁשְּׁאָר הַגּוּף גּוּף אָדָם שָׁלֵם וְיָדָיו וְרַגְלָיו יְדֵי וְרַגְלֵי אָדָם וַהֲרֵי הוּא זָכָר אוֹ נְקֵבָה אֵינוֹ וָלָד וְאֵין אִמּוֹ טְמֵאָה לֵדָה:","אֵי זוֹ הִיא צוּרַת פְּנֵי הָאָדָם. שֶׁיִּהְיֶה הַמֶּצַח וְהַגְּבִינִין וְהָעֵינַיִם וְהַלְּסָתוֹת וְגַבּוֹת הַזָּקָן כְּצוּרַת הָאָדָם. אֲבָל הַפֶּה וְהָאָזְנַיִם וְהָאַף אַף עַל פִּי שֶׁהֵן כְּשֶׁל בְּהֵמָה וְחַיָּה הֲרֵי זֶה וָלָד:","הַמַּפֶּלֶת דְּמוּת נָחָשׁ אִמּוֹ טְמֵאָה לֵדָה מִפְּנֵי שֶׁגַּלְגַּל עֵינָיו עָגל כְּשֶׁל אָדָם. הַמַּפֶּלֶת דְּמוּת אָדָם שֶׁיֵּשׁ לוֹ כְּנָפַיִם שֶׁל בָּשָׂר אִמּוֹ טְמֵאָה לֵדָה. נִבְרָא בְּעַיִן אַחַת וְיָרֵךְ אַחַת אִם הָיוּ מִן הַצַּד הֲרֵי הוּא כַּחֲצִי אָדָם וְאִמּוֹ טְמֵאָה לֵדָה. וְאִם הָיוּ בָּאֶמְצַע אִמּוֹ טְהוֹרָה שֶׁהֲרֵי זוֹ בְּרִיָּה אַחֶרֶת:","נִבְרָא וֵשֶׁט שֶׁלּוֹ אָטוּם אוֹ שֶׁהָיָה חָסֵר מִטִּבּוּרוֹ וּלְמַטָּה וַהֲרֵי הוּא אָטוּם. אוֹ שֶׁהָיְתָה גֻּלְגָּלְתּוֹ אֲטוּמָה. אוֹ שֶׁהָיוּ פָּנָיו טוּחוֹת וְאֵין בָּהֶן הֶכֵּר פָּנִים. אוֹ שֶׁיֵּשׁ לוֹ שְׁנֵי גַּבִּין וּשְׁתֵּי שְׁדֵרוֹת. אוֹ שֶׁהִפִּילָה בְּרִיַּת רֹאשׁ שֶׁאֵינוֹ חָתוּךְ. אוֹ יָד שֶׁאֵינוֹ חָתוּךְ. כָּל נֵפֶל מֵאֵלּוּ אֵינוֹ וָלָד וְאֵין אִמּוֹ טְמֵאָה לֵדָה. אֲבָל אִם הִפִּילָה יָד חֲתוּכָה וְרֶגֶל חֲתוּכָה הֲרֵי חֶזְקָתָהּ מִוָּלָד שָׁלֵם וּמִצְטָרְפִין לְרֹב אֵיבָרָיו:","פְּעָמִים יִקְפֶּה מִשְּׁאָר הַדָּמִים שֶׁנּוֹצַר מֵהֶם הָאָדָם חֲתִיכָה כְּמוֹ לְשׁוֹן הַשּׁוֹר וְתִהְיֶה כְּרוּכָה עַל מִקְצָת הַוָּלָד וְהִיא הַנִּקְרֵאת סַנְדָּל. וּלְעוֹלָם לֹא יֵעָשֶׂה סַנְדָּל זֶה אֶלָּא עִם וָלָד. אֲבָל חֲתִיכָה שֶׁנּוֹצְרָה לְבַדָּהּ בְּלֹא וָלָד אֵינָהּ נִקְרֵאת סַנְדָּל. וְרֹב הָעֻבָּרִים לֹא יִהְיֶה עִמָּהֶם סַנְדָּל. וּפְעָמִים יַכֶּה הַמְעֻבֶּרֶת דָּבָר עַל בִּטְנָהּ וְיִפָּסֵד הָעֻבָּר וְיֵעָשֶׂה כְּסַנְדָּל זֶה. וּפְעָמִים יִשָּׁאֵר בּוֹ הֶכֵּר פָּנִים וּפְעָמִים יִיבַשׁ הַוָּלָד וְיִשְׁתַּנֶּה וְיִקְפְּאוּ עָלָיו הַדָּמִים עַד שֶׁלֹּא יִשָּׁאֵר בּוֹ הֶכֵּר פָּנִים. לְפִיכָךְ הַמַּפֶּלֶת זָכָר וְסַנְדָּל עִמּוֹ אַף עַל פִּי שֶׁאֵין הֶכֵּר פָּנִים לַסַּנְדָּל הֲרֵי זוֹ תֵּשֵׁב לְזָכָר וְלִנְקֵבָה שֶׁמָּא סַנְדָּל זֶה נְקֵבָה הָיָה. וְחֻמְרָא הֶחְמִירוּ בּוֹ לְטַמְּאָהּ בּוֹ מִשּׁוּם וָלָד אַף עַל פִּי שֶׁאֵין בּוֹ צוּרַת פָּנִים הוֹאִיל וְהִיא טְמֵאָה לֵדָה מִפְּנֵי הַוָּלָד שֶׁעִמּוֹ:","הַחוֹתֶלֶת הֶעָבָה שֶׁהִיא כְּמוֹ חֵמֶת שֶׁבְּתוֹכָהּ נוֹצָר הַוָּלָד וְהִיא מַקֶּפֶת אוֹתוֹ וְאֶת הַסַּנְדָּל אִם הָיָה עִמּוֹ סַנְדָּל וּכְשֶׁיַּגִּיעַ זְמַנּוֹ לָצֵאת קוֹרֵעַ אוֹתָהּ וְיוֹצֵא הִיא הַנִּקְרֵאת שִׁלְיָא. וּתְחִלַּת בְּרִיָּתָהּ דּוֹמָה לְחוּט שֶׁל עֵרֶב וַחֲלוּלָה כַּחֲצוֹצֶרֶת וְעָבָה כְּקֻרְקְבָן הַתַּרְנְגוֹלִים. וְאֵין שִׁלְיָא פְּחוּתָה מִטֶּפַח:","הַמַּפֶּלֶת שִׁלְיָא תֵּשֵׁב לְזָכָר וְלִנְקֵבָה. לֹא שֶׁהַשִּׁלְיָא וָלָד אֶלָּא שֶׁאֵין שִׁלְיָא בְּלֹא וָלָד. הִפִּילָה נֵפֶל וְאַחַר כָּךְ הִפִּילָה שִׁלְיָא חוֹשְׁשִׁין לַשִּׁלְיָא וַהֲרֵי הוּא כְּוָלָד אַחֵר וְאֵין אוֹמְרִין זוֹ שִׁלְיַת הַנֵּפֶל. שֶׁאֵין תּוֹלִין אֶת הַשִּׁלְיָא אֶלָּא בְּוָלָד שֶׁל קַיָּמָא. לְפִיכָךְ אִם יָלְדָה וָלָד שֶׁל קַיָּמָא וְהִפִּילָה שִׁלְיָא אֲפִלּוּ אַחַר כ\"ג יוֹם תּוֹלִין אוֹתוֹ בַּוָּלָד וְאֵין חוֹשְׁשִׁין לְוָלָד אַחֵר. שֶׁהַוָּלָד קָרַע הַשִּׁלְיָא וְיָצָא:","הִפִּילָה שִׁלְיָא תְּחִלָּה וְאַחַר כָּךְ יָלְדָה וָלָד שֶׁל קַיָּמָא חוֹשְׁשִׁין לַשִּׁלְיָא שֶׁהִיא וָלָד אַחֵר וְאֵין תּוֹלִין אוֹתָהּ בַּוָּלָד הַבָּא אַחֲרֶיהָ. שֶׁאֵין דַּרְכָּהּ שֶׁל שִׁלְיָא לָצֵאת לִפְנֵי הַוָּלָד. יָצָאת מִקְצָת הַשִּׁלְיָא בַּיּוֹם הָרִאשׁוֹן וּמִקְצָתָהּ בַּשֵּׁנִי מוֹנִין לָהּ מִיּוֹם הָרִאשׁוֹן וְאֵין נוֹתְנִין לָהּ יְמֵי טָהֳרָה אֶלָּא מִיּוֹם שֵׁנִי לְהַחֲמִיר:","הִפִּילָה דְּמוּת בְּהֵמָה חַיָּה וְעוֹף וְשִׁלְיָא קְשׁוּרָה בּוֹ אֵין חוֹשְׁשִׁין לְוָלָד. וְאִם אֵינָהּ קְשׁוּרָה בּוֹ מְטִילִין עָלֶיהָ חֹמֶר שְׁתֵּי וְלָדוֹת שֶׁאֲנִי אוֹמֵר שֶׁמָּא נִמּוֹחַ שַׁפִּיר מְרֻקָּם שֶׁהָיָה בְּשִׁלְיָא זוֹ וְשֶׁמָּא נִמּוֹחָה הַשִּׁלְיָא שֶׁל שַׁפִּיר זֶה שֶׁהוּא דְּמוּת בְּהֵמָה וְחַיָּה:","כָּל אֵלּוּ שֶׁחוֹשְׁשִׁין לְשִׁלְיָא אֵין נוֹתְנִין לָהֶן יְמֵי טֹהַר. וְכָל מִי שֶׁהִפִּילָה דָּבָר שֶׁאֵינוֹ וָלָד אוֹ שַׁפִּיר בְּתוֹךְ אַרְבָּעִים יוֹם שֶׁעֲדַיִן לֹא נִגְמְרָה צוּרָתוֹ אִם יָצָא עִמּוֹ דָּם הֲרֵי זוֹ נִדָּה אוֹ זָבָה. וְאִם יָצָא יָבֵשׁ בְּלֹא דָּם הֲרֵי זוֹ טְהוֹרָה:","מִי שֶׁיָּלְדָה זָכָר וּנְקֵבָה תְּאוֹמִים תֵּשֵׁב לִנְקֵבָה. יָלְדָה טֻמְטוּם אוֹ אַנְדְּרוֹגִינוּס תֵּשֵׁב לְזָכָר וְלִנְקֵבָה. יָלְדָה תְּאוֹמִים אֶחָד זָכָר וְהַשֵּׁנִי טֻמְטוּם אוֹ אַנְדְּרוֹגִינוּס תֵּשֵׁב לְזָכָר וְלִנְקֵבָה. הָאַחַת נְקֵבָה וְהַשֵּׁנִי טֻמְטוּם אוֹ אַנְדְּרוֹגִינוּס תֵּשֵׁב לִנְקֵבָה בִּלְבַד. שֶׁהַטֻּמְטוּם וְהָאַנְדְּרוֹגִינוּס סָפֵק הֵן שֶׁמָּא זָכָר הֵן שֶׁמָּא נְקֵבָה:","הָאִשָּׁה שֶׁהֻחְזְקָה מְעֻבֶּרֶת וְיָלְדָה וְאֵין יָדוּעַ מַה יָּלְדָה כְּגוֹן שֶׁעָבְרָה לַנָּהָר וְהִפִּילָה שָׁם אוֹ שֶׁהִפִּילָה לְבוֹר אוֹ שֶׁהִפִּילָה וּגְרָרַתּוּ חַיָּה הֲרֵי זוֹ בְּחֶזְקַת שֶׁהִפִּילָה וָלָד וְתֵשֵׁב לְזָכָר וְלִנְקֵבָה. אֲבָל אִם לֹא הֻחְזְקָה מְעֻבֶּרֶת וְהִפִּילָה וְאֵין יָדוּעַ מַה הִפִּילָה הֲרֵי זֶה סְפֵק יוֹלֶדֶת וְתֵשֵׁב לְזָכָר וְלִנְקֵבָה וּלְנִדָּה:","כָּל מָקוֹם שֶׁנֶּאֱמַר (ויקרא יב ד) \"תֵּשֵׁב\" לְזָכָר וְלִנְקֵבָה כֵּיצַד דִּינָה. תִּהְיֶה אֲסוּרָה לְבַעְלָהּ י\"ד יוֹם כְּיוֹלֶדֶת נְקֵבָה. שִׁבְעָה הָרִאשׁוֹנִים וַדַּאי. וְהַשִּׁבְעָה הָאַחֲרוֹנִים סָפֵק. וְאֵין נוֹתְנִין לָהּ יְמֵי טֹהַר אֶלָּא עַד אַרְבָּעִים יוֹם כְּיוֹלֶדֶת זָכָר. וְאִם רָאֲתָה דָּם אַחַר הָאַרְבָּעִים עַד שְׁמוֹנִים אֵינוֹ דַּם טֹהַר אֶלָּא סְפֵק דַּם נִדָּה אוֹ סְפֵק דַּם זִיבוּת אִם בָּא מִימֵי הַזִּיבָה כְּמוֹ שֶׁבֵּאַרְנוּ. וְכֵן אִם רָאֲתָה דָּם יוֹם אֶחָד וּשְׁמוֹנִים בִּלְבַד הֲרֵי זוֹ סְפֵק נִדָּה וְתֵשֵׁב שִׁבְעַת יְמֵי הַנִּדָּה שֶׁמָּא נְקֵבָה יָלְדָה שֶׁאֵין לָהּ וֶסֶת נִדּוּת עַד אַחַר מְלֹאת כְּמוֹ שֶׁבֵּאַרְנוּ:","כָּל מָקוֹם שֶׁנֶּאֱמַר (ויקרא יב ד) \"תֵּשֵׁב\" לְזָכָר וְלִנְקֵבָה וּלְנִדָּה כֵּיצַד דִּינָה. תִּהְיֶה אֲסוּרָה לְבַעְלָהּ י\"ד יוֹם כְּיוֹלֶדֶת נְקֵבָה. וְאִם רָאֲתָה דָּם בְּיוֹם אֶחָד וּשְׁמוֹנִים הֲרֵי זוֹ סְפֵק נִדָּה. וְכֵן אִם רָאֲתָה בְּיוֹם ע\"ד וּבְיוֹם פ\"א הֲרֵי זוֹ סְפֵק נִדָּה. וְכֵן אִם רָאֲתָה בְּיוֹם אַרְבָּעִים וְאֶחָד אַף עַל פִּי שֶׁרָאֲתָה בְּיוֹם ל\"ד הֲרֵי זוֹ סְפֵק נִדָּה וַאֲסוּרָה לְבַעְלָהּ עַד לֵיל אַרְבָּעִים וּשְׁמוֹנָה כְּיוֹלֶדֶת זָכָר. וְאֵין נוֹתְנִין לָהּ יְמֵי טֹהַר כְּלָל כְּנִדָּה. וַהֲרֵי הִיא כְּמִי שֶׁלֹּא יָלְדָה. וְכָל דָּם שֶׁתִּרְאֶה מִיּוֹם שֶׁהִפִּילָה עַד שְׁמֹנִים יוֹם אִם בָּא בִּימֵי נִדָּתָהּ הֲרֵי זוֹ סְפֵק נִדָּה מֵאַחַר הַשִּׁבְעָה מִיּוֹם שֶׁהִפִּילָה. וְאִם בָּא בִּימֵי זִיבָתָהּ הֲרֵי זוֹ סְפֵק זָבָה שֶׁכָּל יְמֵי מְלֹאת אֵין בָּהֶן וֶסֶת. וְכֵן אִם רָאֲתָה בְּיוֹם אֶחָד וּשְׁמוֹנִים עֲדַיִן הִיא מְקֻלְקֶלֶת וְתִהְיֶה סְפֵק נִדָּה כְּמוֹ שֶׁבֵּאַרְנוּ אַף עַל פִּי שֶׁלֹּא רָאֲתָה אֶלָּא יוֹם אֶחָד וּכְשֶׁיִּקָּבַע לָהּ הַוֶּסֶת אַחַר הַשְּׁמוֹנִים יָסוּר קִלְקוּלָהּ וְתַחֲזֹר לִהְיוֹת נִדָּה וַדָּאִית אוֹ זָבָה וַדָּאִית. וְכֵן מִיּוֹם שֶׁהִפִּילָה עַד שִׁבְעָה יָמִים וְתִהְיֶה נִדָּה וַדָּאִית אִם הִפִּילָה בְּתוֹךְ יְמֵי נִדָּתָהּ כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Forbidden Intercourse 21":["כָּל הַבָּא עַל עֶרְוָה מִן הָעֲרָיוֹת דֶּרֶךְ אֵיבָרִים אוֹ שֶׁחִבֵּק וְנִשֵּׁק דֶּרֶךְ תַּאֲוָה וְנֶהֱנָה בְּקֵרוּב בָּשָׂר הֲרֵי זֶה לוֹקֶה מִן הַתּוֹרָה. שֶׁנֶּאֱמַר (ויקרא יח ל) \"לְבִלְתִּי עֲשׂוֹת מֵחֻקּוֹת הַתּוֹעֵבֹת\" וְגוֹ'. וְנֶאֱמַר (ויקרא יח ו) \"לֹא תִקְרְבוּ לְגַלּוֹת עֶרְוָה\". כְּלוֹמַר לֹא תִּקְרְבוּ לִדְבָרִים הַמְּבִיאִין לִידֵי גִּלּוּי עֶרְוָה:","הָעוֹשֶׂה דָּבָר מֵחֻקּוֹת אֵלּוּ הֲרֵי הוּא חָשׁוּד עַל הָעֲרָיוֹת. וְאָסוּר לָאָדָם לִקְרֹץ בְּיָדָיו וּבְרַגְלָיו אוֹ לִרְמֹז בְּעֵינָיו לְאַחַת מִן הָעֲרָיוֹת אוֹ לִשְׂחֹק עִמָּהּ אוֹ לְהָקֵל רֹאשׁ. וַאֲפִלּוּ לְהָרִיחַ בְּשָׂמִים שֶׁעָלֶיהָ אוֹ לְהַבִּיט בְּיָפְיָהּ אָסוּר. וּמַכִּין לַמִּתְכַּוֵּן לְדָבָר זֶה מַכַּת מַרְדּוּת. וְהַמִּסְתַּכֵּל אֲפִלּוּ בְּאֶצְבַּע קְטַנָּה שֶׁל אִשָּׁה וְנִתְכַּוֵּן לֵהָנוֹת כְּמִי שֶׁנִּסְתַּכֵּל בִּמְקוֹם הַתֹּרֶף. וַאֲפִלּוּ לִשְׁמֹעַ קוֹל הָעֶרְוָה אוֹ לִרְאוֹת שְׂעָרָהּ אָסוּר:","וְהַדְּבָרִים הָאֵלּוּ אֲסוּרִין בְּחַיָּבֵי לָאוִין. וּמֻתָּר לְהִסְתַּכֵּל בִּפְנֵי הַפְּנוּיָה וּלְבָדְקָהּ בֵּין בְּתוּלָה בֵּין בְּעוּלָה כְּדֵי שֶׁיִּרְאֶה אִם הִיא נָאָה בְּעֵינָיו יִשָּׂאֶנָּה וְאֵין בָּזֶה צַד אִסּוּר וְלֹא עוֹד אֶלָּא שֶׁרָאוּי לַעֲשׂוֹת כֵּן. אֲבָל לֹא יִסְתַּכֵּל דֶּרֶךְ זְנוּת. הֲרֵי הוּא אוֹמֵר (איוב לא א) \"בְּרִית כָּרַתִּי לְעֵינַי וּמָה אֶתְבּוֹנֵן עַל בְּתוּלָה\":","וּמֻתָּר לָאָדָם לְהַבִּיט בְּאִשְׁתּוֹ כְּשֶׁהִיא נִדָּה וְאַף עַל פִּי שֶׁהִיא עֶרְוָה. וְאַף עַל פִּי שֶׁיֵּשׁ לוֹ הֲנָאַת לֵב מִמֶּנָּה בִּרְאִיָּה הוֹאִיל וְהִיא מֻתֶּרֶת לוֹ לְאַחַר זְמַן אֵינוֹ בָּא בָּזֶה לִדְבַר מִכְשׁוֹל. אֲבָל לֹא יִשְׂחֹק וְלֹא יָקֵל רֹאשׁ עִמָּהּ שֶׁמָּא יַרְגִּיל לַעֲבֵרָה:","אָסוּר לְהִשְׁתַּמֵשׁ בְּאִשָּׁה כְּלָל בֵּין גְּדוֹלָה בֵּין קְטַנָּה בֵּין שִׁפְחָה בֵּין מְשֻׁחְרֶרֶת שֶׁמָּא יָבוֹא לִידֵי הִרְהוּר. בְּאֵי זֶה שִׁמּוּשׁ אָמְרוּ רְחִיצַת פָּנָיו יָדָיו וְרַגְלָיו וְהַצָּעַת מִטָּה לְפָנָיו וּמְזִיגַת הַכּוֹס. שֶׁאֵין עוֹשָׂה לְאִישׁ דְּבָרִים אֵלּוּ אֶלָּא אִשְׁתּוֹ בִּלְבַד. וְאֵין שׁוֹאֲלִין בִּשְׁלוֹם אִשָּׁה כְּלָל וַאֲפִלּוּ עַל יְדֵי שָׁלִיחַ:","הַמְחַבֵּק אַחַת מִן הָעֲרָיוֹת שֶׁאֵין לִבּוֹ שֶׁל אָדָם נוֹקְפוֹ עֲלֵיהֶן אוֹ שֶׁנִּשֵּׁק לְאַחַת מֵהֶן כְּגוֹן אֲחוֹתוֹ הַגְּדוֹלָה וַאֲחוֹת אִמּוֹ וְכַיּוֹצֵא בָּהֶן אַף עַל פִּי שֶׁאֵין שָׁם תַּאֲוָה וְלֹא הֲנָאָה כְּלָל הֲרֵי זֶה מְגֻנֶּה בְּיוֹתֵר וְדָבָר אָסוּר הוּא וּמַעֲשֵׂה טִפְּשִׁים הוּא. שֶׁאֵין קְרֵבִין לְעֶרְוָה כְּלָל בֵּין גְּדוֹלָה בֵּין קְטַנָּה חוּץ מֵהָאֵם לִבְנָהּ וְהָאָב לְבִתּוֹ:","כֵּיצַד. מֻתָּר הָאָב לְחַבֵּק בִּתּוֹ וּלְנַשְּׁקָהּ וְתִישַׁן עִמּוֹ בְּקֵרוּב בָּשָׂר. וְכֵן הָאֵם עִם בְּנָהּ כָּל זְמַן שֶׁהֵם קְטַנִּים. הִגְדִּילוּ וְנַעֲשָׂה הַבֵּן גָּדוֹל וְהַבַּת גְּדוֹלָה עַד שֶׁיִּהְיוּ שָׁדַיִם נָכֹנוּ וּשְׂעָרֵךְ צָמַח זֶה יָשֵׁן בִּכְסוּתוֹ וְהִיא יְשֵׁנָה בִּכְסוּתָהּ. וְאִם הָיְתָה הַבַּת בּוֹשָׁה לַעֲמֹד לִפְנֵי אָבִיהָ עֲרֻמָּה אוֹ שֶׁנִּשֵּׂאת. וְכֵן אִם הָאֵם בּוֹשָׁה לַעֲמֹד בִּפְנֵי בְּנָהּ עֲרֻמָּה וְאַף עַל פִּי שֶׁהֵן קְטַנִּים מִשֶּׁהִגִּיעוּ לְהִכָּלֵם מֵהֶן אֵין יְשֵׁנִים עִמָּהֶם אֶלָּא בִּכְסוּתָן:","נָשִׁים הַמְסוֹלָלוֹת זוֹ בָּזוֹ אָסוּר וּמִמַּעֲשֵׂה מִצְרַיִם הוּא שֶׁהֻזְהַרְנוּ עָלָיו שֶׁנֶּאֱמַר (ויקרא יח ג) \"כְּמַעֲשֵׂה אֶרֶץ מִצְרַיִם לֹא תַעֲשׂוּ\". אָמְרוּ חֲכָמִים מֶה הָיוּ עוֹשִׂים אִישׁ נוֹשֵׂא אִישׁ וְאִשָּׁה נוֹשֵׂא אִשָּׁה. וְאִשָּׁה נִשֵּׂאת לִשְׁנֵי אֲנָשִׁים. אַף עַל פִּי שֶׁמַּעֲשֶׂה זֶה אָסוּר אֵין מַלְקִין עָלָיו. שֶׁאֵין לוֹ לָאו מְיֻחָד וַהֲרֵי אֵין שָׁם בִּיאָה כְּלָל. לְפִיכָךְ אֵין נֶאֱסָרוֹת לִכְהֻנָּה מִשּׁוּם זְנוּת וְלֹא תֵּאָסֵר אִשָּׁה עַל בַּעְלָהּ בָּזֶה שֶׁאֵין כָּאן זְנוּת. וְרָאוּי לְהַכּוֹתָן מַכַּת מַרְדּוּת הוֹאִיל וְעָשׂוּ אִסּוּר. וְיֵשׁ לָאִישׁ לְהַקְפִּיד עַל אִשְׁתּוֹ מִדָּבָר זֶה וּמוֹנֵעַ הַנָּשִׁים הַיְדוּעוֹת בְּכָךְ מִלְּהִכָּנֵס לָהּ וּמִלָּצֵאת הִיא אֲלֵיהֶן:","אִשְׁתּוֹ שֶׁל אָדָם מֻתֶּרֶת הִיא לוֹ. לְפִיכָךְ כָּל מַה שֶּׁאָדָם רוֹצֶה לַעֲשׂוֹת בְּאִשְׁתּוֹ עוֹשֶׂה. בּוֹעֵל בְּכָל עֵת שֶׁיִּרְצֶה וּמְנַשֵּׁק בְּכָל אֵיבָר וְאֵיבָר שֶׁיִּרְצֶה. [וּבָא עָלֶיהָ כְּדַרְכָּהּ וְשֶׁלֹּא כְּדַרְכָּהּ ] וּבִלְבַד שֶׁלֹּא יוֹצִיא שִׁכְבַת זֶרַע לְבַטָּלָה. וְאַף עַל פִּי כֵן מִדַּת חֲסִידוּת שֶׁלֹּא יָקֵל אָדָם אֶת רֹאשׁוֹ לְכָךְ וְשֶׁיְּקַדֵּשׁ עַצְמוֹ בִּשְׁעַת תַּשְׁמִישׁ כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת דֵּעוֹת. וְלֹא יָסוּר מִדֶּרֶךְ הָעוֹלָם וּמִנְהָגוֹ שֶׁאֵין דָּבָר זֶה אֶלָּא כְּדֵי לִפְרוֹת וְלִרְבּוֹת:","אָסוּר לָאָדָם לְשַׁמֵּשׁ מִטָּתוֹ לְאוֹר הַנֵּר. הֲרֵי שֶׁהָיְתָה שַׁבָּת וְלֹא הָיָה לוֹ בַּיִת אַחֵר וְהָיָה הַנֵּר דָּלוּק הֲרֵי זֶה לֹא יְשַׁמֵּשׁ כְּלָל. וְכֵן אָסוּר לְיִשְׂרְאֵלִי לְשַׁמֵּשׁ מִטָּתוֹ בַּיּוֹם. שֶׁעַזּוּת פָּנִים הִיא לוֹ. וְאִם הָיָה תַּלְמִיד חָכָם שֶׁאֵינוֹ בָּא לְהִמָּשֵׁךְ בְּכָךְ הֲרֵי זֶה מַאֲפִיל בְּטַלִּיתוֹ וּמְשַׁמֵּשׁ. וְאֵין נִזְקָקִין לְדָבָר זֶה אֶלָּא מִפְּנֵי צֹרֶךְ גָּדוֹל. וְדֶרֶךְ קְדֻשָּׁה לְשַׁמֵּשׁ בְּאֶמְצַע הַלַּיְלָה:","אֵין דַּעַת חֲכָמִים נוֹחָה לְמִי שֶׁהוּא מַרְבֶּה בַּתַּשְׁמִישׁ הַמִּטָּה וְיִהְיֶה מָצוּי אֵצֶל אִשְׁתּוֹ כְּתַרְנְגוֹל. וּפָגוּם הוּא עַד מְאֹד וּמַעֲשֵׂה בּוּרִים הוּא. אֶלָּא כָּל הַמְמַעֵט בַּתַּשְׁמִישׁ הֲרֵי זֶה מְשֻׁבָּח. וְהוּא שֶׁלֹּא יְבַטֵּל עוֹנָה [אֶלָּא] מִדַּעַת אִשְׁתּוֹ. וְלֹא תִּקְּנוּ בָּרִאשׁוֹנָה לְבַעֲלֵי קְרָיִין שֶׁלֹּא יִקְרְאוּ בַּתּוֹרָה עַד שֶׁיִּטְבְּלוּ אֶלָּא כְּדֵי לְמַעֵט בַּתַּשְׁמִישׁ הַמִּטָּה:","וְכֵן אָסְרוּ חֲכָמִים שֶׁלֹּא יְשַׁמֵּשׁ אָדָם מִטָּתוֹ וְלִבּוֹ מְחַשֵּׁב בְּאִשָּׁה אַחֶרֶת. וְלֹא יִבְעל מִתּוֹךְ שִׁכְרוּת וְלֹא מִתּוֹךְ מְרִיבָה וְלֹא מִתּוֹךְ שִׂנְאָה וְלֹא יָבוֹא עָלֶיהָ עַל כָּרְחָהּ וְהִיא יְרֵאָה מִמֶּנּוּ. וְלֹא כְּשֶׁיִּהְיֶה אֶחָד מֵהֶן מְנֻדֶּה. וְלֹא יָבוֹא עָלֶיהָ אַחַר שֶׁגָּמַר בְּלִבּוֹ לְגָרְשָׁהּ. וְאִם עָשָׂה כֵּן הַבָּנִים אֵינָן הֲגוּנִים אֶלָּא מֵהֶן עַזֵּי פָּנִים וּמֵהֶן מוֹרְדִים וּפוֹשְׁעִים:","וְכֵן אָמְרוּ חֲכָמִים שֶׁכָּל אִשָּׁה חֲצוּפָה שֶׁהִיא תּוֹבַעַת תַּשְׁמִישׁ הַמִּטָּה בְּפִיהָ. אוֹ הַמְפַתֶּה אִשָּׁהּ לְשֵׁם נִשּׂוּאִין. אוֹ הַמִּתְכַּוֵּן לָבוֹא עַל רָחֵל אִשְׁתּוֹ וּבָא עַל לֵאָה אִשְׁתּוֹ. וּמִי שֶׁלֹּא שָׁהֲתָה אַחַר מִיתַת בַּעְלָהּ שְׁלֹשָׁה חֳדָשִׁים וַהֲרֵי הַבֵּן סָפֵק. כָּל אֵלּוּ הַבָּנִים הַיִּלּוֹדִים מֵהֶם הֵם הַמּוֹרְדִים וְהַפּוֹשְׁעִים שֶׁיִּסּוּרֵי הַגָּלוּת בּוֹרְרִין אוֹתָן:","וְאָסוּר לְאָדָם לָבֹא עַל אִשְׁתּוֹ בַּשְּׁוָקִים וּבָרְחוֹבוֹת אוֹ בַּגַּנּוֹת וּבַפַּרְדֵּסִין אֶלָּא בְּבֵית דִּירָה. שֶׁלֹּא יֵרָאֶה כִּזְנוּת וְיַרְגִּילוּ עַצְמָם לִידֵי זְנוּת. וְהַבּוֹעֵל אֶת אִשְׁתּוֹ בִּמְקוֹמוֹת אֵלּוּ מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. וְכֵן הַמְקַדֵּשׁ בְּבִיאָה וְהַמְקַדֵּשׁ בַּשּׁוּק וְהַמְקַדֵּשׁ בְּלֹא שִׁדּוּךְ מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","וְאַכְסְנַאי אָסוּר בַּתַּשְׁמִישׁ הַמִּטָּה עַד שֶׁיַּחְזֹר לְבֵיתוֹ. וְכֵן אָסְרוּ חֲכָמִים עַל הָאִישׁ שֶׁיָּדוּר בְּבֵית חָמִיו שֶׁזּוֹ עַזּוּת פָּנִים הִיא. וְלֹא יִכָּנֵס עִמּוֹ לְמֶרְחָץ:","וְלֹא יִכָּנֵס אָדָם עִם אָבִיו לַמֶּרְחָץ. וְלֹא עִם בַּעַל אֲחוֹתוֹ. וְלֹא עִם תַּלְמִידוֹ. וְאִם הָיָה צָרִיךְ לְתַלְמִידוֹ מֻתָּר. וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ שֶׁלֹּא יִכָּנְסוּ שְׁנֵי אַחִים כְּאֶחָד לַמֶּרְחָץ:","לֹא יְהַלְּכוּ בְּנוֹת יִשְׂרָאֵל פְּרוּעֵי רֹאשׁ בַּשּׁוּק. אַחַת פְּנוּיָה וְאַחַת אֵשֶׁת אִישׁ. וְלֹא תֵּלֵךְ אִשָּׁה בַּשּׁוּק וּבְנָהּ אַחֲרֶיהָ גְּזֵרָה שֶׁמָּא יִתְפְּשׂוּ בְּנָהּ וְתֵלֵךְ אַחֲרָיו לְהַחֲזִירוֹ וְיִתְעַלְּלוּ בָּהּ הָרְשָׁעִים שֶׁתְּפָסוּהוּ דֶּרֶךְ שְׂחוֹק:","אָסוּר לְהוֹצִיא שִׁכְבַת זֶרַע לְבַטָּלָה. לְפִיכָךְ לֹא יִהְיֶה אָדָם דָּשׁ מִבִּפְנִים וְזוֹרֶה מִבַּחוּץ. וְלֹא יִשָּׂא קְטַנָּה שֶׁאֵינָהּ רְאוּיָה לֵילֵד. אֲבָל אֵלּוּ שֶׁמְּנָאֲפִין בַּיָּד וּמוֹצִיאִין שִׁכְבַת זֶרַע לֹא דַּי לָהֶם שֶׁאִסּוּר גָּדוֹל הוּא אֶלָּא שֶׁהָעוֹשֶׂה זֶה בְּנִדּוּי הוּא יוֹשֵׁב וַעֲלֵיהֶם נֶאֱמַר (ישעיה א טו) \"יְדֵיכֶם דָּמִים מָלֵאוּ\" וּכְאִלּוּ הָרַג הַנֶּפֶשׁ:","וְכֵן אָסוּר לְאָדָם שֶׁיַּקְשֶׁה עַצְמוֹ לְדַעַת אוֹ יָבִיא עַצְמוֹ לִידֵי הִרְהוּר. אֶלָּא אִם יָבוֹא לוֹ הִרְהוּר יַסִּיעַ לִבּוֹ מִדִּבְרֵי הֲבַאי (וְהַשְׁחָתָה) לְדִבְרֵי תּוֹרָה. שֶׁהִיא (משלי ה יט) \"אַיֶּלֶת אֲהָבִים וְיַעֲלַת חֵן\". לְפִיכָךְ אָסוּר לְאָדָם לִישֹׁן עַל עָרְפּוֹ וּפָנָיו לְמַעְלָה עַד שֶׁיִּטֶּה מְעַט כְּדֵי שֶׁלֹּא יָבוֹא לִידֵי קִשּׁוּי:","וְלֹא יִסְתַּכֵּל בִּבְהֵמָה וּבְחַיָּה וְעוֹף בְּשָׁעָה שֶׁמִּזְדַּקְקִין זָכָר לִנְקֵבָה. ומֻתָּר לְמַרְבִּיעֵי בְּהֵמָה לְהַכְנִיס כְּמִכְחוֹל בִּשְׁפוֹפֶרֶת מִפְּנֵי שֶׁהֵן עֲסוּקִין בִּמְלַאכְתָּן לֹא יָבוֹאוּ לִידֵי הִרְהוּר:","וְכֵן אָסוּר לְאָדָם לְהִסְתַּכֵּל בְּנָשִׁים בְּשָׁעָה שֶׁהֵן עוֹמְדוֹת עַל הַכְּבִיסָה. אֲפִלּוּ לְהִסְתַּכֵּל בְּבִגְדֵי צֶמֶר שֶׁל אִשָּׁה שֶׁהוּא מַכִּירָהּ אָסוּר. שֶׁלֹּא יָבוֹא לִידֵי הִרְהוּר:","מִי שֶׁפָּגַע בְּאִשָּׁה בַּשּׁוּק אָסוּר לוֹ לְהַלֵּךְ אַחֲרֶיהָ אֶלָּא רָץ וּמְסַלְּקָהּ לַצְּדָדִין אוֹ לְאַחֲרָיו. וְכָל הַמְהַלֵּךְ בַּשּׁוּק אַחֲרֵי אִשָּׁה הֲרֵי זֶה מִקַּלֵּי עַמֵּי הָאָרֶץ. וְאָסוּר לַעֲבֹר עַל פֶּתַח אִשָּׁה זוֹנָה עַד שֶׁיַּרְחִיק אַרְבַּע אַמּוֹת שֶׁנֶּאֱמַר (משלי ה ח) \"וְאַל תִּקְרַב אֶל פֶּתַח בֵּיתָהּ\":","וְאָסוּר לְאָדָם שֶׁאֵינוֹ נָשׂוּי לִשְׁלֹחַ יָדוֹ בִּמְבוּשָׁיו שֶׁלֹּא יָבוֹא לִידֵי הִרְהוּר. וַאֲפִלּוּ מִתַּחַת טִבּוּרוֹ לֹא יַכְנִיס יָדוֹ שֶׁמָּא יָבוֹא לִידֵי הִרְהוּר. וְאִם הִשְׁתִּין מַיִם לֹא יֶאֱחֹז בָּאַמָּה וְיַשְׁתִּין. וְאִם הָיָה נָשׂוּי מֻתָּר. וּבֵין נָשׂוּי וּבֵין שֶׁאֵינוֹ נָשׂוּי לֹא יוֹשִׁיט יָדוֹ לָאַמָּה כְּלָל אֶלָּא בְּשָׁעָה שֶׁהוּא צָרִיךְ לִנְקָבָיו:","חֲסִידִים הָרִאשׁוֹנִים וּגְדוֹלֵי הַחֲכָמִים הִתְפָּאֵר אֶחָד מֵהֶם שֶׁמֵּעוֹלָם לֹא נִסְתַּכֵּל בַּמִּילָה שֶׁלּוֹ. וּמֵהֶן מִי שֶּׁהִתְפָּאֵר שֶׁלֹּא הִתְבּוֹנֵן מֵעוֹלָם בְּצוּרַת אִשְׁתּוֹ. מִפְּנֵי שֶׁלִּבּוֹ פּוֹנֶה מִדִּבְרֵי הֲבַאי לְדִבְרֵי הָאֱמֶת שֶׁהֵן אוֹחֲזוֹת לְבַב הַקְּדוֹשִׁים:","מִצְוַת חֲכָמִים שֶׁיַּשִּׂיא אָדָם בָּנָיו וּבְנוֹתָיו סָמוּךְ לְפִרְקָן. שֶׁאִם יַנִּיחָן יָבוֹאוּ לִידֵי זְנוּת אוֹ לִידֵי הִרְהוּר. וְעַל זֶה נֶאֱמַר (איוב ה כד) \"וּפָקַדְתָּ נָוְךָ וְלֹא תֶחֱטָא\". וְאָסוּר לְהַשִּׂיא אִשָּׁה לְקָטָן שֶׁזֶּה כְּמוֹ זְנוּת הִיא:","וְאֵין הָאִישׁ רַשַּׁאי לֵישֵׁב בְּלֹא אִשָּׁה. וְלֹא יִשָּׂא עֲקָרָה וּזְקֵנָה שֶׁאֵינָהּ רְאוּיָה לֵילֵד. וּרְשׁוּת לָאִשָּׁה שֶׁלֹּא תִּנָּשֵׂא לְעוֹלָם אוֹ תִּנָּשֵׂא לְסָרִיס. וְלֹא יִשָּׂא בָּחוּר זְקֵנָה וְלֹא יִשָּׂא זָקֵן יַלְדָּה שֶׁדָּבָר זֶה גּוֹרֵם לִזְנוּת:","וְכֵן מִי שֶׁגֵּרֵשׁ אֶת אִשְׁתּוֹ מִן הַנִּשּׂוּאִין לֹא תָּדוּר עִמּוֹ בֶּחָצֵר שֶׁמָּא יָבוֹאוּ לִידֵי זְנוּת. וְאִם הָיָה כֹּהֵן לֹא תָּדוּר עִמּוֹ בְּמָבוֹי. וּכְפָר קָטָן נִדּוֹן כְּמָבוֹי. הָיָה לָהּ מִלְוֶה אֶצְלוֹ עוֹשָׂה שָׁלִיחַ לְתָבְעוֹ. וּגְרוּשָׁה שֶׁבָּאָה עִם הַמְגָרֵשׁ לַדִּין מְנַדִּין אוֹתָן אוֹ מַכִּין אוֹתָן מַכַּת מַרְדּוּת. וְאִם נִתְגָּרְשָׁה מִן הָאֵרוּסִין מֻתֶּרֶת לְתָבְעוֹ בַּדִּין וְלָדוּר עִמּוֹ. וְאִם הָיָה לִבּוֹ גַּס בָּהּ אַף מִן הָאֵרוּסִין אָסוּר. וּמִי נִדְחֶה מִפְּנֵי מִי הִיא נִדְּחֵת מִפָּנָיו. וְאִם הָיְתָה הֶחָצֵר שֶׁלָּהּ הוּא יִדָּחֶה מִפָּנֶיהָ:","אָסוּר לְאָדָם לִשָּׂא אִשָּׁה וְדַעְתּוֹ לְגָרְשָׁהּ שֶׁנֶּאֱמַר (משלי ג כט) \"אַל תַּחֲרשׁ עַל רֵעֲךָ רָעָה וְהוּא יוֹשֵׁב לָבֶטַח אִתָּךְ\". וְאִם הוֹדִיעָה בַּתְּחִלָּה שֶׁהוּא נוֹשֵׂא אוֹתָהּ לְיָמִים מֻתָּר:","וְלֹא יִשָּׂא אָדָם אִשָּׁה בִּמְדִינָה זוֹ וְאִשָּׁה בִּמְדִינָה אַחֶרֶת שֶׁמָּא יַאֲרִיכוּ הַיָּמִים וְנִמְצָא אָח נוֹשֵׂא אֲחוֹתוֹ וַאֲחוֹת אִמּוֹ וַאֲחוֹת אָבִיו וְכַיּוֹצֵא בָּהֶן וְאֵינוֹ יָדוּעַ. וְאִם הָיָה אָדָם גָּדוֹל שֶׁשְּׁמוֹ יָדוּעַ וַהֲרֵי זַרְעוֹ מְפֻרְסָמִין וִידוּעִין הֲרֵי זֶה מֻתָּר:","לֹא יִשָּׂא אָדָם אִשָּׁה מִמִּשְׁפַּחַת מְצֹרָעִים וְלֹא מִמִּשְׁפַּחַת נִכְפִּין. וְהוּא שֶׁהֻחְזְקוּ שְׁלֹשָׁה פְּעָמִים שֶׁיָּבוֹאוּ בְּנֵיהֶם כָּךְ:","אִשָּׁה שֶׁנִּשֵּׂאת לִשְׁנֵי אֲנָשִׁים וָמֵתוּ. לִשְׁלִישִׁי לֹא תִּנָּשֵׂא וְאִם נִשֵּׂאת לֹא תֵּצֵא. וַאֲפִלּוּ נִתְקַדְּשָׁה יִכְנֹס. וְלֹא יִשָּׂא יִשְׂרָאֵל עַם הָאָרֶץ כֹּהֶנֶת שֶׁזֶּה כְּמוֹ חִלּוּל לְזַרְעוֹ שֶׁל אַהֲרֹן. וְאִם נָשָׂא אָמְרוּ חֲכָמִים אֵין זִוּוּגָן עוֹלֶה יָפֶה אֶלָּא מֵת בְּלֹא בָּנִים אוֹ מֵת הוּא אוֹ הִיא בִּמְהֵרָה אוֹ קְטָטָה תִּהְיֶה בֵּינֵיהֶם. אֲבָל תַּלְמִיד חָכָם שֶׁנָּשָׂא כֹּהֶנֶת הֲרֵי זֶה נָאֶה וּמְשֻׁבָּח. הֲרֵי תּוֹרָה וּכְהֻנָּה כְּאֶחָד:","לֹא יִשָּׂא אָדָם בַּת עַמֵּי הָאָרֶץ שֶׁאִם מֵת אוֹ גּוֹלֶה בָּנָיו עַמֵּי הָאָרֶץ יִהְיוּ שֶׁאֵין אִמָּן יוֹדַעַת כֶּתֶר הַתּוֹרָה. וְלֹא יַשִּׂיא בִּתּוֹ לְעַם הָאָרֶץ שֶׁכָּל הַנּוֹתֵן בִּתּוֹ לְעַם הָאָרֶץ כְּמִיִ שֶׁכְּפָתָהּ וּנְתָנָהּ לִפְנֵי הָאֲרִי מַכֶּה וּבוֹעֵל וְאֵין לוֹ בּשֶׁת פָּנִים. וּלְעוֹלָם יִמְכֹּר אָדָם כָּל מַה שֶּׁיֵּשׁ לוֹ וְיִשָּׂא בַּת תַּלְמִיד חָכָם שֶׁאִם מֵת אוֹ גּוֹלֶה בָּנָיו תַּלְמִידֵי חֲכָמִים. וְכֵן יַשִּׂיא בִּתּוֹ לְתַלְמִיד חָכָם שֶׁאֵין דָּבָר מְגֻנֶּה וְלֹא מְרִיבָה בְּבֵיתוֹ שֶׁל תַּלְמִיד חָכָם:"],"Mishneh Torah, Foreign Worship and Customs of the Nations 12":["אֵין מְגַלְּחִין פַּאֲתֵי הָרֹאשׁ כְּמוֹ שֶׁהָיוּ עוֹשִׂין עוֹבְדֵי כּוֹכָבִים שֶׁנֶּאֱמַר (ויקרא יט כז) \"לֹא תַקִּפוּ פְּאַת רֹאשְׁכֶם\". וְחַיָּב עַל כָּל פֵּאָה וּפֵאָה. לְפִיכָךְ הַמְגַלֵּחַ שְׁנֵי צְדָעָיו אֲפִלּוּ בְּבַת אַחַת וְהַתְרָאָה אַחַת לוֹקֶה שְׁתַּיִם. אֶחָד הַמְגַלֵּחַ הַפֵּאוֹת בִּלְבַד וּמֵנִיחַ שֵׂעָר כָּל הָרֹאשׁ וְאֶחָד הַמְגַלֵּחַ כָּל הָרֹאשׁ כְּאֶחָד לוֹקֶה הוֹאִיל וְגִלַּח הַפֵּאוֹת. בַּמֶּה דְּבָרִים אֲמוּרִים בְּאִישׁ הַמְגַלֵּחַ אֲבָל אִישׁ הַמִּתְגַּלֵּחַ אֵינוֹ לוֹקֶה אֶלָּא אִם כֵּן סִיֵּעַ לַמְגַלֵּחַ. וְהַמְגַלֵּחַ אֶת הַקָּטָן לוֹקֶה:","הָאִשָּׁה שֶׁגִּלְּחָה פְּאַת רֹאשׁ הָאִישׁ אוֹ שֶׁנִּתְגַלְּחָה פְּטוּרָה שֶׁנֶּאֱמַר (ויקרא יט כז) \"לֹא תַקִּפוּ פְּאַת רֹאשְׁכֶם\" (ויקרא יט כז) \"וְלֹא תַשְׁחִית פְּאַת זְקָנֶךָ\" כָּל שֶׁיֶּשְׁנוֹ בְּבַל תַּשְׁחִית יֶשְׁנוֹ בְּבַל תַּקִּיף, וְאִשָּׁה שֶׁאֵינָהּ בְּבַל תַּשְׁחִית לְפִי שֶׁאֵין לָהּ זָקָן אֵינָהּ בְּבַל תַּקִּיף. לְפִיכָךְ הָעֲבָדִים הוֹאִיל וְיֵשׁ לָהֶם זָקָן אֲסוּרִין בְּהַקָּפָה:","כָּל מִצְוֹת לֹא תַּעֲשֶׂה שֶׁבַּתּוֹרָה אֶחָד אֲנָשִׁים וְאֶחָד נָשִׁים חַיָּבִים חוּץ מִ\"בַּל תַּשְׁחִית\" וּ\"בַל תַּקִּיף\" וּ\"בַל יִטָּמֵא כֹּהֵן לַמֵּתִים\" (משנה קידושין א ז). וְכָל מִצְוַת עֲשֵׂה שֶׁהִיא מִזְּמַן לִזְמַן וְאֵינָהּ תְּדִירָה נָשִׁים פְּטוּרוֹת חוּץ מִקִּדּוּשׁ הַיּוֹם וַאֲכִילַת מַצָּה בְּלֵילֵי הַפֶּסַח וַאֲכִילַת הַפֶּסַח וּשְׁחִיטָתוֹ וְהַקְהֵל וְשִׂמְחָה שֶׁהַנָּשִׁים חַיָּבוֹת:","טֻמְטוּם וְאַנְדְּרוֹגִינוּס הֲרֵי הֵן סָפֵק, נוֹתְנִין עֲלֵיהֶן חֻמְרֵי הָאִישׁ וְחֻמְרֵי הָאִשָּׁה בְּכָל מָקוֹם וְחַיָּבִים בַּכּל. וְאִם עָבְרוּ אֵינָם לוֹקִין:","אַף עַל פִּי שֶׁהָאִשָּׁה מֻתֶּרֶת לְגַלֵּחַ פְּאַת רֹאשָׁהּ הֲרֵי הִיא אֲסוּרָה לְגַלֵּחַ פְּאַת רֹאשׁ הָאִישׁ. וַאֲפִלּוּ קָטָן אָסוּר לָהּ לְגַלֵּחַ לוֹ פֵּאָה:","וּפֵאָה זוֹ שֶׁמַּנִּיחִים בַּצְּדָעִים לֹא נָתְנוּ בּוֹ חֲכָמִים שִׁעוּר וְשָׁמַעְנוּ מִזְּקֵנֵינוּ שֶׁאֵינוֹ מַנִּיחַ פָּחוֹת מֵאַרְבָּעִים שְׂעָרוֹת. וּמֻתָּר לְלַקֵּט הַפֵּאוֹת בְּמִסְפָּרַיִם לֹא נֶאֱסַר אֶלָּא הַשְׁחָתָה בְּתַעַר:","דֶּרֶךְ כֹּהֲנֵי עוֹבְדֵי כּוֹכָבִים הָיָה לְהַשְׁחִית זְקָנָם. לְפִיכָךְ אָסְרָה תּוֹרָה לְהַשְׁחִית הַזָּקָן. וְחָמֵשׁ פֵּאוֹת יֵשׁ בּוֹ. לְחִי הָעֶלְיוֹן וּלְחִי הַתַּחְתּוֹן מִיָּמִין וְכֵן מִשְּׂמֹאל וְשִׁבּלֶת הַזָּקָן. וְלוֹקֶה עַל כָּל פֵּאָה וּפֵאָה. וְאִם נְטָלָן כֻּלָּן כְּאַחַת לוֹקֶה חָמֵשׁ. וְאֵינוֹ חַיָּב עַד שֶׁיְּגַלְּחֶנּוּ בְּתַעַר שֶׁנֶּאֱמַר (ויקרא יט כז) \"וְלֹא תַשְׁחִית אֵת פְּאַת זְקָנֶךָ\" גִּלּוּחַ שֶׁיֵּשׁ בּוֹ הַשְׁחָתָה. לְפִיכָךְ אִם גִּלֵּחַ זְקָנוֹ בְּמִסְפָּרַיִם פָּטוּר. וְאֵין הַמִּתְגַּלֵּחַ לוֹקֶה עַד שֶׁיְּסַיֵּעַ. וְאִשָּׁה מֻתֶּרֶת לְהַשְׁחִית זְקָנָהּ אִם יֵשׁ לָהּ שֵׂעָר בַּזָּקָן. וְאִם הִשְׁחִיתָה זְקַן הָאִישׁ פְּטוּרָה:","הַשָּׂפָה מֻתָּר לְגַלְּחוֹ בְּתַעַר וְהוּא הַשֵּׂעָר שֶׁעַל גַּב הַשָּׂפָה הָעֶלְיוֹנָה וְכֵן הַשֵּׂעָר הַמְדֻלְדָּל מִן הַשָּׂפָה הַתַּחְתּוֹנָה. וְאַף עַל פִּי שֶׁהוּא מֻתָּר לֹא נָהֲגוּ יִשְׂרָאֵל לְהַשְׁחִיתוֹ אֶלָּא יְגַלֵּחַ קְצָתוֹ עַד שֶׁלֹּא יְעַכֵּב אֲכִילָה וּשְׁתִיָּה:","הַעֲבָרַת הַשֵּׂעָר מִשְּׁאָר הַגּוּף כְּגוֹן בֵּית הַשֶּׁחִי וּבֵית הָעֶרְוָה אֵינוֹ אָסוּר מִן הַתּוֹרָה אֶלָּא מִדִּבְרֵי סוֹפְרִים וְהַמַּעֲבִירוֹ מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. בַּמֶּה דְּבָרִים אֲמוּרִים בְּמָקוֹם שֶׁאֵין מַעֲבִירִין אוֹתוֹ אֶלָּא נָשִׁים כְּדֵי שֶׁלֹּא יְתַקֵּן עַצְמוֹ תִּקּוּן נָשִׁים. אֲבָל בְּמָקוֹם שֶׁמַּעֲבִירִין הַשֵּׂעָר הַנָּשִׁים וַאֲנָשִׁים אִם הֶעֱבִיר אֵין מַכִּין אוֹתוֹ. וּמֻתָּר לְהַעֲבִיר שְׂעַר שְׁאָר אֵיבָרִים בְּמִסְפָּרַיִם בְּכָל מָקוֹם:","לֹא תַּעֲדֶה אִשָּׁה עֲדִי הָאִישׁ כְּגוֹן שֶׁתָּשִׂים בְּרֹאשָׁהּ מִצְנֶפֶת אוֹ כּוֹבַע אוֹ תִּלְבַּשׁ שִׁרְיוֹן וְכַיּוֹצֵא בּוֹ אוֹ שֶׁתְּגַלֵּחַ רֹאשָׁהּ כְּאִישׁ. וְלֹא יַעֲדֶה אִישׁ עֲדִי אִשָּׁה כְּגוֹן שֶׁיִּלְבַּשׁ בִּגְדֵי צִבְעוֹנִין וַחֲלִי זָהָב בְּמָקוֹם שֶׁאֵין לוֹבְשִׁין אוֹתָן הַכֵּלִים וְאֵין מְשִׂימִים אוֹתוֹ הַחֲלִי אֶלָּא נָשִׁים הַכּל כְּמִנְהַג הַמְּדִינָה. אִישׁ שֶׁעָדָה עֲדִי אִשָּׁה וְאִשָּׁה שֶׁעָדְתָה עֲדִי אִישׁ לוֹקִין. הַמְלַקֵּט שְׂעָרוֹת לְבָנוֹת מִתּוֹךְ הַשְּׁחוֹרוֹת מֵרֹאשׁוֹ אוֹ מִזְּקָנוֹ מִשֶּׁיְּלַקֵּט שַׂעֲרָה אַחַת לוֹקֶה מִפְּנֵי שֶׁעָדָה עֲדִי אִשָּׁה. וְכֵן אִם צָבַע שְׂעָרוֹ שָׁחוֹר מִשֶּׁיִּצְבַּע שֵׂעָר לְבָנָה אַחַת לוֹקֶה. טֻמְטוּם וְאַנְדְּרוֹגִינוּס אֵינוֹ עוֹטֵף כְּאִשָּׁה וְלֹא מְגַלֵּחַ רֹאשׁוֹ כְּאִישׁ וְאִם עָשָׂה כֵּן אֵינוֹ לוֹקֶה:","כְּתֹבֶת קַעֲקַע הָאֲמוּרָה בַּתּוֹרָה הוּא שֶׁיִּשְׂרֹט עַל בְּשָׂרוֹ וִימַלֵּא מְקוֹם הַשְּׂרִיטָה כָּחל אוֹ דְּיוֹ אוֹ שְׁאָר צִבְעוֹנִים הָרוֹשְׁמִים. וְזֶה הָיָה מִנְהַג הָעַכּוּ\"ם שֶׁרוֹשְׁמִין עַצְמָן לַעֲבוֹדַת כּוֹכָבִים כְּלוֹמַר שֶׁהוּא עֶבֶד מָכוּר לָהּ וּמֻרְשָׁם לַעֲבוֹדָתָהּ. וּמֵעֵת שֶׁיִּרְשֹׁם בְּאֶחָד מִדְּבָרִים הָרוֹשְׁמִין אַחַר שֶׁיִּשְׂרֹט בְּאֵי זֶה מָקוֹם מִן הַגּוּף בֵּין אִישׁ בֵּין אִשָּׁה לוֹקֶה. כָּתַב וְלֹא רָשַׁם בְּצֶבַע אוֹ שֶׁרָשַׁם בְּצֶבַע וְלֹא כָּתַב בִּשְׂרִיטָה פָּטוּר עַד שֶׁיִּכְתֹּב וִיקַעֲקֵעַ שֶׁנֶּאֱמַר (ויקרא יט כח) \"וּכְתֹבֶת קַעֲקַע\". בַּמֶּה דְּבָרִים אֲמוּרִים בְּכוֹתֵב אֲבָל זֶה שֶׁכָּתְבוּ בִּבְשָׂרוֹ וְקִעְקְעוּ בּוֹ אֵינוֹ חַיָּב אֶלָּא אִם כֵּן סִיֵּעַ כְּדֵי שֶׁיַּעֲשֶׂה מַעֲשֶׂה. אֲבָל אִם לֹא עָשָׂה כְּלוּם אֵינוֹ לוֹקֶה:","הַשּׂוֹרֵט שְׂרִיטָה אַחַת עַל הַמֵּת לוֹקֶה שֶׁנֶּאֱמַר (ויקרא יט כח) \"וְשֶׂרֶט לָנֶפֶשׁ לֹא תִתְּנוּ בִּבְשַׂרְכֶם\". אֶחָד כֹּהֵן וְאֶחָד יִשְׂרָאֵל. שָׂרַט שְׂרִיטָה אַחַת עַל חָמֵשׁ מֵתִים אוֹ חָמֵשׁ שְׂרִיטוֹת עַל מֵת אֶחָד לוֹקֶה חָמֵשׁ. וְהוּא שֶׁהִתְרוּ בּוֹ עַל כָּל אַחַת וְאַחַת:","גְּדִידָה וּשְׂרִיטָה אַחַת הִיא. וּכְשֵׁם שֶׁהָיוּ הָעַכּוּ\"ם שׂוֹרְטִים בִּבְשָׂרָם עַל מֵתֵיהֶם מִפְּנֵי הַצַּעַר כָּךְ הָיוּ חוֹבְלִין בְּעַצְמָם לַעֲבוֹדַת כּוֹכָבִים שֶׁנֶּאֱמַר (מלכים א יח כח) \"וַיִּתְגֹּדְדוּ כְּמִשְׁפָּטָם\". גַּם זֶה אָסְרָה תּוֹרָה שֶׁנֶּאֱמַר (דברים יד א) \"לֹא תִתְגֹּדְדוּ\". אֶלָּא שֶׁעַל מֵת בֵּין שָׂרַט בְּיָדוֹ בֵּין שָׂרַט בִּכְלִי לוֹקֶה. לַעֲבוֹדַת כּוֹכָבִים בִּכְלִי חַיָּב מַלְקוֹת בְּיָדוֹ פָּטוּר:","וּבִכְלַל אַזְהָרָה זֶה שֶׁלֹּא יִהְיוּ שְׁנֵי בָּתֵּי דִּינִין בְּעִיר אַחַת זֶה נוֹהֵג כְּמִנְהָג זֶה וְזֶה נוֹהֵג כְּמִנְהָג אַחֵר. שֶׁדָּבָר זֶה גּוֹרֵם לְמַחֲלוֹקוֹת גְּדוֹלוֹת שֶׁנֶּאֱמַר (דברים יד א) \"לֹא תִתְגֹּדְדוּ\" לֹא תֵּעָשׂוּ אֲגֻדּוֹת אֲגֻדּוֹת:","הַקֹּרֵחַ קָרְחָה עַל הַמֵּת לוֹקֶה שֶׁנֶּאֱמַר (דברים יד א) \"וְלֹא תָשִׂימוּ קָרְחָה בֵּין עֵינֵיכֶם לָמֵת\". אֶחָד יִשְׂרָאֵל וְאֶחָד כֹּהֵן שֶׁשָּׂרַט עַל הַמֵּת אֵינוֹ לוֹקֶה אֶלָּא אַחַת. הַקֹּרֵחַ אַרְבַּע אוֹ חָמֵשׁ קָרְחוֹת עַל מֵת אֶחָד לוֹקֶה כְּמִנְיַן הַקָּרְחוֹת וְהוּא שֶׁהִתְרוּ בּוֹ עַל כָּל קָרְחָה וְקָרְחָה. אֶחָד הַקֹּרֵחַ בְּיָדוֹ אוֹ בְּסַם אוֹ הִטְבִּיל אֶצְבְּעוֹתָיו בְּסַם וְהִנִּיחָם בַּחֲמִשָּׁה מְקוֹמוֹת בְּרֹאשׁוֹ בְּבַת אַחַת הוֹאִיל וְקָרַח חָמֵשׁ קָרְחוֹת אַף עַל פִּי שֶׁהִיא הַתְרָאָה אַחַת לוֹקֶה חָמֵשׁ שֶׁהֲרֵי כֻּלָּן בָּאִין כְּאַחַת. וְחַיָּב עַל כָּל הָרֹאשׁ כְּבֵין הָעֵינַיִם שֶׁנֶּאֱמַר (ויקרא כא ה) \"לֹא יִקְרְחוּ קָרְחָה בְּרֹאשָׁם\". וְכַמָּה שִׁעוּר הַקָּרְחָה כְּדֵי שֶׁיֵּרָאֶה מֵרֹאשׁוֹ כִּגְרִיס פָּנוּי בְּלִי שֵׂעָר:","הַקֹּרֵחַ רֹאשׁוֹ אוֹ הַשּׂוֹרֵט בִּבְשָׂרוֹ עַל בֵּיתוֹ שֶׁנָּפַל וְעַל סְפִינָתוֹ שֶׁנִּטְבְּעָה בַּיָּם פָּטוּר וְאֵינוֹ לוֹקֶה אֶלָּא עַל הַמֵּת בִּלְבַד אוֹ הַשּׂוֹרֵט לַעֲבוֹדַת כּוֹכָבִים. הַקֹּרֵחַ קָרְחָה בְּרֹאשׁוֹ שֶׁל חֲבֵרוֹ וְהַשּׂוֹרֵט שְׂרִיטָה בִּבְשַׂר חֲבֵרוֹ וְהַכּוֹתֵב כְּתֹבֶת קַעֲקַע בִּבְשָׂרוֹ שֶׁל חֲבֵרוֹ וְהָיָה חֲבֵרוֹ מְסַיֵּעַ. בִּזְמַן שֶּׁשְּׁנֵיהֶן מְזִידִין שְׁנֵיהֶן לוֹקִין. אֶחָד שׁוֹגֵג וְאֶחָד מֵזִיד הַמֵּזִיד מִשְּׁנֵיהֶם לוֹקֶה וְהַשּׁוֹגֵג פָּטוּר:"],"Mishneh Torah, Foundations of the Torah 3":["הַגַּלְגַּלִים הֵם הַנִּקְרָאִים שָׁמַיִם וְרָקִיעַ וּזְבוּל וַעֲרָבוֹת. וְהֵם תִּשְׁעָה גַּלְגַּלִּים. גַּלְגַּל הַקָּרוֹב מִמֶּנּוּ הוּא גַּלְגַּל הַיָּרֵחַ. וְהַשֵּׁנִי שֶׁלְּמַעְלָה מִמֶּנּוּ הוּא גַּלְגַּל שֶׁבּוֹ הַכּוֹכָב הַנִּקְרָא כּוֹכָב. וְגַלְגַּל שְׁלִישִׁי שֶׁלְּמַעְלָה מִמֶּנּוּ שֶׁבּוֹ נֹגַהּ. וְגַלְגַּל רְבִיעִי שֶׁבּוֹ חַמָּה. וְגַלְגַּל חֲמִישִׁי שֶׁבּוֹ מַאֲדִים. וְגַלְגַּל שִׁשִּׁי שֶׁבּוֹ כּוֹכַב צֶדֶק. וְגַלְגַּל שְׁבִיעִי שֶׁבּוֹ שַׁבְּתַי. וְגַלְגַּל שְׁמִינִי שֶׁבּוֹ שְׁאָר כָּל הַכּוֹכָבִים שֶׁנִּרְאִים בָּרָקִיעַ. וְגַלְגַּל תְּשִׁיעִי הוּא גַּלְגַּל הַחוֹזֵר בְּכָל יוֹם מִן הַמִּזְרָח לַמַּעֲרָב וְהוּא הַמַּקִּיף וּמְסַבֵּב אֶת הַכּל. וְזֶה שֶׁתִּרְאֶה כָּל הַכּוֹכָבִים כְּאִלּוּ הֵם כֻּלָּם בְּגַלְגַּל אֶחָד וְאַף עַל פִּי שֶׁיֵּשׁ בָּהֶן זֶה לְמַעְלָה מִזֶּה. מִפְּנֵי שֶׁהַגַּלְגַּלִּים טְהוֹרִים וְזַכִּים כִּזְכוּכִית וּכְסַפִּיר לְפִיכָךְ נִרְאִים הַכּוֹכָבִים שֶׁבַּגַּלְגַּל הַשְּׁמִינִי מִתַּחַת גַּלְגַּל הָרִאשׁוֹן:","כָּל גַּלְגַּל וְגַלְגַּל מִשְּׁמוֹנָה הַגַּלְגַּלִּים שֶׁבָּהֶן הַכּוֹכָבִים נֶחְלָק לְגַלְגַּלִּים הַרְבֵּה זֶה לְמַעְלָה מִזֶּה כְּמוֹ גִּלְדֵי בְּצָלִים. מֵהֶן גַּלְגַּלִּים סוֹבְבִים מִמַּעֲרָב לְמִזְרָח. וּמֵהֶן סוֹבְבִים מִמִּזְרָח לְמַעֲרָב כְּמוֹ הַגַּלְגַּל הַתְּשִׁיעִי הַחוֹזֵר מִמִּזְרָח לְמַעֲרָב. וְכֻלָּן אֵין בֵּינֵיהֶם מָקוֹם פָּנוּי:","כָּל הַגַּלְגַּלִּים אֵינָן לֹא קַלִּים וְלֹא כְּבֵדִים וְאֵין לָהֶם לֹא עַיִן אָדֹם וְלֹא עַיִן שָׁחֹר וְלֹא שְׁאָר עֵינוֹת. וְזֶה שֶׁאָנוּ רוֹאִין אוֹתָם כְּעֵין הַתְּכֵלֶת לְמַרְאִית הָעַיִן בִּלְבַד הוּא לְפִי גֹּבַהּ הָאֲוִיר. וְכֵן אֵין לָהֶם לֹא טַעַם וְלֹא רֵיחַ לְפִי שֶׁאֵין אֵלּוּ הַמְאֹרָעִין מְצוּיִין אֶלָּא בַּגּוּפוֹת שֶׁלְּמַטָּה מֵהֶן:","כָּל הַגַּלְגַּלִּים הָאֵלּוּ הַמַּקִּיפִין אֶת הָעוֹלָם הֵן עֲגֻלִּין כְּכַדּוּר וְהָאָרֶץ תְּלוּיָה בָּאֶמְצַע. וְיֵשׁ לְמִקְצָת מִן הַכּוֹכָבִים גַּלְגַּלִּים קְטַנִּים שֶׁהֵן קְבוּעִים בָּהֶן וְאֵין אוֹתָם הַגַּלְגַּלִּים מַקִּיפִין אֶת הָאָרֶץ אֶלָּא גַּלְגַּל קָטָן שֶׁאֵינוֹ מַקִּיף קָבוּעַ בַּגַּלְגַּל הַגָּדוֹל הַמַּקִּיף:","מִסְפַּר כָּל הַגַּלְגַּלִּים הַמַּקִּיפִין אֶת כָּל הָעוֹלָם שְׁמוֹנָה עָשָׂר. וּמִסְפַּר הַגַּלְגַּלִּים הַקְּטַנִּים שֶׁאֵינָן מַקִּיפִין שְׁמוֹנָה. וּמִמַּהֲלַךְ הַכּוֹכָבִים וִידִיעַת שִׁעוּר סְבִיבָתָן בְּכָל יוֹם וּבְכָל שָׁעָה וּמִנְּטִיָּתָן מֵרוּחַ דָּרוֹם לְרוּחַ צָפוֹן וּמֵרוּחַ צָפוֹן לְרוּחַ דָּרוֹם וּמִגָּבְהָן מֵעַל הָאָרֶץ וּקְרִיבָתָן יִוָדַּע מִסְפַּר כָּל אֵלּוּ הַגַּלְגַּלִּים וְצוּרַת הֲלִיכָתָן וְדֶרֶךְ הַקָּפָתָן. וְזוֹ הִיא חָכְמַת חֶשְׁבּוֹן תְּקוּפוֹת וּמַזָּלוֹת. וּסְפָרִים רַבִּים חִבְּרוּ בָּהֶן חַכְמֵי יָוָן:","גַּלְגַּל הַתְּשִׁיעִי שֶׁהוּא מַקִּיף אֶת הַכּל חִלְּקוּהוּ הַחֲכָמִים הַקַּדְמוֹנִים לִשְׁנֵים עָשָׂר חֲלָקִים. כָּל חֵלֶק וְחֵלֶק הֶעֱלוּ לוֹ שֵׁם עַל שֵׁם צוּרָה זוֹ שֶׁתֵּרָאֶה בּוֹ מִן הַכּוֹכָבִים שֶׁלְּמַטָּה מִמֶּנּוּ שֶׁהֵם מְכֻוָּנִים תַּחְתָּיו. וְהֵם הַמַּזָּלוֹת שֶׁשְּׁמוֹתָם טָלֶה. שׁוֹר. תְּאוֹמִים. סַרְטָן. אַרְיֵה. בְּתוּלָה. מֹאזְנַיִם. עַקְרָב. קֶשֶׁת. גְּדִי. דְּלִי. דָּגִים:","גַּלְגַּל הַתְּשִׁיעִי עַצְמוֹ אֵין בּוֹ לֹא חֲלוּקָה וְלֹא צוּרָה מִכָּל הַצּוּרוֹת הָאֵלּוּ וְלֹא כּוֹכָב. אֶלָּא בְּחִבּוּר הַכּוֹכָבִים שֶׁבַּגַּלְגַּל הַשְּׁמִינִי הוּא שֶׁיֵּרָאֶה בְּכוֹכָבִים גְּדוֹלִים שֶׁבּוֹ תַּבְנִית הַצּוּרוֹת הָאֵלּוּ אוֹ קָרוֹב מֵהֶן. וְאֵלּוּ הַשְּׁנֵים עָשָׂר צוּרוֹת לֹא הָיוּ מְכֻוָּנוֹת כְּנֶגֶד אוֹתָן הַחֲלָקִים אֶלָּא בִּזְמַן הַמַּבּוּל שֶׁאָז הֶעֱלוּ לָהֶן שֵׁמוֹת אֵלּוּ. אֲבָל בַּזְּמַן הַזֶּה כְּבָר סָבְבוּ מְעַט. לְפִי שֶׁכָּל הַכּוֹכָבִים שֶׁבְּגַלְגַּל שְׁמִינִי כֻּלָּם סוֹבְבִים כְּמוֹ הַשֶּׁמֶשׁ וְהַיָּרֵחַ אֶלָּא שֶׁהֵן סוֹבְבִין בִּכְבֵדוּת. וְחֵלֶק שֶׁיִּתְהַלֵּךְ הַשֶּׁמֶשׁ וְהַיָּרֵחַ כְּנֶגְדּוֹ בְּיוֹם אֶחָד יֵלֵךְ כְּנֶגְדּוֹ כָּל כּוֹכָב מֵהֶן בְּקֵרוּב מִשִּׁבְעִים שָׁנָה:","כָּל הַכּוֹכָבִים הַנִּרְאִים יֵשׁ מֵהֶן כּוֹכָבִים קְטַנִּים שֶׁהָאָרֶץ גְּדוֹלָה מֵאֶחָד מֵהֶן. וְיֵשׁ מֵהֶן כּוֹכָבִים גְּדוֹלִים שֶׁכָּל אֶחָד מֵהֶן גָּדוֹל מִן הָאָרֶץ כַּמָּה פְּעָמִים. וְהָאָרֶץ גְּדוֹלָה מִן הַיָּרֵחַ כְּמוֹ אַרְבָּעִים פְּעָמִים. וְהַשֶּׁמֶשׁ גְּדוֹלָה מִן הָאָרֶץ כְּמוֹ מֵאָה וְשִׁבְעִים פְּעָמִים. נִמְצָא הַיָּרֵחַ אֶחָד מִשֵּׁשֶׁת אֲלָפִים וּשְׁמוֹנֶה מֵאוֹת מִן הַשֶּׁמֶשׁ בְּקֵרוּב. וְאֵין בְּכָל הַכּוֹכָבִים כּוֹכָב גָּדוֹל מִן הַשֶּׁמֶשׁ וְלֹא קָטָן מִכּוֹכָב שֶׁבַּגַּלְגַּל הַשֵּׁנִי:","כָּל הַכּוֹכָבִים וְהַגַּלְגַּלִּים כֻּלָּן בַּעֲלֵי נֶפֶשׁ וְדֵעָה וְהַשְׂכֵּל הֵם. וְהֵם חַיִּים וְעוֹמְדִים וּמַכִּירִין אֶת מִי שֶׁאָמַר וְהָיָה הָעוֹלָם. כָּל אֶחָד וְאֶחָד לְפִי גָּדְלוֹ וּלְפִי מַעֲלָתוֹ מְשַׁבְּחִים וּמְפָאֲרִים לְיוֹצְרָם כְּמוֹ הַמַּלְאָכִים. וּכְשֵׁם שֶׁמַּכִּירִין הַקָּדוֹשׁ בָּרוּךְ הוּא כָּךְ מַכִּירִין אֶת עַצְמָן וּמַכִּירִין אֶת הַמַּלְאָכִים שֶׁלְּמַעְלָה מֵהֶן. וְדַעַת הַכּוֹכָבִים וְהַגַּלְגַּלִּים מְעוּטָה מִדַּעַת הַמַּלְאָכִים וּגְדוֹלָה מִדַּעַת בְּנֵי אָדָם:","בָּרָא הָאֵל לְמַטָּה מִגַּלְגַּל הַיָּרֵחַ גּלֶם אֶחָד שֶׁאֵינוֹ כְּגלֶם הַגַּלְגַּלִּים. וּבָרָא אַרְבַּע צוּרוֹת לְגלֶם זֶה וְאֵינָן כְּצוּרַת הַגַּלְגַּלִּים וְנִקְבַּע כָּל צוּרָה וְצוּרָה בְּמִקְצָת גּלֶם זֶה. צוּרָה רִאשׁוֹנָה צוּרַת הָאֵשׁ נִתְחַבְּרָה בְּמִקְצָת גּלֶם זֶה וְנִהְיָה מִשְּׁנֵיהֶן גּוּף הָאֵשׁ. וְצוּרָה שְׁנִיָּה צוּרַת הָרוּחַ נִתְחַבְּרָה בְּמִקְצָתוֹ וְנִהְיָה מִשְּׁנֵיהֶן גּוּף הָרוּחַ. וְצוּרָה שְׁלִישִׁית צוּרַת הַמַּיִם נִתְחַבְּרָה בְּמִקְצָתוֹ וְנִהְיָה מִשְּׁנֵיהֶם גּוּף הַמַּיִם. וְצוּרָה רְבִיעִית צוּרַת הָאָרֶץ נִתְחַבְּרָה בְּמִקְצָתוֹ וְנִהְיָה מִשְּׁנֵיהֶם גּוּף הָאָרֶץ. נִמְצָא לְמַטָּה מִן הָרָקִיעַ אַרְבָּעָה גּוּפִין מֻחְלָקִין זֶה לְמַעְלָה מִזֶּה וְכָל אֶחָד וְאֶחָד מַקִּיף אֶת שֶׁלְּמַטָּה מִמֶּנּוּ מִכָּל רוּחוֹתָיו כְּמוֹ גַּלְגַּל. הַגּוּף הָרִאשׁוֹן הַסָּמוּךְ לְגַלְגַּל הַיָּרֵחַ הוּא גּוּף הָאֵשׁ. לְמַטָּה מִמֶּנּוּ גּוּף הָרוּחַ. לְמַטָּה מִמֶּנּוּ גּוּף הַמַּיִם. לְמַטָּה מִמֶּנּוּ גּוּף הָאָרֶץ. וְאֵין בֵּינֵיהֶם מָקוֹם פָּנוּי בְּלֹא גּוּף כְּלָל:","אַרְבָּעָה גּוּפוֹת הָאֵלּוּ אֵינָם בַּעֲלֵי נֶפֶשׁ וְאֵינָם יוֹדְעִים וְלֹא מַכִּירִים אֶלָּא כְּגוּפִים מֵתִים. וְיֵשׁ לְכָל אֶחָד וְאֶחָד מֵהֶם מִנְהָג שֶׁאֵינוֹ יוֹדְעוֹ וְלֹא מַשִּׂיגוֹ וְאֵינוֹ יָכוֹל לְשַׁנּוֹתוֹ. וְזֶה שֶׁאָמַר דָּוִד (תהילים קמח ז) \"הַלְלוּ אֶת ה' מִן הָאָרֶץ תַּנִּינִים וְכָל תְּהֹמוֹת\" (תהילים קמח ח) \"אֵשׁ וּבָרָד שֶׁלֶג וְקִיטוֹר\". וּבֵאוּר עִנְיַן הַדְּבָרִים הַלְלוּהוּ בְּנֵי אָדָם מִגְּבוּרוֹתָיו שֶׁתִּרְאוּ בָּאֵשׁ וּבַבָּרָד וּבִשְׁאָר בְּרוּאִים שֶׁתִּרְאוּ לְמַטָּה מִן הָרָקִיעַ שֶׁגְּבוּרָתָם תָּמִיד נִכֶּרֶת לַקָּטָן וְלַגָּדוֹל:"],"Mishneh Torah, Gifts to the Poor 2":["כָּל אֹכֶל שֶׁגִּדּוּלָיו מִן הָאָרֶץ וְנִשְׁמָר וּלְקִיטָתוֹ כֻּלּוֹ כְּאַחַת וּמַכְנִיסִין אוֹתוֹ לְקִיּוּם חַיָּב בְּפֵאָה. שֶׁנֶּאֱמַר (ויקרא יט ט) (ויקרא כג כב) \"וּבְקֻצְרְכֶם אֶת קְצִיר אַרְצְכֶם\":","כָּל הַדּוֹמֶה לַקָּצִיר בְּחָמֵשׁ דְּרָכִים אֵלּוּ הוּא שֶׁחַיָּב בְּפֵאָה. כְּגוֹן הַתְּבוּאָה וְהַקִּטְנִיּוֹת וְהֶחָרוּבִין וְהָאֱגוֹזִין וְהַשְּׁקֵדִים וְהָרִמּוֹנִים וְהָעֲנָבִים וְהַזֵּיתִים וְהַתְּמָרִים בֵּין יְבֵשִׁים בֵּין רַכִּים וְכָל כַּיּוֹצֵא בְּאֵלּוּ. אֲבָל אִסְטִיס וּפוּאָה וְכַיּוֹצֵא בָּהֶן פְּטוּרִין מִפְּנֵי שֶׁאֵינָן אֹכֶל. וְכֵן כְּמֵהִין וּפִטְרִיּוֹת פְּטוּרִין מִפְּנֵי שֶׁאֵין גִּדּוּלֵיהֶן מִן הָאָרֶץ כִּשְׁאָר פֵּרוֹת הָאָרֶץ. וְכֵן הַהֶפְקֵר פָּטוּר שֶׁאֵין לוֹ מִי שֶׁיִּשְׁמְרֶנּוּ שֶׁהֲרֵי הוּא מֻפְקָר לַכּל. וְכֵן הַתְּאֵנִים פְּטוּרִין מִפְּנֵי שֶׁאֵין לְקִיטָתָן כְּאַחַת אֶלָּא יֵשׁ בְּאִילָן זֶה מַה שֶּׁיִּגָּמֵר הַיּוֹם וְיֵשׁ בּוֹ מַה שֶּׁיִּגָּמֵר לְאַחַר כַּמָּה יָמִים. וְכֵן יָרָק פָּטוּר שֶׁאֵין מַכְנִיסִין אוֹתוֹ לְקִיּוּם. הַשּׁוּמִים וְהַבְּצָלִים חַיָּבִין בְּפֵאָה שֶׁהֲרֵי מְיַבְּשִׁין אוֹתָן וּמַכְנִיסִין אוֹתָן לְקִיּוּם. וְכֵן הָאֲמָהוֹת שֶׁל בְּצָלִים שֶׁמַּנִּיחִין אוֹתָן בָּאָרֶץ לִקַּח מֵהֶן הַזֶּרַע חַיָּבוֹת בְּפֵאָה. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן:","קַרְקַע כָּל שֶׁהוּא חַיֶּבֶת בְּפֵאָה וַאֲפִלּוּ הָיְתָה שֶׁל שֻׁתָּפִין שֶׁנֶּאֱמַר (ויקרא יט ט) (ויקרא כג כב) \"קְצִיר אַרְצְכֶם\" אֲפִלּוּ שֶׁל רַבִּים:","שָׂדֶה שֶׁקָּצְרוּ נָכְרִים לְעַצְמָן אוֹ שֶׁקְּצָרוּהָ לִסְטִים אוֹ קִרְסְמוּהָ גְּמַלִּים אוֹ שְׁבָרְתָּהּ הָרוּחַ אוֹ בְּהֵמָה הֲרֵי זוֹ פְּטוּרָה מִן הַפֵּאָה. שֶׁחוֹבַת הַפֵּאָה בְּקָמָה:","קָצַר חֶצְיָהּ וְקָצְרוּ הַלִּסְטִים חֶצְיָהּ שֶׁנִּשְׁאַר הֲרֵי זוֹ פְּטוּרָה. שֶׁהַחִיּוּב בַּחֵצִי שֶׁקָּצְרוּ הַלִּסְטִים. אֲבָל אִם קָצְרוּ הַלִּסְטִים חֶצְיָהּ וְחָזַר הוּא וְקָצַר הַשְּׁאָר נוֹתֵן פֵּאָה כְּשִׁעוּר מַה שֶּׁקָּצַר. קָצַר חֶצְיָהּ וּמָכַר חֶצְיָהּ הַלּוֹקֵחַ נוֹתֵן פֵּאָה (לַכּל). קָצַר חֶצְיָהּ וְהִקְדִּישׁ חֶצְיָהּ הַפּוֹדֶה מִיַּד הַגִּזְבָּר נוֹתֵן פֵּאָה לַכּל. קָצַר חֶצְיָהּ וְהִקְדִּישׁוֹ מַנִּיחַ מִן הַנִּשְׁאָר פֵּאָה הָרְאוּיָה לַכּל:","כֶּרֶם שֶׁהָיָה בּוֹצֵר מִמֶּנּוּ עֲנָבִים לִמְכֹּר בַּשּׁוּק וּבְדַעְתּוֹ שֶׁיַּנִּיחַ הַשְּׁאָר לַגַּת לִדְרֹךְ אוֹתוֹ. אִם הָיָה בּוֹצֵר לַשּׁוּק מִכָּאן וּמִכָּאן הֲרֵי זֶה נוֹתֵן פֵּאָה לְמַה שֶּׁבּוֹצֵר לַגַּת כְּפִי הַנִּשְׁאָר. וְאִם הָיָה בּוֹצֵר לַשּׁוּק מֵרוּחַ אַחַת בִּלְבַד הֲרֵי זֶה נוֹתֵן פֵּאָה מִן הַנִּשְׁאָר כְּפִי הָרָאוּי לְכָל הַכֶּרֶם הוֹאִיל וּבָצַר מֵרוּחַ אַחַת אֵינוֹ כְּבוֹצֵר עַרְאַי מְעַט מִכָּאן וּמְעַט מִכָּאן שֶׁהוּא פָּטוּר. וְכֵן כָּל הַקּוֹטֵף מְלִילוֹת מְעַט מְעַט וּמַכְנִיס לְבֵיתוֹ אֲפִלּוּ קָטַף כֵּן כָּל שָׂדֵהוּ פָּטוּר מִן הַלֶּקֶט וּמִן הַשִּׁכְחָה וּמִן הַפֵּאָה:","הַקּוֹצֵר כָּל שָׂדֵהוּ קֹדֶם שֶׁתֻּגְמַר וַעֲדַיִן לֹא הֵבִיאָה שְׁלִישׁ הֲרֵי זוֹ פְּטוּרָה. וְאִם הִגִּיעָה לִשְׁלִישׁ חַיֶּבֶת. וְכֵן בְּפֵרוֹת הָאִילָן אִם נִגְמְרוּ שְׁלִישׁ גְּמִירָתָן חַיָּבִין:","הַמַּקְדִּישׁ שָׂדֵהוּ וְהִיא קָמָה חַיֶּבֶת בְּפֵאָה. קְצָרָהּ הַגִּזְבָּר וְאַחַר כָּךְ פְּדָאָהּ פְּטוּרָה. שֶׁבִּשְׁעַת חִיּוּב הַפֵּאָה הָיְתָה קֹדֶשׁ שֶׁאֵינוֹ חַיָּב בְּפֵאָה:","נָכְרִי שֶׁקָּצַר שָׂדֵהוּ וְאַחַר כָּךְ נִתְגַּיֵּר הֲרֵי זֶה פָּטוּר מִן הַפֵּאָה וּמִן הַלֶּקֶט וּמִן הַשִּׁכְחָה אַף עַל פִּי שֶׁאֵין הַשִּׁכְחָה אֶלָּא בִּשְׁעַת הָעִמּוּר:","אֵין שׂוֹכְרִין פּוֹעֲלִים נָכְרִים לִקְצֹר מִפְּנֵי שֶׁאֵינָן בְּקִיאִין בְּלֶקֶט וּפֵאָה. וְאִם שָׂכַר וְקָצְרוּ אֶת כֻּלּוֹ הֲרֵי זוֹ חַיֶּבֶת בְּפֵאָה:","בַּעַל הַבַּיִת שֶׁקָּצַר כָּל שָׂדֵהוּ וְלֹא הִנִּיחַ פֵּאָה. הֲרֵי זֶה נוֹתֵן מִן הַשִּׁבֳּלִים פֵּאָה לָעֲנִיִּים. וְאֵינוֹ צָרִיךְ לְעַשֵּׂר. וְאִם נָתַן לָהֶם רֹב הַקָּצִיר מִשּׁוּם פֵּאָה הֲרֵי זֶה פָּטוּר מִן הַמַּעַשְׂרוֹת. וְכֵן אִם דָּשׁ וַעֲדַיִן לֹא זָרָה נוֹתֵן לָהֶם הַפֵּאָה קֹדֶם שֶׁיְּעַשֵּׂר. אֲבָל דָּשׁ וְזָרָה בְּרַחַת וּבְמִזְרֶה וְגָמַר מְלַאכְתּוֹ מְעַשֵּׂר וְנוֹתֵן לָהֶם מִן הַפֵּרוֹת הַמְּעֻשָּׂרִין שִׁעוּר הַפֵּאָה הָרְאוּיָה לְאוֹתָהּ שָׂדֶה. וְכֵן בְּאִילָנוֹת:","אֵין מַנִּיחִין אֶת הַפֵּאָה אֶלָּא בְּסוֹף הַשָּׂדֶה. כְּדֵי שֶׁיִּהְיוּ עֲנִיִּים יוֹדְעִין מָקוֹם שֶׁיָּבוֹאוּ לוֹ וּכְדֵי שֶׁתִּהְיֶה נִכֶּרֶת לָעוֹבְרִים וְלַשָּׁבִים וְלֹא יֵחָשֵׁד. וּמִפְּנֵי הָרַמָּאִים שֶׁלֹּא יִתְכַּוֵּן לִקְצֹר הַכּל וְאוֹמֵר לְאֵלּוּ שֶׁרוֹאִים אוֹתוֹ קוֹצֵר סוֹף הַשָּׂדֶה בִּתְחִלַּת הַשָּׂדֶה הִנַּחְתִּי. וְעוֹד שֶׁלֹּא יִשְׁמֹר שָׁעָה שֶׁאֵין שָׁם אָדָם וְיַנִּיחֶנָּהּ וְיִתְּנֶנָּה לֶעָנִי הַקָּרוֹב לוֹ. עָבַר וְהִנִּיחַ הַפֵּאָה בִּתְחִלַּת הַשָּׂדֶה אוֹ בְּאֶמְצָעָהּ הֲרֵי זוֹ פֵּאָה. וְצָרִיךְ שֶׁיַּנִּיחַ בְּסוֹף הַשָּׂדֶה כְּשִׁעוּר הַפֵּאָה הָרְאוּיָה לְמַה שֶּׁנִּשְׁאַר בַּשָּׂדֶה אַחַר שֶׁהִפְרִישׁ אֶת הָרִאשׁוֹנָה:","בַּעַל הַבַּיִת שֶׁנָּתַן פֵּאָה לָעֲנִיִּים וְאָמְרוּ לוֹ תֵּן לָנוּ מִצַּד זֶה וְנָתַן לָהֶם מִצַּד אַחֵר זוֹ וְזוֹ פֵּאָה. וְכֵן בַּעַל הַשָּׂדֶה שֶׁהִפְרִישׁ פֵּאָה וְאָמַר הֲרֵי זוֹ פֵּאָה וְגַם זוֹ אוֹ שֶׁאָמַר הֲרֵי זוֹ פֵּאָה וְזוֹ הֲרֵי שְׁתֵּיהֶן פֵּאָה:","אָסוּר לַפּוֹעֲלִים לִקְצֹר אֶת כָּל הַשָּׂדֶה אֶלָּא מַנִּיחִין בְּסוֹף הַשָּׂדֶה כְּשִׁעוּר הַפֵּאָה. וְאֵין לָעֲנִיִּים בָּהּ כְּלוּם עַד שֶׁיַּפְרִישֶׁנָּה בַּעַל הַבַּיִת מִדַּעְתּוֹ. לְפִיכָךְ עָנִי שֶׁרָאָה פֵּאָה בְּסוֹף שָׂדֶה אָסוּר לִגַּע בָּהּ מִשּׁוּם גֵּזֶל עַד שֶׁיִּוָּדַע לוֹ שֶׁהִיא מִדַּעַת בַּעַל הַבַּיִת:","הַפֵּאָה שֶׁל תְּבוּאָה וְקִטְנִיּוֹת וְכַיּוֹצֵא בָּהֶן מִזְּרָעִים הַנִּקְצָרִים וְכֵן פְּאַת הַכֶּרֶם וְהָאִילָנוֹת נִתֶּנֶת בִּמְחֻבָּר לַקַּרְקַע וְהָעֲנִיִּים בּוֹזְזִין אוֹתָהּ בְּיָדָם. וְאֵין קוֹצְרִין אוֹתָהּ בְּמַגָּלוֹת וְאֵין עוֹקְרִין אוֹתָהּ בְּקַרְדֻּמּוֹת כְּדֵי שֶׁלֹּא יַכּוּ אִישׁ אֶת רֵעֵהוּ. רָצוּ הָעֲנִיִּים לְחַלְּקָהּ בֵּינֵיהֶם הֲרֵי אֵלּוּ מְחַלְּקִין. אֲפִלּוּ תִּשְׁעִים וְתִשְׁעָה אוֹמְרִין לְחַלֵּק וְאֶחָד אוֹמֵר לָבֹז לְזֶה הָאֶחָד שׁוֹמְעִין שֶׁאָמַר כַּהֲלָכָה:","פֵּאָה שֶׁל דָּלִית וְשֶׁל דֶּקֶל שֶׁאֵין עֲנִיִּים מַגִּיעִין לָבֹז אוֹתָהּ אֶלָּא בְּסַכָּנָה גְּדוֹלָה. בַּעַל הַבַּיִת מוֹרִיד אוֹתָהּ וּמְחַלֵּק אוֹתָהּ בֵּין הָעֲנִיִּים. וְאִם רָצוּ כֻּלָּן לָבֹז אוֹתָהּ לְעַצְמָן בּוֹזְזִין. אֲפִלּוּ תִּשְׁעִים וְתִשְׁעָה אוֹמְרִים לָבֹז וְאֶחָד אוֹמֵר לְחַלֵּק שׁוֹמְעִין לָאֶחָד שֶׁאָמַר כַּהֲלָכָה וּמְחַיְּבִין בַּעַל הַבַּיִת לְהוֹרִיד וּלְחַלֵּק בֵּינֵיהֶן:","בְּשָׁלֹשׁ עִתּוֹת בַּיּוֹם מְחַלְּקִין אֶת הַפֵּאָה לָעֲנִיִּים בַּשָּׂדֶה אוֹ מַנִּיחִין אוֹתָם לָבֹז. בַּשַּׁחַר. וּבַחֲצִי הַיּוֹם. וּבַמִּנְחָה. וְעָנִי שֶׁבָּא שֶׁלֹּא בִּזְמַן זֶה אֵין מַנִּיחִין אוֹתוֹ לִטּל. כְּדֵי שֶׁיִּהְיֶה עֵת קָבוּעַ לָעֲנִיִּים שֶׁיִּתְקַבְּצוּ בּוֹ כֻּלָּן לִטּל. וְלָמָּה לֹא קָבְעוּ לָהּ עֵת אַחַת בַּיּוֹם מִפְּנֵי שֶׁיֵּשׁ שָׁם עֲנִיּוֹת מֵינִיקוֹת שֶׁצְּרִיכוֹת לֶאֱכל בִּתְחִלַּת הַיּוֹם. וְיֵשׁ שָׁם עֲנִיִּים קְטַנִּים שֶׁאֵין נֵעוֹרִין בַּבֹּקֶר וְלֹא יַגִּיעוּ לַשָּׂדֶה עַד חֲצִי הַיּוֹם. וְיֵשׁ שָׁם זְקֵנִים שֶׁאֵינָם מַגִּיעִין עַד הַמִּנְחָה:","עָנִי שֶׁנָּטַל מִקְצָת הַפֵּאָה וְזָרַק עַל הַשְּׁאָר אוֹ שֶׁנָּפַל עָלֶיהָ אוֹ שֶׁפֵּרֵשׂ טַלִּיתוֹ עָלֶיהָ קוֹנְסִין אוֹתוֹ וּמַעֲבִירִין אוֹתוֹ מִמֶּנָּה וַאֲפִלּוּ מַה שֶּׁנָּטַל לוֹקְחִין אוֹתוֹ מִיָּדוֹ וְיִנָּתֵן לֶעָנִי אַחֵר [וְכֵן בְּלֶקֶט וְכֵן בְּעֹמֶר הַשִּׁכְחָה]:","מִי שֶׁלָּקַח אֶת הַפֵּאָה וְאָמַר הֲרֵי זֶה לְאִישׁ פְּלוֹנִי הֶעָנִי. אִם עָנִי הוּא זֶה שֶׁלָּקַח מִתּוֹךְ שֶׁזּוֹכֶה בּוֹ לְעַצְמוֹ זָכָה בּוֹ לְאוֹתוֹ פְּלוֹנִי. וְאִם עָשִׁיר הוּא לֹא זָכָה לוֹ אֶלָּא יִתְּנֶנָּה לֶעָנִי שֶׁנִּמְצָא רִאשׁוֹן:","בַּעַל הַבַּיִת שֶׁהִנִּיחַ פֵּאָה לַעֲנִיִּים אֵלּוּ הָעוֹמְדִים לְפָנָיו וּבָא עָנִי אַחֵר מֵאֲחוֹרָיו וּנְטָלָהּ זָכָה בָּהּ שֶׁאֵין אָדָם זוֹכֶה בְּלֶקֶט שִׁכְחָה וּפֵאָה וְסֶלַע שֶׁל מְצִיאָה עַד שֶׁיַּגִּיעַ לְיָדוֹ:"],"Mishneh Torah, Heave Offerings 13":["הַתְּרוּמָה עוֹלָה בְּאֶחָד וּמֵאָה. כֵּיצַד. סְאָה תְּרוּמָה שֶׁנָּפְלָה לְמֵאָה סְאָה שֶׁל חֻלִּין וְנִתְעָרֵב הַכֹּל מַפְרִישׁ מִן הַכֹּל סְאָה אַחַת וְנוֹתְנָהּ לַכֹּהֵן וְהַשְּׁאָר מֻתָּר לְזָרִים. וְכָל תְּרוּמָה שֶׁאֵין הַכֹּהֲנִים מַקְפִּידִין עָלֶיהָ כְּגוֹן תְּרוּמַת הַכְּלִיסִין וְהֶחָרוּבִין וְהַשְּׂעוֹרִים שֶׁל אֱדוֹם אֵינוֹ צָרִיךְ לְהַגְבִּיהַּ הוֹאִיל וְנָפְלָה בְּמֵאָה בָּטְלָה בְּמִעוּטָהּ וְהַכֹּל מֻתָּר לְזָרִים:","נָפְלָה סְאָה תְּרוּמָה לְפָחוֹת מִמֵּאָה נַעֲשֶׂה הַכֹּל מְדֻמָּע וְיִמְכֹּר הַכֹּל לַכֹּהֲנִים בִּדְמֵי תְּרוּמָה חוּץ מִדְּמֵי אוֹתָהּ סְאָה. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁנִּתְעָרֵב מִין בְּמִינוֹ. אֲבָל מִין בְּשֶׁאֵינוֹ מִינוֹ בְּנוֹתֵן טַעַם אִם יֵשׁ בַּכֹּל טַעַם תְּרוּמָה נַעֲשָׂה הַכֹּל מְדֻמָּע וְיִמָּכֵר לַכֹּהֲנִים חוּץ מִדְּמֵי תְּרוּמָה שֶׁבּוֹ. וְאִם טַעַם הַכֹּל טַעַם חֻלִּין הַכֹּל מֻתָּר לְזָרִים:","סְאָה תְּרוּמָה שֶׁנָּפְלָה לְמֵאָה וְהִגְבִּיהַּ סְאָה מִן הַכֹּל וְנָפְלָה הַסְּאָה שֶׁהִגְבִּיהַּ לְמָקוֹם אַחֵר אֵינָהּ מְדַמַּעַת אֶלָּא לְפִי חֶשְׁבּוֹן. וְכֵן סְאָה תְּרוּמָה שֶׁנָּפְלָה לְפָחוֹת מִמֵּאָה וְנַעֲשָׂה הַכֹּל מְדֻמָּע וְנָפַל מִן הַמְדֻמָּע לְמָקוֹם אַחֵר אֵינוֹ מְדַמֵּעַ אֶלָּא לְפִי חֶשְׁבּוֹן. כֵּיצַד. הֲרֵי שֶׁנָּפְלוּ עֶשֶׂר סְאִין שֶׁל תְּרוּמָה לְתִשְׁעִים סְאָה חֻלִּין וְנִדְמְעוּ הַכֹּל אִם נָפַל מִמְּדֻמָּע זֶה עֶשֶׂר סְאִין לְפָחוֹת מִמֵּאָה חֻלִּין נִדְמְעוּ שֶׁהֲרֵי יֵשׁ בְּעֶשֶׂר שֶׁל מְדֻמָּע סְאָה שֶׁל תְּרוּמָה. נָפַל לְתוֹכָן פָּחוֹת מֵעֶשֶׂר סְאִין אֵינָן מְדַמְּעוֹת:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּדָבָר שֶׁאֵין דַּרְכּוֹ לְהִבָּלֵל כְּגוֹן חִטִּים לְחִטִּים אוֹ קֶמַח לְקֶמַח. אֲבָל דַּרְכּוֹ לְהִבָּלֵל כְּגוֹן שֶׁמֶן תְּרוּמָה לְשֶׁמֶן חֻלִּין אוֹ יֵין תְּרוּמָה לְיֵין חֻלִּין הוֹלְכִין אַחַר הָרֹב. אִם רֹב תְּרוּמָה הֲרֵי זֶה מְדַמֵּעַ כִּתְרוּמָה. וְאִם רֹב חֻלִּין הֲרֵי הוּא כְּחֻלִּין וְאֵינוֹ מְדַמֵּעַ אַף עַל פִּי שֶׁהַכֹּל אֲסוּרִים לְזָרִים:","סְאָה תְּרוּמָה שֶׁנָּפְלָה לְמֵאָה הִגְבִּיהָהּ וְנָפְלָה אַחֶרֶת הִגְבִּיהָהּ וְנָפְלָה אַחֶרֶת הֲרֵי הַחֻלִּין מֻתָּרִין עַד שֶׁתִּרְבֶּה תְּרוּמָה עֲלֵיהֶן. שֶׁאִם נָפְלוּ לְתוֹךְ הַמֵּאָה חֻלִּין מֵאָה סְאָה וְעוֹד שֶׁל תְּרוּמָה סְאָה אַחַר סְאָה נַעֲשָׂה הַכֹּל מְדֻמָּע:","סְאָה תְּרוּמָה שֶׁנָּפְלָה לְמֵאָה וְלֹא הִסְפִּיק לְהַגְבִּיהָהּ עַד שֶׁנָּפְלָה סְאָה אַחֶרֶת. אִם יָדַע בָּרִאשׁוֹנָה קֹדֶם שֶׁתִּפּל הַשְּׁנִיָּה לֹא נִדְמְעוּ. אֶלָּא מַפְרִישׁ סָאתַיִם וְהַשְּׁאָר מֻתָּר הוֹאִיל וְהָיָה לָהּ לַעֲלוֹת הֲרֵי הִיא כְּאִלּוּ עָלְתָה. וְאִם לֹא יָדַע בִּסְאָה רִאשׁוֹנָה אֶלָּא אַחַר שֶׁנָּפְלָה הַשְּׁנִיָּה הֲרֵי זֶה מְדֻמָּע וּכְאִלּוּ נָפְלוּ שְׁתֵּיהֶן כְּאַחַת:","אֵין פְּסֹלֶת שֶׁל תְּרוּמָה מִצְטָרֶפֶת עִמָּהּ לֶאֱסֹר הַחֻלִּין. אֲבָל פְּסֹלֶת הַחֻלִּין מִצְטָרֶפֶת עִם הַחֻלִּין לְהַעֲלוֹת הַתְּרוּמָה. כֵּיצַד. סְאָה חִטִּים יָפוֹת שֶׁל תְּרוּמָה שֶׁנָּפְלָה לְמֵאָה סְאָה חִטִּים רָעוֹת שֶׁל חֻלִּין וְטָחַן הַכֹּל. אַף עַל פִּי שֶׁהַמֻּרְסָן שֶׁל חֻלִּין מְרֻבִּין וְשֶׁל תְּרוּמָה מֻעָט וַהֲרֵי קֶמַח שֶׁל תְּרוּמָה בְּפָחוֹת מִמֵּאָה מִקֶּמַח הַחֻלִּין הֲרֵי זֶה עוֹלֶה וּמְשַׁעֲרִין בְּקֶמַח עִם הַמֻּרְסָן שֶׁהוּא מֵאָה וְאֶחָד. אֲבָל אִם נָפְלָה סְאָה חִטִּים רָעוֹת שֶׁל תְּרוּמָה לְפָחוֹת מִמֵּאָה סְאָה חִטִּים יָפוֹת שֶׁל חֻלִּין וְטָחַן הַכֹּל וַהֲרֵי הַקֶּמַח שֶׁל תְּרוּמָה אֶחָד מִמֵּאָה מִקֶּמַח הַחֻלִּין הֲרֵי זֶה עוֹלֶה בְּמֵאָה וְאֶחָד שֶׁהֲרֵי הוֹתִירוּ הַחֻלִּין וּפָחֲתָה הַתְּרוּמָה:","לוֹג יַיִן שֶׁל תְּרוּמָה צָלוּל שֶׁנָּפַל לְמֵאָה לוֹגִין עֲכוּרִין אֵין מוֹצִיאִין שְׁמָרִים שֶׁבָּהֶם. אֶלָּא מַעֲלִין אֶת הַלּוֹג. וְכֵן אִם נָפַל לוֹג עָכוּר לְמֵאָה לוֹגִין צְלוּלִין אֵין מוֹצִיאִין שְׁמָרִים שֶׁבּוֹ:","לוֹג מַיִם שֶׁנָּפַל לְתִשְׁעִים וְתִשְׁעָה לוֹגִין יַיִן וְאַחַר כָּךְ נָפַל לְתוֹךְ הַכֹּל לוֹג יַיִן שֶׁל תְּרוּמָה נִדְמַע הַכֹּל. שֶׁאֵין הַמַּיִם מַעֲלֶה אֶת הַיַּיִן:","סְאָה תְּרוּמָה שֶׁנָּפְלָה לְפָחוֹת מִמֵּאָה חֻלִּין וְנָפְלוּ חֻלִּין אֲחֵרִים עַד שֶׁהוֹסִיפוּ עַל מֵאָה. אִם בְּשׁוֹגֵג הֲרֵי זוֹ עוֹלָה בְּמֵאָה וְאֶחָד. וְאִם בְּמֵזִיד הֲרֵי הַכֹּל מְדֻמָּע שֶׁאֵין מְבַטְּלִין אִסּוּרֵי תּוֹרָה לְכַתְּחִלָּה:","תְּרוּמַת חוּצָה לָאָרֶץ מֻתָּר לְבַטְּלָהּ בְּרֹב וְאוֹכְלָהּ בִּימֵי טֻמְאָתוֹ וְלֹא עוֹד אֶלָּא אִם הָיָה לוֹ יַיִן שֶׁל תְּרוּמַת חוּצָה לָאָרֶץ נוֹטֵל מִמֶּנּוּ לוֹג אֶחָד וְנוֹתֵן עָלָיו שְׁנֵי לוֹגִין חֻלִּין וְנִמְצָא הַכֹּל שְׁלֹשָׁה וְאַחַר כָּךְ נוֹטֵל מִיַּיִן שֶׁל תְּרוּמָה לוֹג וְנוֹתֵן לְתוֹךְ הַשְּׁלֹשָׁה וּמַגְבִּיהַּ מֵאַרְבַּעְתָּן לוֹג וְשׁוֹתֶה. וְחוֹזֵר וּמַשְׁלִיךְ לְתוֹכָן לוֹג אַחֵר וְחוֹזֵר וְנוֹטֵל לוֹג וְשׁוֹתֶה. וְכֵן נוֹתֵן לוֹג תְּרוּמָה וְנוֹטֵל לוֹג מִן הַתַּעֲרֹבֶת עַד שֶׁיִּכְלֶה כָּל הַיַּיִן שֶׁל תְּרוּמָה. וְנִמְצָא שֶׁנָּטַל כַּמָּה לוֹגִין בִּשְׁנֵי לוֹגִין שֶׁל חֻלִּין:","הַזּוֹרֵעַ תְּרוּמָה בְּצַד הַחֻלִּין וְלֹא נוֹדַע אֵי זֶהוּ זֶרַע תְּרוּמָה אֲפִלּוּ הָיָה מֵאָה לְגִנָּה שֶׁל תְּרוּמָה וּלְגִנָּה אַחַת שֶׁל חֻלִּין כֻּלָּן מֻתָּרִין. בַּמֶּה דְּבָרִים אֲמוּרִים בְּדָבָר שֶׁזַּרְעוֹ כָּלֶה בַּקַּרְקַע כְּגוֹן הַחִטִּים וְהַשְּׂעוֹרִים וְכַיּוֹצֵא בָּהֶן. אֲבָל דָּבָר שֶׁאֵין זַרְעוֹ נִפְסָד בָּאָרֶץ כְּגוֹן הַשּׁוּם וְהַבְּצָלִים אֲפִלּוּ מֵאָה לְגִנָּה שֶׁל חֻלִּין וּלְגִנָּה אַחַת שֶׁל תְּרוּמָה תַּעֲרֹבֶת בֵּינֵיהֶן הֲרֵי הַכֹּל מְדֻמָּע. וְאִם נִתְלַשׁ הַכֹּל תַּעֲלֶה הַתְּרוּמָה בְּאֶחָד וּמֵאָה וְלֹא יִתְלֹשׁ לְכַתְּחִלָּה:","שְׁתֵּי קֻפּוֹת אַחַת שֶׁל תְּרוּמָה וְאַחַת שֶׁל חֻלִּין וְאֵין יָדוּעַ אֵי זוֹ הִיא. אוֹ שֶׁנָּפְלָה סְאָה שֶׁל תְּרוּמָה לְתוֹךְ אַחַת מֵהֶן וְאֵין יָדוּעַ לְהֵיכָן נָפְלָה וְאַחַר כָּךְ נָפְלָה אַחַת מִשְּׁתֵּי קֻפּוֹת לְתוֹךְ הַחֻלִּין אֵינָן מְדַמַּעְתָּן. וְכֵן אִם זָרַע אַחַת מֵהֶם הַגִּדּוּלִין חֻלִּין לְכָל דָּבָר. וְהַשְּׁנִיָּה נוֹהֵג בָּהּ כִּתְרוּמָה. נָפְלָה הַקֻּפָּה הַשְּׁנִיָּה לְמָקוֹם אַחֵר אֵינָהּ מְדַמַּעַת. וְכֵן אִם זָרַע אַחֵר אֶת הַשְּׁנִיָּה הַגִּדּוּלִין חֻלִּין. נָפְלוּ שְׁתֵּיהֶן לְמָקוֹם אֶחָד מְדַמַּעַת כַּקְּטַנָּה שֶׁבִּשְׁתֵּיהֶן. זָרַע אֶחָד אֶת שְׁתֵּיהֶם בְּדָבָר שֶׁזַּרְעוֹ כָּלֶה הַגִּדּוּלִין חֻלִּין. וּבְדָבָר שֶׁאֵין זַרְעוֹ כָּלֶה הַגִּדּוּלִין מְדֻמָּע. בַּמֶּה דְּבָרִים אֲמוּרִים בְּזוֹרֵעַ אֶת הַשְּׁנִיָּה עַד שֶׁלֹּא קָצַר אֶת הָרִאשׁוֹנָה. אֲבָל קָצַר אֶת הָרִאשׁוֹנָה וְאַחַר כָּךְ זָרַע אֶת הַשְּׁנִיָּה אֲפִלּוּ בְּדָבָר שֶׁאֵין זַרְעוֹ כָּלֶה הַגִּדּוּלִין חֻלִּין שֶׁאֵין תָּלוּשׁ וּמְחֻבָּרִין נַעֲשִׂין חוֹבָה זֶה לָזֶה:","שְׁתֵּי קֻפּוֹת אַחַת שֶׁל חֻלִּין וְאַחַת שֶׁל תְּרוּמָה וְלִפְנֵיהֶן שְׁתֵּי סְאִין אַחַת שֶׁל חֻלִּין וְאַחַת שֶׁל תְּרוּמָה וְנָפְלוּ אֵלּוּ לְתוֹךְ אֵלּוּ מֻתָּרִין. שֶׁאֲנִי אוֹמֵר חֻלִּין לְתוֹךְ חֻלִּין נָפְלוּ וּתְרוּמָה לְתוֹךְ הַתְּרוּמָה וְאַף עַל פִּי שֶׁלֹּא רַבּוּ חֻלִּין עַל הַתְּרוּמָה. בַּמֶּה דְּבָרִים אֲמוּרִים בִּתְרוּמָה בַּזְּמַן הַזֶּה שֶׁהוּא מִדִּבְרֵיהֶם. אֲבָל בִּתְרוּמָה שֶׁל תּוֹרָה עַד שֶׁיִּרְבּוּ חֻלִּין עַל הַתְּרוּמָה:","סְאָה תְּרוּמָה שֶׁנָּפְלָה לְתוֹךְ הַכְּרִי וְאָמַר תְּרוּמַת הַכְּרִי זֶה לְתוֹכוֹ בְּמָקוֹם שֶׁנָּפְלָה אוֹתָהּ סְאָה שָׁם נִסְתַיְּמָה תְּרוּמַת הַכְּרִי וְנִדְמַע הַכֹּל בִּתְרוּמָה שֶׁנָּפְלָה וּבִתְרוּמַת הַכְּרִי. אָמַר תְּרוּמַת הַכְּרִי בִּצְפוֹנוֹ חוֹלְקִין אוֹתוֹ לִשְׁנַיִם וְהַחֵצִי שֶׁבַּצָּפוֹן לִשְׁנַיִם וְנִמְצָא רְבִיעַ הַכְּרִי שֶׁהוּא צְפוֹן צְפוֹנִי הוּא הַמְדֻמָּע:","הָיוּ לְפָנָיו שְׁנֵי כְּרָיִים וְאָמַר תְּרוּמַת שְׁנֵי כְּרָיִים בְּאֶחָד מֵהֶן הֲרֵי שְׁנֵיהֶן מְדֻמָּעִין. הָיוּ לְפָנָיו שְׁתֵּי סְאִין וּכְרִי אֶחָד וְאָמַר הֲרֵי אַחַת מִן הַסְּאִין הָאֵלּוּ עֲשׂוּיָה תְּרוּמָה עַל הַכְּרִי הַזֶּה הֲרֵי אַחַת מֵהֶן תְּרוּמָה וְאֵין יָדוּעַ אֵי זוֹ הִיא. הָיוּ לְפָנָיו שְׁנֵי כְּרָיִים וּסְאָה אַחַת וְאָמַר הֲרֵי זוֹ תְּרוּמָה עַל אֶחָד מִן הַכְּרָיִים הַלָּלוּ הֲרֵי הוּא תְּרוּמָה וְנִתְקַן אֶחָד מֵהֶן וְאֵין יָדוּעַ אֵי זֶה הוּא הַמְתֻקָּן מִן הַטֶּבֶל:"],"Mishneh Torah, Hiring 10":["הַמַּלְוֶה אֶת חֲבֵרוֹ עַל הַמַּשְׁכּוֹן בֵּין שֶׁהִלְוָהוּ מָעוֹת בֵּין שֶׁהִלְוָהוּ פֵּרוֹת בֵּין שֶׁמִּשְׁכְּנוֹ בִּשְׁעַת הַלְוָאָתוֹ בֵּין שֶׁמִּשְׁכְּנוֹ אַחַר שֶׁהִלְוָהוּ הֲרֵי זֶה שׁוֹמֵר שָׂכָר. לְפִיכָךְ אִם אָבַד הַמַּשְׁכּוֹן אוֹ נִגְנַב חַיָּב בְּדָמָיו. וְאִם נֶאֱנַס הַמַּשְׁכּוֹן כְּגוֹן שֶׁנִּלְקַח בְּלִסְטִים מְזֻיָּן וְכַיּוֹצֵא בּוֹ מִשְּׁאָר אֳנָסִין יִשָּׁבַע שֶׁנֶּאֱנַס וִישַׁלֵּם בַּעַל הַמַּשְׁכּוֹן אֶת חוֹבוֹ עַד פְּרוּטָה אַחֲרוֹנָה:","כָּל הָאוֹמֵר לַחֲבֵרוֹ שְׁמֹר לִי וְאֶשְׁמֹר לְךָ הֲרֵי זֶה שְׁמִירָה בַּבְּעָלִים. אָמַר לוֹ שְׁמֹר לִי הַיּוֹם וְאֶשְׁמֹר לְךָ לְמָחָר. הַשְׁאִילֵנִי הַיּוֹם וַאֲנִי אַשְׁאִילְךָ לְמָחָר. שְׁמֹר לִי הַיּוֹם וְאַשְׁאִילְךָ לְמָחָר. הַשְׁאִילֵנִי הַיּוֹם וְאֶשְׁמֹר לְךָ לְמָחָר. כֻּלָּן נַעֲשׂוּ שׁוֹמְרֵי שָׂכָר זֶה לָזֶה:","כָּל הָאֻמָּנִין שׁוֹמְרֵי שָׂכָר הֵן. וְכֻלָּן שֶׁאָמְרוּ טל אֶת שֶׁלְּךָ וְהָבֵא מָעוֹת אוֹ שֶׁאוֹמֵר לוֹ הָאֻמָּן גְּמַרְתִּיו וְלֹא לָקְחוּ הַבְּעָלִים אֶת הַכְּלִי הָאֻמָּן שׁוֹמֵר חִנָּם. אֲבָל אִם אָמַר הָאֻמָּן הָבֵא מָעוֹת וְטל שֶׁלְּךָ עֲדַיִן הוּא נוֹשֵׂא שָׂכָר כְּשֶׁהָיָה:","נָתַן לְאֻמָּנִין לְתַקֵּן וְקִלְקְלוּ חַיָּבִין לְשַׁלֵּם. כֵּיצַד. נָתַן לְחֵרֵשׁ שִׁדָּה תֵּבָה וּמִגְדָּל לִקְבֹּעַ בָּהֶן מַסְמֵר וּשְׁבָרוֹ אוֹ שֶׁנָּתַן לוֹ אֶת הָעֵצִים לַעֲשׂוֹת מֵהֶן שִׁדָּה תֵּבָה וּמִגְדָּל וְנִשְׁבְּרוּ אַחַר שֶׁנַּעֲשׂוּ מְשַׁלֵּם לוֹ דְּמֵי שִׁדָּה תֵּבָה וּמִגְדָּל. שֶׁאֵין הָאֻמָּן קוֹנֶה בְּשֶׁבַח הַכְּלִי. נָתַן צֶמֶר לְצַבָּע וְהִקְדִיחַתּוּ יוֹרָה נוֹתֵן לוֹ דְּמֵי צִמְרוֹ. צְבָעוֹ כָּעוּר אוֹ נְתָנוֹ לוֹ לְצָבְעוֹ אָדֹם וּצְבָעוֹ שָׁחוֹר שָׁחוֹר וּצְבָעוֹ אָדֹם. נָתַן עֵצִים לְחָרָשׁ לַעֲשׂוֹת מֵהֶן כִּסֵּא נָאֶה וְעָשָׂה כִּסֵּא רַע אוֹ סַפְסָל. אִם הַשֶּׁבַח יָתֵר עַל הַהוֹצָאָה נוֹתֵן בַּעַל הַכְּלִי אֶת הַהוֹצָאָה וְאִם הַהוֹצָאָה יְתֵרָה עַל הַשֶּׁבַח נוֹתֵן לוֹ אֶת הַשֶּׁבַח בִּלְבַד. אָמַר בַּעַל הַכְּלִי אֵינִי רוֹצֶה בְּתַקָּנָה זוֹ אֶלָּא יִתֵּן לִי דְּמֵי הַצֶּמֶר אוֹ דְּמֵי הָעֵצִים אֵין שׁוֹמְעִין לוֹ. וְכֵן אִם אָמַר הָאֻמָּן הֵא לְךָ דְּמֵי צִמְרְךָ אוֹ דְּמֵי עֵצְךָ וְלֵךְ אֵין שׁוֹמְעִין לוֹ שֶׁאֵין הָאֻמָּן קוֹנֶה בְּשֶׁבַח כְּלִי שֶׁעָשָׂה:","הַמּוֹלִיךְ חִטִּין לִטְחֹן וְלֹא לְתָתָן וַעֲשָׂאָן סֻבִּין אוֹ מֻרְסָן. נָתַן הַקֶּמַח לְנַחְתּוֹם וַעֲשָׂאוֹ פַּת נְפוֹלִין. בְּהֵמָה לְטַבָּח וְנִבְּלָהּ. חַיָּבִין לְשַׁלֵּם דְּמֵיהֶן מִפְּנֵי שֶׁהֵן נוֹשְׂאֵי שָׂכָר. לְפִיכָךְ אִם הָיָה טַבָּח מֻמְחֶה וְשָׁחַט בְּחִנָּם פָּטוּר מִלְּשַׁלֵּם וְאֵינוֹ מֻמְחֶה אַף עַל פִּי שֶׁהוּא בְּחִנָּם חַיָּב לְשַׁלֵּם. וְכֵן הַמַּרְאֶה דִּינָר לְשֻׁלְחָנִי וְאָמַר לוֹ יָפֶה הוּא וְנִמְצָא רַע אִם בְּשָׂכָר רָאָהוּ חַיָּב לְשַׁלֵּם אַף עַל פִּי שֶׁהוּא בָּקִי וְאֵינוֹ צָרִיךְ לְהִתְלַמֵּד. וְאִם בְּחִנָּם רָאָהוּ פָּטוּר וְהוּא שֶׁיִּהְיֶה בָּקִי שֶׁאֵינוֹ צָרִיךְ לְהִתְלַמֵּד. וְאִם אֵינוֹ בָּקִי חַיָּב לְשַׁלֵּם אַף עַל פִּי שֶׁהוּא בְּחִנָּם וְהוּא שֶׁיֹּאמַר לַשֻּׁלְחָנִי עָלֶיךָ אֲנִי סוֹמֵךְ אוֹ שֶׁהָיוּ הַדְּבָרִים מַרְאִין שֶׁהוּא סוֹמֵךְ עַל רְאִיָּתוֹ וְלֹא יַרְאֶה לַאֲחֵרִים. טַבָּח שֶׁעָשָׂה בְּחִנָּם וְנִבֵּל וְכֵן שֻׁלְחָנִי שֶׁאָמַר יָפֶה וְנִמְצָא רַע וְכֵן כָּל כַּיּוֹצֵא בָּזֶה עֲלֵיהֶן לְהָבִיא רְאָיָה שֶׁהֵן מֻמְחִין. וְאִם לֹא הֵבִיאוּ רְאָיָה מְשַׁלְּמִין:","מָקוֹם שֶׁנָּהֲגוּ שֶׁיִּהְיֶה הַנּוֹטֵעַ אִילָנוֹת נוֹטֵל חֲצִי הַשֶּׁבַח וּבַעַל הַקַּרְקַע חֲצִי וְנָטַע וְהִשְׁבִּיחַ וְנָטַע וְהִפְסִיד מְחַשְּׁבִין לוֹ חֲצִי הַשֶּׁבַח שֶׁיֵּשׁ לוֹ וּמְנַכִּין מִמֶּנּוּ מַה שֶּׁהִפְסִיד וְנוֹטֵל הַשְּׁאָר. וַאֲפִלּוּ הִתְנָה עַל עַצְמוֹ שֶׁאִם הִפְסִיד לֹא יִטּל כְּלוּם הֲרֵי זֶה אַסְמַכְתָּא וְאֵין מְנַכִּין לוֹ אֶלָּא מַה שֶּׁהִפְסִיד. הָיָה מִנְהָגָם שֶׁיִּטּל הַנּוֹטֵעַ מֶחֱצָה וּבַעַל הַקַּרְקַע מֶחֱצָה וְכָךְ הָיָה מִנְהָגָם שֶׁיִּטּל הָאָרִיס שְׁלִישׁ. אִם נָטַע הַנּוֹטֵעַ וְהִשְׁבִּיחַ וְרָצָה לְהִסְתַּלֵּק שֶׁנִּמְצָא בַּעַל הַקַּרְקַע צָרִיךְ לְהוֹרִיד לָהּ אָרִיס הֲרֵי בַּעַל הַקַּרְקַע מוֹרִיד אָרִיס וְיִטּל בַּעַל הַקַּרְקַע חֶצְיוֹ וְלֹא יַפְסִיד בַּעַל הַקַּרְקַע כְּלוּם וְיִטּל הָאָרִיס שְׁלִישׁ וְהַשְּׁתוּת הַנִּשְׁאָר שֶׁל נוֹטֵעַ שֶׁהֲרֵי סִלֵּק עַצְמוֹ בִּרְצוֹנוֹ:","הַנּוֹטֵעַ אִילָנוֹת לִבְנֵי הַמְּדִינָה שֶׁהִפְסִיד. וְכֵן טַבָּח שֶׁל בְּנֵי הָעִיר שֶׁנִּבֵּל הַבְּהֵמוֹת. וְהַמַּקִּיז דָּם שֶׁחָבַל. וְהַסּוֹפֵר שֶׁטָּעָה בִּשְׁטָרוֹת. וּמְלַמֵּד תִּינוֹקוֹת שֶׁפָּשַׁע בְּתִינוֹקוֹת וְלֹא לִמֵּד אוֹ לִמֵּד בְּטָעוּת. וְכָל כַּיּוֹצֵא בְּאֵלּוּ הָאֻמָּנִים שֶׁאִי אֶפְשָׁר שֶׁיַּחְזִירוּ הַהֶפְסֵד שֶׁהִפְסִידוּ. מְסַלְּקִין אוֹתָן בְּלֹא הַתְרָאָה שֶׁהֵן כְּמֻתְרִין וְעוֹמְדִין עַד שֶׁיִּשְׁתַּדְּלוּ בִּמְלַאכְתָּן הוֹאִיל וְהֶעֱמִידוּ אוֹתָן הַצִּבּוּר עֲלֵיהֶם:"],"Mishneh Torah, Human Dispositions 1":["דֵעוֹת הַרְבֵּה יֵשׁ לְכָל אֶחָד וְאֶחָד מִבְּנֵי אָדָם וְזוֹ מְשֻׁנָּה מִזּוֹ וּרְחוֹקָה מִמֶּנָּהּ בְּיוֹתֵר. יֵשׁ אָדָם שֶׁהוּא בַּעַל חֵמָה כּוֹעֵס תָּמִיד. וְיֵשׁ אָדָם שֶׁדַּעְתּוֹ מְיֻשֶּׁבֶת עָלָיו וְאֵינוֹ כּוֹעֵס כְּלָל וְאִם יִכְעַס יִכְעַס כַּעַס מְעַט בְּכַמָּה שָׁנִים. וְיֵשׁ אָדָם שֶׁהוּא גְּבַהּ לֵב בְּיוֹתֵר. וְיֵשׁ שֶׁהוּא שְׁפַל רוּחַ בְּיוֹתֵר. וְיֵשׁ שֶׁהוּא בַּעַל תַּאֲוָה לֹא תִּשְׂבַּע נַפְשׁוֹ מֵהָלֹךְ בְּתַאֲוָה. וְיֵשׁ שֶׁהוּא בַּעַל לֵב טָהוֹר מְאֹד וְלֹא יִתְאַוֶּה אֲפִלּוּ לִדְבָרִים מְעַטִּים שֶׁהַגּוּף צָרִיךְ לָהֶן. וְיֵשׁ בַּעַל נֶפֶשׁ רְחָבָה שֶׁלֹּא תִּשְׂבַּע נַפְשׁוֹ מִכָּל מָמוֹן הָעוֹלָם, כָּעִנְיָן שֶׁנֶּאֱמַר (קהלת ה ט) \"אוֹהֵב כֶּסֶף לֹא יִשְׂבַּע כֶּסֶף\". וְיֵשׁ מְקַצֵּר נַפְשׁוֹ שֶׁדַּיּוֹ אֲפִלּוּ דָּבָר מְעַט שֶׁלֹּא יַסְפִּיק לוֹ וְלֹא יִרְדֹּף לְהַשִּׂיג כָּל צָרְכּוֹ. וְיֵשׁ שֶׁהוּא מְסַגֵּף עַצְמוֹ בְּרָעָב וְקוֹבֵץ עַל יָדוֹ וְאֵינוֹ אוֹכֵל פְּרוּטָה מִשֶּׁלּוֹ אֶלָּא בְּצַעַר גָּדוֹל. וְיֵשׁ שֶׁהוּא מְאַבֵּד כָּל מָמוֹנוֹ בְּיָדוֹ לְדַעְתּוֹ. וְעַל דְּרָכִים אֵלּוּ שְׁאָר כָּל הַדֵּעוֹת כְּגוֹן מְהוֹלֵל וְאוֹנֵן וְכִילַי וְשׁוֹעַ וְאַכְזָרִי וְרַחֲמָן וְרַךְ לֵבָב וְאַמִּיץ לֵב וְכַיּוֹצֵא בָּהֶן:","וְיֵשׁ בֵּין כָּל דֵּעָה וְדֵעָה הָרְחוֹקָה מִמֶּנָּה בַּקָּצֶה הָאַחֵר דֵּעוֹת בֵּינוֹנִיּוֹת זוֹ רְחוֹקָה מִזּוֹ. וְכָל הַדֵּעוֹת יֵשׁ מֵהֶן דֵּעוֹת שֶׁהֵן לָאָדָם מִתְּחִלַּת בְּרִיָּתוֹ לְפִי טֶבַע גּוּפוֹ. וְיֵשׁ מֵהֶן דֵּעוֹת שֶׁטִּבְעוֹ שֶׁל אָדָם זֶה מְכֻוָּן וְעָתִיד לְקַבֵּל אוֹתָם בִּמְהֵרָה יוֹתֵר מִשְּׁאָר הַדֵּעוֹת. וְיֵשׁ מֵהֶן שֶׁאֵינָן לָאָדָם מִתְּחִלַּת בְּרִיָּתוֹ אֶלָּא לָמַד אוֹתָם מֵאֲחֵרִים אוֹ שֶׁנִּפְנָה לָהֶן מֵעַצְמוֹ לְפִי מַחֲשָׁבָה שֶׁעָלְתָה בְּלִבּוֹ. אוֹ שֶׁשָּׁמַע שֶׁזּוֹ הַדֵּעָה טוֹבָה לוֹ וּבָהּ רָאוּי לֵילֵךְ וְהִנְהִיג עַצְמוֹ בָּהּ עַד שֶׁנִּקְבְּעָה בְּלִבּוֹ:","שְׁתֵּי קְצָווֹת הָרְחוֹקוֹת זוֹ מִזּוֹ שֶׁבְּכָל דֵּעָה וְדֵעָה אֵינָן דֶּרֶךְ טוֹבָה וְאֵין רָאוּי לוֹ לָאָדָם לָלֶכֶת בָּהֶן וְלֹא לְלַמְּדָן לְעַצְמוֹ. וְאִם מָצָא טִבְעוֹ נוֹטֶה לְאַחַת מֵהֶן אוֹ מוּכָן לְאַחַת מֵהֶן אוֹ שֶׁכְּבָר לָמֵד אַחַת מֵהֶן וְנָהַג בָּהּ יַחֲזִיר עַצְמוֹ לַמּוּטָב וְיֵלֵךְ בְּדֶרֶךְ הַטּוֹבִים וְהִיא הַדֶּרֶךְ הַיְשָׁרָה:","הַדֶּרֶךְ הַיְשָׁרָה הִיא מִדָּה בֵּינוֹנִית שֶׁבְּכָל דֵּעָה וְדֵעָה מִכָּל הַדֵּעוֹת שֶׁיֵּשׁ לוֹ לָאָדָם. וְהִיא הַדֵּעָה שֶׁהִיא רְחוֹקָה מִשְּׁתֵּי הַקְּצָווֹת רִחוּק שָׁוֶה וְאֵינָהּ קְרוֹבָה לֹא לָזוֹ וְלֹא לָזוֹ. לְפִיכָךְ צִוּוּ חֲכָמִים הָרִאשׁוֹנִים שֶׁיְּהֵא אָדָם שָׁם דֵּעוֹתָיו תָּמִיד וּמְשַׁעֵר אוֹתָם וּמְכַוִּן אוֹתָם בַּדֶּרֶךְ הָאֶמְצָעִית כְּדֵי שֶׁיְּהֵא שָׁלֵם בְּגוּפוֹ. כֵּיצַד. לֹא יְהֵא בַּעַל חֵמָה נוֹחַ לִכְעֹס וְלֹא כְּמֵת שֶׁאֵינוֹ מַרְגִּישׁ אֶלָּא בֵּינוֹנִי. לֹא יִכְעֹס אֶלָּא עַל דָּבָר גָּדוֹל שֶׁרָאוּי לִכְעֹס עָלָיו כְּדֵי שֶׁלֹּא יֵעָשֶׂה כַּיּוֹצֵא בּוֹ פַּעַם אַחֶרֶת. וְכֵן לֹא יִתְאַוֶּה אֶלָּא לִדְבָרִים שֶׁהַגּוּף צָרִיךְ לָהֶן וְאִי אֶפְשָׁר לִהְיוֹת בְּזוּלָתָן כָּעִנְיָן שֶׁנֶּאֱמַר (משלי יג כה) \"צַדִּיק אֹכֵל לְשֹׂבַע נַפְשׁוֹ\". וְכֵן לֹא יִהְיֶה עָמֵל בְּעִסְקוֹ אֶלָּא לְהַשִּׂיג דָּבָר שֶׁצָּרִיךְ לוֹ לְחַיֵּי שָׁעָה כָּעִנְיָן שֶׁנֶּאֱמַר (תהילים לז טז) \"טוֹב מְעַט לַצַּדִּיק\". וְלֹא יִקְפֹּץ יָדוֹ בְּיוֹתֵר. וְלֹא יְפַזֵּר מָמוֹנוֹ אֶלָּא נוֹתֵן צְדָקָה כְּפִי מִסַּת יָדוֹ וּמַלְוֶה כָּרָאוּי לְמִי שֶׁצָּרִיךְ. וְלֹא יְהֵא מְהוֹלֵל וְשׂוֹחֵק וְלֹא עָצֵב וְאוֹנֵן אֶלָּא שָׂמֵחַ כָּל יָמָיו בְּנַחַת בְּסֵבֶר פָּנִים יָפוֹת. וְכֵן שְׁאָר דֵּעוֹתָיו. וְדֶרֶךְ זוֹ הִיא דֶּרֶךְ הַחֲכָמִים. כָּל אָדָם שֶׁדֵּעוֹתָיו דֵּעוֹת (בֵּינוֹנִית) [בֵּינוֹנִיּוֹת] מְמֻצָּעוֹת נִקְרָא חָכָם:","וּמִי שֶׁהוּא מְדַקְדֵּק עַל עַצְמוֹ בְּיוֹתֵר וְיִתְרַחֵק מִדֵּעָה בֵּינוֹנִית מְעַט לְצַד זֶה אוֹ לְצַד זֶה נִקְרָא חָסִיד. כֵּיצַד. מִי שֶׁיִּתְרַחֵק מִגֹּבַהּ הַלֵּב עַד הַקָּצֶה הָאַחֲרוֹן וְיִהְיֶה שְׁפַל רוּחַ בְּיוֹתֵר נִקְרָא חָסִיד וְזוֹ הִיא מִדַּת חֲסִידוּת. וְאִם נִתְרַחֵק עַד הָאֶמְצַע בִּלְבַד וְיִהְיֶה עָנָו נִקְרָא חָכָם וְזוֹ הִיא מִדַּת חָכְמָה. וְעַל דֶּרֶךְ זוֹ שְׁאָר כָּל הַדֵּעוֹת. וַחֲסִידִים הָרִאשׁוֹנִים הָיוּ מַטִּין דֵּעוֹת שֶׁלָּהֶן מִדֶּרֶךְ הָאֶמְצָעִית כְּנֶגֶד שְׁתֵּי הַקְּצָווֹת. יֵשׁ דֵּעָה שֶׁמַּטִּין אוֹתָהּ כְּנֶגֶד הַקָּצֶה הָאַחֲרוֹן וְיֵשׁ דֵּעָה שֶׁמַּטִּין אוֹתָהּ כְּנֶגֶד הַקָּצֶה הָרִאשׁוֹן. וְזֶהוּ לִפְנִים מִשּׁוּרַת הַדִּין. וּמְצֻוִּין אָנוּ לָלֶכֶת בַּדְּרָכִים הָאֵלּוּ הַבֵּינוֹנִים וְהֵם הַדְּרָכִים הַטּוֹבִים וְהַיְשָׁרִים שֶׁנֶּאֱמַר (דברים כח ט) \"וְהָלַכְתָּ בִּדְרָכָיו\":","כָּךְ לָמְדוּ בְּפֵרוּשׁ מִצְוָה זוֹ. מַה הוּא נִקְרָא חַנּוּן אַף אַתָּה הֱיֵה חַנּוּן. מַה הוּא נִקְרָא רַחוּם אַף אַתָּה הֱיֵה רַחוּם. מַה הוּא נִקְרָא קָדוֹשׁ אַף אַתָּה הֱיֵה קָדוֹשׁ. וְעַל דֶּרֶךְ זוֹ קָרְאוּ הַנְּבִיאִים לָאֵל בְּכָל אוֹתָן הַכִּנּוּיִין אֶרֶךְ אַפַּיִם וְרַב חֶסֶד צַדִּיק וְיָשָׁר תָּמִים גִּבּוֹר וְחָזָק וְכַיּוֹצֵא בָּהֶן. לְהוֹדִיעַ שֶׁהֵן דְּרָכִים טוֹבִים וִישָׁרִים וְחַיָּב אָדָם לְהַנְהִיג עַצְמוֹ בָּהֶן וּלְהִדַּמּוֹת אֵלָיו כְּפִי כֹּחוֹ:","וְכֵיצַד יַרְגִּיל אָדָם עַצְמוֹ בְּדֵעוֹת אֵלּוּ עַד שֶׁיִּקָּבְעוּ בּוֹ. יַעֲשֶׂה וְיִשְׁנֶה וִישַׁלֵּשׁ בַּמַּעֲשִׂים שֶׁעוֹשֶׂה עַל פִּי הַדֵּעוֹת הָאֶמְצָעִיּוֹת וְיַחֲזֹר בָּהֶם תָּמִיד עַד שֶׁיִּהְיוּ מַעֲשֵׂיהֶם קַלִּים עָלָיו וְלֹא יִהְיֶה בָּהֶם טֹרַח עָלָיו וְיִקָּבְעוּ הַדֵּעוֹת בְּנַפְשׁוֹ. וּלְפִי שֶׁהַשֵּׁמוֹת הָאֵלּוּ נִקְרָא בָּהֶן הַיּוֹצֵר וְהֵם הַדֶּרֶךְ הַבֵּינוֹנִית שֶׁאָנוּ חַיָּבִין לָלֶכֶת בָּהּ. נִקְרֵאת דֶּרֶךְ זוֹ דֶּרֶךְ ה'. וְהִיא שֶׁלִּמֵּד אַבְרָהָם אָבִינוּ לְבָנָיו שֶׁנֶּאֱמַר (בראשית יח יט) \"כִּי יְדַעְתִּיו לְמַעַן אֲשֶׁר יְצַוֶּה\" וְגוֹ'. וְהַהוֹלֵךְ בְּדֶרֶךְ זוֹ מֵבִיא טוֹבָה וּבְרָכָה לְעַצְמוֹ שֶׁנֶּאֱמַר (בראשית יח יט) \"לְמַעַן הָבִיא ה' עַל אַבְרָהָם אֵת אֲשֶׁר דִּבֶּר עָלָיו\":"],"Mishneh Torah, Immersion Pools 4":["דִין תּוֹרָה שֶׁכָּל מַיִם מְכֻנָּסִין טוֹבְלִין בָּהֶן שֶׁנֶּאֱמַר (ויקרא יא לו) \"מִקְוֵה מַיִם\" מִכָּל מָקוֹם. וְהוּא שֶׁיִּהְיֶה בָּהֶן כְּדֵי לְהַעֲלוֹת בָּהֶן כְּדֵי טְבִילָה לְכָל גּוּף הָאָדָם בְּבַת אַחַת. שִׁעֲרוּ חֲכָמִים אַמָּה עַל אַמָּה בְּרוּם שָׁלֹשׁ אַמּוֹת. וְשִׁעוּר זֶה הוּא מַחֲזִיק אַרְבָּעִים סְאָה מַיִם בֵּין שְׁאוּבִין בֵּין שֶׁאֵינָן שְׁאוּבִין:","מִדִּבְרֵי סוֹפְרִים שֶׁהַמַּיִם הַשְּׁאוּבִין פְּסוּלִין לִטְבִילָה. וְלֹא עוֹד אֶלָּא מִקְוֵה מַיִם שֶׁאֵינָן שְׁאוּבִין שֶׁנָּפַל לְתוֹכָן שְׁלֹשָׁה לוֹגִין מַיִם שְׁאוּבִין פָּסְלוּ הַכּל. אַף עַל פִּי שֶׁפִּסּוּל מַיִם שְׁאוּבִין מִדִּבְרֵי סוֹפְרִים לְמָדוּהוּ בְּהֶקֵּשׁ שֶׁהֲרֵי הוּא אוֹמֵר (ויקרא יא לו) \"אַךְ מַעְיָן וּבוֹר מִקְוֵה מַיִם יִהְיֶה טָהוֹר\", הַמַּעְיָן אֵין בּוֹ תְּפִיסַת יַד אָדָם כְּלָל וְהַבּוֹר כֻּלּוֹ בִּידֵי אָדָם שֶׁהֲרֵי כֻּלּוֹ מַיִם שְׁאוּבִין, אָמְרוּ חֲכָמִים הַמִּקְוֶה לֹא יִהְיֶה כֻּלּוֹ שָׁאוּב כְּבוֹר וְאֵין צָרִיךְ לִהְיוֹת כֻּלּוֹ בִּידֵי שָׁמַיִם כְּמַעְיָן אֶלָּא אִם יֵשׁ בּוֹ תְּפִיסַת יַד אָדָם כָּשֵׁר:","כֵּיצַד. הַמַּנִּיחַ קַנְקַנִּים בְּרֹאשׁ הַגַּג לְנַגְּבָם וְיָרְדוּ לָהֶם גְּשָׁמִים וְנִתְמַלְּאוּ אַף עַל פִּי שֶׁהִיא עוֹנַת הַגְּשָׁמִים הֲרֵי זֶה יִשְׁבֹּר אֶת הַקַּנְקַנִּים אוֹ יִכְפֵּם וְהַמַּיִם הַנִּקְוִים מֵהֶם כְּשֵׁרִים לִטְבּל וְאַף עַל פִּי שֶׁכָּל הַמַּיִם הָאֵלּוּ הָיוּ בַּכֵּלִים שֶׁהֲרֵי לֹא מִלְּאָן בְּיָדוֹ. לְפִיכָךְ אִם הִגְבִּיהַּ אֶת הַקַּנְקַנִּים וְהֶעֱרָם הֲרֵי כָּל הַמַּיִם שֶׁבָּהֶם שְׁאוּבִין:","הַמַּנִּיחַ כֵּלִים תַּחַת הַצִּנּוֹר תָּמִיד בְּכָל עֵת וּבְכָל זְמַן אֶחָד כֵּלִים קְטַנִּים וְאֶחָד כֵּלִים גְּדוֹלִים אֲפִלּוּ כְּלֵי אֲבָנִים וְכַיּוֹצֵא בָּהֶן מִכֵּלִים שֶׁאֵינָן מְקַבְּלִין טֻמְאָה וְנִתְמַלְּאוּ מֵי גְּשָׁמִים הֲרֵי אֵלּוּ פְּסוּלִין. וְאִם כְּפָאָן עַל פִּיהֶן אוֹ שְׁבָרָן הַמַּיִם הַנִּקְוִין מֵהֶן כִּשְׁאוּבִין לְכָל דָּבָר שֶׁהֲרֵי לְדַעְתּוֹ נִתְמַלְּאוּ שֶׁחֶזְקַת הַצִּנּוֹר לְקַלֵּחַ מַיִם. וַאֲפִלּוּ שָׁכַח הַכֵּלִים תַּחַת הַצִּנּוֹר פְּסוּלִין גָּזְרוּ עַל הַשּׁוֹכֵחַ מִפְּנֵי הַמַּנִּיחַ. וְכֵן הַמַּנִּיחַ אֶת הַכֵּלִים בֶּחָצֵר בְּעֵת קִשּׁוּר הֶעָבִים וְנִתְמַלְּאוּ הַמַּיִם שֶׁבָּהֶן פְּסוּלִין שֶׁהֲרֵי לְדַעְתּוֹ נִתְמַלְּאוּ. וְכֵן גָּזְרוּ עַל הַשּׁוֹכֵחַ בֶּחָצֵר בִּשְׁעַת קִשּׁוּר עָבִים מִשּׁוּם מַנִּיחַ. הִנִּיחָן בֶּחָצֵר בְּעֵת פִּזּוּר עָבִים וּבָאוּ עָבִים וְנִתְמַלְּאוּ הֲרֵי אֵלּוּ כְּשֵׁרִין כְּמוֹ שֶׁמַּנִּיחָן בְּרֹאשׁ הַגָּג לְנַגְּבָן. וְכֵן אִם הִנִּיחָן בְּעֵת קִשּׁוּר הֶעָבִים וְנִתְפַּזְּרוּ וְחָזְרוּ וְנִתְקַשְּׁרוּ וְנִתְמַלְּאוּ הֲרֵי אֵלּוּ כְּשֵׁרִין. וְאִם שִׁבְּרָן אוֹ כְּפָאָן הַמַּיִם הַנִּקְוִין מֵהֶן כְּשֵׁרִין:","הַסַּיָּד שֶׁשָּׁכַח עָצִיץ בַּמִּקְוֶה וְנִתְמַלְּאוּ מַיִם אַף עַל פִּי שֶׁלֹּא נִשְׁאַר בַּמִּקְוֶה אֶלָּא מְעַט וַהֲרֵי הֶעָצִיץ יֵשׁ בּוֹ רֹב הַמִּקְוֶה הֲרֵי זֶה יִשְׁבֹּר אֶת הֶעָצִיץ בִּמְקוֹמוֹ וְנִמְצָא הַמִּקְוֶה כֻּלּוֹ כָּשֵׁר. וְכֵן הַמְסַדֵּר אֶת הַקַּנְקַנִּים בְּתוֹךְ הַמִּקְוֶה כְּדֵי לְחַסְּמָן וְנִתְמַלְּאוּ מַיִם אַף עַל פִּי שֶׁבָּלַע הַמִּקְוֶה אֶת מֵימָיו וְלֹא נִשְׁאַר שָׁם מַיִם כְּלָל אֶלָּא מַיִם שֶׁבְּתוֹךְ הַקַּנְקַנִּים הֲרֵי זֶה יִשְׁבֹּר אֶת הַקַּנְקַנִּים וְהַמַּיִם הַנִּקְוִין מֵהֶן מִקְוֶה כָּשֵׁר:","כֵּיצַד פּוֹסְלִין הַמַּיִם הַשְּׁאוּבִין אֶת הַמִּקְוֶה בִּשְׁלֹשָׁה לוֹגִין. שֶׁאִם הָיָה בַּמִּקְוֶה פָּחוֹת מֵאַרְבָּעִים סְאָה [וְנָפַל לְתוֹכָן שְׁלֹשָׁה לוֹגִין וְהִשְׁלִימוּם לְאַרְבָּעִים סְאָה] הַכּל פָּסוּל. אֲבָל מִקְוֶה שֶׁיֵּשׁ בּוֹ אַרְבָּעִים סְאָה מַיִם שֶׁאֵינָן שְׁאוּבִין וְשָׁאַב בְּכַד וְשָׁפַךְ לְתוֹכוֹ כָּל הַיּוֹם כֻּלּוֹ כָּשֵׁר. וְלֹא עוֹד אֶלָּא מִקְוֶה עֶלְיוֹן שֶׁיֵּשׁ בּוֹ אַרְבָּעִים סְאָה מַיִם כְּשֵׁרִין וְהָיָה מְמַלֵּא בִּכְלִי וְנוֹתֵן לְתוֹכוֹ עַד שֶׁיִּרְבּוּ הַמַּיִם וְיָרְדוּ לַמִּקְוֶה הַתַּחְתּוֹן אַרְבָּעִים סְאָה הֲרֵי הַתַּחְתּוֹן כָּשֵׁר:","מִקְוֶה שֶׁיֵּשׁ בּוֹ אַרְבָּעִים סְאָה מְכֻוָּנוֹת וְנָתַן לְתוֹכוֹ סְאָה מַיִם שְׁאוּבִין וְנָטַל אַחַר כָּךְ מִמֶּנּוּ סְאָה הֲרֵי זֶה כָּשֵׁר. וְכֵן נוֹתֵן סְאָה וְנוֹטֵל סְאָה וְהוּא כָּשֵׁר עַד רֻבּוֹ:","אֵין הַמַּיִם הַשְּׁאוּבִין פּוֹסְלִין אֶת הַמִּקְוֶה בִּשְׁלֹשָׁה לוֹגִין עַד שֶׁיִּפְּלוּ לְתוֹךְ הַמִּקְוֶה מִן הַכְּלִי. אֲבָל אִם נִגְרְרוּ הַמַּיִם הַשְּׁאוּבִין חוּץ לַמִּקְוֶה וְנִמְשְׁכוּ וְיָרְדוּ לַמִּקְוֶה אֵינָן פּוֹסְלִין אֶת הַמִּקְוֶה עַד שֶׁיִּהְיוּ מֶחֱצָה לְמֶחֱצָה אֲבָל אִם הָיָה רֹב מִן הַכְּשֵׁרִים הֲרֵי הַמִּקְוֶה כָּשֵׁר. כֵּיצַד. מִקְוֶה שֶׁיֵּשׁ בּוֹ עֶשְׂרִים סְאָה וּמַשֶּׁהוּ מַיִם כְּשֵׁרִין וְהָיָה מְמַלֵּא וְשׁוֹאֵב חוּץ לַמִּקְוֶה וְהַמַּיִם נִמְשָׁכִין וְיוֹרְדִין לַמִּקְוֶה בֵּין שֶׁהָיוּ נִמְשָׁכִין עַל הַקַּרְקַע אוֹ בְּתוֹךְ הַסִּילוֹן וְכַיּוֹצֵא בּוֹ מִדְּבָרִים שֶׁאֵינָן פּוֹסְלִין אֶת הַמִּקְוֶה הֲרֵי הוּא כָּשֵׁר וַאֲפִלּוּ הִשְׁלִימוֹ לְאֶלֶף סְאָה. שֶׁהַשְּׁאִיבָה שֶׁהִמְשִׁיכוּהָ כְּשֵׁרָה אִם הָיָה שָׁם רֹב אַרְבָּעִים סְאָה מִן הַכָּשֵׁר. וְכֵן גַּג שֶׁהָיָה בְּרֹאשׁוֹ עֶשְׂרִים סְאָה וּמַשֶּׁהוּ מֵי גְּשָׁמִים וּמִלֵּא בִּכְתֵפוֹ וְנָתַן לְתוֹכוֹ פָּחוֹת מֵעֶשְׂרִים שֶׁנִּמְצָא הַכּל פָּסוּל וּפָתַח הַצִּנּוֹר וְנִמְשְׁכוּ הַכּל לְמָקוֹם אֶחָד הֲרֵי זֶה מִקְוֶה כָּשֵׁר. שֶׁהַשְּׁאוּבִים שֶׁהִמְשִׁיכוּהָ כֻּלָּהּ כְּשֵׁרָה הוֹאִיל וְהָיָה שָׁם רֹב מִן הַכָּשֵׁר:","הוֹרוּ מִקְצָת חַכְמֵי מַעֲרָב וְאָמְרוּ הוֹאִיל וְאָמְרוּ חֲכָמִים שְׁאוּבָה שֶׁהִמְשִׁיכוּהָ כֻּלָּהּ טְהוֹרָה אֵין אָנוּ צְרִיכִין שֶׁיִּהְיוּ שָׁם רֹב מַיִם כְּשֵׁרִין. וְזֶה שֶׁהִצְרִיךְ רֹב וְהַמְשָׁכָה דִּבְרֵי יָחִיד הֵן וּכְבָר נִדְּחוּ שֶׁהֲרֵי אָמְרוּ בַּסּוֹף שְׁאוּבָה שֶׁהִמְשִׁיכוּהָ כֻּלָּהּ טְהוֹרָה. לְפִי דִּבְרֵי זֶה אִם הָיָה מְמַלֵּא בִּכְלִי וְשׁוֹפֵךְ וְהַמַּיִם נִזְחָלִין וְהוֹלְכִין לְמָקוֹם אֶחָד הֲרֵי זֶה מִקְוֶה כָּשֵׁר. וְכֵן כָּל אַמְבְּטִי שֶׁבְּמֶרְחֲצָאוֹת שֶׁלָּנוּ מִקְוָאוֹת כְּשֵׁרִין. שֶׁהֲרֵי כָּל הַמַּיִם שֶׁבָּהֶן שָׁאוּב וְשֶׁנִּמְשָׁךְ הוּא. וּמֵעוֹלָם לֹא רָאִינוּ מִי שֶׁעָשָׂה מַעֲשֵׂה בְּעִנְיָן זֶה:","מֵי גְּשָׁמִים וּמַיִם שְׁאוּבִין שֶׁהָיוּ מִתְעָרְבִין בְּחָצֵר וְנִמְשָׁכִין וְיוֹרְדִין לַעֻקָּה שֶׁבֶּחָצֵר אוֹ שֶׁמִּתְעָרְבִין עַל מַעֲלוֹת הַמְּעָרָה וְיוֹרְדִין לַמְּעָרָה. אִם רֹב מִן הַכָּשֵׁר כָּשֵׁר וְאִם רֹב מִן הַפָּסוּל פָּסוּל. מֶחֱצָה לְמֶחֱצָה פָּסוּל. אֵימָתַי בִּזְמַן שֶׁמִּתְעָרְבִין עַד שֶׁלֹּא יַגִּיעוּ לַמִּקְוֶה וְנִמְשָׁכִין וְיוֹרְדִין אֲבָל אִם הָיוּ הַכְּשֵׁרִים וְהַפְּסוּלִים מְקַלְּחִין לְתוֹךְ הַמִּקְוֶה אִם יָדוּעַ שֶׁנָּפְלוּ לְתוֹכוֹ אַרְבָּעִים סְאָה מַיִם כְּשֵׁרִין עַד שֶׁלֹּא יָרְדוּ לְתוֹכוֹ שְׁלֹשָׁה לוֹגִין מַיִם שְׁאוּבִין כָּשֵׁר וְאִם לָאו פָּסוּל:"],"Mishneh Torah, Inheritances 5":["זֶה הַכְּלָל בְּיוֹרְשִׁין. כָּל שְׁנֵי יוֹרְשִׁין שֶׁאֶחָד מֵהֶן יוֹרֵשׁ וַדַּאי וְהַשֵּׁנִי סָפֵק אֵין לַסָּפֵק כְּלוּם. וְאִם הָיוּ שְׁנֵיהֶם סָפֵק שֶׁמָּא זֶהוּ הַיּוֹרֵשׁ אוֹ שֶׁמָּא זֶה הַיּוֹרֵשׁ חוֹלְקִין בְּשָׁוֶה. לְפִיכָךְ מִי שֶׁמֵּת וְהִנִּיחַ בֵּן וְטֻמְטוּם אוֹ אַנְדְּרוֹגִינוּס הֲרֵי הַבֵּן יוֹרֵשׁ אֶת הַכּל שֶׁהַטֻּמְטוּם וְהָאַנְדְּרוֹגִינוּס סָפֵק. הִנִּיחַ בָּנוֹת וְטֻמְטוּם וְאַנְדְּרוֹגִינוּס יוֹרְשׁוֹת בְּשָׁוֶה וַהֲרֵי הוּא כְּאַחַת מִן הַבָּנוֹת:","כְּבָר בֵּאַרְנוּ בְּהִלְכוֹת אִישׁוּת דִּין הַבָּנוֹת עִם הַבָּנִים בִּמְזוֹנוֹתֵיהֶן וּבְפַרְנָסָתָן וְשָׁם בֵּאַרְנוּ שֶׁהַמְּזוֹנוֹת מִתְּנָאֵי כְּתֻבָּה. בִּזְמַן שֶׁהַנְּכָסִים מְרֻבִּין אֵין לַבָּנוֹת אֶלָּא מְזוֹנוֹתֵיהֶן וְהַבָּנִים יִירְשׁוּ הַכּל וְיִתְפַּרְנְסוּ הַבָּנוֹת בְּעִשּׂוּר נְכָסִים כְּדֵי שֶׁיִּנָּשְׂאוּ בּוֹ לְבַעְלֵיהֶן. וּבִזְמַן שֶׁהַנְּכָסִים מוּעָטִין אֵין לַבָּנִים כְּלוּם אֶלָּא הַכּל לִמְזוֹן הַבָּנוֹת. לְפִיכָךְ מִי שֶׁמֵּת וְהִנִּיחַ בָּנִים וּבָנוֹת וְטֻמְטוּם אוֹ אַנְדְּרוֹגִינוּס. בִּזְמַן שֶׁהַנְּכָסִים מְרֻבִּין הַבָּנִים יוֹרְשִׁין וְדוֹחִין הַטֻּמְטוּם אֵצֶל הַבָּנוֹת וְנִזּוֹן כְּמוֹתָן. וּבִזְמַן שֶׁהַנְּכָסִין מוּעָטִין הַבָּנוֹת דּוֹחוֹת אֶת הַטֻּמְטוּם אֵצֶל הַבָּנִים וְאוֹמְרוֹת לוֹ זָכָר אַתָּה וְאֵין לְךָ עִמָּנוּ מְזוֹנוֹת:","מִי שֶׁלֹּא שָׁהֲתָה אַחַר בַּעְלָהּ שְׁלֹשָׁה חֳדָשִׁים וְנִשֵּׂאת וְיָלְדָה בֵּן וְאֵין יָדוּעַ אִם בֶּן תִּשְׁעָה לְרִאשׁוֹן אוֹ בֶּן שִׁבְעָה לְאַחֲרוֹן אֵין זֶה הַבֵּן יוֹרֵשׁ אֶת אֶחָד מִשְּׁנֵיהֶם מִפְּנֵי שֶׁהוּא סָפֵק. וְאִם מֵת הַבֵּן שְׁנֵיהֶן יוֹרְשִׁין אוֹתוֹ וְחוֹלְקִין בְּשָׁוֶה מִפְּנֵי שֶׁשְּׁנֵיהֶם סָפֵק שֶׁמָּא זֶה אָבִיו אוֹ זֶה אָבִיו:","יְבָמָה שֶׁלֹּא שָׁהֲתָה שְׁלֹשָׁה חֳדָשִׁים וְנִתְיַבְּמָה בְּתוֹךְ שְׁלֹשָׁה חֳדָשִׁים וְיָלְדָה בֵּן וְאֵין יָדוּעַ אִם בֶּן תִּשְׁעָה לָרִאשׁוֹן אוֹ בֶּן שִׁבְעָה לָאַחֲרוֹן. זֶה הַסָּפֵק אוֹמֵר שֶׁמָּא בֶּן הַמֵּת אֲנִי וְאִירַשׁ אֶת נִכְסֵי אָבִי כֻּלָּן וְאֵין אַתָּה רָאוּי לְיַבֵּם אוֹתָהּ שֶׁאֵין אִמִּי בַּת יִבּוּם וְהַיָּבָם אוֹמֵר שֶׁמָּא בְּנִי אַתָּה וְאִמְּךָ רְאוּיָה לְיַבֵּם וְאֵין לְךָ בְּנִכְסֵי אָחִי כְּלוּם. הוֹאִיל וְגַם זֶה הַיָּבָם סָפֵק שֶׁמָּא יָבָם הוּא אוֹ אֵינוֹ יָבָם חוֹלְקִין בְּשָׁוֶה. וְכֵן דִּין זֶה הַסָּפֵק עִם בְּנֵי הַיָּבָם בְּנִכְסֵי הַמֵּת שֶׁנִּתְיַבְּמָה אִשְׁתּוֹ חוֹלְקִין בְּשָׁוֶה הַסָּפֵק נוֹטֵל מֶחֱצָה וּבְנֵי הַיָּבָם מֶחֱצָה. מֵת הַיָּבָם אַחַר שֶׁחָלַק עִם זֶה הַסָּפֵק וּבָאוּ בְּנֵי הַיָּבָם הָרְאוּיִים לִירַשׁ אֲבִיהֶם אַף עַל פִּי שֶׁיֵּשׁ לְזֶה הַסָּפֵק לוֹמַר אִם אֲחִיכֶם אֲנִי תְּנוּ לִי חֵלֶק בִּירֻשָּׁה זוֹ וְאִם אֵינִי אֲחִיכֶם הַחְזִירוּ לִי הַחֵצִי שֶׁלָּקַח אֲבִיכֶם אֵין לְזֶה הַסָּפֵק בְּנִכְסֵי אֲבִיהֶן עִמָּהֶן כְּלוּם וְאֵין מוֹצִיא מִיָּדָן:","סָפֵק וְהַיָּבָם שֶׁבָּאוּ לַחְלֹק בְּנִכְסֵי הָאָב הֲרֵי הַיָּבָם יוֹרֵשׁ וַדַּאי וְזֶה הַסָּפֵק אִם הוּא בֶּן הַמֵּת יֵשׁ לוֹ חֲצִי הַמָּמוֹן וּלְזֶה הַיָּבָם חֲצִי. וְאִם הוּא בֶּן הַיָּבָם אֵין לוֹ כְּלוּם. לְפִיכָךְ הַיָּבָם יוֹרֵשׁ וְיִדָּחֶה הַסָּפֵק. הִנִּיחַ הַיָּבָם שְׁנֵי בָּנִים וַדָּאִין וְאַחַר כָּךְ מֵת הַיָּבָם הֲרֵי הַסָּפֵק אוֹמֵר אֲנִי בֶּן הַמֵּת וְיֵשׁ לִי מֶחֱצָה וְלִשְׁנֵיכֶם מֶחֱצָה וְהַשְּׁנַיִם אוֹמְרִים אַתָּה אָחִינוּ וּבֶן הַיָּבָם אַתָּה וְאֵין לְךָ אֶלָּא שְׁלִישׁ בְּנִכְסֵי הַזָּקֵן הַחֵצִי שֶׁמּוֹדֶה לָהֶם בּוֹ נוֹטְלִין וְהִשְׁלִישׁ שֶׁמּוֹדִין הֵן לוֹ נוֹטֵל וְהַשְּׁתוּת הַנִּשְׁאָר חוֹלְקִים אוֹתוֹ בְּשָׁוֶה הוּא נוֹטֵל חֶצְיוֹ וּשְׁנֵיהֶם חֶצְיוֹ. מֵת הַסָּפֵק הֲרֵי הַיָּבָם אוֹמֵר שֶׁמָּא בְּנִי הוּא וַאֲנִי אִירָשֶׁנּוּ וַאֲבִי הַיָּבָם אוֹמֵר שֶׁמָּא בֶּן בְּנִי הַמֵּת הוּא וַאֲנִי אִירָשֶׁנּוּ חוֹלְקִין בְּשָׁוֶה (מֵת הַיָּבָם הַסָּפֵק אוֹמֵר בְּנוֹ אֲנִי וְאִירָשֶׁנּוּ וַאֲבִי הַיָּבָם אוֹמֵר שֶׁמָּא בֶּן בְּנִי הָאַחֵר אַתָּה וְזֶה אֲחִי אָבִיךָ הוּא וַאֲנִי אִירָשֶׁנּוּ חוֹלְקִין בְּשָׁוֶה):","מִי שֶׁנָּפַל הַבַּיִת עָלָיו וְעַל אִשְׁתּוֹ וְאֵין יָדוּעַ אִם הָאִשָּׁה מֵתָה תְּחִלָּה וְנִמְצְאוּ יוֹרְשֵׁי הַבַּעַל יוֹרְשִׁין כָּל נְכָסֶיהָ אוֹ הַבַּעַל מֵת תְּחִלָּה וְנִמְצְאוּ יוֹרְשֵׁי הָאִשָּׁה יוֹרְשִׁין כָּל נְכָסֶיהָ כֵּיצַד דִּינָם. מַעֲמִידִין נִכְסֵי מְלוֹג בְּחֶזְקַת יוֹרְשֵׁי הָאִשָּׁה וְהַכְּתֻבָּה עִקָּר וְהַתּוֹסֶפֶת בְּחֶזְקַת יוֹרְשֵׁי הַבַּעַל וְחוֹלְקִין בְּנִכְסֵי צֹאן בַּרְזֶל יוֹרְשֵׁי הָאִשָּׁה נוֹטְלִין חֶצְיָן וְיוֹרְשֵׁי הַבַּעַל חֶצְיָן. אֲבָל אִם נָפַל הַבַּיִת עָלָיו וְעַל אִמּוֹ מַעֲמִידִין נִכְסֵי הָאֵם בְּחֶזְקַת יוֹרְשֵׁי הָאֵם שֶׁהֵם יוֹרְשִׁין וַדָּאִין אֲבָל יוֹרְשֵׁי הַבֵּן סָפֵק הֵם שֶׁאִם מֵת הַבֵּן תְּחִלָּה אֵין לְאֶחָיו מֵאָבִיו בְּנִכְסֵי אִמָּן כְּלוּם כְּמוֹ שֶׁבֵּאַרְנוּ:","נָפַל הַבַּיִת עָלָיו וְעַל בֶּן בִּתּוֹ אִם הָאָב מֵת תְּחִלָּה בֶּן בִּתּוֹ יִירָשֶׁנּוּ וְנִמְצְאוּ הַנְּכָסִים שֶׁל יוֹרְשֵׁי הַבֵּן. וְאִם בֶּן בִּתּוֹ מֵת תְּחִלָּה אֵין הַבֵּן יוֹרֵשׁ אֶת אִמּוֹ בַּקֶּבֶר כְּמוֹ שֶׁבֵּאַרְנוּ וְנִמְצְאוּ הַנְּכָסִים שֶׁל יוֹרְשֵׁי הָאָב. לְפִיכָךְ יַחְלְקוּ יוֹרְשֵׁי הָאָב עִם יוֹרְשֵׁי בֶּן הַבַּת. וְכֵן אִם [נִשְׁבָּה] הָאָב וּמֵת בֶּן בִּתּוֹ בַּמְּדִינָה אוֹ שֶׁנִּשְׁבָּה הַבֵּן וּמֵת אֲבִי אִמּוֹ בַּמְּדִינָה יַחְלְקוּ יוֹרְשֵׁי הָאָב עִם יוֹרְשֵׁי בֶּן הַבַּת:","נָפַל עָלָיו הַבַּיִת וְעַל אָבִיו אוֹ שְׁאָר מוֹרִישִׁין וְעָלָיו כְּתֻבַּת אִשָּׁה וּבַעֲלֵי חוֹב. יוֹרְשֵׁי הָאָב אוֹמְרִין מֵת הַבֵּן תְּחִלָּה וְלֹא הִנִּיחַ כְּלוּם וְאָבַד הַחוֹב וּבַעֲלֵי חוֹבוֹת אוֹמְרִים הָאָב מֵת תְּחִלָּה וְזָכָה הַבֵּן בִּירֻשָּׁתוֹ וְיֵשׁ לָנוּ לִגְבּוֹת מֵחֶלְקוֹ. הֲרֵי הַנְּכָסִים בְּחֶזְקַת הַיּוֹרְשִׁין וְעַל הָאִשָּׁה וּבַעֲלֵי חוֹבוֹת לְהָבִיא רְאָיָה אוֹ יֵלְכוּ לָהֶם בְּלֹא כְּלוּם:","דִּין אֵלּוּ שֶׁמֵּתוּ תַּחַת הַמַּפּלֶת. אוֹ שֶׁטָּבְעוּ בַּיָּם. אוֹ שֶׁנָּפְלוּ לָאֵשׁ. אוֹ שֶׁמֵּתוּ בְּיוֹם אֶחָד וְזֶה בִּמְדִינָה זוֹ וְהָאַחֵר בִּמְדִינָה אַחֶרֶת. דִּין אֶחָד הוּא. שֶׁבְּכָל אֵלּוּ וְכַיּוֹצֵא בָּהֶן אֵין יוֹדְעִין מִי הוּא שֶׁמֵּת תְּחִלָּה:"],"Mishneh Torah, Kings and Wars 5":["אֵין הַמֶּלֶךְ נִלְחָם תְּחִלָּה אֶלָּא מִלְחֶמֶת מִצְוָה. וְאֵי זוֹ הִיא מִלְחֶמֶת מִצְוָה זוֹ מִלְחֶמֶת שִׁבְעָה עֲמָמִים. וּמִלְחֶמֶת עֲמָלֵק. וְעֶזְרַת יִשְׂרָאֵל מִיַּד צָר שֶׁבָּא עֲלֵיהֶם. וְאַחַר כָּךְ נִלְחָם בְּמִלְחֶמֶת הָרְשׁוּת וְהִיא הַמִּלְחָמָה שֶׁנִּלְחָם עִם שְׁאָר הָעַמִּים כְּדֵי לְהַרְחִיב גְּבוּל יִשְׂרָאֵל וּלְהַרְבּוֹת בִּגְדֻלָּתוֹ וְשִׁמְעוֹ:","מִלְחֶמֶת מִצְוָה אֵינוֹ צָרִיךְ לִטּל בָּהּ רְשׁוּת בֵּית דִּין. אֶלָּא יוֹצֵא מֵעַצְמוֹ בְּכָל עֵת. וְכוֹפֶה הָעָם לָצֵאת. אֲבָל מִלְחֶמֶת הָרְשׁוּת אֵינוֹ מוֹצִיא הָעָם בָּהּ אֶלָּא עַל פִּי בֵּית דִּין שֶׁל שִׁבְעִים וְאֶחָד:","וּפוֹרֵץ לַעֲשׂוֹת לוֹ דֶּרֶךְ וְאֵין מְמַחִין בְּיָדוֹ. וְדֶרֶךְ הַמֶּלֶךְ אֵין לָהּ שִׁעוּר. אֶלָּא כְּפִי מַה שֶּׁהוּא צָרִיךְ. אֵינוֹ מְעַקֵּם הַדְּרָכִים מִפְּנֵי כַּרְמוֹ שֶׁל זֶה אוֹ מִפְּנֵי שָׂדֵהוּ שֶׁל זֶה. אֶלָּא הוֹלֵךְ בְּשָׁוֶה וְעוֹשֶׂה מִלְחַמְתּוֹ:","מִצְוַת עֲשֵׂה לְהַחֲרִים שִׁבְעָה עֲמָמִין שֶׁנֶּאֱמַר (דברים כ יז) \"הַחֲרֵם תַּחֲרִימֵם\". וְכָל שֶׁבָּא לְיָדוֹ אֶחָד מֵהֶן וְלֹא הֲרָגוֹ עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים כ טז) \"לֹא תְחַיֶּה כָּל נְשָׁמָה\". וּכְבָר אָבַד זִכְרָם:","וְכֵן מִצְוַת עֲשֵׂה לְאַבֵּד זֵכֶר עֲמָלֵק. שֶׁנֶּאֱמַר (דברים כה יט) \"תִּמְחֶה אֶת זֵכֶר עֲמָלֵק\". וּמִצְוַת עֲשֵׂה לִזְכֹּר תָּמִיד מַעֲשָׂיו הָרָעִים וַאֲרִיבָתוֹ. כְּדֵי לְעוֹרֵר אֵיבָתוֹ. שֶׁנֶּאֱמַר (דברים כה יז) \"זָכוֹר אֵת אֲשֶׁר עָשָׂה לְךָ עֲמָלֵק\". מִפִּי הַשְּׁמוּעָה לָמְדוּ זָכוֹר בַּפֶּה לֹא תִּשְׁכָּח בַּלֵּב. שֶׁאָסוּר לִשְׁכֹּחַ אֵיבָתוֹ וְשִׂנְאָתוֹ:","כָּל הָאֲרָצוֹת שֶׁכּוֹבְשִׁין יִשְׂרָאֵל בְּמֶלֶךְ עַל פִּי בֵּית דִּין. הֲרֵי זֶה כִּבּוּשׁ רַבִּים וַהֲרֵי הִיא כְּאֶרֶץ יִשְׂרָאֵל שֶׁכָּבַשׁ יְהוֹשֻׁעַ לְכָל דָּבָר. וְהוּא שֶׁכָּבְשׁוּ אַחַר כִּבּוּשׁ כָּל אֶרֶץ יִשְׂרָאֵל הָאֲמוּרָה בַּתּוֹרָה:","וּמֻתָּר לִשְׁכֹּן בְּכָל הָעוֹלָם חוּץ מֵאֶרֶץ מִצְרַיִם. מִן הַיָּם הַגָּדוֹל וְעַד הַמַּעֲרָב אַרְבַּע מֵאוֹת פַּרְסָה עַל אַרְבַּע מֵאוֹת פַּרְסָה כְּנֶגֶד אֶרֶץ כּוּשׁ וּכְנֶגֶד הַמִּדְבָּר. הַכּל אָסוּר לְהִתְיַשֵּׁב בָּהּ. בִּשְׁלֹשָׁה מְקוֹמוֹת הִזְהִירָה תּוֹרָה שֶׁלֹּא לָשׁוּב לְמִצְרַיִם. שֶׁנֶּאֱמַר (דברים יז טז) \"לֹא תֹסִפוּן לָשׁוּב בַּדֶּרֶךְ הַזֶּה עוֹד\". (דברים כח סח) \"לֹא תֹסִיף עוֹד לִרְאֹתָהּ\". (שמות יד יג) \"לֹא תֹסִפוּ לִרְאֹתָם עוֹד עַד עוֹלָם\". וַאֲלֶכְּסַנְדְּרִיאָה בִּכְלַל הָאִסּוּר:","מֻתָּר לַחְזֹר לְאֶרֶץ מִצְרַיִם לִסְחוֹרָה וְלִפְרַקְמַטְיָא. וְלִכְבֹּשׁ אֲרָצוֹת אֲחֵרוֹת. וְאֵין אָסוּר אֶלָּא לְהִשְׁתַּקֵעַ שָׁם. וְאֵין לוֹקִין עַל לָאו זֶה. שֶׁבְּעֵת הַכְּנִיסָה מֻתָּר הוּא. וְאִם יַחֲשֹׁב לֵישֵׁב וּלְהִשְׁתַּקֵעַ שָׁם אֵין בּוֹ מַעֲשֶׂה. וְיֵרָאֶה לִי שֶׁאִם כָּבַשׁ אֶרֶץ מִצְרַיִם מֶלֶךְ יִשְׂרָאֵל עַל פִּי בֵּית דִּין שֶׁהִיא מֻתֶּרֶת. וְלֹא הִזְהִירָה אֶלָּא לָשׁוּב לָהּ יְחִידִים אוֹ לִשְׁכֹּן בָּהּ וְהִיא בְּיַד עַכּוּ\"ם מִפְּנֵי שֶׁמַּעֲשֶׂיהָ מְקֻלְקָלִין יוֹתֵר מִכָּל הָאֲרָצוֹת. שֶׁנֶּאֱמַר (ויקרא יח ג) \"כְּמַעֲשֵׂה אֶרֶץ מִצְרַיִם\":","אָסוּר לָצֵאת מֵאֶרֶץ יִשְׂרָאֵל לְחוּצָה לָאָרֶץ לְעוֹלָם. אֶלָּא לִלְמֹד תּוֹרָה אוֹ לִשָּׂא אִשָּׁה אוֹ לְהַצִּיל מִן הָעַכּוּ\"ם. וְיַחְזֹר לָאָרֶץ. וְכֵן יוֹצֵא הוּא לִסְחוֹרָה. אֲבָל לִשְׁכֹּן בְּחוּצָה לָאָרֶץ אָסוּר אֶלָּא אִם כֵּן חָזַק שָׁם הָרָעָב עַד שֶׁנַּעֲשָׂה שְׁוֵה דִּינָר חִטִּין בִּשְׁנֵי דִּינָרִין. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיוּ הַמָּעוֹת מְצוּיוֹת וְהַפֵּרוֹת בְּיֹקֶר. אֲבָל אִם הַפֵּרוֹת בְּזוֹל וְלֹא יִמְצָא מָעוֹת וְלֹא בְּמָה יִשְׂתַּכֵּר וְאָבְדָה פְּרוּטָה מִן הַכִּיס. יֵצֵא לְכָל מָקוֹם שֶׁיִּמְצָא בּוֹ רֶוַח. וְאַף עַל פִּי שֶׁמֻּתָּר לָצֵאת אֵינָהּ מִדַּת חֲסִידוּת שֶׁהֲרֵי מַחְלוֹן וְכִלְיוֹן שְׁנֵי גְּדוֹלֵי הַדּוֹר הָיוּ וּמִפְּנֵי צָרָה גְּדוֹלָה יָצְאוּ וְנִתְחַיְּבוּ כְּלָיָה לַמָּקוֹם:","גְּדוֹלֵי הַחֲכָמִים הָיוּ מְנַשְּׁקִין עַל תְּחוּמֵי אֶרֶץ יִשְׂרָאֵל וּמְנַשְּׁקִין אֲבָנֶיהָ וּמִתְגַּלְגְּלִין עַל עֲפָרָהּ. וְכֵן הוּא אוֹמֵר (תהילים קב טו) \"כִּי רָצוּ עֲבָדֶיךָ אֶת אֲבָנֶיהָ וְאֶת עֲפָרָהּ יְחֹנֵנוּ\":","אָמְרוּ חֲכָמִים כָּל הַשּׁוֹכֵן בְּאֶרֶץ יִשְׂרָאֵל עֲוֹנוֹתָיו מְחוּלִין. שֶׁנֶּאֱמַר (ישעיה לג כד) \"וּבַל יֹאמַר שָׁכֵן חָלִיתִי הָעָם הַיּשֵׁב בָּהּ נְשֻׂא עָוֹן\". אֲפִלּוּ הָלַךְ בָּהּ אַרְבַּע אַמּוֹת זוֹכֶה לְחַיֵּי הָעוֹלָם הַבָּא. וְכֵן הַקָּבוּר בָּהּ נִתְכַּפֵּר לוֹ. וּכְאִלּוּ הַמָּקוֹם שֶׁהוּא בּוֹ מִזְבַּח כַּפָּרָה. שֶׁנֶּאֱמַר (דברים לב מג) \"וְכִפֶּר אַדְמָתוֹ עַמּוֹ\". וּבַפֻּרְעָנוּת הוּא אוֹמֵר (עמוס ז יז) \"עַל אֲדָמָה טְמֵאָה תָּמוּת\". וְאֵינוֹ דּוֹמֶה קוֹלַטְתּוֹ מֵחַיִּים לְקוֹלַטְתּוֹ אַחַר מוֹתוֹ. וְאַף עַל פִּי כֵן גְּדוֹלֵי הַחֲכָמִים הָיוּ מוֹלִיכִים מֵתֵיהֶם לְשָׁם. צֵא וּלְמַד מִיַּעֲקֹב אָבִינוּ וְיוֹסֵף הַצַּדִּיק:","לְעוֹלָם יָדוּר אָדָם בְּאֶרֶץ יִשְׂרָאֵל אֲפִלּוּ בְּעִיר שֶׁרֻבָּהּ עַכּוּ\"ם וְאַל יָדוּר בְּחוּצָה לָאָרֶץ וַאֲפִלּוּ בְּעִיר שֶׁרֻבָּהּ יִשְׂרָאֵל. שֶׁכָּל הַיּוֹצֵא לְחוּצָה לָאָרֶץ כְּאִלּוּ עוֹבֵד עֲבוֹדָה זָרָה. שֶׁנֶּאֱמַר (שמואל א כו יט) \"כִּי גֵרְשׁוּנִי הַיּוֹם מֵהִסְתַּפֵּחַ בְּנַחֲלַת ה' לֵאמֹר לֵךְ עֲבֹד אֱלֹהִים אֲחֵרִים\". וּבַפֻּרְעָנֻיּוֹת הוּא אוֹמֵר (יחזקאל יג ט) \"וְאֶל אַדְמַת יִשְׂרָאֵל לֹא יָבֹאוּ\". כְּשֵׁם שֶׁאָסוּר לָצֵאת מֵהָאָרֶץ לְחוּצָה לָאָרֶץ כָּךְ אָסוּר לָצֵאת מִבָּבֶל לִשְׁאָר הָאֲרָצוֹת. שֶׁנֶּאֱמַר (ירמיה כז כב) \"בָּבֶלָה יוּבָאוּ וְשָׁמָּה יִהְיוּ\":"],"Mishneh Torah, Leavened and Unleavened Bread 8":["סֵדֶר עֲשִׂיַּת מִצְוֹת אֵלּוּ בְּלֵיל חֲמִשָּׁה עָשָׂר כָּךְ הוּא. בַּתְּחִלָּה מוֹזְגִין כּוֹס לְכָל אֶחָד וְאֶחָד וּמְבָרֵךְ בּוֹרֵא פְּרִי הַגָּפֶן וְאוֹמֵר עָלָיו קִדּוּשׁ הַיּוֹם וּזְמַן וְשׁוֹתֶה. וְאַחַר כָּךְ מְבָרֵךְ עַל נְטִילַת יָדַיִם וְנוֹטֵל יָדָיו. וּמְבִיאִין שֻׁלְחָן עָרוּךְ וְעָלָיו מָרוֹר וְיָרָק אַחֵר וּמַצָּה וַחֲרֹסֶת וְגוּפוֹ שֶׁל כֶּבֶשׂ הַפֶּסַח וּבְשַׂר חֲגִיגָה שֶׁל יוֹם אַרְבָּעָה עָשָׂר. וּבַזְּמַן הַזֶּה מְבִיאִין עַל הַשֻּׁלְחָן שְׁנֵי מִינֵי בָּשָׂר אֶחָד זֵכֶר לַפֶּסַח וְאֶחָד זֵכֶר לַחֲגִיגָה:","מַתְחִיל וּמְבָרֵךְ בּוֹרֵא פְּרִי הָאֲדָמָה וְלוֹקֵחַ יָרָק וּמְטַבֵּל אוֹתוֹ בַּחֲרֹסֶת וְאוֹכֵל כְּזַיִת הוּא וְכָל הַמְסֻבִּין עִמּוֹ כָּל אֶחָד וְאֶחָד אֵין אוֹכֵל פָּחוֹת מִכְּזַיִת. וְאַחַר כָּךְ עוֹקְרִין הַשֻּׁלְחָן מִלִּפְנֵי קוֹרֵא הַהַגָּדָה לְבַדּוֹ. וּמוֹזְגִין הַכּוֹס הַשֵּׁנִי וְכָאן הַבֵּן שׁוֹאֵל. וְאוֹמֵר הַקּוֹרֵא מַה נִּשְׁתַּנָּה הַלַּיְלָה הַזֶּה מִכָּל הַלֵּילוֹת שֶׁבְּכָל הַלֵּילוֹת אֵין אָנוּ מַטְבִּילִין אֲפִלּוּ פַּעַם אַחַת וְהַלַּיְלָה הַזֶּה שְׁתֵּי פְּעָמִים. שֶׁבְּכָל הַלֵּילוֹת אָנוּ אוֹכְלִין חָמֵץ וּמַצָּה וְהַלַּיְלָה הַזֶּה כֻּלּוֹ מַצָּה. שֶׁבְּכָל הַלֵּילוֹת אָנוּ אוֹכְלִין בְּשַׂר צָלִי שָׁלוּק וּמְבֻשָּׁל וְהַלַּיְלָה הַזֶּה כֻּלּוֹ צָלִי. שֶׁבְּכָל הַלֵּילוֹת אָנוּ אוֹכְלִין שְׁאָר יְרָקוֹת וְהַלַּיְלָה הַזֶּה מְרוֹרִים. שֶׁבְּכָל הַלֵּילוֹת אָנוּ אוֹכְלִין בֵּין יוֹשְׁבִין בֵּין מְסֻבִּין וְהַלַּיְלָה הַזֶּה כֻּלָּנוּ מְסֻבִּין:","בַּזְּמַן הַזֶּה אֵינוֹ אוֹמֵר וְהַלַּיְלָה הַזֶּה כֻּלּוֹ צָלִי שֶׁאֵין לָנוּ קָרְבָּן. וּמַתְחִיל בִּגְנוּת וְקוֹרֵא עַד שֶׁגּוֹמֵר דְּרַשׁ פָּרָשַׁת (דברים כו ה) \"אֲרַמִּי אוֹבֵד אָבִי\" כֻּלָּהּ:","וּמַחֲזִיר הַשֻּׁלְחָן לְפָנָיו וְאוֹמֵר פֶּסַח זֶה שֶׁאָנוּ אוֹכְלִין עַל שֵׁם שֶׁפָּסַח הַמָּקוֹם עַל בָּתֵּי אֲבוֹתֵינוּ בְּמִצְרַיִם שֶׁנֶּאֱמַר (שמות יב כז) \"וַאֲמַרְתֶּם זֶבַח פֶּסַח הוּא לַה'\". וּמַגְבִּיהַּ הַמָּרוֹר בְּיָדוֹ וְאוֹמֵר מָרוֹר זֶה שֶׁאָנוּ אוֹכְלִין עַל שֵׁם שֶׁמֵּרְרוּ הַמִּצְרִיִּים אֶת חַיֵּי אֲבוֹתֵינוּ בְּמִצְרַיִם שֶׁנֶּאֱמַר (שמות א יד) \"וַיְמָרְרוּ אֶת חַיֵּיהֶם\". וּמַגְבִּיהַּ הַמַּצָּה בְּיָדוֹ וְאוֹמֵר מַצָּה זוֹ שֶׁאָנוּ אוֹכְלִין עַל שֵׁם שֶׁלֹּא הִסְפִּיק בְּצֵקָם שֶׁל אֲבוֹתֵינוּ לְהַחֲמִיץ עַד שֶׁנִּגְלָה עֲלֵיהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא וּגְאָלָם מִיָּד שֶׁנֶּאֱמַר (שמות יב לט) \"וַיֹּאפוּ אֶת הַבָּצֵק אֲשֶׁר הוֹצִיאוּ מִמִּצְרַיִם\" וְכוּ'. וּבַזְּמַן הַזֶּה אוֹמֵר פֶּסַח שֶׁהָיוּ אֲבוֹתֵינוּ אוֹכְלִין בִּזְמַן שֶׁבֵּית הַמִּקְדָּשׁ קַיָּם עַל שֵׁם שֶׁפָּסַח הַקָּדוֹשׁ בָּרוּךְ הוּא עַל בָּתֵּי אֲבוֹתֵינוּ וְכוּ':","וְאוֹמֵר לְפִיכָךְ אָנוּ חַיָּבִין לְהוֹדוֹת לְהַלֵּל לְשַׁבֵּחַ לְפָאֵר לְהַדֵּר לְרוֹמֵם לְגַדֵּל וּלְנַצֵּחַ לְמִי שֶׁעָשָׂה לַאֲבוֹתֵינוּ וְלָנוּ אֶת כָּל הַנִּסִּים הָאֵלּוּ וְהוֹצִיאָנוּ מֵעַבְדוּת לְחֵרוּת מִיָּגוֹן לְשִׂמְחָה וּמֵאֲפֵלָה לְאוֹר גָּדוֹל וְנֹאמַר לְפָנָיו הַלְלוּיָהּ. (תהילים קיג א) \"הַלְלוּיָהּ הַלְלוּ עַבְדֵי ה'\" וְגוֹ' עַד (תהילים קיד ח) \"חַלָּמִישׁ לְמַעְיְנוֹ מָיִם\". וְחוֹתֵם בָּרוּךְ אַתָּה ה' אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר גְּאָלָנוּ וְגָאַל אֶת אֲבוֹתֵינוּ מִמִּצְרַיִם וְהִגִּיעָנוּ לַלַּיְלָה הַזֶּה לֶאֱכֹל בּוֹ מַצָּה וּמְרוֹרִים. וּבַזְּמַן הַזֶּה מוֹסִיף כֵּן ה' אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ יַגִּיעֵנוּ לַמּוֹעֲדִים וְלִרְגָלִים אֲחֵרִים הַבָּאִים לִקְרָאתֵנוּ לְשָׁלוֹם שְׂמֵחִים בְּבִנְיַן עִירֶךָ וְשָׂשִׂים בַּעֲבוֹדָתֶךָ וְנֹאכַל שָׁם מִן הַזְּבָחִים וּמִן הַפְּסָחִים שֶׁיַּגִּיעַ דָּמָם עַל קִיר מִזְבַּחֲךָ לְרָצוֹן וְנוֹדֶה לְךָ שִׁיר חָדָשׁ עַל גְּאֻלָּתֵנוּ וְעַל פְּדוּת נַפְשֵׁנוּ בָּרוּךְ אַתָּה ה' גָּאַל יִשְׂרָאֵל. וּמְבָרֵךְ בּוֹרֵא פְּרִי הַגָּפֶן וְשׁוֹתֶה הַכּוֹס הַשֵּׁנִי:","וְאַחַר כָּךְ מְבָרֵךְ עַל נְטִילַת יָדַיִם וְנוֹטֵל יָדָיו שֵׁנִית שֶׁהֲרֵי הִסִּיחַ דַּעְתּוֹ בִּשְׁעַת קְרִיאַת הַהַגָּדָה. וְלוֹקֵחַ שְׁנֵי רְקִיקִין וְחוֹלֵק אֶחָד מֵהֶן וּמַנִּיחַ פָּרוּס לְתוֹךְ שָׁלֵם וּמְבָרֵךְ הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ. וּמִפְּנֵי מָה אֵינוֹ מְבָרֵךְ עַל שְׁתֵּי כִּכָּרוֹת כִּשְׁאָר יָמִים טוֹבִים מִשּׁוּם שֶׁנֶּאֱמַר (דברים טז ג) \"לֶחֶם עֹנִי\" מַה דַּרְכּוֹ שֶׁל עָנִי בִּפְרוּסָה אַף כָּאן בִּפְרוּסָה. וְאַחַר כָּךְ כּוֹרֵךְ מַצָּה וּמָרוֹר כְּאַחַת וּמְטַבֵּל בַּחֲרֹסֶת וּמְבָרֵךְ בָּרוּךְ אַתָּה ה' אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל אֲכִילַת מַצּוֹת וּמְרוֹרִים וְאוֹכְלָן. וְאִם אָכַל מַצָּה בִּפְנֵי עַצְמָהּ וּמָרוֹר בִּפְנֵי עַצְמוֹ מְבָרֵךְ עַל זֶה בִּפְנֵי עַצְמוֹ וְעַל זֶה בִּפְנֵי עַצְמוֹ:","וְאַחַר כָּךְ מְבָרֵךְ בָּרוּךְ אַתָּה ה' אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל אֲכִילַת הַזֶּבַח וְאוֹכֵל מִבְּשַׂר חֲגִיגַת אַרְבָּעָה עָשָׂר תְּחִלָּה. וּמְבָרֵךְ בָּרוּךְ אַתָּה ה' אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל אֲכִילַת הַפֶּסַח וְאוֹכֵל מִגּוּפוֹ שֶׁל פֶּסַח. וְלֹא בִּרְכַּת הַפֶּסַח פּוֹטֶרֶת שֶׁל זֶבַח וְלֹא שֶׁל זֶבַח פּוֹטֶרֶת שֶׁל פֶּסַח:","בַּזְּמַן הַזֶּה שֶׁאֵין שָׁם קָרְבָּן, אַחַר שֶׁמְּבָרֵךְ הַמּוֹצִיא לֶחֶם חוֹזֵר וּמְבָרֵךְ עַל אֲכִילַת מַצָּה. וּמְטַבֵּל מַצָּה בַּחֲרֹסֶת וְאוֹכֵל. וְחוֹזֵר וּמְבָרֵךְ עַל אֲכִילַת מָרוֹר וּמְטַבֵּל מָרוֹר בַּחֲרֹסֶת וְאוֹכֵל. וְלֹא יַשְׁהֶה אוֹתוֹ בַּחֲרֹסֶת שֶׁמָּא יְבַטֵּל טַעֲמוֹ. וְזוֹ מִצְוָה מִדִּבְרֵי סוֹפְרִים. וְחוֹזֵר וְכוֹרֵךְ מַצָּה וּמָרוֹר וּמְטַבֵּל בַּחֲרֹסֶת וְאוֹכְלָן בְּלֹא בְּרָכָה זֵכֶר לַמִּקְדָּשׁ:","וְאַחַר כָּךְ נִמְשָׁךְ בַּסְּעֻדָּה וְאוֹכֵל כָּל מַה שֶּׁהוּא רוֹצֶה לֶאֱכל וְשׁוֹתֶה כָּל מַה שֶּׁהוּא רוֹצֶה לִשְׁתּוֹת. וּבָאַחֲרוֹנָה אוֹכֵל מִבְּשַׂר הַפֶּסַח אֲפִלּוּ כְּזַיִת וְאֵינוֹ טוֹעֵם אַחֲרָיו כְּלָל. וּבַזְּמַן הַזֶּה אוֹכֵל כְּזַיִת מַצָּה וְאֵינוֹ טוֹעֵם אַחֲרֶיהָ כְּלוּם. כְּדֵי שֶׁיִּהְיֶה הֶפְסֵק סְעֻדָּתוֹ וְטַעַם בְּשַׂר הַפֶּסַח אוֹ הַמַּצָּה בְּפִיו שֶׁאֲכִילָתָן הִיא הַמִּצְוָה:","וְאַחַר כָּךְ נוֹטֵל יָדָיו וּמְבָרֵךְ בִּרְכַּת הַמָּזוֹן עַל כּוֹס שְׁלִישִׁי וְשׁוֹתֵהוּ. וְאַחַר כָּךְ מוֹזֵג כּוֹס רְבִיעִי וְגוֹמֵר עָלָיו אֶת הַהַלֵּל. וְאוֹמֵר עָלָיו בִּרְכַּת הַשִּׁיר וְהִיא יְהַלְלוּךָ ה' כָּל מַעֲשֶׂיךָ וְכוּ'. וּמְבָרֵךְ בּוֹרֵא פְּרִי הַגָּפֶן וְאֵינוֹ טוֹעֵם אַחַר כָּךְ כְּלוּם כָּל הַלַּיְלָה חוּץ מִן הַמַּיִם. וְיֵשׁ לוֹ לִמְזֹג כּוֹס חֲמִישִׁי וְלוֹמַר עָלָיו הַלֵּל הַגָּדוֹל מֵ(תהילים קלו א) \"הוֹדוּ לַה' כִּי טוֹב\" עַד (תהילים קלז א) \"עַל נַהֲרוֹת בָּבֶל\". וְכוֹס זֶה אֵינוֹ חוֹבָה כְּמוֹ אַרְבָּעָה כּוֹסוֹת. וְיֵשׁ לוֹ לִגְמֹר אֶת הַהַלֵּל בְּכָל מָקוֹם שֶׁיִּרְצֶה אַף עַל פִּי שֶׁאֵינוֹ מְקוֹם סְעֵוּדָּה:","מָקוֹם שֶׁנָּהֲגוּ לֶאֱכל צָלִי בְּלֵילֵי פְּסָחִים אוֹכְלִים. מָקוֹם שֶׁנָּהֲגוּ שֶׁלֹּא לֶאֱכל אֵין אוֹכְלִין גְּזֵרָה שֶׁמָּא יֹאמְרוּ בְּשַׂר פֶּסַח הוּא. וּבְכָל מָקוֹם אָסוּר לֶאֱכל שֶׂה צָלוּי כֻּלּוֹ כְּאֶחָד בְּלַיִל זֶה מִפְּנֵי שֶׁנִּרְאֶה כְּאוֹכֵל קָדָשִׁים בַּחוּץ. וְאִם הָיָה מְחֻתָּךְ אוֹ שֶׁחָסֵר מִמֶּנּוּ אֵיבָר אוֹ שָׁלַק בּוֹ אֵיבָר וְהוּא מְחֻבָּר הֲרֵי זֶה מֻתָּר בְּמָקוֹם שֶׁנָּהֲגוּ:","מִי שֶׁאֵין לוֹ יַיִן בְּלֵילֵי הַפֶּסַח מְקַדֵּשׁ עַל הַפַּת כְּדֶרֶךְ שֶׁעוֹשֶׂה בְּשַׁבָּת וְעוֹשֶׂה כָּל הַדְּבָרִים עַל הַסֵּדֶר הַזֶּה. מִי שֶׁאֵין לוֹ יָרָק אֶלָּא מָרוֹר בִּלְבַד. בַּתְּחִלָּה מְבָרֵךְ עַל הַמָּרוֹר שְׁתֵּי בְּרָכוֹת בּוֹרֵא פְּרִי הָאֲדָמָה וְעַל אֲכִילַת מָרוֹר וְאוֹכֵל. וּכְשֶׁיִּגְמֹר הַהַגָּדָה מְבָרֵךְ עַל הַמַּצָּה וְאוֹכֵל וְחוֹזֵר וְאוֹכֵל מִן הַמָּרוֹר בְּלֹא בְּרָכָה:","מִי שֶׁאֵין לוֹ מַצָּה מְשֻׁמֶּרֶת אֶלָּא כְּזַיִת כְּשֶׁגּוֹמֵר סְעֻדָּתוֹ מִמַּצָּה שֶׁאֵינָהּ מְשֻׁמֶּרֶת מְבָרֵךְ עַל אֲכִילַת מַצָּה וְאוֹכֵל אוֹתוֹ כְּזַיִת וְאֵינוֹ טוֹעֵם אַחֲרָיו כְּלוּם:","מִי שֶׁיָּשַׁן בְּתוֹךְ הַסְּעֻדָּה וְהֵקִיץ אֵינוֹ חוֹזֵר וְאוֹכֵל. בְּנֵי חֲבוּרָה שֶׁיָּשְׁנוּ מִקְצָתָן בְּתוֹךְ הַסְּעֻדָּה חוֹזְרִין וְאוֹכְלִין. נִרְדְּמוּ כֻּלָּן וְנֵעוֹרוּ לֹא יֹאכְלוּ. נִתְנַמְנְמוּ כֻּלָּן יֹאכְלוּ: סְלִיקוּ לְהוּ הִלְכוֹת חָמֵץ וּמַצָה:"],"Mishneh Torah, Marriage 11":["הַנּוֹשֵׂא בְּתוּלָה שֶׁנִּתְאַלְמִנָה אוֹ שֶׁנִּתְגָּרְשָׁה אוֹ נֶחְלְצָה. אִם מִן הָאֵרוּסִין נִתְאַלְמְנָה אוֹ נִתְגָּרְשָׁה אוֹ נֶחְלְצָה כְּתֻבָּתָהּ מָאתַיִם. וְאִם מִן הַנִּשּׂוּאִין כְּתֻבָּתָהּ מֵאָה. שֶׁמִּשֶּׁנִּשֵּׂאת הֲרֵי הִיא כִּבְעוּלָה. וְכֵן הַנּוֹשֵׂא בְּתוּלָה מְשֻׁחְרֶרֶת אוֹ גִּיֹּרֶת אוֹ שְׁבוּיָה אִם נִשְׁתַּחְרְרָה הַשִּׁפְחָה וְנִתְגַּיְּרָה הַכּוּתִית וְנִפְדֵית הַשְּׁבוּיָה וְהֵן פְּחוּתוֹת מִבַּת שָׁלֹשׁ שָׁנִים וְיוֹם אֶחָד כְּתֻבָּתָן מָאתַיִם. וְאִם הָיוּ בְּנוֹת שָׁלֹשׁ שָׁנִים וְיוֹם אֶחָד וָמַעְלָה כְּתֻבָּתָן מֵאָה:","וּמִפְּנֵי מָה תִּקְּנוּ חֲכָמִים לְאֵלּוּ כְּתֻבָּה מֵאָה וְאַף עַל פִּי שֶׁהֵן בְּתוּלוֹת. הוֹאִיל וְחֶזְקַת הַנְּשׂוּאָה שֶׁתִּבָּעֵל וְחֶזְקַת הַשִּׁפְחָה וְהַכּוּתִית וְהַשְּׁבוּיָה שֶׁתִּבָּעֵל תִּקְּנוּ לְאֵלּוּ מֵאָה בֵּין נִבְעֲלוּ בֵּין לֹא נִבְעֲלוּ וַהֲרֵי הֵן כִּבְעוּלוֹת לְכָל דָּבָר:","מֻכַּת עֵץ כְּתֻבָּתָהּ מֵאָה אֲפִלּוּ נִשֵּׂאת עַל מְנָת שֶׁהִיא בְּתוּלָה שְׁלֵמָה וְנִמְצֵאת מֻכַּת עֵץ כְּתֻבָּתָהּ מֵאָה. קְטַנָּה מִבַּת שָׁלֹשׁ שָׁנִים וּלְמַטָּה שֶׁנִּבְעֲלָה אֲפִלּוּ בָּא עָלֶיהָ אָדָם גָּדוֹל כְּתֻבָּתָהּ מָאתַיִם, סוֹפָהּ שֶׁתַּחֲזֹר בְּתוּלָה כִּשְׁאָר הַבְּתוּלוֹת. וְכֵן גְּדוֹלָה שֶׁבָּא עָלֶיהָ קָטָן מִבֶּן תֵּשַׁע שָׁנִים וּלְמַטָּה כְּתֻבָּתָהּ מָאתַיִם כְּאִלּוּ לֹא נִבְעֲלָה כְּלָל. שֶׁבִּיאַת בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד בִּיאָתוֹ בִּיאָה, פָּחוֹת מִזֶּה אֵין בִּיאָתוֹ בִּיאָה:","בְּתוּלָה שֶׁהִיא בּוֹגֶרֶת אוֹ סוּמָא אוֹ אַיְלוֹנִית כְּתֻבָּתָן מָאתַיִם. אֲבָל הַחֵרֶשֶׁת וְהַשּׁוֹטָה לֹא תִּקְּנוּ לָהֶן כְּתֻבָּה. הַשּׁוֹטָה לֹא תִּקְּנוּ לָהּ נִשּׂוּאִין כְּלָל. וְהַחֵרֶשֶׁת אַף עַל פִּי שֶׁיֵּשׁ לָהּ נִשּׂוּאִין מִדִּבְרֵיהֶם לֹא תִּקְּנוּ לָהּ כְּתֻבָּה כְּדֵי שֶׁלֹּא יִמָּנְעוּ מִלָּשֵׂאת אוֹתָהּ. וּכְשֵׁם שֶׁאֵין לָהּ כְּתֻבָּה כָּךְ אֵין לָהּ מְזוֹנוֹת וְלֹא תְּנַאי מִתְּנָאֵי כְּתֻבָּה. וְאִם כָּנַס הַחֵרֶשֶׁת וְנִתְפַּקְּחָה יֵשׁ לָהּ כְּתֻבָּה וּתְנַאי כְּתֻבָּה וּכְתֻבָּתָהּ מֵאָה:","נָשָׂא חֵרֶשֶׁת אוֹ שׁוֹטָה וְכָתַב לָהֶן מֵאָה מָנֶה כְּתֻבָּתָן קַיֶּמֶת מִפְּנֵי שֶׁרָצָה לְהַזִּיק נְכָסָיו:","חֵרֵשׁ אוֹ שׁוֹטֶה שֶׁנָּשְׂאוּ נָשִׁים פִּקְחוֹת אַף עַל פִּי שֶׁנִּתְפַּקֵּחַ הַחֵרֵשׁ וְנִשְׁתַּפָּה הַשּׁוֹטֶה אֵין לִנְשֵׁיהֶם עֲלֵיהֶם כְּלוּם. רָצוּ לְקַיְּמָן אַחַר שֶׁהִבְרִיאוּ יֵשׁ לָהֶן כְּתֻבָּה וּכְתֻבָּתָן מֵאָה. וְאִם בֵּית דִּין הֵם שֶׁהִשִּׂיאוּ הַחֵרֵשׁ וְכָתְבוּ לָהּ כְּתֻבָּתָהּ עַל נְכָסָיו נוֹטֶלֶת כָּל מַה שֶּׁכָּתְבוּ לָהּ בֵּית דִּין. אֲבָל הַשּׁוֹטֶה אֵין בֵּית דִּין מַשִּׂיאִין אוֹתוֹ בְּכָל מָקוֹם. וּמִפְּנֵי שֶׁאֵין תַּקָּנַת חֲכָמִים עוֹמֶדֶת בּוֹ לֹא תִּקְּנוּ לוֹ נִשּׂוּאִין. וְכֵן הַקָּטָן לֹא תִּקְּנוּ לוֹ חֲכָמִים נִשּׂוּאִין הוֹאִיל וְסוֹפוֹ לָבוֹא לִידֵי נִשּׂוּאִין גְּמוּרִין. וּמִפְּנֵי מָה תִּקְּנוּ נִשּׂוּאִין לִקְטַנָּה וְאַף עַל פִּי שֶׁהִיא בָּאָה לִידֵי נִשּׂוּאִין גְּמוּרִין. כְּדֵי שֶׁלֹּא יִנְהֲגוּ בָּהּ מִנְהַג הֶפְקֵר. וְאֵין מַשִּׂיאִין אֶת הַקָּטָן עַד שֶׁבּוֹדְקִין אוֹתוֹ וְיוֹדְעִים שֶׁהֵבִיא סִימָנִין:","קָטָן אֲפִלּוּ בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד שֶׁנָּשָׂא אִשָּׁה אֵין לָהּ כְּתֻבָּה. וְאִם הִגְדִּיל וְקִיְּמָהּ אַחַר שֶׁהִגְדִּיל יֵשׁ לָהּ עִקַּר כְּתֻבָּה. וְכֵן גֵּר שֶׁנִּתְגַּיֵּר הוּא וְאִשְׁתּוֹ כְּתֻבָּתָהּ מָנֶה שֶׁעַל מְנָת כֵּן קִיְּמָהּ:","כָּל בְּתוּלָה שֶׁכְּתֻבָּתָהּ מָאתַיִם יֵשׁ לָהּ טַעֲנַת בְּתוּלִים. וְכָל שֶׁכְּתֻבָּתָהּ מֵאָה אוֹ שֶׁלֹּא תִּקְּנוּ לָהּ חֲכָמִים כְּתֻבָּה אֵין לָהּ טַעֲנַת בְּתוּלִים. וְהַמִּתְיַחֵד עִם אֲרוּסָתוֹ קֹדֶם נִשּׂוּאִין אֵין לָהּ טַעֲנַת בְּתוּלִים:","וּמַה הִיא טַעֲנַת בְּתוּלִים. זֶה שֶׁנָּשָׂא אִשָּׁה שֶׁחֶזְקָתָהּ שֶׁהִיא בְּתוּלָה וְטוֹעֵן וְאוֹמֵר לֹא מְצָאתִיהָ בְּתוּלָה. וּשְׁנֵי סִימָנִין הֵן לִבְתוּלָה. הָאֶחָד דָּמִים שֶׁשׁוֹתְתִין מִמֶּנָּה בְּסוֹף בִּיאָה רִאשׁוֹנָה. וְהַשֵּׁנִי הַדֹּחַק שֶׁיִּמָּצֵא בָּהּ בְּבִיאָה רִאשׁוֹנָה בִּשְׁעַת תַּשְׁמִישׁ:","הַנּוֹשֵׂא אֶת הַבְּתוּלָה שֶׁכְּתֻבָּתָהּ מָאתַיִם וְטָעַן וְאָמַר לֹא מְצָאתִיהָ בְּתוּלָה. שׁוֹאֲלִין אוֹתָהּ אִם אָמְרָה אֱמֶת הוּא לֹא מְצָאַנִי בְּתוּלָה מִפְּנֵי שֶׁנָּפַלְתִּי וְהִכַּנִי עֵץ אוֹ קַרְקַע וְהָלְכוּ בְּתוּלַי הֲרֵי זוֹ נֶאֱמֶנֶת וְתַחֲזֹר כְּתֻבָּתָהּ לְמָנֶה. אַף עַל פִּי שֶׁהוּא טוֹעֵן אוֹמֵר שֶׁמָּא אִישׁ בָּא עָלַיִךְ וְאֵין לָךְ כְּלוּם אֵין מַשְׁגִּיחִין בְּטַעֲנָתוֹ. וְיֵשׁ לוֹ לְהַחֲרִים סְתָם שֶׁלֹּא בָּא עָלֶיהָ אִישׁ שֶׁאֵין הַדָּבָר וַדַּאי לוֹ:","אָמְרָה הִיא אֱמֶת אָמַר שֶׁלֹּא מְצָאַנִי בְּתוּלָה וְאִישׁ בָּא עָלַי בְּאֹנֶס אַחַר שֶׁנִּתְאָרַסְתִּי לוֹ. הֲרֵי זוֹ נֶאֱמֶנֶת וּכְתֻבָּתָהּ מָאתַיִם כְּמוֹ שֶׁהָיְתָה. וְאִם טָעַן וְאָמַר שֶׁמָּא עַד שֶׁלֹּא אֵרַסְתִּיךְ נֶאֱנַסְתְּ וּמִקָּחִי מִקַּח טָעוּת אוֹ אַחַר שֶׁאֵרַסְתִּיךְ נִבְעַלְתְּ בִּרְצוֹנֵךְ. הֲרֵי זֶה מַחֲרִים סְתָם עַל מִי שֶׁטּוֹעֵן שֶׁקֶר כְּדֵי לְחַיְּבֵנִי מָמוֹן שֶׁאֵינִי חַיָּב בּוֹ:","טָעַן וְאָמַר לֹא מְצָאתִיהָ בְּתוּלָה וְהִיא אוֹמֶרֶת לֹא בָּא עָלַי וַעֲדַיִן אֲנִי בְּתוּלָה. בּוֹדְקִין אוֹתָהּ אוֹ חוֹזֵר וּבוֹעֵל בִּפְנֵי עֵדִים. אָמְרָה בָּא עָלַי וּבְתוּלָה מְצָאַנִי כְּכָל הַבְּתוּלוֹת וְשֶׁקֶר הוּא טוֹעֵן. שׁוֹאֲלִין אוֹתוֹ וְאוֹמְרִין לוֹ מֶה הָיָה הַדָּבָר עַד שֶׁאָמַרְתָּ שֶׁאֵינָהּ בְּתוּלָה. אִם אָמַר מִפְּנֵי שֶׁלֹּא מָצָאתִי לָהּ דָּם בּוֹדְקִין בְּמִשְׁפַּחְתָּהּ שֶׁמָּא אֵין לָהֶם דָּם כְּלָל לֹא דַּם נִדָּה וְלֹא דַּם בְּתוּלִים אִם נִמְצְאוּ כֻּלָּן כֵּן הֲרֵי זוֹ בְּחֶזְקָתָהּ. לֹא נִמְצְאוּ בְּנוֹת מִשְׁפַּחְתָּהּ כֵּן בּוֹדְקִין אוֹתָהּ שֶׁמָּא חלִי גָּדוֹל יֵשׁ בָּהּ שֶׁיָּבַשׁ לַחְלוּחִית הָאֵיבָרִים אוֹ שֶׁהָיְתָה מִתְעַנֵּית בָּרָעָב. מַרְטִיבִין אוֹתָהּ וּמַאֲכִילִין אוֹתָהּ וּמַשְׁקִין אוֹתָהּ עַד שֶׁתַּבְרִיא וְתִבָּעֵל שֵׁנִית וְנִרְאֶה אִם תּוֹצִיא דָּם אִם לָאו. וְאִם אֵין שָׁם חלִי וְלֹא רָעָב וְלֹא כַּיּוֹצֵא בּוֹ הֲרֵי זוֹ טַעֲנַת בְּתוּלִים. וְאַף עַל פִּי שֶׁמָּצָא דֹּחַק בְּעֵת תַּשְׁמִישׁ הוֹאִיל וְלֹא יָצָא דָּם אֵין כָּאן בְּתוּלִים. שֶׁכָּל בְּתוּלָה יֵשׁ לָהּ דָּם בֵּין קְטַנָּה בֵּין גְּדוֹלָה בֵּין נַעֲרָה בֵּין בּוֹגֶרֶת אֶלָּא מִפְּנֵי הַחלִי כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִם אָמַר מִפְּנֵי שֶׁלֹּא מָצָאתִי דֹּחַק אֶלָּא פֶּתַח פָּתוּחַ מָצָאתִי שׁוֹאֲלִין עַל שְׁנוֹתֶיהָ שֶׁמָּא בּוֹגֶרֶת הִיא שֶׁרֹב הַבּוֹגְרוֹת אֵין לָהֶן דֹּחַק שֶׁמַּרְגִּישִׁין בּוֹ הַרְבֵּה שֶׁהֲרֵי גָּדְלָה וְנִתְרַפּוּ אֵיבָרֶיהָ וְכָלוּ בְּתוּלֶיהָ. וְאִם לֹא בָּגְרָה עֲדַיִן אוֹמְרִין לוֹ שֶׁמָּא הִטֵּיתָה אוֹ בָּעַלְתָּ בְּנַחַת וּלְפִיכָךְ לֹא הִרְגַּשְׁתָּ בַּדֹּחַק. אִם אָמַר לֹא כִּי אֶלָּא וַדַּאי פֶּתַח פָּתוּחַ הָיָה הֲרֵי זוֹ טַעֲנַת בְּתוּלִים לְכָל בְּתוּלָה שֶׁלֹּא בָּגְרָה בֵּין קְטַנָּה בֵּין נַעֲרָה בֵּין בְּרִיאָה בֵּין חוֹלָה שֶׁכָּל נַעֲרָה בְּתוּלָה פִּתְחָהּ סָתוּם הוּא. וְאַף עַל פִּי שֶׁיָּצָא הַדָּם הוֹאִיל וּמָצָא פֶּתַח פָּתוּחַ אֵין כָּאן בְּתוּלִים:","יֵשׁ גְּאוֹנִים שֶׁהוֹרוּ שֶׁהַבּוֹגֶרֶת אֵין לָהּ טַעֲנַת דָּמִים וְיֵשׁ לָהּ טַעֲנַת פֶּתַח פָּתוּחַ. וְאֵין דֶּרֶךְ הַגְּמָרָא מַרְאָה דָּבָר זֶה וְטָעוּת הָיָה בַּנֻּסְחָאוֹת שֶׁלָּהֶם. וּכְבָר בָּדַקְתִּי עַל סְפָרִים רַבִּים וְקַדְמוֹנִים וּמָצָאתִי שֶׁהַדָּבָר כְּמוֹ שֶׁבֵּאַרְנוּ שֶׁאֵין לְבוֹגֶרֶת אֶלָּא טַעֲנַת דָּמִים בִּלְבַד:","חֲכָמִים הֵם שֶׁתִּקְּנוּ עִקַּר כְּתֻבָּה לְאִשָּׁה וְהֵם הִתְקִינוּ וְאָמְרוּ שֶׁכָּל הַטּוֹעֵן טַעֲנַת בְּתוּלִים וְהָאִשָּׁה מַכְחֶשֶׁת אוֹתוֹ נֶאֱמָן וְעָלֶיהָ לְהָבִיא רְאָיָה לֹא עַל הָאִישׁ. שֶׁחֲזָקָה הִיא שֶׁאֵין אָדָם טוֹרֵחַ בִּסְעֻדָּה וּמַפְסִידָהּ וְהוֹפֵךְ שִׂמְחָתוֹ אֵבֶל:","וְעַד מָתַי יֵשׁ לוֹ לִטְעֹן טַעֲנַת בְּתוּלִים. אִם נִסְתְּרָה מִיָּד. וְאִם לֹא נִסְתְּרָה אֲפִלּוּ לְאַחַר שְׁלֹשִׁים יוֹם:","הוֹרוּ כָּל הַגְּאוֹנִים שֶׁזֶּה שֶׁאָמְרוּ חֲכָמִים שֶׁהוּא נֶאֱמָן אִם הִכְחִישָׁתוֹ אִשְׁתּוֹ. לְהַפְסִידָהּ עִקַּר הַכְּתֻבָּה. אֲבָל הַתּוֹסֶפֶת יֵשׁ לָהּ. אֶלָּא אִם כֵּן נוֹדַע בִּרְאָיָה בְּרוּרָה שֶׁהָיְתָה בְּעוּלָה אוֹ שֶׁהוֹדְתָה לוֹ שֶׁהִיא בְּעוּלָה קֹדֶם שֶׁתִּתְאָרֵס וְהִטְעַתּוּ. לְפִיכָךְ יֵשׁ לוֹ לְהַשְׁבִּיעָהּ בִּנְקִיטַת חֵפֶץ כְּדִין כָּל הַנִּשְׁבָּעִין וְנוֹטְלִין וְאַחַר כָּךְ תִּגְבֶּה הַתּוֹסֶפֶת. וְאֵין לָהּ לְהַשְׁבִּיעוֹ שֶׁלֹּא מְצָאָהּ בְּתוּלָה וְאַחַר כָּךְ תַּפְסִיד עִקַּר כְּתֻבָּה שֶׁחֲזָקָה הִיא שֶׁאֵין אָדָם טוֹרֵחַ בִּסְעֻדָּה וּמַפְסִידָהּ. וְיֵשׁ לָהּ לְהַחֲרִים סְתָם עַל מִי שֶׁטָּעַן עָלֶיהָ שֶׁקֶר:","הֲרֵי שֶׁרָצָה לְקַיְּמָהּ אַחַר שֶׁהִפְסִידָה עִקַּר הַכְּתֻבָּה חוֹזֵר וְכוֹתֵב לָהּ מֵאָה. לְפִי שֶׁאָסוּר לָאָדָם לִשְׁהוֹת עִם אִשְׁתּוֹ שָׁעָה אַחַת בְּלֹא כְּתֻבָּה כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Marriage 22":["הַבַּעַל קוֹדֵם לְכָל אָדָם בִּירֻשַּׁת אִשְׁתּוֹ. וּמֵאֵימָתַי יִזְכֶּה בִּירֻשָּׁתָהּ מִשֶּׁתֵּצֵא מֵרְשׁוּת הָאָב. וְאַף עַל פִּי שֶׁעֲדַיִן לֹא נִכְנְסָה לַחֻפָּה הוֹאִיל וְנַעֲשֵׂית בִּרְשׁוּת בַּעְלָהּ יִירָשֶׁנָּה:","כֵּיצַד. הָאִשָּׁה שֶׁנִּתְאָרְסָה וּמְסָרָהּ אָבִיהָ לְבַעְלָהּ אוֹ לִשְׁלוּחֵי בַּעְלָהּ. אוֹ מְסָרוּהָ שְׁלוּחֵי הָאָב לְבַעְלָהּ אוֹ לִשְׁלוּחָיו וּמֵתָה בַּדֶּרֶךְ קֹדֶם שֶׁתִּכָּנֵס לַחֻפָּה אַף עַל פִּי שֶׁכְּתֻבָּתָהּ עֲדַיִן בְּבֵית אָבִיהָ בַּעְלָהּ יוֹרְשָׁהּ. וְכֵן אִם הָלַךְ הָאָב אוֹ שְׁלוּחֵי הָאָב עִם הַבַּעַל וְנִכְנַס עִמָּהּ בַּעְלָהּ בַּדֶּרֶךְ לֶחָצֵר וְנִתְיַחֵד עִמָּהּ שָׁם לְשֵׁם נִשּׂוּאִין וּמֵתָה הֲרֵי זֶה יִירָשֶׁנָּה בַּעְלָהּ. אֲבָל אִם עֲדַיִן הָאָב עִם הַבַּעַל לְהוֹלִיכָהּ לְבֵית בַּעְלָהּ אוֹ שֶׁהָלְכוּ שְׁלוּחֵי הָאָב עִם שְׁלוּחֵי הַבַּעַל אוֹ עִם הַבַּעַל אֲפִלּוּ נִכְנַס הַבַּעַל עִמָּהּ לֶחָצֵר לָלוּן כְּדֶרֶךְ שֶׁלָּנִין עוֹבְרֵי דְּרָכִים בְּפֻנְדָּק אֶחָד הוֹאִיל וְהָאָב אוֹ שְׁלוּחָיו עִמָּהּ וַעֲדַיִן לֹא נִתְיַחֵד עִמָּהּ לְשֵׁם נִשּׂוּאִין אִם מֵתָה יִירָשֶׁנָּה אָבִיהָ אַף עַל פִּי שֶׁכְּתֻבָּתָהּ בְּבֵית בַּעְלָהּ:","וְכֵן אִם הָיְתָה בּוֹגֶרֶת אוֹ יְתוֹמָה אוֹ אַלְמָנָה וְהָלְכָה הִיא בְּעַצְמָהּ מִבֵּית אָבִיהָ לְבֵית בַּעְלָהּ וְאֵין עִמָּהּ לֹא בַּעְלָהּ וְלֹא שְׁלוּחָיו וּמֵתָה בַּדֶּרֶךְ אֵין הַבַּעַל יוֹרֵשׁ אוֹתָהּ:","הַנּוֹשֵׂא אִשָּׁה שֶׁהִיא אֲסוּרָה לוֹ הוֹאִיל וְיֵשׁ לוֹ בָּהּ קִדּוּשִׁין אִם מֵתָה תַּחְתָּיו יִירָשֶׁנָּה. וְכֵן הַנּוֹשֵׂא אֶת הַקְּטַנָּה אַף עַל פִּי שֶׁאֵין קִדּוּשֶׁיהָ קִדּוּשִׁין גְּמוּרִים אִם מֵתָה תַּחְתָּיו יִירָשֶׁנָּה. אֲבָל הַפִּקֵּחַ שֶׁנָּשָׂא חֵרֶשֶׁת אִם מֵתָה לֹא יִירָשֶׁנָּה. וְהַחֵרֵשׁ שֶׁנָּשָׂא פִּקַּחַת וּמֵתָה יִירָשֶׁנָּה שֶׁהֲרֵי הִיא בַּת דַּעַת וּלְדַעְתָּהּ נִשֵּׂאת וְזִכְּתָה לוֹ מָמוֹנָהּ:","קְטַנָּה שֶׁנִּתְקַדְּשָׁה לְדַעַת אָבִיהָ וְנִשֵּׂאת שֶׁלֹּא לְדַעַת אָבִיהָ בֵּין בְּפָנָיו בֵּין שֶׁלֹּא בְּפָנָיו יָכוֹל הָאָב לִמְחוֹת כְּמוֹ שֶׁבֵּאַרְנוּ. וַאֲפִלּוּ שָׁתַק הָאָב אִם מֵתָה אֵין הַבַּעַל יוֹרְשָׁהּ אֶלָּא אִם כֵּן רָצָה הָאָב בְּנִשּׂוּאֶיהָ:","הוֹרוּ הַגְּאוֹנִים שֶׁהָאִשָּׁה שֶׁחָלְתָה וּבִקְּשָׁה מִבַּעְלָהּ שֶׁיְּגָרְשֶׁנָּה וְתֵצֵא בְּלֹא כְּתֻבָּה כְּדֵי שֶׁלֹּא יִירָשֶׁנָּה אֵין שׁוֹמְעִין לָהּ. וַאֲפִלּוּ אָמְרָה אֲנִי שׂוֹנְאָה אוֹתוֹ וְאֵינִי רוֹצָה לַעֲמֹד עִמּוֹ אֵין שׁוֹמְעִין לָהּ. וְאֵין דָּנִין אוֹתָהּ כְּדִין מוֹרֶדֶת. וְדִין יָפֶה הוּא זֶה:","כָּל נְכָסִים שֶׁיֵּשׁ לָאִשָּׁה בֵּין נִכְסֵי צֹאן בַּרְזֶל בֵּין נִכְסֵי מְלוֹג הַבַּעַל אוֹכֵל כָּל פֵּרוֹתֵיהֶן בְּחַיֶּיהָ וְאִם מֵתָה בְּחַיֵּי בַּעְלָהּ יוֹרֵשׁ בַּעְלָהּ הַכּל. לְפִיכָךְ אִם מָכְרָה הָאִשָּׁה נִכְסֵי מְלוֹג אַחַר שֶׁנִּשֵּׂאת אַף עַל פִּי שֶׁאוֹתָן הַנְּכָסִים נָפְלוּ לָהּ קֹדֶם שֶׁתִּתְאָרֵס הַבַּעַל מוֹצִיא הַפֵּרוֹת מִיָּד הַלָּקוֹחוֹת כָּל יְמֵי חַיֶּיהָ. אֲבָל לֹא גּוּף הַקַּרְקַע שֶׁאֵין לוֹ כְּלוּם בְּגוּף נִכְסֵי מְלוֹג עַד שֶׁתָּמוּת. מֵתָה בְּחַיָּיו מוֹצִיא הַגּוּף מִיַּד הַלָּקוֹחוֹת בְּלֹא דָּמִים. וְאִם הַדָּמִים שֶׁלָּקְחָה מִיַּד הַלָּקוֹחוֹת קַיָּמִין בְּעַצְמָן מַחֲזִירָן לַלָּקוֹחוֹת. וְאֵינוֹ יָכוֹל לוֹמַר שֶׁמָּא מְצִיאָה הֵן:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּנְכָסִים הַיְדוּעִין לַבַּעַל אֲבָל אִם נָפְלוּ לָהּ נְכָסִים בִּמְדִינָה אַחֶרֶת וְלֹא יָדַע בָּהֶן הַבַּעַל וּמָכְרָה אוֹתָן מִכְרָהּ קַיָּם. וְכֵן אֲרוּסָה שֶׁמָּכְרָה קֹדֶם הַנִּשּׂוּאִין מִכְרָהּ קַיָּם שֶׁאֵין לַבַּעַל בְּנִכְסֵי אֲרוּסָתוֹ כְּלוּם עַד שֶׁיִּכְנֹס:","הָאִשָּׁה שֶׁכָּתְבָה כָּל נְכָסֶיהָ לְאַחֵר בֵּין קָרוֹב בֵּין רָחוֹק קֹדֶם שֶׁתִּנָּשֵׂא אַף עַל פִּי שֶׁאִם נִתְגָּרְשָׁה אוֹ נִתְאַלְמְנָה תְּבֻטַּל הַמַּתָּנָה כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת מַתָּנָה אֵין הַבַּעַל אוֹכֵל פֵּרוֹתֵיהֶן. וְאִם מֵתָה בְּחַיָּיו אֵינוֹ יוֹרְשָׁן. שֶׁהֲרֵי נָתְנָה אוֹתָן קֹדֶם שֶׁתִּנָּשֵׂא. וּכְשֶׁתָּמוּת בְּחַיֵּי בַּעְלָהּ יִקְנֶה מְקַבֵּל הַמַּתָּנָה מַתְּנָתוֹ קִנְיָן גָּמוּר. וְלֹא עוֹד אֶלָּא אֲפִלּוּ נָתְנָה מִקְצָת נְכָסֶיהָ אוֹ כֻּלָּם קֹדֶם נִשּׂוּאֶיהָ וְכָתְבָה לַמְקַבֵּל קְנֵה מֵהַיּוֹם וְלִכְשֶׁאֶרְצֶה שֶׁהֲרֵי לֹא קָנָה קִנְיָן גָּמוּר עַד שֶׁתִּרְצֶה אֵין הַבַּעַל אוֹכֵל פֵּרוֹת אוֹתָהּ הַמַּתָּנָה וְאִם מֵתָה אֵינוֹ יוֹרְשָׁהּ:","שׁוֹמֶרֶת יָבָם יֵשׁ לָהּ לִמְכֹּר וְלִתֵּן בְּמַתָּנָה נְכָסִים שֶׁנָּפְלוּ לָהּ כְּשֶׁהִיא שׁוֹמֶרֶת יָבָם. וְאֵין לַיָּבָם פֵּרוֹת אֲפִלּוּ בְּנִכְסֵי צֹאן בַּרְזֶל שֶׁהִכְנִיסָה לְאָחִיו עַד שֶׁיִּכְנֹס. מֵתָה כְּשֶׁהִיא שׁוֹמֶרֶת יָבָם יוֹרְשֶׁיהָ מֵאָבִיהָ יוֹרְשִׁין בְּנִכְסֵי מְלוֹג שֶׁלָּהּ וַחֲצִי נִכְסֵי צֹאן בַּרְזֶל וְיוֹרְשֵׁי הַבַּעַל יוֹרְשִׁים כְּתֻבָּתָהּ וַחֲצִי נִכְסֵי צֹאן בַּרְזֶל. וְיוֹרְשֵׁי הַבַּעַל חַיָּבִין בִּקְבוּרָתָהּ:","שׁוֹמֶרֶת יָבָם כְּתֻבָּתָהּ עַל כָּל נִכְסֵי בַּעְלָהּ. לְפִיכָךְ אֵין הַיָּבָם יָכוֹל לִמְכֹּר בְּנִכְסֵי אָחִיו בֵּין קֹדֶם יִבּוּם בֵּין אַחַר יִבּוּם. וְאִם מָכַר אוֹ נָתַן מַתָּנָה אוֹ חָלַק עִם אֶחָיו בְּנִכְסֵי הַמֵּת בֵּין קֹדֶם יִבּוּם בֵּין אַחַר יִבּוּם לֹא עָשָׂה כְּלוּם שֶׁכְּבָר נִתְחַיְּבוּ נְכָסִים אֵלּוּ לָאַלְמָנָה לִגְבּוֹת מֵהֶן כְּתֻבָּתָהּ:","כָּנַס אֶת יְבִמְתּוֹ וְהִנִּיחַ אָחִיו פֵּרוֹת מְחֻבָּרִין לַקַּרְקַע יִמָּכְרוּ וְיִלָּקַח בָּהֶן קַרְקַע וְהַיָּבָם אוֹכֵל פֵּרוֹתֵיהֶן:","הִנִּיחַ פֵּרוֹת תְּלוּשִׁין מִן הַקַּרְקַע וְכֵן אִם הִנִּיחַ מָעוֹת וּמִטַּלְטְלִין הַכּל שֶׁל יָבָם. וּמִשְׁתַּמֵּשׁ בָּהֶן כְּמוֹ שֶׁיִּרְצֶה וְאֵינָהּ יְכוֹלָה לְעַכֵּב. שֶׁהַמִּטַּלְטְלִין אֵין הַכְּתֻבָּה נִגְבֵּית מֵהֶן אֶלָּא בְּתַקָּנַת הַגְּאוֹנִים וְאֵין כֹּחַ בְּתַקָּנָה זוֹ לְמָנְעוֹ מִנִּכְסֵי אֶחָיו וּלְאָסְרָן עָלָיו בְּאַחֲרָיוּת זוֹ שֶׁלֹּא יִשָּׂא וְיִתֵּן בָּהֶם:","יְבָמָה שֶׁלֹּא הָיְתָה לָהּ כְּתֻבָּה אוֹ שֶׁמָּחֲלָה כְּתֻבָּתָהּ זָכָה בְּנִכְסֵי אָחִיו וּמוֹכֵר וְנוֹתֵן כְּחֶפְצוֹ. וּכְשֶׁיִּכְנֹס אֶת יְבִמְתּוֹ יִכְתֹּב לָהּ כְּתֻבָּה מֵאָה וְיִהְיוּ כָּל נְכָסָיו אַחְרָאִין לִכְתֻבָּתָהּ כִּשְׁאָר כָּל הַנָּשִׁים שֶׁיֵּשׁ לָהֶן כְּתֻבָּה:","הָאִשָּׁה שֶׁמָּכְרָה אוֹ שֶׁנָּתְנָה אַחַר שֶׁנִּשֵּׂאת בְּנִכְסֵי צֹאן בַּרְזֶל בֵּין לְבַעְלָהּ בֵּין לַאֲחֵרִים לֹא עָשְׂתָה כְּלוּם. וְכֵן בַּעַל שֶׁמָּכַר קַרְקַע בְּנִכְסֵי אִשְׁתּוֹ בֵּין נִכְסֵי צֹאן בַּרְזֶל בֵּין נִכְסֵי מְלוֹג לֹא עָשָׂה כְּלוּם:","מָכַר מִטַּלְטְלִין שֶׁל נִכְסֵי צֹאן בַּרְזֶל אַף עַל פִּי שֶׁאֵינוֹ רַשַּׁאי אִם מָכַר מִמִכָּרוֹ מִמְכָּר. מָכְרוּ שְׁנֵיהֶם בְּנִכְסֵי מְלוֹג בֵּין שֶׁלָּקַח מִן הָאִישׁ תְּחִלָּה וְחָזַר וְלָקַח מִן הָאִשָּׁה בֵּין שֶׁלָּקַח מִן הָאִשָּׁה וְחָזַר וְלָקַח מִן הָאִישׁ מִכְרָן קַיָּם:","וְכֵן הָאִשָּׁה שֶׁמָּכְרָה אוֹ נָתְנָה נִכְסֵי מְלוֹג לְבַעְלָהּ מִמְכָּרָהּ וּמַתְּנָתָהּ קַיָּמִין וְאֵינָהּ יְכוֹלָה לוֹמַר בְּנִכְסֵי מְלוֹג נַחַת רוּחַ עָשִׂיתִי לְבַעְלִי. אֲבָל בִּשְׁאָר נְכָסִים יֵשׁ לָהּ לוֹמַר:","כֵּיצַד. הָאִשָּׁה שֶׁמָּכְרָה אוֹ נָתְנָה לְבַעְלָהּ מִנִּכְסֵי צֹאן בַּרְזֶל בֵּין קַרְקַע בֵּין מִטַּלְטְלִין אוֹ שָׂדֶה שֶׁיִּחֵד לָהּ בִּכְתֻבָּתָהּ אוֹ שָׂדֶה שֶׁכָּתַב לָהּ בִּכְתֻבָּתָהּ אוֹ שָׂדֶה שֶׁהִכְנִיס לָהּ שׁוּם מִשֶּׁלּוֹ לֹא קָנָה בַּעְלָהּ. וְאַף עַל פִּי שֶׁקָּנוּ מִיַּד הָאִשָּׁה בִּרְצוֹנָהּ חוֹזֶרֶת בְּכָל עֵת שֶׁתִּרְצֶה. שֶׁלֹּא נָתְנָה וְלֹא מָכְרָה אֶלָּא מִפְּנֵי שְׁלוֹם בֵּיתָהּ. לְפִיכָךְ אֵין לַבַּעַל רְאָיָה בְּנִכְסֵי אִשְׁתּוֹ כְּלָל חוּץ מִנִּכְסֵי מְלוֹג כְּמוֹ שֶׁבֵּאַרְנוּ:","נִכְסֵי צֹאן בַּרְזֶל שֶׁאָבְדוּ אוֹ שֶׁנִּגְנְבוּ וּמָחֲלָה הָאִשָּׁה אוֹתָם לְבַעֲלָהּ וְקָנוּ מִמֶּנָּה בְּעֵדִים יֵרָאֶה לִי שֶׁאֵינָהּ יְכוֹלָה לוֹמַר נַחַת רוּחַ עָשִׂיתִי לְבַעְלִי. הָא לְמָה זֶה דּוֹמֶה לְמִי שֶׁקָּנוּ מִיָדָהּ שֶׁאֵין לָהּ אַחֲרָיוּת שֶׁהֶחֱזִירָה נְכָסִים אֵלּוּ נִכְסֵי מְלוֹג. שֶׁהֲרֵי אֵין הַבַּעַל מֵבִיא רְאָיָה לִטּל כְּלוּם וְלֹא לְהַחֲזִיק בַּנְּכָסִים אֶלָּא לְהִפָּטֵר מִתְּבִיעָתָהּ מִלְּשַׁלֵּם. אֲבָל אִם נָתְנָה לוֹ מַתָּנָה מִטַּלְטְלֵי צֹאן בַּרְזֶל הַקַּיָּמִין לֹא קָנָה מִפְּנֵי שֶׁיֵּשׁ לָהּ לוֹמַר נַחַת רוּחַ עָשִׂיתִי לְבַעְלִי:","בַּעַל שֶׁמָּכַר קַרְקַע לְפֵרוֹת לֹא עָשָׂה כְּלוּם. מִפְּנֵי שֶׁלֹּא הִתְקִינוּ פֵּרוֹת לָאִישׁ אֶלָּא כְּדֵי לְהַרְוִיחַ בְּהוֹצָאַת הַבַּיִת. לְפִיכָךְ אִם מָכַר לְפֵרוֹת וְלָקַח אוֹתָן הַמָּעוֹת לִסְחוֹרָה שׁוֹמְעִין לוֹ:","הָיוּ לָאִשָּׁה כְּסָפִים. אִם נִכְסֵי צֹאן בַּרְזֶל הֵן הֲרֵי זֶה נוֹשֵׂא וְנוֹתֵן בָּהֶן. וְאִם נִכְסֵי מְלוֹג הֵן בֵּין שֶׁהִכְנִיסָה אוֹתָן לוֹ בֵּין שֶׁנָּפְלוּ לָהּ בִּירֻשָּׁה אוֹ נִתְּנוּ לָהּ בְּמַתָּנָה אוֹ נָפְלוּ לָהּ מִטַּלְטְלִין אוֹ נִתְּנוּ לָהּ הֲרֵי אֵלּוּ יִמָּכְרוּ וְיִלָּקַח בָּהֶן קַרְקַע וְהוּא אוֹכֵל פֵּרוֹתֵיהֶן:","וְכֵן הָאִשָּׁה שֶׁחָבְלוּ בָּהּ אֲחֵרִים כָּל הַמָּעוֹת הָרְאוּיוֹת לָתֵת לָהּ יִלָּקַח בָּהֶן קַרְקַע וְהַבַּעַל אוֹכֵל פֵּרוֹתֵיהֶן כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת חוֹבֵל:","נָפְלוּ לָהּ עֲבָדִים אַף עַל פִּי שֶׁהֵן זְקֵנִים לֹא יִמָּכְרוּ מִפְּנֵי שֶׁבַח בֵּית אָבִיהָ. נָפְלוּ לָהּ זֵיתִים וּגְפָנִים וְלֹא הָיָה לָהּ בְּגוּף הַקַּרְקַע שֶׁהָאִילָנוֹת בָּהּ כְּלוּם. אִם עוֹשִׂין כְּדֵי טִפּוּלָן לֹא יִמָּכְרוּ מִפְּנֵי שֶׁבַח בֵּית אָבִיהָ וְאִם לָאו הֲרֵי אֵלּוּ יִמָּכְרוּ לְעֵצִים וְיִלָּקַח בָּהֶן קַרְקַע וְהוּא אוֹכֵל פֵּרוֹת:","נָפְלוּ לָהּ פֵּרוֹת מְחֻבָּרִין לַקַּרְקַע הֲרֵי אֵלּוּ שֶׁל בַּעַל. תְּלוּשִׁין מִן הַקַּרְקַע שֶׁלָּהּ וְיִמָּכְרוּ וְיִלָּקַח בָּהֶן קַרְקַע וְהוּא אוֹכֵל פֵּרוֹת. אֲבָל הַמְגָרֵשׁ אֶת אִשְׁתּוֹ וְהָיוּ לָהּ פֵּרוֹת מְחֻבָּרִין לַקַּרְקַע בִּשְׁעַת גֵּרוּשִׁין הֲרֵי אֵלּוּ שֶׁלָּהּ. וְאִם הָיוּ תְּלוּשִׁין הֲרֵי אֵלּוּ שֶׁלּוֹ:","עַבְדֵי נִכְסֵי מְלוֹג וּבֶהֱמַת נִכְסֵי מְלוֹג הַבַּעַל חַיָּב בִּמְזוֹנוֹת שֶׁלָּהֶן וּבְכָל צָרְכֵיהֶם וְהֵן עוֹשִׂין לוֹ וְהוּא אוֹכֵל פֵּרוֹתֵיהֶם. לְפִיכָךְ וְלַד שִׁפְחַת מְלוֹג לַבַּעַל. וְלַד בֶּהֱמַת מְלוֹג לַבַּעַל. וְאִם גֵּרְשָׁהּ וְרָצְתָה הָאִשָּׁה לִתֵּן דָּמִים וְלִטּל וְלַד הַשִּׁפְחָה מִפְּנֵי שֶׁבַח בֵּית אָבִיהָ שׁוֹמְעִין לָהּ:","הִכְנִיסָה לוֹ שְׁנֵי כֵּלִים אוֹ שְׁתֵּי שְׁפָחוֹת בְּתוֹרַת נִכְסֵי צֹאן בַּרְזֶל וְשָׁמוּ אוֹתָן עָלָיו בְּאֶלֶף זוּז וְהוּקְרוּ וְעָמְדוּ בְּאַלְפַּיִם וְגֵרְשָׁהּ נוֹטֶלֶת אֶחָד בְּאֶלֶף שֶׁלָּהּ. וְהַשֵּׁנִי אִם רָצְתָה שֶׁתִּתֵּן דָּמָיו וְתִטּל מִשּׁוּם שֶׁבַח בֵּית אָבִיהָ שׁוֹמְעִין לָהּ:","הַנּוֹתֵן מַתָּנָה לְאִשְׁתּוֹ בֵּין שֶׁנָּתַן לָהּ קַרְקַע בֵּין שֶׁנָּתַן לָהּ מָעוֹת וְלָקְחָה בָּהֶן קַרְקַע אֵין לַבַּעַל פֵּרוֹת בְּמַתָּנָה זוֹ. וְכֵן הַנּוֹתֵן מַתָּנָה לְאִשָּׁה עַל מְנָת שֶׁלֹּא יִהְיֶה הַבַּעַל אוֹכֵל פֵּרוֹתֶיהָ אֶלָּא יִהְיוּ פֵּרוֹתֶיהָ לָאִשָּׁה לְמַה שֶּׁתִּרְצֶה אֵין הַבַּעַל אוֹכֵל פֵּרוֹת מַתָּנָה זוֹ. וְכֵן הַמּוֹכֶרֶת כְּתֻבָּתָהּ בְּטוֹבַת הֲנָאָה אוֹתָן הַדָּמִים לָאִשָּׁה וְאֵין הַבַּעַל אוֹכֵל פֵּרוֹתֵיהֶן:","וְלַד בֶּהֱמַת מְלוֹג שֶׁנִּגְנַב וְנִמְצָא הַגַּנָּב וְשִׁלֵּם שְׁנַיִם הַכֶּפֶל לָאִשָּׁה שֶׁאֵין זֶה פְּרִי שֶׁתִּקְּנוּ לוֹ חֲכָמִים. הַחוֹבֵל בְּאִשְׁתּוֹ כָּל הַנֵּזֶק וְהַצַּעַר וְהַבּשֶׁת שֶׁלָּהּ וְאֵין הַבַּעַל אוֹכֵל פֵּרוֹת כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת חוֹבֵל:","הַמּוֹכֵר קַרְקַע לְאִשְׁתּוֹ. אִם הָיוּ הַמָּעוֹת שֶׁלָּקְחָה בָּהֶן אֶת הַקַּרְקַע מִבַּעַל גְּלוּיִין וִידוּעִין לַבַּעַל קָנְתָה וְהַבַּעַל אוֹכֵל פֵּרוֹת אוֹתָהּ הַקַּרְקַע. וְאִם הָיוּ מָעוֹת טְמוּנִין לֹא קָנְתָה שֶׁהַבַּעַל אוֹמֵר לֹא מָכַרְתִּי אֶלָּא כְּדֵי לְהַרְאוֹת הַמָּעוֹת שֶׁטָּמְנָה. וְאוֹתָן הַמָּעוֹת שֶׁנִּרְאוּ יִלָּקַח בָּהֶן קַרְקַע וְהַבַּעַל אוֹכֵל פֵּרוֹת:","הֲרֵי שֶׁנִּמְצְאוּ מָעוֹת אוֹ מִטַּלְטְלִין בְּיַד הָאִשָּׁה הִיא אוֹמֶרֶת בְּמַתָּנָה נִתְּנוּ לִי וְהוּא אוֹמֵר מִמַּעֲשֵׂה יָדַיִךְ הֵם שֶׁהֵם שֶׁלִּי הֲרֵי זוֹ נֶאֱמֶנֶת. וְיֵשׁ לוֹ לְהַחֲרִים עַל מִי שֶׁטּוֹעֶנֶת דָּבָר שֶׁאֵינוֹ כֵן. וְיִלָּקַח בָּהֶן קַרְקַע וְהוּא אוֹכֵל פֵּרוֹת. וְאִם אָמְרָה עַל מְנָת כֵּן נִתְּנוּ לִי עַל מְנָת שֶׁלֹּא יִהְיֶה לְבַעְלִי רְשׁוּת בָּהֶן אֶלָּא אֶעֱשֶׂה בָּהֶן כָּל מַה שֶּׁאֶרְצֶה עָלֶיהָ לְהָבִיא רְאָיָה. שֶׁכָּל מָמוֹן שֶׁנִּמְצָא בְּיַד הָאִשָּׁה בְּחֶזְקַת הַבַּעַל הוּא שֶׁיֹּאכַל פֵּרוֹתָיו עַד שֶׁתָּבִיא רְאָיָה:","אָמְרָה לוֹ אַתָּה נָתַתָּ לִי בְּמַתָּנָה נִשְׁבַּעַת שְׁבוּעַת הֶסֵּת שֶׁנָּתַן לָהּ הַבַּעַל וְאֵינוֹ אוֹכֵל פֵּרוֹתֵיהֶן:","אֵין מְקַבְּלִין פִּקְדוֹנוֹת לֹא מִן הַנָּשִׁים וְלֹא מִן הָעֲבָדִים וְלֹא מִן הַקְּטַנִּים. וְאִם עָבַר וְקִבֵּל מִן הָאִשָּׁה יַחֲזִיר לָאִשָּׁה. מֵתָה יַחֲזִיר לְבַעְלָהּ. קִבֵּל מִן הָעֶבֶד יַחֲזִיר לָעֶבֶד וְאִם מֵת יַחֲזִיר לְרַבּוֹ. קִבֵּל מִן הַקָּטָן יִקְנֶה לוֹ בּוֹ סֵפֶר תּוֹרָה אוֹ דָּבָר שֶׁאוֹכֵל פֵּרוֹתֵיהֶם. וְכֻלָּם שֶׁאָמְרוּ בִּשְׁעַת מִיתָתָן פִּקָּדוֹן זֶה שֶׁל פְּלוֹנִי הוּא אִם הָיוּ בְּחֶזְקַת נֶאֱמָנִין אֵצֶל זֶה שֶׁהַפִּקָּדוֹן אֶצְלוֹ יַעֲשֶׂה כְּמוֹ שֶׁצִּוּוּ וְאִם לָאו יִתֵּן לְיוֹרְשֵׁיהֶם:","הָאִשָּׁה שֶׁהָיוּ לָהּ כְּסָפִים הָרְאוּיוֹת לַבַּעַל לֶאֱכל פֵּרוֹתֵיהֶם הוּא אוֹמֵר כָּךְ וְכָךְ יִלָּקַח בָּהֶם וְהִיא אוֹמֶרֶת אֵינִי לוֹקַחַת בָּהֶן אֶלָּא כָּךְ וְכָךְ לוֹקְחִים דָּבָר שֶׁפֵּרוֹתָיו מְרֻבִּים וִיצִיאָתוֹ מְעוּטָה. בֵּין שֶׁהָיָה הַדָּבָר כִּרְצוֹנוֹ אוֹ שֶׁהָיָה כִּרְצוֹנָהּ. וְאֵין לוֹקְחִין אֶלָּא דָּבָר שֶׁגִּזְעוֹ מַחֲלִיף שֶׁמָּא יֹאכַל הַכּל וְנִמְצָא הַקֶּרֶן אָבֵד:","הָאִשָּׁה שֶׁהִכְנִיסָה לְבַעְלָהּ עֵז לַחֲלָבָהּ וְרָחֵל לְגִזָּתָהּ וְדֶקֶל לְפֵרוֹתָיו אַף עַל פִּי שֶׁאֵין לָהּ אֶלָּא פֵּרוֹת אֵלּוּ בִּלְבַד הֲרֵי זֶה אוֹכֵל וְהוֹלֵךְ עַד שֶׁתִּכְלֶה הַקֶּרֶן. וְכֵן אִם הִכְנִיסָה לוֹ כְּלֵי תַּשְׁמִישׁ בְּתוֹרַת נִכְסֵי מְלוֹג הֲרֵי זֶה מִשְׁתַּמֵּשׁ בָּהֶן וְלוֹבֵשׁ וּמַצִּיעַ וּמְכַסֶּה עַד שֶׁיִּכְלֶה הַקֶּרֶן. וּכְשֶׁיְּגָרֵשׁ אֵינוֹ חַיָּב לְשַׁלֵּם הַבְּלָאוֹת שֶׁל נִכְסֵי מְלוֹג:","הוֹרוּ הַגְּאוֹנִים שֶׁנִּכְסֵי צֹאן בַּרְזֶל אַף עַל פִּי שֶׁפְּחִיתָתָן עַל הַבַּעַל אִם הָיוּ הַבְּלָאוֹת קַיָּמִין וְהָיוּ עוֹשִׂין מֵעֵין מְלַאכְתָּן נוֹטֶלֶת כֵּלֶיהָ כְּמָה שֶׁהֵן. וְאִם לֹא הָיוּ עוֹשִׂין מֵעֵין מְלַאכְתָּן הֲרֵי הֵן כְּמוֹ שֶׁנִּגְנְבוּ אוֹ אָבְדוּ שֶׁהוּא חַיָּב לְשַׁלֵּם בִּדְמֵיהֶם שֶׁשָּׁמוּ אוֹתָן עָלָיו בִּשְׁעַת נִשּׂוּאִין. וּמִנְהָג פָּשׁוּט הוּא זֶה. וְכָל הַנּוֹשֵׂא עַל מִנְהָג זֶה קִבֵּל עָלָיו אַחֲרָיוּת הַנְּדוּנְיָא. וּכְשֵׁם שֶׁאֵינוֹ מְשַׁלֵּם הַפְּחָת כָּךְ אֵינוֹ נוֹטֵל אֶת הַשֶּׁבַח אִם הוֹתִירוּ דְּמֵיהֶן לְפִי מִנְהָג זֶה. יֵשׁ לַבַּעַל לָכוֹף מִקְצָת עַבְדֵי אִשְׁתּוֹ וְאַמְּהוֹתֶיהָ שֶׁיִּהְיוּ מְשַׁמְּשִׁין אוֹתוֹ בְּבֵית אִשָּׁה אַחֶרֶת שֶׁנָּשָׂא בֵּין שֶׁהָיוּ עַבְדֵי מְלוֹג בֵּין שֶׁהָיוּ עַבְדֵי צֹאן בַּרְזֶל. אֲבָל אֵינוֹ יָכוֹל לְהוֹלִיכָן לְעִיר אַחֶרֶת שֶׁלֹּא מִדַּעַת אִשְׁתּוֹ:"],"Mishneh Torah, Mourning 10":["הַשַּׁבָּת עוֹלָה לְמִנְיַן אֲבֵלוּת. וְאֵין אֲבֵלוּת בְּשַׁבָּת אֶלָּא בִּדְבָרִים שֶׁבְּצִנְעָה. כְּגוֹן עֲטִיפַת הָרֹאשׁ וְתַשְׁמִישׁ הַמִּטָּה וּרְחִיצָה בְּחַמִּין. אֲבָל דְּבָרִים שֶׁבְּגָלוּי אֵינוֹ נוֹהֵג בָּהֶן אֲבֵלוּת. אֶלָּא לוֹבֵשׁ מִנְעָלָיו וְזוֹקֵף אֶת הַמִּטָּה. וְנוֹתֵן שָׁלוֹם לְכָל אָדָם. וְאִם יֵשׁ לוֹ בֶּגֶד מַחְלִיף. וְלֹא יִלְבַּשׁ בֶּגֶד קָרוּעַ בְּשַׁבָּת. אֲפִלּוּ עַל אָבִיו וְעַל אִמּוֹ. וְאִם אֵין לוֹ לְהַחְלִיף מַחְזִיר אֶת הַקֶּרַע לְאַחֲרָיו:","מֵאֵימָתַי זוֹקְפִים אֶת הַמִּטּוֹת בְּעֶרֶב שַׁבָּת. מִן הַמִּנְחָה וּלְמַעְלָה. וְאַף עַל פִּי כֵן לֹא יֵשֵׁב עָלֶיהָ עַד שֶׁתֶּחֱשַׁךְ. וְאַף עַל פִּי שֶׁלֹּא נִשְׁתַּיֵּר לוֹ אֶלָּא יוֹם אֶחָד חוֹזֵר וְכוֹפֶה אוֹתָן בְּמוֹצָאֵי שַׁבָּת:","הָרְגָלִים וְכֵן רֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים אֵין דָּבָר מִדִּבְרֵי אֲבֵלוּת נוֹהֵג בָּהֶן. וְכָל הַקּוֹבֵר אֶת מֵתוֹ אֲפִלּוּ שָׁעָה אַחַת קֹדֶם הָרֶגֶל אוֹ קֹדֶם רֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים בָּטְלָה מִמֶּנּוּ גְּזֵרַת שִׁבְעָה. נִמְצָא מוֹנֶה לְאַחַר רֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים שְׁלֹשָׁה וְעֶשְׂרִים יוֹם וּלְאַחַר הַפֶּסַח שִׁשָּׁה עָשָׂר יוֹם. שֶׁהֲרֵי בָּטְלָה מִמֶּנּוּ גְּזֵרַת שִׁבְעָה וְשִׁבְעַת יְמֵי הֶחָג הֲרֵי אַרְבָּעָה עָשָׂר. וְכֵן אִם קָבַר קֹדֶם עֲצֶרֶת מוֹנֶה אַחֲרֶיהָ שִׁשָּׁה עָשָׂר יוֹם אַף עַל פִּי שֶׁהוּא יוֹם אֶחָד הֲרֵי הִיא רֶגֶל וְעוֹלָה לְשִׁבְעָה יָמִים:","קָבַר אֶת מֵתוֹ קֹדֶם חַג הַסֻּכּוֹת מוֹנֶה אַחַר הֶחָג תִּשְׁעָה יָמִים בִּלְבַד. שֶׁהֲרֵי שְׁמִינִי עֲצֶרֶת רֶגֶל בִּפְנֵי עַצְמוֹ וְנִמְצָא יוֹם טוֹב הָרִאשׁוֹן מַפְסִיק שִׁבְעָה. וְשִׁבְעַת יְמֵי הֶחָג. וּשְׁמִינִי שֶׁל חַג רֶגֶל אֶחָד הֲרֵי אֶחָד וְעֶשְׂרִים יוֹם:","הַקּוֹבֵר אֶת מֵתוֹ שִׁבְעַת יָמִים קֹדֶם רֶגֶל מִן הָרְגָלִים אוֹ קֹדֶם רֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים בָּטְלָה גְּזֵרַת שְׁלֹשִׁים. וּמֻתָּר לְסַפֵּר וּלְכַבֵּס בְּעֶרֶב יוֹם טוֹב אוֹ בְּעֶרֶב יוֹם הַכִּפּוּרִים שֶׁמִּקְצָת הַיּוֹם כְּכֻלּוֹ. וְאֵינוֹ מוֹנֶה לְאַחֲרֵיהֶם כְּלוּם. וְאִם עַל אָבִיו וְעַל אִמּוֹ הוּא מִתְאַבֵּל אֲפִלּוּ מֵתוּ קֹדֶם הָרֶגֶל שְׁלֹשִׁים יוֹם אֵינוֹ מְגַלֵּחַ עַד שֶׁיִּשְׁלַח פֶּרַע. אוֹ עַד שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו. וְאֵין הָרְגָלִים מַפְסִיקִין דָּבָר זֶה:","חָל שִׁשִּׁי שֶׁלּוֹ בְּעֶרֶב הָרֶגֶל וְאֵין צָרִיךְ לוֹמַר חֲמִישִׁי אוֹ שְׁלִישִׁי. אֵינוֹ מְגַלֵּחַ וְלֹא בָּטְלָה מִמֶּנּוּ אֶלָּא גְּזֵרַת שִׁבְעָה בִּלְבַד. וְאֵינוֹ מֻתָּר לִרְחֹץ וְלָסוּךְ וְלַעֲשׂוֹת דָּבָר עַד שֶׁיִּכָּנֵס יוֹם טוֹב. וְיוֹם טוֹב מַפְסִיק שְׁאָר הַשִּׁבְעָה. וּלְאַחַר יוֹם טוֹב מַשְׁלִים כָּל שְׁלֹשִׁים יוֹם מִיּוֹם הַמִּיתָה וְאָסוּר בָּהֶן בְּכָל חֲמִשָּׁה דְּבָרִים:","חָל שְׁבִיעִי שֶׁלּוֹ לִהְיוֹת בְּעֶרֶב הָרֶגֶל וַהֲרֵי הוּא שַׁבָּת בָּטְלָה מִמֶּנּוּ גְּזֵרַת שְׁלֹשִׁים וּמֻתָּר לְגַלֵּחַ בְּתוֹךְ הַמּוֹעֵד שֶׁהֲרֵי אָנוּס הָיָה וְאִי אֶפְשָׁר לוֹ לְגַלֵּחַ בְּשַׁבָּת. וְכֵן מְגַלֵּחַ אַחַר עֲצֶרֶת אוֹ אַחַר רֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים שֶׁהֲרֵי בָּטְלָה גְּזֵרַת שְׁלֹשִׁים וְיֵשׁ לוֹ לְגַלֵּחַ בְּכָל עֵת שֶׁיִּרְצֶה:","הַקּוֹבֵר אֶת מֵתוֹ בְּתוֹךְ הָרֶגֶל לֹא חָלָה עָלָיו אֲבֵלוּת כְּלָל. וְאֵינוֹ נוֹהֵג אֲבֵלוּת בָּרֶגֶל אֶלָּא לְאַחַר הָרֶגֶל מַתְחִיל לִמְנוֹת שִׁבְעָה וְנוֹהֵג בָּהֶן כָּל דִּבְרֵי אֲבֵלוּת. וּמוֹנֶה שְׁלֹשִׁים מִיּוֹם הַקְּבוּרָה וְנוֹהֵג בִּשְׁאָר הַשְּׁלֹשִׁים בְּכָל גְּזֵרוֹת שְׁלֹשִׁים:","הַמְּקוֹמוֹת שֶׁעוֹשִׂין שְׁנֵי יָמִים טוֹבִים מוֹנֶה הַשִּׁבְעָה מִיּוֹם טוֹב שֵׁנִי הָאַחֲרוֹן. אַף עַל פִּי שֶׁאֵינוֹ נוֹהֵג אֲבֵלוּת. הוֹאִיל וּמִדִּבְרֵיהֶם הוּא עוֹלֶה לוֹ מִן הַמִּנְיָן. וּמוֹנֶה אַחֲרָיו שִׁשָּׁה יָמִים בִּלְבַד וּמוֹנֶה שְׁלֹשִׁים יוֹם מִיּוֹם הַקְּבוּרָה כְּמוֹ שֶׁאָמַרְנוּ:","הַקּוֹבֵר אֶת מֵתוֹ בְּיוֹם טוֹב שֵׁנִי שֶׁהוּא יוֹם טוֹב הָאַחֲרוֹן. אוֹ בְּיוֹם טוֹב שֵׁנִי שֶׁל עֲצֶרֶת. נוֹהֵג בּוֹ אֲבֵלוּת. הוֹאִיל וְיוֹם טוֹב שֵׁנִי מִדִּבְרֵיהֶם וַאֲבֵלוּת יוֹם רִאשׁוֹן שֶׁל תּוֹרָה יִדָּחֶה עֲשֵׂה שֶׁל דִּבְרֵיהֶם מִפְּנֵי עֲשֵׂה שֶׁל תּוֹרָה. אֲבָל אִם קָבַר בְּיוֹם טוֹב שֵׁנִי שֶׁל רֹאשׁ הַשָּׁנָה אֵינוֹ נוֹהֵג בּוֹ אֲבֵלוּת. שֶׁשְּׁנֵיהֶן כְּיוֹם אָרֹךְ הֵן מִטַּעַם שֶׁבֵּאַרְנוּ בְּהִלְכוֹת קִדּוּשׁ הַחֹדֶשׁ:"],"Mishneh Torah, Mourning 9":["כָּל הַקְּרָעִים שֶׁקּוֹרֵעַ אָדָם עַל שְׁאָר קְרוֹבָיו. שׁוֹלֵל הַקֶּרַע לְאַחַר שִׁבְעָה וּמְאַחֶה לְאַחַר שְׁלֹשִׁים. עַל אָבִיו וְעַל אִמּוֹ שׁוֹלֵל לְאַחַר שְׁלֹשִׁים וְאֵינוֹ מְאַחֶה לְעוֹלָם. וְהָאִשָּׁה קוֹרַעַת וְשׁוֹלֶלֶת מִיָּד אֲפִלּוּ עַל אָבִיהָ וְעַל אִמָּהּ מִפְּנֵי הַצְּנִיעוּת:","כְּדֶרֶךְ שֶׁקּוֹרֵעַ אָדָם עַל אָבִיו וְעַל אִמּוֹ כָּךְ חַיָּב לִקְרֹעַ עַל רַבּוֹ שֶׁלִּמְּדוֹ תּוֹרָה. וְעַל הַנָּשִׂיא וְעַל אַב בֵּית דִּין. וְעַל רֹב הַצִּבּוּר שֶׁנֶּהֱרַג. וְעַל בִּרְכַּת הַשֵּׁם. וְעַל סֵפֶר תּוֹרָה שֶׁנִּשְׂרַף. וְעַל עָרֵי יְהוּדָה וְעַל יְרוּשָׁלַיִם. וְעַל הַמִּקְדָּשׁ:","כָּל אֵלּוּ הַקְּרָעִים קוֹרֵעַ עַד שֶׁמְּגַלֶּה אֶת לִבּוֹ וְאֵינוֹ מְאַחֶה לְעוֹלָם. וְאַף עַל פִּי שֶׁאֵין מִתְאַחִין מֻתָּר לְשׁוֹלְלָן לְמָלְלָן וּלְלַקְּטָן וְלַעֲשׂוֹתָם כְּמִין סֻלָּמוֹת. וְלֹא אָסְרוּ אֶלָּא בְּאִחוּי אֲלֶכְּסַנְדְּרִי בִּלְבַד. וְכָל הַקּוֹרֵעַ מִתּוֹךְ הַשָּׁלָל אוֹ הַמֶּלֶל אוֹ הַלִּקּוּט לֹא עָשָׂה כְּלוּם אֲבָל קוֹרֵעַ מִתּוֹךְ הָאִחוּי הָאֲלֶכְּסַנְדְּרִי בִּלְבַד. אֲפִלּוּ הָפַךְ הַכְּלִי וְנַעֲשָׂה שְׂפָתוֹ לְמַטָּה לֹא יְאַחֶה:","וּכְשֵׁם שֶׁהַמּוֹכֵר אָסוּר לְאַחוֹתוֹ כָּךְ הַלּוֹקֵחַ. לְפִיכָךְ הַמּוֹכֵר צָרִיךְ לְהוֹדִיעַ לַלּוֹקֵחַ שֶׁקֶּרַע זֶה אֵינוֹ מִתְאַחֶה:","וּמִנַּיִן שֶׁקּוֹרֵעַ עַל רַבּוֹ כְּדֶרֶךְ שֶׁקּוֹרֵעַ עַל אָבִיו. שֶׁנֶּאֱמַר (מלכים ב ב יב) \"וְהוּא מְצַעֵק אָבִי אָבִי רֶכֶב יִשְׂרָאֵל וּפָרָשָׁיו וְלֹא רָאָהוּ עוֹד וַיַּחֲזֵק בִּבְגָדָיו וַיִּקְרָעֵם לִשְׁנַיִם קְרָעִים\". מִכָּאן שֶׁחַיָּב לְהַבְדִּיל הַשָּׂפָה:","וּמִנַּיִן שֶׁקּוֹרְעִין עַל הַנָּשִׂיא וְעַל אַב בֵּית דִּין וְעַל שְׁמוּעָה שֶׁבָּאָה שֶׁנֶּהֱרַג רֹב צִבּוּר. שֶׁנֶּאֱמַר (שמואל ב א יא) \"וַיַּחֲזֵק דָּוִד בִּבְגָדָו וַיִּקְרָעֵם וְגַם כָּל הָאֲנָשִׁים אֲשֶׁר אִתּוֹ\" (שמואל ב א יב) \"וַיִּסְפְּדוּ וַיִּבְכּוּ וַיָּצֻמוּ עַד הָעָרֶב\". (שמואל ב א יב) \"עַל שָׁאוּל\" זֶה נָשִׂיא. (שמואל ב א יב) \"וְעַל יְהוֹנָתָן בְּנוֹ\" זֶה אַב בֵּית דִּין. (שמואל ב א יב) \"וְעַל עַם ה' וְעַל בֵּית יִשְׂרָאֵל כִּי נָפְלוּ בֶּחָרֶב\" זוֹ שְׁמוּעָה רָעָה:","וּמִנַּיִן שֶׁקּוֹרְעִין עַל בִּרְכַּת הַשֵּׁם. שֶׁנֶּאֱמַר (מלכים ב יח לז) \"וַיָּבֹא אֶלְיָקִים בֶּן חִלְקִיָּהוּ אֲשֶׁר עַל הַבַּיִת וְשֶׁבְנָא הַסֹּפֵר וְיוֹאָח בֶּן אָסָף הַמַּזְכִּיר אֶל חִזְקִיָּהוּ קְרוּעֵי בְגָדִים\". אֶחָד הַשּׁוֹמֵעַ וְאֶחָד הַשּׁוֹמֵעַ מִפִּי שׁוֹמֵעַ חַיָּבִין לִקְרֹעַ:","וְהָעֵדִים אֵין חַיָּבִין לִקְרֹעַ כְּשֶׁיָּעִידוּ בְּבֵית דִּין. שֶׁכְּבָר קָרְעוּ בְּשָׁעָה שֶׁשָּׁמְעוּ:","וּמִנַּיִן שֶׁקּוֹרְעִין עַל סֵפֶר תּוֹרָה שֶׁנִּשְׂרַף. שֶׁנֶּאֱמַר (ירמיה לו כג) \"וַיְהִי כִּקְרוֹא יְהוּדִי שָׁלֹשׁ דְּלָתוֹת וְאַרְבָּעָה\" וְגוֹ' (ירמיה לו כג) \"עַד תֹּם כָּל הַמְּגִלָּה עַל הָאֵשׁ אֲשֶׁר עַל הָאָח\" (ירמיה לו כד) \"וְלֹא פָחֲדוּ וְלֹא קָרְעוּ אֶת בִּגְדֵיהֶם הַמֶּלֶךְ וְכָל עֲבָדָיו\". מִכְלַל שֶׁחַיָּבִין לִקְרֹעַ. וְאֵין חַיָּבִין לִקְרֹעַ אֶלָּא עַל סֵפֶר תּוֹרָה שֶׁנִּשְׂרַף בִּזְרוֹעַ כְּמַעֲשֶׂה שֶׁהָיָה. וְחַיָּב לִקְרֹעַ שְׁתֵּי קְרִיעוֹת אַחַת עַל הַגְּוִיל וְאַחַת עַל הַכְּתָב. שֶׁנֶּאֱמַר (ירמיה לו כז) \"אַחֲרֵי שְׂרֹף הַמֶּלֶךְ אֶת הַמְּגִלָּה וְאֶת הַדְּבָרִים\":","וּמִנַּיִן שֶׁקּוֹרְעִין עַל עָרֵי יְהוּדָה וְעַל יְרוּשָׁלַיִם וְעַל הַמִּקְדָּשׁ שֶׁחָרְבוּ. שֶׁנֶּאֱמַר (ירמיה מא ה) \"וַיָּבֹאוּ אֲנָשִׁים מִשְּׁכֶם וּמִשִּׁילֹה וּמִשֹּׁמְרוֹן שְׁמֹנִים אִישׁ מְגֻלְּחֵי זָקָן וּקְרֻעֵי בְגָדִים\":","כָּל מִי שֶׁעָמַד עִם הַמֵּת בִּשְׁעַת יְצִיאַת נִשְׁמָתוֹ אַף עַל פִּי שֶׁאֵינוֹ קְרוֹבוֹ חַיָּב לִקְרֹעַ וְכֵן אָדָם כָּשֵׁר שֶׁמֵּת הַכּל חַיָּבִין לִקְרֹעַ עָלָיו אַף עַל פִּי שֶׁאֵינוֹ חָכָם. וְקוֹרְעִין טֶפַח כִּשְׁאָר הָאֲבֵלִים. אֲבָל חָכָם שֶׁמֵּת הַכּל קְרוֹבָיו וְהַכּל קוֹרְעִין עָלָיו עַד שֶׁמְּגַלִּין אֶת לִבָּם וְחוֹלְצִין מִיָּמִין. וּבֵית מִדְרָשׁוֹ שֶׁל אוֹתוֹ חָכָם בָּטֵל כָּל שִׁבְעָה. וּכְבָר נָהֲגוּ תַּלְמִידֵי חֲכָמִים בְּכָל מָקוֹם לִקְרֹעַ זֶה עַל זֶה טֶפַח. אַף עַל פִּי שֶׁהֵן שָׁוִין וְאֵין אֶחָד מֵהֶם מְלַמֵּד אֶת חֲבֵרוֹ:","כָּל הַקּוֹרְעִים עַל הֶחָכָם שֶׁמֵּת כֵּיוָן שֶׁהֶחְזִירוּ פְּנֵיהֶן מֵאֲחוֹרֵי הַמִּטָּה שׁוֹלְלִין. וְיֵרָאֶה לִי שֶׁהַקּוֹרֵעַ עַל הֶחָכָם מְאַחֶה לְמָחָר שֶׁאֲפִלּוּ רַבּוֹ שֶׁמֵּת אֵין מִתְאַבֵּל עָלָיו אֶלָּא יוֹם אֶחָד בִּלְבַד אוֹ יוֹם מִיתָה אוֹ יוֹם שְׁמוּעָה. כֵּן יֵרָאֶה לִי שֶׁהַקּוֹרֵעַ עַל הַנָּשִׂיא וְכַיּוֹצֵא בּוֹ שׁוֹלֵל לְמָחָר אַף עַל פִּי שֶׁאֵינוֹ מְאַחֶה עֲלֵיהֶם לְעוֹלָם:","חָכָם שֶׁבָּאָה שְׁמוּעָתוֹ שֶׁמֵּת אֵין קוֹרְעִין עָלָיו אֶלָּא בִּשְׁעַת הֶסְפֵּדוֹ וְזֶהוּ כְּבוֹדוֹ. וְשׁוֹלֵל בּוֹ בַּיּוֹם וּמְאַחֶה לְמָחָר:","אַב בֵּית דִּין שֶׁמֵּת הַכּל קוֹרְעִין עָלָיו וְחוֹלְצִין מִשְּׂמֹאל וְכָל בָּתֵּי מִדְרָשׁוֹת שֶׁבְּעִירוֹ בְּטֵלִין. וּבְנֵי בֵּית הַכְּנֶסֶת נִכְנָסִין לְבֵית הַכְּנֶסֶת. וּמְשַׁנִּין אֶת מְקוֹמָן. הַיּוֹשְׁבִין בַּדָּרוֹם יֵשְׁבוּ בַּצָּפוֹן. וְהַיּוֹשְׁבִים בַּצָּפוֹן יֵשְׁבוּ בַּדָּרוֹם:","נָשִׂיא שֶׁמֵּת הַכּל קוֹרְעִין עָלָיו. וְחוֹלְצִין שְׁתֵּי הַיָּדַיִם מִכָּאן וּמִכָּאן. וּבְכָל בָּתֵּי מִדְרָשׁוֹת בְּטֵלִים. וּבְנֵי בֵּית הַכְּנֶסֶת נִכְנָסִין בְּשַׁבָּת לְבֵית הַכְּנֶסֶת וְקוֹרְאִין שִׁבְעָה. וְלֹא יְטַיְּלוּ בַּשּׁוּק אֶלָּא יוֹשְׁבִין מִשְׁפָּחוֹת מִשְׁפָּחוֹת דָּוִים כָּל הַיּוֹם:"],"Mishneh Torah, Murderer and the Preservation of Life 8":["מִצְוַת עֲשֵׂה לְהַפְרִישׁ עָרֵי מִקְלָט שֶׁנֶּאֱמַר (דברים יט ב) \"שָׁלוֹשׁ עָרִים תַּבְדִּיל לָךְ\". וְאֵין עָרֵי מִקְלָט נוֹהֲגוֹת אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל:","וְשֵׁשׁ עָרִים הָיוּ. שָׁלֹשׁ הִבְדִּיל משֶׁה רַבֵּנוּ בְּעֵבֶר הַיַּרְדֵּן. וְשָׁלֹשׁ הִבְדִּיל יְהוֹשֻׁעַ בְּאֶרֶץ כְּנַעַן:","אֵין אַחַת מֵעָרֵי מִקְלָט קוֹלֶטֶת עַד שֶׁיֻּבְדְּלוּ כֻּלָּן. שֶׁנֶּאֱמַר (במדבר לה יג) \"שֵׁשׁ עָרֵי מִקְלָט תִּהְיֶינָה לָכֶם\". וְהוֹדִיעָנוּ משֶׁה רַבֵּנוּ שֶׁאֵין שָׁלֹשׁ שֶׁבְּעֵבֶר הַיַּרְדֵּן קוֹלְטוֹת עַד שֶׁיֻּבְדְּלוּ שָׁלֹשׁ שֶׁבְּאֶרֶץ כְּנַעַן. וְלָמָּה הִבְדִּילָן אָמַר הוֹאִיל וּבָאָה מִצְוָה לְיָדִי אֲקַיְּמֶנָּה:","בִּימֵי הַמֶּלֶךְ הַמָּשִׁיחַ מוֹסִיפִין שָׁלֹשׁ אֲחֵרוֹת עַל אֵלּוּ הַשֵּׁשׁ. שֶׁנֶּאֱמַר (דברים יט ט) \"וְיָסַפְתָּ לְךָ עוֹד שָׁלֹשׁ עָרִים עַל הַשָּׁלֹשׁ הָאֵלֶּה\". וְהֵיכָן מוֹסִיפִין אוֹתָן בְּעָרֵי הַקֵּינִי וְהַקְּנִזִּי וְהַקַּדְמוֹנִי שֶׁנִּכְרַת לְאַבְרָהָם אָבִינוּ בְּרִית עֲלֵיהֶן וַעֲדַיִן לֹא נִכְבְּשׁוּ וַעֲלֵיהֶן נֶאֱמַר בַּתּוֹרָה (דברים יט ח) \"וְאִם יַרְחִיב ה' אֱלֹהֶיךָ אֶת גְּבֻלְךָ\":","וְחַיָּבִין בֵּית דִּין לְכַוֵּן הַדְּרָכִים לְעָרֵי מִקְלָט לְתַקְּנָם וּלְהַרְחִיבָן. וּמְסִירִין מֵהֶן כָּל מִכְשׁוֹל וְכָל תַּקָּלָה. וְאֵין מַנִּיחִין בַּדֶּרֶךְ לֹא תֵּל וְלֹא גַּיְא וְלֹא נָהָר. אֶלָּא עוֹשִׂין עָלָיו גֶּשֶׁר כְּדֵי שֶׁלֹּא לְעַכֵּב אֶת הַבּוֹרֵחַ לְשָׁם. שֶׁנֶּאֱמַר (דברים יט ג) \"תָּכִין לְךָ הַדֶּרֶךְ\". וְרֹחַב דֶּרֶךְ עָרֵי מִקְלָט אֵין פָּחוֹת מִשְּׁלֹשִׁים וּשְׁתַּיִם אַמּוֹת. וּמִקְלָט מִקְלָט הָיָה כָּתוּב עַל פָּרָשַׁת דְּרָכִים כְּדֵי שֶׁיַּכִּירוּ הָרַצְחָנִים וְיִפְנוּ לְשָׁם:","בַּחֲמִשָּׁה עָשָׂר בַּאֲדָר בְּכָל שָׁנָה בֵּית דִּין מוֹצִיאִין שְׁלוּחִים לְתַקֵּן הַדְּרָכִים. וְכָל מָקוֹם שֶׁמְּצָאוּהוּ שֶׁנִּתְקַלְקֵל מְתַקְּנִים אוֹתוֹ. וּבֵית דִּין שֶׁנִּתְרַשְּׁלוּ בְּדָבָר זֶה מַעֲלֶה עֲלֵיהֶן הַכָּתוּב כְּאִלּוּ שָׁפְכוּ דָּמִים:","וְכֵן מוֹשְׁחִין בֵּין כָּל עִיר וְעִיר מֵעָרֵי מִקְלָט בִּתְחִלַּת הַפְרָשָׁתָן עַד שֶׁיִּהְיוּ מְשֻׁלָּשׁוֹת בְּשָׁוֶה. שֶׁנֶּאֱמַר (דברים יט ג) \"תָּכִין לְךָ הַדֶּרֶךְ\":","עָרֵי מִקְלָט אֵין עוֹשִׂין אוֹתָן לֹא עֲיָרוֹת גְּדוֹלוֹת וְלֹא כְּרַכִּים גְּדוֹלִים וְלֹא קְטַנִּים אֶלָּא עֲיָרוֹת בֵּינוֹנִיּוֹת. וְאֵין מוֹשִׁיבִין אוֹתָן אֶלָּא בִּמְקוֹם שְׁוָקִים וּבִמְקוֹם הַמַּיִם. וְאִם אֵין שָׁם מַיִם מַכְנִיסִין לְתוֹכָן מַיִם. וְאֵין מוֹשִׁיבִין אוֹתָן אֶלָּא בִּמְקוֹם אֻכְלוּסִין. נִתְמַעֲטוּ אֻכְלוּסֵיהֶן מוֹסִיפִין עֲלֵיהֶן. נִתְמַעֲטוּ דִּיּוּרֵיהֶן מַכְנִיסִין לְתוֹכָן כֹּהֲנִים לְוִיִּים וְיִשְׂרְאֵלִים. וְאֵין פּוֹרְסִין בְּתוֹכָן מְצוּדוֹת וְאֵין מַפְשִׁילִין בְּתוֹכָן חֲבָלִים כְּדֵי שֶׁלֹּא יִהְיֶה רֶגֶל גּוֹאֵל הַדָּם מְצוּיָה שָׁם:","כָּל עָרֵי הַלְוִיִּם קוֹלְטוֹת וְכָל אַחַת מֵהֶן עִיר מִקְלָט הִיא. שֶׁנֶּאֱמַר (במדבר לה ו) \"וַעֲלֵיהֶם תִּתְּנוּ אַרְבָּעִים וּשְׁתַּיִם עִיר\" (במדבר לה ז) \"כָּל הֶעָרִים אֲשֶׁר תִּתְּנוּ לַלְוִיִּם אַרְבָּעִים וּשְׁמֹנֶה עִיר\". הִקִּישָׁן הַכָּתוּב כֻּלָּן זוֹ לָזוֹ לִקְלֹט:","וּמַה הֶפְרֵשׁ יֵשׁ בֵּין עָרֵי מִקְלָט שֶׁהֻבְדְּלוּ לְמִקְלָט וּבֵין שְׁאָר עָרֵי הַלְוִיִּם. שֶׁעָרֵי מִקְלָט קוֹלְטוֹת בֵּין לְדַעַת בֵּין שֶׁלֹּא לְדַעַת הוֹאִיל וְנִכְנַס בָּהֶן נִקְלָט. וּשְׁאָר עָרֵי הַלְוִיִּם אֵינָן קוֹלְטוֹת אֶלָּא לְדַעַת. וְרוֹצֵחַ הַדָּר בְּעָרֵי מִקְלָט אֵינוֹ נוֹתֵן שְׂכַר בֵּיתוֹ. וְהַדָּר בִּשְׁאָר עָרֵי הַלְוִיִּם נוֹתֵן שָׂכָר לְבַעַל הַבַּיִת:","כָּל עִיר הַקּוֹלֶטֶת תְּחוּמָהּ קוֹלֵט כָּמוֹהָ. אִילָן שֶׁעוֹמֵד בְּתוֹךְ תְּחוּם עָרֵי מִקְלָט וְנוֹפוֹ נוֹטֶה חוּץ לַתְּחוּם מִשֶּׁיַּגִּיעַ תַּחַת הַנּוֹף נִקְלָט. הָיָה עוֹמֵד חוּץ לַתְּחוּם וְנוֹפוֹ נוֹטֶה לְתוֹךְ הַתְּחוּם מִשֶּׁיַּגִּיעַ לְעִקָּרוֹ נִקְלָט וְהַהוֹרְגוֹ שָׁם נֶהֱרָג עָלָיו. וְאַף עַל פִּי שֶׁהַתְּחוּם קוֹלֵט אֵין הָרוֹצֵחַ דָּר בּוֹ שֶׁנֶּאֱמַר (במדבר לה כה) \"וְיָשַׁב בָּהּ\" בָּהּ וְלֹא בִּתְחוּמָהּ:"],"Mishneh Torah, Negative Mitzvot 1":["מצוה ראשונה ממצוות לא תעשה, שלא לעלות במחשבה שיש שם אלוה זולתי ה', שנאמר \"לא יהיה לך אלוהים אחרים, על פניי\" (שמות כ,ב; דברים ה,ו)."],"Mishneh Torah, Negative Mitzvot 11":["שלא להקים מצבה, שנאמר \"ולא תקים לך, מצבה\" (דברים טז,כב)."],"Mishneh Torah, Negative Mitzvot 120":["שלא להותיר מבשר התודה עד בוקר, שנאמר \"ולא תותירו ממנו, עד בוקר\" (ראה ויקרא כב,ל); והוא הדין לשאר הקודשים, שאין מניחין אותן לאחר זמן אכילתן."],"Mishneh Torah, Negative Mitzvot 131":["שלא לאכול נותר, שנאמר \"ואוכליו עוונו יישא . . . ונכרתה הנפש ההיא, מעמיה\" (ויקרא יט,ח)."],"Mishneh Torah, Negative Mitzvot 142":["שלא לאכול מעשר שני של תירוש חוץ לירושלים, שנאמר \"תירושך\" (דברים יב,יז)."],"Mishneh Torah, Negative Mitzvot 153":["שלא לאכול הטבל; והטבל הוא הדבר שגידוליו מן הארץ החייב בתרומות ומעשרות, שלא הוציאו ממנו תרומת ה': .שנאמר \"ולא יחללו, את קודשי בני ישראל--את אשר ירימו, לה'\" (ויקרא כב,טו); כלומר, דברים שהם עתידין להרים אותם לה', לא יעשו אותם חול ויאכלו אותם בטבלם."],"Mishneh Torah, Negative Mitzvot 164":["שלא ייכנס כוהן למקדש קרוע בגדים, שנאמר \"ובגדיכם לא תפרומו\" (ויקרא י,ו)."],"Mishneh Torah, Negative Mitzvot 175":["שלא לאכול שרץ העוף, שנאמר \"כול שרץ העוף, טמא הוא לכם\" (דברים יד,יט)."],"Mishneh Torah, Negative Mitzvot 186":["שלא לבשל בשר בחלב, שנאמר \"לא תבשל גדי, בחלב אימו\" (שמות כג,יט; שמות לד,כו; דברים יד,כא)."],"Mishneh Torah, Negative Mitzvot 197":["שלא לאכול חמץ בפסח, שנאמר \"לא ייאכל, חמץ\" (שמות יג,ג)."],"Mishneh Torah, Negative Mitzvot 207":["שלא ייטמא הנזיר למת, שנאמר \"לאביו ולאימו . . . לא ייטמא להם, במותם\" (במדבר ו,ז)."],"Mishneh Torah, Negative Mitzvot 218":["שלא יעשה מלאכה בשני מיני בהמה כאחד, שנאמר \"לא תחרוש בשור ובחמור, יחדיו\" (דברים כב,י)."],"Mishneh Torah, Negative Mitzvot 229":["שלא לעזוב הלויים, שנאמר \"הישמר לך, פן תעזוב את הלוי\" (דברים יב,יט), אלא נותנין להם מתנותיהם ומשמחים אותם בהן בכל רגל ורגל."],"Mishneh Torah, Negative Mitzvot 24":["שלא ליהנות בממון עיר הנידחת, שנאמר \"ולא ידבק בידך מאומה, מן החרם\" (דברים יג,יח)."],"Mishneh Torah, Negative Mitzvot 250":["שלא יונה במקח וממכר, שנאמר \"אל תונו, איש את אחיו\" (ויקרא כה,יד)."],"Mishneh Torah, Negative Mitzvot 261":["שלא למכור אמה עברייה לאחר, שנאמר \"לֹא יִמְשׁוֹל לְמָכְרָהּ בְּבִגְדוֹ בָהּ\" (שמות כא, ח)."],"Mishneh Torah, Negative Mitzvot 272":["שלא להיות אצלנו איפה ואיפה אבן ואבן, שנאמר \"לֹא יִהְיֶה לְךָ בְּבֵיתְךָ אֵיפָה וְאֵיפָה\" (דברים כה, יד)."],"Mishneh Torah, Negative Mitzvot 283":["שלא ילמד חובה מי שלימד זכות תחילה בדיני נפשות, שנאמר \"לא תענה על ריב, לנטות\" (שמות כג, ב)."],"Mishneh Torah, Negative Mitzvot 294":["שלא לענוש האנוס, שנאמר \"וְלַנַּעֲרָה לֹא תַעֲשֶׂה דָּבָר\" (דברים כב, כו)."],"Mishneh Torah, Negative Mitzvot 304":["שלא לנקום, שנאמר \"לא תיקום\" (ויקרא יט,יח)."],"Mishneh Torah, Negative Mitzvot 315":["שלא לקלל הדיין, שנאמר \"אלוהים, לא תקלל\" (שמות כב,כז)."],"Mishneh Torah, Negative Mitzvot 326":["שלא לעשות מלאכה באחד לחודש השביעי, שנאמר בו \"כל מלאכת עבודה, לא תעשו\" (ויקרא כג,כה; במדבר כט,א)."],"Mishneh Torah, Negative Mitzvot 337":["שלא לגלות ערוות אישה ובתה, שנאמר \"ערוות אישה ובתה, לא תגלה\" (ויקרא יח,יז)."],"Mishneh Torah, Negative Mitzvot 348":["שלא לשכב עם בהמה, שנאמר \"ובכל בהמה לא תיתן שכובתך, לזרע\" (ראה ויקרא יח,כ; ויקרא יח,כג)."],"Mishneh Torah, Negative Mitzvot 359":["שלא יגרש מוציא שם רע את אשתו, שנאמר בו \"לא יוכל לשלחה כל ימיו\" (דברים כב,יט)."],"Mishneh Torah, Negative Mitzvot 40":["שלא יעדה איש עדי אישה, שנאמר \"ולא ילבש גבר שמלת אישה\" (דברים כב,ה), מפני שזה היה מנהג עובדי עבודה זרה וכן מפורש בספרי עבודתה."],"Mishneh Torah, Negative Mitzvot 51":["שלא להושיב עובדי עבודה זרה בארצנו, שנאמר \"לא יישבו בארצך\" (שמות כג,לג)."],"Mishneh Torah, Negative Mitzvot 62":["שלא ישבע לשוא, שנאמר \"לֹא תִשָּׂא אֶת שֵׁם ה' אֱלֹהֶיךָ לַשָּׁוְא\" (שמות כ, ו; דברים ה, י)."],"Mishneh Torah, Negative Mitzvot 73":["שלא יכנס למקדש ולא יורה בתורה שתוי יין, שנאמר \"יַיִן וְשֵׁכָר אַל תֵּשְׁתְּ בְּבוֹאֲכֶם אֶל אֹהֶל מוֹעֵד\" (ויקרא י, ט) ונאמר \"וּלְהוֹרוֹת אֶת בְּנֵי יִשְׂרָאֵל\" (ויקרא י, יא)."],"Mishneh Torah, Negative Mitzvot 84":["שלא לסוך בשמן המשחה זר, שנאמר \"על בשר אדם, לא ייסך\" (שמות ל,לב)."],"Mishneh Torah, Negative Mitzvot 95":["שלא להקריב בעל מום עובר, שנאמר \"לא תזבח לה' אלוהיך שור ושה, אשר יהיה בו מום\" (דברים יז,א); זה הוא מום עובר."],"Mishneh Torah, Neighbors 3":["כֹּתֶל חָצֵר הַמַּבְדִּיל בֵּין שְׁנֵי שֻׁתָּפִין שֶׁנָּפַל. יֵשׁ לְכָל אֶחָד מִשְּׁנֵיהֶם לָכֹף עַל חֲבֵרוֹ לִבְנוֹתוֹ עַד גֹּבַהּ אַרְבַּע אַמּוֹת כְּדֵי שֶׁלֹּא יִרְאוּ זֶה אֶת זֶה. אֲבָל יֶתֶר עַל אַרְבַּע אַמּוֹת אֵין מְחַיְּבִין אוֹתוֹ. רָצָה הָאֶחָד וְהִגְבִּיהַּ הַכֹּתֶל יוֹתֵר עַל אַרְבַּע אַמּוֹת. אִם בָּא חֲבֵרוֹ וּבָנָה כֹּתֶל אַחֵר גָּבוֹהַּ כְּנֶגֶד הַכֹּתֶל שֶׁבֵּינֵיהֶן מְחַיְּבִין אוֹתוֹ לִתֵּן חֶלְקוֹ בַּגֹּבַהּ שֶׁכְּנֶגֶד כָּתְלוֹ. כֵּיצַד. בָּנָה אֶחָד כֹּתֶל שֶׁבֵּינֵיהֶן וְהִגְבִּיהוֹ עֶשֶׂר אַמּוֹת וּבָא חֲבֵרוֹ וּבָנָה כֹּתֶל אַחֵר כְּנֶגְדּוֹ אוֹ בְּצִדּוֹ לַעֲשׂוֹת לוֹ בַּיִת וְהִגְבִּיהַּ הַכֹּתֶל הָאַחֵר שֵׁשׁ אַמּוֹת מְחַיְּבִין אוֹתוֹ לִתֵּן חֶלְקוֹ בִּשְׁתֵּי אַמּוֹת שֶׁמּוֹסִיף עַל אַרְבַּע אַמּוֹת שֶׁהֲרֵי נִרְאֶה מִמַּעֲשָׂיו שֶׁהוּא רוֹצֶה בָּהֶן. וְכֵן אִם חָקַק בְּרֹאשׁ הַכֹּתֶל שֶׁבֵּינֵיהֶן מָקוֹם לְהַנִּיחַ בּוֹ הַקּוֹרוֹת אוֹ שֶׁבָּנָה עָלָיו קוֹרָה גְּדוֹלָה שֶׁהַקּוֹרוֹת נִשְׁעָנִין עָלֶיהָ מְחַיְּבִין אוֹתוֹ לִתֵּן חֶלְקוֹ בְּשֵׁשׁ הָאַמּוֹת כֻּלָּן שֶׁהוֹסִיף חֲבֵרוֹ עַל הָאַרְבַּע אַמּוֹת אַף עַל פִּי שֶׁלֹּא בָּנָה כָּל הַכֹּתֶל שֶׁהֲרֵי גִּלָּה דַּעְתּוֹ שֶׁהוּא רוֹצֶה בְּכָל הַגֹּבַהּ הַזֶּה:","אֶחָד מִן הַשֻּׁתָּפִין שֶׁבָּנָה הַכֹּתֶל שֶׁמַּבְדִּיל בֵּינוֹ וּבֵין חֲבֵרוֹ עַד אַרְבַּע אַמּוֹת וְתָבַע חֲבֵרוֹ לִתֵּן חֶלְקוֹ בָּהוֹצָאָה וְאָמַר נָתַתִּי חֶלְקִי. הֲרֵי זֶה בְּחֶזְקַת שֶׁנָּתַן וְנִשְׁבָּע הֶסֵּת שֶׁנָּתַן וְנִפְטָר עַד שֶׁיָּבִיא רְאָיָה הַתּוֹבֵעַ שֶׁלֹּא נָתַן. אֲבָל אִם בָּא לִתְבֹּעַ אוֹתוֹ לִתֵּן חֶלְקוֹ בְּהוֹצָאַת שְׁאָר הַגֹּבַהּ שֶׁהוֹסִיף עַל אַרְבַּע אַמּוֹת מִפְּנֵי שֶׁסָּמַךְ לוֹ אוֹ כְּנֶגְדּוֹ וְאָמַר נָתַתִּי אֵינוֹ נֶאֱמָן. אֶלָּא חֲבֵרוֹ נִשְׁבָּע בִּנְקִיטַת חֵפֶץ שֶׁלֹּא נָתַן לוֹ וְנוֹטֵל מִמֶּנּוּ כְּדִין כָּל הַנִּשְׁבָּעִין וְנוֹטְלִין. עַד שֶׁיָּבִיא רְאָיָה זֶה שֶׁנָּתַן לוֹ:","מִי שֶׁהָיָה לוֹ חֻרְבָּה בֵּין חֻרְבּוֹת חֲבֵרוֹ וְעָמַד חֲבֵרוֹ וְגָדַר רוּחַ רִאשׁוֹנָה וּשְׁנִיָּה וּשְׁלִישִׁית עַד שֶׁנִּמְצֵאת חֻרְבָּה זוֹ מִשְּׁלֹשׁ רוּחוֹתֶיהָ גְּדוּרָה. אֵין מְחַיְּבִין אוֹתוֹ לִתֵּן לוֹ הַהוֹצָאָה כְּלוּם שֶׁהֲרֵי לֹא הוֹעִיל לוֹ וַהֲרֵי חֻרְבָּתוֹ פְּתוּחָה לִרְשׁוּת הָרַבִּים כְּשֶׁהָיְתָה. לְפִיכָךְ אִם גָּדַר לוֹ רוּחַ רְבִיעִית עַד שֶׁנִּמְצֵאת חֻרְבָּתוֹ מֻקֶּפֶת גָּדֵר מְגַלְגְּלִין עָלָיו אֶת הַכּל וְנוֹתֵן חֲצִי הַהוֹצָאָה שֶׁהוֹצִיא זֶה בְּאַרְבַּע רוּחוֹת עַד אַרְבַּע אַמּוֹת. וּבִלְבַד שֶׁיִּהְיֶה מְקוֹם הַכֹּתֶל שֶׁל שְׁנֵיהֶם:","אֲבָל אִם הָיָה הַכֹּתֶל שֶׁל זֶה שֶׁבָּנָה וּבְחֶלְקוֹ בָּנָה יֵרָאֶה לִי שֶׁאֵין מְגַלְגְּלִין עָלָיו אֶלָּא דָּבָר מוּעָט כְּמוֹ שֶׁיִּרְאוּ הַדַּיָּנִין שֶׁהֲרֵי אֵינוֹ יָכוֹל לְהִשְׁתַּמֵּשׁ בַּכְּתָלִים. וְכֵן אִם הַנִּקָּף עַצְמוֹ הוּא שֶׁגָּדַר רוּחַ רְבִיעִית הֲרֵי גִּלָּה דַּעְתּוֹ וְנוֹתֵן חֲצִי הַהוֹצָאָה שֶׁל שָׁלֹשׁ רוּחוֹת אִם הָיוּ הַכְּתָלִים שֶׁל שְׁנֵיהֶם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","וְכֵן שְׁנֵי בָּתִּים זֶה בְּצַד זֶה וְהָיוּ גַּגֵּיהֶן עֲשׂוּיִין לְדִירָה אֲפִלּוּ הָיוּ בִּשְׁנֵי צִדֵּי רְשׁוּת הָרַבִּים זֶה עוֹשֶׂה מַעֲקֶה לַחֲצִי גַּגּוֹ שֶׁהוּא דָּר בּוֹ וְזֶה עוֹשֶׂה מַעֲקֶה לַחֲצִי גַּגּוֹ. וְזֶה שֶׁלֹּא כְּנֶגֶד זֶה וּמַעֲדִיף כְּדֵי שֶׁלֹּא יִרְאוּ זֶה אֶת זֶה. וְאַף עַל פִּי שֶׁבְּנֵי רְשׁוּת הָרַבִּים רוֹאִין אוֹתוֹ יָכוֹל כָּל אֶחָד לוֹמַר לַחֲבֵרוֹ אֵלּוּ אֵין רוֹאִין אוֹתִי אֶלָּא בַּיּוֹם בְּעֵת שֶׁאֶעֱמֹד עַל גַּגִּי וְאַתָּה רוֹאֶה אוֹתִי תָּמִיד:","גַּג הַסָּמוּךְ לַחֲצַר חֲבֵרוֹ עוֹשֶׂה לוֹ מַעֲקֶה גָּבוֹהַּ אַרְבַּע אַמּוֹת. אֲבָל בֵּין גַּג לְגַג מִשְּׁאָר הַגַּגִּין אֵינוֹ זָקוּק לְאַרְבַּע אַמּוֹת שֶׁאֵין בְּנֵי אָדָם דָּרִין בַּגַּגּוֹת לְפִיכָךְ אֵין בַּגַּגּוֹת הֶזֵּק רְאִיָּה. אֲבָל צָרִיךְ לַעֲשׂוֹת מְחִצָּה בֵּין שְׁנֵי הַגַּגִּין גְּבוֹהָה עֲשָׂרָה טְפָחִים כְּדֵי שֶׁיִּתְפֹּס אוֹתוֹ כְּגַנָּב אִם נִכְנַס לִרְשׁוּתוֹ:","שְׁתֵּי חֲצֵרוֹת זוֹ לְמַעְלָה מִזּוֹ לֹא יֹאמַר הָעֶלְיוֹן הֲרֵינִי בּוֹנֶה מִכְּנֶגְדִּי וְעוֹלֶה אֶלָּא בּוֹנִים שְׁנֵיהֶם מִלְּמַטָּה וְעוֹלֶה וּבוֹנֶה הָעֶלְיוֹן לְבַדּוֹ מִכְּנֶגְדּוֹ וָמַעְלָה. וְאִם הָיְתָה חֲצֵרוֹ לְמַעְלָה מִגַּגּוֹ שֶׁל חֲבֵרוֹ אֵין הָעֶלְיוֹן זָקוּק לַתַּחְתּוֹן כְּלָל:","מִי שֶׁהָיָה כָּתְלוֹ סָמוּךְ לְגִנַּת חֲבֵרוֹ וְנָפַל כּוֹפִין אוֹתוֹ לְפַנּוֹת אֲבָנָיו. אָמַר לוֹ הִגִּיעוּךָ וַהֲרֵי הֵן שֶׁלְּךָ אֵין שׁוֹמְעִין לוֹ. וְאִם רָצָה בָּהֶן בַּעַל הַגִּנָּה וְאָמַר לוֹ הֵן אִם פִּנָּה אוֹתָם קָנָה וְאֵינוֹ יָכוֹל לַחְזֹר בּוֹ וַאֲפִלּוּ אָמַר הֵילָךְ יְצִיאוֹתֶיךָ וְאֶטּל אֲבָנַי אֵין שׁוֹמְעִין לוֹ. אֲבָל אִם לֹא פִּנָּה לֹא קָנָה שֶׁלֹּא אָמַר לוֹ אֶלָּא לִדְחוֹתוֹ:","חָמֵשׁ גִּנּוֹת הַמְסַפְּקוֹת מַיִם מִמַּעְיָן אֶחָד וְנִתְקַלְקֵל הַמַּעְיָן כֻּלָּן מְתַקְּנוֹת עִם הָעֶלְיוֹנָה. נִמְצֵאת הַתַּחְתּוֹנָה מְתַקֶּנֶת עִם כֻּלָּן וּמְתַקֶּנֶת לְעַצְמָהּ. וְהָרִאשׁוֹנָה אֵינָהּ מְתַקֶּנֶת עִם הַשְּׁנִיָּה וְלֹא מֵהַשְּׁנִיָּה וּלְמַטָּה. וְכֵן חָמֵשׁ חֲצֵרוֹת שֶׁשּׁוֹפְכִין מַיִם לְבִיב אֶחָד וְנִתְקַלְקֵל הַבִּיב כֻּלָּן מְתַקְּנוֹת עִם הַתַּחְתּוֹנָה. נִמְצֵאת הָעֶלְיוֹנָה מְתַקֶּנֶת עִם כֻּלָּן וּמְתַקֶּנֶת לְעַצְמָהּ וְהַתַּחְתּוֹנָה אֵינָהּ מְתַקֶּנֶת עִם הַשְּׁנִיָּה וְלֹא מִשְּׁנִיָּה וּלְמַעְלָה:","בְּנֵי הַנָּהָר מַשְׁקִין עַל הַסֵּדֶר. רָצָה אֶחָד מֵהֶן לִסְכֹּר כְּדֵי שֶׁיַּחֲזֹר לוֹ הַמַּיִם וְיַשְׁקֶה תְּחִלָּה וְאַחַר כָּךְ יִפְתַּח. וְאַחֵר רוֹצֶה לְהַשְׁקוֹת תְּחִלָּה. כָּל הַמִּתְגַּבֵּר זָכָה. וּבוֹר הַקָּרוֹב לָאַמָּה מִתְמַלֵּא רִאשׁוֹן מִפְּנֵי דַּרְכֵי שָׁלוֹם:"],"Mishneh Torah, Oaths 3":["כָּל הַנִּשְׁבָּע שְׁבוּעָה מֵאַרְבַּע מִינֵי שְׁבוּעוֹת אֵלּוּ בְּאֹנֶס הֲרֵי זֶה פָּטוּר מִכְּלוּם. וְאֶחָד הַנִּשְׁבָּע מִתְּחִלָּתוֹ בְּאֹנֶס כְּמוֹ שֶׁבֵּאַרְנוּ. אוֹ שֶׁנִּשְׁבַּע וְנֶאֱנַס וְלֹא הִנִּיחוּהוּ לְקַיֵּם שְׁבוּעָתוֹ. אוֹ שֶׁהִשְׁבִּיעוֹ אַנָּס. לְפִיכָךְ נִשְׁבָּעִין לַחֲרָמִין וּלְהוֹרְגִין וּלְמוֹכְסִין:","בְּאֵי זֶה מוֹכֵס אָמְרוּ. בְּמוֹכֵס הָעוֹמֵד מֵאֵלָיו שֶׁלּוֹקֵחַ מָמוֹן שֶׁלֹּא בִּרְשׁוּת מֶלֶךְ הַמְּדִינָה. אוֹ שֶׁלּוֹקֵחַ בִּרְשׁוּת הַמֶּלֶךְ אֲבָל מוֹסִיף לְעַצְמוֹ עַל הַדָּבָר הַקָּצוּב כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת גְּזֵלָה:","וְצָרִיךְ הַנִּשְׁבָּע בְּאֹנֶס לִהְיוֹת כַּוָּנָתוֹ בְּלִבּוֹ בְּעֵת הַשְּׁבוּעָה לְדָבָר הַפּוֹטְרוֹ. וְאַף עַל פִּי שֶׁהַדְּבָרִים אֵלּוּ שֶׁבַּלֵּב אֵינָן דְּבָרִים. הוֹאִיל וְאֵינוֹ יָכוֹל לְהוֹצִיא בִּשְׂפָתָיו מִפְּנֵי הָאֹנֶס. הֲרֵי זֶה סוֹמֵךְ עַל דְּבָרִים שֶׁבְּלִבּוֹ:","כֵּיצַד. כְּגוֹן שֶׁנִּשְׁבַּע לְאַנָּס שֶׁלֹּא יֹאכַל בָּשָׂר סְתָם. וּבְלִבּוֹ שֶׁלֹּא יֹאכַל הַיּוֹם אוֹ שֶׁלֹּא יֹאכַל בְּשַׂר חֲזִיר הֲרֵי זֶה מֻתָּר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","וְכֵן שְׁבוּעַת הֲבַאי וְשֶׁל שְׁגָגוֹת פָּטוּר עֲלֵיהֶן. שְׁבוּעַת (שֶׁל) הֲבַאי כֵּיצַד. כְּגוֹן שֶׁרָאָה חֵילוֹת גְּדוֹלוֹת וְחוֹמָה גְּבוֹהָה וְנִשְׁבַּע שֶׁרָאִיתִי חֵיל פְּלוֹנִי הַמֶּלֶךְ וְהֵם כְּיוֹצְאֵי מִצְרַיִם. וְשֶׁרָאִיתִי חוֹמַת עִיר פְּלוֹנִית גְּבוֹהָה עַד לָרָקִיעַ וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ. שֶׁזֶּה לֹא גָּמַר בְּלִבּוֹ שֶׁהַדָּבָר כָּךְ בְּלֹא פָּחוֹת וְלֹא יוֹתֵר וְלֹא נִתְכַּוֵּן אֶלָּא לְסַפֵּר אֶת גֹּבַהּ הַחוֹמָה אוֹ רֹב הָעָם:","שְׁבוּעָה שֶׁל שְׁגָגוֹת כֵּיצַד. אִם שְׁבוּעַת הָעֵדוּת אוֹ הַפִּקָּדוֹן הִיא כְּגוֹן שֶׁשָּׁגַג בְּפִקָּדוֹן וּבְעֵדוּת שֶׁהוּא פָּטוּר מִכְּלוּם כְּמוֹ שֶּׁבֵּאַרְנוּ. וְאִם שְׁבוּעַת שָׁוְא הִיא כְּגוֹן שֶׁנִּשְׁבַּע שֶׁלֹּא יִלְבַּשׁ תְּפִלִּין וְלֹא יָדַע שֶׁהַתְּפִלִּין מִצְוָה. וְאִם שְׁבוּעַת שֶׁקֶר הִיא כְּגוֹן שֶׁנִּשְׁבַּע שֶׁלֹּא אָכַל וְנִזְכַּר שֶׁאָכַל. אוֹ שֶׁנִּשְׁבַּע שֶׁלֹּא יֹאכַל וְשָׁכַח וְאָכַל. אוֹ שֶׁלֹּא תֵּהָנֶה אִשְׁתּוֹ לוֹ מִפְּנֵי שֶׁגָּנְבָה כִּיסוֹ אוֹ שֶׁהִכְּתָה אֶת בְּנוֹ וְנוֹדַע שֶׁלֹּא גָּנְבָה וְשֶׁלֹּא הִכְּתָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אִם כֵּן אֵי זֶהוּ שִׁגְגַת שְׁבוּעַת בִּטּוּי שֶׁחַיָּבִין עָלֶיהָ קָרְבַּן עוֹלֶה וְיוֹרֵד לְשֶׁעָבַר. כְּגוֹן שֶׁנִּשְׁבַּע שֶׁלֹּא אָכַל וְהוּא יוֹדֵעַ שֶׁאָכַל. וְשֶׁשְּׁבוּעַת שֶׁקֶר זוֹ שֶׁנִּשְׁבַּע אֲסוּרָה אֲבָל לֹא יָדַע שֶׁחַיָּבִין עָלֶיהָ קָרְבָּן. זוֹ הִיא הַשְּׁגָגָה שֶׁחַיָּבִין עָלֶיהָ קָרְבַּן עוֹלֶה וְיוֹרֵד בִּשְׁבוּעַת בִּטּוּי לְשֶׁעָבַר:","וְכֵיצַד הִיא הַשְּׁגָגָה שֶׁחַיָּבִין עָלֶיהָ קָרְבָּן לְהַבָּא. כְּגוֹן שֶׁנִּשְׁבַּע שֶׁלֹּא יֹאכַל פַּת חִטִּים וְשָׁגַג וְדִמָּה שֶׁנִּשְׁבַּע שֶׁיֹּאכַל פַּת חִטִּים וַאֲכָלָהּ שֶׁזֶּה נֶעֶלְמָה מִמֶּנּוּ הַשְּׁבוּעָה הֵיאַךְ הָיְתָה וַהֲרֵי הוּא זוֹכֵר אֶת הַחֵפֶץ שֶׁנִּשְׁבַּע עָלָיו. זוֹ הִיא שִׁגְגַת שְׁבוּעַת בִּטּוּי לְהַבָּא שֶׁחַיָּבִין עָלֶיהָ קָרְבָּן:","אֲבָל אִם נִשְׁבַּע שֶׁלֹּא יֹאכַל פַּת חִטִּים וְאָכַל פַּת חִטִּים עַל דַּעַת שֶׁהוּא פַּת שְׂעוֹרִים הֲרֵי זֶה אָנוּס וּפָטוּר. שֶׁהֲרֵי לֹא נֶעֶלְמָה מִמֶּנּוּ שְׁבוּעָה וְלֹא נֶעְלָם מִמֶּנּוּ אֶלָּא חֵפֶץ שֶׁנִּשְׁבַּע עָלָיו:","נֶעֶלְמָה מִמֶּנּוּ שְׁבוּעָה הֵיאַךְ הָיְתָה וְנֶעְלַם מִמֶּנּוּ חֵפֶץ שֶׁנִּשְׁבַּע עָלָיו הֲרֵי זֶה פָּטוּר מִן הַקָּרְבָּן. כֵּיצַד. כְּגוֹן שֶׁנִּשְׁבַּע שֶׁלֹּא לֶאֱכל פַּת חִטִּים וְדִמָּה שֶׁנִּשְׁבַּע שֶׁיֹּאכַל פַּת חִטִּים וְאָכַל פַּת חִטִּים עַל דַּעַת שֶׁהוּא פַּת שְׂעוֹרִים שֶׁהֲרֵי הֶעְלֵם שְׁבוּעָה וְחֵפֶץ בְּיָדוֹ הֲרֵי זֶה כְּאָנוּס וּפָטוּר:","נִשְׁבַּע עַל כִּכָּר שֶׁלֹּא יֹאכְלֶנּוּ וְנִצְטַעֵר עָלָיו וַאֲכָלוֹ מִפְּנֵי הַצַּעַר וְהוּא שׁוֹגֵג שֶׁהֲרֵי דִּמָּה שֶׁמֻּתָּר לוֹ לְאָכְלוֹ מִפְּנֵי הַצַּעַר הֲרֵי זֶה פָּטוּר מִן הַקָּרְבָּן לְפִי שֶׁאֵינוֹ שָׁב מִידִיעָתוֹ אֶלָּא יָדַע שֶׁאֲסוּרָה הִיא וַאֲכָלָהּ בְּטָעוּת:"],"Mishneh Torah, Offerings for Unintentional Transgressions 1":["כָּל הָעוֹבֵר בִּשְׁגָגָה עַל אַחַת מִמִּצְוֹת לֹא תַּעֲשֶׂה שֶׁיֵּשׁ בָּהּ מַעֲשֶׂה שֶׁחַיָּבִין עָלֶיהָ כָּרֵת. הֲרֵי זֶה חַיָּב לְהַקְרִיב קָרְבַּן חַטָּאת. וּמִצְוַת עֲשֵׂה שֶׁיַּקְרִיב חַטָּאתוֹ עַל שִׁגְגָתוֹ:","וְכָל עֲבֵרָה שֶׁחַיָּבִין עַל זְדוֹנָהּ כָּרֵת חַיָּבִין עַל שִׁגְגָתָהּ חַטָּאת חוּץ מִשָּׁלֹשׁ עֲבֵרוֹת. מְגַדֵּף. וּמְבַטֵּל מִילָה. וְקָרְבַּן פֶּסַח. הַפֶּסַח וְהַמִּילָה מִפְּנֵי שֶׁהֵן מִצְוַת עֲשֵׂה וְחַטָּאת אֵין מְבִיאִין אֶלָּא עַל שִׁגְגַת לֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (ויקרא ד יג) \"אַחַת מִכָּל מִצְוֹת ה' אֲשֶׁר לֹא תֵעָשֶׂינָה\". וְהַמְגַדֵּף מִפְּנֵי שֶׁאֵין בּוֹ מַעֲשֶׂה וְנֶאֱמַר (במדבר טו כט) \"לָעוֹשֶׂה בִּשְׁגָגָה\" יָצָא מְגַדֵּף שֶׁאֵין בּוֹ מַעֲשֶׂה. לְפִיכָךְ הַמְקַבֵּל עֲבוֹדָה זָרָה בֵּאלוֹהַּ אַף עַל פִּי שֶׁהוּא חַיָּב כָּרֵת אִם הָיָה מֵזִיד נִסְקָל וְאִם קִבֵּל בִּשְׁגָגָה פָּטוּר מִן הַקָּרְבָּן לְפִי שֶׁלֹּא עָשָׂה מַעֲשֶׂה וְנֶאֱמַר (ויקרא ד כז) \"בַּעֲשֹׂתָהּ אַחַת\":","כָּל כְּרֵתוֹת שֶׁבַּתּוֹרָה חוּץ מִשָּׁלֹשׁ כְּרֵתוֹת שֶׁבֵּאַרְנוּ אִם עָבַר הַיָּחִיד עַל אַחַת מֵהֶן בִּשְׁגָגָה מֵבִיא חַטָּאת קְבוּעָה חוּץ מִטָּמֵא שֶׁאָכַל קֹדֶשׁ וְטָמֵא שֶׁנִּכְנַס לַמִּקְדָּשׁ שֶׁשְּׁנֵיהֶם אֵין מְבִיאִין חַטָּאת קְבוּעָה אֶלָּא קָרְבָּן עוֹלֶה וְיוֹרֵד כְּמוֹ שֶׁיִּתְבָּאֵר:","חַטָּאת קְבוּעָה הִיא הַבָּאָה מִן הַבְּהֵמָה בִּלְבַד וְקָרְבָּן עוֹלֶה וְיוֹרֵד הוּא קָרְבָּן שֶׁאֵינוֹ קָבוּעַ אֶלָּא אִם הָיָה עָשִׁיר מֵבִיא חַטַּאת בְּהֵמָה וְאִם הָיָה עָנִי מֵבִיא עוֹף אוֹ עֲשִׂירִית הָאֵיפָה כְּמוֹ שֶׁיִּתְבָּאֵר. נִמְצֵאתָ לָמֵד שֶׁכָּל הָעֲבֵרוֹת שֶׁהַיָּחִיד מֵבִיא עַל שִׁגְגָתָן חַטָּאת קְבוּעָה אַרְבָּעִים וְשָׁלֹשׁ. וְאֵלּוּ הֵן: א) הַבָּא עַל אִמּוֹ. ב) הַבָּא עַל אֵם אִשְׁתּוֹ. ג) הַבָּא עַל אֵם אִמָּהּ. ד) הַבָּא עַל אֵם אָבִיהָ. ה) הַבָּא עַל בִּתּוֹ. ו) הַבָּא עַל בַּת בִּתּוֹ. ז) הַבָּא עַל בַּת בְּנוֹ. ח) הַבָּא עַל בַּת אִשְׁתּוֹ. ט) הַבָּא עַל בַּת בִּתָּהּ. י) הַבָּא עַל בַּת בְּנָהּ. יא) הַבָּא עַל אֲחוֹתוֹ. יב) הַבָּא עַל אֲחוֹתוֹ שֶׁהִיא בַּת אֵשֶׁת אָבִיו. יג) הַבָּא עַל אֲחוֹת אָבִיו. יד) הַבָּא עַל אֲחוֹת אִמּוֹ. טו) הַבָּא עַל אֲחוֹת אִשְׁתּוֹ. טז) הַבָּא עַל אֵשֶׁת אָבִיו. יז) הַבָּא עַל אֵשֶׁת אֲחִי אָבִיו. יח) הַבָּא עַל אֵשֶׁת בְּנוֹ. יט) הַבָּא עַל אֵשֶׁת אָחִיו. כ) הַבָּא עַל אֵשֶׁת אִישׁ. כא) הַבָּא עַל הַנִּדָּה. כב) הַשּׁוֹכֵב עִם זָכָר. כג) הַבָּא עַל אָבִיו. כד) הַבָּא עַל אֲחִי אָבִיו. כה) הַשּׁוֹכֵב עִם בְּהֵמָה. כו) הָאִשָּׁה שֶׁמְּבִיאָהּ עָלֶיהָ אֶת הַבְּהֵמָה. נִמְצְאוּ כָּל כְּרֵתוֹת שֶׁבַּעֲרָיוֹת עֶשְׂרִים וְשֵׁשׁ. וּבִשְׁאָר הָעֲבֵרוֹת שְׁבַע עֶשְׂרֵה. וְאֵלּוּ הֵן: א) הָעוֹבֵד עֲבוֹדָה זָרָה בְּמַעֲשֶׂה. ב) הַנּוֹתֵן מִזַּרְעוֹ לַמּלֶךְ. ג) בַּעַל אוֹב. ד) בַּעַל יִדְּעוֹנִי בְּמַעֲשֶׂה. ה) הַמְחַלֵּל אֶת הַשַּׁבָּת. ו) הָעוֹשֶׂה מְלָאכָה בְּיוֹם הַכִּפּוּרִים. ז) הָאוֹכֵל וְשׁוֹתֶה בְּיוֹם הַכִּפּוּרִים. ח) הָאוֹכֵל נוֹתָר. ט) הָאוֹכֵל חָמֵץ בְּפֶסַח. י) הָאוֹכֵל חֵלֶב. יא) הָאוֹכֵל דָּם. יב) הָאוֹכֵל פִּגּוּל. יג) הַשּׁוֹחֵט קָדָשִׁים חוּץ לָעֲזָרָה. יד) הַמַּעֲלֶה קָרְבָּן חוּץ לָעֲזָרָה. טו) הַמְפַטֵּם אֶת שֶׁמֶן הַמִּשְׁחָה. טז) הַמְפַטֵּם אֶת הַקְּטֹרֶת. יז) הַסָּךְ בְּשֶׁמֶן הַמִּשְׁחָה. הֲרֵי אֵלּוּ אַרְבָּעִים וְשָׁלֹשׁ עֲבֵרוֹת שֶׁמְּבִיאִין עַל שִׁגְגָתָן חַטָּאת קְבוּעָה. וּמַה הוּא הַקָּרְבָּן שֶׁמֵּבִיא הַשּׁוֹגֵג בְּאַחַת מֵאֵלּוּ. אִם שָׁגַג בַּעֲבוֹדָה זָרָה מֵבִיא עֵז בַּת שְׁנָתָהּ לְחַטָּאת וְהִיא הָאֲמוּרָה בְּפָרָשַׁת שְׁלַח לְךָ בֵּין שֶׁהָיָה הַחוֹטֵא הֶדְיוֹט אוֹ מֶלֶךְ אוֹ כֹּהֵן גָּדוֹל אוֹ מְשׁוּחַ מִלְחָמָה הַכּל שָׁוִין בְּשִׁגְגַת עֲבוֹדָה זָרָה. אֲבָל אִם שָׁגַג בְּאַחַת מִשְּׁאָר אַרְבָּעִים וּשְׁתַּיִם אִם הָיָה הֶדְיוֹט מֵבִיא שְׂעִירַת עִזִּים אוֹ נְקֵבָה מִן הַכְּבָשִׂים וְזוֹ הִיא חַטָּאת שֶׁל אֶחָד מֵעַם הָאָרֶץ הָאֲמוּרָה בְּפָרָשַׁת וַיִּקְרָא. וְאִם הַמֶּלֶךְ הוּא שֶׁשָּׁגַג בְּאַחַת מֵהֶן מֵבִיא שְׂעִירַת עִזִּים לְחַטָּאת. וְאִם כֹּהֵן מָשׁוּחַ הוּא מֵבִיא פַּר בֶּן בָּקָר לְחַטָּאת וְהוּא נִשְׂרָף כְּמוֹ שֶׁנִּתְפָּרֵשׁ שָׁם:","אֶחָד יָחִיד שֶׁשָּׁגַג בְּאַחַת מֵאֵלּוּ אוֹ מְרֻבִּין שֶׁנֶּאֱמַר (במדבר טו כט) \"תּוֹרָה אַחַת תִּהְיֶה לָכֶם לָעשֶֹׁה בִּשְׁגָגָה\". כֵּיצַד. אַנְשֵׁי מְדִינָה שֶׁשָּׁגְגוּ וְדִמּוּ שֶׁהַיּוֹם חֹל וַהֲרֵי הוּא יוֹם הַכִּפּוּרִים וְכֻלָּן אָכְלוּ וְעָשׂוּ מְלָאכָה. כָּל אֶחָד מֵהֶן מֵבִיא שְׁתֵּי חַטָּאוֹת כְּבָשׂוֹת אוֹ שְׂעִירוֹת. וְכֵן אִם שָׁגְגוּ כֻּלָּן וְהִקְטִירוּ לַעֲבוֹדָה זָרָה כָּל אֶחָד וְאֶחָד מִן הָעוֹבְדִים מֵבִיא עֵז בַּת שְׁנָתָהּ לְחַטָּאת:"],"Mishneh Torah, Offerings for Unintentional Transgressions 7":["הַמִּשְׁתַחֲוְה לַעֲבוֹדָה זָרָה וְנִסֵּךְ וְקִטֵּר וְזִבֵּחַ בְּהֶעְלֵם אַחַת חַיָּב אַרְבַּע חַטָּאוֹת. וְכֵן אִם פִּעֵר עַצְמוֹ לִפְעוֹר וְזָרַק אֶבֶן לְמַרְקוּלִיס בְּהֶעְלֵם אַחַת. חַיָּב שְׁתַּיִם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה יְהֵא חַיָּב עַל כָּל עֲבוֹדָה וַעֲבוֹדָה. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהֵזִיד בַּעֲבוֹדָה זָרָה וְשָׁגַג בַּעֲבוֹדוֹת אֵלּוּ. אֲבָל אִם הֵזִיד בַּעֲבוֹדוֹת אֵלּוּ וְשָׁגַג בַּעֲבוֹדָה זָרָה אֵינוֹ חַיָּב אֶלָּא חַטָּאת אַחַת. כֵּיצַד. יָדַע שֶׁזּוֹ עֲבוֹדָה זָרָה וְשֶׁאָסוּר לְעָבְדָהּ אֲבָל לֹא יָדַע שֶׁהַהִשְׁתַּחֲוָיָה וְהַנִּסּוּךְ עֲבֵרָה וְהִשְׁתַּחֲוָה וְנִסֵּךְ חַיָּב שְׁתַּיִם. יָדַע שֶׁאֵלּוּ עֲבוֹדוֹת הֵן וְאָסוּר לַעֲבֹד בָּהֶן לְאֵל אַחֵר וְלֹא יָדַע שֶׁזּוֹ עֲבוֹדָה זָרָה לְפִי שֶׁלֹּא הָיְתָה שֶׁל כֶּסֶף וְזָהָב וְעָלָה עַל דַּעְתּוֹ שֶׁאֵין קְרוּיִין עֲבוֹדָה זָרָה אֶלָּא שֶׁל כֶּסֶף וְזָהָב וַעֲבָדָהּ בְּכָל הָעֲבוֹדוֹת אֵינוֹ חַיָּב אֶלָּא חַטָּאת אַחַת:","כְּלָל גָּדוֹל אָמְרוּ בְּשַׁבָּת כָּל הַשּׁוֹכֵחַ עִקַּר שַׁבָּת וְשָׁכַח שֶׁנִּצְטַוּוּ יִשְׂרָאֵל עַל הַשַּׁבָּת. אוֹ שֶׁנִּשְׁבָּה וְהוּא קָטָן לְבֵין הָעַכּוּ\"ם אוֹ נִתְגַּיֵּר קָטָן וְהוּא בֵּין הָעַכּוּ\"ם. אַף עַל פִּי שֶׁעָשָׂה מְלָאכוֹת הַרְבֵּה בְּשַׁבָּתוֹת הַרְבֵּה אֵינוֹ חַיָּב אֶלָּא חַטָּאת אַחַת שֶׁהַכּל שְׁגָגָה אַחַת הִיא. וְכֵן חַיָּב חַטָּאת אַחַת עַל כָּל חֵלֶב שֶׁאָכַל וְחַטָּאת אַחַת עַל דָּם שֶׁאָכַל. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה בַּעֲבוֹדוֹת אֵלּוּ. וְכָל הַיּוֹדֵעַ עִקַּר שַׁבָּת אֲבָל שָׁכַח שֶׁהַיּוֹם שַׁבָּת וְדִמָּה שֶׁהוּא חֹל אַף עַל פִּי שֶׁעָשָׂה בּוֹ מְלָאכוֹת הַרְבֵּה חַיָּב חַטָּאת אַחַת עַל הַיּוֹם כֻּלּוֹ וְכֵן חַטָּאת עַל כָּל שַׁבָּת וְשַׁבָּת שֶׁשָּׁגַג בּוֹ:","וְכָל הַיּוֹדֵעַ שֶׁהַיּוֹם שַׁבָּת וְשָׁגַג בִּמְלָאכוֹת וְלֹא יָדַע שֶׁמְּלָאכוֹת אֵלּוּ אֲסוּרוֹת אוֹ שֶׁיָּדַע שֶׁהֵן אֲסוּרוֹת וְלֹא יָדַע שֶׁחַיָּבִין עֲלֵיהֶן כָּרֵת וְעָשָׂה מְלָאכוֹת הַרְבֵּה. חַיָּב חַטָּאת עַל כָּל אַב מְלָאכָה וּמְלָאכָה. אֲפִלּוּ עָשָׂה הָאַרְבָּעִים חָסֵר אַחַת בְּהֶעְלֵם אַחַת מֵבִיא שְׁלֹשִׁים וְתֵשַׁע חַטָּאוֹת:","שָׁכַח שֶׁהַיּוֹם שַׁבָּת וְשָׁגַג אַף בִּמְלָאכוֹת וְלֹא יָדַע שֶׁמְּלָאכוֹת אֵלּוּ אֲסוּרוֹת אֵינוֹ חַיָּב אֶלָּא חַטָּאת אַחַת:","הָעוֹשֶׂה אָב וְתוֹלְדוֹתָיו בְּהֶעְלֵם אַחַת אֵינוֹ חַיָּב אֶלָּא חַטָּאת אַחַת. וְאֵין צָרִיךְ לוֹמַר הָעוֹשֶׂה תּוֹלָדוֹת הַרְבֵּה שֶׁל אָב אֶחָד שֶׁאֵינוֹ חַיָּב אֶלָּא חַטָּאת אַחַת:","עָשָׂה תּוֹלָדָה שֶׁל אָב זֶה וְתוֹלָדָה שֶׁל אָב זֶה בְּהֶעְלֵם אַחַת. יֵרָאֶה לִי שֶׁהוּא חַיָּב שְׁתֵּי חַטָּאוֹת:","עָשָׂה מְלָאכוֹת הַרְבֵּה מֵעֵין מְלָאכָה אַחַת. כְּגוֹן שֶׁזָּרַע וְהִבְרִיךְ וְהִרְכִּיב בְּהֶעְלֵם אַחַת אֵינוֹ חַיָּב אֶלָּא חַטָּאת אַחַת. וּכְבָר נִתְבָּאֵר בְּהִלְכוֹת שַׁבָּת הָאָבוֹת וְהַתּוֹלָדוֹת וְהַמְּלָאכוֹת שֶׁהֵן מֵעֵין אָבוֹת:","עָשָׂה מְלָאכוֹת הַרְבֵּה מֵעֵין מְלָאכָה אַחַת בְּשַׁבָּתוֹת הַרְבֵּה בֵּין בִּזְדוֹן שַׁבּתַ וְשִׁגְגַת מְלָאכוֹת בֵּין בְּשִׁגְגַת שַׁבָּת וּזְדוֹן מְלָאכוֹת חַיָּב עַל כָּל מְלָאכָה וּמְלָאכָה. כֵּיצַד. יָדַע שֶׁהַיּוֹם שַׁבָּת וְזָרַע בּוֹ מִפְּנֵי שֶׁלֹּא יָדַע שֶׁהַזְּרִיעָה מְלָאכָה. וְכֵן בְּשַׁבָּת שְׁנִיָּה יָדַע שֶׁהוּא שַׁבָּת וְנָטַע בָּהּ מִפְּנֵי שֶׁלֹּא יָדַע שֶׁהַנְּטִיעָה אֲסוּרָה מִשּׁוּם מְלָאכָה. וְכֵן בְּשַׁבָּת שְׁלִישִׁית הִבְרִיךְ מִפְּנֵי שֶׁלֹּא יָדַע שֶׁהַהַבְרָכָה מְלָאכָה. חַיָּב עַל כָּל אַחַת וְאַחַת אַף עַל פִּי שֶׁהִיא מֵעֵין מְלָאכָה אַחַת. מִפְּנֵי שֶׁהַשַּׁבָּתוֹת כְּגוּפִין מֻחְלָקִין:","שָׁגַג שֶׁהַיּוֹם שַׁבָּת וְזָרַע בּוֹ וְהוּא יוֹדֵעַ שֶׁהַזְּרִיעָה מְלָאכָה. וְכֵן בְּשַׁבָּת שְׁנִיָּה שָׁכַח שֶׁהוּא שַׁבָּת וְנָטַע בּוֹ וְהוּא יוֹדֵעַ שֶׁהַנְּטִיעָה מְלָאכָה. וְכֵן בַּשְּׁלִישִׁית שָׁכַח שֶׁהוּא שַׁבָּת וְהִבְרִיךְ אַף עַל פִּי שֶׁיּוֹדֵעַ שֶׁהַהַבְרָכָה מְלָאכָה. הֲרֵי זֶה חַיָּב עַל כָּל אַחַת וְאַחַת. שֶׁהַיָּמִים שֶׁבֵּין שַׁבָּת לְשַׁבָּת הֲרֵי הֵן כִּידִיעָה אַחַת לְחַלֵּק:","מִי שֶׁקָּצַר וְטָחַן כִּגְרוֹגֶרֶת בְּשִׁגְגַת שַׁבָּת וּזְדוֹן מְלָאכוֹת שֶׁאֵינוֹ חַיָּב אֶלָּא חַטָּאת אַחַת. וְחָזַר וְקָצַר וְטָחַן כִּגְרוֹגֶרֶת בִּזְדוֹן שַׁבָּת וְשִׁגְגַת מְלָאכוֹת שֶׁהוּא חַיָּב עַל כָּל מְלָאכָה וּמְלָאכָה. וְנוֹדַע לוֹ עַל קְצִירָה שֶׁל שִׁגְגַת שַׁבָּת וּזְדוֹן מְלָאכוֹת. קְצִירָה גּוֹרֶרֶת קְצִירָה וּטְחִינָה גּוֹרֶרֶת טְחִינָה וּכְאִלּוּ עָשָׂה אַרְבַּעְתָּן בְּשִׁגְגַת שַׁבָּת וּזְדוֹן מְלָאכוֹת שֶׁאֵינוֹ חַיָּב אֶלָּא חַטָּאת אַחַת. וְכֵיוָן שֶׁהִקְרִיב חַטָּאת זוֹ נִתְכַּפֵּר לוֹ עַל הַכּל. וּכְשֶׁיְּדָעֵם אַחַר כֵּן אֵינוֹ צָרִיךְ לְהָבִיא חַטָּאת אַחֶרֶת. אֲבָל אִם נוֹדַע לוֹ תְּחִלָּה עַל קְצִירָהּ שֶׁל זְדוֹן שַׁבָּת וְשִׁגְגַת מְלָאכוֹת וְהִקְרִיב חַטָּאת. נִתְכַּפֵּר לוֹ עַל זוֹ הַקְּצִירָה שֶׁנּוֹדַע לוֹ עָלֶיהָ וְעַל הַקְּצִירָה וְהַטְּחִינָה שֶׁל שִׁגְגַת שַׁבָּת וּזְדוֹן מְלָאכוֹת. מִפְּנֵי שֶׁשְּׁנֵיהֶן כִּמְלָאכָה אַחַת וְנִגְרְרָה קְצִירָה וּטְחִינָה עִם הַקְּצִירָה וְתִשָּׁאֵר הַטְּחִינָה שֶׁל זְדוֹן שַׁבָּת עַד שֶׁיִּוָּדַע לוֹ עָלֶיהָ וְיָבִיא חַטָּאת שְׁנִיָּה. קָצַר כַּחֲצִי גְּרוֹגֶרֶת בְּשִׁגְגַת שַׁבָּת וּזְדוֹן מְלָאכוֹת וְחָזַר וְקָצַר כַּחֲצִי גְּרוֹגֶרֶת בִּזְדוֹן שַׁבָּת וְשִׁגְגַת מְלָאכוֹת הֲרֵי אֵלּוּ מִצְטָרְפִין. קְצִירָהּ גּוֹרֶרֶת קְצִירָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה בִּשְׁאָר מְלָאכוֹת:","הַמִּתְכַּוֵּן לַחְתֹּךְ אֶת הַתָּלוּשׁ וְחָתַךְ אֶת הַמְחֻבָּר אַף עַל פִּי שֶׁנִּתְכַּוֵּן לַחֲתִיכָה הוֹאִיל וְלֹא עָשָׂה מַחְשַׁבְתּוֹ פָּטוּר מִן הַחַטָּאת שֶׁזֶּה כְּמִתְעַסֵּק וְלֹא אָסְרָה תּוֹרָה אֶלָּא מְלֶאכֶת מַחֲשֶׁבֶת כְּמוֹ שֶׁבֵּאַרְנוּ כַּמָּה פְּעָמִים:","הַחוֹתֶה גֶּחָלִים בְּשַׁבָּת שֶׁהוּא מְכַבֶּה אֶת הָעֶלְיוֹנוֹת וּמַדְלִיק אֶת הַתַּחְתּוֹנוֹת אִם נִתְכַּוֵּן לְכַבּוֹת וּלְהַבְעִיר חַיָּב שְׁתַּיִם. חָתָה גֶּחָלִים לְהִתְחַמֵּם מֵהֶם וְהֻבְעֲרוּ מֵאֲלֵיהֶן חַיָּב שְׁתַּיִם מִפְּנֵי שֶׁמְּלָאכָה שֶׁאֵינָהּ צְרִיכָה לְגוּפָהּ חַיָּב עָלֶיהָ כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת שַׁבָּת. וּכְשֵׁם שֶׁחַיָּבִין עַל זְדוֹנָהּ כָּרֵת כָּךְ חַיָּב עַל שִׁגְגָתָהּ קָרְבַּן חַטָּאת:"],"Mishneh Torah, Other Sources of Defilement 10":["כָּל הַמִּתְטַמֵּא בְּאָב מֵאֲבוֹת הַטֻּמְאוֹת בֵּין אָדָם בֵּין כֵּלִים הֲרֵי הוּא רִאשׁוֹן לְטֻמְאָה כְּמוֹ שֶׁבֵּאַרְנוּ עַד שֶׁיִּטְבּל. טָבַל הֲרֵי הוּא כְּשֵׁנִי לְטֻמְאָה עַד שֶׁיַּעֲרִיב שִׁמְשׁוֹ שֶׁנֶּאֱמַר (ויקרא יא לב) \"בַּמַּיִם יוּבָא וְטָמֵא עַד הָעֶרֶב וְטָהֵר\" הַכָּתוּב קָרָא לִטְבוּל יוֹם טָמֵא:","אֶחָד טְבוּל יוֹם מִטֻּמְאָה חֲמוּרָה כְּגוֹן שֶׁטָּבַל מִזִּיבוּת מִטֻּמְאַת מֵת וְצָרַעַת וְאֶחָד טְבוּל יוֹם מִטֻּמְאַת שֶׁרֶץ וְכַיּוֹצֵא בּוֹ כָּל הַטָּעוּן הַעֲרֵב שֶׁמֶשׁ בֵּין אָדָם בֵּין כֵּלִים בֵּין מִדִּבְרֵי תּוֹרָה בֵּין מִדִּבְרֵי סוֹפְרִים הֲרֵי הוּא כְּשֵׁנִי לְטֻמְאָה עַד שֶׁיַּעֲרִיב שִׁמְשׁוֹ:","טְבוּל יוֹם פּוֹסֵל אָכֳלֵי תְּרוּמָה וּמַשְׁקֵה תְּרוּמָה וְאָכֳלֵי הֶקְדֵּשׁ וּמַשְׁקֵה הֶקְדֵּשׁ פּוֹסֵל הַכּל. כֵּיצַד. טְבוּל יוֹם שֶׁנָּגַע בָּאֳכָלִין שֶׁל תְּרוּמָה עֲשָׂאָן שְׁלִישִׁי לְטֻמְאָה מִפְּנֵי שֶׁהוּא שֵׁנִי וְכֵן אִם נָגַע בְּמַשְׁקִין שֶׁל תְּרוּמָה טְמֵאִין וַהֲרֵי הֵן שְׁלִישִׁי לְטֻמְאָה. נָגַע טְבוּל יוֹם בְּמַשְׁקִין שֶׁל קֹדֶשׁ טִמְּאָן וַהֲרֵי הֵן רְבִיעִי לְטֻמְאָה וְכֵן אִם נָגַע בְּאָכְלֵי הֶקְדֵּשׁ עֲשָׂאָן רְבִיעִי. אֲבָל אִם נָגַע בָּאֳכָלִין חֻלִּין וּמַשְׁקֵה חֻלִּין הֲרֵי הֵן טְהוֹרִין. וְדִין מְחֻסַּר כִּפּוּרִים וּטְבוּל יוֹם בִּנְגִיעַת הַקֹּדֶשׁ אֶחָד הוּא. הֲרֵי נִתְבָּאֵר לְךָ מִכָּל אֵלּוּ הַדְּבָרִים שֶׁאֵין שֵׁם מַשְׁקִין שְׁנִיּוֹת לְעוֹלָם אֶלָּא הַמַּשְׁקִין תְּחִלָּה לְעוֹלָם חוּץ מִמַּשְׁקִין שֶׁנָּגַע בָּהֶן טְבוּל יוֹם שֶׁהֵן שְׁלִישִׁי אִם הָיוּ תְּרוּמָה אוֹ רְבִיעִי אִם הָיוּ קֹדֶשׁ:","כָּל הַמְטַמְּאִין בֵּין חֲמוּרִין בֵּין קַלִּין מַשְׁקִין הַיּוֹצְאִין מֵהֶן כְּגוֹן רֻקָּן וּמֵימֵי רַגְלֵיהֶן הֲרֵי הֵן כְּמַשְׁקִין שֶׁנָּגְעוּ בָּהֶן אֵלּוּ וְאֵלּוּ רִאשׁוֹן לְטֻמְאָה כְּמוֹ שֶׁבֵּאַרְנוּ חוּץ מִזָּב וַחֲבֵרָיו שֶׁמַּשְׁקִין הַיּוֹצְאִין מֵהֶן אַב טֻמְאָה וּמַשְׁקִין שֶׁהַזָּב וַחֲבֵרָיו נוֹגְעִין בָּהֶן תְּחִלָּה. אֲפִלּוּ אוֹכֵל אֳכָלִין טְמֵאִין אוֹ שׁוֹתֶה מַשְׁקִין טְמֵאִין הַמַּשְׁקִין הַיּוֹצְאִין מִמֶּנּוּ קֹדֶם שֶׁיִּטְבּל כְּמוֹ הַמַּשְׁקִין שֶׁנָּגַע בָּהֶן שֶׁהֵן תְּחִלָּה. וְכֵן טְבוּל יוֹם מַשְׁקִין הַיּוֹצְאִין מִמֶּנּוּ כְּמַשְׁקִין שֶׁהוּא נוֹגֵעַ בָּהֶן שֶׁאֵין מְטַמְּאִין אֲחֵרִים כְּלָל אֶלָּא אִם נָגַע בְּמַשְׁקֵה חֻלִּין הֲרֵי הֵן טְהוֹרִין וְאִם נָגַע בְּמַשְׁקֵה תְּרוּמָה הֲרֵי הֵן שְׁלִישִׁי וְאִם נָגַע בְּמַשְׁקֵה קֹדֶשׁ הֲרֵי הֵן רְבִיעִי:","וְעַתָּה יִתְבָּאֵר לְךָ שֶׁאֵין שְׁלִישִׁי שֶׁבִּתְרוּמָה וְלֹא רְבִיעִי שֶׁבְּקֹדֶשׁ מְטַמֵּא מַשְׁקֶה אַחֵר אוֹ אֹכֶל אַחֵר. וְאֵין צָרִיךְ לוֹמַר שֶׁאֵין מְטַמְּאִין כֵּלִים. לְפִיכָךְ קְדֵרָה שֶׁמְּלֵאָה מַשְׁקִין וְנָגַע בָּהּ טְבוּל יוֹם אִם הָיָה מַשְׁקֵה חֻלִּין הַכּל טָהוֹר. וְאִם הָיָה מַשְׁקֵה תְּרוּמָה הַמַּשְׁקִין פְּסוּלִין וְהַקְּדֵרָה טְהוֹרָה. וְאִם הָיוּ יָדָיו טְמֵאוֹת הַמַּשְׁקֶה טָמֵא בֵּין מַשְׁקֵה תְּרוּמָה בֵּין מַשְׁקֵה חֻלִּין. וְזֶה חֹמֶר בְּיָדַיִם מִבִּטְבוּל יוֹם. וְחֹמֶר בִּטְבוּל יוֹם מִבְּיָדַיִם טְמֵאוֹת שֶׁסָּפֵק טְבוּל יוֹם פּוֹסֵל מִסָּפֵק וְסָפֵק הַיָּדַיִם טָהוֹר כְּמוֹ שֶׁיִּתְבָּאֵר:","אֶחָד טָהוֹר שֶׁהָיוּ יָדָיו טְמֵאוֹת אוֹ טְבוּל יוֹם שֶׁיָּדָיו טְמֵאוֹת הֲרֵי זֶה מְטַמֵּא מַשְׁקֵה חֻלִּין וְעוֹשֶׂה אוֹתָן תְּחִלָּה לְטַמֵּא אֳכָלִין וּמַשְׁקִין כְּמוֹ שֶׁבֵּאַרְנוּ. וּמֵאַחַר שֶׁמַּשְׁקֶה שֶׁיָּצָא מִטְּבוּל יוֹם כְּמַשְׁקִין שֶׁנָּגַע בָּהֶן. טְבוּל יוֹם שֶׁנָּפַל מֵרֻקּוֹ אוֹ מֵימֵי רַגְלָיו עַל כִּכָּר שֶׁל תְּרוּמָה הֲרֵי זֶה טָהוֹר מִפְּנֵי שֶׁהֵן כְּמַשְׁקִין שֶׁנָּגַע בָּהֶן:","מִכָּל אֵלּוּ הַדְּבָרִים שֶׁהִקְדַּמְנוּ לְבָאֲרָם אַתָּה לָמֵד שֶׁהָאָדָם יִהְיֶה אָב לְטֻמְאָה וְיִהְיֶה רִאשׁוֹן לְטֻמְאָה מִדִּבְרֵי תּוֹרָה. וּלְעוֹלָם לֹא יִהְיֶה הָאָדָם שֵׁנִי אֶלָּא מִדִּבְרֵי סוֹפְרִים וְהוּא הָאוֹכֵל אֳכָלִין טְמֵאִים אוֹ הַשּׁוֹתֶה מַשְׁקִין טְמֵאִין אוֹ הַבָּא רֹאשׁוֹ וְרֻבּוֹ בְּמַיִם שְׁאוּבִין שֶׁכָּל אֵלּוּ כְּשֵׁנִי לְטֻמְאָה מִדִּבְרֵיהֶם. וְכֵן שְׁאָר כָּל הַכֵּלִים חוּץ מִכְּלֵי חֶרֶס יִהְיוּ אַב טֻמְאָה וְיִהְיוּ רִאשׁוֹן לְטֻמְאָה מִדִּבְרֵי תּוֹרָה. וְלֹא יִהְיֶה הַכְּלִי לְעוֹלָם שֵׁנִי לְטֻמְאָה אֶלָּא מִדִּבְרֵי סוֹפְרִים שֶׁאִם יִטְמָא בְּמַשְׁקִין טְמֵאִים יִהְיֶה שֵׁנִי מִדִּבְרֵיהֶן כְּמוֹ שֶׁבֵּאַרְנוּ:","כְּבָר בֵּאַרְנוּ שֶׁכְּלִי חֶרֶס לֹא יִהְיֶה אַב טֻמְאָה לְעוֹלָם לֹא מִדִּבְרֵי תּוֹרָה וְלֹא מִדִּבְרֵי סוֹפְרִים. וְיִהְיֶה רִאשׁוֹן לְטֻמְאָה מִדִּבְרֵי תּוֹרָה וְשֵׁנִי מִדִּבְרֵיהֶן אִם נִטְמָא בְּמַשְׁקִין כִּשְׁאָר הַכֵּלִים. וְלֹא יִהְיֶה הָאָדָם וְלֹא הַכֵּלִים שְׁלִישִׁי וְלֹא רְבִיעִי לְעוֹלָם לֹא מִדִּבְרֵי תּוֹרָה וְלֹא מִדִּבְרֵי סוֹפְרִים:","הָאֳכָלִים לֹא יִהְיוּ אַב טֻמְאָה לְעוֹלָם לֹא מִדִּבְרֵי תּוֹרָה וְלֹא מִדִּבְרֵיהֶם. וְיִהְיוּ רִאשׁוֹן וְשֵׁנִי מִדִּבְרֵי תּוֹרָה שֶׁהָאָדָם אוֹ הַכְּלִי שֶׁהוּא רִאשׁוֹן לְטֻמְאָה אִם נָגַע בְּאֹכֶל עֲשָׂאוּהוּ שֵׁנִי וְהָאֳכָלִין יִהְיוּ שְׁלִישִׁי וּרְבִיעִי לְטֻמְאָה מִדִּבְרֵיהֶן בִּלְבַד:","הַמַּשְׁקִין יִהְיוּ אַב טֻמְאָה מִדִּבְרֵי תּוֹרָה. כְּגוֹן מֵי חַטָּאת וְרֹק הַזָּב וּמֵימֵי רַגְלָיו. וְיִהְיוּ רִאשׁוֹן לְטֻמְאָה מִדִּבְרֵי תּוֹרָה כְּגוֹן שֶׁנָּגְעוּ בְּאָב מֵאֲבוֹת הַטֻּמְאוֹת. וְכֵן אִם נָגְעוּ הַמַּשְׁקִין בִּוְלַד הַטֻּמְאָה בֵּין אָדָם בֵּין כֵּלִים נִטְמְאוּ מִדִּבְרֵי תּוֹרָה וַהֲרֵי הֵן כָּרִאשׁוֹן לְטֻמְאָה לְטַמֵּא אֲחֵרִים מִדִּבְרֵיהֶן. וְכֵן אִם נָגְעוּ בְּשֵׁנִי בֵּין אָדָם בֵּין כֵּלִים בֵּין בָּאֳכָלִין נַעֲשׂוּ רִאשׁוֹן לְטַמֵּא אֲחֵרִים מִדִּבְרֵיהֶם כְּמוֹ שֶׁבֵּאַרְנוּ. וְיִהְיוּ הַמַּשְׁקִין שְׁלִישִׁי וּרְבִיעִי מִדִּבְרֵיהֶם. כֵּיצַד. אִם נָגַע טְבוּל יוֹם בְּמַשְׁקֵה תְּרוּמָה עֲשָׂאָהוּ שְׁלִישִׁי וְאִם נָגַע בְּמַשְׁקֵה קֹדֶשׁ עֲשָׂאָהוּ רְבִיעִי. וְאֵין אַתָּה מוֹצֵא מַשְׁקִין שְׁנִיּוֹת לְעוֹלָם וְלֹא מַשְׁקֶה שֶׁאֵינוֹ תְּחִלָּה חוּץ מִמַּשְׁקֵה טְבוּל יוֹם אוֹ מְחֻסַּר כִּפּוּרִים בְּקֹדֶשׁ כְּמוֹ שֶׁבֵּאַרְנוּ שֶׁהוּא פּוֹסֵל מִדִּבְרֵיהֶם וְאֵינוֹ מְטַמֵּא:"],"Mishneh Torah, Other Sources of Defilement 3":["נִּבְלַת הָעוֹף הַטָּהוֹר מְטַמָּא מִן הַתּוֹרָה. מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזֶּה שֶׁנֶּאֱמַר (ויקרא יז טו) \"וְכָל נֶפֶשׁ אֲשֶׁר תֹּאכַל נְבֵלָה וּטְרֵפָה בָּאֶזְרָח וּבַגֵּר וְכִבֶּס בְּגָדָיו וְרָחַץ בַּמַּיִם\" אֵינוֹ מְדַבֵּר אֶלָּא בְּאוֹכֵל נִבְלַת הָעוֹף הַטָּהוֹר בִּלְבַד שֶׁהוּא אָסוּר מִשּׁוּם נְבֵלָה וּטְרֵפָה. וְכֵיצַד הִיא טֻמְאָתָהּ. אֵינָהּ מְטַמְּאָה לֹא בְּמַגָּע וְלֹא בְּמַשָּׂא וְלֹא כְּשֶׁהִיא בְּתוֹךְ הַפֶּה אֶלָּא בְּתוֹךְ בֵּית הַבְּלִיעָה. שֶׁנֶּאֱמַר וְכָל נֶפֶשׁ אֲשֶׁר תֹּאכַל אֵינָהּ מְטַמְּאָה אֶלָּא כְּשֶׁהִיא בְּבֵית הַנֶּפֶשׁ. וְזֶה שֶׁנֶּאֱמַר תֹּאכַל לָתֵת שִׁעוּר לְטֻמְאָתָהּ כְּשִׁעוּר אֲכִילָה שֶׁהוּא כְּזַיִת. וַהֲרֵי נֶאֱמַר בָּהּ וְכִבֶּס בְּגָדָיו מְלַמֵּד שֶׁהַמִּתְטַמֵּא בָּהּ מְטַמֵּא בְּגָדָיו עַד שֶׁיִּפְרשׁ מִמְּטַמְּאָיו כְּמוֹ שֶׁבֵּאַרְנוּ. כֵּיצַד. הַבּוֹלֵעַ כְּזַיִת מִנִּבְלַת הָעוֹף הַטָּהוֹר וְנָגַע בְּכֵלִים בִּשְׁעַת בְּלִיעָתוֹ טְמֵאִים וְנַעֲשׂוּ רִאשׁוֹן לְטֻמְאָה. הָיָה נוֹגֵעַ בְּאָדָם וּבִכְלֵי חֶרֶס בִּשְׁעַת בְּלִיעָתוֹ לֹא טִמְּאָן כְּמוֹ שֶׁבֵּאַרְנוּ בִּשְׁאָר אֲבוֹת הַטֻּמְאוֹת. וְאַחַר שֶׁבָּלַע אֵינוֹ מְטַמֵּא שְׁאָר כֵּלִים שֶׁהֲרֵי הוּא כִּכְלִי רִאשׁוֹן לְטֻמְאָה אַחַר שֶׁפֵּרֵשׁ מִמְּטַמְּאָיו שֶׁאַף עַל פִּי שֶׁהוּא טָעוּן טְבִילָה וְהַעֲרֵב שֶׁמֶשׁ אֵינוֹ מְטַמֵּא כֵּלִים:","אֵין נִבְלַת הָעוֹף הַטָּהוֹר צְרִיכָה מַחֲשָׁבָה לְטַמֵּא טֻמְאָה זוֹ הַחֲמוּרָה אֶלָּא כֵּיוָן שֶׁבָּלַע מִמֶּנָּה כְּזַיִת מִכָּל מָקוֹם הֲרֵי זוֹ מְטַמְּאָה בְּבֵית הַבְּלִיעָה. חָשַׁב עָלֶיהָ לַאֲכִילָה הֲרֵי זוֹ מְטַמְּאָה טֻמְאַת אֳכָלִין וַהֲרֵי הִיא כְּאֹכֶל רִאשׁוֹן לְטֻמְאָה אַף עַל פִּי שֶׁלֹּא נָגַע בָּהּ טֻמְאָה אַחֶרֶת וְאֵינָהּ צְרִיכָה הֶכְשֵׁר:","פָּרָה אֲדֻמָּה וּשְׂעִירִין הַנִּשְׂרָפִים אֵינָן כֵּן. אַף עַל פִּי שֶׁהֵן מְטַמְּאִין הַמִּתְעַסֵּק בָּהֶן אִם חָשַׁב עֲלֵיהֶן לַאֲכִילָה צְרִיכִין שֶׁתִּגַּע בָּהֶן טֻמְאָה וְאַחַר כָּךְ יִטַּמְּאוּ טֻמְאַת אֳכָלִין:","כְּזַיִת מִנִּבְלַת הַבְּהֵמָה שֶׁתְּחָבוֹ בְּכוּשׁ וְהִכְנִיס לְתוֹךְ מְעִי הָאִשָּׁה מִלְּמַטָּה. אוֹ שֶׁהִכְנִיסוֹ לְתוֹךְ בְּלִיעָתוֹ שֶׁל חֲבֵרוֹ בְּמָקוֹם שֶׁנִּבְלַת הָעוֹף הַטָּהוֹר מְטַמְּאָה. הֲרֵי זֶה טִמְּאוֹ מִשּׁוּם נוֹשֵׂא לֹא מִשּׁוּם נוֹגֵעַ כְּמוֹ שֶׁבֵּאַרְנוּ בִּתְחִלַּת הַסֵּפֶר:","הַכּוֹרֵךְ כְּזַיִת מִבְּשַׂר נִבְלַת הָעוֹף הַטָּהוֹר בַּחֲזֶרֶת וְכַיּוֹצֵא בָּהּ וּבְלָעוֹ אַף עַל פִּי שֶׁלֹּא נָגַע בִּגְרוֹנוֹ הֲרֵי זֶה טָמֵא. כְּרָכוֹ בְּסִיב וּבְלָעוֹ הֲרֵי זֶה טָהוֹר:","הַבּוֹלֵעַ נִבְלַת הָעוֹף הַטָּהוֹר וְאַחַר שֶׁבְּלָעָהּ הֱקִיאָהּ קֹדֶם שֶׁתִּתְעַכֵּל הֲרֵי זֶה אֵינוֹ מְטַמֵּא בְּגָדִים כְּשֶׁתֵּצֵא לִגְרוֹנוֹ בְּשָׁעָה שֶׁמְּקִיאָהּ. שֶׁאֵינָהּ מְטַמְּאָה בְּבֵית הַנֶּפֶשׁ אֶלָּא בִּשְׁעַת בְּלִיעָה לֹא בְּשָׁעָה שֶׁמְּקִיאָהּ:","מְעִי שֶׁל נִבְלַת הָעוֹף הַטָּהוֹר שֶׁבְּלָעוֹ מִקְצָתוֹ בְּבֵית הַבְּלִיעָה וּמִקְצָתוֹ בַּחוּץ לְתוֹךְ פִּיו אִם יֵשׁ בְּבֵית הַבְּלִיעָה כְּזַיִת הֲרֵי זֶה טָמֵא וְאִם לָאו טָהוֹר:","בָּלַע מִמֶּנָּה אֵיבָר שָׁלֵם שֶׁאֵין בּוֹ כְּזַיִת אֵינוֹ מִתְטַמֵּא. אֲפִלּוּ נָטַל צִפּוֹר וַאֲכָלָהּ אִם יֵשׁ בָּהּ כְּזַיִת נִטְמָא וְאִם לָאו טָהוֹר:","הַכְּנָפַיִם וְהַנּוֹצָה אַף עַל פִּי שֶׁהֵן כָּאֳכָלִים וּמִתְטַמְּאִין וּמְטַמְּאִין טֻמְאַת אֳכָלִין אֵינָן מִצְטָרְפִין בְּנִבְלַת הָעוֹף הַטָּהוֹר לִכְזַיִת. אֲבָל הַמְּקוֹמוֹת הָרַכִּים הַקְּרוֹבִים לַבָּשָׂר מִן הַחַרְטוֹם וְהַצִּפָּרְנַיִם הֲרֵי הֵן כְּבָשָׂר וּמִצְטָרְפִין לִכְזַיִת. רָאשֵׁי אֲגַפַּיִים וְרֹאשׁ הַזָּנָב וְהָעֲצָמוֹת אֲפִלּוּ הָרַכּוֹת אֵינָן מִצְטָרְפִין:","הָאוֹכֵל מִנִּבְלַת הָעוֹף הַטָּהוֹר מִן הָעֲצָמוֹת הָרַכִּין אוֹ מִן הַגִּידִין וּמִן הַשְּׁלַל שֶׁל בֵּיצִים וּמִן הַדָּם וּמִבָּשָׂר מִן הַחַי מִמֶּנּוּ טָהוֹר. אֲבָל הָאוֹכֵל מִן הָאֶשְׁכּוֹל שֶׁל בֵּיצִים וּמִן הַקֻּרְקְבָן וּמִן בְּנֵי הַמֵּעַיִם אוֹ שֶׁהִמְחָה אֶת הַחֵלֶב בְּאוּר וּגְמָעוֹ הֲרֵי זֶה טָמֵא כְּאוֹכֵל מִבְּשָׂרָם שֶׁהַשּׁוֹתֶה בִּכְלַל אוֹכֵל. הִמְחָהוּ בַּחַמָּה וּגְמָעוֹ טָהוֹר שֶׁהֲרֵי הִסְרִיחוֹ:","נִבְלַת הָעוֹף הַטָּהוֹר שֶׁנִּפְסְדָה מִלֶּאֱכל הַכֶּלֶב טְהוֹרָה. וְכֵן אִם יָבְשָׁה כְּחֶרֶס וְאֵינָהּ יְכוֹלָה לְהִשָּׁרוֹת בְּפוֹשְׁרִין מֵעֵת לְעֵת לַחְזֹר לִכְמוֹת שֶׁהָיְתָה הֲרֵי זוֹ טְהוֹרָה. וְהָאוֹכֵל נֶצֶל שֶׁל נִבְלַת הָעוֹף הַטָּהוֹר הֲרֵי זֶה טָהוֹר:","עוֹף טָהוֹר שֶׁנִּטְרַף וְנִשְׁחַט שְׁחִיטָה כְּשֵׁרָה שְׁחִיטָתוֹ מְטַהַרְתּוֹ וַאֲפִלּוּ נִשְׁחַט בָּעֲזָרָה. וְאִם נִמְלַק וְנִמְצָא טְרֵפָה אֵין מְלִיקָתוֹ מְטַהֲרְתּוֹ. נִמְצֵאתָ אוֹמֵר שֶׁהַשּׁוֹחֵט עוֹף טָהוֹר בֵּין בַּחוּץ בֵּין בִּפְנִים בֵּין קָדָשִׁים בֵּין חֻלִּין הֲרֵי זֶה טָהוֹר. וְהַמּוֹלֵק חֻלִּין בִּפְנִים אוֹ שֶׁמָּלַק קָדָשִׁים בַּחוּץ הֲרֵי אֵלּוּ מְטַמְּאִין בְּגָדִים בְּבֵית הַבְּלִיעָה:","הַמּוֹלֵק קָדָשִׁים בִּפְנִים אִם הָיוּ רְאוּיִין לְקָרְבָּן וְלֹא נִמְצְאוּ בָּהֶן מוּמִין שֶׁבֵּאַרְנוּ בִּמְקוֹמוֹ הֲרֵי אֵלּוּ טְהוֹרִין. כַּיּוֹצֵא בּוֹ עֶגְלָה עֲרוּפָה שֶׁנֶּעֱרֶפֶת כְּהִלְכָתָהּ טְהוֹרָה כַּפָּרָה כְּתִיב בָּהּ כְּקָדָשִׁים. וְכֵן אִם נִשְׁחֲטָה אַחַר יְרִידָתָהּ לַנַּחַל אַף עַל פִּי שֶׁאֲסוּרָה בַּהֲנָאָה הִצִּילָה אוֹתָהּ שְׁחִיטָתָהּ מִידֵי נְבֵלָה:","נִבְלַת הָעוֹף הַטָּמֵא טְהוֹרָה וְאֵינָהּ מְטַמְּאָה בְּבֵית הַבְּלִיעָה. וְאִם חָשַׁב עָלֶיהָ לַאֲכִילָה וְהֻכְשְׁרָה הֲרֵי הִיא כָּאֳכָלִין טְמֵאִין שֶׁהֵן רִאשׁוֹן לְטֻמְאָה. וּכְנָפַיִם וְהַנּוֹצָה וְהַמְקוֹמוֹת הָרַכִּים מִן הַחַרְטוֹם וּמִן הַצִּפָּרְנַיִם שֶׁלָּהּ הֲרֵי הֵן כִּבְשָׂרָהּ:","אֶחָד הָעוֹף הַטָּהוֹר וְאֶחָד הָעוֹף הַטָּמֵא אֵיבָר מִן הַחַי הַפּוֹרֵשׁ מֵהֶם טָהוֹר וְאֵין בּוֹ טֻמְאָה כְּלָל. שֶׁנֶּאֱמַר (ויקרא יא כד) \"וּלְאֵלֶּה תִּטַּמָּאוּ\" (ויקרא יא כו) \"לְכָל הַבְּהֵמָה\" לְהוֹצִיא אֶת הָעוֹף שֶׁאֵין לוֹ פַּרְסָה. וּמִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁלֹּא בָּא הַכָּתוּב אֶלָּא לְטַמֵּא אֵיבָר מִן הַחַי שֶׁל בְּהֵמָה אוֹ חַיָּה:","אֵיבָר מִן הַמֵּת מִן הָעוֹף הֲרֵי הוּא כְּנִבְלַת הָעוֹף שֶׁפֵּרַשׁ מִמֶּנּוּ. אִם הָיְתָה נִבְלַת עוֹף טָהוֹר מְטַמְּאָה טֻמְאָה חֲמוּרָה בְּבֵית הַבְּלִיעָה בִּכְזַיִת. וְאִם חָשַׁב עָלָיו לַאֲכִילָה מִטַּמֵּא טֻמְאַת אֳכָלִין. וְאִם הָיְתָה נִבְלַת עוֹף טָמֵא מִטַּמֵּא טֻמְאַת אֳכָלִין אִם חָשַׁב עָלָיו וְהֻכְשַׁר. וְאֵינוֹ מְטַמֵּא אֳכָלִין אֲחֵרִים עַד שֶׁיִּהְיֶה בּוֹ כְּבֵיצָה כְּשִׁעוּר כָּל הָאֳכָלִין לְטַמֵּא כְּמוֹ שֶׁיִּתְבָּאֵר:"],"Mishneh Torah, Overview of Mishneh Torah Contents 14":["ספר שופטים","הלכותיו חמש, וזה הוא סידורן: הלכות סנהדרין והעונשין המסורין להם, הלכות עדות, הלכות ממרים, הלכות אבל, הלכות מלכים ומלחמות.","הלכות סנהדרין והעונשין המסורין להם. יש בכללן שלושים מצוות – עשר מצוות עשה, ועשרים מצוות לא תעשה; וזה הוא פרטן: (א) למנות שופטים; (ב) שלא למנות דיין שאינו יודע דרך המשפט; (ג) לנטות אחרי רבים, אם נחלקו השופטים; (ד) שלא להרוג אם רבו המחייבין באיש אחד, עד שיהיו יתר שניים; (ה) שלא ילמד חובה מי שלימד זכות בדיני נפשות; (ו) להרוג בסקילה; (ז) להרוג בשריפה; (ח) להרוג בסיף; (ט) להרוג בחנק; (י) לתלות; (יא) לקבור הנהרג ביום הריגתו; (יב) שלא תלין נבלתו; (יג) שלא להחיות מכשף; (יד) להלקות לרשע; (טו) שלא יוסיף בהכית הלוקה; (טז) שלא להרוג נקי באומדן הדעת; (יז) שלא לענוש אנוס; (יח) שלא לחוס על הורג חברו או חובל בו; (יט) שלא לרחם על הדל בדין; (כ) שלא להדר גדול בדין; (כא) שלא להטות הדין על בעל עבירות, אף על פי שהוא חוטא; (כב) שלא לעוול משפט; (כג) שלא להטות משפט גר יתום; (כד) לשפוט בצדק; (כה) שלא ליראה בדין מאיש זרוע; (כו) שלא ליקח שוחד; (כז) שלא לישא שמע שוא; (כח) שלא לקלל הדיינין; (כט) שלא לקלל הנשיא; (ל) שלא לקלל אדם משאר בני ישראל הכשרים.","הלכות עדות. יש בכללן שמונה מצוות – שלוש מצוות עשה, וחמש מצוות לא תעשה; וזה הוא פרטן: (א) להעיד בבית דין למי שיודע לו עדות; (ב) לדרוש ולחקור העדים; (ג) שלא יורה העד בדין זה שהעיד עליו, בדיני נפשות; (ד) שלא יקום דבר בעדות אחד; (ה) שלא יעיד בעל עבירה; (ו) שלא יעיד קרוב; (ז) שלא להעיד בשקר; (ח) לעשות לעד זומם כאשר זמם.","הלכות ממרים. יש בכללן תשע מצוות – שלוש מצוות עשה, ושש מצוות לא תעשה; וזה הוא פרטן: (א) לעשות על פי התורה שיאמרו בית דין הגדול; (ב) שלא לסור מדבריהם; (ג) שלא להוסיף על התורה, לא במצוות שבכתב ולא בפירושן שלמדנו מפי השמועה; (ד) שלא לגרוע מן הכול; (ה) שלא לקלל אב ואם; (ו) שלא להכות אב ואם; (ז) לכבד אב ואם; (ח) ליראה מאב ואם; (ט) שלא יהיה הבן סורר ומורה על קול אביו ואימו.","הלכות אבל. יש בכללן ארבע מצוות – אחת מצות עשה, ושלוש מצוות לא תעשה; וזה הוא פרטן: (א) להתאבל על הקרובים, ואפילו כוהן מיטמא ומתאבל על הקרובים. ואין אדם מתאבל על הרוגי בית דין; ולפי זה כללתי הלכות אלו בספר זה, שהם מעין קבורה ביום מיתה שהיא מצות עשה. (ב) שלא ייטמא כוהן גדול לקרובים; (ג) שלא ייכנס עם המת באוהל; (ד) שלא ייטמא כוהן הדיוט לנפש אדם אלא לקרובים בלבד.","הלכות מלכים ומלחמות. יש בכללן שלוש ועשרים מצוות – עשר מצוות עשה, ושלוש עשרה מצוות לא תעשה; וזה הוא פרטן: (א) למנות מלך מישראל; (ב) שלא יימנה מקהל גרים; (ג) שלא ירבה לו נשים; (ד) שלא ירבה לו סוסים; (ה) שלא ירבה לו כסף וזהב; (ו) להחרים שבעה עממים; (ז) שלא להחיות מהן נשמה; (ח) למחות זרעו של עמלק; (ט) לזכור מה שעשה עמלק; (י) שלא לשכוח מעשיו הרעים ואריבתו בדרך; (יא) שלא לשכון בארץ מצריים; (יב) לשלוח שלום ליושבי העיר כשצרים עליה, ולדון בה כאשר מפורש בתורה, אם תשלים ואם לא תשלים; (יג) שלא לדרוש שלום מעמון ומואב בלבד, כשצרים עליהן; (יד) שלא להשחית אילני מאכל במצור; (טו) להתקין יד שייצאו בו בעלי המחנה להיפנות בו; (טז) להתקין יתד לחפור בו; (יז) למשוח כוהן לדבר באוזני אנשי הצבא בשעת המלחמה; (יח) להיות מארס ובונה בניין ונוטע כרם שמחים בקניינם שנה תמימה, ומחזירין אותן מן המלחמה; (יט) שלא יעבור עליהן דבר, ולא ייצאו אפילו לצורכי העיר וצורכי הגדוד והדומה להן; (כ) שלא לערוץ ולחזור לאחור בשעת מלחמה; (כא) דין יפת תואר; (כב) שלא תימכר יפת תואר; (כג) שלא יכבשנה לעבדות אחר שנבעלה.","נמצאו כל המצוות הנכללות בספר זה, ארבע ושבעים – מהן שבע ועשרים מצוות עשה, ושבע וארבעים מצוות לא תעשה.","ונמצאו כל ההלכות של ארבעה עשר ספר, שלוש ושמונים הלכות.","ועתה אתחיל לבאר משפטי כל מצוה ומצוה וכל הדינין הנגללין עימה מעניינה על סדר ההלכות, בעזרת שדי."],"Mishneh Torah, Ownerless Property and Gifts 12":["שְׁכִיב מֵרַע שֶׁאָמַר בְּנִי פְּלוֹנִי יִירָשֵׁנִי. הֲרֵי זֶה יוֹרֵשׁ אוֹתוֹ לְבַדּוֹ וְלֹא יִירָשׁוּהוּ שְׁאָר הַבָּנִים. וְכֵן אִם אָמַר עַל בַּת בֵּין הַבָּנוֹת אוֹ אָח בֵּין הָאַחִין אוֹ שְׁאָר יוֹרְשִׁין דְּבָרָיו קַיָּמִין:","אֲבָל הַבָּרִיא אֵין דְּבָרָיו קַיָּמִין:","שְׁכִיב מֵרַע שֶׁאָמַר נְכָסַי לִפְלוֹנִי וְאַחֲרָיו לִפְלוֹנִי. אֵין לַשֵּׁנִי אֶלָּא מַה שֶּׁשִּׁיֵּר רִאשׁוֹן:","וְאִם הָיָה הָרִאשׁוֹן רָאוּי לְיָרְשׁוֹ כְּגוֹן שֶׁהָיָה בֵּן מִכְּלַל הַבָּנִים אֵין לַשֵּׁנִי כְּלוּם. שֶׁכָּל לְשׁוֹן מַתָּנָה לַיּוֹרֵשׁ הֲרֵי הוּא כִּלְשׁוֹן יְרֻשָּׁה. וִירֻשָּׁה אֵין לָהּ הֶפְסֵק וְאַף עַל פִּי שֶׁאָמַר וְאַחֲרָיו לִפְלוֹנִי:","אֲבָל הַבָּרִיא שֶׁנָּתַן מַתְּנַת בָּרִיא עַל דֶּרֶךְ זֶה וְכָתַב לָזֶה נְכָסַי לְךָ וְאַחֲרֶיךָ לִפְלוֹנִי. אֵין לַשֵּׁנִי אֶלָּא מַה שֶּׁשִּׁיֵּר רִאשׁוֹן בֵּין שֶׁהָיָה הָרִאשׁוֹן רָאוּי לְיָרְשׁוֹ בֵּין שֶׁלֹּא הָיָה רָאוּי לְיָרְשׁוֹ:","שְׁכִיב מֵרַע שֶׁאָמַר נְכָסַי לְךָ וְאַחֲרֶיךָ לִפְלוֹנִי וְהָיָה רִאשׁוֹן רָאוּי לְיָרְשׁוֹ וּפֵרֵשׁ וְאָמַר לֹא מִשּׁוּם יְרֻשָּׁה אֲנִי נוֹתֵן לְךָ שֶׁאֵין לָהּ הֶפְסֵק אֶלָּא בְּמַתָּנָה וַהֲרֵי הִפְסַקְתִּיהָ. הַשֵּׁנִי קוֹנֶה מַה שֶּׁמְּשַׁיֵּר הָרִאשׁוֹן. לְפִיכָךְ אִם נָתַן הַמָּעוֹת עַל יַד שָׁלִישׁ אוֹ שֶׁאָמַר תְּנוּ לְבָנַי שֶׁקֶל בְּכָל שַׁבָּת וְלֹא מִשּׁוּם יְרֻשָּׁה אֲנִי נוֹתְנָם לָהֶם. וְהַנִּשְׁאָר מִן הַנְּכָסִים אַחַר מוֹתָם יִהְיֶה לִפְלוֹנִי. אֵין נוֹתְנִין לָהֶם אֶלָּא שֶׁקֶל אַף עַל פִּי שֶׁאֵינוֹ מַסְפִּיק לָהֶם:","נְכָסַי לִפְלוֹנִי וְאַחֲרָיו לִפְלוֹנִי. מֵת רִאשׁוֹן קָנָה שֵׁנִי. מֵת שֵׁנִי הֲרֵי אֵלּוּ שֶׁל יוֹרְשֵׁי הַשֵּׁנִי. מֵת שֵׁנִי בְּחַיֵּי רִאשׁוֹן יִהְיוּ הַנְּכָסִים שֶׁל יוֹרְשֵׁי רִאשׁוֹן:","וְאַף עַל פִּי שֶׁאֵין לַשֵּׁנִי אֶלָּא מַה שֶּׁשִּׁיֵּר רִאשׁוֹן אָסוּר לָרִאשׁוֹן לִמְכֹּר וְלִתֵּן גּוּפוֹ אֶלָּא אוֹכֵל הַפֵּרוֹת עַד שֶׁיָּמוּת וְיִזְכֶּה הַשֵּׁנִי:","וְאִם עָבַר הָרִאשׁוֹן וּמָכַר וְנָתַן בְּמַתָּנָה. אֵין הַשֵּׁנִי מוֹצִיא מִיַּד הַלָּקוֹחוֹת שֶׁאֵין לַשֵּׁנִי לֹא מִן הַגּוּף וְלֹא מִן הַפֵּרוֹת אֶלָּא הַנִּשְׁאָר. וְכָל הַמַּשִּׂיא עֵצָה לָרִאשׁוֹן לִמְכֹּר נִקְרָא רָשָׁע. וַאֲפִלּוּ הָיָה בָּהֶן עֲבָדִים וְהוֹצִיאָן הָרִאשׁוֹן לְחֵרוּת אוֹ כֵּלִים וַעֲשָׂאָן תַּכְרִיכִין לְמֵת מַעֲשָׂיו קַיָּמִין:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁמָּכַר הָרִאשׁוֹן אוֹ נָתַן מַתָּנָה לַאֲחֵרִים. אֲבָל אִם מְכָרָן הָרִאשׁוֹן אוֹ נְתָנָן לִבְנוֹ מַתָּנָה אוֹ לְאֶחָד מִיּוֹרְשָׁיו לֹא עָשָׂה כְּלוּם. וְכֵן אִם נְתָנָן בְּמַתְּנַת שְׁכִיב מֵרַע אֲפִלּוּ לַאֲחֵרִים לֹא עָשָׂה כְּלוּם שֶׁאֵין מַתְּנַת שְׁכִיב מֵרַע קוֹנָה אֶלָּא לְאַחַר מִיתָה וּכְשֶׁיָּמוּת יִקְנֶה הַשֵּׁנִי:","הָיָה חוֹב עַל הָרִאשׁוֹן אוֹ כְּתֻבַּת אִשָּׁה וּבָאוּ לְבֵית דִּין לְהִפָּרַע מִנְּכָסִים אֵלּוּ. אַף עַל פִּי שֶׁהָרִאשׁוֹן קַיָּם אֵין בֵּית דִּין מְגַבִּין אוֹתָם מִגּוּף הַנְּכָסִים אֶלָּא מִן הַפֵּרוֹת בִּלְבַד שָׁמִין לָהֶם. מֵת הָרִאשׁוֹן וּבָא בַּעַל חוֹבוֹ וְאִשְׁתּוֹ לִגְבּוֹת מִנְּכָסִים אֵלּוּ אֵין מְגַבִּין לָהֶם כְּלוּם אֲפִלּוּ עֲשָׂאָן אַפּוֹתֵיקֵי אוֹ שֶׁיִּחֲדָן לְאִשְׁתּוֹ בִּכְתֻבָּתָהּ אֵינָן גּוֹבִין מִנְּכָסִים אֵלּוּ כְּלוּם אֶלָּא הֲרֵי הֵן שֶׁל שֵׁנִי:","שְׁכִיב מֵרַע שֶׁאָמַר לְאִשָּׁה פְּנוּיָה נְכָסַי לָךְ וְאַחֲרַיִךְ לִפְלוֹנִי וְעָמְדָה וְנִשֵּׂאת. בַּעַל לוֹקֵחַ הוּא וְאֵין הַשֵּׁנִי מוֹצִיא מִיַּד הַבַּעַל. וְאִם אָמַר לָהּ כְּשֶׁהִיא נְשׂוּאָה נְכָסַי לִיךְ וְאַחֲרַיִךְ לִפְלוֹנִי וּמֵתָה. הַשֵּׁנִי מוֹצִיא מִיַּד הַבַּעַל. שֶׁכֵּיוָן שֶׁזָּכְתָה בַּנְּכָסִים עַל תְּנַאי זֶה כְּשֶׁהִיא נְשׂוּאָה נִמְצָא כְּאִלּוּ אָמַר לָהּ בְּפֵרוּשׁ אַחֲרַיִךְ יִקְנֶה פְּלוֹנִי לֹא הַבַּעַל. לְפִיכָךְ אִם מָכְרָה נְכָסִים אֵלּוּ כְּשֶׁהִיא תַּחַת בַּעְלָהּ וּמֵתָה תַּחַת בַּעְלָהּ יַעַמְדוּ נְכָסִים בְּיַד הַלּוֹקֵחַ שֶׁאִם יוֹצִיא הַבַּעַל מִיַּד הַלּוֹקֵחַ מִפְּנֵי שֶׁמָּכְרָה כְּשֶׁהִיא נְשׂוּאָה הֲרֵי הַשֵּׁנִי מוֹצִיא מִיַּד הַבַּעַל וְהַלּוֹקֵחַ חוֹזֵר וּמוֹצִיא מִיַּד הַשֵּׁנִי. שֶׁהֲרֵי מָכְרָה לוֹ וְאֵין לוֹ אֶלָּא מַה שֶּׁשִּׁיֵּר רִאשׁוֹן. וְאֵין בִּשְׁלָשְׁתָּן מִי שֶׁהוֹצִיא מָמוֹן אֶלָּא הַלּוֹקֵחַ. וּלְפִיכָךְ תַּעֲמֹד בְּיָדוֹ. מַעֲשֶׂה בְּאֶחָד שֶׁאָמַר נְכָסַי לְאִמִּי וְאַחֲרֶיהָ לְיוֹרְשַׁי וְהָיְתָה לוֹ בַּת נְשׂוּאָה וּמֵתָה הַבַּת בְּחַיֵּי בַּעְלָהּ וּבְחַיֵּי אֵם אָבִיהָ וְאַחַר כָּךְ מֵתָה הַזְּקֵנָה. וְאָמְרוּ חֲכָמִים אֵין הַבַּעַל יוֹרֵשׁ אוֹתָן נְכָסִים מִפְּנֵי שֶׁהֵן רְאוּיִין לְאִשְׁתּוֹ וְלֹא זָכְתָה בָּהֶן הָאִשָּׁה אֶלָּא אַחַר שֶׁמֵּתָה. אֲבָל אִם הִנִּיחָה הַבַּת בֵּן אוֹ בַּת הָיוּ יוֹרְשִׁין הַנְּכָסִים. שֶׁמַּשְׁמָע יוֹרְשִׁין וַאֲפִלּוּ יוֹרְשֵׁי יוֹרְשִׁין. וְאִלּוּ אָמַר וּכְשֶׁתָּמוּת הַזְּקֵנָה הֲרֵי הֵן לְבִתִּי מֵעַכְשָׁו. הָיָה הַבַּעַל יוֹרֵשׁ אוֹתָן אַחַר מִיתַת אִשְׁתּוֹ:","הַכּוֹתֵב נְכָסָיו לִבְנוֹ וּלְאַחַר מוֹתוֹ. הֲרֵי הַגּוּף שֶׁל בֵּן מִזְּמַן הַשְּׁטָר וְהַפֵּרוֹת לָאָב עַד שֶׁיָּמוּת. לְפִיכָךְ הָאָב אֵינוֹ יָכוֹל לִמְכֹּר מִפְּנֵי שֶׁהֵן נְתוּנִין לַבֵּן. וְהַבֵּן אֵינוֹ יָכוֹל לִמְכֹּר מִפְּנֵי שֶׁהֵן בִּרְשׁוּת הָאָב. מֵת הָאָב וְהִנִּיחַ פֵּרוֹת מְחֻבָּרִין לַקַּרְקַע הֲרֵי הֵן שֶׁל בֵּן. מִפְּנֵי שֶׁדַּעְתּוֹ שֶׁל אָדָם קְרוֹבָה אֵצֶל בְּנוֹ. הָיוּ תְּלוּשִׁין אוֹ שֶׁהִגִּיעוּ לְהִבָּצֵר הֲרֵי הֵן שֶׁל יוֹרְשִׁין. עָבַר הָאָב וּמָכַר מְכוּרִין עַד שֶׁיָּמוּת. וּכְשֶׁיָּמוּת הָאָב מוֹצִיא הַבֵּן מִיַּד הַלָּקוֹחוֹת. וְאִם הָיוּ שָׁם פֵּרוֹת מְחֻבָּרִין שָׁמִין אוֹתָם לַלּוֹקֵחַ וְנוֹתֵן הַבֵּן דְּמֵיהֶם. הָיוּ תְּלוּשִׁין אוֹ שֶׁהִגִּיעוּ לְהִבָּצֵר הֲרֵי הֵן שֶׁל לוֹקֵחַ. עָבַר הַבֵּן וּמָכַר אֵין לַלּוֹקֵחַ כְּלוּם עַד שֶׁיָּמוּת הָאָב. מָכַר הַבֵּן בְּחַיֵּי הָאָב וּמֵת הַבֵּן וְאַחַר כָּךְ מֵת הָאָב. כְּשֶׁיָּמוּת הָאָב קָנָה הַלּוֹקֵחַ. שֶׁאֵין לָאָב אֶלָּא פֵּרוֹת וְקִנְיַן פֵּרוֹת אֵינוֹ כְּקִנְיַן הַגּוּף:","מַתְּנַת בָּרִיא שֶׁכָּתוּב בָּהּ מֵהַיּוֹם וּלְאַחַר מִיתָה. הֲרֵי הִיא כְּמַתְּנַת שְׁכִיב מֵרַע שֶׁאֵינוֹ קוֹנֶה אֶלָּא לְאַחַר מִיתָה. שֶׁמַּשְׁמַע דְּבָרִים אֵלּוּ שֶׁאַף עַל פִּי שֶׁקָּנָה הַגּוּף מֵהַיּוֹם אֵינוֹ זוֹכֶה בּוֹ וְאוֹכֵל פֵּרוֹת אֶלָּא לְאַחַר מִיתָה:","שְׁטַר מַתָּנָה שֶׁכָּתוּב בּוֹ שֶׁיִּקְנֶה פְּלוֹנִי שָׂדֶה פְּלוֹנִית לְאַחַר מִיתָה בֵּין שֶׁהָיָה בַּשְּׁטָר קִנְיָן בֵּין שֶׁלֹּא הָיָה בּוֹ קִנְיָן. כֵּיוָן שֶׁכָּתוּב בּוֹ זְמַן וּבִזְמַן זֶה חַי הָיָה. הַזְּמַן מוֹכִיחַ שֶׁמֵּחַיִּים הִקְנָה לוֹ וְאֵינוֹ זוֹכֶה אֶלָּא לְאַחַר מִיתָה. שֶׁאִלּוּ הָיָה בְּדַעְתּוֹ לְהַקְנוֹת לוֹ בִּשְׁטָר זֶה לְאַחַר מִיתָה לֹא הָיָה כּוֹתֵב בּוֹ זְמַן. לְפִיכָךְ אַף עַל פִּי שֶׁאֵין כָּתוּב בּוֹ מֵהַיּוֹם וּלְאַחַר מִיתָה קוֹנֶה לְאַחַר מִיתָה. וְזֶה שֶׁכּוֹתְבִין בְּכָל הַמַּתָּנוֹת וְהַמִּמְכָּרוֹת מֵעַכְשָׁו וְאַף עַל פִּי שֶׁיֵּשׁ בַּשְּׁטָר הַזְּמַן. לְהַרְוִיחַ הַדָּבָר כּוֹתְבִין בּוֹ אַף עַל פִּי שֶׁאֵינוֹ צָרִיךְ:","בָּרִיא שֶׁנָּתַן מַתָּנָה וְכָתַב בַּשְּׁטָר מֵחַיִּים וּבַמָּוֶת. הֲרֵי זוֹ מַתָּנָה גְּמוּרָה מֵחַיִּים שֶׁהֲרֵי כָּתוּב בּוֹ מֵחַיִּים. וְזֶה שֶׁכָּתוּב בּוֹ וּבַמָּוֶת כְּמִי שֶׁאוֹמֵר מֵעַתָּה וְעַד עוֹלָם וּכְמוֹ נוֹיֵי הַשְּׁטָר הוּא זֶה:","הַצַּדִּיקִים הַגְּמוּרִים וְאַנְשֵׁי מַעֲשֶׂה לֹא יְקַבְּלוּ מַתָּנָה מֵאָדָם. אֶלָּא בּוֹטְחִים בַּה' בָּרוּךְ שְׁמוֹ לֹא בִּנְדִיבִים. וַהֲרֵי נֶאֱמַר (משלי טו כז) \"וְשׂוֹנֵא מַתָּנֹת יִחְיֶה\": סְלִיקוּ לְהוּ הִלְכוֹת זְכִיָּה וּמַתָּנָה בְּסַ\"ד"],"Mishneh Torah, Paschal Offering 3":["הָאוֹמֵר לְעַבְדּוֹ צֵא וּשְׁחֹט עָלַי אֶת הַפֶּסַח. אַף עַל פִּי שֶׁדֶּרֶךְ רַבּוֹ לִשְׁחֹט טָלֶה בְּכָל שָׁנָה וְהָלַךְ וְשָׁחַט עָלָיו גְּדִי אוֹ שֶׁהָיָה דַּרְכּוֹ לִשְׁחֹט גְּדִי וְהָלַךְ וְשָׁחַט עָלָיו טָלֶה הֲרֵי זֶה יֹאכַל מִמֶּנּוּ. שֶׁהֲרֵי לֹא פֵּרֵשׁ וְאָמַר לוֹ שְׁחֹט לִי מִמִּין פְּלוֹנִי. הָלַךְ וְשָׁחַט גְּדִי וְטָלֶה אֵינוֹ אוֹכֵל מִשְּׁנֵיהֶן אֶלָּא יֵצְאוּ לְבֵית הַשְּׂרֵפָה שֶׁאֵין נִמְנִין עַל שְׁנֵי פְּסָחִים. וְאִם הָיָה מֶלֶךְ אוֹ מַלְכָּה וְאָמַר לְעַבְדּוֹ לִשְׁחֹט עָלָיו וְשָׁחַט גְּדִי וְטָלֶה יֹאכַל מִן הָרִאשׁוֹן מִשּׁוּם שְׁלוֹם מַלְכוּת:","הָאוֹמֵר לִשְׁלוּחוֹ צֵא וּשְׁחֹט עָלַי אֶת הַפֶּסַח וְקָבַע לוֹ גְּדִי אוֹ טָלֶה וְשָׁכַח מָה אָמַר לוֹ רַבּוֹ. הֲרֵי זֶה שׁוֹחֵט גְּדִי וְטָלֶה וְאוֹמֵר אִם גְּדִי אָמַר לִי גְּדִי שֶׁלּוֹ וְטָלֶה שֶׁלִּי וְאִם טָלֶה אָמַר לִי טָלֶה שֶׁלּוֹ וּגְדִי שֶׁלִּי. שָׁכַח הַשּׁוֹלֵחַ מָה אָמַר לוֹ שְׁנֵיהֶן יֵצְאוּ לְבֵית הַשְּׂרֵפָה. וְאִם שָׁכַח הַשּׁוֹלֵחַ קֹדֶם שֶׁיִּזָּרֵק הַדָּם חַיָּבִין לַעֲשׂוֹת פֶּסַח שֵׁנִי. שָׁכַח אַחַר שֶׁנִּזְרַק הַדָּם פָּטוּר מִלַּעֲשׂוֹת פֶּסַח שֵׁנִי. וְכֵן הַדִּין בְּאוֹמֵר לְעַבְדּוֹ צֵא וּשְׁחֹט עָלַי וְקָבַע לוֹ וְשָׁכַח הָעֶבֶד מָה אָמַר לוֹ רַבּוֹ. וְהוּא שֶׁיִּתֵּן לוֹ רוֹעֶה שֶׁל רַבּוֹ גְּדִי וְטָלֶה וְיֹאמַר לוֹ שְׁחֹט שְׁנֵיהֶן כְּדֵי שֶׁתִּשְׁחֹט כְּמוֹ שֶׁאָמַר לוֹ רַבְּךָ וַהֲרֵי אֶחָד מֵהֶן שֶׁלְּךָ עַל מְנָת שֶׁלֹּא יִהְיֶה לְרַבְּךָ בּוֹ כְּלוּם. אִם עָשָׂה הָרוֹעֶה כָּךְ אַחַר כָּךְ יִהְיֶה אֶפְשָׁר לָעֶבֶד לְהַתְנוֹת כְּמוֹ שֶׁבֵּאַרְנוּ:","בְּנֵי חֲבוּרָה שֶׁאָמְרוּ לָאֶחָד צֵא וּשְׁחֹט לָנוּ אֶת הַפֶּסַח וְאָמַר הוּא לָהֶן וְאַתֶּם שַׁחֲטוּ עָלַי וְשָׁחֲטוּ הֵם וְשָׁחַט הוּא כֻּלָּם אוֹכְלִין מִזֶּה שֶׁנִּשְׁחַט רִאשׁוֹן וְהָאַחֲרוֹן יֵצֵא לְבֵית הַשְּׂרֵפָה:","חֲבוּרָה שֶׁאָבַד פִּסְחָהּ וְאָמְרוּ לָאֶחָד צֵא וּבַקֵּשׁ וּשְׁחֹט עָלֵינוּ. הָלַךְ וּמָצָא פֶּסַח שֶׁאָבַד וּשְׁחָטוֹ וְהֵם לָקְחוּ פֶּסַח אַחֵר וּשְׁחָטוּהוּ אִם שֶׁלּוֹ נִשְׁחַט רִאשׁוֹן הוּא אוֹכֵל מִשֶּׁלּוֹ וְהֵן אוֹכְלִין עִמּוֹ וְהַשֵּׁנִי יִשָּׂרֵף וְאִם שֶׁלָּהֶן נִשְׁחַט רִאשׁוֹן הֵן אוֹכְלִין מִשֶּׁלָּהֶן וְהוּא אוֹכֵל מִשֶּׁלּוֹ. אֵין יָדוּעַ אֵי זֶה מֵהֶן נִשְׁחַט רִאשׁוֹן אוֹ שֶׁשָּׁחֲטוּ שְׁנֵיהֶן כְּאַחַת הוּא אוֹכֵל מִשֶּׁלּוֹ וְהֵן אֵינָן אוֹכְלִין עִמּוֹ וְשֶׁלָּהֶן יֵצֵא לְבֵית הַשְּׂרֵפָה וּפְטוּרִין מִלַּעֲשׂוֹת פֶּסַח שֵׁנִי:","אָמַר לָהֶם זֶה שֶׁשְּׁלָחוּהוּ לְבַקֵּשׁ פֶּסַח שֶׁאָבַד וּלְשָׁחֳטוֹ אִם אֵחַרְתִּי שַׁחֲטוּ אַתֶּם עָלַי. הָלַךְ וּמָצָא וְשָׁחַט וְהֵם לָקְחוּ וְשָׁחֲטוּ. אִם שֶׁלָּהֶן נִשְׁחַט רִאשׁוֹן הֵם אוֹכְלִין מִשֶּׁלָּהֶם וְהוּא אוֹכֵל עִמָּהֶם וְהַשֵּׁנִי יִשָּׂרֵף. וְאִם שֶׁלּוֹ נִשְׁחַט רִאשׁוֹן הוּא אוֹכֵל מִשֶּׁלּוֹ וְהֵן אוֹכְלִין מִשֶּׁלָּהֶן. אֵין יָדוּעַ אֵי זֶה מֵהֶן נִשְׁחַט רִאשׁוֹן אוֹ שֶׁשָּׁחֲטוּ שְׁנֵיהֶם כְּאֶחָד הֵן אוֹכְלִין מִשֶּׁלָּהֶן וְהוּא אֵינוֹ אוֹכֵל עִמָּהֶן. וְשֶׁלּוֹ יֵצֵא לְבֵית הַשְּׂרֵפָה וּפָטוּר מִלַּעֲשׂוֹת פֶּסַח שֵׁנִי:","אָבַד לָהֶן פִּסְחָם וְאָבַד לוֹ פִּסְחוֹ וְאָמַר לָהֶן צְאוּ וּבַקְּשׁוּ וְשַׁחֲטוּ עָלַי וְאָמְרוּ לוֹ צֵא וּבַקֵּשׁ וּשְׁחֹט עָלֵינוּ וְהָלַךְ וּמָצָא וְשָׁחַט וּמָצְאוּ הֵם וְשָׁחֲטוּ. כֻּלָּם אוֹכְלִין מִן הָרִאשׁוֹן וְהַשֵּׁנִי יִשָּׂרֵף. וְאִם אֵין יָדוּעַ אֵי זֶה נִשְׁחַט תְּחִלָּה אוֹ שֶׁשָּׁחֲטוּ שְׁנֵיהֶן כְּאֶחָד שְׁנֵיהֶן יִשָּׂרְפוּ וּפְטוּרִין מִלַּעֲשׂוֹת פֶּסַח שֵׁנִי. הָלַךְ הוּא לְבַקֵּשׁ וְהָלְכוּ הֵם לְבַקֵּשׁ וְלֹא אָמְרוּ זֶה לָזֶה כְּלוּם. אַף עַל פִּי שֶׁהָיָה בְּלִבָּם שֶׁיִּשְׁחֹט כָּל אֶחָד מֵהֶן עַל חֲבֵרוֹ. אוֹ שֶׁהָיוּ שָׁם רְמִיזוֹת וּדְבָרִים שֶׁאֻמְדַּן הַדַּעַת בָּהֶן שֶׁכָּל אֶחָד שֶׁיִּמְצָא יִשְׁחֹט עַל חֲבֵרוֹ. הוֹאִיל וְלֹא פֵּרְשׁוּ וְלֹא אָמְרוּ זֶה לָזֶה כְּלוּם אֵינָן אַחְרָאִין זֶה לָזֶה:","שְׁתֵּי חֲבוּרוֹת שֶׁנִּתְעָרְבוּ פִּסְחֵיהֶן קֹדֶם שֶׁיִּשָּׁחֲטוּ. חֲבוּרָה זוֹ לוֹקְחִין כֶּבֶשׂ אֶחָד מִן הַתַּעֲרוֹבוֹת. וְהַשְּׁנִיָּה לוֹקְחִין הַשֵּׁנִי. וְאֶחָד מִבְּנֵי חֲבוּרָה זוֹ בָּא אֵצֶל אֵלּוּ. וְאֶחָד מִבְּנֵי שְׁנִיָּה בָּא אֵצֶל הָרִאשׁוֹנָה. וְכָל חֲבוּרָה מֵהֶן אוֹמְרוֹת לְזֶה הָאֶחָד שֶׁבָּא אֶצְלָם אִם שֶׁלָּנוּ הוּא הַפֶּסַח הַזֶּה יָדֶיךָ מְשׁוּכוֹת מִשֶּׁלְּךָ וְנִמְנֵיתָ עַל שֶׁלָּנוּ וְאִם שֶׁלְּךָ הוּא הַפֶּסַח הַזֶּה יָדֵינוּ מְשׁוּכוֹת מִשֶּׁלָּנוּ וְנִמְנֵינוּ עַל שֶׁלְּךָ. וְכֵן חָמֵשׁ חֲבוּרוֹת שֶׁל חֲמִשָּׁה חֲמִשָּׁה בְּנֵי אָדָם אוֹ עֶשֶׂר חֲבוּרוֹת שֶׁל עֲשָׂרָה עֲשָׂרָה מוֹשְׁכִין לָהֶן אֶחָד מִכָּל חֲבוּרָה לַחֲבוּרָה הָאַחֶרֶת וְכָךְ הֵם מַתְנִים וְאוֹמְרִים וְאַחַר כָּךְ שׁוֹחֲטִין:","שְׁנַיִם שֶׁנִּתְעָרְבוּ פִּסְחֵיהֶן זֶה לוֹקֵחַ פֶּסַח אֶחָד מִן הַתַּעֲרוֹבוֹת וְזֶה לוֹקֵחַ לוֹ אֶחָד. וְזֶה מְמַנֶּה עַל פִּסְחוֹ אֶחָד מִן הַשּׁוּק וְהָאַחֵר מְמַנֶּה עִמּוֹ אֶחָד מִן הַשּׁוּק כְּדֵי שֶׁיִּהְיוּ שְׁתֵּי חֲבוּרוֹת. וְאַחַר כָּךְ יָבוֹא אֶחָד מִשְּׁנֵיהֶם אֵצֶל אֵלּוּ וְיָבוֹא אֶחָד מֵאֵלּוּ אֵצֶל הָאַחֵר וּמַתְנֶה כָּל אֶחָד עִם חֲבֵרוֹ שֶׁבָּא אֶצְלוֹ מֵחֲבוּרָה שְׁנִיָּה וְאוֹמֵר אִם שֶׁלִּי הוּא פֶּסַח זֶה יָדֶיךָ מְשׁוּכוֹת מִשֶּׁלְּךָ וְנִמְנֵיתָ עַל שֶׁלִּי וְאִם שֶׁלְּךָ הוּא יָדִי מְשׁוּכָה מִפֶּסַח שֶׁלִּי וְנִמְנֵיתִי עַל שֶׁלְּךָ וְנִמְצָא שֶׁלֹּא הִפְסִידוּ כְּלוּם:","חֲמִשָּׁה שֶׁנִּתְעָרְבוּ עוֹרוֹת פִּסְחֵיהֶן נִמְצֵאת יַבֶּלֶת בְּעוֹר אֶחָד מֵהֶן כֻּלָּם יֵצְאוּ לְבֵית הַשְּׂרֵפָה. וְאִם נִתְעָרְבוּ קֹדֶם זְרִיקַת דָּמָן חַיָּבִין בְּפֶסַח שֵׁנִי. נִתְעָרְבוּ אחַר זְרִיקָה פְּטוּרִין מִלַּעֲשׂוֹת פֶּסַח שֵׁנִי שֶׁאִם הִקְרִיבוּ פֶּסַח שֵׁנִי נִמְצָא זֶה שֶׁקָּרַב בָּרִאשׁוֹן קָרְבָּן כָּשֵׁר מֵבִיא חֻלִּין עֲזָרָה. וְאִם נִמְנוּ כֻּלָּן עַל פֶּסַח אֶחָד נִמְצָא נִשְׁחַט שֶׁלֹּא לִמְחֻיָּב וְזֶה כְּמִי שֶׁנִּשְׁחַט שֶׁלֹּא לִמְנוּיָיו. וְאִם הִתְנָה כָּל אחָד מֵהֶן וְאָמַר אִם אֵינוֹ פֶּסַח יִהְיֶה שְׁלָמִים דַּם הַפֶּסַח בִּשְׁפִיכָה וְדַם הַשְּׁלָמִים בִּזְרִיקָה וְהַנִּתָּנִין בִּזְרִיקָה אַל יִתְּנֵם בִּשְׁפִיכָה לְכַתְּחִלָּה לְפִיכָךְ פְּטוּרִין מִפֶּסַח שֵׁנִי:"],"Mishneh Torah, Plaintiff and Defendant 14":["כָּל אֵלּוּ שֶׁאֵין אֲכִילָתָן רְאָיָה אִם הֵבִיאוּ עֵדִים שֶׁמָּכְרוּ לָהֶם הַבְּעָלִים שָׂדֶה זוֹ אוֹ נְתָנוּהָ לָהֶן בְּמַתָּנָה רְאָיָתָן רְאָיָה. חוּץ מִן הַגַּזְלָן וְהַבַּעַל בְּנִכְסֵי אִשְׁתּוֹ. בְּאֵי זֶה נְכָסִים אָמְרוּ בְּנִכְסֵי צֹאן בַּרְזֶל אוֹ בְּשָׂדֶה שֶׁיִּחֵד לָהּ בִּכְתֻבָּתָהּ וּבְשָׂדֶה שֶׁכָּתַב לָהּ בִּכְתֻבָּתָהּ וּבְשָׂדֶה שֶׁנָּתַן לָהּ בְּשׁוּם מִשֶּׁלּוֹ. אֲבָל בְּנִכְסֵי מְלוֹג יֵשׁ לוֹ רְאָיָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת אִישׁוּת:","כֵּיצַד הַגַּזְלָן אֵין לוֹ רְאָיָה. כֵּיוָן שֶׁהֻחְזַק גַּזְלָן עַל שָׂדֶה זוֹ אַף עַל פִּי שֶׁהֵבִיא רְאָיָה שֶׁהוֹדָה הַבַּעַל בִּפְנֵי עֵדִים שֶׁמָּכַר לוֹ שָׂדֶה זוֹ וְלָקַח דָּמִים וְהַבְּעָלִים אוֹמְרִים לֹא מָכַרְנוּ לְךָ אֶלָּא מִפְּנֵי הַיִּרְאָה הוֹדִינוּ לוֹ מוֹצִיאִין אֶת הַשָּׂדֶה מִיָּדוֹ וְאֵין לוֹ כְּלוּם. וְאִם הֵעִידוּ הָעֵדִים שֶׁבִּפְנֵיהֶם מָנָה לוֹ כָּךְ וְכָךְ מוֹצִיאִין אֶת הַשָּׂדֶה מִיַּד הַגַּזְלָן וּמַחְזִירִין לוֹ הַבְּעָלִים אֶת הַדָּמִים כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת גְּזֵלָה:","בֶּן הָאֻמָּן וּבֶן הָאָרִיס וְכֵן הָאַפּוֹטְרוֹפּוֹס שֶׁאָכְלוּ שָׂדֶה זוֹ שְׁנֵי חֲזָקָה. אִם טָעֲנוּ שֶׁהַבְּעָלִים מָכְרוּ לָהֶן אוֹ נָתְנוּ לָהֶן יֵשׁ לָהֶן חֲזָקָה. וְאִם טָעֲנוּ שֶׁהִיא יְרֻשָּׁה לָהֶן מֵאֲבִיהֶם שֶׁאֲכָלוּהָ שְׁנֵי חֲזָקָה אֵין לָהֶן חֲזָקָה. וְאִם הֵבִיאוּ עֵדִים שֶׁהוֹדוּ הַבְּעָלִים לַאֲבִיהֶן שֶׁמְּכָרוּהָ לָהֶן אוֹ נְתָנוּהָ מַעֲמִידִין אֶת הַשָּׂדֶה בְּיָדָן:","בֶּן הַגַּזְלָן אַף עַל פִּי שֶׁהֵבִיא רְאָיָה שֶׁהוֹדוּ הַבְּעָלִים לְאָבִיו שֶׁמָּכַר אֵינָהּ רְאָיָה כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל בֶּן בֶּן הַגַּזְלָן אֲפִלּוּ בָּא בְּטַעֲנַת אָבִיו יֵשׁ לוֹ חֲזָקָה בָּא בְּטַעֲנַת אֲבִי אָבִיו אֵין לוֹ חֲזָקָה:","הָעַכּוּ\"ם אֲפִלּוּ אֲכָלָהּ כַּמָּה שָׁנִים אֵין אֲכִילָתוֹ רְאָיָה. וְאִם לֹא הֵבִיא שְׁטָר תַּחְזֹר הַשָּׂדֶה לַבְּעָלִים בְּלֹא שׁוּם שְׁבוּעָה שֶׁלֹּא תִּקְּנוּ שְׁבוּעַת הֶסֵּת אֶלָּא לְיִשְׂרָאֵל וְיִשְׂרָאֵל הַבָּא מֵחֲמַת הָעַכּוּ\"ם הֲרֵי הוּא כְּעַכּוּ\"ם שֶׁאֵין אֲכִילָתוֹ רְאָיָה:","טָעַן זֶה הַיִּשְׂרָאֵל הַבָּא מֵחֲמַת הָעַכּוּ\"ם וְאָמַר בְּפָנַי לְקָחָהּ הָעַכּוּ\"ם שֶׁמָּכַר לִי מִזֶּה הַיִּשְׂרָאֵל הַמְעַרְעֵר עָלַי הֲרֵי זֶה נֶאֱמָן וְיִשָּׁבַע הֶסֵּת עַל כָּךְ מִתּוֹךְ שֶׁיָּכוֹל לוֹמַר אֲנִי לְקַחְתִּיהָ מִמְּךָ וַהֲרֵי אֲכַלְתִּיהָ שְׁנֵי חֲזָקָה יָכוֹל לוֹמַר מִפְּלוֹנִי לְקַחְתִּיהָ שֶׁבְּפָנַי לְקָחָהּ מִמְּךָ:","אֵין מַחֲזִיקִין בְּנִכְסֵי קָטָן וַאֲפִלּוּ הִגְדִּיל. כֵּיצַד. אֲכָלָהּ בְּפָנָיו כְּשֶׁהוּא קָטָן שָׁנָה אַחַת וּשְׁתַּיִם אַחַר שֶׁהִגְדִּיל וְטָעַן אַתָּה מָכַרְתָּ לִי אַתָּה נָתַתָּ לִי אֵין זֶה כְּלוּם עַד שֶׁיֹּאכַל שָׁלֹשׁ שָׁנִים רְצוּפוֹת אַחַר שֶׁהִגְדִּיל:","מִי שֶׁהֶחְזִיק בְּנִכְסֵי קָטָן שָׁנִים רַבּוֹת וְטָעַן וְאָמַר מַשְׁכּוֹנָה הֵן בְּיָדִי וְיֵשׁ לִי חוֹבָה עֲלֵיהֶן כָּךְ וְכָךְ. הוֹאִיל וְאִלּוּ רָצָה אָמַר לְקוּחִים הֵן בְּיָדִי נֶאֱמָן שֶׁהֲרֵי אֵינָהּ מֻחְזֶקֶת שֶׁהָיָה לְאָבִיו שֶׁל זֶה וַהֲרֵי זֶה גּוֹבֶה מִשִּׁבְחָהּ מַה שֶּׁטָּעַן וְתַחְזֹר לַיְתוֹמִים. אֲבָל אִם יָצָא עָלֶיהָ קוֹל שֶׁהִיא שֶׁל יְתוֹמִים אֵינוֹ נֶאֱמָן שֶׁהֲרֵי אֵין מַחֲזִיקִין בְּנִכְסֵי קָטָן וְתַחְזֹר הַשָּׂדֶה וְכָל הַפֵּרוֹת שֶׁאָכַל לַיְתוֹמִים עַד שֶׁיִּגְדְּלוּ וְיַעֲשֶׂה עִמָּהֶן דִּין:","אֲכָלָהּ שְׁנֵי חֲזָקָה בְּחַיֵּי אֲבִיהֶן מִתּוֹךְ שֶׁיָּכוֹל לוֹמַר לְקוּחָה הִיא בְּיָדִי מֵאֲבִיהֶן נֶאֱמָן לוֹמַר חוֹב יֵשׁ לִי עַל אֲבִיהֶן. וְגוֹבֶה אוֹתוֹ מִן הַפֵּרוֹת וְגוֹבֵהוּ שֶׁלֹּא בִּשְׁבוּעָה מִתּוֹךְ שֶׁיָּכוֹל לוֹמַר שֶׁלִּי הֵן:","בּוֹרֵחַ שֶׁבָּרַח מֵחֲמַת סַכָּנַת נְפָשׁוֹת כְּגוֹן שֶׁהָיָה הַמֶּלֶךְ מְבַקֵּשׁ לַהֲמִיתוֹ. אֵין מַחֲזִיקִין בִּנְכָסָיו אֲפִלּוּ אָכַל הַמַּחֲזִיק כַּמָּה שָׁנִים וְטָעַן שֶׁלָּקַח אֵין אֲכִילָתוֹ רְאָיָה. וְאֵין אוֹמְרִים לְבַעַל הַשָּׂדֶה לָמָּה לֹא מָחִיתָ מִפְּנֵי שֶׁהוּא מִתְעַסֵּק בְּנַפְשׁוֹ. אֲבָל הַבּוֹרֵחַ מֵחֲמַת מָמוֹן הֲרֵי הוּא כְּכָל אָדָם וְאִם לֹא מִחָה מַחֲזִיקִין בִּנְכָסָיו:","מַחֲזִיקִין בְּנִכְסֵי אֵשֶׁת אִישׁ. כֵּיצַד. אֲכָלָהּ מִקְצָת שְׁנֵי חֲזָקָה בְּחַיֵּי הַבַּעַל וְשָׁלֹשׁ שָׁנִים אַחַר מִיתַת הַבַּעַל. וְטָעַן וְאָמַר מְכַרְתָּהּ לִי אַתְּ וּבַעֲלֵךְ מַעֲמִידִין אוֹתָהּ בְּיָדוֹ מִתּוֹךְ שֶׁיָּכוֹל לוֹמַר מִמֵּךְ לְקַחְתִּיהָ אַחַר מוֹת בַּעֲלִיךְ שֶׁהֲרֵי אֲכָלָהּ שְׁנֵי חֲזָקָה אַחַר מִיתַת הַבַּעַל וְלֹא מִחֵת בּוֹ. אֲבָל אִם אֲכָלָהּ בְּחַיֵּי בַּעְלָהּ כַּמָּה שָׁנִים וְלֹא אֲכָלָהּ שְׁנֵי חֲזָקָה אַחַר מִיתַת בַּעְלָהּ אֵין לוֹ חֲזָקָה:","כָּל חֲזָקָה שֶׁאֵין עִמָּהּ טַעֲנָה אֵינָהּ חֲזָקָה. כֵּיצַד. הֲרֵי שֶׁאָכַל פֵּרוֹת שָׂדֶה זוֹ כַּמָּה שָׁנִים וּבָא הַמְעַרְעֵר וְאָמַר לוֹ מֵאַיִן לְךָ שָׂדֶה זוֹ שֶׁלִּי הִיא הֱשִׁיבוֹ וְאָמַר לוֹ אֵינִי יוֹדֵעַ שֶׁל מִי הִיא וְכֵיוָן שֶׁלֹּא אָמַר לִי אָדָם כְּלוּם יָרַדְתִּי לְתוֹכָהּ. אֵין זוֹ חֲזָקָה שֶׁהֲרֵי לֹא טָעַן שֶׁלְּקָחָהּ וְלֹא שֶׁנְּתָנָהּ לוֹ וְלֹא שֶׁיְּרָשָׁהּ. וְאַף עַל פִּי שֶׁלֹּא טָעַן אֵין מוֹצִיאִין אוֹתָהּ מִיָּדוֹ עַד שֶׁיָּבִיא זֶה הַמְעַרְעֵר עֵדִים שֶׁהִיא שֶׁלּוֹ. הֵבִיא עֵדִים תַּחְזֹר לוֹ הַשָּׂדֶה וּמוֹצִיאִין מִזֶּה כָּל הַפֵּרוֹת שֶׁאָכַל וְאֵין פּוֹתְחִין לָזֶה הַמַּחֲזִיק תְּחִלָּה וְאֵין אוֹמְרִים שֶׁמָּא שְׁטָר הָיָה לְךָ וְאָבַד עַד שֶׁיִּטְעֹן מֵעַצְמוֹ וְאִם לֹא טָעַן יַחְזִיר כָּל הַפֵּרוֹת שֶׁאָכַל. וְכֵן הָאוֹכֵל שְׁנֵי חֲזָקָה מֵחֲמַת שֶׁיֵּשׁ שְׁטָר בְּיָדוֹ וְנִמְצָא הַשְּׁטָר בָּטֵל בָּטְלָה הַחֲזָקָה וְתַחְזֹר הַשָּׂדֶה עִם כָּל הַפֵּרוֹת לַבְּעָלִים:","הַבָּא מֵחֲמַת יְרֻשָּׁה צָרִיךְ לְהָבִיא רְאָיָה שֶׁדָּר אָבִיו בְּשָׂדֶה זוֹ אוֹ נִשְׁתַּמֵּשׁ בָּהּ אֲפִלּוּ יוֹם אֶחָד וְכֵיוָן שֶׁאֲכָלָהּ הוּא שָׁלֹשׁ שָׁנִים מֵחֲמַת אָבִיו מַעֲמִידִין אוֹתָהּ בְּיָדוֹ. אֲבָל אִם לֹא הֵבִיא רְאָיָה שֶׁדָּר בָּהּ אָבִיו כְּלָל תַּחְזֹר הַשָּׂדֶה וְכָל הַפֵּרוֹת לַמְעַרְעֵר שֶׁיֵּשׁ לוֹ עֵדִים שֶׁהוּא שֶׁלּוֹ. שֶׁהֲרֵי אֵינוֹ טוֹעֵן עָלָיו שֶׁמָּכַר אוֹ נָתַן לוֹ וְלֹא נוֹדְעָה קַרְקַע זוֹ לַאֲבוֹתָיו. הֵבִיא רְאָיָה שֶׁנִּרְאָה בָּהּ אָבִיו אֵינָהּ כְּלוּם שֶׁמָּא בָּא לְבַקֵּר אוֹתָהּ וְלֹא קְנָאָהּ. אֶלָּא צָרִיךְ לְהָבִיא רְאָיָה שֶׁדָּר אָבִיו בָּהּ אֲפִלּוּ יוֹם אֶחָד:","הֲרֵי שֶׁאָכַל שָׂדֶה זוֹ שָׁנִים רַבּוֹת וּבָא הַמְעַרְעֵר וְאָמַר לוֹ מַה לְּךָ וּלְשָׂדֶה זוֹ הוֹדָה וְאָמַר לוֹ יוֹדֵעַ אֲנִי שֶׁהָיְתָה שֶׁלְּךָ אֲבָל פְּלוֹנִי מְכָרָהּ לִי וְהוּא לְקָחָהּ מִמְּךָ. וְאָמַר לוֹ הַמְעַרְעֵר פְּלוֹנִי שֶׁמָּכַר לְךָ גַּזְלָן הוּא. הוֹאִיל וְהוֹדָה שֶׁהִיא שֶׁלּוֹ וְשֶׁלֹּא לְקָחָהּ מִמֶּנּוּ תַּחְזֹר הַשָּׂדֶה וְכָל הַפֵּרוֹת לַמְעַרְעֵר אַף עַל פִּי שֶׁאֵין לְזֶה הַמְעַרְעֵר עֵדִים שֶׁהִיא שֶׁלּוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. הֵבִיא זֶה הַמַּחֲזִיק עֵדִים שֶׁפְּלוֹנִי שֶׁמָּכַר לוֹ דָּר בָּהּ אֲפִלּוּ יוֹם אֶחָד אוֹ שֶׁאָמַר לוֹ בְּפָנַי לָקַח מִמְּךָ וְאַחַר כָּךְ מְכָרָהּ לִי. מַעֲמִידִין אוֹתָהּ בְּיָדוֹ שֶׁהֲרֵי יֵשׁ לוֹ טַעֲנָה עִם חֶזְקָתוֹ וְאִלּוּ רָצָה טָעַן וְאָמַר מִמְּךָ לְקַחְתִּיהָ שֶׁהֲרֵי יֵשׁ לוֹ שְׁנֵי חֲזָקָה:"],"Mishneh Torah, Positive Mitzvot 10":["לִקְרוֹת קִרְיַת שְׁמַע פַּעֲמַיִם בְּכָל יוֹם, שֶׁנֶּאֱמָר: \"וְדִבַּרְתָּ בָּם בְּשִׁבְתְּךָ בְּבֵיתֶךָ וּבְלֶכְתְּךָ בַדֶּרֶךְ וּבְשָׁכְבְּךָ וּבְקוּמֶךָ\" (דברים ו, ז)."],"Mishneh Torah, Positive Mitzvot 110":["להיות הטהרה מן הצרעת בין צרעת אדם בין צרעת בית בעץ ארז ואיזוב ושני תולעת ושתי ציפורים ומים חיים, שנאמר: \"זֹאת תִּהְיֶה תּוֹרַת הַמְּצֹרָע\" (ויקרא יד, ב)."],"Mishneh Torah, Positive Mitzvot 121":["להניח לקט."],"Mishneh Torah, Positive Mitzvot 132":["לקרות על הביכורים, שנאמר: \"וענית ואמרת לפני ה' אלוהיך\" (דברים כו,ה)."],"Mishneh Torah, Positive Mitzvot 143":["ליתן מן הבהמה לכוהן הזרוע והלחיים והקיבה, שנאמר: \"ונתן, לכוהן, הזרוע\" (דברים יח,ג)."],"Mishneh Torah, Positive Mitzvot 154":["לשבות בשבת, שנאמר: \"וביום השביעי תשבות\" (שמות כג,יב; שמות לד,כא)."],"Mishneh Torah, Positive Mitzvot 165":["לשבות ביום הצום, שנאמר: \"שבת שבתון\" (ויקרא טז,לא; ויקרא כג,לב)."],"Mishneh Torah, Positive Mitzvot 176":["למנות שופטים ושוטרים בכל קהל וקהל מישראל, שנאמר: \"שופטים ושוטרים, תיתן לך\" (דברים טז,יח)."],"Mishneh Torah, Positive Mitzvot 187":["לאבד שבעה עממים מארץ ישראל, שנאמר: \"החרם תחרימם\" (דברים כ,יז)."],"Mishneh Torah, Positive Mitzvot 198":["להלוות לנוכרי בריבית, שנאמר: \"לנוכרי תשיך\" (דברים כג,כא); מפי השמועה למדו שזו מצות עשה."],"Mishneh Torah, Positive Mitzvot 208":["לצדק מאזניים עם המשקלות, שנאמר: \"מאזני צדק אבני צדק\" (ויקרא יט, לו)."],"Mishneh Torah, Positive Mitzvot 219":["לישב מוציא שם רע עם אשתו כל ימיו, שנאמר: \"ולו תהיה לאישה\" (דברים כב,יט)."],"Mishneh Torah, Positive Mitzvot 23":["לִהְיוֹת הַלֵּוִי עוֹבֵד בַּמִּקְדָּשׁ, שֶׁנֶּאֱמָר: \"וְעָבַד הַלֵּוִי הוּא\" (במדבר יח, כג)."],"Mishneh Torah, Positive Mitzvot 240":["לדון בנזקי הבער, שנאמר: \"כי יבער איש, שדה או כרם\" (שמות כב,ד)."],"Mishneh Torah, Positive Mitzvot 28":["לְהַקְטִיר קְטֹרֶת פַּעֲמַיִם בַּיּוֹם, שֶׁנֶּאֱמָר: \"וְהִקְטִיר עָלָיו אַהֲרֹן קְטֹרֶת סַמִּים\" (שמות ל, ז)."],"Mishneh Torah, Positive Mitzvot 39":["להקריב תמידין בכל יום, שנאמר: \"שְׁנַיִם לַיּוֹם עוֹלָה תָמִיד\" (במדבר כח, ג)."],"Mishneh Torah, Positive Mitzvot 5":["לְהִתְפַּלַּל לוֹ, שֶׁנֶּאֱמָר: \"וַעֲבַדְתֶּם, אֵת ה' אֱלֹהֵיכֶם\" (שמות כג, כה) – עֲבוֹדָה זוֹ תְּפִלָּה."],"Mishneh Torah, Positive Mitzvot 60":["להיות כל קרבנות בהמה מיום שמיני והלאה, שנאמר: \"מִיּוֹם הַשְּׁמִינִי וָהָלְאָה\" (ויקרא כב, כז)."],"Mishneh Torah, Positive Mitzvot 71":["להקריב השוגג במעילה, או החוטא בגזילה, או בשפחה חרופה, או שכפר בפיקדון ונשבע; מביא קרבן אשם, וזה הוא הנקרא אשם ודאי."],"Mishneh Torah, Positive Mitzvot 82":["לערוף פטר חמור, שנאמר: \"ואם לא תפדה וערפתו\" (שמות יג,יג; שמות לד,כ)."],"Mishneh Torah, Positive Mitzvot 93":["לגלח הנזיר שערו על קרבנותיו במלאות ימי נזרו, או בתוך ימי נזרו אם נטמא, שנאמר: \"וכי ימות מת עליו\" (במדבר ו,ט)."],"Mishneh Torah, Prayer and the Priestly Blessing 14":["בְּשַׁחֲרִית בְּמוּסָף וּבִנְעִילה הַכֹּהֲנִים נוֹשְׂאִים אֶת כַּפֵּיהֶם. אֲבָל בְּמִנְחָה אֵין נְשִׂיאַת כַּפַּיִם. מִפְּנֵי שֶׁבְּמִנְחָה כְּבָר סָעֲדוּ כָּל הָעָם וְשֶׁמָּא שָׁתוּ הַכֹּהֲנִים יַיִן וְשִׁכּוֹר אָסוּר בִּנְשִׂיאַת כַּפַּיִם. וַאֲפִלּוּ בְּיוֹם תַּעֲנִית אֵין נוֹשְׂאִין כַּפֵּיהֶן בְּמִנְחָה גְּזֵרָה מִנְחַת תַּעֲנִית מִפְּנֵי מִנְחַת כָּל יוֹם:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּתַעֲנִיּוֹת שֶׁמִּתְפַּלְּלִין בּוֹ מִנְחָה וּנְעִילָה כְּגוֹן צוֹם כִּפּוּר וְתַעֲנִית צִבּוּר. אֲבָל תַּעֲנִית שֶׁאֵין בּוֹ נְעִילָה כְּגוֹן תִּשְׁעָה בְּאָב וְשִׁבְעָה עָשָׂר בְּתַמּוּז הוֹאִיל וּתְפִלַּת מִנְחָה שֶׁלָּהֶם סָמוּךְ לִשְׁקִיעַת הַחַמָּה הֲרֵי נִרְאֵית כִּנְעִילָה וְאֵינָהּ מִתְחַלֶּפֶת בְּמִנְחָה שֶׁל כָּל יוֹם. וּלְפִיכָךְ יֵשׁ בָּהּ נְשִׂיאַת כַּפַּיִם. וְכֹהֵן שֶׁעָבַר וְעָלָה לַדּוּכָן בְּמִנְחָה שֶׁל יוֹם הַכִּפּוּרִים הוֹאִיל וְהַדָּבָר יָדוּעַ שֶׁאֵין שָׁם שִׁכְרוּת הֲרֵי זֶה נוֹשֵׂא כַּפָּיו וְאֵין מוֹרִידִין אוֹתוֹ מִפְּנֵי הַחֲשָׁד שֶׁלֹּא יֹאמְרוּ פָּסוּל הָיָה לְפִיכָךְ הוֹרִידוּהוּ:","כֵּיצַד הִיא נְשִׂיאַת כַּפַּיִם בַּגְּבוּלִין. בְּעֵת שֶׁיַּגִּיעַ שְׁלִיחַ צִבּוּר לַעֲבוֹדָה כְּשֶׁיֹּאמַר רְצֵה כָּל הַכֹּהֲנִים הָעוֹמְדִים בְּבֵית הַכְּנֶסֶת נֶעֱקָרִין מִמְּקוֹמָן וְהוֹלְכִין וְעוֹלִין לַדּוּכָן וְעוֹמְדִים שָׁם פְּנֵיהֶם לַהֵיכָל וַאֲחוֹרֵיהֶם כְּלַפֵּי הָעָם וְאֶצְבְּעוֹתֵיהֶם כְּפוּפוֹת לְתוֹךְ כַּפֵּיהֶם עַד שֶׁיַּשְׁלִים שְׁלִיחַ צִבּוּר הַהוֹדָאָה וּמַחְזִירִין פְּנֵיהֶם כְּלַפֵּי הָעָם וּפוֹשְׁטִין אֶצְבְּעוֹתֵיהֶן וּמַגְבִּיהִין יְדֵיהֶם כְּנֶגֶד כִּתְפֵיהֶם וּמַתְחִילִין (במדבר ו כד) ״יְבָרֶכְךָ״. וּשְׁלִיחַ צִבּוּר מַקְרֵא אוֹתָם מִלָּה מִלָּה וְהֵם עוֹנִין שֶׁנֶּאֱמַר (במדבר ו כג) ״אָמוֹר לָהֶם״ עַד שֶׁיֹּאמַר. כְּשֶׁמַּשְׁלִימִין פָּסוּק רִאשׁוֹן כָּל הָעָם עוֹנִין אָמֵן. וְחוֹזֵר שְׁלִיחַ צִבּוּר וּמַקְרֵא אוֹתָן פָּסוּק שֵׁנִי מִלָּה מִלָּה וְהֵם עוֹנִים עַד שֶׁמַּשְׁלִימִין פָּסוּק שֵׁנִי וְכָל הָעָם עוֹנִין אָמֵן. וְכֵן בְּפָסוּק שְׁלִישִׁי:","כְּשֶׁיַּשְׁלִימוּ הַכֹּהֲנִים שְׁלֹשָׁה פְּסוּקִים מַתְחִיל שְׁלִיחַ צִבּוּר בְּרָכָה אַחֲרוֹנָה שֶׁל תְּפִלָּה שֶׁהִיא שִׂים שָׁלוֹם וְהַכֹּהֲנִים מַחְזִירִין פְּנֵיהֶם כְּלַפֵּי הַקֹּדֶשׁ וְקוֹפְצִין אֶצְבְּעוֹתֵיהֶן וְעוֹמְדִין שָׁם בַּדּוּכָן עַד שֶׁיִּגְמֹר הַבְּרָכָה וְחוֹזְרִין לִמְקוֹמָן:","אֵין הַמַּקְרֵא רַשַּׁאי (לְהַקְרוֹת לַכֹּהֲנִים) עַד שֶׁיִּכְלֶה אָמֵן מִפִּי הַצִּבּוּר. וְאֵין הַכֹּהֲנִים רַשָּׁאִין לְהַתְחִיל בַּבְּרָכָה עַד שֶׁיִּכְלֶה הַדִּבּוּר מִפִּי הַמַּקְרֵא. וְאֵין הַצִּבּוּר עוֹנִין אָמֵן עַד שֶׁתִּכְלֶה הַבְּרָכָה מִפִּי הַכֹּהֲנִים. וְאֵין הַכֹּהֲנִים מַתְחִילִין בִּבְרָכָה אַחֶרֶת עַד שֶׁיִּכְלֶה אָמֵן מִפִּי הַצִּבּוּר. וְאֵין שְׁלִיחַ צִבּוּר רַשַּׁאי לַעֲנוֹת אָמֵן אַחַר הַכֹּהֲנִים כִּשְׁאָר הָעָם שֶׁמָּא תִּטָּרֵף דַּעְתּוֹ וְלֹא יֵדַע אֵיזוֹ בְּרָכָה מַקְרֵא אוֹתָן, אִם פָּסוּק שֵׁנִי אוֹ פָּסוּק שְׁלִישִׁי:","אֵין הַכֹּהֲנִים רַשָּׁאִין לְהַחֲזִיר פְּנֵיהֶם מִן הַצִּבּוּר עַד שֶׁיַּתְחִיל שְׁלִיחַ צִבּוּר שִׂים שָׁלוֹם. וְאֵין הַכֹּהֲנִים רַשָּׁאִין לֵעָקֵר מִמְּקוֹמָן עַד שֶׁיִּגְמֹר שְׁלִיחַ צִבּוּר שִׂים שָׁלוֹם. וְאֵין רַשָּׁאִין לָכֹף קִשְׁרֵי אֶצְבְּעוֹתֵיהֶם עַד שֶׁיַּחֲזִירוּ פְּנֵיהֶם מִן הַצִּבּוּר. וּמִתַּקָּנוֹת [ עֶזְרָא] שֶׁלֹּא יַעֲלוּ הַכֹּהֲנִים לַדּוּכָן בְּסַנְדְּלֵיהֶן אֶלָּא עוֹמְדִין יְחֵפִין:","כְּשֶׁיִּהְיוּ הַכֹּהֲנִים מְבָרְכִין אֶת הָעָם לֹא יַבִּיטוּ בָּעָם וְלֹא יַסִּיחוּ דַּעְתָּן אֶלָּא יִהְיוּ עֵינֵיהֶם כְּנֶגֶד הָאָרֶץ כְּעוֹמֵד בִּתְפִלָּה. וְאֵין אָדָם רַשַּׁאי לְהִסְתַּכֵּל בִּפְנֵי הַכֹּהֲנִים בְּשָׁעָה שֶׁהֵן מְבָרְכִין אֶת הָעָם כְּדֵי שֶׁלֹּא יַסִּיחוּ דַּעְתָּם. אֶלָּא כָּל הָעָם מִתְכַּוְּנִין לִשְׁמֹעַ הַבְּרָכָה וּמְכַוְּנִים פְּנֵיהֶם כְּנֶגֶד פְּנֵי הַכֹּהֲנִים וְאֵינָם מַבִּיטִים בִּפְנֵיהֶם:","אִם הָיָה הַכֹּהֵן הַמְבָרֵךְ אֶחָד מַתְחִיל לְבָרֵךְ מֵעַצְמוֹ. וּשְׁלִיחַ צִבּוּר מַקְרֵא אוֹתוֹ מִלָּה מִלָּה כְּמוֹ שֶׁאָמַרְנוּ. הָיוּ שְׁנַיִם אוֹ יוֹתֵר אֵינָן מַתְחִילִין לְבָרֵךְ עַד שֶׁיִּקְרָא לָהֶם שְׁלִיחַ צִבּוּר וְאוֹמֵר לָהֶם כֹּהֲנִים וְהֵם עוֹנִין וְאוֹמְרִים (במדבר ו כד) ״יְבָרֶכְךָ״. וְהוּא מַקְרֵא אוֹתָן מִלָּה מִלָּה עַל הַסֵּדֶר שֶׁאָמַרְנוּ:","כֵּיצַד בִּרְכַּת כֹּהֲנִים בַּמִּקְדָּשׁ. הַכֹּהֲנִים עוֹלִין לַדּוּכָן אַחַר שֶׁיַּשְׁלִימוּ הַכֹּהֲנִים עֲבוֹדַת תָּמִיד שֶׁל שַׁחַר. וּמַגְבִּיהִין יְדֵיהֶם לְמַעְלָה עַל גַּבֵּי רָאשֵׁיהֶן וְאֶצְבְּעוֹתֵיהֶן פְּשׁוּטוֹת. חוּץ מִכֹּהֵן גָּדוֹל שֶׁאֵין מַגְבִּיהַּ יָדָיו לְמַעְלָה מִן הַצִּיץ. וְאֶחָד מַקְרֵא אוֹתָן מִלָּה מִלָּה כְּדֶרֶךְ שֶׁעוֹשִׂין בַּגְּבוּלִין עַד שֶׁיַּשְׁלִימוּ שְׁלֹשָׁה הַפְּסוּקִים. וְאֵין הָעָם עוֹנִין אַחַר כָּל פָּסוּק אֶלָּא עוֹשִׂין אוֹתָהּ בַּמִּקְדָּשׁ בְּרָכָה אַחַת. וּכְשֶׁיַּשְׁלִימוּ כָּל הָעָם עוֹנִים בָּרוּךְ יְיָ׳‎ אֱלֹהִים אֱלֹהֵי יִשְׂרָאֵל מִן הָעוֹלָם וְעַד הָעוֹלָם:","וְאוֹמֵר אֶת הַשֵּׁם כִּכְתָבוֹ וְהוּא הַשֵּׁם הַנֶּהְגֶּה מִיּוּ״ד הֵ״א וָא״ו הֵ״א. וְזֶה הוּא הַשֵּׁם הַמְפֹרָשׁ הָאָמוּר בְּכָל מָקוֹם. וּבַמְּדִינָה אוֹמְרִים אוֹתוֹ בְּכִנּוּיוֹ וְהוּא בְּאָלֶ״ף דָּלֶ״ת. שֶׁאֵין מַזְכִּירִין אֶת הַשֵּׁם כִּכְתָבוֹ אֶלָּא בַּמִּקְדָּשׁ בִּלְבַד. וּמִשֶּׁמֵּת שִׁמְעוֹן הַצַּדִּיק פָּסְקוּ הַכֹּהֲנִים מִלְּבָרֵךְ בַּשֵּׁם הַמְפֹרָשׁ אֲפִלּוּ בַּמִּקְדָּשׁ כְּדֵי שֶׁלֹּא יִלְמֹד אוֹתוֹ אָדָם שֶׁאֵינוֹ חָשׁוּב וְשֶׁאֵינוֹ הָגוּן. וְלֹא הָיוּ חֲכָמִים הָרִאשׁוֹנִים מְלַמְּדִין שֵׁם זֶה לְתַלְמִידֵיהֶם וּבְנֵיהֶם הַהֲגוּנִים אֶלָּא פַּעַם אַחַת לְשֶׁבַע שָׁנִים. כָּל זֶה גְּדֻלָּה לִשְׁמוֹ הַנִּכְבָּד וְהַנּוֹרָא:","אֵין בִּרְכַּת כֹּהֲנִים נֶאֱמֶרֶת בְּכָל מָקוֹם אֶלָּא בִּלְשׁוֹן הַקֹּדֶשׁ שֶׁנֶּאֱמַר (במדבר ו כג) ״כֹּה תְבָרַכוּ אֶת בְּנֵי יִשְׂרָאֵל״. כָּךְ לָמְדוּ מִפִּי הַשְּׁמוּעָה מִמּשֶׁה רַבֵּנוּ עָלָיו הַשָּׁלוֹם כֹּה תְּבָרְכוּ בַּעֲמִידָה. כֹּה תְּבָרְכוּ בִּנְשִׂיאַת כַּפַּיִם. כֹּה תְּבָרְכוּ בִּלְשׁוֹן הַקֹּדֶשׁ. כֹּה תְּבָרְכוּ פָּנִים כְּנֶגֶד פָּנִים. כֹּה תְּבָרְכוּ בְּקוֹל רָם. כֹּה תְּבָרְכוּ בְּשֵׁם הַמְפֹרָשׁ. וְהוּא שֶׁיִּהְיֶה בַּמִּקְדָּשׁ כְּמוֹ שֶׁאָמַרְנוּ:","אֵין הַכֹּהֲנִים רַשָּׁאִין בְּכָל מָקוֹם לְהוֹסִיף בְּרָכָה עַל שְׁלֹשֶׁת הַפְּסוּקִים כְּגוֹן (דברים א יא) ״יְיָ׳‎ אֱלֹהֵי אֲבוֹתֵיכֶם יוֹסֵף עֲלֵיכֶם כָּכֶם אֶלֶף פְּעָמִים״ וְכַיּוֹצֵא בָּהּ לֹא בְּקוֹל רָם וְלֹא בְּלַחַשׁ שֶׁנֶּאֱמַר (דברים ד ב) ״לֹא תּוֹסִיפוּ עַל הַדָּבָר״. בְּשָׁעָה שֶׁכָּל כֹּהֵן עוֹלֶה לַדּוּכָן כְּשֶׁהוּא עוֹקֵר רַגְלָיו לַעֲלוֹת אוֹמֵר יְהִי רָצוֹן מִלְּפָנֶיךָ יְיָ׳‎ אֱלֹהֵינוּ שֶׁתִּהְיֶה בְּרָכָה זוֹ שֶׁצִּוִּיתָנוּ לְבָרֵךְ אֶת עַמְּךָ יִשְׂרָאֵל בְּרָכָה שְׁלֵמָה וְאַל יְהִי בָּהּ מִכְשׁוֹל וְעָוֹן מֵעַתָּה וְעַד עוֹלָם. וְקֹדֶם שֶׁיַּחֲזִיר פָּנָיו לְבָרֵךְ אֶת הָעָם מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בִּקְדֻשָּׁתוֹ שֶׁל אַהֲרֹן וְצִוָּנוּ לְבָרֵךְ אֶת עַמּוֹ יִשְׂרָאֵל בְּאַהֲבָה. וְאַחַר כָּךְ מַחֲזִיר פָּנָיו לַצִּבּוּר וּמַתְחִיל לְבָרְכָם. וּכְשֶׁמַּחֲזִיר פָּנָיו מִן הַצִּבּוּר אַחַר שֶׁמַּשְׁלִים אוֹמֵר עָשִׂינוּ מַה שֶּׁגָּזַרְתָּ עָלֵינוּ עֲשֵׂה עִמָּנוּ מַה שֶּׁהִבְטַחְתָּנוּ (דברים כו טו) ״הַשְׁקִיפָה מִמְּעוֹן קָדְשְׁךָ מִן הַשָּׁמַיִם וּבָרֵךְ אֶת עַמְּךָ אֶת יִשְׂרָאֵל״:","כְּשֶׁמַּחְזִירִין הַכֹּהֲנִים אֶת פְּנֵיהֶם לַצִּבּוּר לְבָרְכָם וּכְשֶׁמַּחְזִירִין פְּנֵיהֶם מִן הַצִּבּוּר אַחַר שֶׁמְּבָרְכִין לֹא יַחֲזִירוּ אֶלָּא עַל דֶּרֶךְ יָמִין בְּכָל מָקוֹם. וְכֵן כָּל פִּנּוֹת שֶׁיִּהְיֶה אָדָם פּוֹנֶה לֹא יִהְיוּ אֶלָּא עַל דֶּרֶךְ יָמִין:","בַּמִּקְדָּשׁ מְבָרְכִין בִּרְכַּת כֹּהֲנִים פַּעַם אַחַת בְּיוֹם אַחַר תָּמִיד שֶׁל שַׁחַר. בָּאִין וְעוֹמְדִין עַל מַעֲלוֹת הָאוּלָם וּמְבָרְכִין כְּדֶרֶךְ שֶׁאָמַרְנוּ. אֲבָל בַּמְּדִינָה מְבָרְכִין אוֹתָהּ אַחַר כָּל תְּפִלָּה חוּץ מִמִּנְחָה כְּמוֹ שֶׁאָמַרְנוּ. בְּכָל מָקוֹם מִשְׁתַּדְּלִין שֶׁיִּהְיֶה הַמַּקְרֵא אוֹתָן יִשְׂרָאֵל שֶׁנֶּאֱמַר (במדבר ו כג) ״אָמוֹר לָהֶם״ מִכְּלָל שֶׁאֵין הַמַּקְרֵא מֵהֶם:"],"Mishneh Torah, Reading the Shema 3":["הַקוֹרֵא אֶת שְׁמַע רוֹחֵץ יָדָיו בַּמַּיִם קֹדֶם שֶׁיִּקְרָא. הִגִּיעַ זְמַן קְרִיאָתָהּ וְלֹא מָצָא מַיִם קֹדֶם שֶׁיִּקְרָא לֹא יְאַחֵר קְרִיאָתָהּ וְיֵלֵךְ לְבַקֵּשׁ מַיִם אֶלָּא מְקַנֵּחַ יָדָיו בֶּעָפָר אוֹ בִּצְרוֹר אוֹ בְּקוֹרָה וְכַיּוֹצֵא בָּהֶן וְקוֹרֵא:","אֵין קוֹרִין לֹא בְּבֵית הַמֶּרְחָץ וְלֹא בְּבֵית הַכִּסֵּא אַף עַל פִּי שֶׁאֵין בּוֹ צוֹאָה וְלֹא בְּבֵית הַקְּבָרוֹת וְלֹא בְּצַד הַמֵּת עַצְמוֹ וְאִם הִרְחִיק אַרְבַּע אַמּוֹת מִן הַקֶּבֶר אוֹ מִן הַמֵּת מֻתָּר לִקְרוֹת. וְכָל מִי שֶׁקָּרָא בְּמָקוֹם שֶׁאֵין קוֹרִין בּוֹ חוֹזֵר וְקוֹרֵא:","בֵּית הַכִּסֵּא הֶחָדָשׁ שֶׁהוּכַן וַעֲדַיִן לֹא נִשְׁתַּמֵּשׁ בּוֹ מֻתָּר לִקְרוֹת קְרִיאַת שְׁמַע לְנֶגְדּוֹ אֲבָל לֹא בְּתוֹכוֹ. מֶרְחָץ הֶחָדָשׁ מֻתָּר לִקְרוֹת בְּתוֹכוֹ. הָיוּ שְׁנֵי בָּתִּים זִמֵּן אֶחָד מֵהֶם לְבֵית הַכִּסֵּא וְאָמַר עַל הַשֵּׁנִי וְזֶה. הֲרֵי הַשֵּׁנִי סָפֵק אִם הִזְמִינוֹ לְכָךְ אִם לֹא. לְפִיכָךְ אֵין קוֹרִין בּוֹ לְכַתְּחִלָּה וְאִם קָרָא יָצָא. אָמַר גַּם זֶה הֲרֵי שְׁנֵיהֶם מְזֻמָּנִין וְאֵין קוֹרְאִין בָּהֶן. חֲצַר הַמֶּרְחָץ וְהוּא הַמָּקוֹם שֶׁבְּנֵי אָדָם עוֹמְדִין בּוֹ לְבוּשִׁין מֻתָּר לִקְרוֹת בּוֹ קְרִיאַת שְׁמַע:","וְלֹא קְרִיאַת שְׁמַע בִּלְבַד אֶלָּא כָּל עִנְיָן שֶׁהוּא מִדִּבְרֵי הַקֹּדֶשׁ אָסוּר לְאָמְרוֹ בְּבֵית הַמֶּרְחָץ וּבְבֵית הַכִּסֵּא וַאֲפִלּוּ אֲמָרוֹ בִּלְשׁוֹן חֹל. וְלֹא לְאָמְרוֹ בִּלְבַד אֶלָּא אֲפִלּוּ לְהַרְהֵר בְּלִבּוֹ בְּדִבְרֵי תּוֹרָה בְּבֵית הַכִּסֵּא וּבְבֵית הַמֶּרְחָץ וּבִמְקוֹם הַטִּנֹפֶת וְהוּא הַמָּקוֹם שֶׁיֵּשׁ בּוֹ צוֹאָה וּמֵי רַגְלַיִם אָסוּר:","דְּבָרִים שֶׁל חֹל מֻתָּר לְאָמְרָן בִּלְשׁוֹן קֹדֶשׁ בְּבֵית הַכִּסֵּא. וְכֵן הַכִּנּוּיִים כְּגוֹן רַחוּם וְחַנּוּן וְנֶאֱמָן וְכַיּוֹצֵא בָּהֶן מֻתָּר לְאָמְרָן בְּבֵית הַכִּסֵּא. אֲבָל הַשֵּׁמוֹת הַמְיֻחָדִים וְהֵן הַשֵּׁמוֹת שֶׁאֵינָן נִמְחָקִין אָסוּר לְהַזְכִּירָן בְּבֵית הַכִּסֵּא וּבְבֵית הַמֶּרְחָץ יָשָׁן. וְאִם נִזְדַּמֵּן לוֹ לְהַפְרִישׁ מִן דָּבָר הָאָסוּר בְּבֵית הַמֶּרְחָץ אוֹ בְּבֵית הַכִּסֵּא מַפְרִישׁ וַאֲפִלּוּ בִּלְשׁוֹן קֹדֶשׁ וּבְעִנְיְנֵי קֹדֶשׁ:","צוֹאַת הָאָדָם וְצוֹאַת כְּלָבִים וַחֲזִירִין בִּזְמַן שֶׁיֵּשׁ בְּתוֹכָן עוֹרוֹת וְכָל צוֹאָה שֶׁרֵיחָהּ רַע כְּגוֹן אֵלּוּ אָסוּר לִקְרוֹת קְרִיאַת שְׁמַע כְּנֶגְדָּן. וְכֵן כְּנֶגֶד מֵי רַגְלַיִם שֶׁל אָדָם. אֲבָל מֵי רַגְלַיִם שֶׁל בְּהֵמָה קוֹרִין כְּנֶגְדָּן. קָטָן שֶׁאֵינוֹ יָכוֹל לֶאֱכל כְּזַיִת דָּגָן בִּכְדֵי שֶׁיֹּאכַל הַגָּדוֹל כִּשְׁלֹשָׁה בֵּיצֵי דָּגָן אֵין מַרְחִיקִין לֹא מִצּוֹאָתוֹ וְלֹא מִמֵּי רַגְלָיו:","הָיְתָה צוֹאָה יְבֵשָׁה כְּחֶרֶשׂ אָסוּר לִקְרוֹת כְּנֶגְדָּהּ. וְאִם הָיְתָה יְבֵשָׁה יוֹתֵר מֵחֶרֶשׂ עַד שֶׁאִם זְרָקָהּ תִּתְפָּרֵךְ הֲרֵי הִיא כְּעָפָר וּמֻתָּר לִקְרוֹת כְּנֶגְדָּהּ. מֵי רַגְלַיִם שֶׁנִּבְלְעוּ בַּקַּרְקַע אִם הָיוּ מַרְטִיבִין הַיָּד אָסוּר לִקְרוֹת כְּנֶגְדָּן וְאִם לָאו מֻתָּר:","כַּמָּה יַרְחִיק אָדָם מִצּוֹאָה וּמִמֵּי רַגְלַיִם וְאַחַר כָּךְ יִקְרָא, אַרְבַּע אַמּוֹת. בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁהֵם מִלַּאֲחוֹרָיו אוֹ מִצִּדָּיו אֲבָל אִם הָיוּ כְּנֶגֶד פָּנָיו מַרְחִיק מֵהֶן עַד שֶׁלֹּא יִרְאֶה אוֹתָן וְאַחַר כָּךְ יִקְרָא:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה עִמָּהֶן בַּבַּיִת בְּמָקוֹם שָׁוֶה אֲבָל אִם הָיָה שָׁם מָקוֹם גָּבוֹהַּ מֵהֶן עֲשָׂרָה טְפָחִים אוֹ נָמוּךְ מֵהֶם עֲשָׂרָה טְפָחִים יוֹשֵׁב בְּצַד הַמָּקוֹם וְקוֹרֵא שֶׁהֲרֵי נִפְסָק בֵּינֵיהֶם. וְהוּא שֶׁלֹּא יַגִּיעַ לוֹ רֵיחַ רַע. וְכֵן אִם כָּפָה כְּלִי עַל הַצּוֹאָה אוֹ עַל מֵימֵי רַגְלַיִם אַף עַל פִּי שֶׁהֵן עִמּוֹ בַּבַּיִת הֲרֵי אֵלּוּ כִּקְבוּרִין וּמֻתָּר לִקְרוֹת כְּנֶגְדָּן:","הָיָה בֵּינוֹ וּבֵין הַצּוֹאָה מְחִצָּה שֶׁל זְכוּכִית אַף עַל פִּי שֶׁהוּא רוֹאֶה אוֹתָהּ מֵאַחֲרֵי הַזְּכוּכִית מֻתָּר לִקְרוֹת בְּצִדָּהּ. נָתַן רְבִיעִית מַיִם לְתוֹךְ מֵי רַגְלַיִם שֶׁל פַּעַם אַחַת מֻתָּר לִקְרוֹת עִמָּהֶן בְּתוֹךְ אַרְבַּע אַמּוֹת:","הָיְתָה צוֹאָה בְּגוּמָא עוֹמֵד בְּסַנְדָּלוֹ עַל הַגּוּמָא וְקוֹרֵא. וְהוּא שֶׁלֹּא יִהְיֶה סַנְדָּלוֹ נוֹגֵעַ בָּהּ. הָיְתָה כְּנֶגְדּוֹ צוֹאָה מְעוּטָה בְּיוֹתֵר כְּמוֹ טִפָּה רוֹקֵק עָלֶיהָ רֹק עָבֶה עַד שֶׁתִּתְכַּסֶּה וְקוֹרֵא. הָיְתָה נְטִישַׁת צוֹאָה עַל בְּשָׂרוֹ אוֹ יָדָיו מְטֻנָּפוֹת מִבֵּית הַכִּסֵּא וְלֹא הָיָה לָהֶן רֵיחַ רַע כְּלָל מִפְּנֵי קָטְנָן אוֹ יַבְשׁוּתָן מֻתָּר לִקְרוֹת לְפִי שֶׁאֵין לָהֶן רֵיחַ רַע. אֲבָל אִם הָיְתָה בִּמְקוֹמָהּ אַף עַל פִּי שֶׁאֵינָהּ נִרְאֵית כְּשֶׁהוּא עוֹמֵד הוֹאִיל וְנִרְאֵית כְּשֶׁהוּא יוֹשֵׁב אָסוּר לִקְרוֹת עַד שֶׁיְּקַנֵּחַ יָפֶה יָפֶה מִפְּנֵי שֶׁהַצּוֹאָה לָחָה הִיא וְיֵשׁ לָהּ רֵיחַ רַע. וְכַמָּה גְּאוֹנִים הוֹרוּ שֶׁאָסוּר לוֹ לִקְרוֹת אִם הָיוּ יָדָיו מְטֻנָּפוֹת וְכָךְ רָאוּי לַעֲשׂוֹת:","רֵיחַ רַע שֶׁיֵּשׁ לוֹ עִקָּר מַרְחִיק ד׳‎ אַמּוֹת וְקוֹרֵא אִם פָּסַק הָרֵיחַ. וְאִם לֹא פָּסַק הָרֵיחַ מַרְחִיק עַד מָקוֹם שֶׁפָּסַק הָרֵיחַ. וְשֶׁאֵין לוֹ עִקָּר כְּגוֹן מִי שֶׁיָּצָא מִמֶּנּוּ רוּחַ מִלְּמַטָּה מַרְחִיק עַד מָקוֹם שֶׁתִּכְלֶה הָרֵיחַ וְקוֹרֵא. גְּרָף שֶׁל רְעִי וַעֲבִיט שֶׁל מֵימֵי רַגְלַיִם אָסוּר לִקְרוֹת קְרִיאַת שְׁמַע כְּנֶגְדָּן וְאַף עַל פִּי שֶׁאֵין בָּהֶן כְּלוּם וְאֵין לָהֶם רֵיחַ רַע מִפְּנֵי שֶׁהֵם כְּבֵית הַכִּסֵּא:","צוֹאָה עוֹבֶרֶת כְּגוֹן שֶׁהָיְתָה שָׁטָה עַל פְּנֵי הַמַּיִם אָסוּר לִקְרוֹת כְּנֶגְדָּהּ. וּפִי חֲזִיר כְּצוֹאָה עוֹבֶרֶת דָּמִי וְאָסוּר לִקְרוֹת כְּנֶגְדּוֹ עַד שֶׁיַּעַבְרוּ מִמֶּנּוּ אַרְבַּע אַמּוֹת:","הָיָה קוֹרֵא וְהִגִּיעַ לִמְקוֹם הַטִּנֹּפֶת לֹא יַנִּיחַ יָדוֹ עַל פִּיו וְיִקְרָא אֶלָּא יַפְסִיק עַד שֶׁיַּעֲבֹר מֵאוֹתוֹ מָקוֹם. וְכֵן הַקּוֹרֵא שֶׁיָּצְתָה מִמֶּנּוּ רוּחַ מִלְּמַטָּה יַפְסִיק עַד שֶׁתִּכְלֶה בַּאֲשָׁהּ וְחוֹזֵר לִקְרִיאָתוֹ. וְכֵן בְּדִבְרֵי תּוֹרָה. יָצְתָה רוּחַ מֵחֲבֵרוֹ אַף עַל פִּי שֶׁמַּפְסִיק לִקְרִיאַת שְׁמַע אֵינוֹ פּוֹסֵק לְדִבְרֵי תּוֹרָה:","הָיָה קוֹרֵא קְרִיאַת שְׁמַע בְּבַיִת וְנִסְתַּפֵּק לוֹ אִם יֵשׁ שָׁם צוֹאָה אוֹ מֵימֵי רַגְלַיִם אוֹ אֵין שָׁם הֲרֵי זֶה מֻתָּר לִקְרוֹת. הָיָה קוֹרֵא בָּאַשְׁפָּה וְנִסְתַּפֵּק לוֹ אִם יֵשׁ שָׁם צוֹאָה אוֹ אֵין שָׁם לֹא יִקְרָא עַד שֶׁיִּבְדֹּק שֶׁחֶזְקַת הָאַשְׁפָּה שֶׁהִיא מְקוֹם הַטִּנֹּפֶת. אֲבָל סְפֵק מֵי רַגְלַיִם אֲפִלּוּ בָּאַשְׁפָּה מֻתָּר לִקְרוֹת:","כְּשֵׁם שֶׁאָסוּר לִקְרוֹת כְּנֶגֶד צוֹאָה וּמֵי רַגְלַיִם עַד שֶׁיַּרְחִיק כָּךְ אָסוּר לִקְרוֹת כְּנֶגֶד הָעֶרְוָה עַד שֶׁיַּחֲזִיר פָּנָיו. אֲפִלּוּ כּוּתִי אוֹ קָטָן לֹא יִקְרָא כְּנֶגֶד עֶרְוָתָן אֲפִלּוּ מְחִצָּה שֶׁל זְכוּכִית מַפְסֶקֶת הוֹאִיל וְהוּא רוֹאֶה אוֹתָהּ אָסוּר לִקְרוֹת עַד שֶׁיַּחֲזִיר פָּנָיו. וְכָל גּוּף הָאִשָּׁה עֶרְוָה לְפִיכָךְ לֹא יִסְתַּכֵּל בְּגוּף הָאִשָּׁה כְּשֶׁהוּא קוֹרֵא וַאֲפִלּוּ אִשְׁתּוֹ. וְאִם הָיָה מְגֻלֶּה טֶפַח מִגּוּפָהּ לֹא יִקְרָא כְּנֶגְדָּהּ:","וּכְשֵׁם שֶׁהוּא אָסוּר כְּנֶגֶד עֶרְוַת אֲחֵרִים כָּךְ הוּא אָסוּר לִקְרוֹת כְּנֶגֶד עֶרְוָתוֹ וְלֹא יִקְרָא כְּשֶׁהוּא עָרֹם עַד שֶׁיְּכַסֶּה עֶרְוָתוֹ. הָיְתָה חֲגוֹרָה שֶׁל בֶּגֶד אוֹ עוֹר אוֹ שַׂק עַל מָתְנָיו אַף עַל פִּי שֶׁשְּׁאָר גּוּפוֹ עָרֹם מֻתָּר לוֹ לִקְרוֹת קְרִיאַת שְׁמַע וְהוּא שֶׁלֹּא יִהְיֶה עֲקֵבוֹ נוֹגֵעַ בְּעֶרְוָתוֹ. הָיָה יָשֵׁן בְּטַלִּיתוֹ וְהָיָה עָרֹם חוֹצֵץ בְּטַלִּיתוֹ מִתַּחַת לִבּוֹ וְקוֹרֵא. אֲבָל לֹא יָחֹץ צַוָּארוֹ וְיִקְרָא מִפְּנֵי שֶׁלִּבּוֹ רוֹאֶה אֶת הָעֶרְוָה וְנִמְצָא כְּמִי שֶׁקּוֹרֵא בְּלֹא חֲגוֹרָה:","שְׁנַיִם שֶׁהָיוּ יְשֵׁנִים בְּטַלִּית אַחַת כָּל אֶחָד מֵהֶן אָסוּר לִקְרוֹת אַף עַל פִּי שֶׁיְּכַסֶּה מִתַּחַת לִבּוֹ עַד שֶׁתְּהֵא טַלִּית מַפְסֶקֶת בֵּינֵיהֶן עַד שֶׁלֹּא יִגַּע בְּשַׂר זֶה בִּבְשַׂר זֶה מִמָּתְנָיו וּלְמַטָּה. וְאִם הָיָה יָשֵׁן עִם אִשְׁתּוֹ אוֹ בָּנָיו וּבְנֵי בֵּיתוֹ הַקְּטַנִּים הֲרֵי גּוּפָן כְּגוּפוֹ וְאֵינוֹ מַרְגִּישׁ מֵהֶן. לְפִיכָךְ אַף עַל פִּי שֶׁבְּשָׂרוֹ נוֹגֵעַ בָּהֶם מַחֲזִיר פָּנָיו וְחוֹצֵץ מִתַּחַת לִבּוֹ וְקוֹרֵא:","עַד אֵימָתַי הֵם קְטַנִּים לְעִנְיָן זֶה עַד שֶׁיְּהֵא הַזָּכָר בֶּן שְׁתֵּים עֶשְׂרֵה שָׁנָה וְיוֹם אֶחָד וְהַנְּקֵבָה בַּת אַחַת עֶשְׂרֵה שָׁנָה וְיוֹם אֶחָד וְהוּא שֶׁיְּהֵא תַּבְנִיתָם כְּתַבְנִית גְּדוֹלִים (יחזקאל טז ז) ״שָׁדַיִם נָכוֹנוּ וּשְׂעָרֵךְ צִמֵּחַ״. וְאַחַר כָּךְ לֹא יִקְרָא עַד שֶׁתַּפְסִיק טַלִּית בֵּינֵיהֶן. אֲבָל אִם עֲדַיִן לֹא הָיוּ שָׁדַיִם נָכוֹנוּ וּשְׂעָרֵךְ צִמֵּחַ קוֹרֵא עִמָּהֶן בְּקֵרוּב בָּשָׂר וְאֵינוֹ צָרִיךְ הֶפְסֵק עַד שֶׁיִּהְיֶה הַזָּכָר בֶּן י״ג שָׁנָה וְיוֹם אֶחָד וְהַנְּקֵבָה בַּת שְׁתֵּים עֶשְׂרֵה שָׁנָה וְיוֹם אֶחָד:"],"Mishneh Torah, Red Heifer 12":["אָדָם שֶׁנִּטְמָא בְּמֵת וְהִזָּה עָלָיו כֵּיוָן שֶׁנָּגַע כָּל שֶׁהוּא מִמֵּי הַנִּדָּה בְּכָל מָקוֹם מֵעוֹר בְּשָׂרוֹ שֶׁל טָמֵא עָלְתָה לוֹ הַזָּיָה. אֲפִלּוּ נָפְלָה הַהַזָּאָה עַל רֹאשׁ אֶצְבָּעוֹ אוֹ עַל רֹאשׁ שְׂפָתוֹ. אֲבָל אִם נָגְעָה בִּלְשׁוֹנוֹ אֵינָהּ כְּלוּם. אַף עַל פִּי שֶׁהַלָּשׁוֹן כְּאֵיבָרִים שֶׁבְּגָלוּי לְעִנְיַן טֻמְאָה כְּמוֹ שֶׁבֵּאַרְנוּ. אֵינָן כְּאֵיבָרִים שֶׁבְּגָלוּי לְעִנְיַן הַזָּאָה וּטְבִילָה. וְכֵן כְּלִי שֶׁנִּטְמָא בְּמֵת וְהִזָּה עָלָיו כֵּיוָן שֶׁהִגִּיעַ לְגוּפוֹ שֶׁל כְּלִי כָּל שֶׁהוּא מִמֵּי הַנִּדָּה עָלְתָה לוֹ הַזָּאָה:","שְׁנֵי כֵּלִים אוֹ שְׁנֵי בְּנֵי אָדָם שֶׁנִּתְכַּוֵּן לְהַזּוֹת עַל שְׁנֵיהֶן כְּאַחַת וְהִזָּה עַל אֶחָד מֵהֶן. וְנָטְפוּ הַמַּיִם מֵעַל הָרִאשׁוֹן עַל הַשֵּׁנִי הֲרֵי הַשֵּׁנִי בְּטֻמְאָתוֹ עַד שֶׁיִּפְּלוּ עָלָיו הַמַּיִם מֵהַזָּיַת הַמַּזֶּה לֹא מִן הַתַּמְצִית. הִזָּה עַל שְׁנֵי כֵּלִים וְנִסְתַּפֵּק לוֹ אִם הִזָּה עַל שְׁנֵיהֶן כְּאַחַד אוֹ מֵחֲבֵרוֹ נִמְצָה עָלָיו הַזָּיָתוֹ פְּסוּלָה:","מַחַט שֶׁנְּתוּנָה עַל הַחֶרֶשׂ וְהִזָּה עָלֶיהָ סָפֵק עַל הַמַּחַט הִזָּה סָפֵק מִן הַחֶרֶשׂ נִמְצָה עָלֶיהָ הַזָּיָתוֹ פְּסוּלָה:","כֵּלִים הַמְפֻצָּלִין שֶׁמְּחֻבָּרִין זֶה לָזֶה בְּמַסְמְרִים. כְּגוֹן מִסְפֹּרֶת שֶׁל פְּרָקִים וְאִזְמֵל שֶׁל רְהִיטְנִי וְכַיּוֹצֵא בָּהֶן. בִּשְׁעַת מְלָאכָה חִבּוּר לְטֻמְאָה וּלְהַזָּיָה. שֶׁלֹּא בִּשְׁעַת מְלָאכָה אֵינוֹ חִבּוּר לֹא לָזֶה וְלֹא לָזֶה. כֵּיצַד הֵן חִבּוּר לְטֻמְאָה וּלְהַזָּיָה. שֶׁאִם נִטְמָא אֶחָד מֵהֶן בִּשְׁעַת מְלָאכָה נִטְמָא הַשֵּׁנִי. וְאִם הִזָּה עַל אֶחָד מֵהֶן בִּשְׁעַת מְלָאכָה עָלְתָה הַזָּיָה לִשְׁנֵיהֶן וּכְאִלּוּ הֵן גּוּף אֶחָד. וְכֵיצַד אֵינוֹ חִבּוּר לֹא לְטֻמְאָה וְלֹא לְהַזָּיָה. שֶׁאִם נִטְמָא אֶחָד מֵהֶן שֶׁלֹּא בִּשְׁעַת מְלָאכָה לֹא נִטְמָא חֲבֵרוֹ. וְאִם נִטְמְאוּ שְׁנֵיהֶן וְהִזָּה עַל אֶחָד מֵהֶן שֶׁלֹּא בִּשְׁעַת מְלָאכָה לֹא טִהֵר חֲבֵרוֹ אַף עַל פִּי שֶׁהֵן מְחֻבָּרִין. וְזֶהוּ דִּין תּוֹרָה. אֲבָל מִדִּבְרֵי סוֹפְרִים גָּזְרוּ שֶׁיִּהְיוּ חִבּוּר לְטֻמְאָה אֲפִלּוּ שֶׁלֹּא בִּשְׁעַת מְלָאכָה גְּזֵרָה מִשּׁוּם שְׁעַת מְלָאכָה. וּלְעוֹלָם אִם נָגְעָה בְּאֶחָד מֵהֶן טֻמְאָה נִטְמָא חֲבֵרוֹ. וְכֵן גָּזְרוּ עֲלֵיהֶן שֶׁלֹּא יִהְיוּ חִבּוּר לְהַזָּיָה אֲפִלּוּ בִּשְׁעַת מְלָאכָה גְּזֵרָה מִשּׁוּם שֶׁלֹּא בִּשְׁעַת מְלָאכָה. וּלְעוֹלָם אִם הִזָּה עַל אֶחָד מֵהֶן לֹא טִהֵר חֲבֵרוֹ עַד שֶׁיַּזֶּה גַּם עָלָיו. הִנֵּה לָמַדְתָּ שֶׁכָּל מָקוֹם שָׁאַתָּה שׁוֹמֵעַ חִבּוּר לְטֻמְאָה וְאֵינוֹ חִבּוּר לְהַזָּיָה אֵין זֶה אֶלָּא גְּזֵרָה מִדִּבְרֵיהֶם עַל הַדֶּרֶךְ שֶׁבֵּאַרְנוּ:","שְׁנֵי כֵּלִים שֶׁחִבְּרָן עַד שֶׁנַּעֲשׂוּ כְּגוּף אֶחָד. כְּגוֹן שֶׁתָּפַר שְׁנֵי בְּגָדִים אוֹ שְׁתֵּי יְרִיעוֹת הֲרֵי אֵלּוּ חִבּוּר לְטֻמְאָה וּלְהַזָּאָה מִפְּנֵי שֶׁהֵן כִּכְלִי אֶחָד:","שְׁלַל הַכּוֹבְסִין וְהַבֶּגֶד שֶׁהוּא תָּפוּר בְּכִלְאַיִם וְהֵן עוֹמְדִין לְהַתִּירָן אֵינוֹ חִבּוּר לְהַזָּיָה וַהֲרֵי הֵן חִבּוּר לְטֻמְאָה. וְכֵן הַסְּלָעִים שֶׁבַּקַּנְתָּל. וְהַמִּטָּה שֶׁל טַרְבָּל. וְקֶרֶן שֶׁל כְּלִיבָה. וְקַרְנַיִם שֶׁל יוֹצְאֵי דְּרָכִים. וְשַׁלְשֶׁלֶת הַמַּפְתְּחוֹת. חִבּוּר לְטֻמְאָה וְלֹא לְהַזָּאָה. אֶלָּא צָרִיךְ שֶׁיִּגְּעוּ הַמַּיִם מִן הַמַּזֶּה בְּכָל סַל וְסַל. וּבְכָל מַפְתֵּחַ וּמַפְתֵּחַ. וּבְכָל קֶרֶן וְקֶרֶן. וּבְכָל קוֹרָה וְקוֹרָה מִמִּטָּה זוֹ הַמְפֻצֶּלֶת:","הַמְחַבֵּר שָׁלֹשׁ כְּסָתוֹת שֶׁל צֶמֶר וְשֵׁשׁ שֶׁל פִּשְׁתָּן. אוֹ שְׁלֹשָׁה סְדִינִים אוֹ שְׁתֵּים עֶשְׂרֵה מִטְפָּחוֹת. הֲרֵי אֵלּוּ חִבּוּר לְטֻמְאָה וּלְהַזָּאָה. יֶתֶר מִכָּאן חִבּוּר לְטֻמְאָה וְלֹא לְהַזָּאָה. חָלוּק אֶחָד וְטַלִּית אַחַת וּקְלוּבְקָרִין אֶחָד הֲרֵי הֵן חִבּוּר לְטֻמְאָה וּלְהַזָּיָה אֲפִלּוּ הָיוּ אֲרֻכִּין בְּיוֹתֵר אוֹ רְחָבִין בְּיוֹתֵר כָּל שֶׁהֵן. וְאֵי זֶהוּ קְלוּבְקָרִין זֶה שְׁנֵי בְּגָדִים שֶׁמַּנִּיחִין צֶמֶר גֶפֶן בֵּינֵיהֶן וְתוֹפְרִין אוֹתָן כְּאַחַת וְעוֹשִׂין מֵהֶן חָלוּק לִימוֹת הַגְּשָׁמִים:","כִּסּוּי הַמֵּחַם שֶׁמְּחֻבָּר בְּשַׁלְשֶׁלֶת. הִזָּה עַל הַמֵּחַם טִהֵר הַכּל. הִזָּה עַל הַכִּסּוּי לֹא טִהֵר הַמֵּחַם עַד שֶׁיַּזֶּה עָלָיו:","הַזּוֹג וְהָעִנְבָּל חִבּוּר לְטֻמְאָה וּלְהַזָּאָה וְאִם הִזָּה עַל אֶחָד מֵהֶן טִהֲרוּ שְׁנֵיהֶן:","הַטֶּוִוי שֶׁטּוֹוִים בּוֹ הַפִּשְׁתִּים אוֹ שׁוֹזְרִין בּוֹ הַחֲבָלִים שְׁלֹשָׁה גּוּפִין יֵשׁ בּוֹ. הָעֵץ שֶׁמְּלַפְּפִין עָלָיו הַטָּווּיִ וְהוּא הַנִּקְרָא כּוּשׁ. וְהַנְּחשֶׁת אוֹ הַבַּרְזֶל שֶׁבְּרֹאשׁ הָעֵץ וְהוּא הַנִּקְרָא צִנּוֹרָא שֶׁבָּהּ פּוֹתְלִין וְטוֹוִין. וְהָרֵחַיִם שֶׁבְּאֶמְצַע הַכּוּשׁ וְהִיא הַנִּקְרֵאת פִּיקָא. הַכּוּשׁ שֶׁפּוֹתְלִין בּוֹ הַחֲבָלִים שֶׁנִּטְמָא לֹא יַזֶּה עַל הַפִּיקָא שֶׁלּוֹ וְלֹא עַל הַכּוּשׁ אֶלָּא עַל הַצִּנּוֹרָא. וְאִם הִזָּה עַל אֶחָד מִשְּׁלָשְׁתָּן טִהֵר הַכּל. וְשֶׁל פִּשְׁתָּן מַזֶּה עַל אֶחָד מִשְּׁלָשְׁתָּן לְכַתְּחִלָּה שֶׁשְּׁלָשְׁתָּן חִבּוּר:","עוֹר שֶׁל עֲרִיסָה שֶׁהוּא מְחֻבָּר לְפִיקוֹת. חִבּוּר לְטֻמְאָה וּלְהַזָּאָה. הַמַּלְבֵּן שֶׁל מִטּוֹת אֵינוֹ חִבּוּר לֹא לְטֻמְאָה וְלֹא לְהַזָּאָה:","כָּל יְדוֹת הַכֵּלִים הַקְּדוּחוֹת כְּגוֹן נִצַּב הַסַּכִּין וְכַיּוֹצֵא בּוֹ שֶׁהַנִּצָּב נָקוּב וְהַבַּרְזֶל נִכְנָס בּוֹ חִבּוּר לְטֻמְאָה וּלְהַזָּאָה. אֲבָל הַיָּדוֹת הַחֲרוּקוֹת כְּגוֹן עֵץ הַחֲנִית שֶׁהָעֵץ נִכְנָס בַּבַּרְזֶל אֵינוֹ חִבּוּר לְהַזָּאָה:"],"Mishneh Torah, Repentance 1":["כָּל מִצְוֹת שֶׁבַּתּוֹרָה בֵּין עֲשֵׂה בֵּין לֹא תַּעֲשֶׂה אִם עָבַר אָדָם עַל אַחַת מֵהֶן בֵּין בְּזָדוֹן בֵּין בִּשְׁגָגָה כְּשֶׁיַּעֲשֶׂה תְּשׁוּבָה וְיָשׁוּב מֵחֶטְאוֹ חַיָּב לְהִתְוַדּוֹת לִפְנֵי הָאֵל בָּרוּךְ הוּא שֶׁנֶּאֱמַר (במדבר ה ו) \"אִישׁ אוֹ אִשָּׁה כִּי יַעֲשׂוּ\" וְגוֹ' (במדבר ה ז) \"וְהִתְוַדּוּ אֶת חַטָּאתָם אֲשֶׁר עָשׂוּ\" זֶה וִדּוּי דְּבָרִים. וִדּוּי זֶה מִצְוַת עֲשֵׂה. כֵּיצַד מִתְוַדִּין. אוֹמֵר אָנָּא הַשֵּׁם חָטָאתִי עָוִיתִי פָּשַׁעְתִּי לְפָנֶיךָ וְעָשִׂיתִי כָּךְ וְכָךְ וַהֲרֵי נִחַמְתִּי וּבֹשְׁתִּי בְּמַעֲשַׂי וּלְעוֹלָם אֵינִי חוֹזֵר לְדָבָר זֶה. וְזֶהוּ עִקָּרוֹ שֶׁל וִדּוּי. וְכָל הַמַּרְבֶּה לְהִתְוַדּוֹת וּמַאֲרִיךְ בְּעִנְיָן זֶה הֲרֵי זֶה מְשֻׁבָּח. וְכֵן בַּעֲלֵי חַטָּאוֹת וַאֲשָׁמוֹת בְּעֵת שֶׁמְּבִיאִין קָרְבְּנוֹתֵיהֶן עַל שִׁגְגָתָן אוֹ עַל זְדוֹנָן אֵין מִתְכַּפֵּר לָהֶן בְּקָרְבָּנָם עַד שֶׁיַּעֲשׂוּ תְּשׁוּבָה וְיִתְוַדּוּ וִדּוּי דְּבָרִים שֶׁנֶּאֱמַר (ויקרא ה ה) \"וְהִתְוַדָּה אֲשֶׁר חָטָא עָלֶיהָ\". וְכֵן כָּל מְחֻיְּבֵי מִיתוֹת בֵּית דִּין וּמְחֻיְּבֵי מַלְקוֹת אֵין מִתְכַּפֵּר לָהֶן בְּמִיתָתָן אוֹ בִּלְקִיָּתָן עַד שֶׁיַּעֲשׂוּ תְּשׁוּבָה וְיִתְוַדּוּ. וְכֵן הַחוֹבֵל בַּחֲבֵרוֹ וְהַמַּזִּיק מָמוֹנוֹ אַף עַל פִּי שֶׁשִּׁלֵּם לוֹ מַה שֶּׁהוּא חַיָּב לוֹ אֵינוֹ מִתְכַּפֵּר עַד שֶׁיִּתְוַדֶּה וְיָשׁוּב מִלַּעֲשׂוֹת כָּזֶה לְעוֹלָם שֶׁנֶּאֱמַר (במדבר ה ו) \"מִכָּל חַטֹּאת הָאָדָם\":","שָׂעִיר הַמִּשְׁתַּלֵּחַ לְפִי שֶׁהוּא כַּפָּרָה עַל כָּל יִשְׂרָאֵל כֹּהֵן גָּדוֹל מִתְוַדֶּה עָלָיו עַל לְשׁוֹן כָּל יִשְׂרָאֵל שֶׁנֶּאֱמַר (ויקרא טז כא) \"וְהִתְוַדָּה עָלָיו אֶת כָּל עֲוֹנֹת בְּנֵי יִשְׂרָאֵל\". שָׂעִיר הַמִּשְׁתַּלֵּחַ מְכַפֵּר עַל כָּל עֲבֵרוֹת שֶׁבַּתּוֹרָה, הַקַּלּוֹת וְהַחֲמוּרוֹת, בֵּין שֶׁעָבַר בְּזָדוֹן בֵּין שֶׁעָבַר בִּשְׁגָגָה, בֵּין שֶׁהוֹדַע לוֹ בֵּין שֶׁלֹּא הוֹדַע לוֹ, הַכּל מִתְכַּפֵּר בְּשָׂעִיר הַמִּשְׁתַּלֵּחַ. וְהוּא שֶׁעָשָׂה תְּשׁוּבָה. אֲבָל אִם לֹא עָשָׂה תְּשׁוּבָה אֵין הַשָּׂעִיר מְכַפֵּר לוֹ אֶלָּא עַל הַקַּלּוֹת. וּמַה הֵן הַקַּלּוֹת וּמַה הֵן הַחֲמוּרוֹת. הַחֲמוּרוֹת הֵן שֶׁחַיָּבִין עֲלֵיהֶם מִיתַת בֵּית דִּין אוֹ כָּרֵת. וּשְׁבוּעַת שָׁוְא וָשֶׁקֶר אַף עַל פִּי שֶׁאֵין בָּהֶן כָּרֵת הֲרֵי הֵן מִן הַחֲמוּרוֹת. וּשְׁאָר מִצְוֹת לֹא תַּעֲשֶׂה וּמִצְוֹת עֲשֵׂה שֶׁאֵין בָּהֶן כָּרֵת הֵם הַקַּלּוֹת:","בַּזְּמַן הַזֶּה שֶׁאֵין בֵּית הַמִּקְדָּשׁ קַיָּם וְאֵין לָנוּ מִזְבַּח כַּפָּרָה אֵין שָׁם אֶלָּא תְּשׁוּבָה. הַתְּשׁוּבָה מְכַפֶּרֶת עַל כָּל הָעֲבֵרוֹת. אֲפִלּוּ רָשָׁע כָּל יָמָיו וְעָשָׂה תְּשׁוּבָה בָּאַחֲרוֹנָה אֵין מַזְכִּירִין לוֹ שׁוּם דָּבָר מֵרִשְׁעוֹ שֶׁנֶּאֱמַר (יחזקאל לג יב) \"רִשְׁעַת הָרָשָׁע לֹא יִכָּשֶׁל בָּהּ בְּיוֹם שׁוּבוֹ מֵרִשְׁעוֹ\". וְעַצְמוֹ שֶׁל יוֹם הַכִּפּוּרִים מְכַפֵּר לַשָּׁבִים שֶׁנֶּאֱמַר (ויקרא טז ל) \"כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם\":","אַף עַל פִּי שֶׁהַתְּשׁוּבָה מְכַפֶּרֶת עַל הַכּל וְעַצְמוֹ שֶׁל יוֹם הַכִּפּוּרִים מְכַפֵּר. יֵשׁ עֲבֵרוֹת שֶׁהֵן מִתְכַּפְּרִים לִשְׁעָתָן וְיֵשׁ עֲבֵרוֹת שֶׁאֵין מִתְכַּפְּרִים אֶלָּא לְאַחַר זְמַן. כֵּיצַד. עָבַר אָדָם עַל מִצְוַת עֲשֵׂה שֶׁאֵין בָּהּ כָּרֵת וְעָשָׂה תְּשׁוּבָה אֵינוֹ זָז מִשָּׁם עַד שֶׁמּוֹחֲלִין לוֹ, וּבְאֵלּוּ נֶאֱמַר (ירמיה ג כב) \"שׁוּבוּ בָּנִים שׁוֹבָבִים אֶרְפָּה מְשׁוּבֹתֵיכֶם\" וְגוֹ'. עָבַר עַל מִצְוַת לֹא תַּעֲשֶׂה שֶׁאֵין בָּהּ כָּרֵת וְלֹא מִיתַת בֵּית דִּין וְעָשָׂה תְּשׁוּבָה, תְּשׁוּבָה תּוֹלָה וְיוֹם הַכִּפּוּרִים מְכַפֵּר, וּבְאֵלּוּ נֶאֱמַר (ויקרא טז ל) \"כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם\". עָבַר עַל כְּרֵתוֹת וּמִיתוֹת בֵּית דִּין וְעָשָׂה תְּשׁוּבָה, תְּשׁוּבָה וְיוֹם הַכִּפּוּרִים תּוֹלִין וְיִסּוּרִין הַבָּאִין עָלָיו גּוֹמְרִין לוֹ הַכַּפָּרָה. וּלְעוֹלָם אֵין מִתְכַּפֵּר לוֹ כַּפָּרָה גְּמוּרָה עַד שֶׁיָּבוֹאוּ עָלָיו יִסּוּרִין, וּבְאֵלּוּ נֶאֱמַר (תהילים פט לג) \"וּפָקַדְתִּי בְשֵׁבֶט פִּשְׁעָם וּבִנְגָעִים עֲוֹנָם\". בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁלֹּא חִלֵּל אֶת הַשֵּׁם בְּשָׁעָה שֶׁעָבַר אֲבָל הַמְחַלֵּל אֶת הַשֵּׁם אַף עַל פִּי שֶׁעָשָׂה תְּשׁוּבָה וְהִגִּיעַ יוֹם הַכִּפּוּרִים וְהוּא עוֹמֵד בִּתְשׁוּבָתוֹ וּבָאוּ עָלָיו יִסּוּרִין אֵינוֹ מִתְכַּפֵּר לוֹ כַּפָּרָה גְּמוּרָה עַד שֶׁיָּמוּת. אֶלָּא תְּשׁוּבָה יוֹם הַכִּפּוּרִים וְיִסּוּרִין שְׁלָשְׁתָּן תּוֹלִין וּמִיתָה מְכַפֶּרֶת שֶׁנֶּאֱמַר (ישעיה כב יד) \"וְנִגְלָה בְאָזְנָי ה' צְבָאוֹת וְגוֹ' אִם יְכֻפַּר הֶעָוֹן הַזֶּה לָכֶם עַד תְּמֻתוּן\":"],"Mishneh Torah, Rest on a Holiday 3":["מִי שֶׁהָיָה לוֹ עָפָר מוּכָן אוֹ אֵפֶר מוּכָן שֶׁמֻּתָּר לְטַלְטְלוֹ הֲרֵי זֶה שׁוֹחֵט חַיָּה וָעוֹף וּמְכַסֶּה דָּמָם. וְאִם אֵין לוֹ עָפָר מוּכָן אוֹ אֵפֶר הָרָאוּי לְטַלְטְלוֹ הֲרֵי זֶה לֹא יִשְׁחֹט וְאִם עָבַר וְשָׁחַט לֹא יְכַסֶּה דָּמָם עַד לָעֶרֶב. וְכֵן בְּרִיָּה שֶׁהוּא סָפֵק אִם חַיָּה הִיא אִם בְּהֵמָה אֵין שׁוֹחֲטִין אוֹתָהּ בְּיוֹם טוֹב וְאִם שָׁחַט לֹא יְכַסֶּה דָּמָהּ עַד לָעֶרֶב. אֲפִלּוּ הָיָה לוֹ עָפָר מוּכָן אוֹ אֵפֶר. שֶׁמָּא יֹאמַר הָרוֹאֶה חַיָּה וַדָּאִית הִיא וּלְפִיכָךְ כִּסָּה דָּמוֹ בְּיוֹם טוֹב וְיָבוֹא הָרוֹאֶה לְהַתִּיר חֶלְבּוֹ:","וְכֵן הַשּׁוֹחֵט חַיָּה וָעוֹף מֵעֶרֶב יוֹם טוֹב לֹא יְכַסֶּה דָּמָם בְּיוֹם טוֹב. שָׁחַט בְּהֵמָה חַיָּה וָעוֹף בְּיוֹם טוֹב וְנִתְעָרֵב דָּמָם לֹא יְכַסֶּה אוֹתוֹ עַד לָעֶרֶב. וְאִם הָיָה לוֹ עָפָר מוּכָן אוֹ אֵפֶר וְיָכוֹל לְכַסּוֹת הַכּל בִּדְקִירָה אַחַת הֲרֵי זֶה יְכַסֵּהוּ:","הַשּׁוֹחֵט בְּהֵמָה בְּיוֹם טוֹב מֻתָּר לוֹ לִתְלֹשׁ צֶמֶר לִמְקוֹם הַסַּכִּין בְּיָדוֹ. וּבִלְבַד שֶׁלֹּא יְזִיזֶנּוּ מִמְּקוֹמוֹ אֶלָּא יִשָּׁאֵר שָׁם מְסֻבָּךְ כִּשְׁאָר צֶמֶר הַצַּוָּאר. אֲבָל בְּעוֹף לֹא יִמְרֹט מִפְּנֵי שֶׁהוּא דַּרְכּוֹ וְנִמְצָא תּוֹלֵשׁ בְּיוֹם טוֹב:","הַמַּפְשִׁיט עוֹר בְּהֵמָה בְּיוֹם טוֹב לֹא יִמְלָחֶנּוּ שֶׁזֶּה עִבּוּד הוּא וְנִמְצָא עוֹשֶׂה מְלָאכָה שֶׁלֹּא לְצֹרֶךְ אֲכִילָה. אֲבָל נוֹתְנוֹ לִפְנֵי בֵּית הַדְּרִיסָה כְּדֵי שֶׁיִּדְרְסוּ עָלָיו וְלֹא יִפָּסֵד. וְלֹא הִתִּירוּ דָּבָר זֶה אֶלָּא מִפְּנֵי שִׂמְחַת יוֹם טוֹב כְּדֵי שֶׁלֹּא יִמָּנַע מִלִּשְׁחֹט. וּמֻתָּר לִמְלֹחַ בָּשָׂר לְצָלִי עַל גַּבֵּי הָעוֹר. וּמַעֲרִימִים בְּדָבָר זֶה. כֵּיצַד. מוֹלֵחַ מְעַט בָּשָׂר מִכָּאן וּמְעַט מִכָּאן עַד שֶׁיִּמְלַח הָעוֹר כֻּלּוֹ:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּמוֹלֵחַ לְצָלִי שֶׁאֵינוֹ צָרִיךְ מֶלַח הַרְבֵּה אֲבָל לִקְדֵרָה אָסוּר לִמְלֹחַ עַל הָעוֹר. וְכֵן אֵין מוֹלְחִין אֶת הַחֲלָבִים וְאֵין מְהַפְּכִין בָּהֶן וְאֵין שׁוֹטְחִין אוֹתָן בָּרוּחַ עַל גַּבֵּי יְתֵדוֹת מִפְּנֵי שֶׁאֵינָן רְאוּיִין לַאֲכִילָה:","הַמַּפְשִׁיט אֶת הַבְּהֵמָה לֹא יַרְגִּיל בְּיוֹם טוֹב. כֵּיצַד הוּא הַמַּרְגִּיל. זֶה הַמּוֹצִיא כָּל בָּשָׂר מֵרֶגֶל אַחַת כְּדֵי שֶׁיּוֹצִיא כָּל הָעוֹר שָׁלֵם וְלֹא יִקָּרַע. מִפְּנֵי שֶׁטּוֹרֵחַ בְּהֶפְשֵׁט זֶה טֹרַח גָּדוֹל וְאֵין בּוֹ צֹרֶךְ לַמּוֹעֵד. וְכֵן אָסוּר לַעֲשׂוֹת בֵּית יָד בַּבָּשָׂר וְהוּא שֶׁיַּעֲשֶׂה בְּסַכִּין שֶׁלֹּא יַעֲשֶׂה כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל. וּמֻתָּר לַעֲשׂוֹת סִימָן בַּבָּשָׂר:","מוֹלְגִין אֶת הָרֹאשׁ וְאֶת הָרַגְלַיִם וּמְהַבְהֲבִין אוֹתָן בָּאוּר. אֲבָל אֵין טוֹפְלִין אוֹתָן בְּסִיד וּבְחַרְסִית וְלֹא בַּאֲדָמָה וְאֵין גּוֹזְזִין אוֹתָן בְּמִסְפָּרַיִם. וְכֵן אֵין גּוֹזְזִין אֶת הַיָּרָק בְּתִסְפֹּרֶת שֶׁלּוֹ אֲבָל מְתַקְּנִין אֶת הָאֹכֶל שֶׁיֵּשׁ בּוֹ קוֹצִים כְּגוֹן קֻנְדָּס וְעַכְּבִיּוֹת בְּתִסְפֹּרֶת:","מֻתָּר לָלוּשׁ עִסָּה גְּדוֹלָה בְּיוֹם טוֹב. וְהַלָּשׁ עִסָּה מֵעֶרֶב יוֹם טוֹב אֵינוֹ מַפְרִישׁ מִמֶּנָּה חַלָּה בְּיוֹם טוֹב. וְאִם לָשָׁהּ בְּיוֹם טוֹב מַפְרִישׁ מִמֶּנָּה חַלָּה וְנוֹתְנָהּ לַכֹּהֵן. וְאִם הָיְתָה עִסָּה טְמֵאָה אוֹ שֶׁנִּטְמֵאת הַחַלָּה לֹא יְבַשֵּׁל אֶת הַחַלָּה שֶׁאֵין מְבַשְּׁלִין בְּיוֹם טוֹב אֶלָּא לֶאֱכל וְזוֹ לִשְׂרֵפָה עוֹמֶדֶת. וְכֵן אֵין שׂוֹרְפִין אוֹתָהּ בְּיוֹם טוֹב שֶׁאֵין שׂוֹרְפִין קָדָשִׁים שֶׁנִּטְמְאוּ בְּיוֹם טוֹב. שֶׁשְּׂרֵפַת קָדָשִׁים שֶׁנִּטְמְאוּ מִצְוַת עֲשֵׂה שֶׁנֶּאֱמַר (ויקרא ז יט) \"בָּאֵשׁ יִשָּׂרֵף\" וַעֲשִׂיַּת מְלָאכָה שֶׁאֵינָהּ לְצֹרֶךְ אֲכִילָה וְכַיּוֹצֵא בָּהֶן עֲשֵׂה וְלֹא תַּעֲשֶׂה וְאֵין עֲשֵׂה דּוֹחֶה אֶת לֹא תַּעֲשֶׂה וַעֲשֵׂה:","כֵּיצַד יַעֲשֶׂה בָּהּ. יְנִיחֶנָּהּ עַד הָעֶרֶב וְיִשְׂרֹף אוֹתָהּ. הָיָה יוֹם טוֹב שֶׁל פֶּסַח שֶׁאִם יְנִיחֶנָּהּ תַּחֲמִיץ לֹא יַפְרִישׁ אֶת הַחַלָּה בָּצֵק אֶלָּא יֹאפֶה אֶת כָּל הָעִסָּה הַטְּמֵאָה וְאַחַר כָּךְ יַפְרִישׁ הַחַלָּה לֶחֶם:","אֵין אוֹפִין בְּפוּרְנִי חֲדָשָׁה גְּזֵרָה שֶׁמָּא תִּפָּחֵת וְתַפְסִיד הַלֶּחֶם וְיִמָּנַע מִשִּׂמְחַת יוֹם טוֹב. אֵין גּוֹרְפִין תַּנּוּר וְכִירַיִם אֲבָל מְכַבְּשִׁין אֶת הָאֵפֶר שֶׁבָּהֶן. וְאִם אִי אֶפְשָׁר לֶאֱפוֹת בּוֹ אוֹ לִצְלוֹת אֶלָּא אִם כֵּן גָּרַף מֻתָּר. וְסוֹתְמִין פִּי הַתַּנּוּר בְּטִיט וְרֶפֶשׁ שֶׁבִּסְבִיבוֹת הַנָּהָר וְהוּא שֶׁרִכְּכוֹ מֵאֶמֶשׁ אֲבָל לְגַבֵּל טִיט בְּיוֹם טוֹב אָסוּר. וּמֻתָּר לְגַבֵּל אֶת הָאֵפֶר לִסְתֹּם בּוֹ פִּי הַתַּנּוּר:","תַּנּוּר וְכִירַיִם חֲדָשִׁים אֵין סָכִין אוֹתָן בְּשֶׁמֶן בְּיוֹם טוֹב. וְאֵין טָשִׁין אוֹתָן בְּמַטְלִית. וְאֵין מְפִיגִין אוֹתָן בְּצוֹנֵן כְּדֵי לְחָסְמָן וְאִם בִּשְׁבִיל לֶאֱפוֹת בָּהֶן מֻתָּר. אֵין מְלַבְּנִין אֶת הָאֲבָנִים לִצְלוֹת אוֹ לֶאֱפוֹת עֲלֵיהֶן מִפְּנֵי שֶׁמְּחַסְּמָן. וּמַסִּיקִין וְאוֹפִין בְּפוּרְנִי וּמְחִמִּין חַמִּין בְּאַנְטִיכִי:","אֵין עוֹשִׂין גְּבִינָה בְּיוֹם טוֹב שֶׁאִם גִּבֵּן מֵעֶרֶב יוֹם טוֹב אֵין בָּזֶה חֶסְרוֹן טַעַם אֲבָל דָּכִין אֶת הַתַּבְלִין כְּדַרְכָּן שֶׁאִם יָדוּךְ אוֹתָן מִבָּעֶרֶב יָפוּג טַעֲמָן. אֲבָל מֶלַח אֵינוֹ נִדּוֹךְ בְּיוֹם טוֹב אֶלָּא אִם כֵּן הִטָּה הַמַּכְתֵּשׁ אוֹ שֶׁיָּדוּךְ בִּקְעָרָה וְכַיּוֹצֵא בָּהּ כְּדֵי שֶׁיְּשַׁנֶּה. שֶׁאִם שָׁחַק הַמֶּלַח מֵעֶרֶב יוֹם טוֹב לֹא יָפוּג טַעֲמוֹ. וְאֵין שׁוֹחֲקִין אֶת הַפִּלְפְּלִין בָּרֵחַיִם שֶׁלָּהֶן אֶלָּא דָּךְ אוֹתָן בִּמְדוּכָה כְּכָל הַתַּבְלִין:","אֵין כּוֹתְשִׁין אֶת הָרִיפוֹת בְּמַכְתֶּשֶׁת גְּדוֹלָה. אֲבָל כּוֹתְשִׁין בְּמַכְתֶּשֶׁת קְטַנָּה שֶׁזֶּה הוּא הַשִּׁנּוּי שֶׁלָּהּ. וּבְאֶרֶץ יִשְׂרָאֵל אֲפִלּוּ בִּקְטַנָּה אָסוּר שֶׁהַתְּבוּאָה שֶׁלָּהֶן טוֹבָה הִיא וְאִם כּוֹתְשִׁין אוֹתָם מֵעֶרֶב יוֹם טוֹב אֵין בְּכָךְ הֶפְסֵד:","הַקֶּמַח אַף עַל פִּי שֶׁרִקְּדוֹ מֵעֶרֶב יוֹם טוֹב וְהֵסִיר מִמֶּנּוּ הַסֻּבִּין אֵין מְרַקְּדִין אוֹתוֹ פַּעַם שְׁנִיָּה בְּיוֹם טוֹב אֶלָּא אִם כֵּן נָפַל בְּתוֹכוֹ צְרוֹר אוֹ קֵיסָם וְכַיּוֹצֵא בָּהֶם. וְאִם שִׁנָּה מֻתָּר. כֵּיצַד. כְּגוֹן שֶׁיְּרַקֵּד מֵאֲחוֹרֵי הַנָּפָה אוֹ שֶׁרִקֵּד עַל גַּבֵּי הַשֻּׁלְחָן וְכַיּוֹצֵא בְּשִׁנּוּי זֶה:","מוֹלְלִין מְלִילוֹת וּמְפָרְכִין קִטְנִית בְּיוֹם טוֹב וּמְנַפֵּחַ עַל יָד עַל יָד בְּכָל כֹּחוֹ וְאוֹכֵל וַאֲפִלּוּ בְּקָנוֹן אוֹ בְּתַמְחוּי אֲבָל לֹא בְּנָפָה וְלֹא בִּכְבָרָה. וְכֵן הַבּוֹרֵר קִטְנִיּוֹת בְּיוֹם טוֹב בּוֹרֵר כְּדַרְכּוֹ בְּחֵיקוֹ וּבְתַמְחוּי אֲבָל לֹא בְּנָפָה וְלֹא בְּטַבְלָה וְלֹא בִּכְבָרָה:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָאֹכֶל מְרֻבֶּה עַל הַפְּסלֶת אֲבָל אִם הָיְתָה הַפְּסלֶת מְרֻבָּה עַל הָאֹכֶל בּוֹרֵר אֶת הָאֹכֶל וּמֵנִיחַ אֶת הַפְּסלֶת. וְאִם הָיָה טֹרַח בִּבְרֵרַת הַפְּסלֶת מִן הָאֹכֶל יֶתֶר מִטֹּרַח בִּבְרֵרַת הָאֹכֶל מִן הַפְּסלֶת אַף עַל פִּי שֶׁהָאֹכֶל מְרֻבֶּה בּוֹרֵר אֶת הָאֹכֶל וּמֵנִיחַ אֶת הַפְּסלֶת:","אֵין מְסַנְּנִין אֶת הַחַרְדָּל בְּמִסְנֶנֶת שֶׁלָּהּ מִפְּנֵי שֶׁנִּרְאֶה כְּבוֹרֵר. אֲבָל נוֹתְנִין בֵּיצָה בְּמִסְנֶנֶת שֶׁל חַרְדָּל וְהוּא מִסְתַּנֵּן מֵאֵלָיו. וְאִם הָיְתָה הַמְּשַׁמֶּרֶת תְּלוּיָה מֻתָּר לִתֵּן לָהּ יַיִן בְּיוֹם טוֹב. אֲבָל לֹא יִתְלֶה בַּתְּחִלָּה שֶׁלֹּא יַעֲשֶׂה כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל. וּמַעֲרִים וְתוֹלֶה אֶת הַמְּשַׁמֶּרֶת לִתְלוֹת בָּהּ רִמּוֹנִים וְתוֹלֶה בָּהּ רִמּוֹנִים וְאַחַר כָּךְ נוֹתֵן לְתוֹכָהּ שְׁמָרִים:"],"Mishneh Torah, Ritual Slaughter 12":["הַשׁוֹחֵט אוֹתוֹ וְאֶת בְּנוֹ בְּיוֹם אֶחָד הַבָּשָׂר מֻתָּר בַּאֲכִילָה וְהַשּׁוֹחֵט לוֹקֶה שֶׁנֶּאֱמַר (ויקרא כב כח) \"אֹתוֹ וְאֶת בְּנוֹ לֹא תִשְׁחֲטוּ בְּיוֹם אֶחָד\". וְאֵינוֹ לוֹקֶה אֶלָּא עַל שְׁחִיטַת הָאַחֲרוֹן. לְפִיכָךְ אִם שָׁחַט אֶחָד מִשְּׁנֵיהֶן וּבָא חֲבֵרוֹ וְשָׁחַט אֶת הַשֵּׁנִי חֲבֵרוֹ לוֹקֶה:","אִסּוּר אוֹתוֹ וְאֶת בְּנוֹ נוֹהֵג בְּכָל זְמַן וּבְכָל מָקוֹם. בְּחֻלִּין וּבְמֻקְדָּשִׁין. בֵּין קָדָשִׁים הַנֶּאֱכָלִין בֵּין קָדָשִׁים שֶׁאֵינָן נֶאֱכָלִין. לְפִיכָךְ הָרִאשׁוֹן שֶׁשָּׁחַט בַּעֲזָרָה וְהַשֵּׁנִי בַּחוּץ. אוֹ הָרִאשׁוֹן בַּחוּץ וְהַשֵּׁנִי בַּעֲזָרָה. בֵּין שֶׁהָיוּ שְׁנֵיהֶן חֻלִּין אוֹ שְׁנֵיהֶן קָדָשִׁים. בֵּין שֶׁהָיָה אֶחָד מֵהֶן חֻלִּין וְאֶחָד קָדָשִׁים. זֶה שֶׁשָּׁחַט אַחֲרוֹן לוֹקֶה מִשּׁוּם אוֹתוֹ וְאֶת בְּנוֹ:","אֵין אִסּוּר אוֹתוֹ וְאֶת בְּנוֹ נוֹהֵג אֶלָּא בִּשְׁחִיטָה בִּלְבַד שֶׁנֶּאֱמַר (ויקרא כב כח) \"לֹא תִשְׁחֲטוּ\" בִּשְׁחִיטַת שְׁנֵיהֶן הוּא הָאִסּוּר. אֲבָל אִם נָחַר הָרִאשׁוֹן אוֹ נִתְנַבֵּל בְּיָדוֹ מֻתָּר לִשְׁחֹט. וְכֵן אִם שָׁחַט הָרִאשׁוֹן וְנִחָר הַשֵּׁנִי אוֹ נִתְנַבֵּל בְּיָדוֹ פָּטוּר:","חֵרֵשׁ שׁוֹטֶה וְקָטָן שֶׁשָּׁחֲטוּ בֵּינָם לְבֵין עַצְמָן אֶת הָרִאשׁוֹן מֻתָּר לִשְׁחֹט שֵׁנִי אַחֲרֵיהֶם. לְפִי שֶׁאֵין שְׁחִיטָתָן שְׁחִיטָה (כְּלָל):","הַשּׁוֹחֵט אֶת הָרִאשׁוֹן וַהֲרֵי הוּא סְפֵק נְבֵלָה אָסוּר לִשְׁחֹט הַשֵּׁנִי. וְאִם שְׁחָטוֹ אֵינוֹ לוֹקֶה:","שְׁחִיטָה שֶׁאֵינָהּ רְאוּיָה לַאֲכִילָה שְׁמָהּ שְׁחִיטָה. לְפִיכָךְ הָרִאשׁוֹן שֶׁשָּׁחַט חֻלִּין בַּעֲזָרָה אוֹ טְרֵפָה אוֹ שׁוֹר הַנִּסְקָל וְעֶגְלָה עֲרוּפָה וּפָרָה אֲדֻמָּה אוֹ שֶׁשָּׁחַט לְעַכּוּ\"ם וּבָא הָאַחֲרוֹן וְשָׁחַט אֶת הַשֵּׁנִי לוֹקֶה. וְכֵן אִם שָׁחַט הָרִאשׁוֹן אֶת הָאֶחָד וּבָא הָאַחֲרוֹן וְשָׁחַט אֶת הַשֵּׁנִי וַהֲרֵי הוּא חֻלִּין בָּעֲזָרָה אוֹ שׁוֹר הַנִּסְקָל אוֹ עֶגְלָה עֲרוּפָה וּפָרָה אֲדֻמָּה הֲרֵי זֶה לוֹקֶה:","שְׁחָטוֹ לְעַכּוּ\"ם פָּטוּר מִשּׁוּם אוֹתוֹ וְאֶת בְּנוֹ שֶׁהֲרֵי נִתְחַיֵּב בְּנַפְשׁוֹ. וְאִם הִתְרוּ בּוֹ מִשּׁוּם אוֹתוֹ וְאֶת בְּנוֹ וְלֹא הִתְרוּ בּוֹ מִשּׁוּם עַכּוּ\"ם לוֹקֶה:","אֵין אִסּוּר אוֹתוֹ וְאֶת בְּנוֹ נוֹהֵג אֶלָּא בִּבְהֵמָה טְהוֹרָה בִּלְבַד שֶׁנֶּאֱמַר (ויקרא כב כח) \"וְשׁוֹר אוֹ שֶׂה אֹתוֹ וְאֶת בְּנוֹ לֹא תִשְׁחֲטוּ בְּיוֹם אֶחָד\". וְנוֹהֵג בְּכִלְאַיִם. כֵּיצַד. צְבִי שֶׁבָּא עַל הָעֵז וְשָׁחַט הָעֵז וְאֶת בְּנָהּ לוֹקֶה. אֲבָל הָעֵז שֶׁבָּא עַל הַצִּבְיָה אָסוּר לִשְׁחֹט אוֹתָהּ וְאֶת בְּנָהּ. וְאִם שָׁחַט אֵינוֹ לוֹקֶה. פָּרָה וּבְנָהּ אָסְרָה תּוֹרָה לֹא צִבְיָה וּבְנָהּ:","הָיְתָה בַּת הַצִּבְיָה הַזֹּאת נְקֵבָה וְיָלְדָה בֵּן וְשָׁחַט אֶת הַנְּקֵבָה בַּת הַצִּבְיָה וְאֶת בְּנָהּ לוֹקֶה. וְכֵן כִּלְאַיִם הַבָּא מִמִּין כֶּבֶשׂ וּמִמִּין עֵז בֵּין מִכֶּבֶשׂ עִם הָעֵז בֵּין מֵעֵז עִם הַכִּבְשָׂה לוֹקֶה מִשּׁוּם אוֹתוֹ וְאֶת בְּנוֹ:","מֻתָּר לִשְׁחֹט אֶת הַמְעֻבֶּרֶת. עֻבָּר יֶרֶךְ אִמּוֹ הוּא. וְאִם יָצָא הָעֻבָּר חַי אַחַר שְׁחִיטָה וְהִפְרִיס עַל גַּבֵּי קַרְקַע אֵין שׁוֹחֲטִין אוֹתוֹ בְּיוֹם אֶחָד. וְאִם שָׁחַט אֵינוֹ לוֹקֶה:","אִסּוּר אוֹתוֹ וְאֶת בְּנוֹ נוֹהֵג בִּנְקֵבוֹת שֶׁזֶּה בְּנָהּ וַדַּאי. וְאִם נוֹדַע וַדַּאי שֶׁזֶּה הוּא אָבִיו אֵין שׁוֹחֲטִין שְׁנֵיהֶן בְּיוֹם אֶחָד. וְאִם שָׁחַט אֵינוֹ לוֹקֶה. שֶׁהַדָּבָר סָפֵק אִם נוֹהֵג בִּזְכָרִים אוֹ אֵינוֹ נוֹהֵג:","הַשּׁוֹחֵט אֶת הַפָּרָה וְאַחַר כָּךְ שָׁחַט שְׁנֵי בָּנֶיהָ לוֹקֶה שְׁתֵּי מַלְקִיּוֹת. שָׁחַט אֶת בָּנֶיהָ וְאַחַר כָּךְ שָׁחַט הִיא לוֹקֶה אַחַת. שְׁחָטָהּ וְאֶת בִּתָּהּ וְאֶת בֶּן בִּתָּהּ לוֹקֶה שְׁתַּיִם. שְׁחָטָהּ וְאֶת בֶּן בִּתָּהּ וְאַחַר כָּךְ שָׁחַט אֶת הַבַּת לוֹקֶה אַחַת בֵּין הוּא בֵּין אַחֵר:","שְׁנַיִם שֶׁלָּקְחוּ שְׁתֵּי בְּהֵמוֹת זֶה הָאֵם וְזֶה הַבַּת וּבָאוּ לְדִין. זֶה שֶׁלָּקַח רִאשׁוֹן יִשְׁחֹט רִאשׁוֹן וְהַשֵּׁנִי יַמְתִּין לְמָחָר. וְאִם קָדַם הַשֵּׁנִי וְשָׁחַט זָכָה וְיַמְתִּין הָרִאשׁוֹן עַד לְמָחָר:","בְּאַרְבָּעָה פְּרָקִים בְּשָׁנָה הַמּוֹכֵר בְּהֵמָה לַחֲבֵרוֹ צָרִיךְ לְהוֹדִיעוֹ וְלוֹמַר לוֹ כְּבָר מָכַרְתִּי אִמָּהּ אוֹ בִּתָּהּ לְאַחֵר לִשְׁחֹט כְּדֵי שֶׁיַּמְתִּין זֶה הָאַחֲרוֹן וְלֹא יִשְׁחֹט עַד לְמָחָר. וְאֵלּוּ הֵן. עֶרֶב יוֹם טוֹב הָאַחֲרוֹן שֶׁל חַג. וְעֶרֶב יוֹם טוֹב הָרִאשׁוֹן שֶׁל פֶּסַח. וְעֶרֶב עֲצֶרֶת. וְעֶרֶב רֹאשׁ הַשָּׁנָה:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁרָאָה זֶה שֶׁלָּקַח בָּאַחֲרוֹנָה נֶחְפָּז לִקְנוֹת וְהָיָה בְּסוֹף הַיּוֹם שֶׁחֶזְקָתוֹ שֶׁהוּא שׁוֹחֵט עַתָּה. אֲבָל אִם הָיָה רֶוַח בַּיּוֹם אֵינוֹ צָרִיךְ לְהוֹדִיעוֹ שֶׁמָּא לֹא יִשְׁחֹט אֶלָּא לְמָחָר:","וְהַמּוֹכֵר אֶת הָאֵם לֶחָתָן וְהַבַּת לַכַּלָּה צָרִיךְ לְהוֹדִיעָן. שֶׁוַּדַּאי בְּיוֹם אֶחָד שׁוֹחֲטִין. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","יוֹם אֶחָד הָאָמוּר בְּאֹתוֹ וְאֶת בְּנוֹ הַיּוֹם הוֹלֵךְ אַחַר הַלַּיְלָה. כֵּיצַד. הֲרֵי שֶׁשָּׁחַט רִאשׁוֹן בִּתְחִלַּת לֵיל רְבִיעִי לֹא יִשְׁחֹט הַשֵּׁנִי עַד תְּחִלַּת לֵיל חֲמִישִׁי. וְכֵן אִם שָׁחַט הָרִאשׁוֹן בְּסוֹף יוֹם רְבִיעִי קֹדֶם בֵּין הַשְּׁמָשׁוֹת שׁוֹחֵט הַשֵּׁנִי בִּתְחִלַּת לֵיל חֲמִישִׁי. שָׁחַט רִאשׁוֹן בֵּין הַשְּׁמָשׁוֹת שֶׁל לֵיל חֲמִישִׁי לֹא יִשְׁחֹט הַשֵּׁנִי עַד לֵיל שִׁשִּׁי. וְאִם שָׁחַט בְּיוֹם חֲמִישִׁי אֵינוֹ לוֹקֶה:"],"Mishneh Torah, Robbery and Lost Property 10":["עַכּוּ\"ם בַּעַל זְרוֹעַ שֶׁאָנַס נִכְסֵי יִשְׂרָאֵל וְיָרַד לְתוֹךְ שָׂדֵהוּ מֵחֲמַת שֶׁהָיָה לוֹ חוֹב עַל בַּעַל הַשָּׂדֶה אוֹ מֵחֲמַת שֶׁיֵּשׁ לוֹ נֵזֶק בְּיַד זֶה הַיִּשְׂרָאֵל אוֹ מֵחֲמַת שֶׁהִפְסִיד מָמוֹנוֹ. וְאַחַר שֶׁתָּקַף לוֹ אֶת הַשָּׂדֶה מְכָרָהּ לְיִשְׂרָאֵל אַחֵר. אֵין הַבְּעָלִים יְכוֹלִין לְהוֹצִיא מִיַּד הַלּוֹקֵחַ:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהוֹדוּ הַבְּעָלִים שֶׁאֱמֶת טָעַן הָעַכּוּ\"ם [הַמּוֹכֵר אוֹ יָעִידוּ עֵדֵי יִשְׂרָאֵל שֶׁהָאֱמֶת טָעַן הָעַכּוּ\"ם] הַמּוֹכֵר. וְכֵן אִם הָיָה שָׁם מֶלֶךְ אוֹ שַׂר בְּאוֹתוֹ מָקוֹם שֶׁיָּכוֹל לָכֹף אֶת הָעַכּוּ\"ם שֶׁמָּכַר לְדִין וְלֹא תָּבְעוּ הַבְּעָלִים אֶת הָעַכּוּ\"ם אֵינָן יְכוֹלִין לְהוֹצִיא מִיַּד הַלּוֹקֵחַ מִן הָעַכּוּ\"ם אַף עַל פִּי שֶׁאֵינָן מוֹדִין לָעַכּוּ\"ם וְאַף עַל פִּי שֶׁאֵין שָׁם עֵדִים שֶׁאֱמֶת טָעַן הָעַכּוּ\"ם שֶׁהֲרֵי אוֹמֵר הַלּוֹקֵחַ לַבְּעָלִים אִם גַּזְלָן הוּא הָעַכּוּ\"ם לָמָּה לֹא תְּבַעְתֶּם אוֹתוֹ בְּדִינֵיהֶם:","הָעַכּוּ\"ם הַמְּצִיקִים לְיִשְׂרָאֵל וּמְבַקְּשִׁים לְהָרְגָם עַד שֶׁיִּפְדֶּה עַצְמוֹ מִיַּד הָעַכּוּ\"ם בְּשָׂדֵהוּ אוֹ בְּבֵיתוֹ וְיִתְּנֶנָּה לַמֵּצִיק וְאַחַר כָּךְ יַנִּיחֶנּוּ. כְּשֶׁיִּרְצֶה הַמֵּצִיק לִמְכֹּר אוֹתָהּ הַקַּרְקַע אִם יֵשׁ בְּיַד הַבְּעָלִים לִקַּח מִן הַמֵּצִיק הֵן קוֹדְמִין לְכָל אָדָם. וְאִם אֵין בְּיַד הַבְּעָלִים לִקַּח אוֹ שֶׁשָּׁהָה הַקַּרְקַע בְּיַד הַמֵּצִיק שְׁנֵים עָשָׂר חֹדֶשׁ כָּל הַקּוֹדֵם וְלָקַח מִן הַמֵּצִיק זָכָה. וּבִלְבַד שֶׁיִּתֵּן לַבְּעָלִים הָרִאשׁוֹנִים רְבִיעַ הַקַּרְקַע אוֹ שְׁלִישׁ הַמָּעוֹת מִפְּנֵי שֶׁזֶּה הַמֵּצִיק מוֹכֵר בְּזוֹל הוֹאִיל וְקַרְקַע שֶׁאֵינָהּ שֶׁלּוֹ הוּא מוֹכֵר הֲרֵי זֶה מוֹכֵר בְּפָחוֹת רְבִיעַ אוֹ קָרוֹב לוֹ וְזֶה רְבִיעַ שֶׁל בְּעָלִים שֶׁהֲרֵי מֵחֲמַת שֶׁהִיא שֶׁלָּהֶן מוֹכֵר בְּזוֹל. לְפִיכָךְ הַלּוֹקֵחַ מִן הַמֵּצִיק בִּשְׁלֹשִׁים נוֹתֵן לַבְּעָלִים עֲשָׂרָה אוֹ נוֹתֵן לָהֶם רְבִיעַ הַקַּרְקַע וְאַחַר כָּךְ יִקְנֶה הַכּל. וְאִם לֹא נָתַן הֲרֵי רְבִיעַ הַקַּרְקַע כְּגֵזֶל בְּיָדוֹ:","הַיּוֹרֵד לְתוֹךְ שְׂדֵה חֲבֵרוֹ שֶׁלֹּא בִּרְשׁוּת וּנְטָעָהּ אִם הָיְתָה שָׂדֶה הָעֲשׂוּיָה לִטַּע אוֹמְדִין כַּמָּה אָדָם רוֹצֶה לִתֵּן בְּשָׂדֶה זוֹ לִטְּעָהּ וְנוֹטֵל מִבַּעַל הַשָּׂדֶה. וְאִם אֵינָהּ עֲשׂוּיָה לִטַּע שָׁמִין לוֹ וְיָדוֹ עַל הַתַּחְתּוֹנָה:","אָמַר לוֹ בַּעַל הַשָּׂדֶה עֲקֹר אִילָנְךָ וְלֵךְ שׁוֹמְעִים לוֹ. אָמַר הַנּוֹטֵעַ הֲרֵינִי עוֹקֵר אִילָנִי אֵין שׁוֹמְעִין לוֹ מִפְּנֵי שֶׁמַּכְחִישׁ אֶת הַקַּרְקַע:","הַחֲצֵרוֹת הֲרֵי הֵן רְאוּיִין לְבִנְיָן וּלְהוֹסִיף בָּהֶן בָּתִּים וַעֲלִיּוֹת. לְפִיכָךְ הוֹרוּ הַגְּאוֹנִים שֶׁהַבּוֹנֶה בַּחֲצַר חֲבֵרוֹ שֶׁלֹּא מִדַּעְתּוֹ הֲרֵי זֶה כְּנוֹטֵעַ שָׂדֶה הָעֲשׂוּיָה לִטַּע וְשָׁמִין לוֹ כַּמָּה אָדָם רוֹצֶה לִתֵּן בְּבִנְיָן זֶה לִבְנוֹתוֹ. וְהוּא שֶׁיִּבְנֶה בִּנְיָן הַמּוֹעִיל הָרָאוּי לְאוֹתָהּ חָצֵר כְּמִנְהַג אוֹתוֹ מָקוֹם:","הַיּוֹרֵד לִשְׂדֵה חֲבֵרוֹ בִּרְשׁוּת אֲפִלּוּ נָטַע שָׂדֶה שֶׁאֵינָהּ עֲשׂוּיָה לִטַּע שָׁמִין לוֹ וְיָדוֹ עַל הָעֶלְיוֹנָה. שֶׁאִם הָיְתָה הַהוֹצָאָה יֶתֶר עַל הַשֶּׁבַח נוֹטֵל הַהוֹצָאָה וְאִם הַשֶּׁבַח יֶתֶר עַל הַהוֹצָאָה נוֹטֵל הַשֶּׁבַח. וּבַעַל בְּנִכְסֵי אִשְׁתּוֹ וְהַשֻּׁתָּף בְּשָׂדֶה שֶׁיֵּשׁ לוֹ חֵלֶק בָּהּ כְּיוֹרֵד בִּרְשׁוּת הֵן וְשָׁמִין לָהֶם וְיָדָם עַל הָעֶלְיוֹנָה:","הַיּוֹרֵד לִשְׂדֵה חֲבֵרוֹ שֶׁלֹּא בִּרְשׁוּת וְנָטַע אוֹ בָּנָה וְאַחַר כָּךְ בָּא בַּעַל הַשָּׂדֶה וְהִשְׁלִים הַבִּנְיָן אוֹ שֶׁשָּׁמַר הַנְּטִיעוֹת וְכַיּוֹצֵא בְּאֵלּוּ הַדְּבָרִים שֶׁמַּרְאִין שֶׁדַּעְתּוֹ נוֹטָה לְמַה שֶּׁעָשָׂה זֶה וּבִרְצוֹנוֹ בָּא הַדָּבָר שָׁמִין לוֹ וְיָדוֹ עַל הָעֶלְיוֹנָה:","הַיּוֹרֵד לְתוֹךְ חֻרְבָּתוֹ שֶׁל חֲבֵרוֹ וּבְנָאָהּ שֶׁלֹּא בִּרְשׁוּת שָׁמִין לוֹ וְיָדוֹ עַל הַתַּחְתּוֹנָה. וְאִם אָמַר בַּעַל הַבִּנְיָן עֵצַי וַאֲבָנַי אֲנִי נוֹטֵל. בַּבַּיִת שׁוֹמְעִין לוֹ. בַּשָּׂדֶה אֵין שׁוֹמְעִין לוֹ מִפְּנֵי שֶׁמַּכְחִישׁ אֶת הַקַּרְקַע. אָמַר לוֹ בַּעַל הַקַּרְקַע טֹל מַה שֶּׁבָּנִיתָ שׁוֹמְעִין לוֹ:","כָּל מִי שֶׁשָּׁמִין לוֹ בֵּין שֶׁהָיְתָה יָדוֹ עַל הָעֶלְיוֹנָה בֵּין שֶׁהָיְתָה יָדוֹ עַל הַתַּחְתּוֹנָה אֵינוֹ נוֹטֵל כְּלוּם עַד שֶׁיִּשָּׁבַע בִּנְקִיטַת חֵפֶץ כַּמָּה הוֹצִיא. וְאִם אָמַר יָבוֹאוּ הַדַּיָּנִים וְיַעֲשׂוּ שׁוּמַת הַהוֹצָאָה וַהֲרֵי הִיא גְּלוּיָה לְעֵינֵיהֶם וִישַׁעֲרוּ הָעֵצִים וְהָאֲבָנִים וְהַסִּיד וּשְׂכַר הָאֻמָּנִין בַּפָּחוּת שֶׁבַּשְּׁעָרִים שׁוֹמְעִין לוֹ וְנוֹטֵל בְּלֹא שְׁבוּעָה. וְכֵן זֶה שֶׁנּוֹטֵל הַשֶּׁבַח בִּלְבַד וְהָיְתָה יָדוֹ עַל הָעֶלְיוֹנָה אֵין צָרִיךְ שְׁבוּעָה:","כָּל שֶׁשָּׁמִין לוֹ וְנוֹטֵל שֶׁטָּעַן בַּעַל הַשָּׂדֶה וְאָמַר נָתַתִּי וְהַיּוֹרֵד לַשָּׂדֶה אוֹמֵר לֹא נָטַלְתִּי. הַיּוֹרֵד נֶאֱמָן וְנִשְׁבָּע שֶׁלֹּא נָתַן לוֹ כְּלוּם וְנוֹטֵל שֶׁהֲרֵי אוֹמְרִין לְבַעַל הַשָּׂדֶה עֲדַיִן לֹא שָׁמוּ לְךָ וְלֹא יָדַעְתָּ כַּמָּה אַתָּה חַיָּב לִתֵּן הֵיאַךְ נָתַתָּ. אֲבָל אִם שָׁמוּ לוֹ וְאָמְרוּ לְבַעַל הַשָּׂדֶה תֵּן לוֹ וְאָמַר נָתַתִּי אַף עַל פִּי שֶׁעֲדַיִן לֹא נִשְׁבַּע הַיּוֹרֵד הֲרֵי בַּעַל הַשָּׂדֶה נֶאֱמָן וְיִשָּׁבַע שְׁבוּעַת הֶסֵּת שֶׁנָּתַן וְיִפָּטֵר. שֶׁהַקַּרְקַע בְּחֶזְקַת בְּעָלֶיהָ:","בַּעַל שֶׁהוֹרִיד אֲרִיסִין בְּנִכְסֵי אִשְׁתּוֹ וְאַחַר כָּךְ גֵּרְשָׁהּ. אִם הָיָה הַבַּעַל עַצְמוֹ אָרִיס נִסְתַּלֵּק בַּעַל נִסְתַּלְּקוּ אֲרִיסָיו שֶׁלֹּא יָרְדוּ לָהּ אֶלָּא עַל דַּעַת הַבַּעַל. וְשָׁמִין לָהֶם וְיָדָם עַל הַתַּחְתּוֹנָה. וְאִם אֵין הַבַּעַל אָרִיס עַל דַּעַת הַקַּרְקַע יָרְדוּ וְשָׁמִין לָהֶם כְּאָרִיס:"],"Mishneh Torah, Robbery and Lost Property 5":["אָסוּר לִקְנוֹת דָּבָר הַגָּזוּל מִן הַגַּזְלָן וְאָסוּר לְסַעֲדוֹ עַל שִׁנּוּיוֹ כְּדֵי שֶׁיִּקְנֵהוּ. שֶׁכָּל הָעוֹשֶׂה דְּבָרִים אֵלּוּ וְכַיּוֹצֵא בָּהֶן מְחַזֵּק יְדֵי עוֹבְרֵי עֲבֵרָה וְעוֹבֵר עַל (ויקרא יט יד) \"וְלִפְנֵי עִוֵּר לֹא תִתֵּן מִכְשׁל\":","אָסוּר לֵהָנוֹת בְּדָבָר הַגָּזוּל וַאֲפִלּוּ לְאַחַר יֵאוּשׁ. וְהוּא שֶׁיֵּדַע בְּוַדַּאי שֶׁדָּבָר זֶה הוּא הַגְּזֵלָה עַצְמָהּ. כֵּיצַד. יָדַע בְּוַדַּאי שֶׁבְּהֵמָה זוֹ גְּזוּלָה אָסוּר לִרְכֹּב עָלֶיהָ אוֹ לַחְרשׁ בָּהּ:","גָּזַל בַּיִת אוֹ שָׂדֶה אָסוּר לַעֲבֹר בְּתוֹכָהּ אוֹ לִכָּנֵס בָּהּ בַּחַמָּה מִפְּנֵי הַחַמָּה וּבַגְּשָׁמִים מִפְּנֵי הַגְּשָׁמִים. וְאִם דָּר בְּתוֹכָהּ חַיָּב לְהַעֲלוֹת שָׂכָר לַבְּעָלִים כְּדִין הַדָּר בַּחֲצַר חֲבֵרוֹ שֶׁלֹּא מִדַּעְתּוֹ. גָּזַל דְּקָלִים וְעָשָׂה מֵהֶן גֶּשֶׁר אָסוּר לַעֲבֹר עָלָיו. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מִי שֶׁעָבַר וְאָכַל הַגְּזֵלָה אַחַר יֵאוּשׁ פָּטוּר מִלְּשַׁלֵּם. וְאִם אָכַל קֹדֶם יֵאוּשׁ וְרָצוּ הַבְּעָלִים לִגְבּוֹת מִן הָאוֹכֵל גּוֹבִין שֶׁעֲדַיִן בִּרְשׁוּתָן הִיא. וְאִם רָצוּ גּוֹבִין מִן הַגַּזְלָן:","הַגּוֹזֵל וּמֵת בֵּין שֶׁהֶאֱכִיל אֶת הַגְּזֵלָה לַבָּנִים אַחַר יֵאוּשׁ בֵּין שֶׁלֹּא הֶאֱכִילָם אֶלָּא מְכָרָהּ אוֹ אָבְדָה. אִם הִנִּיחַ קַרְקַע חַיָּבִין לְשַׁלֵּם. אֲבָל מִן הַמִּטַּלְטְלִין אֵינָן חַיָּבִין לְשַׁלֵּם. שֶׁדְּמֵי הַגְּזֵלָה חוֹב הֵן עַל הַגַּזְלָן וְאֵין הַמִּטַּלְטְלִין מִשְׁתַּעְבְּדִין לְבַעַל חוֹב:","כְּבָר תִּקְּנוּ הַגְּאוֹנִים לִגְבּוֹת בַּעַל חוֹב מִן הַמִּטַּלְטְלִין וַאֲפִלּוּ בְּמִלְוֶה עַל פֶּה. לְפִיכָךְ חַיָּבִין לְשַׁלֵּם בֵּין אָכְלוּ בֵּין לֹא אָכְלוּ. בֵּין נִתְיָאֲשׁוּ בֵּין לֹא נִתְיָאֲשׁוּ. בֵּין מִן הַקַּרְקַע בֵּין מִן הַמִּטַּלְטְלִין שֶׁהִנִּיחַ:","דִּין הַלּוֹקֵחַ מִטַּלְטְלִין מִן הַגַּזְלָן כְּלוֹקֵחַ מִן הַגַּנָּב. אִם גַּזְלָן מְפֻרְסָם הוּא לֹא עָשׂוּ בּוֹ תַּקָּנַת הַשּׁוּק. וְאִם אֵינוֹ מְפֻרְסָם עָשׂוּ בּוֹ תַּקָּנַת הַשּׁוּק וְנוֹתֵן הַנִּגְזָל דָּמִים שֶׁנָּתַן וְלוֹקֵחַ גְּזֵלָתוֹ וְחוֹזֵר וְתוֹבֵעַ הַגַּזְלָן בִּדְמֵי הַגְּזֵלָה. וְאִם כְּבָר נִתְיָאֲשׁוּ הַבְּעָלִים קָנָה לוֹקֵחַ עַצְמָהּ שֶׁל גְּזֵלָה וְאֵינוֹ מַחְזִירָהּ:","אָסוּר לֵהָנוֹת מִן הַגַּזְלָן וְאִם הָיָה מִעוּט שֶׁלּוֹ אַף עַל פִּי שֶׁרֹב מָמוֹנוֹ גָּזוּל מֻתָּר לֵהָנוֹת מִמֶּנּוּ עַד שֶׁיֵּדַע בְּוַדַּאי שֶׁדָּבָר זֶה גָּזוּל בְּיָדוֹ:","בְּנֵי אָדָם שֶׁחֶזְקָתָן גַּזְלָנִין וְחֶזְקַת כָּל מָמוֹנָן מִן הַגֵּזֶל מִפְּנֵי שֶׁמְּלַאכְתָּן מְלֶאכֶת גַּזְלָנִין כְּגוֹן הַמּוֹכְסִין וְהַלִּסְטִים אָסוּר לֵהָנוֹת מֵהֶן שֶׁחֶזְקַת מְלָאכָה זוֹ שֶׁהוּא גָּזוּל וְאֵין מִצְטָרְפִים דִּינָרִים מִן הַתֵּבָה שֶׁלָּהֶן שֶׁהַכּל בְּחֶזְקַת גְּזֵלָה:","נָטְלוּ מוֹכְסִין כְּסוּתוֹ וְהֶחֱזִירוּ לוֹ אַחֶרֶת (נָטְלוּ חֲמוֹרוֹ וְהֶחֱזִירוּ לוֹ חֲמוֹר אַחֵר). הֲרֵי אֵלּוּ שֶׁלּוֹ מִפְּנֵי שֶׁזּוֹ כִּמְכִירָה הִיא וְחֶזְקָתָהּ שֶׁנִּתְיָאֲשׁוּ הַבְּעָלִים מִמֶּנָּה וְאֵינוֹ יוֹדֵעַ בְּוַדַּאי שֶׁזּוֹ גְּזֵלָה. וְאִם הָיָה וָתִיק וּמַחְמִיר עַל עַצְמוֹ מַחֲזִירָן לַבְּעָלִים הָרִאשׁוֹנִים:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהַמּוֹכֵס כְּלִסְטִים בִּזְמַן שֶׁהַמּוֹכֵס עַכּוּ\"ם אוֹ מוֹכֵס הָעוֹמֵד מֵאֵלָיו אוֹ מוֹכֵס הָעוֹמֵד מֵחֲמַת הַמֶּלֶךְ וְאֵין לוֹ קִצְבָה אֶלָּא לוֹקֵחַ מַה שֶּׁיִּרְצֶה וּמֵנִיחַ מַה שֶּׁיִּרְצֶה. אֲבָל מֶכֶס שֶׁפְּסָקוֹ הַמֶּלֶךְ וְאָמַר שֶׁיִּקַּח שְׁלִישׁ אוֹ רְבִיעַ אוֹ דָּבָר קָצוּב וְהֶעֱמִיד מוֹכֵס יִשְׂרָאֵל לִגְבּוֹת חֵלֶק זֶה לַמֶּלֶךְ וְנוֹדַע שֶׁאָדָם זֶה נֶאֱמָן וְאֵינוֹ מוֹסִיף כְּלוּם עַל מַה שֶּׁגָּזַר הַמֶּלֶךְ אֵינוֹ בְּחֶזְקַת גַּזְלָן לְפִי שֶׁדִּין הַמֶּלֶךְ דִּין הוּא. וְלֹא עוֹד אֶלָּא שֶׁהוּא עוֹבֵר הַמַּבְרִיחַ מִמֶּכֶס זֶה מִפְּנֵי שֶׁהוּא גּוֹזֵל מְנַת הַמֶּלֶךְ בֵּין שֶׁהָיָה הַמֶּלֶךְ עַכּוּ\"ם בֵּין שֶׁהָיָה הַמֶּלֶךְ יִשְׂרָאֵל:","וְכֵן מֶלֶךְ שֶׁמֵּשִׂים מַס עַל בְּנֵי הָעִיר אוֹ עַל כָּל אִישׁ וְאִישׁ דָּבָר קָצוּב מִשָּׁנָה לְשָׁנָה אוֹ עַל כָּל שָׂדֶה וְשָׂדֶה דָּבָר קָצוּב. אוֹ שֶׁגָּזַר שֶׁכָּל מִי שֶׁיַּעֲבֹר עַל דָּבָר זֶה יִלָּקְחוּ כָּל נְכָסָיו לְבֵית הַמֶּלֶךְ. אוֹ כָּל מִי שֶׁיִּמָּצֵא בַּשָּׂדֶה בִּשְׁעַת הַגֹּרֶן הוּא יִתֵּן הַמַּס שֶׁעָלֶיהָ בֵּין שֶׁהָיָה הוּא בַּעַל הַשָּׂדֶה בֵּין שֶׁאֵינוֹ בַּעַל הַשָּׂדֶה וְכָל כַּיּוֹצֵא מִדְּבָרִים אֵלּוּ אֵינוֹ גֵּזֶל וְיִשְׂרָאֵל שֶׁגָּבָה אוֹתָן לַמֶּלֶךְ אֵינוֹ בְּחֶזְקַת גַּזְלָן וַהֲרֵי הוּא כָּשֵׁר. וְהוּא שֶׁלֹּא יוֹסִיף וְלֹא יְשַׁנֶּה וְלֹא יִקַּח לְעַצְמוֹ כְּלוּם:","וְכֵן מֶלֶךְ שֶׁכָּעַס עַל אֶחָד מֵעֲבָדָיו וְשַׁמָּשָׁיו מִבְּנֵי הַמְּדִינָה וְלָקַח שָׂדֵהוּ אוֹ חֲצֵרוֹ אֵינָהּ גֵּזֶל וּמֻתָּר לֵהָנוֹת בָּהּ וְהַלּוֹקְחָהּ מִן הַמֶּלֶךְ הֲרֵי הִיא שֶׁלּוֹ וְאֵין הַבְּעָלִים מוֹצִיאִין אוֹתָהּ מִיָּדוֹ. שֶׁזֶּה דִּין הַמְּלָכִים כֻּלָּם לִקַּח כָּל מָמוֹן שַׁמָּשֵׁיהֶם כְּשֶׁכּוֹעֲסִין עֲלֵיהֶם וַהֲרֵי הַמֶּלֶךְ הִפְקִיעַ שִׁעְבּוּדָן וְנַעֲשֵׂית חָצֵר זוֹ אוֹ שָׂדֶה זוֹ כְּהֶפְקֵר וְכָל הַקּוֹנֶה אוֹתָהּ מִן הַמֶּלֶךְ זָכָה בָּהּ. אֲבָל מֶלֶךְ שֶׁלָּקַח חָצֵר אוֹ שָׂדֶה שֶׁל אֶחָד מִבְּנֵי הַמְּדִינָה שֶׁלֹּא בַּדִּינִין שֶׁחָקַק הֲרֵי זֶה גַּזְלָן וְהַלּוֹקֵחַ מִמֶּנּוּ מוֹצִיאִין הַבְּעָלִים מִיָּדוֹ:","כְּלָלוֹ שֶׁל דָּבָר כָּל דִּין שֶׁיַּחְקֹק אוֹתוֹ הַמֶּלֶךְ לַכּל וְלֹא יִהְיֶה לְאָדָם אֶחָד בִּפְנֵי עַצְמוֹ אֵינוֹ גֵּזֶל. וְכָל שֶׁיִּקַּח מֵאִישׁ זֶה בִּלְבַד שֶׁלֹּא כַּדָּת הַיְדוּעָה לַכּל אֶלָּא חָמַס אֶת זֶה הֲרֵי זֶה גֵּזֶל. לְפִיכָךְ גַּבָּאֵי הַמֶּלֶךְ וְשׁוֹטְרָיו שֶׁמּוֹכְרִים הַשָּׂדוֹת בְּמַס הַקָּצוּב עַל הַשָּׂדוֹת מִמְכָּרָן מִמְכָּר. אֲבָל מַס שֶׁעַל כָּל אִישׁ וְאִישׁ אֵינוֹ גּוֹבֶה אֶלָּא מִן הָאָדָם עַצְמוֹ וְאִם מָכְרוּ הַשָּׂדֶה בְּמַס שֶׁעַל הָרֹאשׁ הֲרֵי זֶה אֵינוֹ מִמְכָּר אֶלָּא אִם כֵּן הָיָה דִּין הַמֶּלֶךְ כָּךְ:","מֶלֶךְ שֶׁהָיוּ דִּינָיו שֶׁכָּל שֶׁלֹּא יִתֵּן הַמַּס שֶׁעַל הַשָּׂדֶה תִּהְיֶה הַשָּׂדֶה לְנוֹתֵן הַמַּס וּבָרַח בַּעַל הַשָּׂדֶה מִפְּנֵי הַמַּס וּבָא זֶה וְנָתַן מַס שֶׁעָלֶיהָ לַמֶּלֶךְ וְאָכַל פֵּרוֹתֶיהָ אֵין זֶה גֵּזֶל אֶלָּא אוֹכֵל פֵּרוֹת וְנוֹתֵן הַמַּס עַד שֶׁיַּחְזְרוּ הַבְּעָלִים שֶׁדִּין הַמֶּלֶךְ דִּין הוּא כְּמוֹ שֶׁאָמַרְנוּ:","וְכֵן מֶלֶךְ שֶׁגָּזַר שֶׁכָּל מִי שֶׁיִּתֵּן מַס הַקָּצוּב עַל הָאִישׁ יִשְׁתַּעְבֵּד בָּזֶה שֶׁלֹּא נָתַן וּבָא יִשְׂרָאֵל וְנָתַן הַמַּס שֶׁעַל יִשְׂרָאֵל זֶה הֶעָנִי הֲרֵי זֶה עוֹבֵד בּוֹ יוֹתֵר מִדַּאי שֶׁדִּין הַמֶּלֶךְ דִּין. אֲבָל אֵינוֹ עוֹבֵד בּוֹ כְּעֶבֶד:","מֶלֶךְ שֶׁכָּרַת אִילָנוֹת שֶׁל בַּעֲלֵי בָּתִּים וְעָשָׂה מֵהֶן גֶּשֶׁר מֻתָּר לַעֲבֹר עָלָיו. וְכֵן אִם הָרַס בָּתִּים וַעֲשָׂאָן דֶּרֶךְ אוֹ חוֹמָה מֻתָּר לֵהָנוֹת בָּהּ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה שֶׁדִּין הַמֶּלֶךְ דִּין:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּמֶלֶךְ שֶׁמַּטְבְּעוֹ יוֹצֵא בְּאוֹתָן הָאֲרָצוֹת שֶׁהֲרֵי הִסְכִּימוּ עָלָיו בְּנֵי אוֹתָהּ הָאָרֶץ וְסָמְכָה דַּעְתָּן שֶׁהוּא אֲדוֹנֵיהֶם וְהֵם לוֹ עֲבָדִים. אֲבָל אִם אֵין מַטְבְּעוֹ יוֹצֵא הֲרֵי הוּא כְּגַזְלָן בַּעַל זְרוֹעַ וּכְמוֹ חֲבוּרַת לִסְטִים הַמְזֻיָּנִין שֶׁאֵין דִּינֵיהֶן דִּין וְכֵן מֶלֶךְ זֶה וְכָל עֲבָדָיו גַּזְלָנִין לְכָל דָּבָר:"],"Mishneh Torah, Sabbath 16":["מָקוֹם שֶׁלֹּא הֻקַּף לְדירָה אֶלָּא שֶׁיִּהְיֶה תַּשְׁמִישׁוֹ לַאֲוִיר כְּגוֹן גַּנּוֹת וּפַרְדֵּסִים וּכְגוֹן הַמַּקִּיף מָקוֹם מִן הָאָרֶץ לְשָׁמְרוֹ וְכַיּוֹצֵא בָּהֶן. אִם יֵשׁ בְּגֹבַהּ הַמְּחִצּוֹת עֲשָׂרָה טְפָחִים אוֹ יֶתֶר הֲרֵי הוּא כִּרְשׁוּת הַיָּחִיד לְחַיֵּב הַמּוֹצִיא וְהַזּוֹרֵק וְהַמּוֹשִׁיט מִמֶּנּוּ לִרְשׁוּת הָרַבִּים אוֹ מֵרְשׁוּת הָרַבִּים לְתוֹכוֹ. וְאֵין מְטַלְטְלִין בְּכֻלּוֹ אֶלָּא אִם כֵּן יֵשׁ בּוֹ בֵּית סָאתַיִם אוֹ פָּחוֹת. אֲבָל אִם הָיָה בּוֹ יֶתֶר עַל בֵּית סָאתַיִם אָסוּר לְטַלְטֵל בּוֹ אֶלָּא בְּאַרְבַּע אַמּוֹת כְּכַרְמְלִית:","וְכֵן עַמּוּד שֶׁגָּבוֹהַּ עֲשָׂרָה טְפָחִים וְרָחָב עַד בֵּית סָאתַיִם מְטַלְטְלִין עַל כֻּלּוֹ. הָיָה רָחָב עַל בֵּית סָאתַיִם אֵין מְטַלְטְלִין בּוֹ אֶלָּא בְּאַרְבַּע אַמּוֹת. סֶלַע שֶׁבַּיָּם הָיָה גָּבוֹהַּ פָּחוֹת מֵעֲשָׂרָה מְטַלְטְלִין מִתּוֹכוֹ לַיָּם וּמִן הַיָּם לְתוֹכוֹ שֶׁהַכּל כַּרְמְלִית. הָיָה גָּבוֹהַּ עֲשָׂרָה אִם הָיָה רָחְבּוֹ מֵאַרְבָּעָה טְפָחִים עַד בֵּית סָאתַיִם הוֹאִיל וּמֻתָּר לְטַלְטֵל בְּכֻלּוֹ אֵין מְטַלְטְלִין לֹא מִתּוֹכוֹ לַיָּם וְלֹא מִן הַיָּם לְתוֹכוֹ. הָיָה יֶתֶר מִבֵּית סָאתַיִם אַף עַל פִּי שֶׁהוּא רְשׁוּת הַיָּחִיד הוֹאִיל וְאָסוּר לְטַלְטֵל בּוֹ אֶלָּא בְּאַרְבַּע אַמּוֹת כְּכַרְמְלִית הֲרֵי זֶה מֻתָּר לְטַלְטֵל מִתּוֹכוֹ לַיָּם וּמִן הַיָּם לְתוֹכוֹ שֶׁזֶּה דָּבָר שֶׁאֵינוֹ מָצוּי הוּא וְלֹא גָּזְרוּ בּוֹ:","כַּמָּה הִיא בֵּית סְאָה חֲמִשִּׁים אַמָּה עַל חֲמִשִּׁים אַמָּה. נִמְצָא בֵּית סָאתַיִם מָקוֹם שֶׁיֵּשׁ בְּתִשְׁבָּרְתוֹ חֲמֵשֶׁת אֲלָפִים אַמָּה. וְכָל מָקוֹם שֶׁיֵּשׁ בּוֹ כַּמִּדָּה הַזֹּאת בֵּין שֶׁהָיָה מְרֻבָּע שֶׁהוּא שִׁבְעִים אַמָּה וְשִׁירַיִם עַל שִׁבְעִים אַמָּה וְשִׁירַיִם בֵּין שֶׁהָיָה עָגל בֵּין שְׁאָר הַצּוּרוֹת הֲרֵי זֶה נִקְרָא בֵּית סָאתַיִם:","מָקוֹם שֶׁלֹּא הֻקַּף לְדִירָה שֶׁיֵּשׁ בּוֹ בֵּית סָאתַיִם אִם הָיָה אָרְכּוֹ פִּי שְׁנַיִם כְּרָחְבּוֹ כְּדֵי שֶׁיִּהְיֶה מֵאָה עַל חֲמִשִּׁים כַּחֲצַר הַמִּשְׁכָּן מֻתָּר לְטַלְטֵל בְּכֻלּוֹ. אֲבָל אִם הָיָה אָרְכּוֹ יֶתֶר עַל שְׁנַיִם כְּרָחְבּוֹ אֲפִלּוּ אַמָּה אֵין מְטַלְטְלִין בּוֹ אֶלָּא בְּאַרְבַּע אַמּוֹת. שֶׁלֹּא עָשׂוּ בֵּית סָאתַיִם שֶׁתַּשְׁמִישׁוֹ לַאֲוִיר כִּשְׁאָר הַחֲצֵרוֹת אֶלָּא מֵחֲצַר הַמִּשְׁכָּן:","מָקוֹם שֶׁהֻקַּף שֶׁלֹּא לְשֵׁם דִּירָה אִם פָּרַץ בּוֹ פִּרְצָה יֶתֶר עַל עֶשֶׂר אַמּוֹת בְּגֹבַהּ עֲשָׂרָה טְפָחִים וְגָדַר בָּהּ לְשֵׁם דִּירָה עַד עֲשָׂרָה מֻתָּר לְטַלְטֵל בְּכֻלָּהּ. וַאֲפִלּוּ פָּרַץ אַמָּה וּגְדָרָהּ לְשֵׁם דִּירָה וּפָרַץ אַמָּה וּגְדָרָהּ לְשֵׁם דִּירָה עַד שֶׁהִשְׁלִימָהּ לְיֶתֶר מֵעֶשֶׂר מֻתָּר לְטַלְטֵל בְּכֻלָּהּ אַף עַל פִּי שֶׁיֵּשׁ בּוֹ כַּמָּה מִילִין:","מָקוֹם יָתֵר מִבֵּית סָאתַיִם שֶׁהֻקַּף לְדִירָה אִם נִזְרַע רֻבּוֹ הֲרֵי הוּא כְּגִנָּה וְאָסוּר לְטַלְטֵל בְּכֻלּוֹ. נִזְרַע מִעוּטוֹ אִם נִזְרַע מִמֶּנּוּ בֵּית סָאתַיִם מֻתָּר לְטַלְטֵל בְּכֻלּוֹ. וְאִם הָיָה הַמָּקוֹם הַזָּרוּעַ יֶתֶר מִבֵּית סָאתַיִם אָסוּר לְטַלְטֵל בְּכֻלּוֹ. נָטַע רֻבּוֹ הֲרֵי הוּא כְּחָצֵר וּמֻתָּר לְטַלְטֵל בְּכֻלּוֹ. נִתְמַלֵּא מַיִם אֲפִלּוּ הָיוּ עֲמֻקִּים הַרְבֵּה אִם הָיוּ רְאוּיִין לְתַשְׁמִישׁ הֲרֵי הֵן כִּנְטָעִים וּמֻתָּר לְטַלְטֵל בְּכֻלּוֹ. וְאִם אֵינָן רְאוּיִין לְתַשְׁמִישׁ אֵין מְטַלְטְלִין בּוֹ אֶלָּא בְּאַרְבַּע אַמּוֹת:","מָקוֹם שֶׁהֻקַּף שֶׁלֹּא לְשֵׁם דִּירָה שֶׁיֵּשׁ בּוֹ בֵּית שָׁלֹשׁ סְאִין וְקֵרוּ בּוֹ בֵּית סְאָה קֵרוּיוֹ מַתִּירוֹ שֶׁפִּי תִּקְרָה יוֹרֵד וְסוֹתֵם. נִפְרַץ בִּמְלוֹאוֹ לֶחָצֵר וְנִפְרְצָה חָצֵר כְּנֶגְדּוֹ. חָצֵר מֻתֶּרֶת כְּשֶׁהָיְתָה וְהַקַּרְפַּף אָסוּר כְּשֶׁהָיָה. שֶׁאֵין אֲוִיר הֶחָצֵר מַתִּירוֹ:","הָיָה יֶתֶר מִבֵּית סָאתַיִם וּבָא לְמַעֲטוֹ בָּאִילָנוֹת אֵינוֹ מִעוּט. בָּנָה בּוֹ עַמּוּד בְּצַד הַכֹּתֶל גָּבוֹהַּ עֲשָׂרָה וְרָחָב שְׁלֹשָׁה אוֹ יֶתֶר הֲרֵי זֶה מִעוּט. פָּחוֹת מִשְּׁלֹשָׁה אֵינוֹ מִעוּט שֶׁכָּל פָּחוֹת מִשְּׁלֹשָׁה כְּלָבוּד דָּמִי. וְכֵן אִם הִרְחִיק מִן הַכֹּתֶל שְׁלֹשָׁה וְעָשָׂה מְחִצָּה הֲרֵי זֶה מִעוּט. פָּחוֹת מִשְּׁלֹשָׁה לֹא עָשָׂה כְּלוּם:","טָח אֶת הַכֹּתֶל בְּטִיט אַף עַל פִּי שֶׁאֵינוֹ יָכוֹל לַעֲמֹד בִּפְנֵי עַצְמוֹ הֲרֵי זֶה מִעוּט. הִרְחִיק מִן הַתֵּל שְׁלֹשָׁה וְעָשָׂה מְחִצָּה הוֹעִיל. עָשָׂה מְחִצָּה עַל שְׂפַת הַתֵּל אֵינוֹ מוֹעִיל שֶׁהָעוֹשֶׂה מְחִצָּה עַל גַּבֵּי מְחִצָּה אֵינוֹ מוֹעִיל. נִבְלְעָה מְחִצָּה הַתַּחְתּוֹנָה וַהֲרֵי הָעֶלְיוֹנָה קַיֶּמֶת. הוֹאִיל וְנַעֲשֵׂית הָעֶלְיוֹנָה לְשֵׁם דִּירָה וַהֲרֵי אֵין שָׁם נִרְאֶה אֶלָּא הִיא הֲרֵי זֶה הוֹעִיל וּמֻתָּר לְטַלְטֵל בְּכֻלָּהּ:","רְחָבָה שֶׁאֲחוֹרֵי בָּתִּים יְתֵרָה עַל בֵּית סָאתַיִם אֵין מְטַלְטְלִין בָּהּ אֶלָּא בְּאַרְבַּע. וַאֲפִלּוּ הָיָה פֶּתַח הַבַּיִת פָּתוּחַ לְתוֹכָהּ. וְאִם פָּתַח הַפֶּתַח לְשָׁם וְאַחַר כָּךְ הִקִּיפָה הֲרֵי זוֹ כְּמֻקֶּפֶת לְדִירָה וּמֻתָּר לְטַלְטֵל בְּכֻלָּהּ:","רְחָבָה הַפְּתוּחָה לַמְּדִינָה מִצַּד אֶחָד וּמִצַּד אַחֵר פְּתוּחָה לַשְּׁבִיל הַמַּגִּיעַ לַנָּהָר. עוֹשֶׂה לָהּ לֶחִי מִצַּד הַמְּדִינָה וְיִהְיֶה מֻתָּר לְטַלְטֵל בְּכֻלָּהּ וּמִתּוֹכָהּ לַמְּדִינָה וּמִן הַמְּדִינָה לְתוֹכָהּ:","יָחִיד שֶׁשָּׁבַת בְּבִקְעָה וְעָשָׂה מְחִצָּה סָבִיב לוֹ אִם יֵשׁ בָּהּ עַד בֵּית סָאתַיִם מֻתָּר לְטַלְטֵל בְּכֻלָּהּ. וְאִם הָיְתָה יֶתֶר עַל בֵּית סָאתַיִם אֵינוֹ מְטַלְטֵל בָּהּ אֶלָּא בְּאַרְבַּע אַמּוֹת. וְכֵן אִם הָיוּ שְׁנַיִם. אֲבָל שְׁלֹשָׁה יִשְׂרְאֵלִים אוֹ יֶתֶר עֲלֵיהֶן שֶׁשָּׁבְתוּ בְּבִקְעָה הֲרֵי הֵן שַׁיָּרָא וּמֻתָּר לָהֶם לְטַלְטֵל בְּכָל צָרְכָּן אֲפִלּוּ כַּמָּה מִילִין. וְהוּא שֶׁלֹּא יִשָּׁאֵר מִן הַמְּחִצָּה שֶׁהִקִּיפוּ בֵּית סָאתַיִם פָּנוּי בְּלֹא כֵּלִים. אֲבָל אִם נִשְׁאָר בֵּית סָאתַיִם פָּנוּי בְּלֹא כֵּלִים וְלֹא הָיוּ צְרִיכִים לוֹ אֲסוּרִים לְטַלְטֵל בְּכָל הַמְּחִצָּה אֶלָּא בְּאַרְבַּע אַמּוֹת. וְאֵין הַקָּטָן מַשְׁלִים לְשַׁיָּרָא:","שְׁלֹשָׁה שֶׁהִקִּיפוּ כְּדֵי צָרְכָּן וְקָנוּ שְׁבִיתָה וְאַחַר כָּךְ מֵת אֶחָד מֵהֶן הֲרֵי הֵם מֻתָּרִין לְטַלְטֵל בְּכֻלָּהּ. קָנוּ שְׁנַיִם שְׁבִיתָה בְּיֶתֶר מִבֵּית סָאתַיִם וְאַחַר כָּךְ בָּא לָהֶם שְׁלִישִׁי אֲסוּרִין לְטַלְטֵל אֶלָּא בְּאַרְבַּע אַמּוֹת כְּשֶׁהָיוּ קֹדֶם שֶׁיָּבוֹא זֶה. שֶׁהַשְּׁבִיתָה הִיא הַגּוֹרֶמֶת לֹא הַדִּיּוּרִין:","שְׁלֹשָׁה מְקוֹמוֹת הַמֻּקָּפִין שֶׁלֹּא לְשֵׁם דִּירָה זֶה בְּצַד זֶה וּפְתוּחִים זֶה לָזֶה שְׁנַיִם הַחִיצוֹנִים רְחָבִים וְהָאֶמְצָעִי קָצָר שֶׁנִּמְצְאוּ לַשְּׁנַיִם הַחִיצוֹנִים פַּסִּין מִכָּאן וּמִכָּאן וְהָיָה יָחִיד בָּזֶה וְיָחִיד בָּזֶה וְיָחִיד בָּזֶה נַעֲשׂוּ כְּשַׁיָּרָא וְנוֹתְנִין לָהֶם כָּל צָרְכָּן. הָיָה הָאֶמְצָעִי רָחָב וּשְׁנַיִם הַחִיצוֹנִים קְצָרִים שֶׁנִּמְצָא הָאֶמְצָעִי בְּפַסִּין מִשְּׁנֵי רוּחוֹתָיו הֲרֵי הוּא מֻבְדָּל מִשְּׁנַיִם הַחִיצוֹנִים. לְפִיכָךְ אִם שָׁבַת יָחִיד בָּזֶה וְיָחִיד בָּזֶה וְיָחִיד בָּזֶה אֵין נוֹתְנִין לָהֶן כָּל צָרְכָּן אֶלָּא כָּל אֶחָד וְאֶחָד יֵשׁ לוֹ בֵּית סָאתַיִם בִּמְקוֹמוֹ. הָיָה יָחִיד בָּזֶה וְיָחִיד בָּזֶה וּשְׁנַיִם בָּאֶמְצָעִי אוֹ שְׁנַיִם בָּזֶה וּשְׁנַיִם בָּזֶה וְאֶחָד בָּאֶמְצָעִי נוֹתְנִין לָהֶן כָּל צָרְכָּן:","כָּל מְחִצָּה שֶׁאֵינָהּ יְכוֹלָה לַעֲמֹד בְּרוּחַ מְצוּיָה אֵינָהּ מְחִצָּה. וְכָל מְחִצָּה שֶׁאֵינָהּ עֲשׂוּיָה לְנַחַת אֵינָהּ מְחִצָּה. וְכָל מְחִצָּה שֶׁאֵינָהּ עֲשׂוּיָה אֶלָּא לִצְנִיעוּת בִּלְבַד אֵינָהּ מְחִצָּה. וְכָל מְחִצָּה שֶׁאֵין בְּגָבְהָהּ עֲשָׂרָה טְפָחִים אוֹ יוֹתֵר אֵינָהּ מְחִצָּה גְּמוּרָה. גִּדּוּד חֲמִשָּׁה וּמְחִצָּה חֲמִשָּׁה מִצְטָרְפִין:","כָּל מְחִצָּה שֶׁיֵּשׁ בָּהּ פָּרוּץ מְרֻבֶּה עַל הָעוֹמֵד אֵינָהּ מְחִצָּה. אֲבָל אִם הָיָה פָּרוּץ כְּעוֹמֵד הֲרֵי זוֹ מֻתֶּרֶת. וּבִלְבַד שֶׁלֹּא יִהְיֶה בְּאוֹתָן הַפְּרָצוֹת פִּרְצָה שֶׁהִיא יֶתֶר עַל עֶשֶׂר אַמּוֹת. אֲבָל עֶשֶׂר אַמּוֹת הֲרֵי הִיא כְּפֶתַח. אִם הָיָה לְפִרְצָה זוֹ צוּרַת פֶּתַח אַף עַל פִּי שֶׁיֵּשׁ בָּהּ יוֹתֵר מֵעֶשֶׂר אֵינָהּ מַפְסֶדֶת הַמְּחִצָּה. וְהוּא שֶׁלֹּא יְהֵא הַפָּרוּץ מְרֻבֶּה עַל הָעוֹמֵד:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁהַפְּרָצוֹת מִשְּׁלֹשָׁה טְפָחִים וּלְמַעְלָה. אֲבָל אִם הָיוּ הַפְּרָצוֹת כָּל פִּרְצָה מֵהֶן פְּחוּתָה מִשְּׁלֹשָׁה הֲרֵי זוֹ מֻתֶּרֶת. וְאַף עַל פִּי שֶׁהַפָּרוּץ מְרֻבֶּה עַל הָעוֹמֵד. שֶׁכָּל פָּחוֹת מִשְּׁלֹשָׁה הֲרֵי הוּא כְּלָבוּד:","כֵּיצַד. הֲרֵי שֶׁהִקִּיף בְּקָנִים וְאֵין בֵּין קָנֶה לַחֲבֵרוֹ שְׁלֹשָׁה טְפָחִים. אוֹ שֶׁהִקִּיף בַּחֲבָלִים וְאֵין בֵּין חֶבֶל לַחֲבֵרוֹ שְׁלֹשָׁה טְפָחִים. הֲרֵי זוֹ מְחִצָּה גְּמוּרָה. אַף עַל פִּי שֶׁהִיא שְׁתִי בְּלֹא עֵרֶב אוֹ עֵרֶב בְּלֹא שְׁתִי. וְצָרִיךְ שֶׁיִּהְיֶה גֹּבַהּ הַקָּנֶה עֲשָׂרָה אוֹ שֶׁיִּהְיֶה מִן הָאָרֶץ עַד סוֹף עֹבִי הַחֶבֶל הָעֶלְיוֹן עֲשָׂרָה אִם הִקִּיף בַּחֲבָלִים. שֶׁאֵין מְחִצָּה פְּחוּתָה מֵעֲשָׂרָה. וְכָל הַשִּׁעוּרִין הָאֵלּוּ הֲלָכָה לְמשֶׁה מִסִּינַי הֵן:","צוּרַת פֶּתַח הָאֲמוּרָה בְּכָל מָקוֹם הִיא אֲפִלּוּ קָנֶה וְכַיּוֹצֵא בּוֹ מִכָּאן וְקָנֶה מִכָּאן וְקָנֶה עַל גַּבֵּיהֶן. גֹּבַהּ שְׁנֵי הַלְּחָיַיִם עֲשָׂרָה טְפָחִים אוֹ יֶתֶר וְהַקָּנֶה וְכַיּוֹצֵא בּוֹ שֶׁעַל גַּבֵּיהֶן אַף עַל פִּי שֶׁאֵינוֹ נוֹגֵעַ בִּשְׁנֵי הַלְּחָיַיִם אֶלָּא יֵשׁ בֵּינֵיהֶן כַּמָּה אַמּוֹת הוֹאִיל וְגֹבַהּ הַלְּחָיַיִם עֲשָׂרָה הֲרֵי זוֹ צוּרַת פֶּתַח. וְצוּרַת פֶּתַח שֶׁאָמְרוּ צְרִיכָה שֶׁתְּהֵא בְּרִיאָה לְקַבֵּל דֶּלֶת אֲפִלּוּ דֶּלֶת שֶׁל קַשׁ:","פָּתַח שֶׁצּוּרָתוֹ כִּפָּה אִם יֵשׁ בְּאֹרֶךְ רַגְלֵי הַכִּפָּה עֲשָׂרָה טְפָחִים הֲרֵי זֶה צוּרַת פֶּתַח. וְצוּרַת פֶּתַח שֶׁעָשָׂה אוֹתָהּ מִן הַצַּד אֵינָהּ כְּלוּם שֶׁאֵין דֶּרֶךְ הַפְּתָחִים לִהְיוֹת בְּקֶרֶן זָוִית אֶלָּא בְּאֶמְצַע:","בַּכּל עוֹשִׂין מְחִצָּה בֵּין בְּכֵלִים בֵּין בָּאֳכָלִים בֵּין בְּאָדָם אֲפִלּוּ בִּבְהֵמָה וּשְׁאָר מִינֵי חַיָּה וְעוֹף וְהוּא שֶׁיִּהְיוּ כְּפוּתִים כְּדֵי שֶׁלֹּא יָנוּדוּ:","מְחִצָּה הָעוֹמֶדֶת מֵאֵלֶיהָ הֲרֵי זוֹ כְּשֵׁרָה. וּמְחִצָּה הַנַּעֲשֵׂית בְּשַׁבָּת הֲרֵי זוֹ מְחִצָּה. וְאִם נַעֲשֵׂית בִּשְׁגָגָה מֻתָּר לְטַלְטֵל בָּהּ בְּאוֹתָהּ שַׁבָּת. וְהוּא שֶׁתֵּעָשֶׂה שֶׁלֹּא לְדַעַת הַמְּטַלְטֵל. אֲבָל אִם נִתְכַּוֵּן אָדָם לְזוֹ הַמְּחִצָּה שֶׁתֵּעָשֶׂה בְּשַׁבָּת כְּדֵי לְטַלְטֵל בָּהּ אַף עַל פִּי שֶׁעָשָׂה אוֹתָהּ הָעוֹשֶׂה בִּשְׁגָגָה אָסוּר לְטַלְטֵל בָּהּ בְּאוֹתָהּ שַׁבָּת. וְכֵן אִם נַעֲשֵׂית בְּמֵזִיד אַף עַל פִּי שֶׁלֹּא נִתְכַּוֵּן זֶה לְטַלְטֵל בָּהּ הֲרֵי זֶה אָסוּר לְטַלְטֵל בָּהּ:","מֻתָּר לַעֲשׂוֹת מְחִצָּה שֶׁל בְּנֵי אָדָם בְּשַׁבָּת שֶׁיַּעֲמֹד זֶה בְּצַד זֶה וּבִלְבַד שֶׁלֹּא יֵדְעוּ אֵלּוּ הָעוֹמְדִין שֶׁבִּשְׁבִיל לַעֲשׂוֹתָן מְחִצָּה הֶעֱמִידָן. וְלֹא יַעֲמִיד אוֹתָן אָדָם שֶׁהוּא רוֹצֶה לְהִשְׁתַּמֵּשׁ בִּמְחִצָּה זוֹ אֶלָּא יַעֲמִיד אוֹתָן אַחֵר שֶׁלֹּא לְדַעְתּוֹ:","אִילָן שֶׁהוּא מֵסֵךְ עַל הָאָרֶץ אִם אֵין נוֹפוֹ גָּבוֹהַּ מִן הָאָרֶץ שְׁלֹשָׁה טְפָחִים מְמַלֵּא בֵּין בָּדָיוֹ וְעָלָיו תֶּבֶן וְקַשׁ וְכַיּוֹצֵא בָּהֶן וְקוֹשְׁרָן בָּאָרֶץ עַד שֶׁיַּעֲמֹד בְּרוּחַ מְצוּיָה וְלֹא יִתְנַדְנֵד וּמְטַלְטֵל תַּחַת כֻּלּוֹ. וְהוּא שֶׁיִּהְיוּ תַּחְתָּיו עַד בֵּית סָאתַיִם. אֲבָל אִם הָיָה יֶתֶר מִבֵּית סָאתַיִם אֵין מְטַלְטְלִין תַּחְתָּיו אֶלָּא בְּאַרְבַּע אַמּוֹת מִפְּנֵי שֶׁתַּחְתָּיו מָקוֹם שֶׁלֹּא הֻקַּף לְדִירָה הוּא:"],"Mishneh Torah, Sabbath 27":["הַיּוֹצֵא חוּץ לִתְחוּם הַמְּדִינָה בְּשַׁבָּת לוֹקֶה שֶׁנֶּאֱמַר (שמות טז כט) \"אַל יֵצֵא אִישׁ מִמְּקֹמוֹ בַּיּוֹם הַשְּׁבִיעִי\". מָקוֹם זֶה הוּא תְּחוּם הָעִיר. וְלֹא נָתְנָה תּוֹרָה שִׁעוּר לִתְחוּם זֶה אֲבָל חֲכָמִים הֶעְתִּיקוּ שֶׁתְּחוּם זֶה הוּא חוּץ לִשְׁנֵים עָשָׂר מִיל כְּנֶגֶד מַחֲנֵה יִשְׂרָאֵל. וְכָךְ אָמַר לָהֶם משֶׁה רַבֵּנוּ לֹא תֵּצְאוּ חוּץ לַמַּחֲנֶה. וּמִדִּבְרֵי סוֹפְרִים שֶׁלֹּא יֵצֵא אָדָם חוּץ לָעִיר אֶלָּא עַד אַלְפַּיִם אַמָּה אֲבָל חוּץ לְאַלְפַּיִם אַמָּה אָסוּר. שֶׁאַלְפַּיִם אַמָּה הוּא מִגְרַשׁ הָעִיר:","נִמְצֵאתָ לָמֵד שֶׁמֻּתָּר לְאָדָם בְּשַׁבָּת לְהַלֵּךְ אֶת כָּל הָעִיר כֻּלָּהּ אֲפִלּוּ הָיְתָה כְּנִינְוֵה. בֵּין שֶׁהָיְתָה מֻקֶּפֶת חוֹמָה בֵּין שֶׁלֹּא הָיְתָה מֻקֶּפֶת חוֹמָה. וְכֵן מֻתָּר לוֹ לְהַלֵּךְ חוּץ לָעִיר אַלְפַּיִם אַמָּה לְכָל רוּחַ מְרֻבָּעוֹת כְּטַבְלָה מְרֻבַּעַת כְּדֵי שֶׁיִּהְיֶה נִשְׂכָּר אֶת הַזָּוִיּוֹת. וְאִם יָצָא חוּץ לְאַלְפַּיִם אַמָּה מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת עַד שְׁנֵים עָשָׂר מִיל. אֲבָל אִם יָצָא וְהִרְחִיק מִן הָעִיר יֶתֶר עַל שְׁנֵים עָשָׂר מִיל אֲפִלּוּ אַמָּה אַחַת לוֹקֶה מִן הַתּוֹרָה:","הַמְהַלֵּךְ חוּץ לַתְּחוּם לְמַעְלָה מֵעֲשָׂרָה טְפָחִים כְּגוֹן שֶׁקָּפַץ עַל גַּבֵּי עַמּוּדִים שֶׁגְּבוֹהִין עֲשָׂרָה וְאֵין בְּכָל אֶחָד מֵהֶן אַרְבָּעָה עַל אַרְבָּעָה טְפָחִים הֲרֵי זֶה סָפֵק אִם יֵשׁ תְּחוּמִין לְמַעְלָה מֵעֲשָׂרָה אוֹ אֵין תְּחוּמִין לְמַעְלָה מֵעֲשָׂרָה. אֲבָל אִם הָלַךְ עַל מָקוֹם שֶׁיֵּשׁ בּוֹ אַרְבָּעָה עַל אַרְבָּעָה הֲרֵי זֶה כִּמְהַלֵּךְ עַל הָאָרֶץ וְיֵשׁ אִסּוּר תְּחוּמִין שָׁם:","מִי שֶׁשָּׁבַת בְּדִיר שֶׁבַּמִּדְבָּר אוֹ בְּסַהַר אוֹ בִּמְעָרָה וְכַיּוֹצֵא בָּהֶן מֵרְשׁוּת הַיָּחִיד מְהַלֵּךְ אֶת כֻּלָּהּ וְחוּצָה לָהּ אַלְפַּיִם אַמָּה לְכָל רוּחַ בְּרִבּוּעַ. וְכֵן הַשּׁוֹבֵת בְּבִקְעָה אֲפִלּוּ הָיָה יָשֵׁן בְּשָׁעָה שֶׁנִּכְנַס הַשַּׁבָּת שֶׁלֹּא קָנָה שְׁבִיתָה יֵשׁ לוֹ לְהַלֵּךְ מִמְּקוֹמוֹ אַלְפַּיִם אַמָּה לְכָל רוּחַ בְּרִבּוּעַ. הָיָה מְהַלֵּךְ בְּבִקְעָה וְאֵינוֹ יוֹדֵעַ תְּחוּם שַׁבָּת מְהַלֵּךְ אַלְפַּיִם פְּסִיעוֹת בֵּינוֹנִיּוֹת וְזֶה הוּא תְּחוּם שַׁבָּת:","הַמְהַלֵּךְ אַלְפַּיִם אַמָּה שֶׁיֵּשׁ לוֹ לְהַלֵּךְ וְשָׁלְמָה מִדָּתוֹ בְּתוֹךְ דִּיר אוֹ סַהַר אוֹ מְעָרָה אוֹ בְּתוֹךְ הַמְּדִינָה אֵינוֹ מְהַלֵּךְ אֶלָּא עַד סוֹף מִדָּתוֹ. וְאֵין אוֹמְרִין הוֹאִיל וְכִלְּתָה מִדָּתוֹ בְּתוֹךְ רְשׁוּת הַיָּחִיד מְהַלֵּךְ אֶת כֻּלָּהּ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁכָּלְתָה מִדָּתוֹ בְּמִקְצָת הָעִיר אוֹ בְּמִקְצָת הַמְּעָרָה אֲבָל אִם הָיְתָה אוֹתָהּ רְשׁוּת הַיָּחִיד מֻבְלַעַת בְּתוֹךְ אַלְפַּיִם אַמָּה שֶׁלּוֹ תֵּחָשֵׁב לוֹ כָּל אוֹתָהּ הָרְשׁוּת כְּאַרְבַּע אַמּוֹת וּמַשְׁלִימִין לוֹ אֶת הַשְּׁאָר:","כֵּיצַד. הֲרֵי שֶׁהָיָה אֶלֶף אַמָּה מִמְּקוֹם שְׁבִיתָתוֹ אִם מִחוּץ לָעִיר עַד מְדִינָה אוֹ מְעָרָה שֶׁיֵּשׁ בְּאָרְכָּהּ אֶלֶף אַמָּה אוֹ פָּחוֹת מֵאֶלֶף מְהַלֵּךְ אֶת כָּל הַמְּדִינָה אוֹ הַמְּעָרָה שֶׁפָּגַע בָּהּ וּמְהַלֵּךְ חוּצָה לָהּ אֶלֶף אַמָּה פָּחוֹת אַרְבַּע אַמּוֹת:","אֲבָל אִם הָיָה בַּמְּדִינָה אוֹ בַּמְּעָרָה שֶׁפָּגַע בָּהּ בְּתוֹךְ מִדָּתוֹ אֶלֶף אַמָּה וְאַמָּה אֵינוֹ מְהַלֵּךְ בָּהּ אֶלָּא אֶלֶף אַמָּה בִּלְבַד שֶׁהוּא תַּשְׁלוּם אַלְפַּיִם אַמָּה שֶׁיֵּשׁ לוֹ:","מִי שֶׁכָּלְתָה מִדָּתוֹ בַּחֲצִי הָעִיר אַף עַל פִּי שֶׁאֵינוֹ מְהַלֵּךְ אֶלָּא עַד סוֹף מִדָּתוֹ מֻתָּר לְטַלְטֵל בְּכָל הָעִיר עַל יְדֵי זְרִיקָה. וְכֵן מִי שֶׁשָּׁבַת בְּבִקְעָה וְהִקִּיפוּהוּ נָכְרִים מְחִצָּה בְּשַׁבָּת אֵינוֹ מְהַלֵּךְ בָּהּ אֶלָּא אַלְפַּיִם אַמָּה לְכָל רוּחַ אַף עַל פִּי שֶׁהוּא בְּתוֹךְ הַמְּחִצָּה. וּמֻתָּר לוֹ לְטַלְטֵל בְּכָל הַמְּחִצָּה עַל יְדֵי זְרִיקָה אִם הִקִּיפוּהָ לְשֵׁם דִּירָה:","מִי שֶׁהָיָה בָּא בַּדֶּרֶךְ לִכָּנֵס לִמְדִינָה בֵּין שֶׁהָיָה בָּא בַּיָּם בֵּין שֶׁהָיָה בָּא בֶּחָרָבָה. אִם נִכְנַס בְּתוֹךְ אַלְפַּיִם אַמָּה קָרוֹב לָעִיר קֹדֶם שֶׁיִּכָּנֵס הַשַּׁבָּת אַף עַל פִּי שֶׁלֹּא הִגִּיעַ לַמְּדִינָה אֶלָּא בְּשַׁבָּת הֲרֵי זֶה יִכָּנֵס וִיהַלֵּךְ אֶת כֻּלָּהּ וְחוּצָה לָהּ אַלְפַּיִם אַמָּה לְכָל רוּחַ:","הָיָה בָּא לִמְדִינָה וְיָשֵׁן בַּדֶּרֶךְ וְלֹא נֵעוֹר אֶלָּא בְּשַׁבָּת וּכְשֶׁנֵּעוֹר מָצָא עַצְמוֹ בְּתוֹךְ הַתְּחוּם הֲרֵי זֶה יִכָּנֵס לָהּ וִיהַלֵּךְ אֶת כֻּלָּהּ וְחוּצָה לָהּ אַלְפַּיִם אַמָּה לְכָל רוּחַ. מִפְּנֵי שֶׁדַּעְתּוֹ הָיְתָה לְהַלֵּךְ לִמְדִינָה זוֹ וּלְפִיכָךְ קָנָה שְׁבִיתָה עִם בְּנֵי הַמְּדִינָה כְּמוֹתָן שֶׁהֲרֵי נִכְנַס עִמָּהֶן בַּתְּחוּם:","מִי שֶׁיָּצָא חוּץ לַתְּחוּם אֲפִלּוּ אַמָּה אַחַת לֹא יִכָּנֵס שֶׁהָאַרְבַּע אַמּוֹת שֶׁיֵּשׁ לוֹ לָאָדָם תְּחִלָּתָן מִמָּקוֹם שֶׁהוּא עוֹמֵד בּוֹ. לְפִיכָךְ כֵּיוָן שֶׁיָּצָא חוּץ מִתְּחוּמוֹ אַמָּה אוֹ יֶתֶר יֵשֵׁב בִּמְקוֹמוֹ וְאֵין לוֹ לְהַלֵּךְ אֶלָּא בְּתוֹךְ אַרְבַּע אַמּוֹת מֵעֲמִידַת רַגְלָיו וְלַחוּץ. וְכֵן מִי שֶׁהֶחְשִׁיךְ חוּץ לִתְחוּם הַמְּדִינָה אֲפִלּוּ אַמָּה אַחַת הֲרֵי זֶה לֹא יִכָּנֵס לָהּ אֶלָּא מְהַלֵּךְ מִמָּקוֹם שֶׁנִּכְנַס עָלָיו הַשַּׁבָּת וְהוּא עוֹמֵד בּוֹ אַלְפַּיִם אַמָּה בִּלְבַד. וְאִם כָּלְתָה מִדָּתוֹ בְּמִקְצָת הָעִיר מְהַלֵּךְ עַד סוֹף מִדָּתוֹ כְּמוֹ שֶׁאָמַרְנוּ. הָיְתָה רַגְלוֹ אַחַת בְּתוֹךְ הַתְּחוּם וְרַגְלוֹ אַחַת חוּץ לַתְּחוּם הֲרֵי זֶה יִכָּנֵס:","מִי שֶׁיָּצָא חוּץ לַתְּחוּם שֶׁלֹּא לְדַעְתּוֹ כְּגוֹן שֶׁהוֹצִיאוּהוּ נָכְרִים אוֹ רוּחַ רָעָה אוֹ שֶׁשָּׁגַג וְיָצָא אֵין לוֹ אֶלָּא אַרְבַּע אַמּוֹת. חָזַר לְדַעַת אֵין לוֹ אֶלָּא אַרְבַּע אַמּוֹת. הֶחְזִירוּהוּ כְּאִלּוּ לֹא יָצָא. וְאִם נְתָנוּהוּ בִּרְשׁוּת הַיָּחִיד כְּגוֹן שֶׁנְּתָנוּהוּ נָכְרִים בַּדִּיר וְסַהַר וּמְעָרָה אוֹ בְּעִיר אַחֶרֶת יֵשׁ לוֹ לְהַלֵּךְ אֶת כֻּלָּהּ. וְכֵן אִם יָצָא לְאֶחָד מֵאֵלּוּ בִּשְׁגָגָה וְנִזְכַּר וְהוּא בְּתוֹכָן מְהַלֵּךְ אֶת כֻּלָּהּ:","יָצָא חוּץ לַתְּחוּם לְדַעַת אַף עַל פִּי שֶׁחָזַר שֶׁלֹּא לְדַעַת כְּגוֹן שֶׁהֶחְזִירוּהוּ נָכְרִים אוֹ רוּחַ רָעָה אֵין לוֹ אֶלָּא אַרְבַּע אַמּוֹת. וְכֵן אִם יָצָא חוּץ לַתְּחוּם לְדַעַת אַף עַל פִּי שֶׁהוּא בְּתוֹךְ רְשׁוּת הַיָּחִיד כְּגוֹן דִּיר וְסַהַר אֵין לוֹ אֶלָּא אַרְבַּע אַמּוֹת. הַמְּפַרֵשׁ בַּיָּם הַגָּדוֹל אַף עַל פִּי שֶׁהוּא חוּץ לַתְּחוּם שֶׁשָּׁבַת בּוֹ מְהַלֵּךְ אֶת כָּל הַסְּפִינָה כֻּלָּהּ וּמְטַלְטֵל בְּכֻלָּהּ:","מִי שֶׁיָּצָא חוּץ לַתְּחוּם שֶׁלֹּא לְדַעַת וְהֻקַּף בִּמְחִצָּה בְּשַׁבָּת יֵשׁ לוֹ לְהַלֵּךְ כָּל אוֹתָהּ הַמְּחִצָּה וְהוּא שֶׁלֹּא תִּהְיֶה יֶתֶר עַל אַלְפַּיִם אַמָּה. וְאִם הָיָה תְּחוּם שֶׁיָּצָא מִמֶּנּוּ מֻבְלָע מִקְצָתוֹ בְּתוֹךְ הַמְּחִצָּה שֶׁנַּעֲשֵׂית שֶׁלֹּא לְדַעְתּוֹ הוֹאִיל וְיֵשׁ לוֹ לְהַלֵּךְ אֶת כָּל הַמְּחִצָּה הֲרֵי זֶה נִכְנָס לִתְחוּמוֹ וְכֵיוָן שֶׁיִּכָּנֵס הֲרֵי הוּא כְּאִלּוּ לֹא יָצָא:","כָּל מִי שֶׁאֵין לוֹ לָזוּז מִמְּקוֹמוֹ אֶלָּא בְּתוֹךְ אַרְבַּע אַמּוֹת אִם נִצְרָךְ לִנְקָבָיו הֲרֵי זֶה יוֹצֵא וּמַרְחִיק וְנִפְנֶה וְחוֹזֵר לִמְקוֹמוֹ. וְאִם נִכְנַס לְמִקְצָת תְּחוּם שֶׁיָּצָא מִמֶּנּוּ בְּעֵת שֶׁיִּתְרַחֵק לְהִפָּנוֹת הוֹאִיל וְנִכְנַס יִכָּנֵס וּכְאִלּוּ לֹא יָצָא. וְהוּא שֶׁלֹּא יָצָא בַּתְּחִלָּה לְדַעַת אֲבָל אִם יָצָא לְדַעַת אַף עַל פִּי שֶׁנִּכְנַס אֵין לוֹ אֶלָּא אַרְבַּע אַמּוֹת:","כָּל מִי שֶׁיָּצָא בִּרְשׁוּת בֵּית דִּין כְּגוֹן הָעֵדִים שֶׁבָּאוּ לְהָעִיד עַל רְאִיַּת הַלְּבָנָה וְכַיּוֹצֵא בָּהֶן מִמִּי שֶׁמֻּתָּר לוֹ לָצֵאת לִדְבַר מִצְוָה יֵשׁ לוֹ אַלְפַּיִם אַמָּה לְכָל רוּחַ בְּאוֹתוֹ מָקוֹם שֶׁהִגִּיעַ לוֹ. וְאִם הִגִּיעַ לִמְדִינָה הֲרֵי הוּא כְּאַנְשֵׁי הָעִיר וְיֵשׁ לוֹ אַלְפַּיִם אַמָּה לְכָל רוּחַ חוּץ לַמְּדִינָה:","הָיָה יוֹצֵא בִּרְשׁוּת וְאָמְרוּ לוֹ וְהוּא הוֹלֵךְ בַּדֶּרֶךְ כְּבָר נַעֲשֵׂית הַמִּצְוָה שֶׁיָּצָאתָ לַעֲשׂוֹת יֵשׁ לוֹ מִמְּקוֹמוֹ אַלְפַּיִם אַמָּה לְכָל רוּחַ. וְאִם הָיָה מִקְצָת תְּחוּם שֶׁיָּצָא מִמֶּנּוּ בִּרְשׁוּת מֻבְלָע בְּתוֹךְ אַלְפַּיִם אַמָּה שֶׁיֵּשׁ לוֹ מִמְּקוֹמוֹ הֲרֵי זֶה חוֹזֵר לִמְקוֹמוֹ וּכְאִלּוּ לֹא יָצָא. וכָּל הַיּוֹצְאִין לְהַצִּיל נַפְשׁוֹת יִשְׂרָאֵל מִיַּד עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת אוֹ מִן הַנָּהָר אוֹ מִן הַמַּפֹּלֶת יֵשׁ לָהֶם אַלְפַּיִם אַמָּה לְכָל רוּחַ מִמָּקוֹם שֶׁהִצִּילוּ בּוֹ. וְאִם הָיְתָה יַד הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת תַּקִּיפָה וְהָיוּ מְפַחֲדִים לִשְׁבֹּת בַּמָּקוֹם שֶׁהִצִּילוּ בּוֹ הֲרֵי אֵלּוּ חוֹזְרִין בְּשַׁבָּת לִמְקוֹמָן וּבִכְלֵי זֵינָן:"],"Mishneh Torah, Sabbatical Year and the Jubilee 10":["מִצְוַת עֲשֵׂה לִסְפֹּר שֶׁבַע שֶׁבַע שָׁנִים וּלְקַדֵּשׁ שְׁנַת הַחֲמִשִּׁים שֶׁנֶּאֱמַר (ויקרא כה ח) \"וְסָפַרְתָּ לְךָ שֶׁבַע שַׁבְּתֹת שָׁנִים\" וְגוֹ' (ויקרא כה י) \"וְקִדַּשְׁתֶּם אֵת שְׁנַת הַחֲמִשִּׁים\". וּשְׁתֵּי מִצְוֹת אֵלּוּ מְסוּרִין לְבֵית דִּין הַגָּדוֹל בִּלְבַד:","ומֵאֵימָתַי הִתְחִילוּ לִמְנוֹת. מֵאַחַר אַרְבַּע עֶשְׂרֵה שָׁנָה מִשֶּׁנִּכְנְסוּ לָאָרֶץ שֶׁנֶּאֱמַר (ויקרא כה ג) \"שֵׁשׁ שָׁנִים תִּזְרַע שָׂדֶךָ וְשֵׁשׁ שָׁנִים תִּזְמֹר כַּרְמֶךָ\" [עַד שֶׁיִּהְיֶה כָּל אֶחָד מַכִּיר אֶת אַרְצוֹ. וְשֶׁבַע שָׁנִים עָשׂוּ] בְּכִבּוּשׁ הָאָרֶץ וְשֶׁבַע שָׁנִים בְּחִלּוּק. נִמְצֵאתָ אוֹמֵר בִּשְׁנַת שָׁלֹשׁ וַחֲמֵשׁ מֵאוֹת וְאַלְפַּיִם לַיְצִירָה מֵרֹאשׁ הַשָּׁנָה מֵאַחַר מוֹלַד אָדָם הָרִאשׁוֹן שֶׁהִיא שָׁנָה שְׁנִיָּה לַיְצִירָה הִתְחִילוּ לִמְנוֹת. וְעָשׂוּ שְׁנַת עֶשֶׂר וַחֲמֵשׁ מֵאוֹת לַיְצִירָה שֶׁהִיא שְׁנַת אַחַת וְעֶשְׂרִים מִשֶּׁנִּכְנְסוּ לָאָרֶץ שְׁמִטָּה. וּמָנוּ שֶׁבַע שְׁמִטּוֹת וְקִדְּשׁוּ שְׁנַת הַחֲמִשִּׁים שֶׁהִיא שְׁנַת אַרְבַּע וְשִׁשִּׁים מִשֶּׁנִּכְנְסוּ לָאָרֶץ:","שִׁבְעָה עָשָׂר יוֹבְלִים מָנוּ יִשְׂרָאֵל מִשֶּׁנִּכְנְסוּ לָאָרֶץ וְעַד שֶׁיָּצְאוּ. וְשָׁנָה שֶׁיָּצְאוּ בָּהּ שֶׁחָרַב הַבַּיִת בָּרִאשׁוֹנָה מוֹצָאֵי שְׁבִיעִית הָיְתָה וּשְׁנַת שֵׁשׁ וּשְׁלֹשִׁים בַּיּוֹבֵל הָיְתָה. שֶׁאַרְבַּע מֵאוֹת שָׁנָה וְעֶשֶׂר שָׁנִים עָמַד בַּיִת רִאשׁוֹן. כֵּיוָן שֶׁחָרַב הַבַּיִת בָּטַל מִנְיָן זֶה. מִשֶּׁבָּטְלָה נִשְׁאֲרָה הָאָרֶץ חֲרֵבָה שִׁבְעִים שָׁנָה וְנִבְנָה בַּיִת שֵׁנִי. וְאַרְבַּע מֵאוֹת וְעֶשְׂרִים שָׁנָה עָמַד. וּבַשָּׁנָה הַשְּׁבִיעִית מִבִּנְיָנוֹ עָלָה עֶזְרָא וְהִיא הַבִּיאָה הַשְּׁנִיָּה. וּמִשָּׁנָה זוֹ הִתְחִילוּ לִמְנוֹת מִנְיָן אַחֵר. וְעָשׂוּ שְׁנַת י\"ג לְבִנְיַן בַּיִת שֵׁנִי שְׁמִטָּה. וּמָנוּ שֶׁבַע שְׁמִטּוֹת וְקִדְּשׁוּ שְׁנַת הַחֲמִשִּׁים. אַף עַל פִּי שֶׁלֹּא הָיְתָה שָׁם יוֹבֵל בְּבַיִת שֵׁנִי מוֹנִין הָיוּ אוֹתוֹ כְּדֵי לְקַדֵּשׁ שְׁמִטּוֹת:","נִמְצֵאתָ לָמֵד שֶׁהַשָּׁנָה שֶׁחָרַב בָּהּ הַבַּיִת בָּאַחֲרוֹנָה שֶׁתְּחִלָּתָהּ מִתִּשְׁרֵי שֶׁאַחַר הַחֻרְבָּן כִּשְׁנֵי חֳדָשִׁים שֶׁהֲרֵי מִתִּשְׁרֵי הוּא הַמִּנְיָן לִשְׁמִטִּים וּלְיוֹבְלוֹת אוֹתָהּ הַשָּׁנָה מוֹצָאֵי שְׁבִיעִית הָיְתָה. וּשְׁנַת ט\"ו מִן הַיּוֹבֵל הַתְּשִׁיעִי הָיְתָה. וּלְפִי חֶשְׁבּוֹן זֶה שָׁנָה זוֹ שֶׁהִיא שְׁנַת אֶלֶף וּמֵאָה וְשֶׁבַע לַחֻרְבָּן שֶׁהִיא שְׁנַת שְׁמוֹנִים וְשִׁבְעָה וְאֶלֶף וְאַרְבַּע מֵאוֹת לְמִנְיַן שְׁטָרוֹת שֶׁהִיא שְׁנַת שֵׁשׁ וּשְׁלֹשִׁים וּתְשַׁע מֵאוֹת וְאַרְבַּעַת אֲלָפִים לַיְצִירָה הִיא שְׁנַת שְׁמִטָּה וְהִיא שְׁנַת אַחַת וְעֶשְׂרִים מִן הַיּוֹבֵל:","אֲבָל כָּל הַגְּאוֹנִים אָמְרוּ שֶׁמָּסֹרֶת הִיא בִּידֵיהֶם אִישׁ מִפִּי אִישׁ שֶׁלֹּא מָנוּ בְּאוֹתָן הַשִּׁבְעִים שָׁנָה שֶׁבֵּין חֻרְבַּן בַּיִת רִאשׁוֹן וּבִנְיַן בַּיִת שֵׁנִי אֶלָּא שְׁמִטּוֹת בִּלְבַד בְּלֹא יוֹבֵל. וְכֵן מִשֶּׁחָרַב בָּאַחֲרוֹנָה לֹא מָנוּ שְׁנַת הַחֲמִשִּׁים אֶלָּא שֶׁבַע שֶׁבַע בִּלְבַד מִתְּחִלַּת שְׁנַת הַחֻרְבָּן. וְכֵן עוֹלֶה בַּגְּמָרָא עֲבוֹדָה זָרָה חֶשְׁבּוֹן זֶה שֶׁהוּא קַבָּלָה:","וּשְׁנַת הַשְּׁמִטָּה יְדוּעָה הִיא וּמְפֻרְסֶמֶת אֵצֶל הַגְּאוֹנִים וְאַנְשֵׁי אֶרֶץ יִשְׂרָאֵל. וְכֻלָּן לֹא מָנוּ אֶלָּא לִשְׁנֵי חֻרְבָּן מַשְׁלִיכִין אוֹתָן שֶׁבַע שֶׁבַע. וּלְפִי חֶשְׁבּוֹן זֶה תְּהִי שָׁנָה זוֹ שֶׁהִיא שְׁנַת שֶׁבַע וּמֵאָה וְאֶלֶף לַחֻרְבָּן מוֹצָאֵי שְׁבִיעִית. וְעַל זֶה אָנוּ סוֹמְכִין. וּכְפִי הַחֶשְׁבּוֹן זֶה אָנוּ מוֹרִין לְעִנְיַן מַעַשְׂרוֹת וּשְׁבִיעִית וְהַשְׁמָטַת כְּסָפִים שֶׁהַקַּבָּלָה וְהַמַּעֲשֶׂה עַמּוּדִים גְּדוֹלִים בְּהוֹרָאָה וּבָהֶן רָאוּי לְהִתָּלוֹת:","שְׁנַת יוֹבֵל אֵינָהּ עוֹלָה מִמִּנְיַן שְׁנֵי הַשָּׁבוּעַ. אֶלָּא שְׁנַת תֵּשַׁע וְאַרְבָּעִים שְׁמִטָּה וּשְׁנַת חֲמִשִּׁים יוֹבֵל. וּשְׁנַת חֲמִשִּׁים וְאַחַת תְּחִלַּת שֵׁשׁ שָׁנִים שֶׁל שָׁבוּעַ וְכֵן בְּכָל יוֹבֵל וְיוֹבֵל:","מִשֶּׁגָּלָה שֵׁבֶט רְאוּבֵן וְשֵׁבֶט גָּד וַחֲצִי שֵׁבֶט מְנַשֶּׁה בָּטְלוּ הַיּוֹבְלוֹת שֶׁנֶּאֱמַר (ויקרא כה י) \"וּקְרָאתֶם דְּרוֹר בָּאָרֶץ לְכָל ישְׁבֶיהָ\" בִּזְמַן שֶׁכָּל יוֹשְׁבֶיהָ עָלֶיהָ. וְהוּא שֶׁלֹּא יִהְיוּ מְעֻרְבָּבִין שֵׁבֶט בְּשֵׁבֶט אֶלָּא כֻּלָּן יוֹשְׁבִין כְּתִקְנָן. בִּזְמַן שֶׁהַיּוֹבֵל [נוֹהֵג בָּאָרֶץ] נוֹהֵג בְּחוּצָה לָאָרֶץ שֶׁנֶּאֱמַר (ויקרא כה י יב) \"יוֹבֵל הִיא\" בְּכָל מָקוֹם בֵּין בִּפְנֵי הַבַּיִת בֵּין שֶׁלֹּא בִּפְנֵי הַבַּיִת:","וּבִזְמַן שֶׁהַיּוֹבֵל נוֹהֵג נוֹהֵג דִּין עֶבֶד עִבְרִי. וְדִין בָּתֵּי עָרֵי חוֹמָה. וְדִין שְׂדֵה חֲרָמִים וְדִין שְׂדֵה אֲחֻזָּה. וּמְקַבְּלִין גֵּר תּוֹשָׁב וְנוֹהֶגֶת שְׁבִיעִית בָּאָרֶץ וְהַשְׁמָטַת כְּסָפִים בְּכָל מָקוֹם מִן הַתּוֹרָה. וּבִזְמַן שֶׁאֵין הַיּוֹבֵל [נוֹהֵג] אֵינוֹ נוֹהֵג אֶחָד מִכָּל אֵלּוּ חוּץ מִשְּׁבִיעִית בָּאָרֶץ. וְהַשְׁמָטַת כְּסָפִים בְּכָל מָקוֹם מִדִּבְרֵיהֶם כְּמוֹ שֶׁבֵּאַרְנוּ:","מִצְוַת עֲשֵׂה לִתְקֹעַ בַּשּׁוֹפָר בָּעֲשִׂירִי לְתִשְׁרֵי בִּשְׁנַת הַיּוֹבֵל. וּמִצְוָה זוֹ מְסוּרָה לְבֵית דִּין תְּחִלָּה (שֶׁנֶּאֱמַר (ויקרא כה ט) \"וְהַעֲבַרְתָּ שׁוֹפַר תְּרוּעָה\") וְכָל יָחִיד וְיָחִיד חַיָּב לִתְקֹעַ שֶׁנֶּאֱמַר (ויקרא כה ט) \"תַּעֲבִירוּ שׁוֹפָר\". וְתוֹקְעִין בַּשּׁוֹפָר תֵּשַׁע כְּדֶרֶךְ שֶׁתּוֹקְעִין בְּרֹאשׁ הַשָּׁנָה. וּמַעֲבִירִין שׁוֹפָר בְּכָל גְּבוּל יִשְׂרָאֵל:","שׁוֹפָר שֶׁל יוֹבֵל וְשֶׁל רֹאשׁ הַשָּׁנָה אֶחָד הוּא לְכָל דָּבָר. וְאֶחָד רֹאשׁ הַשָּׁנָה וְאֶחָד הַיּוֹבֵל לַתְּקִיעוֹת. אֶלָּא שֶׁבַּיּוֹבֵל תּוֹקְעִין בֵּין בְּבֵית דִּין שֶׁקִּדְּשׁוּ בּוֹ אֶת הַחֹדֶשׁ בֵּין בְּבֵית דִּין שֶׁלֹּא קִדְּשׁוּ בּוֹ אֶת הַחֹדֶשׁ. וְכָל יָחִיד וְיָחִיד חַיָּב לִתְקֹעַ כָּל זְמַן שֶׁבֵּית דִּין יוֹשְׁבִין וְשֶׁלֹּא בִּפְנֵי בֵּית דִּין:","וּבְרֹאשׁ הַשָּׁנָה שֶׁחָל לִהְיוֹת בְּשַׁבָּת לֹא הָיוּ תּוֹקְעִין אֶלָּא בְּבֵית דִּין שֶׁקִּדְּשׁוּ בּוֹ אֶת הַחֹדֶשׁ. וְאֵין כָּל יָחִיד וְיָחִיד תּוֹקֵעַ אֶלָּא בִּפְנֵי בֵּית דִּין:","שְׁלֹשָׁה דְּבָרִים מְעַכְּבִין בַּיּוֹבֵל. תְּקִיעָה וְשִׁלּוּחַ עֲבָדִים וְהַחְזָרַת שָׂדוֹת לְבַעֲלֵיהֶן. וְזוֹ הִיא שְׁמִטַּת קַרְקַע:","מֵרֹאשׁ הַשָּׁנָה עַד יוֹם הַכִּפּוּרִים לֹא הָיוּ עֲבָדִים נִפְטָרִים לְבָתֵּיהֶן וְלֹא מִשְׁתַּעְבְּדִין לַאֲדוֹנֵיהֶן. וְלֹא הַשָּׂדוֹת חוֹזְרוֹת לְבַעֲלֵיהֶן. אֶלָּא עֲבָדִים אוֹכְלִין וְשׁוֹתִים וּשְׂמֵחִים וְעַטְרוֹתֵיהֶם בְּרָאשֵׁיהֶם. כֵּיוָן שֶׁהִגִּיעַ יוֹם הַכִּפּוּרִים תָּקְעוּ בֵּית דִּין בַּשּׁוֹפָר נִפְטְרוּ עֲבָדִים לְבָתֵּיהֶן וְחָזְרוּ שָׂדוֹת לְבַעֲלֵיהֶן:","דִּין הַיּוֹבֵל בִּשְׁבִיתַת הָאָרֶץ וְדִין הַשְּׁמִטָּה אֶחָד הוּא לְכָל דָּבָר. כָּל שֶׁאָסוּר בַּשְּׁבִיעִית מֵעֲבוֹדַת הָאָרֶץ אָסוּר בִּשְׁנַת יוֹבֵל. וְכָל שֶׁמֻּתָּר בַּשְּׁבִיעִית מֻתָּר בַּיּוֹבֵל. וּמְלָאכוֹת שֶׁלּוֹקִין עֲלֵיהֶן בַּשְּׁבִיעִית לוֹקִין עֲלֵיהֶן בַּיּוֹבֵל. וְדִין פֵּרוֹת שְׁנַת יוֹבֵל בַּאֲכִילָה וּבַמְּכִירָה וּבַבִּעוּר כְּדִין פֵּרוֹת שְׁבִיעִית לְכָל דָּבָר:","יְתֵרָה שְׁבִיעִית עַל הַיּוֹבֵל שֶׁהַשְּׁבִיעִית מְשַׁמֶּטֶת כְּסָפִים וְלֹא יוֹבֵל. וְיוֹתֵר יוֹבֵל עַל הַשְּׁבִיעִית שֶׁהַיּוֹבֵל מוֹצִיא עֲבָדִים וּמַשְׁמִיט קַרְקַע. וְזֶהוּ דִּין מְכִירַת שָׂדוֹת הָאֲמוּרוֹת בַּתּוֹרָה וְהִיא מִצְוַת עֲשֵׂה שֶׁנֶּאֱמַר (ויקרא כה כד) \"גְּאֻלָּה תִּתְּנוּ לָאָרֶץ\". יוֹבֵל מְשַׁמֵּט קַרְקַע בִּתְחִלָּתוֹ וּשְׁבִיעִית אֵינָהּ מְשַׁמֶּטֶת כְּסָפִים אֶלָּא בְּסוֹפָהּ כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Sacrifices Rendered Unfit 1":["כָּל הַפְּסוּלִין לַעֲבוֹדָה מֻתָּרִין לִשְׁחֹט קָדָשִׁים לְכַתְּחִלָּה וַאֲפִלּוּ קָדְשֵׁי קָדָשִׁים. חוּץ מִן הַטָּמֵא שֶׁאֵינוֹ שׁוֹחֵט לְכַתְּחִלָּה. וְאַף עַל פִּי שֶׁהוּא חוּץ לָעֲזָרָה וּפָשַׁט יָדָיו וְשָׁחַט בָּעֲזָרָה גְּזֵרָה שֶׁמָּא יִגַּע בַּבָּשָׂר:","וְאִם עָבַר וְשָׁחַט הַזֶּבַח כָּשֵׁר. וְכֵן פַּר כֹּהֵן גָּדוֹל שֶׁל יוֹם הַכִּפּוּרִים אַף עַל פִּי שֶׁנֶּאֱמַר בּוֹ (ויקרא טז יא) \"וְשָׁחַט אַהֲרֹן\" אִם שְׁחָטוֹ זָר כָּשֵׁר. אַף פָּרָה אֲדֻמָּה שֶׁשָּׁחַט הַזָּר כְּשֵׁרָה שֶׁאֵין לְךָ שְׁחִיטָה פְּסוּלָה בְּזָר:","הַשּׁוֹחֵט אֶת הַקָּדָשִׁים וְלֹא נִתְכַּוֵּן לִשְׁחִיטָה אֶלָּא כְּמִתְעַסֵּק. הֲרֵי אֵלּוּ פְּסוּלִין עַד שֶׁיִּתְכַּוֵּן לִשְׁחִיטָה:","וְלֹא יִשְׁחֹט שְׁנֵי רָאשִׁים כְּאֶחָד בְּקָדָשִׁים וְאִם שָׁחַט הֲרֵי אֵלּוּ כְּשֵׁרִים:","אֲבָל שְׁנַיִם שׁוֹחֲטִין בְּהֵמָה אַחַת בְּקָדָשִׁים כְּחֻלִּין:","הַקָּטָן אֵינוֹ שׁוֹחֵט קָדָשִׁים אַף עַל פִּי שֶׁהַגָּדוֹל עוֹמֵד עַל גַּבָּיו. שֶׁהַקָּדָשִׁים צְרִיכִין מַחֲשָׁבָה וְקָטָן אֵין לוֹ מַחֲשָׁבָה. אֲפִלּוּ הָיְתָה מַחְשַׁבְתּוֹ נִכֶּרֶת מִתּוֹךְ מַעֲשָׂיו אֵינָהּ מַחֲשָׁבָה לְהָקֵל אֶלָּא לְהַחְמִיר. כֵּיצַד. הָיְתָה עוֹלָה עוֹמֶדֶת בַּדָּרוֹם וּמְשָׁכָהּ הַקָּטָן וֶהֱבִיאָהּ לַצָּפוֹן וּשְׁחָטָהּ שֶׁהֲרֵי מִמַּעֲשָׂיו נִכָּר שֶׁמַּחְשַׁבְתּוֹ לִשְׁחִיטַת קָדָשִׁים הֲרֵי זוֹ פְּסוּלָה:","קָדְשֵׁי קָדָשִׁים שֶׁנִּשְׁחֲטוּ בַּדָּרוֹם אוֹ שֶׁנִּתְקַבֵּל דָּמָם בַּדָּרוֹם פְּסוּלִין:","הָיָה עוֹמֵד בַּדָּרוֹם וְהוֹשִׁיט יָדוֹ לַצָּפוֹן וְשָׁחַט שְׁחִיטָתוֹ כְּשֵׁרָה:","הָיָה עוֹמֵד בַּדָּרוֹם וְהוֹשִׁיט יָדוֹ וְקִבֵּל הַדָּם בַּצָּפוֹן. קַבָּלָתוֹ פְּסוּלָה:","הִכְנִיס רֹאשׁוֹ וְרֻבּוֹ לַצָּפוֹן הֲרֵי הוּא כְּעוֹמֵד בַּצָּפוֹן:","שְׁחָטָהּ בַּצָּפוֹן וּפִרְכְּסָה וְיָצָאת לַדָּרוֹם. אֲפִלּוּ הוֹצִיאָהּ לַדָּרוֹם כְּשֵׁרָה. פִּרְכְּסָה וְיָצָאת לַדָּרוֹם וְחָזְרָה לַצָּפוֹן וְאַחַר כָּךְ קִבֵּל דָּמָהּ בַּצָּפוֹן כְּשֵׁרָה. וְכֵן קָדָשִׁים קַלִּים שֶׁהָיוּ בִּפְנִים וְעָמַד חוּץ לָעֲזָרָה וְהִכְנִיס יָדוֹ לְפָנִים וְשָׁחַט שְׁחִיטָתוֹ כְּשֵׁרָה:","הִכְנִיס יָדוֹ וְקִבֵּל קַבָּלָתוֹ פְּסוּלָה אֲפִלּוּ הִכְנִיס רֹאשׁוֹ וְרֻבּוֹ. אֲפִלּוּ הָיָה הָעוֹבֵד כֻּלּוֹ בִּפְנִים וְצִיצָתוֹ בַּחוּץ עֲבוֹדָתוֹ פְּסוּלָה. שֶׁנֶּאֱמַר (ויקרא י ט) \"בְּבֹאֲכֶם אֶל אֹהֶל מוֹעֵד\" עַד שֶׁיָּבוֹאוּ כֻּלָּן:","פִּרְכְּסָה הַבְּהֵמָה וְיָצָאת לַחוּץ אַחַר קַבָּלַת דָּמָהּ כְּשֵׁרָה. שֶׁאֲפִלּוּ יָצְאוּ הָאֵימוּרִין וְהַבָּשָׂר קֹדֶם זְרִיקָה בְּקָדָשִׁים קַלִּים הַזֶּבַח כָּשֵׁר כְּמוֹ שֶׁיִּתְבָּאֵר:","הָיְתָה הַבְּהֵמָה כֻּלָּהּ בִּפְנִים וְרַגְלֶיהָ בַּחוּץ וּשְׁחָטָהּ הַזֶּבַח פָּסוּל. שֶׁנֶּאֱמַר (ויקרא יז ה) \"וֶהֱבִיאֻם לַה'\" עַד שֶׁתִּהְיֶה כֻּלָּהּ בִּפְנִים:","שְׁחָטָהּ וְהִיא כֻּלָּהּ בִּפְנִים. וְאַחַר כָּךְ הוֹצִיאָה רַגְלָהּ לַחוּץ. חוֹתֵךְ הַבָּשָׂר עַד שֶׁהוּא מַגִּיעַ לָעֶצֶם וְאַחַר כָּךְ מְקַבֵּל הַדָּם. וְאִם קִבֵּל וְאַחַר כָּךְ חָתַךְ פָּסוּל מִפְּנֵי שַׁמְנוּנִית הַבָּשָׂר שֶׁבַּחוּץ. וּבְקָדָשִׁים קַלִּים אֵין צָרִיךְ לַחְתֹּךְ אֶלָּא מַחְזִיר רַגְלָהּ לְפָנִים וּמְקַבֵּל. שֶׁבְּשַׂר קָדָשִׁים [קַלִּים] שֶׁיָּצָא קֹדֶם זְרִיקָה כָּשֵׁר:","תָּלָה הַבְּהֵמָה וּשְׁחָטָהּ בַּאֲוִיר הָעֲזָרָה פְּסוּלָה. שֶׁנֶּאֱמַר (ויקרא א יא) \"עַל יֶרֶךְ הַמִּזְבֵּחַ\" עַד שֶׁיִּשְׁחֹט בָּאָרֶץ:","הָיְתָה הַבְּהֵמָה בָּאָרֶץ וְנִתְלָה וְשָׁחַט וְהוּא תָּלוּי בָּאֲוִיר. בְּקָדְשֵׁי קָדָשִׁים פָּסוּל. בְּקָדָשִׁים קַלִּים כָּשֵׁר:","שָׁחַט מִעוּט סִימָנִים בַּחוּץ וּגְמָרָן בִּפְנִים. אוֹ שֶׁשָּׁחַט מִעוּטָן בַּדָּרוֹם וּגְמָרָן בַּצָּפוֹן פְּסוּלִין. שֶׁיֶּשְׁנָה לַשְּׁחִיטָה מִתְּחִלָּתָהּ וְעַד סוֹף:","נִתְלָה וְקִבֵּל הַדָּם מִצַּוַּאר בְּהֵמָה הַמֻּנַּחַת בַּקַּרְקַע פָּסוּל. שֶׁאֵין דֶּרֶךְ שֵׁרוּת בְּכָךְ:","הָיָה עוֹמֵד בָּעֲזָרָה וְתָלָה הַמִּזְרָק בְּיָדוֹ וְקִבֵּל הַדָּם בָּאֲוִיר. אוֹ שֶׁהִגְבִּיהַּ הַבְּהֵמָה וְקִבֵּל הַדָּם בָּאֲוִיר כָּשֵׁר. שֶׁאֲוִיר הַמָּקוֹם כַּמָּקוֹם:","נָתַן מִזְרָק לְתוֹךְ מִזְרָק וְקִבֵּל כָּשֵׁר. מִין בְּמִינוֹ אֵינוֹ חוֹצֵץ. הִנִּיחַ סִיב בְּתוֹךְ הַמִּזְרָק וְקִבֵּל כָּשֵׁר. מִפְּנֵי שֶׁהַסִּיב חָלוּל וַהֲרֵי הַדָּם יוֹרֵד לְתוֹךְ הַמִּזְרָק וְאֵין כָּאן חֲצִיצָה. אֲבָל אִם עָשָׂה כֵּן בִּקְמִיצַת הַמִּנְחָה וְקָמַץ מִתּוֹךְ הַסִּיב פְּסוּלָה:","קַבָּלַת הַדָּם וְהוֹלָכָתוֹ לַמִּזְבֵּחַ וּזְרִיקָתוֹ וְכֵן הוֹלָכַת אֵיבָרִים לַכֶּבֶשׁ כָּל אַחַת מֵאֵלּוּ אֵינָהּ כְּשֵׁרָה אֶלָּא בְּכֹהֵן הַכָּשֵׁר לַעֲבוֹדָה כְּמוֹ שֶׁבֵּאַרְנוּ בִּקְמִיצַת הַמִּנְחָה וּבִמְלִיקַת הָעוֹף:","וְהוֹלָכָה שֶׁלֹּא בָּרֶגֶל אֵינָהּ הוֹלָכָה. לְפִיכָךְ כֹּהֵן גָּדוֹל שֶׁקִּבֵּל אֶת הַדָּם וְעָמַד בִּמְקוֹמוֹ וּזְרָקוֹ לַמִּזְבֵּחַ נִפְסַל הַזֶּבַח:","קִבֵּל בִּימִינוֹ וְנָתַן לִשְׂמֹאלוֹ יַחְזִיר לִימִינוֹ. קִבֵּל בִּכְלִי חֹל נִפְסַל הַזֶּבַח. קִבֵּל בִּכְלִי קֹדֶשׁ וְנָתַן לִכְלִי חֹל יַחְזִיר לִכְלִי קֹדֶשׁ:","נִשְׁפַּךְ מִן הַכְּלִי עַל הָרִצְפָּה וַאֲסָפוֹ כָּשֵׁר. אֲבָל אִם נִשְׁפַּךְ מִצַּוַּאר הַבְּהֵמָה עַל הָרִצְפָּה וַאֲסָפוֹ וּנְתָנוֹ לִכְלִי הַשָּׁרֵת נִפְסַל הַזֶּבַח:","נִשְׁפַּךְ מִקְצָת הַדָּם מִצַּוַּאר בְּהֵמָה עַל הָאָרֶץ וְלֹא אֲסָפוֹ וְקִבֵּל מִקְצָתוֹ מִצַּוַּאר בְּהֵמָה. הֲרֵי זֶה כָּשֵׁר וּבִלְבַד שֶׁיִּהְיֶה זֶה הַדָּם שֶׁנִּתְקַבֵּל דַּם הַנֶּפֶשׁ. לֹא דַּם הַתַּמְצִית וְלֹא דַּם הָעוֹר:","כָּל הַזְּבָחִים שֶׁקִּבֵּל דָּמָם אֶחָד מִן הַפְּסוּלִין לַעֲבוֹדָה. אוֹ שֶׁהוֹלִיךְ אֶת הַדָּם לַמִּזְבֵּחַ. אוֹ שֶׁזְּרָקוֹ לַמִּזְבֵּחַ כְּהִלְכָתוֹ. נִפְסַל הַזֶּבַח. קִבֵּל הַכָּשֵׁר וְנָתַן לְפָסוּל וְלֹא הִלֵּךְ בּוֹ הַפָּסוּל אֶלָּא עָמַד בִּמְקוֹמוֹ יַחְזִיר לַכָּשֵׁר. אֲבָל דָּם שֶׁהוֹלִיכוֹ הַפָּסוּל לַעֲבוֹדָה וְהֶחֱזִירוֹ לַכָּשֵׁר וְהוֹלִיכוֹ. אוֹ שֶׁהוֹלִיכוֹ הַכֹּהֵן תְּחִלָּה וְהֶחֱזִירוֹ וּנְתָנוֹ לַפָּסוּל וְהוֹלִיכוֹ. הוֹאִיל וְהוֹלִיכוֹ הַפָּסוּל בֵּין בַּתְּחִלָּה בֵּין בַּסּוֹף נִפְסַל הַזֶּבַח. שֶׁהֲרֵי אִי אֶפְשָׁר לְתַקֵּן דָּבָר זֶה:","קִבֵּל הַפָּסוּל. אִם נִשְׁאַר דַּם הַנֶּפֶשׁ חוֹזֵר הַכָּשֵׁר וּמְקַבֵּל וּמוֹלִיךְ וְזוֹרֵק. שֶׁאֵין הַפְּסוּלִין לַעֲבוֹדָה עוֹשִׂין הַדָּם הַנִּשְׁאָר שְׁיָרִים. חוּץ מִן הַטָּמֵא הוֹאִיל וְהוּא רָאוּי לַעֲבוֹדָה בְּקָרְבָּן הַבָּא בְּטֻמְאָה כְּמוֹ שֶׁבֵּאַרְנוּ. עוֹשֶׂה שְׁיָרִים כֵּיצַד. קִבֵּל הַטָּמֵא. אַף עַל פִּי שֶׁקִּבֵּל אַחֲרָיו הַכָּשֵׁר דַּם הַנֶּפֶשׁ וּזְרָקוֹ נִפְסַל הַזֶּבַח. שֶׁזֶּה שֶׁקִּבֵּל הַכָּשֵׁר בָּאַחֲרוֹנָה שְׁיָרִים הוּא וְאֵינוֹ כְּלוּם:","בְּהֵמָה שֶׁחָסַר מֵאֵיבָרֶיהָ כָּל שֶׁהוּא אַחַר שְׁחִיטָה קֹדֶם קַבָּלַת הַדָּם נִפְסְלָה. אֲפִלּוּ צָרַם בְּאָזְנָהּ קֹדֶם קַבָּלָה הֲרֵי זֶה לֹא יְקַבֵּל שֶׁנֶּאֱמַר (ויקרא טז יד) (ויקרא טז יח) \"וְלָקַח מִדַּם הַפָּר\" שֶׁיִּהְיֶה שָׁלֵם כֻּלּוֹ בִּשְׁעַת הַקַּבָּלָה. וְאִם קִבֵּל מִן הַחֲסֵרָה וְזָרַק הֲרֵי זֶה פָּסוּל:","אֲבָל אִם חָסְרָה אַחַר קַבָּלָה קֹדֶם זְרִיקָה. אֲפִלּוּ אָבַד הַבָּשָׂר קֹדֶם זְרִיקַת הַדָּם אוֹ נִשְׂרַף. אִם נִשְׁתַּיֵּר כְּזַיִת מִן הַבָּשָׂר אוֹ כְּזַיִת מִן הָאֵימוּרִין זוֹרֵק אֶת הַדָּם. וְאִם לָאו אֵינוֹ זוֹרֵק. וּבְעוֹלָה אֲפִלּוּ כַּחֲצִי זַיִת מִן הַבָּשָׂר וַחֲצִי זַיִת מִן הָאֵימוּרִין. מִפְּנֵי שֶׁכֻּלָּהּ לָאִשִּׁים:","נִשְׁאַר פָּחוֹת מִכְּזַיִת לֹא יִזְרֹק. וְאִם זָרַק לֹא הֻרְצָה. נִפְסַל הַבָּשָׂר קֹדֶם זְרִיקָה אוֹ שֶׁיָּצָא חוּץ לָעֲזָרָה לֹא יִזְרֹק הַדָּם. וְאִם זָרַק הֻרְצָה:","בְּשַׂר קָדָשִׁים קַלִּים שֶׁיָּצָא חוּץ לָעֲזָרָה קֹדֶם זְרִיקַת דָּמִים. אַף עַל פִּי שֶׁנִּזְרַק הַדָּם וְהַבָּשָׂר בַּחוּץ הַזֶּבַח כָּשֵׁר מִפְּנֵי שֶׁסּוֹף הַבָּשָׂר לָצֵאת. וְהַזְּרִיקָה מוֹעֶלֶת לַיּוֹצֵא לְשָׂרְפוֹ אֲבָל לֹא לְאָכְלוֹ:","וְכֵן אֵימוּרֵי קָדָשִׁים קַלִּים שֶׁיָּצְאוּ לִפְנֵי זְרִיקַת דָּמִים וְנִזְרַק הַדָּם וְהֵם בַּחוּץ לֹא נִפְסַל הַזֶּבַח. וְאִם הֶחְזִירָן מַקְטִירִין אוֹתָן. וְאַף עַל פִּי שֶׁלֹּא הֶחְזִירָן חַיָּבִין עֲלֵיהֶן מִשּׁוּם פִּגּוּל וְנוֹתָר וְטָמֵא:","כָּל הַזְּבָחִים שֶׁל יָחִיד. בֵּין שֶׁנִּטְמָא בָּשָׂר וְהַחֵלֶב קַיָּם בֵּין שֶׁנִּטְמָא חֵלֶב וְהַבָּשָׂר קַיָּם. זוֹרֵק אֶת הַדָּם. נִטְמְאוּ שְׁנֵיהֶן לֹא יִזְרֹק. וְאִם זָרַק הֻרְצָה. שֶׁהַצִּיץ מְרַצֶּה עַל הַטֻּמְאָה. וְכֵן אֵימוּרִין אוֹ אֵיבְרֵי עוֹלָה שֶׁנִּטְמְאוּ וְהִקְטִירָן הַצִּיץ מְרַצֶּה כְּמוֹ שֶׁבֵּאַרְנוּ. וְכָל קָרְבְּנוֹת הַצִּבּוּר שֶׁנִּטְמָא הַבָּשָׂר וְהַחֵלֶב כֻּלּוֹ הֲרֵי זֶה זוֹרֵק אֶת הַדָּם:","דַּם קָדָשִׁים שֶׁיָּצָא חוּץ לָעֲזָרָה נִפְסַל הַזֶּבַח. וְאַף עַל פִּי שֶׁחָזַר וְהִכְנִיסוֹ וּזְרָקוֹ עַל הַמִּזְבֵּחַ לֹא נִרְצָה:","וְכָל דַּם הַקָּדָשִׁים אֵינוֹ מְקַבֵּל טֻמְאָה כְּלָל שֶׁנֶּאֱמַר בַּדָּם (דברים יב טז) (דברים יב כד) \"עַל הָאָרֶץ תִּשְׁפְּכֶנּוּ כַּמָּיִם\". דָּם שֶׁנִּשְׁפַּךְ כְּמַיִם הוּא הַנֶּחְשָׁב כְּמַיִם וּמְקַבֵּל טֻמְאָה אֲבָל דַּם קָדָשִׁים שֶׁאֵינוֹ נִשְׁפַּךְ כְּמַיִם אֵינוֹ מְקַבֵּל טֻמְאָה:","וְדָם שֶׁשָּׁקְעָה עָלָיו חַמָּה וְלֹא נִזְרַק נִפְסַל הַזֶּבַח. וְאִם זְרָקוֹ לֹא הֻרְצָה:"],"Mishneh Torah, Sacrifices Rendered Unfit 3":["קָדְשֵׁי קָדָשִׁים שֶׁשְּׁחָטָן בְּרֹאשׁ הַמִּזְבֵּחַ כְּאִלּוּ שְׁחָטָן בַּצָּפוֹן שֶׁנֶּאֱמַר (שמות כ כא) \"וְזָבַחְתָּ עָלָיו אֶת עֹלֹתֶיךָ וְאֶת שְׁלָמֶיךָ\". מְלַמֵּד שֶׁכָּל הַמִּזְבֵּחַ רָאוּי לִשְׁחִיטַת הָעוֹלָה וּשְׁחִיטַת הַשְּׁלָמִים:","עוֹלָה שֶׁשְּׁחָטָהּ בְּרֹאשׁ הַמִּזְבֵּחַ. אוֹ שֶׁשְּׁחָטָהּ לְמַטָּה וְהֶעֱלָה אוֹתָהּ לְרֹאשׁ הַמִּזְבֵּחַ. יַפְשִׁיט אוֹתָהּ וִינַתְּחֶנָּה בִּמְקוֹמָהּ. וּמוֹרִיד הַקְּרָבַיִם וּמְדִיחָן לְמַטָּה. וְחוֹזֵר וּמַעֲלֶה אוֹתָן וּמוֹרִיד הָעוֹר וְנוֹתְנוֹ לַכֹּהֲנִים:","וְכֵן זְבָחִים שְׁחוּטִים שֶׁעָלוּ לְגַבֵּי הַמִּזְבֵּחַ. מַפְשִׁיטָן וּמְנַתְּחָן בִּמְקוֹמָן וּמוֹרִיד הַקְּרָבַיִם וּמְדִיחָן בְּמַיִם וְחוֹזֵר וּמַעֲלֶה אוֹתָן וּמוֹרִיד אֶת הָעוֹר וְאֶת הַבָּשָׂר וְנוֹתְנוֹ לַבְּעָלִים וְחוֹזֵר וּמַקְטִיר אֶת הַשְּׁאָר. וּמִפְּנֵי מָה לֹא יוֹרִיד הַכּל אֶלָּא יַפְשִׁיט וִינַתֵּחַ בְּרֹאשׁ הַמִּזְבֵּחַ. שֶׁכָּל הָרָאוּי לָאִשִּׁים אִם עָלָה לְרֹאשׁ הַמִּזְבֵּחַ לֹא יֵרֵד. שֶׁנֶּאֱמַר (שמות כט לז) \"כָּל הַנֹּגֵעַ בַּמִּזְבֵּחַ יִקְדָּשׁ\". יָכוֹל אַף עַל פִּי שֶׁאֵינוֹ רָאוּי. תַּלְמוּד לוֹמַר (ויקרא ו ב) \"הִיא הָעלָה עַל מוֹקְדָה\". מָה עוֹלָה שֶׁהִיא רְאוּיָה לָאִשִּׁים אִם עָלְתָה לֹא תֵּרֵד אַף כָּל הָרָאוּי לָאִשִּׁים אִם עָלָה לֹא יֵרֵד:","עוֹלָה שֶׁהֶעֱלָהּ חַיָּה לְרֹאשׁ הַמִּזְבֵּחַ תֵּרֵד שֶׁעֲדַיִן אֵינָהּ רְאוּיָה:","וְכֵן קֹמֶץ הַמִּנְחָה שֶׁלֹּא נִתְקַדֵּשׁ בִּכְלִי שָׁרֵת. וְכָל אִסּוּרֵי הַמִּזְבֵּחַ שֶׁעָלוּ יֵרְדוּ לְפִי שֶׁאֵינָן רְאוּיִין מִתְּחִלָּתָן:","וְכֵן בֶּהֱמַת קָדָשִׁים שֶׁנִּשְׁחֲטָה בַּלַּיְלָה אוֹ נִשְׁפַּךְ דָּמָהּ אוֹ שֶׁיָּצָאת חוּץ לָעֲזָרָה אִם עָלְתָה תֵּרֵד:","אֲבָל קָדָשִׁים שֶׁלָּנוּ אוֹ שֶׁלָּן הַדָּם אוֹ הַבָּשָׂר אוֹ הָאֵימוּרִים. וְזֶבַח שֶׁיָּצָא חוּץ לָעֲזָרָה. אוֹ שֶׁנִּטְמָא אוֹ נִפְסַל בְּמַחְשֶׁבֶת הַזְּמַן אוֹ בְּמַחְשֶׁבֶת מָקוֹם אוֹ בְּמַחְשֶׁבֶת שִׁנּוּי. אוֹ שֶׁקִּבְּלוּ הַטְּמֵאִים וְזָרְקוּ אֶת דָּמוֹ הוֹאִיל וּרְאוּיִין בַּעֲבוֹדַת קָרְבָּן הַבָּא בְּטֻמְאָה. וְשֶׁנָּתַן דָּמוֹ חוּץ לִמְקוֹמוֹ אוֹ קָדְשֵׁי קָדָשִׁים שֶׁנִּשְׁחֲטוּ בַּדָּרוֹם אוֹ שֶׁנִּתְקַבֵּל דָּמָם בַּדָּרוֹם. אַף עַל פִּי שֶׁכָּל אֵלּוּ פְּסוּלִים אִם עָלוּ לְרֹאשׁ הַמִּזְבֵּחַ לֹא יֵרְדוּ:","כָּל שֶׁפִּסּוּלוֹ בַּקֹּדֶשׁ הַקֹּדֶשׁ מְקַבְּלוֹ. וּכְשֵׁם שֶׁאִם עָלוּ לֹא יֵרְדוּ כָּךְ אִם יָרְדוּ לֹא יַעֲלוּ שְׁנִיָּה שֶׁהֲרֵי פְּסוּלִין הֵם:","וְאִם מָשְׁלָה בָּהֶם הָאוּר אַף עַל פִּי שֶׁיָּרְדוּ יַעֲלוּ שְׁנִיָּה וְיַשְׁלִים הַקְטָרָתָן:","קֹמֶץ שֶׁנִּתְפַּגֵּל וּמִקְצָתוֹ בָּאָרֶץ וּמִקְצָתוֹ מָשְׁלָה בּוֹ הָאוּר יַעֲלֶה כֻּלּוֹ:","אֵיבָרִים וַחֲלָבִים וּקְמָצִים שֶׁלָּנוּ בְּרֹאשׁוֹ שֶׁל מִזְבֵּחַ כְּאִלּוּ לָנוּ בָּעֲזָרָה וְאִם יָרְדוּ לֹא יַעֲלוּ. אֲבָל אִם לֹא יָרְדוּ מַקְטִירִין אוֹתָן לְעוֹלָם:","וַאֲוִיר מִזְבֵּחַ כְּמִזְבֵּחַ. וְאֵימוּרֵי קָדָשִׁים קַלִּים שֶׁהֶעֱלָן קֹדֶם זְרִיקַת דָּמִים לֹא יֵרְדוּ. שֶׁהֲרֵי נַעֲשָׂה לַחְמוֹ שֶׁל מִזְבֵּחַ:","הִפְרִישׁ שְׁנֵי אֲשָׁמוֹת לְאַחֲרָיוּת וְשָׁחַט אֶת שְׁנֵיהֶם וְקָדַם וְהֶעֱלָה אֵימוּרִים שֶׁל אֶחָד מֵהֶם קֹדֶם זְרִיקָה הֲרֵי אֵלּוּ יֵרְדוּ:","הַזֶּבַח הַפָּסוּל וְהַנְּסָכִים הַפְּסוּלִים שֶׁעָלוּ לַמִּזְבֵּחַ. הַזֶּבַח לֹא יֵרֵד כְּמוֹ שֶׁבֵּאַרְנוּ מִפְּנֵי שֶׁהוּא רָאוּי לָאִשִּׁים. וְהַנְּסָכִים יֵרְדוּ. וְכֵן נְסָכִים הַבָּאִים בִּפְנֵי עַצְמָן שֶׁנִּפְסְלוּ וְעָלוּ יֵרְדוּ:","עוֹף שֶׁמְּלָקוֹ זָר וְעָלָה לֹא יֵרֵד. וְקֹמֶץ הַמִּנְחָה שֶׁקְּמָצוֹ זָר וְעָלָה יֵרֵד. אַף עַל פִּי שֶׁזֶּה פָּסוּל וְזֶה פָּסוּל זֶה כְּאִלּוּ לֹא נִתְקַדֵּשׁ כְּלָל. וְאֶחָד הַזָּר וְאֶחָד שְׁאָר הַפְּסוּלִים:","וְאֵלּוּ אִם יַעֲלוּ יֵרְדוּ. כָּל שֶׁאֵינוֹ רָאוּי לָאִשִּׁים. בְּשַׂר קָדְשֵׁי קָדָשִׁים וּבְשַׂר קָדָשִׁים קַלִּים. מוֹתַר הָעֹמֶר וּשְׁיָרֵי מְנָחוֹת וּשְׁתֵּי הַלֶּחֶם וְלֶחֶם הַפָּנִים וְהַקְּטֹרֶת. וְצֶמֶר שֶׁבְּרָאשֵׁי כְּבָשִׂים וְשֵׂעָר שֶׁבִּזְקַן הַתְּיָשִׁים וְהָעֲצָמוֹת וְהַגִּידִים. וְהַקַּרְנַיִם וְהַטְּלָפַיִם בִּזְמַן שֶׁאֵינָן מְחֻבָּרִים אִם עָלוּ יֵרְדוּ:","קֹמֶץ שֶׁמִּצָּה שַׁמְנוֹ עַל הָעֶצֶם וְיָרַד הָעֶצֶם יַחֲזִירוֹ. שֶׁהַדָּבָר סָפֵק שֶׁמָּא חִבּוּרֵי עוֹלִין כְּעוֹלִין הֵם חֲשׁוּבִין:","מִזְבֵּחַ הַפְּנִימִי מְקַדֵּשׁ פְּסוּלִים בֵּין רְאוּיִין לוֹ בֵּין שֶׁאֵינָן רְאוּיִין לוֹ. אֲבָל מִזְבֵּחַ הַחִיצוֹן אֵינוֹ מְקַדֵּשׁ אֶלָּא פְּסוּלִין הָרְאוּיִין לוֹ כְּמוֹ שֶׁבֵּאַרְנוּ. כֵּיצַד. מִזְבֵּחַ הַחִיצוֹן שֶׁעָלוּ לוֹ זְבָחִים שֶׁנִּפְסְלוּ לֹא יֵרְדוּ. עָלְתָה לוֹ קְטֹרֶת זָרָה תֵּרֵד שֶׁאֵין הַקְּטֹרֶת זָרָה רְאוּיָה לַמִּזְבֵּחַ הַחִיצוֹן. אֲבָל מִזְבֵּחַ הַפְּנִימִי שֶׁעָלָה לוֹ קֹמֶץ מִנְחָה בֵּין כָּשֵׁר בֵּין פָּסוּל לֹא יֵרֵד. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. כְּשֵׁם שֶׁהַמִּזְבֵּחַ מְקַדֵּשׁ אֶת הָרָאוּי לוֹ כָּךְ הַכֶּבֶשׁ וּשְׁאָר כְּלֵי הַשָּׁרֵת מְקַדְּשִׁין אֶת הָרָאוּי לָהֶם שֶׁהֲרֵי נֶאֱמַר בַּכֵּלִים (שמות ל כט) \"כָּל הַנֹּגֵעַ בָּהֶם יִקְדָּשׁ\". מִשֶּׁיַּגִּיעַ לַכֶּבֶשׁ דָּבָר הָרָאוּי לוֹ לֹא יֵרֵד וְאַף עַל פִּי שֶׁנִּפְסַל. וְכֵן כְּשֶׁיַּגִּיעַ לִכְלִי שָׁרֵת כָּל דָּבָר הָרָאוּי לוֹ מִתְקַדֵּשׁ וְלֹא יִפָּדֶה לְעוֹלָם וְאַף עַל פִּי שֶׁנִּפְסַל כְּמוֹ שֶׁבֵּאַרְנוּ בְּאִסּוּרֵי הַמִּזְבֵּחַ:","אֵין כְּלֵי הַלַּח מְקַדְּשׁוֹת אֶת הַיָּבֵשׁ. וְלֹא כְּלֵי הַיָּבֵשׁ מְקַדְּשׁוֹת אֶת הַלַּח. בַּמֶּה דְּבָרִים אֲמוּרִים בְּמִדּוֹת הַלַּח וְהַיָּבֵשׁ שֶׁהָיוּ בַּמִּקְדָּשׁ כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת כְּלֵי הַמִּקְדָּשׁ. אֲבָל הַמִּזְרָקוֹת מְקַדְּשׁוֹת הַלַּח וְהַיָּבֵשׁ. וּכְלֵי שָׁרֵת מְקַדְּשִׁין דַּם הַפָּסוּל לִקָּרֵב:","כָּל כְּלֵי הַשָּׁרֵת אֵין מְקַדְּשִׁין אֶלָּא בַּמִּקְדָּשׁ וְאֵין מְקַדְּשִׁין אֶלָּא מִדַּעַת וְאֵין מְקַדְּשִׁין אֶלָּא מִתּוֹכָן וְאֵין מְקַדְּשִׁין אֶלָּא שְׁלֵמִים. נִקְּבוּ אִם עוֹשִׂין מֵעֵין מְלַאכְתָּן שֶׁהָיוּ עוֹשִׂין וְהֵם שְׁלֵמִים מְקַדְּשִׁין וְאִם לָאו אֵין מְקַדְּשִׁין. וְאֵין מְקַדְּשִׁין אֶלָּא מְלֵאִין. אֲבָל הַמִּדּוֹת אֵין מְקַדְּשׁוֹת חֲסֵרוֹת אֶלָּא אִם דַּעְתּוֹ לְמַלְּאוֹתָן. וְאִם אֵין דַּעְתּוֹ לְמַלְּאוֹתָן מְקַדְּשׁוֹת לְהִפָּסֵל אֲבָל לֹא לִקָּרֵב:","כְּלֵי שָׁרֵת מְקַדְּשִׁין שֶׁלֹּא בִּזְמַנָּן לְהִפָּסֵל אֲבָל לֹא לְהִקָּרֵב. כֵּיצַד. דָּבָר שֶׁמִּצְוָתוֹ בַּיּוֹם שֶׁנִּתְקַדֵּשׁ בִּכְלִי שָׁרֵת בַּלַּיְלָה נִפְסַל וְיִשָּׂרֵף. אֲבָל אֵינוֹ קָרֵב. כְּגוֹן שֶׁקָּמַץ מִנְחָה בַּלַּיְלָה וְנָתַן קֻמְצָהּ לִכְלִי שָׁרֵת הֲרֵי זוֹ נִשְׂרֶפֶת:","מִזְבֵּחַ שֶׁנִּפְגַּם נִפְסְלוּ כָּל הַקָּדָשִׁים שֶׁהָיוּ שָׁם שְׁחוּטִין בַּמִּקְדָּשׁ שֶׁעֲדַיִן לֹא נִזְרַק דָּמָם. שֶׁהֲרֵי אֵין שָׁם מִזְבֵּחַ לִזְרֹק עָלָיו וְנֶאֱמַר (שמות כ כא) \"וְזָבַחְתָּ עָלָיו אֶת עלֹתֶיךָ וְאֶת שְׁלָמֶיךָ\" כְּלוֹמַר תִּזְבַּח וְהוּא עוֹמֵד בְּתִקּוּנוֹ לֹא פָּגוּם:","אֲבָל קָדָשִׁים חַיִּים שֶׁהָיוּ שָׁם בָּעֲזָרָה כְּשֶׁנִּפְגַּם לֹא נִפְסְלוּ. אֶלָּא כְּשֶׁיִּבָּנֶה הַמִּזְבֵּחַ יִקָּרְבוּ שֶׁאֵין בַּעֲלֵי חַיִּים נִדְחִין:","הִקְדִּישׁ בְּהֵמוֹת עַד שֶׁלֹּא נִבְנָה הַמִּזְבֵּחַ. כְּשֶׁיִּבָּנֶה מַקְרִיבִין אוֹתָן שֶׁהַדָּחוּי מֵעִקָּרוֹ אֵינוֹ דָּחוּי:","וְכֵן אֵין אוֹכְלִין קָדָשִׁים וְהַמִּזְבֵּחַ פָּגוּם. שֶׁנֶּאֱמַר (ויקרא י יב) \"וְאִכְלוּהָ מַצּוֹת אֵצֶל הַמִּזְבֵּחַ\". וְהוּא הַדִּין לְקָדָשִׁים קַלִּים שֶׁאֵין אוֹכְלִין אוֹתָן בִּירוּשָׁלַיִם וְהַמִּזְבֵּחַ פָּגוּם עַד שֶׁיִּבָּנֶה:"],"Mishneh Torah, Sacrificial Procedure 14":["מִתְנַדֵּב אָדָם וְנוֹדֵר עוֹלָה וּשְׁלָמִים וְכָל מִין שֶׁיִּרְצֶה מֵחֲמִשָּׁה מִינֵי מְנָחוֹת הַבָּאִין בְּנֵדֶר וּנְדָבָה. וּמִתְנַדֵּב אוֹ נוֹדֵר מִנְחָה מִמִּנְחַת נְסָכִים לְבַדָּהּ מֵאֵי זֶה מִין מִשְּׁלֹשָׁה מִינֵי מְנָחוֹת נְסָכִים כְּמוֹ שֶׁבֵּאַרְנוּ. וּמִתְנַדֵּב אוֹ נוֹדֵר יַיִן בִּפְנֵי עַצְמוֹ אוֹ לְבוֹנָה בִּפְנֵי עַצְמָהּ אוֹ שֶׁמֶן בִּפְנֵי עַצְמוֹ אוֹ עֵצִים לַמַּעֲרָכָה מִפְּנֵי שֶׁהֵן כְּקָרְבָּן שֶׁנֶּאֱמַר (נחמיה יג לא) \"וּלְקֻרְבַּן הָעֵצִים\":","שְׁנַיִם מִתְנַדְּבִין אוֹ נוֹדְרִין קָרְבָּן אֶחָד עוֹלָה אוֹ שְׁלָמִים אֲפִלּוּ פְּרֵדָה אַחַת שֶׁל תּוֹרִים אוֹ בְּנֵי יוֹנָה מְבִיאִין אוֹתָהּ בְּשֻׁתָּפוּת. אֲבָל הַמִּנְחָה אֵינָהּ בָּאָה בְּשֻׁתָּפוּת. וּדְבָרִים אֵלּוּ הֵן דִּבְרֵי קַבָּלָה:","הֵנִיחַ מִנְחָה לִשְׁנֵי בָּנָיו וּמֵת הֲרֵי אֵלּוּ מְבִיאִין אוֹתָהּ:","אֵי זֶה הוּא נֵדֶר וְאֵי זוֹ הִיא נְדָבָה. הָאוֹמֵר הֲרֵי עָלַי עוֹלָה אוֹ הֲרֵי עָלַי שְׁלָמִים אוֹ הֲרֵי עָלַי מִנְחָה אוֹ הֲרֵי דְּמֵי בְּהֵמָה זוֹ עָלַי עוֹלָה אוֹ שְׁלָמִים זֶהוּ הַנֵּדֶר. אֲבָל הָאוֹמֵר הֲרֵי בְּהֵמָה זוֹ אוֹ דְּמֵי בְּהֵמָה זוֹ עוֹלָה אוֹ שְׁלָמִים אוֹ הֲרֵי הָעִשָּׂרוֹן הַזֶּה מִנְחָה הֲרֵי זוֹ נְדָבָה:","מַה בֵּין נְדָרִים לִנְדָבוֹת. שֶׁהַנּוֹדֵר אִם הִפְרִישׁ קָרְבָּנוֹ וְאָבַד אוֹ נִגְנַב חַיָּב בְּאַחֲרָיוּתוֹ עַד שֶׁיַּקְרִיב כְּמוֹ שֶׁנָּדַר. וְהַמִּתְנַדֵּב וְאוֹמֵר זוֹ אִם מֵת אוֹ נִגְנַב אֵינוֹ חַיָּב בְּאַחֲרָיוּתוֹ:","הָאוֹמֵר דְּמֵי שׁוֹר זֶה עָלַי עוֹלָה וּדְמֵי בַּיִת זֶה עָלַי קָרְבָּן וּמֵת הַשּׁוֹר וְנָפַל הַבַּיִת חַיָּב לְשַׁלֵּם. אָמַר הֲרֵי עָלַי עוֹלָה עַל מְנָת שֶׁלֹּא אֶתְחַיֵּב בְּאַחֲרָיוּתָהּ אֵינוֹ חַיָּב בְּאַחֲרָיוּתָהּ:","כְּבָר בֵּאַרְנוּ שֶׁהָעוֹשֶׂה בַּיִת חוּץ לַמִּקְדָּשׁ לְהַקְרִיב בּוֹ קָרְבָּנוֹת אֵינוֹ כְּבֵית עֲבוֹדָה זָרָה וְהָאוֹמֵר הֲרֵי עָלַי עוֹלָה שֶׁאַקְרִיבֶנָּה בַּמִּקְדָּשׁ וְהִקְרִיבָהּ בְּבַיִת זֶה לֹא יָצָא. שֶׁאַקְרִיבֶנָּה בְּבַיִת זֶה וְהִקְרִיבָהּ בַּמִּקְדָּשׁ יָצָא. וְאִם הִקְרִיבָהּ בְּאוֹתוֹ הַבַּיִת יָצָא. הֲרֵי הוּא כְּמִי שֶׁנָּדַר עוֹלָה עַל מְנָת שֶׁלֹּא יִתְחַיֵּב בְּאַחֲרָיוּתָהּ וְעָנוּשׁ כָּרֵת עַל הַעֲלָיָתָהּ בַּחוּץ. וְכֵן אִם אָמַר הֲרֵינִי נָזִיר עַל מְנָת שֶׁאֲגַלֵּחַ בְּבַיִת זֶה. אִם גִּלֵּחַ שָׁם יָצָא. הֲרֵי הוּא כְּמִי שֶׁנָּדַר לְצַעֵר עַצְמוֹ וַהֲרֵי צִעֵר עַצְמוֹ וְאֵינָהּ נְזִירוּת:","חַטָּאת וְאָשָׁם אֵינָן בָּאִין אֶלָּא עַל חֵטְא. וְאֵינָן בָּאִין בְּנֵדֶר וּנְדָבָה. הָאוֹמֵר הֲרֵי עָלַי חַטָּאת אוֹ אָשָׁם אוֹ שֶׁאָמַר הֲרֵי זוֹ חַטָּאת אוֹ אָשָׁם לֹא אָמַר כְּלוּם. הָיָה מְחֻיָּב חַטָּאת אוֹ אָשָׁם וְאָמַר הֲרֵי זוֹ לְחַטָּאתִי אוֹ לַאֲשָׁמִי אוֹ הֲרֵי הַמָּעוֹת הָאֵלּוּ לְחַטָּאתִי אוֹ לַאֲשָׁמִי דְּבָרָיו קַיָּמִים:","הָאוֹמֵר קָרְבַּן מְצֹרָע זֶה אוֹ יוֹלֶדֶת זוֹ עָלַי. אִם הָיָה אוֹתוֹ מְצֹרָע אוֹ הַיּוֹלֶדֶת עֲנִיִּים מֵבִיא הַנּוֹדֵר קָרְבַּן עָנִי. וְאִם הָיוּ עֲשִׁירִים מֵבִיא הַנּוֹדֵר קָרְבַּן עָשִׁיר אַף עַל פִּי שֶׁהַנּוֹדֵר עָנִי:","הָאוֹמֵר חַטָּאתוֹ וְעוֹלָתוֹ וַאֲשָׁמוֹ וּשְׁלָמָיו שֶׁל פְּלוֹנִי עָלַי. אִם רָצָה אוֹתוֹ פְּלוֹנִי הֲרֵי זֶה מְנִיחוֹ לְהַקְרִיבָן עַל יָדוֹ וּמִתְכַּפֵּר לוֹ. רָצָה בִּשְׁעַת הַפְרָשָׁה וְלֹא רָצָה בִּשְׁעַת הַקְרָבָה אֶלָּא חָזַר בּוֹ. בְּעוֹלָה וּבִשְׁלָמִים מַקְרִיבִין וּמִתְכַּפֵּר לוֹ בָּהֶן אַף עַל פִּי שֶׁאֵינוֹ רוֹצֶה עַתָּה שֶׁהֲרֵי רָצָה בִּשְׁעַת הַפְרָשָׁה. אֲבָל בְּחַטָּאת וּבְאָשָׁם לֹא נִתְכַּפֵּר לוֹ עַד שֶׁיִּרְצֶה מִתְּחִלָּה וְעַד סוֹף:","הָאוֹמֵר הֲרֵי עָלַי כְּנִדְרֵי רְשָׁעִים שֶׁמִּנִּדְרֵיהֶן נָזִיר וְקָרְבָּן וּשְׁבוּעָה חַיָּב בְּכֻלָּן. כְּנִדְרֵי כְּשֵׁרִין לֹא נִתְחַיֵּב כְּלוּם. הֲרֵי עָלַי כִּנְדָבוֹת כְּשֵׁרִין הֲרֵי זֶה נָדַר בְּנָזִיר וּבְקָרְבָּן. וְכָל כִּנּוּיֵי קָרְבָּן כְּקָרְבָּן:","אֵין הַנּוֹדֵר וְלֹא הַמִּתְנַדֵּב חַיָּב עַד שֶׁיְּהֵא פִּיו וְלִבּוֹ שָׁוִין. כֵּיצַד. הַמִּתְכַּוֵּן לוֹמַר הֲרֵי עָלַי עוֹלָה וְאָמַר שְׁלָמִים. אוֹ שֶׁנִּתְכַּוֵּן לוֹמַר הֲרֵי זוֹ עוֹלָה וְאָמַר שְׁלָמִים לֹא אָמַר כְּלוּם. נִתְכַּוֵּן לִנְדֹּר בְּעוֹלָה וְאָמַר קָרְבָּן. לִנְדֹּר בְּחֵרֶם וְאָמַר הֶקְדֵּשׁ דְּבָרָיו קַיָּמִים. שֶׁהָעוֹלָה קָרְבָּן וְהַחֵרֶם הֶקְדֵּשׁ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. בִּנְדָרִים וּנְדָבוֹת אֵינוֹ צָרִיךְ לְהוֹצִיא בִּשְׂפָתָיו כְּלוּם אֶלָּא אִם גָּמַר בְּלִבּוֹ וְלֹא הוֹצִיא בִּשְׂפָתָיו כְּלוּם חַיָּב. כֵּיצַד. גָּמַר בְּלִבּוֹ שֶׁזּוֹ עוֹלָה אוֹ שֶׁיָּבִיא עוֹלָה הֲרֵי זֶה חַיָּב לְהָבִיא שֶׁנֶּאֱמַר (שמות לה ה) \"כּל נְדִיב לֵב יְבִיאָהּ\" בִּנְדִיבוּת לֵב יִתְחַיֵּב לְהָבִיא. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה מִנִּדְרֵי קָדָשִׁים וְנִדְבוּתָן:","אֶחָד נְדָרִים וּנְדָבוֹת עִם שְׁאָר הַדְּבָרִים שֶׁאָדָם חַיָּב בָּהֶן מֵעֲרָכִין וְדָמִים וּמַעַשְׂרוֹת וּמַתְּנוֹת עֲנִיִּים מִצְוַת עֲשֵׂה מִן הַתּוֹרָה שֶׁיָּבִיא הַכּל בָּרֶגֶל שֶׁפָּגַע בּוֹ תְּחִלָּה שֶׁנֶּאֱמַר (דברים יב ה) \"וּבָאתָ שָּׁמָּה\" (דברים יב ו) \"וַהֲבֵאתֶם שָׁמָּה\" וְגוֹ' כְּלוֹמַר בְּעֵת שֶׁתָּבוֹא לָחֹג תָּבִיא כָּל מַה שֶׁאַתָּה חַיָּב בּוֹ וְתִתֵּן כָּל חוֹב שֶׁעָלֶיךָ לַשֵּׁם. הִגִּיעַ הָרֶגֶל וְלֹא הֵבִיא הֲרֵי זֶה בִּטֵּל מִצְוַת עֲשֵׂה. עָבְרוּ עָלָיו שְׁלֹשָׁה רְגָלִים וְלֹא הֵבִיא קָרְבְּנוֹתָיו שֶׁנָּדַר אוֹ הִתְנַדֵּב אוֹ שֶׁלֹּא נָתַן הָעֲרָכִים וְהַחֲרָמִים וְהַדָּמִים הֲרֵי זֶה עָבַר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים כג כב) \"לֹא תְאַחֵר לְשַׁלְּמוֹ\" אֵינוֹ עוֹבֵר בְּלֹא תַּעֲשֶׂה עַד שֶׁיַּעַבְרוּ עָלָיו רַגְלֵי הַשָּׁנָה כֻּלָּהּ. וְאֵין לוֹקִין עַל לָאו זֶה לְפִי שֶׁאֵין בּוֹ מַעֲשֶׂה:","הִקְדִּישׁ בְּהֵמָה לַמִּזְבֵּחַ וְעָבְרוּ עָלָיו שְׁנֵי רְגָלִים וְנָפַל בָּהּ מוּם וּפְדָאָהּ עַל גַּב בְּהֵמָה אַחֶרֶת אֵינוֹ עוֹבֵר בְּלֹא תַּעֲשֶׂה עַד שֶׁיַּעַבְרוּ עַל הָאַחֶרֶת שְׁלֹשָׁה רְגָלִים. וְאֶחָד הָאִישׁ וְאֶחָד הָאִשָּׁה עוֹבֵר בְּבַל תְּאַחֵר. אֲבָל הַיּוֹרֵשׁ אֵינוֹ עוֹבֵר בְּבַל תְּאַחֵר:","כָּל הַקָּרְבָּנוֹת שֶׁעָבְרוּ עֲלֵיהֶן שְׁלֹשָׁה רְגָלִים לֹא נִפְסְלוּ. אֶלָּא מַקְרִיבָן וּכְשֵׁרִים. וּבְכָל יוֹם וְיוֹם אַחַר הַשְּׁלֹשָׁה רְגָלִים הוּא עוֹבֵר בְּלֹא תְּאַחֵר. וּבֵית דִּין מְצֻוִּין לְעַשּׂוֹתוֹ מִיָּד עַד שֶׁיַּקְרִיב קָרְבְּנוֹתָיו בָּרֶגֶל שֶׁפָּגַע בּוֹ תְּחִלָּה:","אַף עַל פִּי שֶׁנֶּאֱמַר (ויקרא א ג) \"לִרְצוֹנוֹ\" כּוֹפִין אוֹתוֹ עַד שֶׁיֹּאמַר רוֹצֶה אֲנִי. בֵּין שֶׁנָּדַר וְלֹא הִפְרִישׁ בֵּין שֶׁהִפְרִישׁ וְלֹא הִקְרִיב כּוֹפִין אוֹתוֹ עַד שֶׁיַּקְרִיב:","כָּל חַיָּבֵי עוֹלוֹת וּשְׁלָמִים מְמַשְׁכְּנִין אוֹתָם. אַף עַל פִּי שֶׁאֵין מִתְכַּפֵּר לוֹ עַד שֶׁיִּרְצֶה שֶׁנֶּאֱמַר (ויקרא א ג) \"לִרְצֹנוֹ\" כּוֹפִין אוֹתוֹ עַד שֶׁיֹּאמַר רוֹצֶה אֲנִי. אֲבָל חַיָּבֵי חַטָּאוֹת וַאֲשָׁמוֹת אֵין מְמַשְׁכְּנִין אוֹתָן הוֹאִיל וְהֵם מְעֻכְּבֵי כַּפָּרָה אֵין חוֹשְׁשִׁין לָהֶם שֶׁמָּא יִפְשְׁעוּ וְיַשְׁהוּ קָרְבְּנוֹתֵיהֶן. חוּץ מֵחַטַּאת נָזִיר הוֹאִיל וְאֵינָהּ מְעַכַּבְתּוֹ מִלִּשְׁתּוֹת יַיִן שֶׁמָּא יְאַחֵר אוֹתָהּ לְפִיכָךְ מְמַשְׁכְּנִין אוֹתוֹ עָלֶיהָ:"],"Mishneh Torah, Sacrificial Procedure 8":["חֹמֶר בְּחַטַּאת הַבְּהֵמָה מִשְּׁאָר קָדְשֵׁי קָדָשִׁים. שֶׁדַּם חַטַּאת הַבְּהֵמָה שֶׁנִּתַּז מִן הַכְּלִי שֶׁקִּבֵּל בּוֹ הַדָּם קֹדֶם הַזָּיָה עַל הַבֶּגֶד טָעוּן כִּבּוּס בְּמַיִם בָּעֲזָרָה שֶׁנֶּאֱמַר (ויקרא ו כ) \"וַאֲשֶׁר יִזֶּה מִדָּמָהּ עַל הַבֶּגֶד אֲשֶׁר יִזֶּה עָלֶיהָ תְּכַבֵּס בְּמָקוֹם קָדשׁ\":","אֶחָד הַבֶּגֶד וְאֶחָד הָעוֹר הָרַךְ וְאֶחָד הַשַּׂק טְעוּנִין כִּבּוּס. אֲבָל הָעוֹר הַקָּשֶׁה הֲרֵי הוּא כְּעֵץ וְגוֹרֵד הַדָּם מֵעָלָיו. וְאֶחָד דַּם חַטָּאת הַנֶּאֱכֶלֶת אוֹ דַּם חַטָּאת הַנִּשְׂרֶפֶת אֲבָל לֹא דַּם חַטַּאת הָעוֹף. שֶׁנֶּאֱמַר (ויקרא ו יח) \"תִּשָּׁחֵט הַחַטָּאת\" בְּנִשְׁחֶטֶת הַכָּתוּב מְדַבֵּר לֹא בְּנִמְלֶקֶת:","חַטָּאת שֶׁנִּפְסְלָה אֵין דָּמָהּ טָעוּן כִּבּוּס. בֵּין שֶׁהָיְתָה לָהּ שְׁעַת הַכּשֶׁר בֵּין שֶׁלֹּא הָיְתָה לָהּ שְׁעַת הַכּשֶׁר. אֵי זוֹ הִיא שֶׁהָיְתָה לָהּ שְׁעַת הַכּשֶׁר. שֶׁלָּנָה וְשֶׁנִּטְמֵאת וְשֶׁיָּצָאת חוּץ לָעֲזָרָה. וְאֵי זוֹ הִיא שֶׁלֹּא הָיְתָה לָהּ שְׁעַת הַכּשֶׁר. שֶׁנִּפְסְלָה בִּשְׁחִיטָה אוֹ בִּזְרִיקַת הַדָּם:","אֵין טָעוּן כִּבּוּס אֶלָּא מְקוֹם הַדָּם בִּלְבַד. וְהוּא שֶׁיִּהְיֶה עַל כְּלִי שֶׁרָאוּי לְקַבֵּל טֻמְאָה וְרָאוּי לְכִבּוּס. אֲבָל אִם נִתַּז עַל כְּלִי עֵץ אוֹ כְּלִי מַתֶּכֶת אֵינוֹ טָעוּן כִּבּוּס לְפִי שֶׁאֵינָן רְאוּיִין לְכִבּוּס אֶלָּא גּוֹרְדָן בִּלְבַד:","נִתַּז עַל עוֹר הַדָּג אֵינוֹ טָעוּן כִּבּוּס לְפִי שֶׁאֵינוֹ רָאוּי לְקַבֵּל טֻמְאָה. אֲבָל אִם נִתַּז עַל עוֹר בְּהֵמָה. עַד שֶׁלֹּא הֻפְשַׁט אֵינוֹ טָעוּן כִּבּוּס. אַחַר שֶׁהֻפְשַׁט טָעוּן כִּבּוּס. שֶׁאַף עַל פִּי שֶׁאֵינוֹ מְקַבֵּל טֻמְאָה עַתָּה הֲרֵי הוּא רָאוּי לְקַבֵּל טֻמְאָה לְאַחַר שֶׁיִּתְעַבֵּד:","נִתַּז מִן הַצַּוָּאר עַל הַבֶּגֶד אוֹ מֵעַל קֶרֶן הַמִּזְבֵּחַ אוֹ שֶׁנִּשְׁפָּךְ הַדָּם עַל הָרִצְפָּה וַאֲסָפוֹ וְנִתַּז מִמֶּנּוּ עַל הַבֶּגֶד אֵינוֹ טָעוּן כִּבּוּס שֶׁנֶּאֱמַר (ויקרא ו כ) \"וַאֲשֶׁר יִזֶּה מִדָּמָהּ\". לֹא אָמַרְתִּי אֶלָּא בְּדָם שֶׁנִּתְקַבֵּל בִּכְלִי שָׁרֵת וְרָאוּי לְהַזָּיָה וְיֵשׁ בּוֹ כְּדֵי הַזָּיָה:","נָתַן אַרְבַּע הַמַּתָּנוֹת וְאַחַר כָּךְ נִתַּז מִן הַכּוֹס עַל הַבֶּגֶד מִשְּׁיָרֵי הַדָּם אֵינוֹ טָעוּן כִּבּוּס. אַף עַל פִּי שֶׁעֲדַיִן לֹא זָרַק הַשְּׁיָרִים עַל הַיְסוֹד. וְכֵן בְּחַטָּאוֹת הַנִּשְׂרָפוֹת:","נִתַּז מֵאֶצְבָּעוֹ אַחַר שֶׁיָּצָאת הַזָּיָה מִיָּדוֹ אֵינוֹ טָעוּן כִּבּוּס שֶׁשְּׁיָרֵי הַדָּם שֶׁבָּאֶצְבַּע פְּסוּלִין לְהַזָּיָה:","נִתַּז מִן הַבֶּגֶד לְבֶגֶד שֵׁנִי אֵין הַבֶּגֶד הַשֵּׁנִי טָעוּן כִּבּוּס. נִתַּז עַל בֶּגֶד טָמֵא אֵינוֹ טָעוּן כִּבּוּס. נִתַּז דַּם הַחַטָּאת עַל הַבֶּגֶד וְנִתַּז עַל דַּם הַחַטָּאת דַּם חֻלִּין טָעוּן כִּבּוּס. אֲבָל אִם נִתַּז דַּם הַחֻלִּין תְּחִלָּה (אוֹ אֲפִלּוּ דַּם עוֹלָה) וְנִתַּז עָלָיו דַּם הַחַטָּאת אֵינוֹ טָעוּן כִּבּוּס שֶׁהֲרֵי לֹא נִבְלַע בּוֹ:","כְּשֶׁמְּכַבְּסִין אֶת מְקוֹם הַדָּם מְכַבְּסִין אוֹתוֹ בְּמַיִם יָפֶה יָפֶה עַד שֶׁלֹּא יִשָּׁאֵר לוֹ רשֶׁם. וְכָל שִׁבְעַת הַסַּמְמָנִים שֶׁמַּעֲבִירִין עַל הַכֶּתֶם מַעֲבִירִין עַל דַּם חַטָּאת. חוּץ מִמֵּי רַגְלַיִם שֶׁאֵין מַכְנִיסִין מֵי רַגְלַיִם לַמִּקְדָּשׁ:","כְּלִי חֶרֶשׂ שֶׁנִּתְבַּשְּׁלָה בּוֹ הַחַטָּאת הַנֶּאֱכֶלֶת טָעוּן שְׁבִירָה בָּעֲזָרָה. וּכְלִי מַתָּכוֹת שֶׁנִּתְבַּשְּׁלָה בּוֹ טָעוּן מְרִיקָה וּשְׁטִיפָה בְּמַיִם בָּעֲזָרָה שֶׁנֶּאֱמַר (ויקרא ו כא) \"וּכְלִי חֶרֶס אֲשֶׁר תְּבֻשַּׁל בּוֹ יִשָּׁבֵר\". אַף עַל פִּי שֶׁלֹּא נֶאֱמַר כָּאן (ויקרא ז ו) (ויקרא טז כד) \"בְּמָקוֹם קָדוֹשׁ\" הֲרֵי דִּינָן כְּדִין הַכִּבּוּס. מָה כִּבּוּס הַבֶּגֶד בַּקֹּדֶשׁ אַף שְׁבִירַת כְּלִי חֶרֶס וּשְׁטִיפַת כְּלִי מַתָּכוֹת וּמְרִיקָתוֹ בַּקֹּדֶשׁ. וְאֶחָד כְּלִי שֶׁבִּשֵּׁל בּוֹ אוֹ כְּלִי שֶׁהֶעֱרָה לְתוֹכוֹ רוֹתֵחַ:","מְרִיקָה בְּחַמִּין וּשְׁטִיפָה בְּצוֹנֵן. בְּמַיִם לֹא בְּיַיִן וְלֹא בְּמֶזֶג וְלֹא בִּשְׁאָר מַשְׁקִין. וְהַמְּרִיקָה וְהַשְּׁטִיפָה כִּמְרִיקַת הַכּוֹס וּשְׁטִיפָתוֹ. וְהַשִּׁפּוּד וְהָאַסְכָּלָה מַגְעִילָן בְּמַיִם חַמִּים עַל גַּבֵּי הָאֵשׁ וְאַחַר כָּךְ מְדִיחָן:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁבִּשֵּׁל בָּהֶן אַחַר שֶׁנִּזְרַק דָּמָהּ כְּהִלְכָתוֹ. אֲבָל אִם בִּשֵּׁל קֹדֶם זְרִיקָה אוֹ שֶׁבִּשֵּׁל בָּהּ בְּשַׂר חַטָּאת הַנִּשְׂרֶפֶת אֵינוֹ טָעוּן מְרִיקָה וּשְׁטִיפָה. בִּשֵּׁל בְּמִקְצָת הַכְּלִי כֻּלּוֹ טָעוּן מְרִיקָה וּשְׁטִיפָה:","צָלָה הַבָּשָׂר [בַּאֲוִיר] תַּנּוּר שֶׁל חֶרֶס יֵשׁ בַּדָּבָר סָפֵק אִם יִשָּׁבֵר הוֹאִיל וְנִתְבַּשְּׁלָה בּוֹ אוֹ לֹא יִשָּׁבֵר הוֹאִיל וְלֹא נָגְעָה בּוֹ. וְלֹא בְּחַטָּאת בִּלְבַד אֶלָּא כָּל הַכֵּלִים שֶׁמִּשְׁתַּמְּשִׁין בָּהֶן בְּקָדָשִׁים עַל יְדֵי חַמִּין בֵּין קָדְשֵׁי קָדָשִׁים בֵּין קָדָשִׁים קַלִּים טְעוּנִין מְרִיקָה וּשְׁטִיפָה עֵקֶב אֲכִילָה. וְכֵן הַשִּׁפּוּד וְהָאַסְכָּלָה מַגְעִילָן עֵקֶב אֲכִילָה. וְאֵינוֹ מְנִיחָן עַד זְמַן אֲכִילָה שְׁנִיָּה. אֶלָּא כְּשֶׁיַּשְׁלִים לֶאֱכל יַגְעִיל הַשִּׁפּוּד וְהָאַסְכָּלָה וִימָרֵק וַיִּשְׁטֹף הַכְּלִי בֵּין כְּלֵי מַתָּכוֹת בֵּין כְּלֵי חֶרֶס חוּץ מִן הַחַטָּאת שֶׁשּׁוֹבֵר בָּהּ כְּלֵי חֶרֶס. וּמְבַשֵּׁל וְשׁוֹנֶה וּמְשַׁלֵּשׁ מִיָּד בֵּין בִּכְלֵי מַתָּכוֹת בֵּין בִּכְלֵי חֶרֶס וּמְמָרֵק וְשׁוֹטֵף עַד סוֹף אֲכִילָה:","כְּלֵי גְּלָלִים וּכְלֵי אֲבָנִים וּכְלֵי אֲדָמָה אֵינָן טְעוּנִין מְרִיקָה וּשְׁטִיפָה אֲפִלּוּ בְּחַטָּאת אֶלָּא הֲדָחָה בִּלְבַד. נֶאֱמַר בְּחַטָּאת (ויקרא ו כ) \"כּל אֲשֶׁר יִגַּע בִּבְשָׂרָהּ יִקְדָּשׁ\" לִהְיוֹת כָּמוֹהָ. אִם פְּסוּלָה הִיא הַנּוֹגֵעַ בָּהּ פָּסוּל וְאִם כְּשֵׁרָה הַנּוֹגֵעַ בָּהּ יֵאָכֵל כָּמוֹהָ וּבִקְדֻשָּׁתָהּ:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁנִּבְלְעָה בּוֹ. אֲבָל נְגִיעָה בְּלֹא הַבְלָעָה אֵינָהּ מְקֻדֶּשֶׁת. וְאֶחָד הַחַטָּאת וְאֶחָד שְׁאָר קָדָשִׁים בֵּין קָדָשִׁים קַלִּים בֵּין חֲמוּרִים שֶׁנֶּאֱמַר (ויקרא ז לז) \"זֹאת הַתּוֹרָה לָעלָה וְלַמִּנְחָה\":","נָגַע בְּשָׂרָהּ בְּרָקִיק וְנִבְלַע בְּמִקְצָתוֹ לֹא נִתְקַדֵּשׁ כֻּלּוֹ אֶלָּא חוֹתֵךְ מְקוֹם הַבֶּלַע:","כְּלִי שֶׁבִּשֵּׁל בּוֹ קָדָשִׁים וְחֻלִּין אוֹ קָדְשֵׁי קָדָשִׁים וְקָדָשִׁים קַלִּים. אִם יֵשׁ בָּהֶן בְּנוֹתֵן טַעַם הֲרֵי הַכּל נֶאֱכָל כֶּחָמוּר שֶׁבָּהֶן. וְטָעוּן הַכְּלִי מְרִיקָה וּשְׁטִיפָה וְהַכּל כֶּחָמוּר שֶׁבָּהֶן לְכָל דָּבָר. וְאִם לֹא נָתַן טַעַם זֶה בָּזֶה אֵין הַקַּלִּין נֶאֱכָלִין כַּחֲמוּרִים וְאֵינָן כְּמוֹתָן לְכָל דָּבָר. אֲבָל הַכְּלִי טָעוּן מְרִיקָה וּשְׁטִיפָה:","בֶּגֶד שֶׁנִּתַּז עָלָיו דַּם הַחַטָּאת וְיָצָא חוּץ לָעֲזָרָה מַחְזִירוֹ לָעֲזָרָה וּמְכַבְּסוֹ שָׁם. נִטְמָא חוּץ לָעֲזָרָה כֵּיצַד יַעֲשֶׂה. קוֹרְעוֹ כְּדֵי שֶׁיִּטְהַר וּמַכְנִיסוֹ וּמְכַבְּסוֹ בִּפְנִים. וְצָרִיךְ לְהָנִיחַ בּוֹ שָׁלֵם כְּדֵי מַעֲפֹרֶת לְפִי שֶׁנֶּאֱמַר (ויקרא ו כ) \"בֶּגֶד\" צָרִיךְ לְכַבֵּס בֶּגֶד. וְאַף עַל פִּי שֶׁהוּא טָמֵא מִדִּבְרֵיהֶם מִפְּנֵי כְּדֵי הַמַּעֲפֹרֶת שֶׁנִּשְׁאֲרָה בּוֹ כֵּיוָן שֶׁנִּקְרַע רֻבּוֹ טָהוֹר מִן הַתּוֹרָה וּמֻתָּר לְהַכְנִיסוֹ לַמִּקְדָּשׁ לְכַבֵּס הַדָּם:","מְעִיל שֶׁנִּתַּז עָלָיו דַּם חַטָּאת וְיָצָא וְנִטְמָא לַחוּץ כֵּיצַד הוּא עוֹשֶׂה וַהֲרֵי הַקּוֹרֵעַ אוֹתוֹ לוֹקֶה כְּמוֹ שֶׁבֵּאַרְנוּ. מַכְנִיסוֹ פָּחוֹת פָּחוֹת מִשָּׁלֹשׁ אֶצְבָּעוֹת וּמְכַבְּסוֹ בִּפְנִים. וְאַחַר שֶׁיִּתְכַּבֵּס כָּל הַדָּם מְעַט מְעַט מַטְבִּילִין אוֹתוֹ בַּחוּץ:","כְּלִי חֶרֶס שֶׁבִּשֵּׁל בּוֹ הַחַטָּאת וְיָצָא מַכְנִיסוֹ וְשׁוֹבְרוֹ בִּפְנִים. נִטְמָא בַּחוּץ נוֹקְבוֹ בִּכְדֵי שֹׁרֶשׁ קָטָן כְּדֵי שֶׁיִּטְהַר וּמַכְנִיסוֹ וְשׁוֹבְרוֹ בִּפְנִים. וְאִם נִקְּבוֹ נֶקֶב גָּדוֹל מִזֶּה אֵינוֹ שׁוֹבְרוֹ בִּפְנִים שֶׁהֲרֵי אֵינוֹ כְּלִי וְאֵין שׁוֹבְרִין בִּפְנִים אֶלָּא כֵּלִים. וְכֵן כְּלִי מַתָּכוֹת שֶׁבִּשֵּׁל בּוֹ וְיָצָא חוּץ לָעֲזָרָה מַכְנִיסוֹ וּמוֹרְקוֹ וְשׁוֹטְפוֹ בִּפְנִים. נִטְמָא כְּשֶׁיָּצָא פּוֹחֲתוֹ עַד שֶׁיִּטְהַר וּמַכְנִיסוֹ בִּפְנִים וְחוֹזֵר וּמְרַדְּדוֹ עַד שֶׁיִּסָּתֵם הַפְּחָת וְיַחְזֹר כְּתַבְנִית הַכֵּלִים. וְאַחַר כָּךְ מוֹרְקוֹ וְשׁוֹטְפוֹ בָּעֲזָרָה שֶׁנֶּאֱמַר (ויקרא ו כא) \"וְאִם בִּכְלִי נְחשֶׁת\" וְגוֹ' אֵין מוֹרְקִין בִּפְנִים אֶלָּא כֵּלִים:"],"Mishneh Torah, Sales 19":["אָסוּר לַמּוֹכֵר לִמְכֹּר לַחֲבֵרוֹ קַרְקַע אוֹ מִטַּלִטְלִין שֶׁיֵּשׁ בָּהּ עֲסִיקִין וְיֵשׁ בָּהּ דִּין עַד שֶׁיּוֹדִיעוֹ. שֶׁאַף עַל פִּי שֶׁהָאַחֲרָיוּת עָלָיו אֵין אָדָם רוֹצֶה שֶׁיִּתֵּן מְעוֹתָיו וְיוֹרֵד לְדִין וְיִהְיֶה נִתְבָּע מֵאֲחֵרִים:","הַמּוֹכֵר קַרְקַע לַחֲבֵרוֹ וְאַחַר שֶׁקָּנָה הַלּוֹקֵחַ בְּאֶחָד מִן הַדְּרָכִים שֶׁקּוֹנִין בָּהֶן קֹדֶם שֶׁיִּשְׁתַּמֵּשׁ בָּהּ יָצָא עָלָיו מְעַרְעֲרִין. הֲרֵי זֶה יָכוֹל לַחְזֹר בּוֹ. שֶׁאֵין לְךָ מוּם גָּדוֹל מִזֶּה שֶׁעֲדַיִן לֹא נֶהֱנָה בּוֹ וּבָאוּ הַתּוֹבְעִין. לְפִיכָךְ יִבָּטֵל הַמִּקָּח וְיַחְזִיר הַמּוֹכֵר אֶת הַדָּמִים וְיַעֲשֶׂה דִּין עִם הַמְעַרְעְרִין. וְאִם נִשְׁתַּמֵּשׁ בָּהּ הַלּוֹקֵחַ כָּל שֶׁהוּא וַאֲפִלּוּ דָּשׁ הַמֵּצַר שֶׁלָּהּ וְעֵרְבוֹ עִם הָאָרֶץ אֵינוֹ יָכוֹל לַחְזֹר בּוֹ אֶלָּא עוֹשֶׂה דִּין עִם הַמְעַרְעְרִין. וְאִם הוֹצִיאוּ מִיָּדוֹ בְּדִין יַחְזֹר עַל הַמּוֹכֵר כְּדִין כָּל הַנִּטְרָפִין:","כָּל הַמּוֹכֵר קַרְקַע אוֹ עֶבֶד אוֹ שְׁאָר מִטַּלְטְלִין הֲרֵי זֶה חַיָּב בְּאַחֲרָיוּתָן. כֵּיצַד. אִם הוֹצִיא הַמִּקָּח מִיַּד הַלּוֹקֵחַ מֵחֲמַת הַמּוֹכֵר. חוֹזֵר הַלּוֹקֵחַ וְנוֹטֵל כָּל הַדָּמִים שֶׁנָּתַן מִן הַמּוֹכֵר שֶׁהֲרֵי נִלְקָח הַמִּקָּח מֵחֲמָתוֹ. כָּךְ הַדִּין בְּכָל מִמְכָּר אַף עַל פִּי שֶׁלֹּא פֵּרֵשׁ הַלּוֹקֵחַ דָּבָר זֶה אֶלָּא קָנָה סְתָם. אֲפִלּוּ מָכַר הַקַּרְקַע בִּשְׁטָר וְלֹא הִזְכִּיר בּוֹ הָאַחֲרָיוּת הֲרֵי זֶה חַיָּב בְּאַחֲרָיוּתָן. שֶׁאַחֲרָיוּת שֶׁלֹּא נִזְכַּר טָעוּת סוֹפֵר הוּא:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהוֹצִיא הַמִּקָּח מִיַּד הַלּוֹקֵחַ בְּבֵית דִּין שֶׁל יִשְׂרָאֵל. כְּגוֹן שֶׁהָיָה הַמִּקָּח מִטַּלְטְלִין וְהָיוּ גְּנוּבִין אוֹ גְּזוּלִין אוֹ שֶׁהָיְתָה הַקַּרְקַע גְּזוּלָה. אוֹ שֶׁבָּא בַּעַל חוֹב שֶׁל מוֹכֵר וּטְרָפָהּ מִיַּד הַלּוֹקֵחַ וְהַכּל בְּבֵית דִּין שֶׁל יִשְׂרָאֵל. אֲבָל אִם הָעוֹבֵד כּוֹכָבִים הוּא שֶׁהוֹצִיא הַמִּקָּח מִן הַלּוֹקֵחַ בֵּין בְּדִין הַמֶּלֶךְ בֵּין בְּעַרְכָּאוֹת שֶׁלָּהֶן. אֵין הַמּוֹכֵר חַיָּב בְּאַחֲרָיוּתוֹ. וְאַף עַל פִּי שֶׁהָעוֹבֵד כּוֹכָבִים טוֹעֵן שֶׁהַמּוֹכֵר גָּנַב חֵפֶץ זֶה אוֹ גְּזָלָהּ מִמֶּנּוּ וְהֵבִיא עֵדֵי עַכּוּ\"ם עַל כָּךְ אֵין הַמּוֹכֵר חַיָּב כְּלוּם. שֶׁזֶּה אֹנֶס הוּא וְאֵין הַמּוֹכֵר חַיָּב בְּאַחֲרָיוּת אֹנֶס:","הַמּוֹכֵר קַרְקַע לַחֲבֵרוֹ וְהִתְנָה עִמּוֹ שֶׁכָּל אֹנֶס שֶׁיִּוָּלֵד בְּקַרְקַע זֶה יִהְיֶה חַיָּב לְשַׁלֵּם. אֲפִלּוּ בָּא עַכּוּ\"ם וּגְזָלָהּ מֵחֲמַת הַמּוֹכֵר חַיָּב לְשַׁלֵּם. אֲבָל אִם נִפְסַק הַנָּהָר שֶׁהָיָה מַשְׁקֶה אוֹתָהּ. אוֹ שֶׁחָזַר הַנָּהָר לַעֲבֹר בְּתוֹכָהּ וְנַעֲשֵׂית בְּרֵכָה. אוֹ שֶׁבָּאָה זְוָעָה וְהִשְׁחִיתָה אוֹתָהּ. הֲרֵי זֶה פָּטוּר. שֶׁאֵלּוּ וְכַיּוֹצֵא בָּהֶן אֹנֶס שֶׁאֵינוֹ מָצוּי הוּא וְלֹא עָלָה עַל לֵב הַמּוֹכֵר דְּבַר זֶה הַפֶּלֶא בְּעֵת שֶׁהִתְנָה. וְכָל אֹנֶס שֶׁאֵינוֹ מָצוּי אֵינוֹ בִּכְלַל הַתְּנַאי הַזֶּה:","וְהוּא הַדִּין לְכָל תְּנַאי מָמוֹן שֶׁאוֹמְדִין דַּעַת הַמַּתְנֶה וְאֵין כּוֹלְלִין בְּאוֹתוֹ הַתְּנַאי אֶלָּא דְּבָרִים הַיְדוּעִין שֶׁבִּכְלָלָן הָיָה הַתְּנַאי וְהֵם שֶׁהָיוּ בְּדַעַת הַמַּתְנֶה בִּשְׁעַת שֶׁהִתְנָה:","מַעֲשֶׂה בְּאֶחָד שֶׁשָּׂכַר מַלָּחִים לְהָבִיא שֻׁמְשְׁמִין לְמָקוֹם פְּלוֹנִי. וְהִתְנָה עִמָּהֶם שֶׁהֵן חַיָּבִין בְּכָל אֹנֶס שֶׁיֶּאֱרַע לָהֶם עַד שֶׁיַּגִּיעוּ הַשֻּׁמְשְׁמִין לְמָקוֹם פְּלוֹנִי. וְנִפְסַק הַנָּהָר שֶׁהָיוּ מוֹלִיכִין בּוֹ. וְאָמְרוּ חֲכָמִים זֶה אֹנֶס שֶׁאֵינוֹ מָצוּי וְאֵין חַיָּבִין לְהוֹלִיךְ שֻׁמְשְׁמִין אֵלּוּ עַל גַּבֵּי בְּהֵמָה עַד אוֹתוֹ מָקוֹם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַמּוֹכֵר קַרְקַע לַחֲבֵרוֹ וְהִתְנָה הַמּוֹכֵר שֶׁלֹּא יִהְיֶה עָלָיו אַחֲרָיוּת. אֲפִלּוּ נוֹדַע בְּוַדַּאי שֶׁזּוֹ הָאָרֶץ גְּזוּלָה וְיָצָאת מִיַּד הַלּוֹקֵחַ. אֵין הַמּוֹכֵר חַיָּב כְּלוּם. וְאֵין צָרִיךְ לוֹמַר אִם בָּא בַּעַל חוֹב וּטְרָפָהּ שֶׁאֵינוֹ מַחְזִיר לוֹ כְּלוּם. שֶׁכָּל תְּנַאי שֶׁבְּמָמוֹן קַיָּם:","רְאוּבֵן שֶׁמָּכַר שָׂדֶה לְשִׁמְעוֹן שֶׁלֹּא בְּאַחֲרָיוּת. וּבָא לֵוִי וְהוֹצִיאָהּ מִיַּד שִׁמְעוֹן. אִם רָצָה רְאוּבֵן לַעֲשׂוֹת דִּין עִם לֵוִי עוֹשֶׂה. וְאֵין יָכוֹל לֵוִי לוֹמַר לוֹ מַה לִּי וּלְךָ וַהֲרֵי אֵין עָלֶיךָ אַחֲרָיוּת. שֶׁהֲרֵי רְאוּבֵן אוֹמֵר לוֹ אֵין רְצוֹנִי שֶׁיִּהְיֶה לְשִׁמְעוֹן תַּרְעֹמֶת עָלַי שֶׁהֲרֵי הִפְסִיד בִּגְלָלִי:","רְאוּבֵן שֶׁמָּכַר שָׂדֶה לְשִׁמְעוֹן שֶׁלֹּא בְּאַחֲרָיוּת וְחָזַר וּלְקָחָהּ מִשִּׁמְעוֹן בְּאַחֲרָיוּת. וּבָא בַּעַל חוֹב שֶׁל רְאוּבֵן לִטְרֹף אוֹתָהּ מִמֶּנּוּ. אֵינוֹ יָכוֹל לַחְזֹר עַל שִׁמְעוֹן. שֶׁאַף עַל פִּי שֶׁלֹּא קִבֵּל עָלָיו אַחֲרָיוּת לְשִׁמְעוֹן אַחֲרָיוּת עַצְמוֹ קִבֵּל שֶׁלֹּא יִהְיֶה הוּא הַמּוֹכֵר וְהוּא הַמּוֹצִיא לְעַצְמוֹ. אֲבָל אִם בָּא בַּעַל חוֹב שֶׁל יַעֲקֹב אֲבִיהֶם וּטְרָפָהּ מִיַּד רְאוּבֵן. חוֹזֵר בְּכָל הַדָּמִים עַל שִׁמְעוֹן. מִפְּנֵי שֶׁשִּׁמְעוֹן קִבֵּל לוֹ הָאַחֲרָיוּת וּרְאוּבֵן לֹא קִבֵּל לְשִׁמְעוֹן אַחֲרָיוּת שֶׁל אֲחֵרִים כְּלָל:"],"Mishneh Torah, Sales 3":["אֶחָד הַבְּהֵמָה וְאֶחָד שְׁאָר הַמִּטַּלְטְלִין נִקְנִין בְּמָעוֹת דִּין תּוֹרָה. וּמִשֶּׁנָּתַן אֶת הַמָּעוֹת קָנָה וְאֵין אֶחָד מֵהֶן יוּכַל לַחְזֹר בּוֹ. אֲבָל חֲכָמִים תִּקְּנוּ שֶׁלֹּא יִקְנוּ הַמִּטַּלְטְלִין אֶלָּא בְּהַגְבָּהָה אוֹ בִּמְשִׁיכַת דָּבָר שֶׁאֵין דַּרְכּוֹ לְהַגְבִּיהַּ:","כֵּיצַד. הַמְקַבֵּץ עֵצִים אוֹ פִּשְׁתָּן וְכַיּוֹצֵא בָּהֶן וְעָשָׂה מֵהֶן טָעוּן גָּדוֹל שֶׁאִי אֶפְשָׁר לְהַגְבִּיהוֹ. אֵינוֹ נִקְנֶה בִּמְשִׁיכָה. שֶׁהֲרֵי אֶפְשָׁר לְהַתִּיר הָאֶגֶד וּלְהַגְבִּיהוֹ עֵץ עֵץ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. אֲבָל אִם הָיָה טָעוּן שֶׁל אֱגוֹזִים אוֹ שֶׁל פִּלְפְּלִין אוֹ שֶׁל שְׁקֵדִים וְכַיּוֹצֵא בָּהֶן וְהָיָה גָּדוֹל שֶׁאֵין אֶחָד יוּכַל לְהַגְבִּיהוֹ. הֲרֵי זֶה נִקְנֶה בִּמְשִׁיכָה. שֶׁאִם יַתִּירוֹ יִתְפָּרֵד וְיִהְיֶה לוֹ בּוֹ טֹרַח גָּדוֹל. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַסְּפִינָה הוֹאִיל וְאִי אֶפְשָׁר לְהַגְבִּיהָהּ וְיֵשׁ בִּמְשִׁיכָתָהּ טֹרַח גָּדוֹל וְאֵינָהּ נִמְשֶׁכֶת אֶלָּא לָרַבִּים. לֹא הִצְרִיכוּהָ מְשִׁיכָה אֶלָּא נִקְנֵית בִּמְסִירָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְאִם אָמַר לוֹ הַמּוֹכֵר לֵךְ מְשֹׁךְ וּקְנֵה אֵינוֹ קוֹנֶה הַסְּפִינָה עַד שֶׁיִּמְשְׁכֶנָּה כֻּלָּהּ וְיוֹצִיאֶנָּהּ מִכָּל הַמָּקוֹם שֶׁהָיְתָה בּוֹ. שֶׁהֲרֵי הִקְפִּיד הַמּוֹכֵר שֶׁלֹּא יִקְנֶה זֶה אֶלָּא בִּמְשִׁיכָה:","נִמְצֵאתָ לָמֵד שֶׁהַלּוֹקֵחַ מִטַּלְטְלִין אַף עַל פִּי שֶׁנָּתַן כָּל הַדָּמִים יָכוֹל לַחְזֹר בּוֹ. וְכֵן הַמּוֹכֵר יָכוֹל לַחְזֹר בּוֹ עַד שֶׁיַּגְבִּיהַּ אוֹ יִמְשֹׁךְ דָּבָר שֶׁאֵין בּוֹ הַגְבָּהָה. אוֹ יִמְסֹר הַמּוֹכֵר לַלּוֹקֵחַ דָּבָר שֶׁאֵין דַּרְכּוֹ לְהַמְשִׁיךְ. וּמִשֶּׁהִגְבִּיהַּ אוֹ מָשַׁךְ דָּבָר שֶׁאֵין דַּרְכּוֹ לְהַגְבִּיהַּ אוֹ נִמְסַר לוֹ דָּבָר שֶׁאֵין דַּרְכּוֹ לְהַמְשִׁיךְ קָנָה וְאֵין אֶחָד מִשְּׁנֵיהֶם יָכוֹל לַחְזֹר בּוֹ. וְכוֹפִין אֶת הַלּוֹקֵחַ לִתֵּן אֶת הַדָּמִים:","וְלָמָּה תִּקְנוּ חֲכָמִים דָּבָר זֶה בְּמִטַּלְטְלִין. גְּזֵרָה שֶׁמָּא יִתֵּן הַלּוֹקֵחַ דְּמֵי הַחֵפֶץ וְקֹדֶם שֶׁיִּקָּחֶנּוּ יֹאבַד בְּאֹנֶס. וּכְגוֹן שֶׁנָּפְלָה דְּלֵקָה וְנִשְׂרַף. אוֹ בָּאוּ לִסְטִים וּנְטָלוּהוּ. אִם יִהְיֶה בִּרְשׁוּת הַלּוֹקֵחַ יִתְמַהְמֵהַּ הַמּוֹכֵר וְלֹא יַצִּילֵהוּ. לְפִיכָךְ הֶעֱמִידוּהוּ חֲכָמִים בִּרְשׁוּת הַמּוֹכֵר כְּדֵי שֶׁיִּשְׁתַּדֵּל וַיַּצִּיִל הַחֵפֶץ. שֶׁאִם אָבַד חַיָּב לְשַׁלֵּם:","נִמְצֵאתָ אוֹמֵר שֶׁאִם נָתַן דְּמֵי הַמִּקָּח וְנֶאֱנַס קדֶם שֶׁיִּקָּחֶנּוּ. וְאָמַר לוֹ הַלּוֹקֵחַ תֵּן לִי מִקָּחִי אוֹ הַחְזֵר לִי אֶת מְעוֹתַי. וְאַף עַל פִּי שֶׁיֵּשׁ עֵדִים שֶׁאָבַד בְּאֹנֶס וְלֹא הָיָה בַּמּוֹכֵר כֹּחַ לְהַצִּילוֹ וְלֹא נִתְרַשֵּׁל בַּדָּבָר. הֲרֵי זֶה מַחְזִיר אֶת הַדָּמִים. שֶׁהֲרֵי תִּקְּנוּ חֲכָמִים מְשִׁיכָה. לְפִיכָךְ אִם הָיָה בֵּיתוֹ שֶׁל לוֹקֵחַ שֶׁיֵּשׁ בּוֹ הַחֵפֶץ שֶׁנִּמְכַּר מֻשְׂכָּר לַמּוֹכֵר לֹא תִּקְּנוּ לוֹ חֲכָמִים מְשִׁיכָה. שֶׁהֲרֵי הַמִּקָּח בִּרְשׁוּת הַלּוֹקֵחַ. וּמִשֶּׁנָּתַן אֶת הַדָּמִים נִקְנָה הַמִּקָּח וְאֵין אֶחָד מֵהֶן יָכוֹל לַחְזֹר בּוֹ:","וְכֵן הַשּׂוֹכֵר הַמָּקוֹם שֶׁאוֹתָן הַמִּטַּלְטְלִין הַנִּמְכָּרִין מֻנָּחִין בּוֹ קָנָה. וְאֵין אֶחָד מֵהֶן יָכוֹל לַחְזֹר בּוֹ וְאַף עַל פִּי שֶׁלֹּא הִגְבִּיהַּ וְלֹא מָשַׁךְ וְלֹא נִמְסְרוּ לוֹ. שֶׁהֲרֵי נַעֲשָׂה בִּרְשׁוּתוֹ. וּכְבָר בֵּאַרְנוּ שֶׁשְּׂכִירוּת קַרְקַע נִקְנֶה בְּכֶסֶף אוֹ בִּשְׁטָר אוֹ בַּחֲזָקָה:","הַמַּקְנֶה קַרְקַע וּמִטַּלְטְלִין כְּאֶחָד כֵּיוָן שֶׁקָּנָה קַרְקַע בְּכֶסֶף אוֹ בִּשְׁטָר אוֹ בַּחֲזָקָה נִקְנוּ הַמִּטַּלְטְלִין עִמָּהֶם בֵּין שֶׁהָיוּ שְׁנֵיהֶם בְּמֶכֶר אוֹ בְּמַתָּנָה. בֵּין שֶׁמָּכַר מִטַּלְטְלִין וְנָתַן קַרְקַע. בֵּין שֶׁמָּכַר הַקַּרְקַע וְנָתַן הַמִּטַּלְטְלִין. כֵּיוָן שֶׁקָּנָה קַרְקַע קָנָה מִטַּלְטְלִין:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיוּ אוֹתָן הַמִּטַּלְטְלִין צְבוּרִין בְּאוֹתָהּ קַרְקַע. אֲבָל אִם הָיוּ בְּמָקוֹם אַחֵר צָרִיךְ שֶׁיֹּאמַר לוֹ קְנֵה מִטַּלְטְלִין אַגַּב קַרְקַע. אֲפִלּוּ הָיוּ הַמִּטַּלְטְלִין בִּמְדִינָה אַחֶרֶת וְאָמַר לוֹ קְנֵה אוֹתָם עַל גַּבֵּי קַרְקַע פְּלוֹנִית כֵּיוָן שֶׁקָּנָה הַקַּרְקַע נִקְנוּ הַמִּטַּלְטְלִין אַף עַל פִּי שֶׁאֵינָן צְבוּרִין בְּתוֹכָהּ. וְאִם לֹא אָמַר קְנֵה אַגַּב קַרְקַע לֹא קָנָה. וְקַרְקַע כָּל שֶׁהִיא קוֹנִין עַל גַּבָּהּ כָּל מִטַּלְטְלִין שֶׁיִּרְצֶה:","הִקְנָה הַשָּׂדֶה לְאֶחָד וְהַמִּטַּלְטְלִין לְאַחֵר אַף עַל פִּי שֶׁאָמַר לוֹ קְנֵה הַמִּטַּלְטְלִין עַל גַּבֵּי קַרְקַע וְהֶחֱזִיק הָאֶחָד בַּקַּרְקַע לֹא קָנָה הַשֵּׁנִי הַמִּטַּלְטְלִין. וְאִם תְּפָשָׂן אַחַר שֶׁחָזַר בּוֹ הַמַּקְנֶה אֵין מוֹצִיאִין מִיָּדוֹ. שֶׁהֲרֵי תְּפָשָׂן אַחַר שֶׁקָּנָה חֲבֵרוֹ הַקַּרְקַע שֶׁנִּקְנוּ אֵלּוּ עַל גַּבּוֹ:","הַמַּקְנֶה עֲבָדִים וְקַרְקָעוֹת כְּאֶחָד הֶחֱזִיק בַּעֲבָדִים לֹא קָנָה הַקַּרְקָעוֹת. הֶחֱזִיק בְּקַרְקָעוֹת לֹא קָנָה עֲבָדִים עַד שֶׁיִּהְיוּ עוֹמְדִין בְּתוֹךְ הַקַּרְקַע. וְאַף עַל פִּי שֶׁאָמַר לוֹ קְנֵה עֲבָדִים עַל גַּבֵּי קַרְקַע לֹא קָנָה עַד שֶׁיִּהְיוּ בְּתוֹכָהּ. שֶׁהָעֶבֶד מְהַלֵּךְ לְדַעַת עַצְמוֹ:","הַמַּקְנֶה עֲבָדִים וּמִטַּלְטְלִין כְּאֶחָד מָשַׁךְ הַמִּטַּלְטְלִין לֹא קָנָה הָעֲבָדִים הֶחֱזִיק בַּעֲבָדִים לֹא קָנָה הַמִּטַּלְטְלִין. אֶלָּא אִם כֵּן הָיוּ הַמִּטַּלְטְלִין עַל גַּב הָעֶבֶד. וְהוּא שֶׁיִּהְיֶה כָּפוּת שֶׁהֲרֵי אֵינוֹ יָכוֹל לְהַלֵּךְ:","הַמַּקְנֶה בְּהֵמָה וְכֵלִים שֶׁעַל גַּבָּהּ כְּאֶחָד אַף עַל פִּי שֶׁמָּשַׁךְ הַבְּהֵמָה וּקְנָאָהּ לֹא קָנָה הַכֵּלִים שֶׁעָלֶיהָ עַד שֶׁיַּגְבִּיהַּ אוֹ יִמְשֹׁךְ הַכֵּלִים עַצְמָן אִם אֵין דַּרְכָּן לְהַגְבִּיהָן. שֶׁהַבְּהֵמָה כֶּחָצֵר הַמִּתְהַלֶּכֶת הִיא וְאֵין מַה שֶּׁבְּתוֹכָהּ קָנוּי לְבַעְלָהּ. לְפִיכָךְ אִם הָיְתָה הַבְּהֵמָה כְּפוּתָה קָנָה אַף כֵּלִים שֶׁעָלֶיהָ:","אָמַר לוֹ הַמַּקְנֶה מְשֹׁךְ בְּהֵמָה וּקְנֵה כֵּלִים שֶׁעָלֶיהָ. הוֹאִיל וְלֹא הִקְנָה לוֹ גּוּף הַבְּהֵמָה אַף עַל פִּי שֶׁמְּשָׁכָהּ וְהִיא כְּפוּתָה לֹא קָנָה כֵּלִים שֶׁעָלֶיהָ עַד שֶׁיִּמְשֹׁךְ הַכֵּלִים עַצְמָן:","הָיָה עָצִיץ נָקוּב לְאֶחָד וְהָיוּ הַזְּרָעִים שֶׁבּוֹ לְאַחֵר. הִקְנָה הֶעָצִיץ לְבַעַל הַזְּרָעִים כֵּיוָן שֶׁמָּשַׁךְ קָנָה. הִקְנָה הַזְּרָעִים לְבַעַל הֶעָצִיץ לֹא קָנָה עַד שֶׁיַּחְזִיק בַּזְּרָעִים עַצְמָן:","הָיָה הֶעָצִיץ וְהַזְּרָעִים שֶׁבּוֹ לְאֶחָד וְהִקְנָה הַכּל לְאַחֵר וְהֶחֱזִיק בָּעָצִיץ לִקְנוֹת הַזְּרָעִים אַף הֶעָצִיץ לֹא קָנָה. הֶחֱזִיק בַּזְּרָעִים קָנָה הֶעָצִיץ. וְזֶהוּ שֶׁשָּׁנִינוּ נְכָסִים שֶׁאֵין לָהֶן אַחֲרָיוּת נִקְנִים עִם נְכָסִים שֶׁיֵּשׁ לָהֶן אַחֲרָיוּת. שֶׁהַזְּרָעִים שֶׁבְּעָצִיץ נָקוּב זְרוּעִים הֵם בָּאָרֶץ וְכָל הַמְחֻבָּר לַקַּרְקַע הֲרֵי הוּא כְּקַרְקַע כְּמוֹ שֶׁבֵּאַרְנוּ:","כְּבָר בֵּאַרְנוּ שֶׁכָּל הָעוֹמֵד לִבָּצֵר כְּבָצוּר דָּמִי וְאֵינוֹ נִקְנֶה אֶלָּא בְּהַגְבָּהָה אוֹ בִּשְׁאָר דְּבָרִים שֶׁנִּקְנִים בָּהֶן הַמִּטַּלְטְלִים:","פִּשְׁתָּן כְּשֶׁהוּא מְחֻבָּר לַקַּרְקַע וְיָבֵשׁ שֶׁאֵינוֹ צָרִיךְ לַקַּרְקַע וְאָמַר לוֹ יַפֶּה לִי קַרְקַע כָּל שֶׁהוּא וּקְנֵה כָּל מַה שֶּׁעָלֶיהָ. כֵּיוָן שֶׁתָּלַשׁ כָּל שֶׁהוּא קָנָה הַכּל מִפְּנֵי הַתְּנַאי הַזֶּה. אֲבָל אִם (אָמַר לוֹ) הִקְנָה לוֹ הַפִּשְׁתָּן הַזֶּה בְּמֶכֶר אוֹ בְּמַתָּנָה לֹא קָנָה אֶלָּא מַה שֶּׁתָּלַשׁ שֶׁהֲרֵי הִגְבִּיהוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Sanctification of the New Month 13":["אִם תִּרְצֶה לֵידַע מְקוֹם הַשְּׁמֶשׁ הָאֲמִתִּי בְּכָל יוֹם שֶׁתִּרְצֶה. תּוֹצִיא תְּחִלָּה מְקוֹמָהּ הָאֶמְצָעִי לְאוֹתוֹ הַיּוֹם עַל הַדֶּרֶךְ שֶׁבֵּאַרְנוּ. וְתוֹצִיא מְקוֹם גֹּבַהּ הַשֶּׁמֶשׁ. וְתִגְרַע מְקוֹם גֹּבַהּ הַשֶּׁמֶשׁ מִמְּקוֹם הַשֶּׁמֶשׁ הָאֶמְצָעִי וְהַנִּשְׁאָר הוּא הַנִּקְרָא מַסְלוּל הַשֶּׁמֶשׁ:","וְתִרְאֶה כַּמָּה מַעֲלוֹת הוּא מַסְלוּל הַשֶּׁמֶשׁ. אִם הָיָה הַמַּסְלוּל פָּחוֹת מִק\"פ מַעֲלוֹת. תִּגְרַע מְנַת הַמַּסְלוּל מִמְּקוֹם הַשֶּׁמֶשׁ הָאֶמְצָעִי. וְאִם הָיָה הַמַּסְלוּל יוֹתֵר עַל ק\"פ מַעֲלוֹת עַד ש\"ס תּוֹסִיף מְנַת הַמַּסְלוּל עַל מְקוֹם הַשֶּׁמֶשׁ הָאֶמְצָעִי. וּמַה שֶּׁיִּהְיֶה אַחַר שֶׁתּוֹסִיף עָלָיו אוֹ תִּגְרַע מִמֶּנּוּ הוּא הַמָּקוֹם הָאֲמִתִּי:","וְדַע שֶׁאִם יִהְיֶה הַמַּסְלוּל ק\"פ בְּשָׁוֶה אוֹ ש\"ס בְּשָׁוֶה. אֵין לוֹ מָנָה אֶלָּא יִהְיֶה הַמָּקוֹם הָאֶמְצָעִי הוּא הַמָּקוֹם הָאֲמִתִּי:","וְכַמָּה הִיא מְנַת הַמַּסְלוּל. אִם יִהְיֶה הַמַּסְלוּל עֶשֶׂר מַעֲלוֹת. תִּהְיֶה מְנָתוֹ כ' חֲלָקִים. וְאִם יִהְיֶה כ' מַעֲלוֹת תִּהְיֶה מְנָתוֹ מ' חֲלָקִים. וְאִם יִהְיֶה ל' מַעֲלוֹת תִּהְיֶה מְנָתוֹ נ\"ח חֲלָקִים. וְאִם יִהְיֶה מ' מַעֲלוֹת תִּהְיֶה מְנָתוֹ מַעֲלָה אַחַת וְט\"ו חֲלָקִים. וְאִם יִהְיֶה נ' מַעֲלוֹת תִּהְיֶה מְנָתוֹ מַעֲלָה אַחַת וְכ\"ט חֲלָקִים. וְאִם יִהְיֶה ס' מַעֲלוֹת תִּהְיֶה מְנָתוֹ מַעֲלָה אַחַת וּמ\"א חֲלָקִים. וְאִם יִהְיֶה ע' מַעֲלוֹת תִּהְיֶה מְנָתוֹ מַעֲלָה אַחַת וְנ\"א חֲלָקִים. וְאִם יִהְיֶה פ' מַעֲלוֹת תִּהְיֶה מְנָתוֹ מַעֲלָה אַחַת וְנ\"ז חֲלָקִים. וְאִם יִהְיֶה צ' מַעֲלוֹת תִּהְיֶה מְנָתוֹ מַעֲלָה אַחַת וְנ\"ט חֲלָקִים. וְאִם יִהְיֶה ק' מַעֲלוֹת תִּהְיֶה מְנָתוֹ מַעֲלָה אַחַת וְנ\"ח חֲלָקִים. וְאִם יִהְיֶה ק\"י תִּהְיֶה מְנָתוֹ מַעֲלָה אַחַת וְנ\"ג חֲלָקִים. וְאִם יִהְיֶה ק\"כ תִּהְיֶה מְנָתוֹ מַעֲלָה אַחַת וּמ\"ה חֲלָקִים. וְאִם יִהְיֶה ק\"ל תִּהְיֶה מְנָתוֹ מַעֲלָה אַחַת ל\"ג חֲלָקִים. וְאִם יִהְיֶה ק\"מ תִּהְיֶה מְנָתוֹ מַעֲלָה אַחַת וְי\"ט חֲלָקִים. וְאִם יִהְיֶה ק\"נ תִּהְיֶה מְנָתוֹ מַעֲלָה אַחַת וְחֵלֶק אֶחָד. וְאִם יִהְיֶה ק\"ס תִּהְיֶה מְנָתוֹ מ\"ב חֲלָקִים. וְאִם יִהְיֶה ק\"ע תִּהְיֶה מְנָתוֹ כ\"א חֲלָקִים. וְאִם יִהְיֶה ק\"פ בְּשָׁוֶה אֵין לוֹ מָנָה כְּמוֹ שֶׁבֵּאַרְנוּ אֶלָּא מְקוֹם הַשֶּׁמֶשׁ הָאֶמְצָעִי הוּא מְקוֹמָהּ הָאֲמִתִּי:","הָיָה הַמַּסְלוּל יֶתֶר עַל ק\"פ מַעֲלוֹת. תִּגְרַע אוֹתוֹ מִש\"ס מַעֲלוֹת וְתֵדַע מְנָתוֹ. כֵּיצַד. הֲרֵי שֶׁהָיָה הַמַּסְלוּל ר' מַעֲלוֹת. תִּגְרַע אוֹתוֹ מִש\"ס תִּשָּׁאֵר ק\"ס מַעֲלוֹת. וּכְבָר הוֹדַעְנוּ שֶׁמְּנַת ק\"ס מַעֲלוֹת מ\"ב חֲלָקִים. וְכֵן מְנַת הַמָּאתַיִם מ\"ב חֲלָקִים:","וְכֵן אִם הָיָה הַמַּסְלוּל ש' מַעֲלוֹת. תִּגְרַע אוֹתוֹ מִש\"ס יִשָּׁאֵר ס'. וּכְבָר יָדַעְתָּ שֶׁמְּנַת ס' מַעֲלוֹת מַעֲלָה אַחַת וּמ\"א חֲלָקִים. וְכֵן הִיא מְנַת הַש' מַעֲלוֹת. וְעַל דֶּרֶךְ זוֹ בְּכָל מִנְיָן וּמִנְיָן:","הֲרֵי שֶׁהָיָה הַמַּסְלוּל ס\"ה מַעֲלוֹת. וּכְבָר יָדַעְנוּ שֶׁמְּנַת הַשִּׁשִּׁים הִיא מַעֲלָה אַחַת וּמ\"א חֲלָקִים. וּמְנַת הָע' הִיא מַעֲלָה אַחַת וְנ\"א חֲלָקִים. נִמְצָא בֵּין שְׁתֵּי הַמָּנוֹת י' חֲלָקִים. וּלְפִי חֶשְׁבּוֹן הַמַּעֲלוֹת יִהְיֶה לְכָל מַעְלָה חֵלֶק אֶחָד. וְיִהְיֶה מְנַת הַמַּסְלוּל שֶׁהוּא ס\"ה מַעֲלָה אַחַת וּמ\"ו חֲלָקִים:","וְכֵן אִלּוּ הָיָה הַמַּסְלוּל ס\"ז הָיְתָה מְנָתוֹ מַעֲלָה אַחַת וּמ\"ח חֲלָקִים. וְעַל דֶּרֶךְ זוֹ תַּעֲשֶׂה בְּכָל מַסְלוּל שֶׁיִּהְיֶה בְּמִנְיָנוֹ אֲחָדִים עִם הָעֲשָׂרוֹת. בֵּין בְּחֶשְׁבּוֹן הַשֶּׁמֶשׁ בֵּין בְּחֶשְׁבּוֹן הַיָּרֵחַ:","כֵּיצַד. הֲרֵי שֶׁרָצִינוּ לֵידַע מְקוֹם הַשֶּׁמֶשׁ הָאֲמִתִּי בִּתְחִלַּת לֵיל הַשַּׁבָּת י\"ד יוֹם לְחֹדֶשׁ תַּמּוּז מִשָּׁנָה זוֹ. תּוֹצִיא אֶמְצַע הַשֶּׁמֶשׁ תְּחִלָּה לָעֵת הַזֹּאת. וְסִימָנוֹ ק\"ה ל\"ז כ\"ה כְּמוֹ שֶׁבֵּאַרְנוּ. וְתוֹצִיא מְקוֹם גֹּבַהּ הַשֶּׁמֶשׁ לָעֵת הַזֹּאת. יֵצֵא לְךָ סִימָנוֹ פ\"ו מ\"ה כ\"ג. וְתִגְרַע מְקוֹם הַגֹּבַהּ מִן הָאֶמְצָעִי. יֵצֵא לְךָ הַמַּסְלוּל י\"ח מַעֲלוֹת וְנ\"ב חֲלָקִים וּשְׁתֵּי שְׁנִיּוֹת. סִימָנָם י\"ח נ\"ב ב'. וְאַל תַּקְפִּיד בְּכָל מַסְלוּל עַל הַחֲלָקִים אֶלָּא אִם יִהְיוּ פָּחוֹת מִשְּׁלֹשִׁים אַל תִּפְנֶה אֲלֵיהֶם. וְאִם הָיוּ שְׁלֹשִׁים אוֹ יוֹתֵר תַּחְשֹׁב אוֹתָם מַעֲלָה אַחַת וְתוֹסִיף אוֹתָהּ עַל מִנְיַן מַעֲלוֹת הַמַּסְלוּל. לְפִיכָךְ יִהְיֶה מַסְלוּל זֶה י\"ט מַעֲלוֹת וְתִהְיֶה מְנָתוֹ עַל הַדֶּרֶךְ שֶׁבֵּאַרְנוּ ל\"ח חֲלָקִים:","וּלְפִי שֶׁהַמַּסְלוּל הַזֶּה הָיָה פָּחוֹת מִק\"פ. תִּגְרַע הַמָּנָה שֶׁהִיא ל\"ח חֲלָקִים מֵאֶמְצַע הַשֶּׁמֶשׁ יִשָּׁאֵר ק\"ד מַעֲלוֹת וְנ\"ט חֲלָקִים וְכ\"ה שְׁנִיּוֹת. סִימָנָם ק\"ד נ\"ט כ\"ה. וְנִמְצָא מְקוֹם הַשֶּׁמֶשׁ הָאֲמִתִּי בִּתְחִלַּת לֵיל זֶה בְּמַזַּל סַרְטָן בְּט\"ו מַעֲלוֹת בּוֹ פָּחוֹת ל\"ה שְׁנִיּוֹת. וְאַל תִּפְנֶה אֶל הַשְּׁנִיּוֹת כְּלָל לֹא בִּמְקוֹם הַשֶּׁמֶשׁ וְלֹא בִּמְקוֹם הַיָּרֵחַ וְלֹא בִּשְׁאָר חֶשְׁבּוֹנוֹת הָרְאִיָּה. אֶלָּא חֲקֹר עַל הַחֲלָקִים בִּלְבַד. וְאִם יִהְיוּ הַשְּׁנִיּוֹת קָרוֹב לִשְׁלֹשִׁים עֲשֵׂה אוֹתָם חֵלֶק אֶחָד וְהוֹסִיפוֹ עַל הַחֲלָקִים:","וּמֵאַחַר שֶׁתֵּדַע מְקוֹם הַשֶּׁמֶשׁ בְּכָל עֵת שֶׁתִּרְצֶה. תֵּדַע יוֹם הַתְּקוּפָה הָאֲמִתִּי כָּל תְּקוּפָה שֶׁתִּרְצֶה. בֵּין תְּקוּפוֹת הַבָּאוֹת אַחַר עִקָּר זֶה שֶׁמִּמֶּנּוּ הִתְחַלְנוּ. בֵּין תְּקוּפוֹת שֶׁעָבְרוּ מִשָּׁנִים קַדְמוֹנִיּוֹת:"],"Mishneh Torah, Sanctification of the New Month 7":["אֵין קוֹבְעִין לְעוֹלָם רֹאשׁ חֹדֶשׁ תִּשְׁרֵי לְפִי חֶשְׁבּוֹן זֶה לֹא בְּאֶחָד בְּשַׁבָּת וְלֹא בִּרְבִיעִי בְּשַׁבָּת וְלֹא בְּעֶרֶב שַׁבָּת. סִימָן לָהֶם אד\"ו. אֶלָּא כְּשֶׁיִּהְיֶה מוֹלַד תִּשְׁרֵי בְּאֶחָד מִשְּׁלֹשָׁה יָמִים הָאֵלּוּ קוֹבְעִין רֹאשׁ חֹדֶשׁ בַּיּוֹם שֶׁלְּאַחֲרָיו. כֵּיצַד. הֲרֵי שֶׁהָיָה הַמּוֹלָד בְּאֶחָד בְּשַׁבָּת קוֹבְעִין רֹאשׁ חֹדֶשׁ תִּשְׁרֵי יוֹם שֵׁנִי. וְאִם הָיָה הַמּוֹלָד בִּרְבִיעִי קוֹבְעִין רֹאשׁ חֹדֶשׁ יוֹם חֲמִישִׁי. וְאִם הָיָה הַמּוֹלָד בְּשִׁשִּׁי קוֹבְעִין רֹאשׁ חֹדֶשׁ בִּשְׁבִיעִי:","וְכֵן אִם יִהְיֶה הַמּוֹלָד בַּחֲצִי הַיּוֹם אוֹ לְמַעְלָה מֵחֲצִי הַיּוֹם קוֹבְעִין רֹאשׁ חֹדֶשׁ בַּיּוֹם שֶׁלְּאַחֲרָיו. כֵּיצַד. הֲרֵי שֶׁהָיָה הַמּוֹלָד בְּיוֹם שֵׁנִי בְּשֵׁשׁ שָׁעוֹת בַּיּוֹם אוֹ יֶתֶר עַל שֵׁשׁ שָׁעוֹת קוֹבְעִין רֹאשׁ חֹדֶשׁ בִּשְׁלִישִׁי. וְאִם יִהְיֶה הַמּוֹלָד קֹדֶם חֲצִי הַיּוֹם אֲפִלּוּ בְּחֵלֶק אֶחָד קוֹבְעִין רֹאשׁ הַחֹדֶשׁ בְּאוֹתוֹ יוֹם הַמּוֹלָד עַצְמוֹ. וְהוּא שֶׁלֹּא יִהְיֶה אוֹתוֹ הַיּוֹם מִימֵי אד\"ו:","כְּשֶׁיִּהְיֶה הַמּוֹלָד בַּחֲצִי הַיּוֹם אוֹ אַחַר חֲצוֹת וְיִדָּחֶה לַיּוֹם שֶׁלְּאַחֲרָיו. אִם יִהְיֶה יוֹם שֶׁלְּאַחֲרָיו מִימֵי אד\"ו הֲרֵי זֶה נִדְחֶה לְשֶׁלְּאַחֲרָיו וְיִהְיֶה רֹאשׁ הַחֹדֶשׁ קָבוּעַ בִּשְׁלִישִׁי מִיּוֹם הַמּוֹלָד. כֵּיצַד. הֲרֵי שֶׁיִּהְיֶה הַמּוֹלָד בְּשַׁבָּת בַּחֲצוֹת סִימָן זי\"ח קוֹבְעִין רֹאשׁ הַחֹדֶשׁ בַּשָּׁנָה שֶׁמּוֹלָדָהּ כָּזֶה בְּשֵׁנִי בְּשַׁבָּת. וְכֵן אִם הָיָה הַמּוֹלָד בִּשְׁלִישִׁי בַּחֲצוֹת אוֹ אַחַר חֲצוֹת קוֹבְעִין רֹאשׁ הַחֹדֶשׁ בַּחֲמִישִׁי בְּשַׁבָּת:","מוֹלַד תִּשְׁרֵי שֶׁיָּצָא בְּחֶשְׁבּוֹן זֶה בְּלֵיל שְׁלִישִׁי בְּתֵשַׁע שָׁעוֹת בַּלַּיְלָה וּמָאתַיִם וְאַרְבָּעָה חֲלָקִים מִשָּׁעָה עֲשִׂירִית סִימָנָהּ ג\"ט ר\"ד. אוֹ יוֹתֵר עַל זֶה. אִם הָיְתָה שָׁנָה פְּשׁוּטָה דּוֹחִין אֶת רֹאשׁ הַחֹדֶשׁ וְאֵין קוֹבְעִים אוֹתוֹ בִּשְׁלִישִׁי בְּשָׁנָה זוֹ אֶלָּא בַּחֲמִישִׁי בְּשַׁבָּת:","וְכֵן אִם יָצָא מוֹלַד תִּשְׁרֵי בְּיוֹם שֵׁנִי בְּשָׁלֹשׁ שָׁעוֹת בְּיוֹם וְתקפ\"ט חֲלָקִים מִשָּׁעָה רְבִיעִית. סִימָנָהּ בט\"ו תקפ\"ט. אוֹ יֶתֶר עַל כֵּן. אִם הָיְתָה אוֹתָהּ הַשָּׁנָה מוֹצָאֵי הַמְעֻבֶּרֶת שֶׁהָיְתָה הַשָּׁנָה הַסְּמוּכָה לָהּ שֶׁעָבְרָה מְעֻבֶּרֶת. אֵין קוֹבְעִין רֹאשׁ הַחֹדֶשׁ בְּשֵׁנִי בְּשָׁנָה זוֹ אֶלָּא בִּשְׁלִישִׁי:","הָיָה מוֹלַד הַשָּׁנָה הַפְּשׁוּטָה שֶׁאָמַרְנוּ שֶׁתִּדָּחֶה לַחֲמִישִׁי פָּחוֹת חֵלֶק אֶחָד. כְּגוֹן שֶׁיָּצָא סִימָנָהּ ג\"ט ר\"ג אוֹ פָּחוֹת מִזֶּה. קוֹבְעִין אוֹתָהּ בִּשְׁלִישִׁי. וְכֵן אִם הָיָה מוֹלַד מוֹצָאֵי הָעִבּוּר בְּיוֹם שֵׁנִי פָּחוֹת חֵלֶק. כְּגוֹן שֶׁהָיָה סִימָנָהּ בט\"ו תקפ\"ח אוֹ פָּחוֹת מִזֶּה. קוֹבְעִין אוֹתָהּ בְּשֵׁנִי. נִמְצָא דֶּרֶךְ קְבִיעַת רֹאשׁ חֹדֶשׁ תִּשְׁרֵי לְפִי חֶשְׁבּוֹן זֶה כָּךְ הוּא. תַּחְשֹׁב וְתֵדַע הַמּוֹלָד בְּאֵי זֶה יוֹם יִהְיֶה וּבְכַמָּה שָׁעוֹת מִן הַיּוֹם אוֹ מִן הַלַּיְלָה וּבְכַמָּה חֲלָקִים מִן הַשָּׁעָה. וְיוֹם הַמּוֹלָד הוּא יוֹם הַקְּבִיעָה לְעוֹלָם. אֶלָּא אִם כֵּן הָיָה בְּאֶחָד בְּשַׁבָּת אוֹ בִּרְבִיעִי אוֹ בְּעֶרֶב שַׁבָּת. אוֹ אִם הָיָה הַמּוֹלָד בַּחֲצוֹת הַיּוֹם אוֹ אַחַר חֲצוֹת. אוֹ אִם הָיָה בר\"ד חֲלָקִים מִשָּׁעָה עֲשִׂירִית מִלֵּיל שְׁלִישִׁי אוֹ יוֹתֵר עַל זֶה וְהָיְתָה שָׁנָה פְּשׁוּטָה. אוֹ שֶׁהָיָה הַמּוֹלָד בתקפ\"ט חֲלָקִים מִשָּׁעָה רְבִיעִית מִיּוֹם שֵׁנִי וְהָיְתָה הַשָּׁנָה פְּשׁוּטָה שֶׁאַחַר הַמְעֵבֶּרֶת. שֶׁאִם יֶאֱרַע בְּאֶחָד מֵאַרְבָּעָה דְּבָרִים הָאֵלּוּ אֵין קוֹבְעִין בְּיוֹם הַמּוֹלָד אֶלָּא בַּיּוֹם שֶׁלְּאַחֲרָיו אוֹ שֶׁלְּאַחַר אַחֲרָיו כַּדֶּרֶךְ שֶׁבֵּאַרְנוּ:","וּמִפְּנֵי מָה אֵין קוֹבְעִין בְּחֶשְׁבּוֹן זֶה בִּימֵי אד\"ו. לְפִי שֶׁהַחֶשְׁבּוֹן הַזֶּה הוּא לְקִבּוּץ הַיָּרֵחַ וְהַשֶּׁמֶשׁ בְּהִלּוּכָהּ הָאֶמְצָעִי לֹא בַּמָּקוֹם הָאֲמִתִּי כְּמוֹ שֶׁהוֹדַעְנוּ. לְפִיכָךְ עָשׂוּ יוֹם קְבִיעָה וְיוֹם דְּחִיָּה כְּדֵי לִפְגֹּעַ בְּיוֹם קִבּוּץ הָאֲמִתִּי. כֵּיצַד. בִּשְׁלִישִׁי קוֹבְעִין בִּרְבִיעִי דּוֹחִין. בַּחֲמִישִׁי קוֹבְעִין בְּשִׁשִּׁי דּוֹחִין. בְּשַׁבָּת קוֹבְעִין אֶחָד בְּשַׁבָּת דּוֹחִין. בְּשֵׁנִי קוֹבְעִין:","וְעִקַּר שְׁאָר הָאַרְבַּע דְּחִיּוֹת אֵלּוּ הוּא זֶה הָעִקָּר שֶׁאָמַרְנוּ שֶׁהַחֶשְׁבּוֹן הַזֶּה בְּמַהֲלָךְ אֶמְצָעִי. וּרְאָיָה לַדָּבָר שֶׁהַמּוֹלָד יִהְיֶה בְּלֵיל שְׁלִישִׁי וְיִדָּחֶה לַחֲמִישִׁי פְּעָמִים רַבּוֹת לֹא יֵרָאֶה יָרֵחַ בְּלֵיל חֲמִישִׁי וְלֹא בְּלֵיל שִׁשִּׁי מִכְּלַל שֶׁלֹּא נִתְקַבְּצוּ הַשֶּׁמֶשׁ וְהַיָּרֵחַ קִבּוּץ אֲמִתִּי אֶלָּא בַּחֲמִישִׁי:"],"Mishneh Torah, Second Tithes and Fourth Year's Fruit 4":["הָרוֹצֶה לִפְדּוֹת פֵּרוֹת מַעֲשֵׂר שֵׁנִי פּוֹדֶה אוֹתָן בִּדְמֵיהֶן וְאוֹמֵר הֲרֵי הַמָּעוֹת הָאֵלּוּ תַּחַת הַפֵּרוֹת הָאֵלּוּ אוֹ הַפֵּרוֹת הָאֵלּוּ מְחֻלָּלוֹת עַל הַמָּעוֹת הָאֵלּוּ. וְאִם לֹא פֵּרֵשׁ אֶלָּא הִפְרִישׁ מָעוֹת בִּלְבַד כְּנֶגֶד הַפֵּרוֹת דַּיּוֹ וְאֵינוֹ צָרִיךְ לְפָרֵשׁ וְיֵצְאוּ הַפֵּרוֹת לְחֻלִּין. וְיַעֲלוּ הַמָּעוֹת לִירוּשָׁלַיִם וְיוֹצִיאֵם שָׁם שֶׁנֶּאֱמַר (דברים יד כד) \"וְכִי יִרְבֶּה מִמְּךָ הַדֶּרֶךְ כִּי לֹא תוּכַל שְׂאֵתוֹ\":","וְכֵן אִם רָצָה לְחַלֵּל פֵּרוֹת הַמַּעֲשֵׂר עַל פֵּרוֹת אֲחֵרוֹת. יַעֲלוּ הַפֵּרוֹת הַשְּׁנִיּוֹת וְיֵאָכְלוּ בִּירוּשָׁלַיִם. וְלֹא יְחַלֵּל מִמִּין עַל שֶׁאֵינוֹ מִינוֹ וְלֹא מִן הַיָּפֶה עַל הָרַע וַאֲפִלּוּ בְּאוֹתוֹ הַמִּין. וְאִם חִלֵּל הֲרֵי הֵן מְחֻלָּלוֹת:","הַפּוֹדֶה מַעֲשֵׂר שֵׁנִי מְבָרֵךְ אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל פִּדְיוֹן מַעֲשֵׂר שֵׁנִי. וְאִם חִלְּלָן עַל פֵּרוֹת אֲחֵרוֹת אוֹ שֶׁחִלֵּל מָעוֹת עַל הַפֵּרוֹת מְבָרֵךְ עַל חִלּוּל מַעֲשֵׂר שֵׁנִי. וְהַפּוֹדֶה אוֹ הַמְחַלֵּל מַעֲשֵׂר שֵׁנִי שֶׁל דְּמַאי אֵינוֹ צָרִיךְ בְּרָכָה:","כְּשֶׁפּוֹדִין אֶת הַמַּעֲשֵׂר אֵין פּוֹדִין אוֹתוֹ לְשֵׁם מַעֲשֵׂר אֶלָּא לְשֵׁם חֻלִּין. וְאוֹמְרִין כַּמָּה שָׁוִין פֵּרוֹת חֻלִּין אֵלּוּ וְאַף עַל פִּי שֶׁהַכּל יוֹדְעִין שֶׁהֵן מַעֲשֵׂר כְּדֵי שֶׁלֹּא יִתְבַּזֶּה:","אֵין מְחַלְּלִין מְעוֹת מַעֲשֵׂר שֵׁנִי עַל מָעוֹת אֲחֵרוֹת. בֵּין שֶׁהָיוּ אֵלּוּ וְאֵלּוּ כֶּסֶף אוֹ אֵלּוּ וְאֵלּוּ נְחשֶׁת. [אוֹ הָרִאשׁוֹנוֹת כֶּסֶף וְהַשְּׁנִיּוֹת נְחשֶׁת. אוֹ] הָרִאשׁוֹנוֹת נְחשֶׁת וְהַשְּׁנִיּוֹת כֶּסֶף. וְאִם עָבַר וְחִלֵּל הֲרֵי אֵלּוּ מְחֻלָּלִין:","אֵין מְחַלְּלִין מָעוֹת מַעֲשֵׂר עַל הַפֵּרוֹת. וְאִם חִלֵּל יַעֲלוּ הַפֵּרוֹת וְיֵאָכְלוּ בִּירוּשָׁלַיִם. וְלֹא יְחַלְּלֵם עַל בְּהֵמָה חַיָּה וְעוֹף חַיִּין. וְאִם חִלֵּל לֹא קָנָה מַעֲשֵׂר שֶׁמָּא יְגַדֵּל מֵהֶם עֲדָרִים עֲדָרִים. אֲבָל אִם חִלֵּל עַל שְׁחוּטִים הֲרֵי הֵן כִּשְׁאָר הַפֵּרוֹת וְיַעֲלוּ וְיֵאָכְלוּ בִּירוּשָׁלַיִם וְיֵצְאוּ הַמָּעוֹת לְחֻלִּין:","בִּשְׁעַת הַדְּחָק מֻתָּר לְחַלֵּל מָעוֹת הַכֶּסֶף עַל שֶׁל נְחשֶׁת. לֹא שֶׁיְּקַיֵּם כֵּן אֶלָּא עַד שֶׁיִּמְצָא רֶוַח. וְיַחֲזֹר וִיחַלֵּל מָעוֹת הַנְּחשֶׁת עַל מָעוֹת הַכֶּסֶף:","מַעֲשֵׂר שֵׁנִי שֶׁל דְּמַאי מְחַלְּלִים אוֹתוֹ לְכַתְּחִלָּה כֶּסֶף עַל כֶּסֶף וְכֶסֶף עַל נְחשֶׁת וּנְחשֶׁת עַל נְחשֶׁת וּנְחשֶׁת עַל הַפֵּרוֹת וְיַעֲלוּ אוֹתָן הַפֵּרוֹת וְיֵאָכְלוּ בִּירוּשָׁלַיִם:","אֵין פּוֹדִין פֵּרוֹת מַעֲשֵׂר אֶלָּא בְּכֶסֶף שֶׁנֶּאֱמַר (דברים יד כה) \"וְצַרְתָּ הַכֶּסֶף\". וְכֵן אִם פָּדָה לְעַצְמוֹ וְהוֹסִיף חֹמֶשׁ לֹא יִהְיֶה הַחֹמֶשׁ אֶלָּא כֶּסֶף כַּקֶּרֶן. וְאֵין פּוֹדִין בְּכֶסֶף שֶׁאֵינוֹ מַטְבֵּעַ אֶלָּא בְּכֶסֶף מְפֻתָּח שֶׁיֵּשׁ עָלָיו צוּרָה אוֹ כְּתָב [שֶׁנֶּאֱמַר וְצַרְתָּ הַכֶּסֶף]. וְאִם פָּדָה בְּלָשׁוֹן שֶׁל כֶּסֶף וְכַיּוֹצֵא בּוֹ וְהוּא הַנִּקְרָא אֲסִימוֹן לֹא עָשָׂה כְּלוּם. וְאֵין פּוֹדִין בְּפָחוֹת מִפְּרוּטָה מִפְּנֵי שֶׁהוּא כְּפוֹדֶה בַּאֲסִימוֹן:","אֵין פּוֹדִין בְּמַטְבֵּעַ שֶׁאֵינוֹ יוֹצֵא בְּאוֹתוֹ זְמַן וּבְאוֹתוֹ מָקוֹם שֶׁנֶּאֱמַר (דברים יד כו) \"וְנָתַתָּ הַכֶּסֶף בְּכֹל אֲשֶׁר תְּאַוֶּה נַפְשְׁךָ\" עַד שֶׁיִּהְיֶה רָאוּי לְהוֹצָאָה. וּמַטְבֵּעַ מְלָכִים הָרִאשׁוֹנִים אִם יוֹצֵא מִשְּׁמָם פּוֹדִין בּוֹ:","אֵינוֹ פּוֹדֶה בְּמָעוֹת שֶׁאֵינָן בִּרְשׁוּתוֹ שֶׁנֶּאֱמַר (דברים יד כה) \"וְצַרְתָּ הַכֶּסֶף בְּיָדְךָ\". נָפַל כִּיסוֹ לְבוֹר וְהוּא יָכוֹל לְהוֹצִיאוֹ פּוֹדֶה בּוֹ מִפְּנֵי שֶׁהוּא בִּרְשׁוּתוֹ:","הָיָה בָּא בַּדֶּרֶךְ וּמָעוֹת בְּיָדוֹ וְאַנָּס בָּא כְּנֶגְדּוֹ אִם יָכוֹל לְהַצִּיל עַל יְדֵי הַדְּחָק פּוֹדֶה בָּהֶן פֵּרוֹת שֶׁבְּבֵיתוֹ. וְאִם לָאו וְאָמַר פֵּרוֹת שֶׁיֵּשׁ לִי בְּתוֹךְ בֵּיתִי מְחֻלָּלִין עַל הַמָּעוֹת הַלָּלוּ לֹא אָמַר כְּלוּם:","הַמֵּנִיחַ מָעוֹת לִהְיוֹת מְחַלֵּל עֲלֵיהֶן מַעֲשֵׂר שֵׁנִי הֲרֵי זֶה פּוֹדֶה בָּהֶן בְּחֶזְקַת שֶׁהֵן קַיָּמִים. מְצָאָן שֶׁאָבְדוּ חוֹשֵׁשׁ לְכָל מַה שֶּׁפָּדָה בָּהֶן לְמַפְרֵעַ:","מִי שֶׁהָיָה עוֹמֵד בִּטְבֶרְיָא וְיֵשׁ לוֹ מָעוֹת (בָּבֶל) בְּבָבֶל אֵינוֹ מְחַלֵּל עֲלֵיהֶם. הָיוּ לוֹ מָעוֹת מִמַּטְבֵּעַ טְבֶרְיָא בְּבָבֶל מְחַלֵּל עֲלֵיהֶם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הָאוֹמֵר מַעֲשֵׂר שֵׁנִי מְחֻלָּל עַל סֶלַע שֶׁתַּעֲלֶה בְּיָדִי מִכִּיס זֶה עַל סֶלַע שֶׁאֶפְרֹט מִדִּינָר זָהָב זֶה עַל פּוּנְדְיוֹן שֶׁאֶפְרֹט מִסֶּלַע זֶה הֲרֵי זֶה חִלֵּל. וְסֶלַע שֶׁתַּעֲלֶה בְּיָדוֹ אוֹ שֶׁיִּפְרֹט תְּהִי מַעֲשֵׂר:","אָמַר הֲרֵי מַעֲשֵׂר מְחֻלָּל עַל סֶלַע שֶׁהָיְתָה בְּיַד בְּנִי לֹא חִלֵּל. שֶׁמָּא לֹא הָיְתָה בְּיָדוֹ בְּאוֹתָהּ שָׁעָה:","הַפּוֹדֶה מַעֲשֵׂר שֵׁנִי קֹדֶם שֶׁיַּפְרִישֶׁנּוּ כְּגוֹן שֶׁאָמַר מַעֲשֵׂר שֵׁנִי שֶׁל פֵּרוֹת אֵלּוּ פָּדוּי בְּמָעוֹת אֵלּוּ לֹא אָמַר כְּלוּם וְלֹא קָבַע מַעֲשֵׂר. אֲבָל אִם קָבַע וְאָמַר מַעֲשֵׂר שֵׁנִי שֶׁלָּהֶן בַּצָּפוֹן אוֹ בַּדָּרוֹם מְחֻלָּל עַל הַמָּעוֹת אֵלּוּ הֲרֵי זֶה פָּדוּי:","כְּשֶׁפּוֹדִין מַעֲשֵׂר שֵׁנִי פּוֹדִין אוֹתוֹ בְּשָׁוְיוֹ. וְיֵשׁ לוֹ לִפְדּוֹת בַּשַּׁעַר הַזּוֹל כְּמוֹת שֶׁהַחֶנְוָנִי לוֹקֵחַ וְלֹא כְּמוֹת שֶׁהוּא מוֹכֵר. וְנוֹתֵן הַמָּעוֹת כְּמוֹת שֶׁהַשֻּׁלְחָנִי פּוֹרֵט לֹא כְּמוֹת שֶׁהוּא מְצָרֵף. וְאִם עָבַר וּפָדָה שְׁוֵה מָנֶה בִּפְרוּטָה אוֹ חִלֵּל שְׁוֵה מָנֶה עַל שְׁוֵה פְּרוּטָה הֲרֵי זֶה מְחֻלָּל:","הָיְתָה הַסֶּלַע חֲסֵרָה שְׁתוּת אוֹ פָּחוֹת מִשְּׁתוּת אִם הָיְתָה יוֹצֵאת עַל יְדֵי הַדְּחָק מְחַלֵּל עָלֶיהָ לְכַתְּחִלָּה בִּשְׁוֵה סֶלַע וְאֵינוֹ חוֹשֵׁשׁ. פָּדָה בְּסֶלַע וְנִמְצֵאת רָעָה יַחֲלִיפֶנָּה:","אֵין פּוֹדִין מַעֲשֵׂר שֵׁנִי אַכְסָרָה אֶלָּא מְדַקְדֵּק בְּמִדָּתוֹ אוֹ בְּמִשְׁקָלוֹ וְנוֹתֵן דָּמָיו. אִם הָיוּ דָּמָיו יְדוּעִים יִפָּדֶה עַל פִּי אֶחָד. וְאִם דָּבָר שֶׁאֵין דָּמָיו יְדוּעִים כְּגוֹן יַיִן שֶׁהִתְחִיל לְהַחֲמִיץ וּפֵרוֹת שֶׁהִרְקִיבוּ אוֹ מָעוֹת שֶׁהֶחֱלִידוּ יִפָּדֶה עַל פִּי שְׁלֹשָׁה תַּגָּרִים וַאֲפִלּוּ הָיָה אֶחָד מֵהֶן עַכּוּ\"ם אוֹ בַּעַל הַמַּעֲשֵׂר אֲפִלּוּ אִישׁ וּשְׁתֵּי נָשָׁיו פּוֹדִין עַל פִּיהֶם. וְכוֹפִין אֶת הַבְּעָלִים לִפְתֹּחַ רִאשׁוֹן. וְזֶה חֹמֶר בְּמַעֲשֵׂר מִן הַהֶקְדֵּשׁ:","אֵין מוֹלִיכִין פֵּרוֹת מַעֲשֵׂר מִמָּקוֹם לְמָקוֹם לִפְדּוֹתָם שָׁם. וְהַמּוֹלִיךְ מִמְּקוֹם הַיֹּקֶר לַמָּקוֹם הַזּוֹל אוֹ מִמָּקוֹם הַזּוֹל לִמְקוֹם הַיֹּקֶר פּוֹדֶה כְּשַׁעַר מְקוֹם הַפְּדִיָּה. וְאִם הָיוּ דְּמַאי פּוֹדִין אוֹתוֹ כַּשַּׁעַר הַזּוֹל הוֹאִיל וְנִרְאוּ לְהִמָּכֵר בְּזוֹל:","הָיוּ לוֹ פֵּרוֹת מַעֲשֵׂר שֵׁנִי בַּגֹּרֶן וְהוֹצִיא עֲלֵיהֶם יְצִיאוֹת מִבֵּיתוֹ עַד שֶׁהֱבִיאָן לָעִיר וְהִשְׁבִּיחוּ. פּוֹדֶה כְּשַׁעַר הָעִיר וְהִפְסִיד יְצִיאוֹתָיו:"],"Mishneh Torah, Sheqel Dues 2":["כֵּיצַד כּוֹנְסִין הַשֻּׁלְחָנִים אֶת הַשְּׁקָלִים בְּכָל מְדִינָה וּמְדִינָה. מַנִּיחִין לִפְנֵיהֶם שְׁתֵּי תֵּבוֹת שׁוּלֵי הַתֵּבָה רְחָבִין מִלְּמַטָּה וּפִיהָ צַר מִלְּמַעְלָה כְּמִין שׁוֹפָר כְּדֵי שֶׁיַּשְׁלִיכוּ לְתוֹכָן וְלֹא יִהְיֶה אֶפְשָׁר לִקַּח מֵהֶן בְּנַחַת. וְלָמָּה עוֹשִׂין שְׁתֵּי תֵּבוֹת. אַחַת שֶׁמַּשְׁלִיכִין בָּהּ שְׁקָלִים שֶׁל שָׁנָה זוֹ. וְהַשְּׁנִיָּה מַנִּיחִין בָּהּ שִׁקְלֵי שָׁנָה שֶׁעָבְרָה. שֶׁגּוֹבִין מִמִּי שֶׁלֹּא שָׁקַל בְּשָׁנָה שֶׁעָבְרָה:","וּבַמִּקְדָּשׁ הָיָה לִפְנֵיהֶם תָּמִיד שְׁלֹשׁ עֶשְׂרֵה תֵּבוֹת. כָּל תֵּבָה כְּמִין שׁוֹפָר. רִאשׁוֹנָה לְשִׁקְלֵי שָׁנָה זוֹ. שְׁנִיָּה לְשִׁקְלֵי שָׁנָה שֶׁעָבְרָה. שְׁלִישִׁית לְכָל מִי שֶׁיֵּשׁ עָלָיו קָרְבַּן שְׁתֵּי תּוֹרִים אוֹ שְׁנֵי בְּנֵי יוֹנָה אֶחָד עוֹלָה וְאֶחָד חַטָּאת מַשְׁלִיךְ דְּמֵיהֶן לְתֵבָה זוֹ. רְבִיעִית לְכָל מִי שֶׁיֵּשׁ עָלָיו עוֹלַת הָעוֹף בִּלְבַד מַשְׁלִיךְ דָּמֶיהָ לְתֵבָה זוֹ. חֲמִישִׁית לְמִי שֶׁהִתְנַדֵּב מָעוֹת לִקְנוֹת עֵצִים לַמַּעֲרָכָה בָּהֶן. שִׁשִּׁית לְמִי שֶׁהִתְנַדֵּב מָעוֹת לִלְבוֹנָה. שְׁבִיעִית לְמִי שֶׁהִתְנַדֵּב זָהָב לַכַּפֹּרֶת. שְׁמִינִית לְמוֹתַר חַטָּאת כְּגוֹן שֶׁהִפְרִישׁ מָעוֹת לְחַטָּאתוֹ וְלָקַח חַטָּאת וְהוֹתִיר מִן הַמָּעוֹת יַשְׁלִיךְ הַשְּׁאָר לְתוֹכָהּ. תְּשִׁיעִית לְמוֹתַר אָשָׁם. עֲשִׂירִית לְמוֹתַר קִנֵּי זָבִים וְזָבוֹת וְיוֹלְדוֹת. אַחַת עֶשְׂרֵה לְמוֹתַר קָרְבְּנוֹת נָזִיר. שְׁתֵּים עֶשְׂרֵה לְמוֹתַר אֲשַׁם מְצֹרָע. שְׁלֹשׁ עֶשְׂרֵה לְמִי שֶׁהִתְנַדֵּב מָעוֹת לְעוֹלַת בְּהֵמָה:","וְשֵׁם כָּל דָּבָר שֶׁיִּהְיוּ מָעוֹתָיו בְּתוֹךְ הַתֵּבָה כָּתוּב עַל הַתֵּבָה מִבַּחוּץ. וּתְנַאי בֵּית דִּין הוּא עַל כָּל הַמּוֹתָרוֹת שֶׁיִּקָּרְבוּ עוֹלַת בְּהֵמָה. נִמְצֵאתָ לָמֵד שֶׁכָּל הַמָּעוֹת הַנִּמְצָאוֹת בְּשֵׁשׁ הַתֵּבוֹת הָאַחֲרוֹנוֹת לְעוֹלַת בְּהֵמָה וְעוֹרוֹתֶיהָ לַכֹּהֲנִים כִּשְׁאָר כָּל הָעוֹרוֹת. וְכָל הַמָּעוֹת שֶׁבְּתֵבָה שְׁלִישִׁית לִקַּח בָּהֶן עוֹפוֹת חֶצְיָן עוֹלוֹת וְחֶצְיָן חַטָּאוֹת. וְשֶׁבָּרְבִיעִית כֻּלָּן עוֹלַת הָעוֹף:","בְּכָל מְדִינָה וּמְדִינָה כְּשֶׁגּוֹבִין הַשְּׁקָלִים מְשַׁלְּחִין אוֹתָן בְּיַד שְׁלוּחִים לַמִּקְדָּשׁ. וְיֵשׁ לָהֶם לְצָרֵף אוֹתָן בְּדִינְרֵי זָהָב מִפְּנֵי מַשּׂאוֹי הַדֶּרֶךְ. וְהַכּל מִתְקַבְּצִין לַמִּקְדָּשׁ וּמַנִּיחִין אוֹתָן בְּלִשְׁכָּה אַחַת מִן הַלְּשָׁכוֹת בַּמִּקְדָּשׁ וְסוֹגְרִין כָּל דַּלְתוֹתֶיהָ בְּמַפְתְּחוֹת וְחוֹתְמִין עָלֶיהָ חוֹתָמוֹת וּמְמַלְּאִין מִכָּל הַשְּׁקָלִים שֶׁיִּתְקַבְּצוּ שָׁם שָׁלֹשׁ קֻפּוֹת גְּדוֹלוֹת שִׁעוּר כָּל קֻפָּה כְּדֵי שֶׁתָּכִיל תֵּשַׁע סְאִין וְהַשְּׁאָר מַנִּיחִין אוֹתוֹ בַּלִּשְׁכָּה. וְזֶה שֶׁבְּתוֹךְ הַקֻּפּוֹת הוּא הַנִּקְרָא תְּרוּמַת הַלִּשְׁכָּה וְזֶה שֶׁיִּשָּׁאֵר שָׁם יֶתֶר עַל מַה שֶּׁיֵּשׁ בַּקֻּפּוֹת הוּא הַנִּקְרָא שְׁיָרֵי הַלִּשְׁכָּה:","בִּשְׁלֹשָׁה פְּרָקִים בַּשָּׁנָה תּוֹרְמִין אֶת הַלִּשְׁכָּה. בְּרֹאשׁ חֹדֶשׁ נִיסָן. וּבְרֹאשׁ חֹדֶשׁ תִּשְׁרֵי קֹדֶם יוֹם טוֹב אוֹ אַחֲרָיו. וְקֹדֶם עֲצֶרֶת בַּחֲמִשָּׁה עָשָׂר יוֹם. וְכֵיצַד תּוֹרְמִין אוֹתָהּ. אֶחָד נִכְנַס לִפְנִים מִן הַלִּשְׁכָּה וְהַשּׁוֹמְרִין עוֹמְדִים בַּחוּץ וְהוּא אוֹמֵר לָהֶם אֶתְרֹם וְהֵן אוֹמְרִים לוֹ תְּרֹם תְּרֹם תְּרֹם שְׁלֹשָׁה פְּעָמִים. וְאַחַר כָּךְ מְמַלֵּא שָׁלֹשׁ קֻפּוֹת קְטַנּוֹת כָּל קֻפָּה מֵהֶן מְכִילָה שָׁלֹשׁ סְאִין מֵאוֹתָן שָׁלֹשׁ קֻפּוֹת הַגְּדוֹלוֹת וּמוֹצִיאָן לַחוּץ כְּדֵי לְהִסְתַּפֵּק מֵהֶן עַד שֶׁיִּכְלוּ. וְחוֹזֵר וּמְמַלֵּא אוֹתָן הַשָּׁלֹשׁ קֻפּוֹת הַקְּטַנּוֹת מִן שָׁלֹשׁ גְּדוֹלוֹת פַּעַם שְׁנִיָּה קֹדֶם עֲצֶרֶת וּמִסְתַּפְּקִין מֵהֶן עַד שֶׁיִּכְלוּ:","וְחוֹזֵר וּמְמַלֵּא אוֹתָן פַּעַם שְׁלִישִׁית מִן הַשָּׁלֹשׁ קֻפּוֹת הַגְּדוֹלוֹת בְּתִשְׁרֵי וּמִסְתַּפְּקִין מֵהֶן עַד שֶׁיִּכְלוּ עַד רֹאשׁ חֹדֶשׁ נִיסָן. וּבְרֹאשׁ חֹדֶשׁ נִיסָן תּוֹרְמִין מִתְּרוּמָה חֲדָשָׁה. לֹא הִסְפִּיקוּ לָהֶן הַשְּׁקָלִים שֶׁבְּשָׁלֹשׁ קֻפּוֹת הַגְּדוֹלוֹת וְכָלוּ עַד שֶׁלֹּא הִגִּיעַ נִיסָן חוֹזְרִין וְתוֹרְמִין מִשְּׁיָרֵי הַלִּשְׁכָּה:","שָׁלֹשׁ קֻפּוֹת הַקְּטַנּוֹת שֶׁהוּא תּוֹרֵם בָּהֶם וּמוֹצִיאָן לַחוּץ כָּתוּב עֲלֵיהֶן אָלֶ\"ף בֵּי\"ת גִּימֶ\"ל כְּדֵי שֶׁיִּסְתַּפְּקוּ מִן הָרִאשׁוֹנָה עַד שֶׁתִּכְלֶה. וְאַחַר כָּךְ מִסְתַּפְּקִין מִן הַשְּׁנִיָּה. וְאַחַר כָּךְ מִסְתַּפְּקִין מִן הַשְּׁלִישִׁית. וְתוֹרֵם רִאשׁוֹנָה מִן הַקֻּפָּה הָאַחַת הַגְּדוֹלָה וּמְחַפֶּה אוֹתָהּ הַגְּדוֹלָה בְּמִטְפַּחַת. וְתוֹרֵם הַשְּׁנִיָּה מֵהַקֻּפָּה הַגְּדוֹלָה הַשְּׁנִיָּה וּמְחַפֶּה אוֹתָהּ הַגְּדוֹלָה בְּמִטְפַּחַת. וְתוֹרֵם הַשְּׁלִישִׁית מִן הַקֻּפָּה הַגְּדוֹלָה הַשְּׁלִישִׁית וְאֵינוֹ מְחַפֶּה אוֹתָהּ בְּמִטְפַּחַת כְּדֵי שֶׁתִּהְיֶה נִכֶּרֶת שֶׁבָּהּ סִיֵּם. וְיַתְחִיל מִמֶּנָּה בַּתְּחִלָּה בְּפַעַם שְׁנִיָּה כְּשֶׁיִּכָּנֵס קֹדֶם עֲצֶרֶת. וְתוֹרֵם הָרִאשׁוֹנָה מִן הַגְּדוֹלָה שֶׁהָיְתָה מְגֻלָּה וּמְחַפֶּה אוֹתָהּ. וְתוֹרֵם הַשְּׁנִיָּה מִן הַגְּדוֹלָה שֶׁתָּרַם מִמֶּנָּה בָּרִאשׁוֹנָה תְּחִלָּה וּמְחַפֶּה אוֹתָהּ. וְתוֹרֵם הַשְּׁלִישִׁית מִן הַגְּדוֹלָה הַסְּמוּכָה לָהּ וְאֵינוֹ מְחַפֶּה אוֹתָהּ כְּדֵי שֶׁיַּתְחִיל מִמֶּנָּה בַּתְּחִלָּה בְּפַעַם שְׁלִישִׁית כְּשֶׁיִּכָּנֵס בְּתִשְׁרֵי. עַד שֶׁנִּמְצָא תּוֹרֵם רִאשׁוֹנָה וּשְׁנִיָּה וּשְׁלִישִׁית הַקְּטַנּוֹת מִכָּל אַחַת וְאַחַת מִן הַגְּדוֹלוֹת:","כְּשֶׁהוּא תּוֹרֵם שָׁלֹשׁ קֻפּוֹת אֵלּוּ תּוֹרֵם אֶת הָרִאשׁוֹנָה לְשֵׁם אֶרֶץ יִשְׂרָאֵל. וְהַשְּׁנִיָּה לְשֵׁם הַכְּרַכִּין הַמֻּקָּפִין לָהּ וּלְשֵׁם כָּל (אֶרֶץ) יִשְׂרָאֵל. וְהַשְּׁלִישִׁית לְשֵׁם בָּבֶל וּלְשֵׁם מָדַי וּלְשֵׁם הַמְּדִינוֹת הָרְחוֹקוֹת וּלְשֵׁם שְׁאָר כָּל יִשְׂרָאֵל:","כְּשֶׁהוּא תּוֹרֵם מִתְכַּוֵּן לִתְרֹם עַל הַגָּבוּי שֶׁיֵּשׁ בַּלִּשְׁכָּה. וְעַל הַגָּבוּי שֶׁעֲדַיִן לֹא הִגִּיעַ לַלִּשְׁכָּה. וְעַל הֶעָתִיד לִגָּבוֹת כְּדֵי שֶׁיִּהְיוּ אֵלּוּ הַשְּׁקָלִים שֶׁהוֹצִיאָן לְהִסְתַּפֵּק מֵהֶן כַּפָּרָה עַל כָּל יִשְׂרָאֵל וּכְאִלּוּ הִגִּיעוּ כָּל שִׁקְלֵיהֶן לַלִּשְׁכָּה וְנִתְרְמָה מֵהֶן תְּרוּמָה זוֹ:","כְּשֶׁיִּכָּנֵס הַתּוֹרֵם לִתְרֹם לֹא יִכָּנֵס בְּבֶגֶד שֶׁאֶפְשָׁר לְהַחְבּוֹת בּוֹ כֶּסֶף וְלֹא בְּמִנְעָל וְלֹא בְּסַנְדָּל וְלֹא בִּתְפִלָּה וְלֹא בְּקָמֵעַ שֶׁמָּא יַחְשְׁדוּ אוֹתוֹ הָעָם וְיֹאמְרוּ הֶחְבִּיא מִמְּעוֹת הַלִּשְׁכָּה תַּחְתָּיו כְּשֶׁתְּרָמָהּ. וּמְדַבְּרִים הָיוּ עִמּוֹ מִשָּׁעָה שֶׁיִּכָּנֵס עַד שָׁעָה שֶׁיֵּצֵא כְּדֵי שֶׁלֹּא יִתֵּן לְתוֹךְ פִּיו. וְאַף עַל פִּי שֶׁנִּזְהָרִים כָּל כָּךְ עָנִי אוֹ מִי שֶׁהוּא נִבְהַל לַהוֹן לֹא יִתְרֹם מִפְּנֵי הַחֲשָׁד שֶׁנֶּאֱמַר (במדבר לב כב) \"וִהְיִיתֶם נְקִיִּים מֵה' וּמִיִּשְׂרָאֵל\":"],"Mishneh Torah, Slaves 2":["עֶבֶד עִבְרִי שֶׁמְּכָרוּהוּ בֵּית דִּין [וְהַמּוֹכֵר עַצְמוֹ] נִקְנֶה בְּכֶסֶף וּבִשְׁוֵה כֶּסֶף וּבִשְׁטָר. כֵּיצַד בִּשְׁטָר. כּוֹתֵב לוֹ עַל הַנְּיָר אוֹ עַל הַחֶרֶס הֲרֵינִי מָכוּר לְךָ הֲרֵינִי קָנוּי לְךָ וְנוֹתֵן לוֹ הַשְּׁטָר:","מְכָרוּהוּ בֵּית דִּין עוֹבֵד שֵׁשׁ שָׁנִים מִיּוֹם מְכִירָתוֹ וּבִתְחִלַּת הַשָּׁנָה הַשְּׁבִיעִית שֶׁלּוֹ יֵצֵא בֶּן חוֹרִין. וְאִם פָּגְעָה בּוֹ שְׁנַת הַשְּׁמִטָּה בִּכְלַל הַשֵּׁשׁ הֲרֵי זֶה עוֹבֵד בָּהּ. אֲבָל אִם פָּגְעָה בּוֹ שְׁנַת יוֹבֵל אֲפִלּוּ נִמְכַּר שָׁנָה אַחַת לִפְנֵי הַיּוֹבֵל הֲרֵי זֶה יֵצֵא לְחֵרוּת שֶׁנֶּאֱמַר (ויקרא כה מ) \"עַד שְׁנַת הַיֹּבֵל יַעֲבֹד עִמָּךְ\" (ויקרא כה יג) \"בִּשְׁנַת הַיּוֹבֵל הַזֹּאת\" וְגוֹ':","הַמּוֹכֵר עַצְמוֹ יֵשׁ לוֹ לִמְכֹּר עַצְמוֹ לְיֶתֶר עַל שֵׁשׁ. הֲרֵי שֶׁמָּכַר עַצְמוֹ לְעֶשֶׂר שָׁנִים אוֹ לְעֶשְׂרִים שָׁנָה וּפָגַע בּוֹ יוֹבֵל אֲפִלּוּ אַחַר שָׁנָה הֲרֵי זֶה יוֹצֵא בַּיּוֹבֵל שֶׁנֶּאֱמַר (ויקרא כה מ) \"עַד שְׁנַת הַיֹּבֵל יַעֲבֹד עִמָּךְ\":","אֶחָד הַמּוֹכֵר עַצְמוֹ אוֹ שֶׁמְּכָרוּהוּ בֵּית דִּין וּבָרַח חַיָּב לְהַשְׁלִים שֵׁשׁ. וְאִם פָּגַע בּוֹ יוֹבֵל יוֹצֵא לְחֵרוּת:","חָלָה בֵּין שֶׁחָלָה שָׁנָה אַחַר שָׁנָה אוֹ שֶׁחָלָה חֳלָאִים מְקֻטָּעִים אִם הַכּל פָּחוֹת מֵאַרְבַּע שָׁנִים עוֹלִין לְמִנְיַן שֵׁשׁ. אֲבָל אִם חָלָה אַרְבַּע שָׁנִים חַיָּב לְהַשְׁלִים כָּל יְמֵי הַחֹלִי שֶׁנֶּאֱמַר (ויקרא כה מ) \"כְּשָׂכִיר כְּתוֹשָׁב\". וְאִם פָּגַע בּוֹ יוֹבֵל יֵצֵא. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁמְּחַשְּׁבִין יְמֵי הַחֹלִי כְּשֶׁהָיָה חָלְיוֹ כָּבֵד שֶׁאֵינוֹ יָכוֹל לַעֲשׂוֹת מְלָאכָה. אֲבָל אִם לֹא הָיָה חָלְיוֹ כָּבֵד אֶלָּא יָכוֹל לַעֲשׂוֹת מַעֲשֵׂה מַחַט אֲפִלּוּ חָלָה כָּל שֵׁשׁ עוֹלִין לוֹ:","הַמּוֹכֵר עַצְמוֹ לְעַכּוּ\"ם אִם לֹא נִפְדָּה אֵינוֹ יוֹצֵא אֶלָּא בַּיּוֹבֵל שֶׁנֶּאֱמַר (ויקרא כה נד) \"וְאִם לֹא יִגָּאֵל בְּאֵלֶּה וְיָצָא בִּשְׁנַת הַיֹּבֵל הוּא וּבָנָיו עִמּוֹ\":","הַנִּמְכָּר לְעַכּוּ\"ם אִם לֹא הִשִּׂיגָה יָדוֹ לִגְאל קְרוֹבָיו פּוֹדִין אוֹתוֹ וְקָרוֹב קָרוֹב קוֹדֵם שֶׁנֶּאֱמַר (ויקרא כה מט) \"אוֹ דֹדוֹ אוֹ בֶן דֹּדוֹ יִגְאָלֶנּוּ\". וּבֵית דִּין כּוֹפִין אֶת קְרוֹבָיו לִפְדּוֹתוֹ שֶׁלֹּא יִטָּמַע בָּעַכּוּ\"ם. לֹא פְּדָאוּהוּ קְרוֹבָיו אוֹ שֶׁאֵין יָדָם מַשֶּׂגֶת מִצְוָה עַל כָּל אָדָם מִיִּשְׂרָאֵל לִפְדּוֹתוֹ. וּבֵין שֶׁפְּדָאוּהוּ קְרוֹבִים בֵּין שֶׁפְּדָאָהוּ שְׁאָר אָדָם יֵצֵא לְחֵרוּת. וְיֵשׁ לוֹ לִלְווֹת וְלִגְאל אֶת עַצְמוֹ מִן הָעַכּוּ\"ם. וְגוֹאֵל לַחֲצָאִין. אֲבָל הַנִּמְכָּר לְיִשְׂרָאֵל אֵין הַקְּרוֹבִים פּוֹדִין אוֹתוֹ וְאֵין לוֶֹה וְגוֹאֵל וְאֵינוֹ גּוֹאֵל לַחֲצָאִין. אֶלָּא כֵּיצַד דִּינוֹ. אִם הִשִּׂיגָה יָדוֹ לִתֵּן כְּפִי הַשָּׁנִים הַנּוֹתָרוֹת נוֹתֵן וְיוֹצֵא וְאִם לָאו לֹא יֵצֵא:","אֶחָד הַמּוֹכֵר עַצְמוֹ בֵּין לְיִשְׂרָאֵל בֵּין לְעַכּוּ\"ם וְאֶחָד שֶׁמְּכָרוּהוּ בֵּית דִּין הֲרֵי זֶה מְגָרֵעַ מִפִּדְיוֹנוֹ וְיוֹצֵא. כֵּיצַד. הֲרֵי שֶׁמְּכָרוּהוּ בְּשִׁשִּׁים דִּינָרִים וְעָבַד אַרְבַּע שָׁנִים וּמָצְאָה יָדוֹ הֲרֵי זֶה נוֹתֵן עֶשְׂרִים דִּינָרִים וְיֵצֵא לְחֵרוּת. וְכֵן אִם מָכַר עַצְמוֹ בְּאַרְבָּעִים דִּינָרִין לְעֶשֶׂר שָׁנִים הֲרֵי זֶה מְגָרֵעַ אַרְבָּעָה דִּינָרִין לְכָל שָׁנָה שֶׁעָבַד וְנוֹתֵן הַנִּשְׁאָר כֶּסֶף אוֹ שְׁוֵה כֶּסֶף וְיוֹצֵא. וְכֵן הַנִּמְכָּר לְעַכּוּ\"ם מְחַשֵּׁב הַדָּמִים לְפִי הַשָּׁנִים הַנִּשְׁאָרוֹת עַד שְׁנַת הַיּוֹבֵל שֶׁנֶּאֱמַר (ויקרא כה נ) \"וְחִשַּׁב עִם קֹנֵהוּ מִשְּׁנַת הִמָּכְרוֹ לוֹ עַד שְׁנַת הַיֹּבֵל\". כֵּיצַד. מָכַר עַצְמוֹ בְּמֵאָה וְנִשְׁאַר לַיּוֹבֵל מִשְּׁנַת מְכִירָה עֶשֶׂר שָׁנִים מְחַשֵּׁב עֲשָׂרָה לְכָל שָׁנָה שֶׁעָבַד וְגוֹרֵעַ הַדָּמִים וּמֵשִׁיב הַשְּׁאָר כֶּסֶף לֹא תְּבוּאָה וְלֹא כֵּלִים שֶׁנֶּאֱמַר (ויקרא כה נ) \"כֶּסֶף מִמְכָּרוֹ\" בְּכֶסֶף הוּא נִגְאָל מִיַּד הָעַכּוּ\"ם וְאֵינוֹ נִגְאָל בִּשְׁוֵה כֶּסֶף:","כָּל עֶבֶד עִבְרִי אוֹ עִבְרִיָּה שֶׁיָּצָא בְּגִרְעוֹן כֶּסֶף וְהִבְרִיא וְהוֹסִיפוּ דָּמָיו אוֹ נִשְׁחַף וּפָחֲתוּ דָּמָיו מְחַשְּׁבִין לוֹ לְהָקֵל עָלָיו. כֵּיצַד. הֲרֵי שֶׁנִּמְכַּר בְּמֵאָה וַהֲרֵי הוּא עַתָּה שָׁוֶה מָאתַיִם אֵינוֹ מְחַשֵּׁב עִם אֲדוֹנָיו אֶלָּא לְפִי מֵאָה. נִמְכַּר בְּמָאתַיִם וַהֲרֵי הוּא שָׁוֶה מֵאָה מְחַשֵּׁב עִמּוֹ עַל פִּי הַשָּׁנִים הַנּוֹתָרוֹת לְפִי מֵאָה:","הַנִּמְכָּר לְעַכּוּ\"ם הוֹאִיל וְיֵשׁ לִגְאל עַצְמוֹ לַחֲצָאִין כְּמוֹ שֶׁבֵּאַרְנוּ פְּעָמִים יִהְיֶה לְהָקֵל וּפְעָמִים לְהַחְמִיר. כֵּיצַד לְהָקֵל. קָנָה אוֹתוֹ בְּמָאתַיִם וְנִשְׁחַף וַהֲרֵי הוּא עַתָּה שָׁוֶה מֵאָה וְנָתַן לוֹ חֲמִשִּׁים חֲצִי דָּמָיו וְהִבְרִיא וַהֲרֵי הוּא שָׁוֶה מָאתַיִם נוֹתֵן לוֹ מֵאָה שֶׁהֵן חֲצִי דָּמָיו הַנִּשְׁאָר וְיָצָא. כֵּיצַד לְהַחְמִיר. קָנָה אוֹתוֹ בְּמָאתַיִם וְנָתַן לוֹ חֲצִי דָּמָיו שֶׁהֵן מֵאָה וְנִשְׁחַף וַהֲרֵי עַתָּה שָׁוֶה מֵאָה נוֹתֵן לוֹ חֲמִשִּׁים שֶׁהֵן דְּמֵי חֶצְיוֹ הַנִּשְׁאָר וְנִמְצָא שֶׁנָּתַן מֵאָה וַחֲמִשִּׁים אַף עַל פִּי שֶׁהוּא עַתָּה שָׁוֶה מֵאָה:","הָרַב שֶׁמָּחַל לָעֶבֶד עַל הַכֶּסֶף שֶׁנִּשְׁאַר לוֹ לַעֲבֹד כְּנֶגְדּוֹ אֵינוֹ מָחוּל לוֹ עַד שֶׁיִּכְתֹּב לוֹ שְׁטַר שִׁחְרוּר. כֵּיצַד. הֲרֵי שֶׁקָּנָהוּ בְּשִׁשִּׁים וְעָבַד שָׁנָה אוֹ שְׁנָתַיִם וְאָמַר לוֹ שְׁאָר הַדָּמִים מְחוּלִין לְךָ לֵךְ לְדַרְכְּךָ לֹא נִפְטַר מִשִּׁעְבּוּדוֹ עַד שֶׁיִּכְתֹּב לוֹ שְׁטָר:","אָדוֹן שֶׁמֵּת אִם הִנִּיחַ בֶּן זָכָר הֲרֵי הָעֶבֶד עוֹבֵד הַבֵּן עַד סוֹף הַשֵּׁשׁ אוֹ עַד סוֹף הַשָּׁנִים שֶׁמָּכַר עַצְמוֹ לָהֶן אוֹ עַד שֶׁיִּפְגַּע בּוֹ יוֹבֵל אוֹ עַד שֶׁיְּגַרֵעַ פִּדְיוֹנוֹ וְיִתֵּן הַשְּׁאָר. אֲבָל אִם לֹא הִנִּיחַ בֶּן זָכָר הֲרֵי זֶה יֵצֵא לְחֵרוּת וְאֵינוֹ עוֹבֵד לֹא אֶת הַבַּת וְלֹא אֶת הָאָח וְאֵין צָרִיךְ לוֹמַר שֶׁאֵינוֹ עוֹבֵד שְׁאָר הַיּוֹרְשִׁין. וְהַנִּמְכָּר לְגֵר צֶדֶק אוֹ לְעַכּוּ\"ם אֲפִלּוּ הַבֵּן אֵינוֹ עוֹבֵד אֶלָּא כֵּיוָן שֶׁמֵּת הָאָדוֹן יֵצֵא לְחֵרוּת. נִמְצֵאתָ אוֹמֵר שֶׁעֶבֶד עִבְרִי נִקְנֶה בְּכֶסֶף אוֹ בִּשְׁטָר וְקוֹנֶה אֶת עַצְמוֹ בַּחֲמִשָּׁה דְּבָרִים. בְּשָׁנִים אוֹ בְּיוֹבֵל אוֹ בְּגִרְעוֹן כֶּסֶף אוֹ בִּשְׁטַר שִׁחְרוּר אוֹ בְּמִיתַת אָדוֹן בְּלֹא בֵּן וּבְעַכּוּ\"ם אוֹ בְּגֵר אֲפִלּוּ הִנִּיחַ בֵּן. מִצְוָה לוֹמַר לוֹ צֵא בִּשְׁעַת יְצִיאָתוֹ. אַף עַל פִּי שֶׁלֹּא אָמַר לוֹ הֲרֵי הוּא יוֹצֵא בְּחִנָּם. וְאֵינוֹ צָרִיךְ שְׁטָר. אֲפִלּוּ חָלָה וְהוֹצִיא רַבּוֹ עָלָיו הוֹצָאוֹת הַרְבֵּה אֵינוֹ חַיָּב לוֹ כְּלוּם שֶׁנֶּאֱמַר (שמות כא ב) \"יֵצֵא לַחָפְשִׁי חִנָּם\":"],"Mishneh Torah, Tefillin, Mezuzah and the Torah Scroll 1":["אַרְבַּע פָּרָשִׁיּוֹת אֵלּוּ. שֶׁהֵן (שמות יג א) ״קַדֶּשׁ לִי״. (שמות יג יא) ״וְהָיָה כִי יְבִיאֲךָ יְיָ׳‎״ שֶׁבְּסֵפֶר וְאֵלֶּה שְׁמוֹת. וּ(דברים ו ד) ״שְׁמַע״. (דברים יא יג) ״וְהָיָה אִם שָׁמוֹעַ״. הֵן שֶׁנִּכְתָּבוֹת בִּפְנֵי עַצְמָן וּמְחַפִּין אוֹתָן בְּעוֹר וְנִקְרָאִין תְּפִלִּין וּמַנִּיחִין אוֹתָן עַל הָרֹאשׁ וְקוֹשְׁרִין אוֹתָן עַל הַיָּד. וַאֲפִלּוּ קוֹצוֹ שֶׁל אוֹת אַחַת מֵאַרְבַּע פָּרָשִׁיּוֹת אֵלּוּ מְעַכֵּב אֶת כֻּלָּן מִן הַתּוֹרָה עַד שֶׁיִּהְיוּ נִכְתָּבוֹת שְׁלֵמוֹת כְּתִקּוּנָן:","וְכֵן שְׁתֵּי פָּרָשִׁיּוֹת שֶׁבַּמְּזוּזָה שֶׁהֵן (דברים ו ד) ״שְׁמַע״ (דברים יא יג) ״וְהָיָה אִם שָׁמוֹעַ״ אֲפִלּוּ אוֹת אַחַת מִשְּׁתֵּי הַפָּרָשִׁיּוֹת אִם חָסֵר קוֹצוֹ מְעַכֵּב מִן הַתּוֹרָה עַד שֶׁיִּהְיוּ שְׁתֵּיהֶן נִכְתָּבוֹת שְׁלֵמוֹת. וְכֵן סֵפֶר תּוֹרָה שֶׁחִסֵּר אֲפִלּוּ אוֹת אַחַת פָּסוּל:","עֲשָׂרָה דְּבָרִים יֵשׁ בַּתְּפִלִּין כֻּלָּן הֲלָכָה לְמשֶׁה מִסִּינַי וְכֻלָּן מְעַכְּבִין. לְפִיכָךְ אִם שִׁנָּה בְּאַחַת מֵהֶן הֲרֵי הַתְּפִלִּין פְּסוּלוֹת. שְׁנַיִם הֵן בִּכְתִיבָתָן וּשְׁמוֹנָה בְּחִפּוּיָן וּקְשִׁירַת רְצוּעוֹתֵיהֶן. וְאֵלּוּ הֵן הַשְּׁנַיִם שֶׁבִּכְתִיבָתָן. שֶׁכּוֹתְבִין אוֹתָן בִּדְיוֹ וְשֶׁיִּהְיוּ נִכְתָּבִין עַל הַקְּלָף:","כֵּיצַד מַעֲשֵׂה הַדְּיוֹ. מְקַבְּצִין הֶעָשָׁן שֶׁל שְׁמָנִים אוֹ שֶׁל זֶפֶת וְשֶׁל שַׁעֲוָה וְכַיּוֹצֵא בָּהֶן וְגוֹבְלִין אוֹתָן בִּשְׂרַף הָאִילָן וּבִמְעַט דְּבַשׁ וְלוֹתְתִין אוֹתוֹ הַרְבֵּה וְדָכִין אוֹתוֹ עַד שֶׁיֵּעָשֶׂה רְקִיקִין וּמְיַבְּשִׁין אוֹתוֹ וּמַצְנִיעִין אוֹתוֹ. וּבִשְׁעַת כְּתִיבָה שׁוֹרֵהוּ בְּמֵי עֲפָצִים וְכַיּוֹצֵא בּוֹ וְכוֹתֵב בּוֹ. שֶׁאִם תִּמְחָקֶנּוּ יִהְיֶה נִמְחָק. וְזֶהוּ הַדְּיוֹ שֶׁמִּצְוָה מִן הַמֻּבְחָר לִכְתֹּב בּוֹ סְפָרִים תְּפִלִּין וּמְזוּזוֹת. וְאִם כָּתַב שְׁלָשְׁתָּן בְּמֵי עֲפְצָא וְקַנְקַנְתּוֹם שֶׁהוּא עוֹמֵד וְאֵינוֹ נִמְחָק כְּשֵׁרִיִם:","אִם כֵּן מַה מִּעֲטָה הַהֲלָכָה שֶׁנֶּאֱמַר לְמשֶׁה מִסִּינַי שֶׁיִּהְיוּ כְּתוּבִים בִּדְיוֹ. לְמַעֵט שְׁאָר מִינֵי צִבְעוֹנִין כְּגוֹן הָאָדֹם וְהַיָּרֹק וְכַיּוֹצֵא בָּהֶן. שֶׁאִם כָּתַב בַּסְּפָרִים אוֹ בַּתְּפִלִּין אוֹ בַּמְּזוּזוֹת אֲפִלּוּ אוֹת אַחַת בִּשְׁאָר מִינֵי צִבְעוֹנִין אוֹ בְּזָהָב הֲרֵי אֵלּוּ פְּסוּלִין:","שָׁלֹשׁ עוֹרוֹת הֵן. גְּוִיל וּקְלָף וְדוּכְסוּסְטוּס. כֵּיצַד. לוֹקְחִין עוֹר בְּהֵמָה אוֹ חַיָּה וּמַעֲבִירִין הַשֵּׂעָר מִמֶּנּוּ תְּחִלָּה. וְאַחַר כָּךְ מוֹלְחִין אוֹתוֹ בְּמֶלַח. וְאַחַר כָּךְ מְעַבְּדִין אוֹתוֹ בְּקֶמַח. וְאַחַר כָּךְ בָּעֲפְצָא וְכַיּוֹצֵא בּוֹ מִדְּבָרִים שֶׁמְּכַוְּצִין אֶת הָעוֹר וּמְחַזְּקִין אוֹתוֹ. וְזֶה הוּא הַנִּקְרָא גְּוִיל:","וְאִם לָקְחוּ הָעוֹר אַחַר שֶׁהֶעֱבִירוּ שְׂעָרוֹ וְחִלְּקוּ אוֹתוֹ בְּעָבְיוֹ לִשְׁנַיִם כְּמוֹ שֶׁהָעַבְּדָנִין עוֹשִׂין עַד שֶׁיִּהְיוּ שְׁנֵי עוֹרוֹת. אֶחָד דַּק הוּא שֶׁמִּמּוּל הַשֵּׂעָר וְאֶחָד עָבֶה וְהוּא שֶׁמִּמּוּל הַבָּשָׂר וְעִבְּדוּ אוֹתוֹ בְּמֶלַח וְאַחַר כָּךְ בְּקֶמַח וְאַחַר כָּךְ בָּעֲפְצָא וְכַיּוֹצֵא בּוֹ. זֶה הַחֵלֶק שֶׁמִּמּוּל הַשֵּׂעָר נִקְרָא דּוּכְסוּסְטוּס וְזֶה שֶׁמִּמּוּל הַבָּשָׂר נִקְרָא קְלָף:","הֲלָכָה לְמשֶׁה מִסִּינַי שֶׁיִּהְיוּ כּוֹתְבִין סֵפֶר תּוֹרָה עַל הַגְּוִיל וְכוֹתְבִין בִּמְקוֹם הַשֵּׂעָר. וְשֶׁיִּהְיוּ כּוֹתְבִין הַתְּפִלִּין עַל הַקְּלָף וְכוֹתְבִין בִּמְקוֹם הַבָּשָׂר. וְשֶׁיִּהְיוּ כּוֹתְבִין הַמְּזוּזָה עַל דּוּכְסוּסְטוּס וְכוֹתְבִין בִּמְקוֹם הַשֵּׂעָר. וְכָל הַכּוֹתֵב עַל הַקְּלָף בִּמְקוֹם שֵׂעָר אוֹ שֶׁכָּתַב בִּגְוִיל וּבְדוּכְסוּסְטוּס בִּמְקוֹם בָּשָׂר פָּסוּל:","אַף עַל פִּי שֶׁכָּךְ הִיא הֲלָכָה לְמשֶׁה מִסִּינַי אִם כָּתַב סֵפֶר תּוֹרָה עַל הַקְּלָף כָּשֵׁר. וְלֹא נֶאֱמַר גְּוִיל אֶלָּא לְמַעֵט דּוּכְסוּסְטוּס שֶׁאִם כָּתַב עָלָיו הַסֵּפֶר פָּסוּל. וְכֵן אִם כָּתַב אֶת הַמְּזוּזָה עַל הַקְּלָף אוֹ עַל הַגְּוִיל כָּשֵׁר. לֹא אָמְרוּ עַל דּוּכְסוּסְטוּס אֶלָּא לְמִצְוָה:","אֵין כּוֹתְבִין סְפָרִים תְּפִלִּין וּמְזוּזוֹת עַל גַּבֵּי עוֹר בְּהֵמָה טְמֵאָה וְעוֹף וְחַיָּה הַטְּמֵאִים. אֲבָל כּוֹתְבִין עַל גַּבֵּי עוֹר בְּהֵמָה וְחַיָּה וָעוֹף טְהוֹרִים וַאֲפִלּוּ נְבֵלוֹת וּטְרֵפוֹת שֶׁלָּהֶן. וְאֵין כּוֹתְבִין עַל גַּבֵּי עוֹר הַדָּג הַטָּהוֹר מִפְּנֵי הַזֻּהֲמָא. שֶׁאֵין הַזֻּהֲמָא פּוֹסֶקֶת בְּעִבּוּדָהּ:","גְּוִיל שֶׁל סֵפֶר תּוֹרָה וּקְלָף שֶׁל תְּפִלִּין אוֹ שֶׁל סֵפֶר תּוֹרָה צָרִיךְ לְעַבֵּד אוֹתָן לִשְׁמָן. וְאִם עִבְּדָן שֶׁלֹּא לִשְׁמָן פְּסוּלִין. לְפִיכָךְ אִם עִבְּדָן הַכּוּתִי פְּסוּלִין אַף עַל פִּי שֶׁאָמַרְנוּ לוֹ לַכּוּתִי לְעַבֵּד עוֹר זֶה לְשֵׁם הַסֵּפֶר אוֹ לְשֵׁם הַתְּפִלִּין פְּסוּלִין. שֶׁהַכּוּתִי עַל דַּעַת עַצְמוֹ הוּא עוֹשֶׂה לֹא עַל דַּעַת הַשּׂוֹכֵר אוֹתוֹ. לְפִיכָךְ כָּל דָּבָר שֶׁצָּרִיךְ מַעֲשֶׂה לִשְׁמוֹ אִם עֲשָׂהוּ הַכּוּתִי פָּסוּל. וּמְזוּזָה אֵינָהּ צְרִיכָה הַעֲבָדָה לִשְׁמָהּ:","הֲלָכָה לְמשֶׁה מִסִּינַי שֶׁאֵין כּוֹתְבִין סֵפֶר תּוֹרָה וְלֹא מְזוּזָה אֶלָּא בְּשִׂרְטוּט. אֲבָל תְּפִלִּין אֵינָן צְרִיכִין שִׂרְטוּט לְפִי שֶׁהֵן מְחֻפִּין. וּמֻתָּר לִכְתֹּב תְּפִלִּין וּמְזוּזָה שֶׁלֹּא מִן הַכְּתָב שֶׁהַכּל גּוֹרְסִין פָּרָשִׁיּוֹת אֵלּוּ. אֲבָל סֵפֶר תּוֹרָה אָסוּר לִכְתֹּב אֲפִלּוּ אוֹת אַחַת שֶׁלֹּא מִן הַכְּתָב:","סֵפֶר תּוֹרָה תְּפִלִּין וּמְזוּזוֹת שֶׁכְּתָבָן אֶפִּיקוֹרוֹס יִשָּׂרְפוּ. כְּתָבָן כּוּתִי אוֹ יִשְׂרָאֵל מוּמָר אוֹ מוֹסֵר בְּיַד אַנָּס אוֹ עֶבֶד אוֹ אִשָּׁה אוֹ קָטָן הֲרֵי אֵלּוּ פְּסוּלִין וְיִגָּנְזוּ שֶׁנֶּאֱמַר (דברים ו ח) ״וּקְשַׁרְתָּם״ (דברים ו ט) ״וּכְתַבְתָּם״ כָּל שֶׁמֻּזְהָר עַל הַקְּשִׁירָה וּמַאֲמִין בָּהּ הוּא שֶׁכּוֹתֵב. נִמְצְאוּ בְּיַד אֶפִּיקוֹרוֹס וְאֵינוֹ יוֹדֵעַ מִי כְּתָבָן יִגָּנְזוּ. נִמְצְאוּ בְּיַד כּוּתִי כְּשֵׁרִים. וְאֵין לוֹקְחִין סְפָרִים תְּפִלִּין וּמְזוּזוֹת מִן הַכּוּתִים בְּיוֹתֵר עַל דְּמֵיהֶם שֶׁלֹּא לְהַרְגִּיל אוֹתָן לְגָנְבָן וּלְגָזְלָן:","סֵפֶר תּוֹרָה תְּפִלִּין וּמְזוּזוֹת שֶׁכְּתָבָן עַל גַּבֵּי עוֹר בְּהֵמָה חַיָּה וְעוֹף הַטְּמֵאִין אוֹ עַל גַּבֵּי עוֹרוֹת שֶׁאֵינָם מְעֻבָּדִין אוֹ שֶׁכָּתַב סֵפֶר תּוֹרָה וּתְפִלִּין עַל עוֹר שֶׁלֹּא עִבְּדָן לִשְׁמָן הֲרֵי אֵלּוּ פְּסוּלִין:","הַכּוֹתֵב סֵפֶר תּוֹרָה אוֹ תְּפִלִּין אוֹ מְזוּזָה וּבִשְׁעַת כְּתִיבָה לֹא הָיְתָה לוֹ כַּוָּנָה וְכָתַב אַזְכָּרָה מִן הָאַזְכָּרוֹת שֶׁבָּהֶן שֶׁלֹּא לִשְׁמָן פְּסוּלִין. לְפִיכָךְ הַכּוֹתֵב אֶת הַשֵּׁם אֲפִלּוּ מֶלֶךְ יִשְׂרָאֵל שׁוֹאֵל בִּשְׁלוֹמוֹ לֹא יְשִׁיבֶנּוּ. הָיָה כּוֹתֵב שְׁנַיִם אוֹ שְׁלֹשָׁה שֵׁמוֹת הֲרֵי זֶה מַפְסִיק בֵּינֵיהֶם וּמֵשִׁיב:","הַטּוֹבֵל אֶת הַקֻּלְמוֹס לִכְתֹּב אֶת הַשֵּׁם לֹא יַתְחִיל מֵאוֹת הַשֵּׁם אֲבָל מַתְחִיל הוּא מֵאוֹת שֶׁלְּפָנָיו. שָׁכַח לִכְתֹּב אֶת הַשֵּׁם כֻּלּוֹ תּוֹלֶה אוֹתוֹ בֵּין הַשִּׁטּוֹת. אֲבָל מִקְצָת הַשֵּׁם בַּשִּׁטָּה וּמִקְצָתוֹ תָּלוּי פָּסוּל. וּבִשְׁאָר הַתֵּבוֹת אִם שָׁכַח כּוֹתֵב מִקְצָת הַתֵּבָה בַּשִּׁטָּה וּמִקְצָתָהּ לְמַעְלָה. בַּמֶּה דְּבָרִים אֲמוּרִים בְּסֵפֶר תּוֹרָה אֲבָל בִּמְזוּזָה וּתְפִלִּין אֵין תּוֹלִין בָּהֶן אֲפִלּוּ אוֹת אַחַת. אֶלָּא אִם שָׁכַח אֲפִלּוּ אוֹת אַחַת גּוֹנֵז מַה שֶּׁכָּתַב וְכוֹתֵב אַחֶרֶת. וּמֻתָּר לִכְתֹּב אֶת הַשֵּׁם עַל מְקוֹם הַגֶּרֶד וְעַל מְקוֹם הַמַּחַק בְּכֻלָּן:","כּוֹתְבֵי סְפָרִים תְּפִלִּין וּמְזוּזוֹת אָסוּר לָהֶם לַהֲפֹךְ הַיְרִיעָה עַל פָּנֶיהָ אֶלָּא פּוֹרֵשׂ עָלֶיהָ בֶּגֶד אוֹ כּוֹפְלָהּ:","סֵפֶר תּוֹרָה תְּפִלִּין וּמְזוּזָה שֶׁאָמַר הַסּוֹפֵר אַחַר שֶׁיָּצְאוּ מִתַּחַת יָדוֹ לֹא כָּתַבְתִּי הָאַזְכָּרוֹת שֶׁבָּהֶן לִשְׁמָן אֵינוֹ נֶאֱמָן לְפָסְלָן אֲבָל נֶאֱמָן הוּא לְהַפְסִיד כָּל שְׂכָרוֹ. וְלָמָּה אֵינוֹ נֶאֱמָן לְפָסְלָן שֶׁמָּא לֹא נִתְכַּוֵּן אֶלָּא לְהַפְסִיד עַל הַלּוֹקֵחַ אוֹ עַל זֶה שֶׁשְּׂכָרוֹ וְדוֹמֶה שֶׁאֵינוֹ מַפְסִיד בַּאֲמִירָה זוֹ אֶלָּא שְׂכַר הָאַזְכָּרוֹת. לְפִיכָךְ אִם אָמַר סֵפֶר תּוֹרָה זֶה אוֹ תְּפִלִּין אֵלּוּ עוֹרוֹת שֶׁלָּהֶן אֵינָם מְעֻבָּדוֹת לִשְׁמָן מִתּוֹךְ שֶׁנֶּאֱמָן לְהַפְסִיד שְׂכָרוֹ נֶאֱמָן לְפָסְלָן. שֶׁהֲרֵי הַכּל יוֹדְעִים שֶׁאִם אֵין הָעוֹרוֹת מְעֻבָּדִים לִשְׁמָן אֵין שָׂכָר לוֹ כְּלָל:","אֵין כּוֹתְבִין תְּפִלִּין וּמְזוּזָה אֶלָּא בִּכְתָב אַשּׁוּרִית. וְהִתִּירוּ בַּסְּפָרִים לִכְתֹּב אַף בִּיוָנִי בִּלְבַד. וּכְבָר נִשְׁקַע יְוָנִי מִן הָעוֹלָם וְנִשְׁתַּבֵּשׁ וְאָבַד לְפִיכָךְ אֵין כּוֹתְבִין הַיּוֹם שְׁלָשְׁתָּן אֶלָּא אַשּׁוּרִית. וְצָרִיךְ לְהִזָּהֵר בִּכְתִיבָתָן כְּדֵי שֶׁלֹּא תִּדְבַּק אוֹת בְּאוֹת שֶׁכָּל אוֹת שֶׁאֵין הָעוֹר מַקִּיף לָהּ מֵאַרְבַּע רוּחוֹתֶיהָ פָּסוּל. וְכָל אוֹת שֶׁאֵין הַתִּינוֹק שֶׁאֵינוֹ לֹא חָכָם וְלֹא סָכָל יָכוֹל לִקְרוֹתָהּ פָּסוּל. לְפִיכָךְ צָרִיךְ לְהִזָּהֵר בְּצוּרַת הָאוֹתִיּוֹת שֶׁלֹּא תִּדְמֶה הַיּוּ״ד לְוָא״ו וְלֹא וָא״ו לְיוּ״ד וְלֹא כָּ״ף לְבֵי״ת וְלֹא בֵּי״ת לְכָ״ף וְלֹא דָּלֶ״ת לְרֵי״שׁ וְלֹא רֵי״שׁ לְדָלֶ״ת וְכֵן כָּל כַּיּוֹצֵא בָּזֶה עַד שֶׁיָּרוּץ כָּל הַקּוֹרֵא בָּהֶן:","עוֹר שֶׁהָיָה נָקוּב לֹא יִכְתֹּב עַל גַּבֵּי הַנֶּקֶב. וְכָל נֶקֶב שֶׁהַדְּיוֹ עוֹבֶרֶת עָלָיו אֵינוֹ נֶקֶב וּמֻתָּר לִכְתֹּב עָלָיו. לְפִיכָךְ מֻתָּר לִכְתֹּב עַל גַּבֵּי עוֹר הָעוֹף שֶׁנִּתְעַבֵּד. נִקַּב הָעוֹר אַחַר שֶׁנִּכְתַּב אִם נִקַּב בְּתוֹךְ הָאוֹת כְּגוֹן תּוֹךְ הֵ״א אוֹ תּוֹךְ מֵ״ם וְכֵן בִּשְׁאָר אוֹתִיּוֹת כָּשֵׁר. נִקַּב בַּיָּרֵךְ שֶׁל אוֹת עַד שֶׁנִּפְסְקָה. אִם נִשְׁתַּיֵּר מִמֶּנָּה מְלֹא אוֹת קְטַנָּה כָּשֵׁר וְהוּא שֶׁלֹּא תִּדְמֶה לְאוֹת אַחֶרֶת. וְאִם לֹא נִשְׁתַּיֵּר מִמֶּנָּה מְלֹא אוֹת קְטַנָּה פְּסוּלָה:"],"Mishneh Torah, Testimony 11":["מִי שֶׁאֵינוֹ לֹא בְּמִקְרָא וְלֹא בְּמִשְׁנָה וְלֹא בְּדֶרֶךְ אֶרֶץ הֲרֵי זֶה בְּחֶזְקַת רָשָׁע וּפָסוּל לְעֵדוּת מִדִּבְרֵיהֶם. שֶׁכָּל מִי שֶׁיָּרַד עַד כָּךְ חֲזָקָה שֶׁהוּא עוֹבֵר עַל רֹב הָעֲבֵרוֹת שֶׁיָּבוֹאוּ לְיָדוֹ:","לְפִיכָךְ אֵין מוֹסְרִין עֵדוּת לְעַם הָאָרֶץ וְאֵין מְקַבְּלִין מִמֶּנּוּ עֵדוּת אֶלָּא אִם כֵּן הֻחְזַק שֶׁהוּא עוֹסֵק בְּמִצְוֹת וּבִגְמִילוּת חֲסָדִים וְנוֹהֵג בְּדַרְכֵי הַיְשָׁרִים וְיֵשׁ בּוֹ דֶּרֶךְ אֶרֶץ מְקַבְּלִין עֵדוּתוֹ אַף עַל פִּי שֶׁהוּא עַם הָאָרֶץ וְאֵינוֹ לֹא בְּמִקְרָא וְלֹא בְּמִשְׁנָה:","נִמְצֵאתָ אוֹמֵר כָּל תַּלְמִיד חָכָם בְּחֶזְקַת כָּשֵׁר עַד שֶׁיִּפָּסֵל. כָּל עַם הָאָרֶץ בְּחֶזְקַת שֶׁהוּא פָּסוּל עַד שֶׁיֻּחְזַק שֶׁהוּא הוֹלֵךְ בְּדַרְכֵי הַיְשָׁרִים:","וְכָל מִי שֶׁיְּקַבֵּל עֵדוּת עַם הָאָרֶץ טֶרֶם שֶׁתִּהְיֶה לוֹ חֲזָקָה זוֹ אוֹ קֹדֶם שֶׁיָּבוֹאוּ עֵדִים וְיָעִידוּ שֶׁהוּא נוֹהֵג בְּמִצְוֹת וּבְדֶרֶךְ אֶרֶץ הֲרֵי זֶה הֶדְיוֹט וְעָתִיד לִתֵּן אֶת הַדִּין שֶׁהֲרֵי מְאַבֵּד מָמוֹנָן שֶׁל יִשְׂרָאֵל עַל פִּי רְשָׁעִים:","וְכֵן הַבְּזוּיִין פְּסוּלִין לְעֵדוּת מִדִּבְרֵיהֶם וְהֵם הָאֲנָשִׁים שֶׁהוֹלְכִין וְאוֹכְלִין בַּשּׁוּק בִּפְנֵי כָּל הָעָם וּכְגוֹן אֵלּוּ שֶׁהוֹלְכִין עֲרוּמִים בַּשּׁוּק בְּעֵת שֶׁהֵן עוֹסְקִין בִּמְלָאכָה מְנֻוֶלֶת וְכַיּוֹצֵא בְּאֵלּוּ שֶׁאֵין מַקְפִּידִין עַל הַבּשֶׁת. שֶׁכָּל אֵלּוּ חֲשׁוּבִין כְּכֶלֶב וְאֵין מַקְפִּידִין עַל עֵדוּת שֶׁקֶר. וּמִכְּלַל אֵלּוּ הָאוֹכְלִין צְדָקָה שֶׁל עַכּוּ\"ם בְּפַרְהֶסְיָא אַף עַל פִּי שֶׁאֶפְשָׁר לָהֶן שֶׁיִּזּוֹנוּ בְּצִנְעָה מְבַזִּים עַצְמָן וְאֵינָן חוֹשְׁשִׁין. כָּל אֵלּוּ פְּסוּלִין מִדִּבְרֵיהֶם:","מַה בֵּין פָּסוּל לְעֵדוּת מִן הַתּוֹרָה לְפָסוּל מִדִּבְרֵיהֶם. שֶׁהַפָּסוּל מִן הַתּוֹרָה שֶׁהֵעִיד עֵדוּתוֹ בְּטֵלָה אַף עַל פִּי שֶׁלֹּא הִכְרִיזוּ עָלָיו בְּבָתֵּי כְּנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת וְהַפָּסוּל מִדִּבְרֵיהֶם צָרִיךְ הַכְרָזָה. לְפִיכָךְ כָּל עֵדוּת שֶׁהֵעִיד קֹדֶם שֶׁהִכְרִיזוּ עָלָיו מְקַבְּלִין אוֹתָה כְּדֵי שֶׁלֹּא לְאַבֵּד זְכוּת הָעָם שֶׁהֲרֵי לֹא יָדְעוּ שֶׁהוּא פָּסוּל וְאֵין פְּסוּלוֹ אֶלָּא מִדִּבְרֵיהֶם:","עֵד אֶחָד נֶאֱמָן בְּאִסּוּרִין אַף עַל פִּי שֶׁהוּא פָּסוּל לִשְׁאָר עֵדוּיוֹת. שֶׁהֲרֵי רָשָׁע בַּעֲבֵרָה שֶׁשָּׁחַט שְׁחִיטָתוֹ כְּשֵׁרָה וְנֶאֱמָן לוֹמַר כַּהֲלָכָה שָׁחַטְתִּי. אֲבָל הֶחָשׁוּד עַל דָּבָר אֵינוֹ נֶאֱמָן עַל שֶׁלּוֹ אֲבָל נֶאֱמָן הוּא עַל אֲחֵרִים:","לְפִיכָךְ הֶחָשׁוּד עַל דָּבָר יֵשׁ לוֹ לָדוּן בּוֹ וּלְהָעִיד בּוֹ לַאֲחֵרִים. חֲזָקָה אֵין אָדָם חוֹטֵא כְּדֵי שֶׁיֵּהָנוּ אֲחֵרִים. כֵּיצַד. נֶאֱמָן עַם הָאָרֶץ לוֹמַר פֵּרוֹת פְּלוֹנִי מְתֻקָּנִים הֵם. וְנֶאֱמָן הַנֶּחְשָׁד לִמְכֹּר בְּשַׂר בְּכוֹר לוֹמַר בָּשָׂר זֶה שֶׁמּוֹכֵר פְּלוֹנִי חֻלִּין הוּא. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה מִשְּׁאָר הָאִסּוּרִין. לְפִי שֶׁאֵימַת הָאִסּוּרִים עַל הָרְשָׁעִים וְאֵין אֵימַת הַמָּמוֹן עֲלֵיהֶן:","מַלְכֵי יִשְׂרָאֵל לֹא מְעִידִין וְלֹא מְעִידִין עֲלֵיהֶן מִפְּנֵי שֶׁהֵן אַלָּמִים בַּעֲלֵי זְרוֹעַ וְאֵינָן נִכְנָעִין תַּחַת עֹל הַדַּיָּנִים. אֲבָל כֹּהֵן גָּדוֹל מְעִידִין עָלָיו וּמֵעִיד הוּא לַמֶּלֶךְ בְּבֵית דִּין הַגָּדוֹל כְּמוֹ שֶׁבֵּאַרְנוּ:","הַמּוֹסְרִין וְהָאֶפִּיקוֹרוֹסִין וְהַמּוּמָרִים לֹא הִצְרִיכוּ חֲכָמִים לִמְנוֹתָן בִּכְלַל פְּסוּלֵי עֵדוּת שֶׁלֹּא מָנוּ אֶלָּא רִשְׁעֵי יִשְׂרָאֵל. אֲבָל אֵלּוּ הַמּוֹרְדִין הַכּוֹפְרִין פְּחוּתִין הֵן מִן הָעַכּוּ\"ם. שֶׁהָעַכּוּ\"ם לֹא מַעֲלִין וְלֹא מוֹרִידִין וְיֵשׁ לַחֲסִידֵיהֶן חֵלֶק לָעוֹלָם הַבָּא. וְאֵלּוּ מוֹרִידִין וְלֹא מַעֲלִין וְאֵין לָהֶן חֵלֶק לָעוֹלָם הַבָּא:"],"Mishneh Torah, Testimony 22":["שְׁתֵּי כִּתֵּי עֵדִים הַמַּכְחִישׁוֹת זוֹ אֶת זוֹ שֶׁבָּא עֵד אֶחָד מִכַּת זוֹ וְעֵד אֶחָד מִכַּת זוֹ וְהֵעִידוּ בְּעֵדוּת אַחֶרֶת אֵין כָּאן עֵדוּת. שֶׁהֲרֵי בְּוַדַּאי אֶחָד מֵהֶן שֶׁקֶר וְאֵין יָדוּעַ מִי הוּא מִשְּׁנֵיהֶן. בָּאָה כַּת זוֹ בִּפְנֵי עַצְמָהּ וְהֵעִידָה עֵדוּת וּבָאָה כַּת זוֹ וְהֵעִידָה עֵדוּת אַחֶרֶת בִּפְנֵי עַצְמָהּ מְקַבְּלִין כָּל אַחַת מֵהֶן בִּפְנֵי עַצְמָהּ:","רְאוּבֵן שֶׁהוֹצִיא עַל שִׁמְעוֹן שְׁנֵי שְׁטָרוֹת אֶחָד בְּמָנֶה וְאֶחָד בְּמָאתַיִם וְכָפַר שִׁמְעוֹן בִּשְׁנֵי הַשְּׁטָרוֹת וְעֵדֵי שְׁטָר זֶה כַּת אַחַת מֵאוֹתָן הַשְּׁנַיִם שֶׁהִכְחִישׁוּ זוֹ אֶת זוֹ. וְעֵדֵי הַשְּׁטָר הַשֵּׁנִי הַכַּת הַשְּׁנִיָּה. הֲרֵי שִׁמְעוֹן מְשַׁלֵּם מָנֶה שֶׁיַּד בַּעַל הַשְּׁטָר עַל הַתַּחְתּוֹנָה וְיִשָּׁבַע עַל הַשְּׁאָר. יֵרָאֶה לִי שֶׁשְּׁבוּעָה זוֹ שֶׁיִּשָּׁבַע עַל הַשְּׁאָר בִּנְקִיטַת חֵפֶץ כְּדִין מוֹדֶה בְּמִקְצָת. שֶׁהֲרֵי עָלָיו שְׁנֵי עֵדִים כְּשֵׁרִים מְעִידִין בְּמִקְצָת הַמָּמוֹן שֶׁכָּפַר בְּכֻלּוֹ. וְלֹא תְּהֵא הוֹדָאַת פִּיו גְּדוֹלָה מֵהַעֲדָאַת עֵדִים כְּמוֹ שֶׁבֵּאַרְנוּ:","הוֹצִיא רְאוּבֵן שְׁטָר עַל לֵוִי וְעֵדָיו כַּת אַחַת מִשְּׁתֵּיהֶן. וְהוֹצִיא שִׁמְעוֹן שְׁטָר שֵׁנִי עַל לֵוִי וְעֵדָיו הַכַּת הַשְּׁנִיָּה. וְלֵוִי כּוֹפֵר בִּשְׁנֵיהֶן. הֲרֵי רְאוּבֵן נִשְׁבָּע וְנוֹטֵל וְשִׁמְעוֹן נִשְׁבָּע וְנוֹטֵל שֶׁבְּוַדַּאי אֶחָד מֵהֶן יֵשׁ לוֹ אֶצְלוֹ. וּשְׁבוּעָה זוֹ בְּתַקָּנַת חֲכָמִים כְּדִין חֶנְוָנִי עַל פִּנְקָסוֹ:","הוֹצִיא רְאוּבֵן שְׁטָר עַל שִׁמְעוֹן וְעֵדָיו כַּת אַחַת מֵהֶן וְהוֹצִיא שְׁטָר שֵׁנִי עַל לֵוִי וְעֵדָיו הַכַּת הַשְּׁנִיָּה וְכָל אֶחָד מֵהֶן כּוֹפֵר בּוֹ הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. הוֹאִיל וְאֵין רְאוּבֵן יָכוֹל לְקַיֵּם אֶחָד מִשְּׁנֵי שְׁטָרוֹת הֲרֵי כָּל שְׁטָר מֵהֶן כְּחֶרֶס וּשְׁנֵי הַנִּטְעָנִין נִשְׁבָּעִין הֶסֵּת וְנִפְטָרִין. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁבָּאוּ שְׁתֵּי הַכִּתּוֹת לְהָעִיד כְּאַחַת. אֲבָל כָּל הַמּוֹצִיא שְׁטָר שֶׁיֵּשׁ בּוֹ עֵדוּת כַּת אַחַת מִשְּׁתֵּיהֶן הֲרֵי זֶה גּוֹבֶה בּוֹ. וְאִם הוֹצִיא אַחַר כָּךְ בֵּין הוּא בֵּין אַחֵר שְׁטָר שֶׁיֵּשׁ בּוֹ עֵדוּת הַכַּת הַשְּׁנִיָּה הֲרֵי זֶה גּוֹבֶה בּוֹ בֵּין מִמַּלְוֶה הָרִאשׁוֹן בֵּין מֵאַחֵר. שֶׁהֲרֵי כָּל כַּת מִשְּׁתֵּיהֶן בָּאָה בִּפְנֵי עַצְמָהּ וְהֵעִידָה:","מִי שֶׁהֵבִיא עֵדִים וְנֶחְקְרָה עֵדוּתָן וְהוּזַמּוּ וְחָזַר וְהֵבִיא עֵדִים אֲחֵרִים בְּאוֹתָהּ הַטַּעֲנָה עַצְמָהּ וְהוּזַמּוּ אֲפִלּוּ מֵאָה כַּת. וְאַחַר כָּךְ הֵבִיא עֵדִים אֲחֵרִים בְּאוֹתָהּ הַטַּעֲנָה עַצְמָהּ וְנִמְצֵאת עֵדוּת אֵלּוּ הָאַחֲרוֹנִים מְכֻוֶּנֶת. דָּנִין עַל פִּיהֶן. שֶׁאַף עַל פִּי שֶׁהֻחְזַק זֶה שֶׁטָּעַן טַעֲנָה זוֹ לְהָבִיא עֵדִים שַׁקְרָנִים הֲרֵי לֹא הֻחְזְקוּ אֵלּוּ הָעֵדִים הָאַחֲרוֹנִים שֶׁהֵן מְשַׁקְּרִין. אֲבָל שְׁטָר שֶׁקָּרָא עָלָיו עַרְעָר וְהוּא שֶׁיָּבוֹאוּ שְׁנַיִם וְיֹאמְרוּ מִמֶּנּוּ שָׁאַל לְזַיֵּף לוֹ שְׁטָר זֶה אַף עַל פִּי שֶׁנִּתְקַיֵּם הַשְּׁטָר מֵחוֹתְמָיו אֵין גּוֹבִין בּוֹ לְעוֹלָם. וְיֵרָאֶה לִי שֶׁאִם בָּאוּ עֵדֵי הַשְּׁטָר וְהֵעִידוּ הֵן בְּעַצְמָן עַל כְּתַב יָדָן גּוֹבִין בּוֹ: סְלִיקוּ לְהוּ הִלְכוֹת עֵדוּת בְּסַ\"ד"],"Mishneh Torah, The Chosen Temple 5":["הַר הַבַּיִת וְהוּא הַר הַמּוֹרִיָּה הָיָה חֲמֵשׁ מֵאוֹת אַמָּה עַל חֲמֵשׁ מֵאוֹת אַמָּה וְהָיָה מֻקָּף חוֹמָה. וְכֵפִין עַל גַּבֵּי כֵּפִין הָיוּ בְּנוּיוֹת מִתַּחְתָּיו. מִפְּנֵי אֹהֶל הַטֻּמְאָה. וְכֻלּוֹ הָיָה מְקֹרֶה סְטָיו לְפָנִים מִסְּטָיו:","וַחֲמִשָּׁה שְׁעָרִים הָיוּ לוֹ. אֶחָד מִן הַמַּעֲרָב וְאֶחָד מִן הַמִּזְרָח וְאֶחָד מִן הַצָּפוֹן וּשְׁנַיִם מִן הַדָּרוֹם. רֹחַב כָּל שַׁעַר עֶשֶׂר אַמּוֹת וְגָבְהוֹ עֶשְׂרִים. וְיֵשׁ לָהֶם דַּלְתוֹת:","לְפָנִים מִמֶּנּוּ סוֹרֵג מַקִּיף סְבִיב גָּבְהוֹ עֲשָׂרָה טְפָחִים וּלְפָנִים מִן הַסּוֹרֵג הַחֵיל [גָּבְהוֹ] עֶשֶׂר אַמּוֹת. וְעָלָיו הוּא אוֹמֵר בַּקִּינוֹת (איכה ב ח) \"וַיַּאֲבֶל חֵל וְחוֹמָה\" זוֹ חוֹמַת הָעֲזָרָה:","לְפָנִים מִן הַחֵיל הָעֲזָרָה. וְכָל הָעֲזָרָה הָיְתָה אֹרֶךְ קפ\"ז עַל רֹחַב קל\"ה. וְשִׁבְעָה שְׁעָרִים הָיוּ לָהּ. שְׁלֹשָׁה מִן הַצָּפוֹן הַסְּמוּכִין לַמַּעֲרָב. וּשְׁלֹשָׁה מִן הַדָּרוֹם סְמוּכִין לַמַּעֲרָב. וְאֶחָד בַּמִּזְרָח מְכֻוָּן כְּנֶגֶד בֵּית קֹדֶשׁ הַקָּדָשִׁים בָּאֶמְצַע:","כָּל שַׁעַר מֵהֶן הָיָה רָחְבּוֹ עֶשֶׂר אַמּוֹת וְגָבְהוֹ עֶשְׂרִים אַמָּה. וְהָיוּ לוֹ דְּלָתוֹת מְחֻפּוֹת זָהָב. חוּץ מִשַּׁעַר מִזְרָחִי שֶׁהָיָה מְצֻפֶּה נְחשֶׁת דּוֹמָה לְזָהָב. וְשַׁעַר זֶה הוּא הַנִּקְרָא שַׁעַר הָעֶלְיוֹן וְהוּא שַׁעַר נִיקָנוֹר:","הָעֲזָרָה לֹא הָיְתָה מְכֻוֶּנֶת בְּאֶמְצַע הַר הַבַּיִת. אֶלָּא רְחוֹקָה מִדְּרוֹם הַר הַבַּיִת יֶתֶר מִכָּל הָרוּחוֹת וּקְרוֹבָה לַמַּעֲרָב יֶתֶר מִכָּל הָרוּחוֹת. וּבֵינָהּ וּבֵין הַצָּפוֹן יֶתֶר מִמַּה שֶּׁבֵּינָהּ וּבֵין הַמַּעֲרָב. וּבֵינָהּ וּבֵין הַמִּזְרָח יֶתֶר מִמַּה שֶּׁבֵּינָהּ וּבֵין הַצָּפוֹן:","וְלִפְנֵי הָעֲזָרָה בַּמִּזְרָח הָיְתָה עֶזְרַת הַנָּשִׁים. וְהִיא הָיְתָה אֹרֶךְ מֵאָה אַמָּה וַחֲמִשָּׁה וּשְׁלֹשִׁים עַל רֹחַב קל\"ה. וְאַרְבַּע לְשָׁכוֹת הָיוּ בְּאַרְבַּע מִקְצְעוֹתֶיהָ שֶׁל אַרְבָּעִים אַרְבָּעִים אַמָּה וְלֹא הָיוּ מְקֹרוֹת וְכֵן עֲתִידִין לִהְיוֹת:","וּמַה הֵם מְשַׁמְּשׁוֹת. דְּרוֹמִית מִזְרָחִית לִשְׁכַּת הַנְּזִירִים שֶׁשָּׁם מְבַשְּׁלִין אֶת שַׁלְמֵיהֶם וּמְגַלְּחִין אֶת שַׂעֲרָם. מִזְרָחִית צְפוֹנִית לִשְׁכַּת דִּיר הָעֵצִים שֶׁשָּׁם כֹּהֲנִים בַּעֲלֵי מוּמִין מַתְלִיעִים בָּעֵצִים. שֶׁכָּל עֵץ שֶׁנִּמְצָא בּוֹ תּוֹלַעַת פָּסוּל. צְפוֹנִית מַעֲרָבִית לִשְׁכַּת הַמְצֹרָעִים. מַעֲרָבִית דְּרוֹמִית בָּהּ הָיוּ נוֹתְנִין יַיִן וְשֶׁמֶן וְהִיא הָיְתָה נִקְרֵאת לִשְׁכַּת בֵּית שַׁמְנַיָּא:","עֶזְרַת הַנָּשִׁים הָיְתָה מֻקֶּפֶת גְּזוּזְטְרָא כְּדֵי שֶׁיִּהְיוּ הַנָּשִׁים רוֹאוֹת מִלְּמַעְלָן וְהָאֲנָשִׁים מִלְּמַטָּן כְּדֵי שֶׁלֹּא יִהְיוּ מְעֵרְבָּבִין. וּבַיִת גָּדוֹל הָיָה בְּצַד הָעֲזָרָה בִּצְפוֹנָהּ מִבַּחוּץ בֵּין הָעֲזָרָה וְהַחֵיל וְהָיָה בָּנוּי כִּפָּה וּמֻקָּף רְבָדִין שֶׁל אֶבֶן וְהוּא הָיָה נִקְרָא בֵּית הַמּוֹקֵד. וּשְׁנֵי פְּתָחִים הָיוּ לוֹ אֶחָד פָּתוּחַ לָעֲזָרָה וְאֶחָד פָּתוּחַ לַחֵיל:","וְאַרְבַּע לְשָׁכוֹת הָיוּ בּוֹ. שְׁתַּיִם קֹדֶשׁ וּשְׁתַּיִם חֹל. וְרָאשֵׁי פִּסְפְּסִין מַבְדִּילִין בֵּין הַקֹּדֶשׁ וְהַחל. וּמַה הָיוּ מְשַׁמְּשׁוֹת מַעֲרָבִית דְּרוֹמִית לִשְׁכַּת הַטְּלָאִים. וּדְרוֹמִית מִזְרָחִית לִשְׁכַּת עוֹשֵׂי לֶחֶם הַפָּנִים. מִזְרָחִית צְפוֹנִית בָּהּ גָּנְזוּ בֵּית חַשְׁמוֹנַי אַבְנֵי מִזְבֵּחַ שֶׁשִּׁקְּצוּם מַלְכֵי יָוָן. צְפוֹנִית מַעֲרָבִית בָּהּ יוֹרְדִין לְבֵית הַטְּבִילָה:","הַיּוֹרֵד לְבֵית הַטְּבִילָה מִלִּשְׁכָּה זוֹ הָיָה הוֹלֵךְ בַּמְּסִבָּה הַהוֹלֶכֶת תַּחַת הַמִּקְדָּשׁ כֻּלּוֹ וְהַנֵּרוֹת דּוֹלְקוֹת מִכָּאן וּמִכָּאן עַד שֶׁמַּגִּיעַ לְבֵית הַטְּבִילָה. וּמְדוּרָה הָיְתָה שָׁם. וּבֵית הַכִּסֵּא שֶׁל כָּבוֹד. וְזֶהוּ כְּבוֹדוֹ, מְצָאוֹ נָעוּל בְּיָדוּעַ שֶׁיֵּשׁ שָׁם אָדָם:","אֹרֶךְ הָעֲזָרָה מִן הַמִּזְרָח לַמַּעֲרָב קפ\"ז וְזֶהוּ חֶשְׁבּוֹנָן. מִכֹּתֶל מַעֲרָבִי שֶׁל עֲזָרָה עַד כֹּתֶל הַהֵיכָל אַחַת עֶשְׂרֵה אַמָּה. וְאֹרֶךְ הַהֵיכָל כֻּלּוֹ מֵאָה אַמָּה. בֵּין הָאוּלָם וְלַמִּזְבֵּחַ שְׁתַּיִם וְעֶשְׂרִים. הַמִּזְבֵּחַ שְׁתַּיִם וּשְׁלֹשִׁים. מְקוֹם דְּרִיסַת רַגְלֵי הַכֹּהֲנִים וְהוּא הַנִּקְרָא עֶזְרַת כֹּהֲנִים אַחַת עֶשְׂרֵה אַמָּה. מְקוֹם דְּרִיסַת רַגְלֵי יִשְׂרָאֵל וְהוּא הַנִּקְרָא עֶזְרַת יִשְׂרָאֵל אַחַת עֶשְׂרֵה אַמָּה:","וְרֹחַב הָעֲזָרָה מִן הַצָּפוֹן לַדָּרוֹם מֵאָה וּשְׁלֹשִׁים וְחָמֵשׁ וְזֶהוּ חֶשְׁבּוֹנָן. מִכֹּתֶל צְפוֹנִי עַד בֵּית הַמִּטְבָּחַיִם שְׁמוֹנֶה אַמּוֹת. בֵּית הַמִּטְבָּחַיִם י\"ב אַמּוֹת וּמֶחֱצָה. וְשָׁם תּוֹלִין וּמַפְשִׁיטִין אֶת הַקָּדָשִׁים בְּצִדּוֹ:","מְקוֹם הַשֻּׁלְחָנוֹת שְׁמוֹנֶה אַמּוֹת וּבוֹ שֻׁלְחָנוֹת שֶׁל שַׁיִשׁ שֶׁמַּנִּיחִין עֲלֵיהֶן הַנְּתָחִים וּמְדִיחִין אֶת הַבָּשָׂר לְבַשְּׁלוֹ. וּשְׁמוֹנָה שֻׁלְחָנוֹת הָיוּ. וּבְצַד מְקוֹם הַשֻּׁלְחָנוֹת מְקוֹם הַטַּבָּעוֹת כ\"ד אַמָּה. וְשָׁם שׁוֹחֲטִין אֶת הַקָּדָשִׁים:","וּבֵין מְקוֹם הַטַּבָּעוֹת וְהַמִּזְבֵּחַ שְׁמוֹנֶה אַמּוֹת וְהַמִּזְבֵּחַ ל\"ב. וְהַכֶּבֶשׁ שְׁלֹשִׁים. וּבֵין הַכֶּבֶשׁ וּלְכֹתֶל דְּרוֹמִי י\"ב אַמָּה וּמֶחֱצָה. מִכֹּתֶל צְפוֹנִי שֶׁל עֲזָרָה עַד כֹּתֶל הַמִּזְבֵּחַ שֶׁהוּא רֹחַב שִׁשִּׁים וּמֶחֱצָה. וּכְנֶגְדוֹ מִכֹּתֶל הָאוּלָם עַד כֹּתֶל מִזְרָחִי שֶׁל עֲזָרָה שֶׁהוּא אֹרֶךְ שֵׁשׁ וְשִׁבְעִים:","כָּל הַמְרֻבָּע הַזֶּה הוּא הַנִּקְרָא צָפוֹן הוּא הַמָּקוֹם שֶׁשּׁוֹחֲטִין בּוֹ קָדְשֵׁי קָדָשִׁים:","שְׁמוֹנֶה לְשָׁכוֹת הָיוּ בְּעֶזְרַת יִשְׂרָאֵל. שָׁלֹשׁ בַּצָּפוֹן. וְשָׁלֹשׁ בַּדָּרוֹם. שֶׁבַּדָּרוֹם לִשְׁכַּת הַמֶּלַח. לִשְׁכַּת הַפַּרְוָה. לִשְׁכַּת הַמְּדִיחִין. לִשְׁכַּת הַמֶּלַח שָׁם נוֹתְנִין מֶלַח לַקָּרְבָּן. לִשְׁכַּת הַפַּרְוָה שָׁם מוֹלְחִין עוֹרוֹת הַקָּדָשִׁים. וְעַל גַּגָּהּ הָיְתָה בֵּית טְבִילָה לְכֹהֵן גָּדוֹל בְּיוֹם הַכִּפּוּרִים. לִשְׁכַּת הַמְּדִיחִין שָׁם הָיוּ מְדִיחִין קִרְבֵי הַקָּדָשִׁים וּמִשָּׁם מְסִבָּה עוֹלָה לְגַג בֵּית הַפַּרְוָה. וְהַשָּׁלֹשׁ שֶׁבִּצְפוֹן לִשְׁכַּת הַגָּזִית. לִשְׁכַּת הַגּוּלָה. לִשְׁכַּת הָעֵץ. לִשְׁכַּת הַגָּזִית שֶׁבָּהּ סַנְהֶדְרִי גְּדוֹלָה יוֹשֶׁבֶת. וְחֶצְיָהּ הָיָה קֹדֶשׁ וְחֶצְיָהּ הָיָה חֹל. וְלָהּ שְׁנֵי פְּתָחִים אֶחָד לַקֹּדֶשׁ וְאֶחָד לְחל וּבַחֵצִי שֶׁל חֹל הָיוּ הַסַּנְהֶדְרִין יוֹשְׁבִין. לִשְׁכַּת הַגּוּלָה שָׁם הָיְתָה בּוֹר שֶׁמְּמַלְּאִין מִמֶּנּוּ בַּגּוּלָה וּמִשָּׁם מְסַפְּקִין מַיִם לְכָל הָעֲזָרָה. וְלִשְׁכַּת הָעֵץ הָיְתָה אֲחוֹרֵי שְׁתֵּיהֶן וְהִיא הָיְתָה לִשְׁכַּת כֹּהֵן גָּדוֹל וְהִיא הַנִּקְרֵאת לִשְׁכַּת פַּרְהֶדְרִין. וְגַג שְׁלָשְׁתָּן שָׁוֶה. וּשְׁתֵּי לְשָׁכוֹת אֲחֵרוֹת הָיוּ שָׁם בְּעֶזְרַת יִשְׂרָאֵל. אַחַת מִימִין שַׁעַר מִזְרָחִי וְהוּא לִשְׁכַּת פִּינְחָס הַמַּלְבִּישׁ. וְאֶחָד מִשְּׂמֹאלוֹ וְהוּא לִשְׁכַּת עוֹשֶׂה חֲבִיתִין:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 12":["כֵּיצַד דָּנִין דִּינֵי נְפָשׁוֹת. כְּשֶׁיָּבוֹאוּ עֵדִים לְבֵית דִּין וְאוֹמְרִים רָאִינוּ פְּלוֹנִי זֶה שֶׁעָבַר עֲבֵרָה פְּלוֹנִית. אוֹמְרִין לָהֶן מַכִּירִין אַתֶּם אוֹתוֹ הִתְרֵיתֶם בּוֹ. אִם אָמְרוּ אֵין אָנוּ מַכִּירִין אוֹתוֹ אוֹ נִסְתַּפֵּק לָנוּ אוֹ שֶׁלֹּא הִתְרוּ בּוֹ הֲרֵי זֶה פָּטוּר:","אֶחָד תַּלְמִיד חָכָם וְאֶחָד עַם הָאָרֶץ צָרִיךְ הַתְרָאָה שֶׁלֹּא נִתְּנָה הַתְרָאָה אֶלָּא לְהַבְחִין בֵּין שׁוֹגֵג לְמֵזִיִד שֶׁמָּא שׁוֹגֵג הָיָה. וְכֵיצַד מַתְרִין בּוֹ. אוֹמְרִין לוֹ פְּרשׁ אוֹ אַל תַּעֲשֶׂה שֶׁזּוֹ עֲבֵרָה הִיא וְחַיָּב אַתָּה עָלֶיהָ מִיתַת בֵּית דִּין אוֹ מַלְקוֹת. אִם פֵּרַשׁ פָּטוּר. וְכֵן אִם שָׁתַק אוֹ הִרְכִּין בְּרֹאשׁוֹ פָּטוּר. וַאֲפִלּוּ אָמַר יוֹדֵעַ אֲנִי פָּטוּר עַד שֶׁיַּתִּיר עַצְמוֹ לְמִיתָה וְיֹאמַר עַל מְנָת כֵּן אֲנִי עוֹשֶׂה. וְאַחַר כָּךְ יֵהָרֵג. וְצָרִיךְ שֶׁיַּעֲבֹר וְיַעֲשֶׂה תֵּכֶף לַהַתְרָאָה בְּתוֹךְ כְּדֵי דִּבּוּר. אֲבָל אַחַר כְּדֵי דִּבּוּר צָרִיךְ הַתְרָאָה אַחֶרֶת. וּבֵין שֶׁהִתְרָה בּוֹ אֶחָד מִן הָעֵדִים וּבֵין שֶׁהִתְרָה בּוֹ אַחֵר בִּפְנֵי עֵדִים אֲפִלּוּ אִשָּׁה אוֹ עֶבֶד אֲפִלּוּ שָׁמַע קוֹל הַמַּתְרֶה וְלֹא רָאָהוּ וַאֲפִלּוּ הִתְרָה בְּעַצְמוֹ הֲרֵי זֶה נֶהֱרָג:","אָמְרוּ הָעֵדִים הָיְתָה לוֹ הַתְרָאָה וּמַכִּירִין אָנוּ אוֹתוֹ מְאַיְּמִין בֵּית דִּין עֲלֵיהֶן. וְכֵיצַד מְאַיְּמִין עַל עִסְקֵי נְפָשׁוֹת. אוֹמְרִים לָהֶן שֶׁמָּא תֹּאמְרוּ מֵאֹמֶד וּמִשְּׁמוּעָה עֵד מִפִּי עֵד מִפִּי אָדָם נֶאֱמָן שְׁמַעְתֶּם. אוֹ שֶׁמָּא אֵין אַתֶּם יוֹדְעִים שֶׁסּוֹפֵנוּ לִבְדֹּק אֶתְכֶם בִּדְרִישָׁה וַחֲקִירָה. הֱווּ יוֹדְעִים שֶׁלֹּא כְּדִינֵי מָמוֹנוֹת דִּינֵי נְפָשׁוֹת. דִּינֵי מָמוֹנוֹת אָדָם נוֹתֵן מָמוֹנוֹ וּמִתְכַּפֵּר לוֹ דִּינֵי נְפָשׁוֹת דָּמוֹ וְדַם זַרְעוֹ תְּלוּיִין בּוֹ עַד סוֹף כָּל הָעוֹלָם שֶׁהֲרֵי בְּקַיִן נֶאֱמַר (בראשית ד י) \"קוֹל דְּמֵי אָחִיךָ צֹעֲקִים\" דָּמוֹ וְדַם זַרְעוֹ. לְפִיכָךְ נִבְרָא אָדָם יְחִידִי בָּעוֹלָם לְלַמֵּד שֶׁכָּל הַמְאַבֵּד נֶפֶשׁ אַחַת מִן הָעוֹלָם מַעֲלִין עָלָיו כְּאִלּוּ אִבֵּד עוֹלָם מָלֵא וְכָל הַמְקַיֵּם נֶפֶשׁ אַחַת בָּעוֹלָם מַעֲלִין עָלָיו כְּאִלּוּ קִיֵּם עוֹלָם מָלֵא. הֲרֵי כָּל בָּאֵי עוֹלָם בְּצוּרַת אָדָם הָרִאשׁוֹן הֵם נִבְרָאִים וְאֵין פְּנֵי כָּל אֶחָד מֵהֶן דּוֹמִין לִפְנֵי חֲבֵרוֹ. לְפִיכָךְ כָּל אֶחָד וְאֶחָד יָכוֹל לוֹמַר בִּשְׁבִילִי נִבְרָא הָעוֹלָם. שֶׁמָּא תֹּאמְרוּ מַה לָּנוּ וּלְצָרָה זוֹ הֲלֹא כְּבָר נֶאֱמַר (ויקרא ה א) \"וְהוּא עֵד אוֹ רָאָה אוֹ יָדָע\". אוֹ שֶׁמָּא תֹּאמְרוּ מַה לָּנוּ לָחוֹב בְּדָמוֹ שֶׁל זֶה וַהֲלֹא כְּבָר נֶאֱמַר (משלי יא י) \"וּבַאֲבֹד רְשָׁעִים רִנָּה\". אִם עָמְדוּ בְּדִבְרֵיהֶן מַכְנִיסִין אֶת הַגָּדוֹל שֶׁבָּעֵדִים וּבוֹדְקִים אוֹתוֹ בִּדְרִישָׁה וַחֲקִירָה כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת עֵדוּת. אִם נִמְצֵאת עֵדוּתוֹ מְכֻוֶּנֶת מַכְנִיסִין אֶת הַשֵּׁנִי וּבוֹדְקִין אוֹתוֹ כָּרִאשׁוֹן. אֲפִלּוּ הָיוּ מֵאָה עֵדִים בּוֹדְקִין כָּל אֶחָד וְאֶחָד בִּדְרִישָׁה וַחֲקִירָה. נִמְצְאוּ דִּבְרֵי כָּל הָעֵדִים מְכֻוָּנִים פּוֹתְחִין לִזְכוּת כְּמוֹ שֶׁבֵּאַרְנוּ. וְאוֹמְרִים אִם לֹא חָטָאתָ אַל תִּירָא מִדִּבְרֵיהֶם וְדָנִין אוֹתוֹ. אִם מָצְאוּ לוֹ זְכוּת פְּטָרוּהוּ וְאִם לֹא מָצְאוּ לוֹ זְכוּת אוֹסְרִין אוֹתוֹ עַד לְמָחָר. וּבוֹ בַּיּוֹם מִזְדַּוְּגִין הַסַּנְהֶדְרִין זוּגוֹת זוּגוֹת לְעַיֵּן בְּדִינוֹ. וּמְמַעֲטִין בְּמַאֲכָל וְאֵין שׁוֹתִין יַיִן כָּל אוֹתוֹ הַיּוֹם. וְנוֹשְׂאִין בַּדָּבָר כָּל הַלַּיְלָה כָּל אֶחָד וְאֶחָד עִם זוּג שֶׁלּוֹ אוֹ עִם עַצְמוֹ בְּבֵיתוֹ. וְלַמָּחֳרָת מַשְׁכִּימִין לְבֵית דִּין. הַמְזַכֶּה אוֹמֵר אֲנִי הוּא הַמְזַכֶּה וּמְזַכֶּה אֲנִי בִּמְקוֹמִי וְהַמְחַיֵּב אוֹמֵר אֲנִי הוּא הַמְחַיֵּב וּמְחַיֵּב אֲנִי בִּמְקוֹמִי אוֹ חָזַרְתִּי בִּי וַאֲנִי מְזַכֶּה. וְאִם טָעוּ בַּדָּבָר וְלֹא יָדְעוּ מִי הֵם שֶׁחִיְּבוּ אוֹ זִכּוּ מִטַּעַם אֶחָד שֶׁאֵינָן נֶחְשָׁבִין אֶלָּא כְּאֶחָד כְּמוֹ שֶׁבֵּאַרְנוּ. הֲרֵי סוֹפְרֵי הַדַּיָּנִין מַזְכִּירִין אוֹתָן שֶׁהֲרֵי כּוֹתְבִין טַעַם שֶׁל כָּל אֶחָד וְאֶחָד. וּמַתְחִילִין בְּדִינוֹ. אִם מָצְאוּ לוֹ זְכוּת פְּטָרוּהוּ וְאִם הֻצְרְכוּ לְהוֹסִיף מוֹסִיפִין. רַבּוּ הַמְחַיְּבִין וְנִתְחַיֵּב מוֹצִיאִין אוֹתוֹ לְהָרְגוֹ. ומָקוֹם שֶׁהוֹרְגִין בּוֹ בֵּית דִּין הָיָה חוּץ לְבֵית דִּין וְרָחוֹק מִבֵּית דִּין. שֶׁנֶּאֱמַר (ויקרא כד יד) \"הוֹצֵא אֶת הַמְקַלֵּל אֶל מִחוּץ לַמַּחֲנֶה\". וְיֵרָאֶה לִי שֶׁיִּהְיֶה רָחוֹק כְּמוֹ שִׁשָּׁה מִילִין כְּמוֹ שֶׁהָיָה בֵּין בֵּית דִּינוֹ שֶׁל משֶׁה רַבֵּנוּ שֶׁהָיָה לִפְנֵי פֶּתַח אֹהֶל מוֹעֵד וּבֵין מַחֲנֵה יִשְׂרָאֵל:","מִשֶּׁנִּגְמַר דִּינוֹ אֵין מַשְׁהִין אוֹתוֹ אֶלָּא יֵהָרֵג בְּיוֹמוֹ. אֲפִלּוּ הָיְתָה עֻבָּרָה אֵין מַמְתִּינִין לָהּ עַד שֶׁתֵּלֵד. וּמַכִּין אוֹתָהּ כְּנֶגֶד בֵּית הַהֵרָיוֹן עַד שֶׁיָּמוּת הַוָּלָד תְּחִלָּה. אֲבָל אִם יָשְׁבָה עַל הַמַּשְׁבֵּר מַמְתִּינִין לָהּ עַד שֶׁתֵּלֵד. וְכָל אִשָּׁה שֶׁתֵּהָרֵג מֻתָּר לֵהָנוֹת בִּשְׂעָרָהּ:","מִי שֶׁיָּצָא לֵהָרֵג וְהָיָה זִבְחוֹ זָבוּחַ אֵין הוֹרְגִין אוֹתוֹ עַד שֶׁמַּזִּין עָלָיו מִדַּם חַטָּאתוֹ וַאֲשָׁמוֹ. וְאִם נִגְמַר דִּינוֹ וַעֲדַיִן לֹא נִשְׁחַט הַזֶּבַח אֵין מַמְתִּינִין לוֹ עַד שֶׁיַּקְרִיבוּ עָלָיו קָרְבָּנוֹ שֶׁאֵין מְעַנִּין אֶת דִּינוֹ:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 23":["(דברים טז יט) \"לֹא תִּקַּח שֹׁחַד\" אֵין צָרִיךְ לוֹמַר לְעַוֵּת אֶת הַדִּין אֶלָּא אֲפִלּוּ לְזַכּוֹת אֶת הַזַּכַּאי וּלְחַיֵּב אֶת הַחַיָּב אָסוּר וְעוֹבֵר בְּלֹא תַּעֲשֶׂה. וַהֲרֵי הוּא בִּכְלַל אָרוּר לֹקֵחַ שֹׁחַד. וְחַיָּב לְהַחְזִיר הַשֹּׁחַד כְּשֶׁיִּתְבָּעֶנּוּ הַנּוֹתֵן:","וּכְשֵׁם שֶׁהַלּוֹקֵחַ עוֹבֵר בְּלֹא תַּעֲשֶׂה כָּךְ הַנּוֹתֵן. שֶׁנֶּאֱמַר (ויקרא יט יד) \"וְלִפְנֵי עִוֵּר לֹא תִתֵּן מִכְשׁל\":","כָּל דַּיָּן שֶׁיּוֹשֵׁב וּמְגַדֵּל מַעֲלָתוֹ כְּדֵי לְהַרְבּוֹת שָׂכָר לְחַזָּנָיו וּלְסוֹפְרָיו הֲרֵי הוּא בִּכְלַל הַנּוֹטִים אַחֲרֵי הַבֶּצַע. וְכֵן עָשׂוּ בְּנֵי שְׁמוּאֵל וּלְכָךְ נֶאֱמַר לָהֶם (שמואל א ח ג) \"וַיִּטּוּ אַחֲרֵי הַבָּצַע וַיִּקְחוּ שֹׁחַד\". וְלֹא שֹׁחַד מָמוֹן בִּלְבַד אֶלָּא אֲפִלּוּ שֹׁחַד דְּבָרִים. וּמַעֲשֶׂה בְּדַיָּן אֶחָד שֶׁהָיָה עוֹלֶה בְּדוּגִית קְטַנָּה לַעֲבֹר בַּנָּהָר וּפָשַׁט אֶחָד יָדוֹ וְסִיְּעוֹ בַּעֲלִיָּתוֹ וְהָיָה לוֹ דִּין וְאָמַר לוֹ הַדַּיָּן הֲרֵינִי פָּסוּל לְךָ לָדִין. וּמַעֲשֶׂה בְּאֶחָד שֶׁהֶעֱבִיר אֶבְרָה נוֹצָה שֶׁל עוֹף מֵעַל רְדִיד הַדַּיָּן וְאַחַר כִּסָּה רֹק מִלִּפְנֵי הַדַּיָּן וְאָמַר לוֹ הֲרֵינִי פָּסוּל לְךָ לָדִין. וּמַעֲשֶׂה בְּאֶחָד שֶׁהֵבִיא מַתָּנָה אַחַת מִמַּתְּנוֹת כְּהֻנָּה לְדַיָּן כֹּהֵן וְאָמַר לוֹ פָּסוּל אֲנִי לְךָ לָדִין. וּמַעֲשֶׂה בְּאָרִיס אֶחָד שֶׁל דַּיָּן שֶׁהָיָה מֵבִיא לוֹ תְּאֵנִים מִתּוֹךְ שָׂדֵהוּ מֵעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת פַּעַם אַחַת הִקְדִּים וְהֵבִיא בַּחֲמִישִׁי בְּשַׁבָּת מִפְּנֵי שֶׁהָיָה לוֹ דִּין וְאָמַר לוֹ הַדַּיָּן הֲרֵינִי פָּסוּל לְךָ לָדִין אַף עַל פִּי שֶׁהַתְּאֵנִים מִשֶּׁל דַּיָּן הוֹאִיל וֶהֱבִיאָן שֶׁלֹּא בִּזְמַנָּם נִפְסַל לוֹ לָדִין:","כָּל דַּיָּן שֶׁשָּׁאַל שְׁאֵלָה פָּסוּל לָדִין לָזֶה שֶׁהִשְׁאִילוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁלֹּא הָיָה לוֹ לַדַּיָּן לְהַשְׁאִיל אֲבָל הָיָה לוֹ לְהַשְׁאִיל כָּשֵׁר שֶׁהֲרֵי גַּם זֶה שׁוֹאֵל מִמֶּנּוּ:","כָּל דַּיָּן שֶׁנּוֹטֵל שְׂכָרוֹ לָדוּן דִּינָיו בְּטֵלִים. וְהוּא שֶׁלֹּא יִהְיֶה שָׂכָר הַנִּכָּר. אֲבָל אִם הָיָה עוֹסֵק בִּמְלַאכְתּוֹ וּבָאוּ לְפָנָיו שְׁנַיִם לְדִין וְאָמַר לָהֶן תְּנוּ לִי מִי שֶׁיַּעֲשֶׂה תַּחְתַּי עַד שֶׁאָדוּן לָכֶם אוֹ תְּנוּ לִי שָׂכָר בַּטָּלָתִי הֲרֵי זֶה מֻתָּר. וְהוּא שֶׁיִּהְיֶה הַדָּבָר נִכָּר שֶׁהוּא שְׂכַר הַבַּטָּלָה בִּלְבַד וְלֹא יוֹתֵר. וְיִטּל מִשְּׁנֵיהֶם בְּשָׁוֶה זֶה בִּפְנֵי זֶה. כְּגוֹן זֶה מֻתָּר:","אָסוּר לַדַּיָּן לָדוּן לְמִי שֶׁהוּא אוֹהֲבוֹ אַף עַל פִּי שֶׁאֵינוֹ שׁוֹשְׁבִינוֹ וְלֹא רֵעוֹ אֲשֶׁר כְּנַפְשׁוֹ וְלֹא לְמִי שֶׁשּׂוֹנְאוֹ אַף עַל פִּי שֶׁאֵינוֹ אוֹיֵב לוֹ וְלֹא מְבַקֵּשׁ רָעָתוֹ אֶלָּא צָרִיךְ שֶׁיִּהְיוּ שְׁנֵי בַּעֲלֵי דִּינִים שָׁוִין בְּעֵינֵי הַדַּיָּנִים וּבְלִבָּם. וְאִם לֹא הָיָה מַכִּיר אֶת אֶחָד מֵהֶם וְלֹא מַעֲשָׂיו אֵין לְךָ דַּיַּן צֶדֶק כָּמוֹהוּ:","כָּל שְׁנֵי תַּלְמִידֵי חֲכָמִים שֶׁשּׂוֹנְאִים זֶה אֶת זֶה אֲסוּרִין לֵישֵׁב בַּדִּין זֶה עִם זֶה. שֶׁדָּבָר זֶה גּוֹרֵם לִיצִיאַת מִשְׁפָּט מְעֻקָּל. מִפְּנֵי הַשִּׂנְאָה שֶׁבֵּינֵיהֶן דַּעַת כָּל אֶחָד נוֹטָה לִסְתֹּר דִּבְרֵי חֲבֵרוֹ:","לְעוֹלָם יִרְאֶה דַּיָּן עַצְמוֹ כְּאִלּוּ חֶרֶב מֻנַּחַת לוֹ עַל צַוָּארוֹ וְגֵיהִנֹּם פְּתוּחָה לוֹ מִתַּחְתָּיו. וְיֵדַע אֶת מִי הוּא דָּן וְלִפְנֵי מִי הוּא דָּן וּמִי עָתִיד לְהִפָּרַע מִמֶּנּוּ אִם נָטָה מִקַּו הָאֱמֶת שֶׁנֶּאֱמַר (תהילים פב א) \"אֱלֹהִים נִצָּב בַּעֲדַת אֵל\". וְאוֹמֵר (דברי הימים ב יט ו) \"רְאוּ מָה אַתֶּם עוֹשִׂים כִּי לֹא לְאָדָם תִּשְׁפְּטוּ כִּי לַה'\":","כָּל דַּיָּן שֶׁאֵינוֹ דָּן דִּין אֱמֶת לַאֲמִתּוֹ גּוֹרֵם לַשְּׁכִינָה שֶׁתִּסְתַּלֵּק מִיִּשְׂרָאֵל. וְכָל דַּיָּן שֶׁנּוֹטֵל מִזֶּה וְנוֹתֵן לָזֶה שֶׁלֹּא כַּדִּין הַקָּדוֹשׁ בָּרוּךְ הוּא גּוֹבֶה מִמֶּנּוּ נְפָשׁוֹת שֶׁנֶּאֱמַר (משלי כב כג) \"וְקָבַע אֶת קֹבְעֵיהֶם נָפֶשׁ\". וְכָל דַּיָּן שֶׁדָּן דִּין אֱמֶת לַאֲמִתּוֹ אֲפִלּוּ שָׁעָה אַחַת כְּאִלּוּ תִּקֵּן אֶת כָּל הָעוֹלָם כֻּלּוֹ וְגוֹרֵם לַשְּׁכִינָה שֶׁתִּשְׁרֶה בְּיִשְׂרָאֵל שֶׁנֶּאֱמַר (תהילים פב א) \"אֱלֹהִים נִצָּב בַּעֲדַת אֵל\". וְשֶׁמָּא יֹאמַר הַדַּיָּן מַה לִּי וְלַצָּרָה הַזֹּאת תַּלְמוּד לוֹמַר (דברי הימים ב יט ו) \"וְעִמָּכֶם בִּדְבַר מִשְׁפָּט\". אֵין לַדַּיָּן אֶלָּא מַה שֶּׁעֵינָיו רוֹאוֹת:","ולְעוֹלָם יִהְיוּ בַּעֲלֵי דִּינִין לְפָנֶיךָ כִּרְשָׁעִים וּבְחֶזְקַת שֶׁכָּל אֶחָד מֵהֶן טוֹעֵן שֶׁקֶר וְדוּן לְפִי מַה שֶּׁתִּרְאֶה מִן הַדְּבָרִים. וּכְשֶׁיִּפָּטְרוּ מִלְּפָנֶיךָ יִהְיוּ בְּעֵינֶיךָ כְּצַדִּיקִים כְּשֶׁקִּבְּלוּ עֲלֵיהֶם אֶת הַדִּין וְדוּן כָּל אֶחָד מֵהֶם לְכַף זְכוּת:"],"Mishneh Torah, Theft 2":["הַגּוֹנֵּב אֶת הָעַכּוּ\"ם אוֹ שֶׁגָּנַב נִכְסֵי הֶקְדֵּשׁ אֵינוֹ מְשַׁלֵּם אֶלָּא הַקֶּרֶן בִּלְבַד שֶׁנֶּאֱמַר (שמות כב ח) \"יְשַׁלֵּם שְׁנַיִם לְרֵעֵהוּ\" לְרֵעֵהוּ וְלֹא לַהֶקְדֵּשׁ לְרֵעֵהוּ וְלֹא לְעַכּוּ\"ם. וְכֵן הַגּוֹנֵב קָדָשִׁים מִבֵּית בַּעֲלֵיהֶן בֵּין קָדְשֵׁי קָדָשִׁים בֵּין קָדָשִׁים קַלִּים בֵּין קָדָשִׁים שֶׁאֵין הַבְּעָלִים חַיָּבִין בְּאַחֲרָיוּתָן בֵּין קָדָשִׁים שֶׁהַבְּעָלִים חַיָּבִין בְּאַחֲרָיוּתָן הֲרֵי זֶה פָּטוּר מִן הַכֶּפֶל וּמִתַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה שֶׁנֶּאֱמַר (שמות כב ו) \"וְגֻנַּב מִבֵּית הָאִישׁ\" וְלֹא מִבֵּית הֶקְדֵּשׁ:","וְכֵן הַגּוֹנֵב עֲבָדִים וּשְׁטָרוֹת וְקַרְקָעוֹת אֵינוֹ מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל. שֶׁלֹּא חִיְּבָה הַתּוֹרָה הַכֶּפֶל אֶלָּא בְּמִטַּלְטְלִין שֶׁגּוּפָן מָמוֹן שֶׁנֶּאֱמַר (שמות כב ח) \"עַל שׁוֹר עַל חֲמוֹר עַל שֶׂה עַל שַׂלְמָה\". אֲבָל הָעֲבָדִים הֻקְּשׁוּ לְקַרְקָעוֹת שֶׁנֶּאֱמַר (ויקרא כה מו) \"וְהִתְנַחַלְתֶּם אֹתָם לִבְנֵיכֶם\". וְהַשְּׁטָרוֹת אֵין גּוּפָן מָמוֹן:","הַגּוֹנֵב פֶּטֶר חָמוֹר שֶׁל חֲבֵרוֹ קֹדֶם שֶׁיִּפָּדֶה מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל לַבְּעָלִים. שֶׁאַף עַל פִּי שֶׁאֵינוֹ עַכְשָׁו שֶׁלּוֹ רָאוּי לִהְיוֹתוֹ לוֹ אַחַר שֶׁיִּפָּדֶה:","הַגּוֹנֵב טִבְלוֹ שֶׁל חֲבֵרוֹ וַאֲכָלוֹ מְשַׁלֵּם לוֹ דְּמֵי טִבְלוֹ. וְכֵן אִם גָּנַב חֶלְבּוֹ וַאֲכָלוֹ מְשַׁלֵּם לוֹ דְּמֵי חֶלְבּוֹ:","גָּנַב תְּרוּמָה מִבְּעָלֶיהָ הַיִּשְׂרְאֵלִים שֶׁהִפְרִישׁוּהָ אֵינוֹ מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל. שֶׁאֵין לָהֶם בָּהּ אֶלָּא טוֹבַת הֲנָאָה וְטוֹבַת הֲנָאָה אֵינָהּ מָמוֹן:","הַגּוֹנֵב מִשֶּׁל אָבִיו וְטָבַח אוֹ מָכַר וְאַחַר כָּךְ מֵת אָבִיו מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה. וְאִם מֵת אָבִיו וְאַחַר כָּךְ טָבַח אוֹ מָכַר מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל וְאֵינוֹ מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה. גָּנַב וְטָבַח אוֹ מָכַר וְאַחַר כָּךְ הִקְדִּישׁ מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה. וְאִם הִקְדִּישׁ וְאַחַר כָּךְ טָבַח אוֹ מָכַר אַף עַל פִּי שֶׁהִקְדִּישׁוֹ קָדָשִׁים קַלִּים מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל וְאֵינוֹ מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהִקְדִּישׁ אַחַר יֵאוּשׁ. אֲבָל אִם הִקְדִּישׁ לִפְנֵי יֵאוּשׁ אֵינוֹ קָדוֹשׁ וְאִם טָבַח אוֹ מָכַר מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה:","הִקְדִּישׁוּ הַבְּעָלִים וְהוּא בְּבֵית הַגַּנָּב אֵינוֹ קָדוֹשׁ לְפִי שֶׁאֵינוֹ בִּרְשׁוּתָן וְאַף עַל פִּי שֶׁלֹּא נִתְיָאֲשׁוּ. וְאִם טָבַח אוֹ מָכַר אֲפִלּוּ אַחַר הֶקְדֵּשָׁן מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה:","הַשּׁוֹחֵט וְנִתְנַבְּלָה בְּיָדוֹ וְהַנּוֹחֵר וְהַמְעַקֵּר מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל בִּלְבַד. אֲבָל אִם שָׁחַט לִרְפוּאָה אוֹ לִכְלָבִים אוֹ שֶׁנִּמְצֵאת טְרֵפָה אוֹ שֶׁשְּׁחָטוֹ בָּעֲזָרָה מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה. אַף עַל פִּי שֶׁחֻלִּין שֶׁנִּשְׁחֲטוּ בַּעֲזָרָה אֲסוּרִין בַּהֲנָאָה הוֹאִיל וְאִסּוּרָן מִדִּבְרֵיהֶם הֲרֵי זֶה חַיָּב לְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה:","וְכֵן הַגּוֹנֵב כִּלְאַיִם הַבָּא מִן הַשֶּׂה וּמִמִּין אַחֵר אוֹ שֶׁגָּנַב טְרֵפָה אוֹ קִטַּעַת אוֹ חִגֶּרֶת אוֹ סוּמָא אוֹ בֶּהֱמַת הַשֻּׁתָּפִין וְטָבַח וּמָכַר מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה:","גָּנַב וְנָתַן לְאַחֵר בְּמַתָּנָה אוֹ שֶׁנָּתַן לְאַחֵר לִטְבֹּחַ וְטָבַח אוֹ שֶׁנָּתַן לְאַחֵר לִמְכֹּר וּמְכָרָהּ לְאַחֵר. גָּנַב וְהִקִּיף גָּנַב וְהֶחְלִיף גָּנַב וּפָרַע בְּהֶקֵּפוֹ אוֹ שֶׁשְּׁלָחוֹ סִבְלוֹנוֹת לְבֵית חָמִיו מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה:","גָּנַב וּמָכַר וְהִקְנָה לַמּוֹכֵר לְאַחַר שְׁלֹשִׁים יוֹם וּבְתוֹךְ שְׁלֹשִׁים יוֹם הֻכַּר הַגַּנָּב אֵינוֹ מְשַׁלֵּם אֶלָּא כֶּפֶל. מְכָרוֹ חוּץ מֵאֶחָד מִמֵּאָה שֶׁבּוֹ אוֹ חוּץ מִיָּדוֹ אוֹ רַגְלוֹ כְּלָלוֹ שֶׁל דָּבָר שֶׁשִּׁיֵּר בּוֹ דָּבָר הַנִּתָּר עִמּוֹ בִּשְׁחִיטָה פָּטוּר מִתַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה. וְאִם מְכָרוֹ חוּץ מִגִּזָּתוֹ אוֹ חוּץ מִקַּרְנָיו חַיָּב בְּתַשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה שֶׁאֵלּוּ אֵינָם נִתָּרִים עִמּוֹ בִּשְׁחִיטָה:","גָּנַב וְקָטַע מִמֶּנָּה אֵיבָר וְאַחַר כָּךְ מְכָרָהּ אוֹ שֶׁמְּכָרָהּ חוּץ מִמְּלַאכְתָּהּ אוֹ שֶׁמְּכָרָהּ חוּץ מִשְּׁלֹשִׁים יוֹם אֵין מוֹצִיאִין מִמֶּנּוּ תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה. וְאִם תָּפַשׂ הַנִּזָּק אֵין מוֹצִיאִין מִיָּדוֹ:","מְכָרָהּ וְהָיְתָה לוֹ בָּהּ שֻׁתָּפוּת פָּטוּר מִתַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה:","שֻׁתָּפִין שֶׁגָּנְבוּ. אִם טָבַח אֶחָד מֵהֶן אוֹ מָכַר מִדַּעַת חֲבֵרוֹ מְשַׁלְּמִין תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה. וְאִם עָשָׂה שֶׁלֹּא מִדַּעַת חֲבֵרוֹ פְּטוּרִין מִתַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה וְחַיָּבִין בְּכֶפֶל:","גָּנַב וְעָמַד בַּדִּין וְאָמְרוּ לוֹ הַדַּיָּנִין צֵא תֵּן לוֹ מַה שֶּׁגָּנַבְתָּ וְיָצָא וְאַחַר כָּךְ טָבַח אוֹ מָכַר פָּטוּר מִתַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה. אָמְרוּ לוֹ חַיָּב אַתָּה לִתֵּן לוֹ וְטָבַח אוֹ מָכַר אַחַר כָּךְ הֲרֵי זֶה חַיָּב בְּתַשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה הוֹאִיל וְלֹא חָתְכוּ הַדִּין עָלָיו וַעֲדַיִן עוֹמֵד הוּא בִּגְנֵבָתוֹ:","הַגּוֹנֵב בִּרְשׁוּת הַבְּעָלִים הוֹאִיל וְהַגְּנֵבָה עֲדַיִן הִיא בִּרְשׁוּתָם פָּטוּר מִן הַכֶּפֶל. וְכֵן אִם טָבַח וּמָכַר שָׁם בִּרְשׁוּתָן פָּטוּר. וְאִם הִגְבִּיהַּ הַגְּנֵבָה נִתְחַיֵּב מִשּׁוּם גּוֹנֵב אַף עַל פִּי שֶׁעֲדַיִן לֹא הוֹצִיאָהּ מֵרְשׁוּת הַבְּעָלִים. כֵּיצַד. גָּנַב טָלֶה מִן הַדִּיר וְהָיָה מוֹשְׁכוֹ וְיוֹצֵא וּמֵת בִּרְשׁוּת הַבְּעָלִים פָּטוּר. הִגְבִּיהוֹ אוֹ הוֹצִיאוֹ מֵרְשׁוּת הַבְּעָלִים וּמֵת חַיָּב. נְתָנוֹ שָׁם בְּבֵית הַבְּעָלִים לִבְכוֹרַת בְּנוֹ אוֹ לְבַעַל חוֹבוֹ אוֹ לְשׁוֹמֵר חִנָּם וּלְשׁוֹאֵל לְנוֹשֵׂא שָׂכָר וּלְשׂוֹכֵר וְהָיָה מוֹשְׁכוֹ זֶה שֶׁנִּתַּן לוֹ וּמֵת פָּטוּר הַשּׁוֹמֵר. הִגְבִּיהוֹ אוֹ שֶׁהוֹצִיאוֹ מֵרְשׁוּת הַבְּעָלִים וּמֵת חַיָּב הַשּׁוֹמֵר אוֹ בַּעַל הַחוֹב שֶׁנִּתַּן לוֹ מִפְּנֵי שֶׁעֲדַיִן לֹא הוֹצִיאוֹ הַגַּנָּב מֵרְשׁוּת בְּעָלָיו:","הָיָה הָעֵדֶר בַּיַּעַר כֵּיוָן שֶׁהִכִּישׁ אֶת הַבְּהֵמָה וּטְמָנָהּ בְּתוֹךְ הָאִילָנוֹת וְהָעֵצִים חַיָּב בְּתַשְׁלוּמֵי כֶּפֶל וְאִם טְבָחָהּ אוֹ מְכָרָהּ שָׁם מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה:","גָּנַב בִּרְשׁוּת הַבְּעָלִים וְאַחַר שֶׁיָּדְעוּ שֶׁנִּגְנְבָה הוֹצִיאָהּ וּטְבָחָהּ אוֹ מְכָרָהּ חוּץ מֵרְשׁוּתָן. אוֹ שֶׁגָּנַב וְהוֹצִיא חוּץ מֵרְשׁוּתָן וְטָבַח אוֹ מָכַר בִּרְשׁוּתָן מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה:"],"Mishneh Torah, Things Forbidden on the Altar 5":["שְׂאוֹר וּדְבַשׁ אֲסוּרִין לְגַבֵּי הַמִּזְבֵּחַ וְאִסּוּרָן בְּכָל שֶׁהֵן שֶׁנֶּאֱמַר (ויקרא ב׳:י״א) \"כִּי כָל שְׂאֹר וְכָל דְּבַשׁ לֹא תַקְטִירוּ\" וְגוֹ'. וְאֵינוֹ חַיָּב אֶלָּא אִם הִקְטִירָן עִם הַקָּרְבָּן אוֹ לְשֵׁם קָרְבָּן. וְאֶחָד הַמַּקְטִיר עַצְמָן אוֹ הַמַּקְטִיר תַּעֲרוֹבוֹת שֶׁלָּהֶן לוֹקֶה עַל כָּל אֶחָד מֵהֶן בִּפְנֵי עַצְמוֹ. וְאִם הִקְטִיר שְׁנֵיהֶן כְּאֶחָד אֵינוֹ לוֹקֶה אֶלָּא אַחַת לְפִי שֶׁשְּׁנֵיהֶם נֶאֶמְרוּ בְּלָאו אֶחָד:","נָפַל מֵהֶם כָּל שֶׁהוּא בַּקְּטֹרֶת נִפְסְלָה. וְאִם הִקְטִיר מִמֶּנָּה בַּהֵיכָל לוֹקֶה. וְאֵין הַקְטָרָה פְּחוּתָה מִכְּזַיִת:","הֶעֱלָה שְׂאוֹר אוֹ דְּבַשׁ בִּפְנֵי עַצְמָן לַמִּזְבֵּחַ לְשֵׁם עֵצִים פָּטוּר שֶׁנֶּאֱמַר (ויקרא ב׳:י״ב) \"וְאֶל הַמִּזְבֵּחַ לֹא יַעֲלוּ לְרֵיחַ נִיחֹחַ\". לְרֵיחַ נִיחוֹחַ אִי אַתָּה מַעֲלֶה אֲבָל אַתָּה מַעֲלֶה לְשֵׁם עֵצִים. אֲפִלּוּ הִקְטִיר דָּבָר שֶׁאֵינוֹ רָאוּי לְהַקְטָרָה בִּדְבַשׁ אוֹ בִּשְׂאוֹר הוֹאִיל וְהוּא מִן הַקָּרְבָּן לוֹקֶה:","כֵּיצַד. הַמַּעֲלֶה מִבְּשַׂר חַטָּאת וְאָשָׁם אוֹ מִבְּשַׂר קָדָשִׁים קַלִּים אוֹ מִשְּׁיָרֵי הַמְּנָחוֹת אוֹ מִמּוֹתַר הָעֹמֶר אוֹ מֵחַטַּאת הָעוֹף אוֹ מִלֶּחֶם הַפָּנִים וּשְׁתֵּי הַלֶּחֶם אוֹ מִלּוֹג שֶׁמֶן שֶׁל מְצֹרָע הַמַּעֲלֶה כְּזַיִת מֵאַחַת מֵאֵלּוּ בְּחָמֵץ אוֹ בִּדְבַשׁ בֵּין לַמִּזְבֵּחַ בֵּין לַכֶּבֶשׁ לוֹקֶה. אַף עַל פִּי שֶׁאֵין כָּל אֵלּוּ רְאוּיִין לְהַקְטָרָה הוֹאִיל וְהֵן קְרוּיִין קָרְבָּן חַיָּב עֲלֵיהֶן שֶׁנֶּאֱמַר (ויקרא ב׳:י״ב) \"קָרְבַּן רֵאשִׁית תַּקְרִיבוּ אֹתָם לַה'\" וְגוֹ':","וְכֵן אָסוּר לְהַקְטִיר עַל הַמִּזְבֵּחַ דָּבָר מִכָּל דְּבָרִים אֵלּוּ שֶׁאֵינָן רְאוּיִין לְהַקְטָרָה. כְּגוֹן בְּשַׂר חַטָּאוֹת וַאֲשָׁמוֹת וּשְׁיָרֵי מְנָחוֹת וְכַיּוֹצֵא בָּהֶן. מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁכָּל דָּבָר שֶׁמִּקְצָתוֹ לָאִשִּׁים הֲרֵי שְׁאֵרִיתוֹ בְּבַל תַּקְטִירוּ:","הַמַּקְטִיר אֵיבְרֵי בְּהֵמָה טְמֵאָה עַל גַּבֵּי הַמִּזְבֵּחַ לוֹקֶה. וְאַף עַל פִּי שֶׁאִסּוּר הַקְרָבָתָהּ מִכְּלַל עֲשֵׂה שֶׁהֲרֵי נֶאֱמַר מִן הַטְּהוֹרָה אֱכל וּמִן הַטְּהוֹרָה הַקְרֵב הָא טְמֵאָה לֹא תֹּאכַל וְלֹא תַּקְרִיב. כְּשֵׁם שֶׁלּוֹקֶה עַל אֲכִילַת הַטְּמֵאָה הַבָּא מִכְּלַל עֲשֵׂה כְּמוֹ שֶׁבֵּאַרְנוּ בִּמְקוֹמוֹ כָּךְ לוֹקֶה עַל הַקְרָבָתָהּ. אֲבָל הַמַּקְרִיב אֵיבְרֵי חַיָּה טְהוֹרָה עוֹבֵר בַּעֲשֵׂה וְאֵינוֹ לוֹקֶה. וּמִנַּיִן שֶׁהוּא בַּעֲשֵׂה שֶׁנֶּאֱמַר (ויקרא א׳:ב׳) \"מִן הַבְּהֵמָה מִן הַבָּקָר וּמִן הַצֹּאן תַּקְרִיבוּ אֶת קָרְבַּנְכֶם\" הָא מִן הַחַיָּה לֹא תַּקְרִיבוּ וְלָאו הַבָּא מִכְּלַל עֲשֵׂה עֲשֵׂה:","הַגּוֹנֵב אוֹ הַגּוֹזֵל וְהִקְרִיב הַקָּרְבָּן פָּסוּל וְהַקָּדוֹשׁ בָּרוּךְ הוּא שׂוֹנְאוֹ שֶׁנֶּאֱמַר (ישעיה סא-ח) \"שֹׂנֵא גָזֵל בְּעוֹלָה\" וְאֵין צָרִיךְ לוֹמַר שֶׁאֵינוֹ מִתְקַבֵּל. וְאִם נִתְיָאֲשׁוּ הַבְּעָלִים הַקָּרְבָּן כָּשֵׁר. וַאֲפִלּוּ הָיָה חַטָּאת שֶׁהַכֹּהֲנִים אוֹכְלִין אֶת בְּשָׂרָהּ. וּמִפְּנֵי תַּקָּנַת מִזְבֵּחַ אָמְרוּ שֶׁהַחַטָּאת הַגְּזוּלָה אִם נוֹדְעָה לָרַבִּים אֵינָהּ מְכַפֶּרֶת אַף עַל פִּי שֶׁנִּתְיָאֲשׁוּ הַבְּעָלִים כְּדֵי שֶׁלֹּא יֹאמְרוּ מִזְבֵּחַ אוֹכֵל גְּזֵלוֹת וְכֵן הָעוֹלָה:","הַגּוֹנֵב עוֹלַת חֲבֵרוֹ וְהִקְרִיבָהּ סְתָם נִתְכַּפְּרוּ בָּהּ הַבְּעָלִים הָרִאשׁוֹנִים:","אֵין מְבִיאִין מְנָחוֹת וּנְסָכִים לֹא מִן הַטֶּבֶל וְלֹא מִן הֶחָדָשׁ קֹדֶם לָעֹמֶר וְלֹא מִן הַמְדֻמָּע וְאֵין צָרִיךְ לוֹמַר מֵעָרְלָה וְכִלְאֵי הַכָּרֶם מִפְּנֵי שֶׁהִיא מִצְוָה הַבָּאָה בַּעֲבֵרָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׂוֹנְאָהּ. וְאִם הֵבִיא לֹא נִתְקַדְּשׁוּ לִהְיוֹתָן רְאוּיִין לְקָרְבָּן אֲבָל נִתְקַדְּשׁוּ לְהִפָּסֵל וְיִהְיוּ כְּקָדָשִׁים שֶׁנִּפְסְלוּ:","כָּל הַמְּנָחוֹת אֵין מְבִיאִין אוֹתָן מִן הֶחָדָשׁ קֹדֶם שְׁתֵּי הַלֶּחֶם לְכַתְּחִלָּה שֶׁהֲרֵי נֶאֱמַר בָּהֶן (ויקרא ב-יד) (ויקרא כג-יז) \"בִּכּוּרִים לַה'\". וְאִם הֵבִיא כָּשֵׁר. וּמְבִיאִים נְסָכִים מִן הַמֻּקְצֶה בְּיוֹם טוֹב:","מִצְוַת עֲשֵׂה לִמְלֹחַ כָּל הַקָּרְבָּנוֹת קֹדֶם שֶׁיַּעֲלוּ לַמִּזְבֵּחַ שֶׁנֶּאֱמַר (ויקרא ב׳:י״ג) \"עַל כָּל קָרְבָּנְךָ תַּקְרִיב מֶלַח\". וְאֵין לְךָ דָּבָר שֶׁקָּרֵב לַמִּזְבֵּחַ בְּלֹא מֶלַח חוּץ מִיֵּין הַנְּסָכִים וְהַדָּם וְהָעֵצִים. וְדָבָר זֶה קַבָּלָה וְאֵין לוֹ מִקְרָא לִסְמֹךְ עָלָיו. וּמִצְוָה לִמְלֹחַ הַבָּשָׂר יָפֶה יָפֶה כְּמוֹלֵחַ בָּשָׂר לְצָלִי שֶׁמְּהַפֵּךְ אֶת הָאֵיבָר וּמוֹלֵחַ. וְאִם מָלַח כָּל שֶׁהוּא אֲפִלּוּ בְּגַרְגִּיר מֶלַח אֶחָד כָּשֵׁר:","הִקְרִיב בְּלֹא מֶלַח כְּלָל לוֹקֶה שֶׁנֶּאֱמַר (ויקרא ב׳:י״ג) \"וְלֹא תַשְׁבִּית מֶלַח בְּרִית אֱלֹהֶיךָ\". וְאַף עַל פִּי שֶׁלּוֹקֶה הַקָּרְבָּן כָּשֵׁר וְהֻרְצָה. חוּץ מִן הַמִּנְחָה שֶׁהַמֶּלַח מְעַכֵּב בַּקְּמִיצָה שֶׁנֶּאֱמַר \"וְלֹא תַשְׁבִּית מֶלַח בְּרִית אֱלֹהֶיךָ מֵעַל מִנְחָתֶךָ\":","הַמֶּלַח שֶׁמּוֹלְחִין בּוֹ כָּל הַקָּרְבָּנוֹת מִשֶּׁל צִבּוּר כְּמוֹ הָעֵצִים. וְאֵין הַיָּחִיד מֵבִיא מֶלַח אוֹ עֵצִים לְקָרְבָּנוֹ מִבֵּיתוֹ. וּבִשְׁלֹשָׁה מְקוֹמוֹת הָיוּ נוֹתְנִין הַמֶּלַח. בְּלִשְׁכַּת הַמֶּלַח. וְעַל גַּבֵּי הַכֶּבֶשׁ. וּבְרֹאשׁוֹ שֶׁל מִזְבֵּחַ. בְּלִשְׁכַּת הַמֶּלַח הָיוּ מוֹלְחִין עוֹרוֹת הַקָּדָשִׁים. וְעַל גַּבֵּי הַכֶּבֶשׁ מוֹלְחִין הָאֵיבָרִים. וּבְרֹאשׁוֹ שֶׁל מִזְבֵּחַ מוֹלְחִין הַקֹּמֶץ וְהַלְּבוֹנָה וּמְנָחוֹת הַנִּשְׂרָפוֹת וְעוֹלַת הָעוֹף:"],"Mishneh Torah, Those Who Defile Bed or Seat 6":["כְּבָר בֵּאַרְנוּ שֶׁהַזָּב וַחֲבֵרָיו מְטַמְּאִין מִשְׁכָּב וּמוֹשָׁב וּמֶרְכָּב. וְהַמִּשְׁכָּב וְהַמּוֹשָׁב אֶחָד הוּא וְלָמָּה נֶאֱמַר בַּתּוֹרָה (ויקרא טו ד) \"מִשְׁכָּב וּמוֹשָׁב\" שֶׁהַמִּשְׁכָּב הָרָאוּי לִשְׁכִיבָה וְהַמּוֹשָׁב הָרָאוּי לִישִׁיבָה. וּבֵין שֶׁיָּשַׁב עַל הַמִּשְׁכָּב אוֹ שֶׁשָּׁכַב עַל הַמּוֹשָׁב טִמְּאָהוּ לְפִיכָךְ אֲנִי אוֹמֵר בְּכָל מָקוֹם מִשְׁכָּב לְבַד וְהוּא הַדִּין לְמוֹשָׁב. וְאֵי זֶהוּ מֶרְכָּב זֶה הָרָאוּי לִרְכִיבָה כְּגוֹן מִרְדַּעַת הַחֲמוֹר וְטַפִּיטָן הַסּוּס:","הַמִּשְׁכָּב וְהַמֶּרְכָּב כָּל אֶחָד מֵהֶן אָב מֵאֲבוֹת הַטֻּמְאוֹת שֶׁל תּוֹרָה מְטַמְּאִין אָדָם וְכֵלִים בְּמַגָּע וּמְטַמְּאִין אֶת הָאָדָם בְּמַשָּׂא. וּמַה בֵּין מִשְׁכָּב לְמֶרְכָּב שֶׁהַנּוֹגֵעַ בְּמִשְׁכָּב אִם הָיָה אָדָם וְנָגַע בִּבְגָדִים וּבִשְׁאָר כֵּלִים עַד שֶׁלֹּא פֵּרַשׁ מִמְּטַמְּאָיו הֲרֵי זֶה טִמְּאָם וַעֲשָׂאָן רִאשׁוֹן לְטֻמְאָה וְהַנּוֹגֵעַ בְּמֶרְכָּב אֵינוֹ מְטַמֵּא בְּגָדִים וְלֹא כֵּלִים אֲפִלּוּ בִּשְׁעַת מַגָּעוֹ אֲבָל הַנּוֹשֵׂא אֶת הַמִּשְׁכָּב אוֹ אֶת הַמֶּרְכָּב הֲרֵי זֶה מְטַמֵּא בְּגָדִים וּשְׁאָר כֵּלִים בִּשְׁעַת נְשִׂיאָתוֹ עַד שֶׁלֹּא פֵּרֵשׁ מִמְּטַמְּאָיו. וּמִנַּיִן שֶׁבְּטֻמְאַת מֶרְכָּב חָלַק מַגָּעוֹ מִמַּשָּׂאוֹ וּבְמִשְׁכָּב לֹא חָלַק. שֶׁהֲרֵי הוּא אוֹמֵר בְּמִשְׁכָּב (ויקרא טו ה) \"וְאִישׁ אֲשֶׁר יִגַּע בְּמִשְׁכָּבוֹ יְכַבֵּס בְּגָדָיו\" וּבְמֶרְכָּב הוּא אוֹמֵר (ויקרא טו ט) \"וְכָל הַמֶּרְכָּב אֲשֶׁר יִרְכַּב עָלָיו\" (ויקרא טו י) \"וְכָל הַנֹּגֵעַ בְּכל אֲשֶׁר יִהְיֶה תַחְתָּיו יִטְמָא עַד הָעָרֶב\". וְלֹא נֹאמַר בּוֹ יְכַבֵּס בְּגָדָיו מְלַמֵּד שֶׁאֵינוֹ מְטַמֵּא בְּגָדִים בִּשְׁעַת מַגָּעוֹ וְנֶאֱמַר (ויקרא טו י) \"וְהַנּוֹשֵׂא אוֹתָם יְכַבֵּס בְּגָדָיו\" אֶחָד הַנּוֹשֵׂא אֶת הַמֶּרְכָּב אוֹ הַנּוֹשֵׂא מִשְׁכָּב מְטַמֵּא בְּגָדִים בִּשְׁעַת נְשִׂיאָתוֹ. נִמְצֵאתָ לָמֵד שֶׁהַזָּב וְהַזָּבָה וְהַנִּדָּה וְהַיּוֹלֶדֶת וּמִשְׁכָּבָן וְרֻקָּן וּמֵימֵי רַגְלֵיהֶן וְדַם נִדָּה וְזָבָה וְיוֹלֶדֶת וְזוֹבוֹ שֶׁל זָב כָּל אֶחָד מֵאֵלּוּ אָב. וְאָדָם שֶׁנָּגַע בְּאֶחָד מִכָּל אֵלּוּ אוֹ נְשָׂאָן מְטַמֵּא בְּגָדִים וּשְׁאָר כֵּלִים בִּשְׁעַת נְגִיעָתוֹ אוֹ בִּשְׁעַת נְשִׂיאָתוֹ. וְאֵינוֹ מְטַמֵּא לֹא אָדָם וְלֹא כְּלֵי חֶרֶשׂ. שֶׁכָּל הַמְטַמֵּא אָדָם מְטַמֵּא כְּלֵי חֶרֶשׂ וְכָל שֶׁאֵינוֹ מְטַמֵּא אָדָם אֵינוֹ מְטַמֵּא כְּלֵי חֶרֶשׂ. הִנֵּה לָמַדְתָּ שֶׁכָּל טָמֵא שֶׁנֶּאֱמַר בּוֹ יְכַבֵּס בְּגָדָיו הֲרֵי זֶה מְטַמֵּא בְּגָדִים שֶׁיִּגַּע בָּהֶם כָּל זְמַן שֶׁלֹּא פֵּרַשׁ מִמְּטַמְּאָיו וְעוֹשֶׂה אוֹתָן רִאשׁוֹן לְטֻמְאָה כָּמוֹהוּ. וּמְטַמֵּא שְׁאָר כֵּלִים כִּבְגָדִים. חוּץ מִכְּלִי חֶרֶשׂ שֶׁאֵינוֹ מְטַמֵּא לֹא אָדָם וְלֹא כְּלֵי חֶרֶשׂ אַף עַל פִּי שֶׁעֲדַיִן לֹא פֵּרַשׁ. וְכָל טָמֵא שֶׁלֹּא נֶאֱמַר בּוֹ יְכַבֵּס בְּגָדָיו הֲרֵי הוּא עַד שֶׁלֹּא פֵּרַשׁ כְּאַחַר שֶׁפֵּרַשׁ שֶׁאֵינוֹ מְטַמֵּא בְּגָדִים מִפְּנֵי שֶׁהוּא וָלָד וְאֵין צָרִיךְ לוֹמַר שֶׁאֵינוֹ מְטַמֵּא אָדָם וְלֹא כְּלֵי חֶרֶשׂ. וּלְפִיכָךְ הַנּוֹגֵעַ בְּמֶרְכָּב אֵינוֹ מְטַמֵּא בְּגָדִים בִּשְׁעַת מַגָּעוֹ וְהַנּוֹשֵׂא אֶת הַמֶּרְכָּב מְטַמֵּא בְּגָדִים בִּשְׁעַת נְשִׂיאָתוֹ כְּמוֹ שֶׁבֵּאַרְנוּ:","כָּל הַכֵּלִים שֶׁיִּנָּשְׂאוּ לְמַעְלָה מִן הַזָּב הֵם הַנִּקְרָאִין מַדָּף וְהֵם כֻּלָּם כְּכֵלִים שֶׁהוּא נוֹגֵעַ בָּהֶם שֶׁהֵם רִאשׁוֹן לְטֻמְאָה וְאֵינָן מְטַמְּאִין לֹא אָדָם וְלֹא כֵּלִים אֲבָל מְטַמְּאִין אֳכָלִין וּמַשְׁקִין כִּשְׁאָר וַלְדוֹת הַטֻּמְאָה. וְטֻמְאַת מַדָּף מִדִּבְרֵיהֶם:","הַזָּב וְהַזָּבָה וְהַנִּדָּה וְהַיּוֹלֶדֶת וְהַמְצֹרָע שֶׁמֵּתוּ הֲרֵי הֵן מְטַמְּאִין מִשְׁכָּב וּמֶרְכָּב אַחַר מִיתָתָן כְּשֶׁהָיוּ כְּשֶׁהֵן חַיִּין עַד שֶׁיִּמֹּק הַבָּשָׂר. וְטֻמְאָה זוֹ מִדִּבְרֵיהֶם גְּזֵרָה שֶׁמָּא יִתְעַלֵּף אֶחָד מֵאֵלּוּ וִידַמּוּ שֶׁמֵּת וְהוּא עֲדַיִן לֹא מֵת. נִמְצָא מִשְׁכָּבוֹ וּמֶרְכָּבוֹ שֶׁל אַחַר מִיתָה אַב טֻמְאָה שֶׁל דִּבְרֵי סוֹפְרִים. אֲבָל נָכְרִי שֶׁמֵּת אֵינוֹ עוֹשֶׂה מִשְׁכָּב שֶׁהֲרֵי כְּשֶׁהוּא חַי אֵינוֹ מְטַמֵּא אֶלָּא מִדִּבְרֵיהֶם כְּמוֹ שֶׁבֵּאַרְנוּ:","כָּל מָקוֹם שָׁאַתָּה שׁוֹמֵעַ טֻמְאַת מִשְׁכָּב וּמֶרְכָּב אֵינוֹ שֶׁיִּגַּע הַטָּמֵא בַּמִּשְׁכָּב אוֹ בַּמֶּרְכָּב כְּשֶׁיִּנָּשֵׂא עֲלֵיהֶן אֶלָּא אֲפִלּוּ הָיוּ אֲבָנִים גְּדוֹלוֹת לְמַעְלָה מִן הַכְּלִי הֶעָשׂוּי לְמִשְׁכָּב אוֹ לְמֶרְכָּב וְנִשָּׂא הַזָּב עַל הָאֲבָנִים מִלְּמַעְלָה נִטְמָא הַמִּשְׁכָּב אוֹ הַמֶּרְכָּב וְנַעֲשָׂה אַב טֻמְאָה אֲפִלּוּ אֶלֶף מִשְׁכָּב אוֹ מֶרְכָּב זֶה לְמַעְלָה מִזֶּה וְאֶבֶן עַל הָעֶלְיוֹן וְיָשַׁב אֶחָד מִמְּטַמְּאֵי מִשְׁכָּב וּמוֹשָׁב לְמַעְלָה מִן הָאֶבֶן נִטְמְאוּ הַכּל. וְאֶחָד הַמִּשְׁכָּב הַנּוֹגֵעַ בָּאָרֶץ אוֹ הַמִּשְׁכָּב שֶׁל מַעְלָה אִם נָגַע בּוֹ בִּשְׁעַת שְׁכִיבָתוֹ כָּל אֶחָד מֵהֶן אַב הַטֻּמְאָה. וְכֵן אִם הָיָה אֶחָד מִמְּטַמְּאֵי מִשְׁכָּב וּמוֹשָׁב לְמַטָּה וְאֶבֶן עַל גַּבָּיו וָאֳכָלִין וּמַשְׁקִין וְכֵלִים וְאָדָם עַל גַּבֵּי הָאֶבֶן זֶה לְמַעְלָה מִזֶּה כֻּלָּן טְמֵאִין וְרִאשׁוֹן לְטֻמְאָה. וְאֶחָד כְּלִי אוֹ אֹכֶל וּמַשְׁקֶה אוֹ אָדָם הַנּוֹגֵעַ בְּזָב. אוֹ כְּלִי אוֹ אֹכֶל וּמַשְׁקֶה אוֹ אָדָם שֶׁהוּא לְמַעְלָה עַל הָאֶבֶן שֶׁעַל גַּבָּיו. הַכּל וְלַד טֻמְאָה. וְאֵינוֹ מְטַמֵּא לֹא אָדָם וְלֹא כֵּלִים חוּץ מִן הָאָדָם שֶׁעַל גַּבֵּי הַזָּב שֶׁעַד שֶׁלֹּא פֵּרַשׁ מִמְּטַמְּאָיו מְטַמֵּא שְׁאָר כֵּלִים כְּמוֹ שֶׁבֵּאַרְנוּ:","הָאֳכָלִים וְהַמַּשְׁקִין וְהַכֵּלִים שֶׁאֵינָן עֲשׂוּיִם לֹא לְמִשְׁכָּב וְלֹא לְמוֹשָׁב וְלֹא לְמֶרְכָּב שֶׁהָיוּ לְמַטָּה וְיָשַׁב הַזָּב וְכַיּוֹצֵא בּוֹ עֲלֵיהֶם לְמַעְלָה וְלֹא נָגְעוּ בָּהֶן כֻּלָּן טְהוֹרִין. אֲבָל אִם הָיָה הָאָדָם לְמַטָּה וְהַזָּב לְמַעְלָה אַף עַל פִּי שֶׁאֵינוֹ נוֹגֵעַ בּוֹ הֲרֵי זֶה טָמֵא מִשּׁוּם נוֹשֵׂא זָב. כְּכָל נוֹשֵׂא דָּבָר שֶׁמְּטַמֵּא בְּמַשָּׂא שֶׁהַנּוֹשֵׂא רִאשׁוֹן לְטֻמְאָה. הָא לָמַדְתָּ שֶׁכָּל שֶׁיִּהְיֶה לְמַעְלָה מִן הַזָּב טָמֵא בֵּין אָדָם וּבֵין כֵּלִים הָעֲשׂוּיִין לְמִשְׁכָּב וּלְמוֹשָׁב וּלְמֶרְכָּב בֵּין שְׁאָר כָּל הַכֵּלִים בֵּין אֳכָלִים בֵּין מַשְׁקִין הַכּל רִאשׁוֹן לְטֻמְאָה. וְכָל שֶׁיִּהְיֶה לְמַטָּה מִן הַזָּב וְלֹא יִגַּע בּוֹ טָהוֹר. חוּץ מִן הָאָדָם אוֹ כְּלִי הֶעָשׂוּי לְמִשְׁכָּב אוֹ לְמוֹשָׁב אוֹ לְמֶרְכָּב. אֶלָּא שֶׁהָאָדָם רִאשׁוֹן וְהַכֵּלִים הָעֲשׂוּיִים לְמוֹשָׁב אוֹ לְמִשְׁכָּב אוֹ לְמֶרְכַּב אַב הַטֻּמְאָה כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Tithes 4":["אֵין הַטֶּבֶל נִקְבָּע לְמַעַשְׂרוֹת מִן הַתּוֹרָה עַד שֶׁיַּכְנִיסֶנּוּ לְבֵיתוֹ שֶׁנֶּאֱמַר (דברים כו יג) \"בִּעַרְתִּי הַקֹּדֶשׁ מִן הַבַּיִת\". וְהוּא שֶׁיַּכְנִיסֶנּוּ דֶּרֶךְ הַשַּׁעַר שֶׁנֶּאֱמַר (דברים כו יב) \"וְאָכְלוּ בִשְׁעָרֶיךָ\". אֲבָל אִם הִכְנִיס תְּבוּאָתוֹ דֶּרֶךְ גַּגּוֹת וְקַרְפִּיפוֹת פָּטוּר מִן הַתְּרוּמָה וּמִן הַמַּעַשְׂרוֹת:","יֵרָאֶה לִי שֶׁאֵין לוֹקִין מִן הַתּוֹרָה עַל אֲכִילַת הַטֶּבֶל עַד שֶׁיִּקָבַע בִּכְנִיסָתוֹ לְבֵיתוֹ כְּמוֹ שֶׁבֵּאַרְנוּ מִפִּי הַשְּׁמוּעָה. אֲבָל אִם נִקְבַּע בִּשְׁאָר הַשִּׁשָּׁה דְּבָרִים שֶׁמָּנִינוּ אֵין לוֹקִין עָלָיו אֶלָּא מַכַּת מַרְדּוּת מִדִּבְרֵיהֶן. וְכֵן הָאוֹכֵל מִפֵּרוֹת שֶׁדַּעְתּוֹ לְהוֹלִיכָן לַשּׁוּק אַחַר שֶׁנִּגְמְרָה מְלַאכְתָּן אֵינוֹ לוֹקֶה אֶלָּא מַכַּת מַרְדּוּת כְּמוֹ שֶׁבֵּאַרְנוּ. שֶׁאֵין הַגּוֹמֵר לִמְכֹּר חַיָּב בְּמַעֲשֵׂר אֶלָּא מִדִּבְרֵיהֶם:","בַּיִת שֶׁאֵין בּוֹ אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת אֵינוֹ קוֹבֵעַ וְכֵן הַגַּגִּים אֵינָן קוֹבְעִין אַף עַל פִּי שֶׁהַבַּיִת שֶׁלְּמַטָּה קוֹבֵעַ. וְאִם לֹא הָיָה בַּגַּג אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת כְּגוֹן שֶׁהָיָה הַבַּיִת מְשֻׁפָּע וְעוֹלֶה אֵינוֹ פּוֹטֵר מִן הַמַּעֲשֵׂר אֶלָּא הֲרֵי גַּג זֶה כְּמִקְצָת אֲוִיר הַבַּיִת:","הַצְּרִיפִין וְהַבֻּרְגָּנִין וּבָתֵּי הַקַּיִץ וְהוּא אַרְבָּעָה עַמּוּדִים וְתִקְרָה עַל גַּבֵּיהֶן שֶׁנִּמְצָא בְּלֹא כְּתָלִים וְכֵן סֻכּוֹת שֶׁעוֹשִׂין בְּנֵי הַכְּרָמִים וּבְנֵי הַגִּנּוֹת בִּימֵי הַקַּיִץ אַף עַל פִּי שֶׁדָּרִין בָּהֶן כָּל יְמֵי הַקַּיִץ וְיֵשׁ בָּהֶם רֵחַיִם וְתַרְנְגוֹלִין אֵינָן קוֹבְעִין לְמַעֲשֵׂר. וְכֵן סֻכַּת הַיּוֹצְרִים הַחִיצוֹנָה וְסֻכַּת הֶחָג בֶּחָג אֵינָן קוֹבְעִין שֶׁכָּל אֵלּוּ אֵין דִּירָתָן קֶבַע:","הַצְּרִיפִין וְהַבֻּרְגָּנִין טוֹבְלִין לְבַעְלֵיהֶן אַף עַל פִּי שֶׁאֵינָן טוֹבְלִין לְכָל אָדָם וְכֵן בֵּית הַסֵּפֶר וּבֵית הַמִּדְרָשׁ טוֹבֵל לְזֶה שֶׁיּוֹשֵׁב וּמְלַמֵּד מִפְּנֵי שֶׁהֵם כְּבֵיתוֹ וְאֵין טוֹבְלִין לַאֲחֵרִים:","בֵּית הַכְּנֶסֶת וּבֵית הַמִּדְרָשׁ אִם יֵשׁ בָּהֶן בֵּית דִּירָה קוֹבְעִין וְאִם לָאו אֵין קוֹבְעִין. הָאוֹרִיאֲרוֹת הָאוֹצָרוֹת שֶׁבַּשָּׂדוֹת הָעֲשׂוּיוֹת לִמְכֻנָּס אֵינָן קוֹבְעִין וְאִם הָיוּ לְדִירָה קוֹבְעִין:","כְּשֵׁם שֶׁהַבַּיִת קוֹבֵעַ לְמַעֲשֵׂר כָּךְ הֶחָצֵר קוֹבַעַת לְמַעֲשֵׂר. וּמִשֶּׁיִּכָּנְסוּ לֶחָצֵר דֶּרֶךְ הַשַּׁעַר נִקְבְּעוּ אַף עַל פִּי שֶׁלֹּא הִכְנִיסָן לְתוֹךְ הַבַּיִת:","אֵי זוֹ הִיא חָצֵר הַקּוֹבַעַת. כָּל שֶׁהַכֵּלִים נִשְׁמָרִין בְּתוֹכָהּ. אוֹ שֶׁאֵין אָדָם בּוֹשׁ מִלֶּאֱכל בְּתוֹכָהּ. אוֹ חָצֵר שֶׁאִם יִכָּנֵס אָדָם לָהּ אוֹמְרִין לוֹ מָה אַתָּה מְבַקֵּשׁ. וְכֵן חָצֵר שֶׁיֵּשׁ בָּהּ שְׁנֵי דִּיּוּרִין אוֹ שֶׁהִיא לִשְׁנֵי שֻׁתָּפִין שֶׁאֶחָד פּוֹתְחָהּ וְנִכְנָס וְאֶחָד בָּא וְנִכְנָס אוֹ יוֹצֵא וְנוֹעֵל הוֹאִיל וְהֵן פּוֹתְחִין וְנוֹעֲלִין הֲרֵי זוֹ קוֹבַעַת:","בֵּית שַׁעַר שֶׁל חָצֵר וְהָאַכְסַדְרָה וְהַמִּרְפֶּסֶת הֲרֵי הֵן כְּחָצֵר אִם הָיְתָה קוֹבַעַת קוֹבְעִין וְאִם לָאו אֵינָן קוֹבְעִין:","שְׁתֵּי חֲצֵרוֹת זוֹ לְפָנִים מִזּוֹ שְׁתֵּיהֶן קוֹבְעוֹת. סֻכַּת הַיּוֹצְרִים זוֹ לְפָנִים מִזּוֹ הַפְּנִימִית קוֹבַעַת וְהַחִיצוֹנָה אֵינָהּ קוֹבַעַת וְהַחֲנוּת קוֹבַעַת כְּבַיִת:","הַמּוֹלִיךְ פֵּרוֹתָיו מִמָּקוֹם לְמָקוֹם אַף עַל פִּי שֶׁהוּא נִכְנָס בָּהֶן לְבָתִּים וְלַחֲצֵרוֹת בַּדֶּרֶךְ לֹא נִקְבְּעוּ אֶלָּא אוֹכֵל עַרְאַי עַד שֶׁיַּגִּיעַ לְמָקוֹם שֶׁהוּא סוֹף מְגַמָּתוֹ וְכֵן בַּחֲזָרָה:","הָרוֹכְלִין הַמַּחְזִירִין בַּעֲיָרוֹת שֶׁהֵן נִכְנָסִין מֵחָצֵר לְחָצֵר אוֹכְלִין עַרְאַי עַד שֶׁמַּגִּיעִין לְבַיִת שֶׁלָּנִין בּוֹ:","הַמֵּבִיא תְּאֵנִים מִן הַשָּׂדֶה לְאָכְלָן בֶּחָצֵר הַפְּטוּרָה מִן הַמַּעַשְׂרוֹת. שָׁכַח וְהִכְנִיסָן לְתוֹךְ בֵּיתוֹ הֲרֵי זֶה מֻתָּר לְהוֹצִיאָן וְלֶאֱכל מֵהֶן עַרְאַי וְכֵן אִם שָׁכַח וְהֶעֱלָן לַגַּג אוֹכֵל מֵהֶן בַּגַּג עַרְאַי. הֱבִיאָן לְאָכְלָן בְּרֹאשׁ גַּגּוֹ וְשָׁכַח וְהִכְנִיסָן לְתוֹךְ חֲצַר חֲבֵרוֹ נִקְבְּעוּ וְלֹא יֹאכַל עַד שֶׁיְּעַשֵּׂר:","חָצֵר שֶׁהִיא נֶעְדֶּרֶת הֲרֵי הִיא כְּגִנָּה וְאוֹכְלִין בְּתוֹכָהּ עַרְאַי. וְהוּא שֶׁיֵּעָדֵר רֻבָּהּ. וְאִם זָרַע רֻבָּהּ אֵין אוֹכְלִין עַרְאַי וְכֵן אִם נָטַע רֻבָּהּ. וְאִם נָטַע לְנוֹי חָצֵר הוֹאִיל וְהִיא נֶעְדֶּרֶת הֲרֵי זֶה אוֹכֵל עַרְאַי מֵאוֹתָן אִילָנוֹת:","תְּאֵנָה הָעוֹמֶדֶת בֶּחָצֵר אוֹכֵל מִמֶּנָּה אַחַת אַחַת וּפָטוּר. וְאִם צֵרֵף חַיָּב בְּמַעֲשֵׂר. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיָה עוֹמֵד בַּקַּרְקַע. אֲבָל אִם עָלָה לְרֹאשׁ הַתְּאֵנָה מְמַלֵּא חֵיקוֹ וְאוֹכֵל שָׁם שֶׁאֵין אֲוִיר חָצֵר קוֹבֵעַ לְמַעֲשֵׂר:","הָיְתָה עוֹמֶדֶת בְּחָצֵר וְנוֹטָה לְגִנָּה הֲרֵי זֶה אוֹכֵל מִמֶּנָּה בַּגִּנָּה כְּדַרְכּוֹ כְּאִלּוּ הָיְתָה נְטוּעָה בַּגִּנָּה. הָיְתָה נְטוּעָה בַּגִּנָּה וְנוֹטָה לְחָצֵר הֲרֵי זוֹ כִּנְטוּעָה בֶּחָצֵר שֶׁאֵינוֹ אוֹכֵל שָׁם אֶלָּא אַחַת [אַחַת]:","גֶּפֶן שֶׁנְּטוּעָה בֶּחָצֵר לֹא יִטּל אֶת כָּל הָאֶשְׁכּוֹל וְיֹאכַל אֶלָּא מְגַרְגֵּר אֶחָד אֶחָד. וְכֵן בְּרִמּוֹן לֹא יִטּל אֶת כָּל הָרִמּוֹן אֶלָּא פּוֹרֵט אֶת הָרִמּוֹן בָּאִילָן וְאוֹכֵל הַפֶּרֶד מִשָּׁם. וְכֵן בָּאֲבַטִּיחַ כּוֹפְתוֹ בַּקַּרְקַע וְאוֹכְלוֹ שָׁם. הָיָה אוֹכֵל בְּאֶשְׁכּוֹל בַּגִּנָּה וְנִכְנַס מִן הַגִּנָּה לֶחָצֵר אַף עַל פִּי שֶׁיָּצָא מִן הֶחָצֵר לֹא יִגְמֹר עַד שֶׁיְּעַשֵּׂר:","כֻּסְבַּר הַזְּרוּעָה בֶּחָצֵר מְקַרְסֵם עָלֶה עָלֶה וְאוֹכְלוֹ. וְאִם צֵרֵף חַיָּב לְעַשֵּׂר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Torah Study 7":["חָכָם זָקֵן בְּחָכְמָה וְכֵן נָשִׂיא אוֹ אַב בֵּית דִּין שֶׁסָּרַח אֵין מְנַדִּין אוֹתוֹ בְּפַרְהֶסְיָא לְעוֹלָם. אֶלָּא אִם כֵּן עָשָׂה כְּיָרָבְעָם בֶּן נְבָט וַחֲבֵרָיו. אֲבָל כְּשֶׁחָטָא שְׁאָר חַטָּאוֹת מַלְקִין אוֹתוֹ בְּצִנְעָה. שֶׁנֶּאֱמַר (הושע ד ה) \"וְכָשַׁלְתָּ הַיּוֹם וְכָשַׁל גַּם נָבִיא עִמְּךָ לָיְלָה\" אַף עַל פִּי שֶׁכָּשַׁל כַּסֵּהוּ כְּלַיְלָה. וְאוֹמְרִים לוֹ הִכָּבֵד וְשֵׁב בְּבֵיתְךָ. וְכֵן כָּל תַּלְמִיד חָכָם שֶׁנִּתְחַיֵּב נִדּוּי אָסוּר לְבֵית דִּין לִקְפֹּץ וּלְנַדּוֹתוֹ בִּמְהֵרָה אֶלָּא בּוֹרְחִין מִדָּבָר זֶה וְנִשְׁמָטִין מִמֶּנּוּ. וַחֲסִידֵי הַחֲכָמִים הָיוּ מִשְׁתַּבְּחִים שֶׁלֹּא נִמְנוּ מֵעוֹלָם לְנַדּוֹת תַּלְמִיד חָכָם אַף עַל פִּי שֶׁנִּמְנִין לְהַלְקוֹתוֹ אִם נִתְחַיֵּב מַלְקוֹת. וַאֲפִלּוּ מַכַּת מַרְדּוּת נִמְנִין עָלָיו לְהַכּוֹתוֹ:","וְכֵיצַד הוּא הַנִּדּוּי, אוֹמֵר פְּלוֹנִי יְהֵא בְּשַׁמָּתָא. וְאִם נִדּוּהוּ בְּפָנָיו אוֹמֵר לוֹ פְּלוֹנִי זֶה בְּשַׁמָּתָא. וְהַחֵרֶם, אוֹמֵר לוֹ פְּלוֹנִי מֻחְרָם. וְאָרוּר בּוֹ אָלָה בּוֹ שְׁבוּעָה בּוֹ נִדּוּי:","וְכֵיצַד מַתִּירִין הַנִּדּוּי אוֹ הַחֵרֶם. אוֹמֵר לוֹ שָׁרוּי לְךָ וּמָחוּל לְךָ. וְאִם הִתִּירוּהוּ שֶׁלֹּא בְּפָנָיו אוֹמֵר לוֹ פְּלוֹנִי שָׁרוּי לוֹ וּמָחוּל לוֹ:","מַהוּ הַמִּנְהָג שֶׁיִּנְהֹג הַמְנֻדֶּה בְּעַצְמוֹ וְשֶׁנּוֹהֲגִין עִמּוֹ. מְנֻדֶּה אָסוּר לְסַפֵּר וּלְכַבֵּס כְּאָבֵל כָּל יְמֵי נִדּוּיוֹ. וְאֵין מְזַמְּנִין עָלָיו. וְלֹא כּוֹלְלִין אוֹתוֹ בַּעֲשָׂרָה לְכָל דָּבָר שֶׁצָּרִיךְ עֲשָׂרָה. וְלֹא יוֹשְׁבִין עִמּוֹ בְּאַרְבַּע אַמּוֹת. אֲבָל שׁוֹנֶה הוּא לַאֲחֵרִים וְשׁוֹנִין לוֹ וְנִשְׂכָּר וְשׂוֹכֵר. וְאִם מֵת בְּנִדּוּי בֵּית דִּין שׁוֹלְחִין וּמַנִּיחִין אֶבֶן עַל אֲרוֹנוֹ כְּלוֹמַר שֶׁהֵן רוֹגְמִין אוֹתוֹ לְפִי שֶׁהוּא מֻבְדָּל מִן הַצִּבּוּר. וְאֵין צָרִיךְ לוֹמַר שֶׁאֵין מַסְפִּידִין אוֹתוֹ וְאֵין מְלַוִּין אֶת מִטָּתוֹ:","יוֹתֵר עָלָיו הַמֻּחְרָם שֶׁאֵינוֹ שׁוֹנֶה לַאֲחֵרִים וְאֵין שׁוֹנִין לוֹ אֲבָל שׁוֹנֶה הוּא לְעַצְמוֹ שֶׁלֹּא יִשְׁכַּח תַּלְמוּדוֹ. וְאֵינוֹ נִשְׂכָּר וְאֵין נִשְׂכָּרִין לוֹ. וְאֵין נוֹשְׂאִין וְנוֹתְנִין עִמּוֹ. וְאֵין מִתְעַסְּקִין עִמּוֹ אֶלָּא מְעַט עֵסֶק כְּדֵי פַּרְנָסָתוֹ:","מִי שֶׁיָּשַׁב בְּנִדּוּי שְׁלֹשִׁים יוֹם וְלֹא בִּקֵּשׁ לְהַתִּירוֹ מְנַדִּין אוֹתוֹ שְׁנִיָּה. יָשַׁב שְׁלֹשִׁים יוֹם אֲחֵרִים וְלֹא בִּקֵּשׁ לְהַתִּירוֹ מַחְרִימִין אוֹתוֹ:","בְּכַמָּה מַתִּירִין הַנִּדּוּי אוֹ הַחֵרֶם. בִּשְׁלֹשָׁה אֲפִלּוּ הֶדְיוֹטוֹת. וְיָחִיד מֻמְחֶה מַתִּיר הַנִּדּוּי אוֹ הַחֵרֶם לְבַדּוֹ. וְיֵשׁ לְתַלְמִיד לְהַתִּיר הַנִּדּוּי אוֹ הַחֵרֶם וַאֲפִלּוּ בִּמְקוֹם הָרַב:","שְׁלֹשָׁה שֶׁנִּדּוּ וְהָלְכוּ לָהֶן וְחָזַר זֶה מִדָּבָר שֶׁנִּדּוּהוּ בִּגְלָלוֹ בָּאִין שְׁלֹשָׁה אֲחֵרִים וּמַתִּירִין לוֹ:","מִי שֶׁלֹּא יָדַע מִי שֶׁנִּדָּהוּ יֵלֵךְ לוֹ אֵצֶל הַנָּשִׂיא וְיַתִּיר לוֹ נִדּוּיוֹ:","נִדּוּי עַל תְּנַאי אֲפִלּוּ עַל פִּי עַצְמוֹ צָרִיךְ הֲפָרָה. תַּלְמִיד חָכָם שֶׁנִּדָּה עַצְמוֹ וַאֲפִלּוּ נִדָּה עַצְמוֹ עַל דַּעַת פְּלוֹנִי וַאֲפִלּוּ עַל דָּבָר שֶׁחַיָּב עָלָיו נִדּוּי הֲרֵי זֶה מֵפֵר לְעַצְמוֹ:","מִי שֶׁנִּדּוּהוּ בַּחֲלוֹם אֲפִלּוּ יָדַע מִי נִדָּהוּ צָרִיךְ עֲשָׂרָה בְּנֵי אָדָם שֶׁשּׁוֹנִין הֲלָכוֹת לְהַתִּירוֹ מִנִּדּוּיוֹ. וְאִם לֹא מָצָא טוֹרֵחַ אַחֲרֵיהֶם עַד פַּרְסָא. לֹא מָצָא מַתִּירִים לוֹ אֲפִלּוּ עֲשָׂרָה שֶׁשּׁוֹנִים מִשְׁנָה. לֹא מָצָא מַתִּירִין לוֹ עֲשָׂרָה שֶׁיּוֹדְעִים לִקְרוֹת בַּתּוֹרָה. לֹא מָצָא מַתִּירִין לוֹ אֲפִלּוּ עֲשָׂרָה שֵׁאֵינָן יוֹדְעִין לִקְרוֹת. לֹא מָצָא בִּמְקוֹמוֹ עֲשָׂרָה מַתִּירִין לוֹ אֲפִלּוּ שְׁלֹשָׁה:","מִי שֶׁנִּדּוּהוּ בְּפָנָיו אֵין מַתִּירִין לוֹ אֶלָּא בְּפָנָיו. נִדּוּהוּ שֶׁלֹּא בְּפָנָיו מַתִּירִין לוֹ בְּפָנָיו וְשֶׁלֹּא בְּפָנָיו. וְאֵין בֵּין נִדּוּי לַהֲפָרָה כְּלוּם אֶלָּא מְנַדִּין וּמַתִּירִין בְּרֶגַע אֶחָד כְּשֶׁיַּחֲזֹר הַמְנֻדֶּה לַמּוּטָב. וְאִם רָאוּ בֵּית דִּין לְהַנִּיחַ זֶה בְּנִדּוּי כַּמָּה שָׁנִים מַנִּיחִין כְּפִי רִשְׁעוֹ. וְכֵן אִם רָאוּ בֵּית דִּין לְהַחֲרִים לָזֶה לְכַתְּחִלָּה וּלְהַחֲרִים מִי שֶׁיֹּאכַל עִמּוֹ וְשׁוֹתֶה עִמּוֹ אוֹ מִי שֶׁיַּעֲמֹד עִמּוֹ בְּאַרְבַּע אַמּוֹת מַחְרִימִין כְּדֵי לְיַסְּרוֹ וּכְדֵי לַעֲשׂוֹת סְיָג לַתּוֹרָה עַד שֶׁלֹּא יִפְרְצוּ הַחוֹטְאִים. אַף עַל פִּי שֶׁיֵּשׁ רְשׁוּת לֶחָכָם לְנַדּוֹת לִכְבוֹדוֹ אֵינוֹ שֶׁבַח לְתַלְמִיד חָכָם לְהַנְהִיג עַצְמוֹ בְּדָבָר זֶה אֶלָּא מַעֲלִים אָזְנָיו מִדִּבְרֵי עַם הָאָרֶץ וְלֹא יָשִׁית לִבּוֹ לָהֶן כָּעִנְיָן שֶׁאָמַר שְׁלֹמֹה בְּחָכְמָתוֹ (קהלת ז כא) \"גַּם לְכָל הַדְּבָרִים אֲשֶׁר יְדַבְּרוּ אַל תִּתֵּן לִבְּךָ\". וְכֵן הָיָה דֶּרֶךְ חֲסִידִים הָרִאשׁוֹנִים שׁוֹמְעִים חֶרְפָּתָם וְאֵינָן מְשִׁיבִין וְלֹא עוֹד אֶלָּא שֶׁמּוֹחֲלִים לַמְחָרֵף וְסוֹלְחִים לוֹ. וַחֲכָמִים גְּדוֹלִים הָיוּ מִשְׁתַּבְּחִים בְּמַעֲשֵׂיהֶם הַנָּאִים וְאוֹמְרִים שֶׁמֵּעוֹלָם לֹא נִדּוּ אָדָם וְלֹא הֶחְרִימוּהוּ לִכְבוֹדָן. וְזוֹ הִיא דַּרְכָּם שֶׁל תַּלְמִידֵי חֲכָמִים שֶׁרָאוּי לֵילֵךְ בָּהּ. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁבִּזָּהוּ אוֹ חֵרְפָהוּ בַּסֵּתֶר. אֲבָל תַּלְמִיד חָכָם שֶׁבִּזָּהוּ אוֹ חֵרְפוֹ אָדָם בְּפַרְהֶסְיָא אָסוּר לוֹ לִמְחל עַל כְּבוֹדוֹ וְאִם מָחַל נֶעֱנָשׁ שֶׁזֶּה בִּזְיוֹן תּוֹרָה אֶלָּא נוֹקֵם וְנוֹטֵר הַדָּבָר כְּנָחָשׁ עַד שֶׁיְּבַקֵּשׁ מִמֶּנּוּ מְחִילָה וְיִסְלַח לוֹ:"],"Mishneh Torah, Transmission of the Oral Law 2":["כָּל הַתּוֹרָה – כְּתָבָהּ מֹשֶׁה רַבֵּנוּ קֹדֶם שֶׁיָּמוּת, בִּכְתָב יָדוֹ. וְנָתַן סֵפֶר לְכָל שֵׁבֶט וְשֵׁבֶט; וְסֵפֶר אֶחָד – נְתָנָהוּ בָּאָרוֹן לְעֵד, שֶׁנֶּאֱמָר \"לָקֹחַ, אֵת סֵפֶר הַתּוֹרָה הַזֶּה, וְשַׂמְתֶּם אֹתוֹ, מִצַּד אֲרוֹן בְּרִית־ה' אֱלֹהֵיכֶם; וְהָיָה־שָׁם בְּךָ, לְעֵד\" (דברים לא, כו)."],"Mishneh Torah, Transmission of the Oral Law 30":["וְאַחַר בֵּית דִּינוֹ שֶׁלְּרָב אַשֵׁי, שֶׁחִבַּר הַתַּלְמוּד בִּימֵי בְּנוֹ וּגְמָרוֹ, נִתְפַּזְּרוּ יִשְׂרָאֵל בְּכָל הָאֲרָצוֹת פִּזּוּר יָתֵר, וְהִגִּיעוּ לַקְּצָווֹת וְלָאִיִּים הָרְחוֹקִים; וְרָבְתָה קְטָטָה בָּעוֹלָם, וְנִשְׁתַּבְּשׁוּ הַדְּרָכִים בִּגְיָסוֹת. וְנִתְמַעַט תַּלְמוּד תּוֹרָה, וְלֹא נִתְכַּנְּסוּ יִשְׂרָאֵל לִלְמֹד בִּישִׁיבוֹתֵיהֶם אֲלָפִים וּרְבָבוֹת כְּמוֹ שֶׁהָיוּ מִקֹּדֶם."],"Mishneh Torah, Transmission of the Oral Law 41":["וּמִפְּנֵי זֶה נָעַרְתִּי חָצְנִי, אֲנִי מֹשֶׁה בֵּירִבִּי מַיְמוֹן הַסְּפָרַדִּי, וְנִשְׁעַנְתִּי עַל הַצּוּר בָּרוּךְ הוּא, וּבִינוֹתִי בְּכָל אֵלּוּ הַסְּפָרִים; וְרָאִיתִי לְחַבַּר דְּבָרִים הַמִּתְבָּרְרִים מִכָּל אֵלּוּ הַחִבּוּרִין, בְּעִנְיַן הָאָסוּר וְהַמֻּתָּר וְהַטָּמֵא וְהַטָּהוֹר עִם שְׁאָר דִּינֵי תּוֹרָה: כֻּלָּן בְּלָשׁוֹן בְּרוּרָה וְדֶרֶךְ קְצָרָה, עַד שֶׁתְּהֶא תּוֹרָה שֶׁבְּעַל פֶּה כֻּלָּהּ סְדוּרָה בְּפִי הַכֹּל – בְּלֹא קֻשְׁיָה וְלֹא פֵּרוּק, וְלֹא זֶה אוֹמֵר בְּכֹה וְזֶה אוֹמֵר בְּכֹה, אֵלָא דְּבָרִים בְּרוּרִים קְרוֹבִים נְכוֹנִים, עַל פִּי הַמִּשְׁפָּט אֲשֶׁר יִתְבָּאַר מִכָּל אֵלּוּ הַחִבּוּרִין וְהַפֵּרוּשִׁין הַנִּמְצָאִים מִיְּמוֹת רַבֵּנוּ הַקָּדוֹשׁ וְעַד עַכְשָׁו."],"Mishneh Torah, Trespass 3":["קָדְשֵׁי מִזְבֵּחַ שֶׁמֵּתוּ יָצְאוּ מִידֵי מְעִילָה דְּבַר תּוֹרָה. אֲבָל מוֹעֲלִין בָּהֶן מִדִּבְרֵי סוֹפְרִים. וְכֵן אִם נִפְסְלוּ בִּדְבָרִים שֶׁיִּפָּסְלוּ בָּהֶן הַקָּרְבָּנוֹת שֶׁכְּבָר בֵּאַרְנוּם מוֹעֲלִין בָּהֶן מִדִּבְרֵי סוֹפְרִים. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁלֹּא הָיָה לָהֶן שְׁעַת הֶתֵּר לַאֲכִילַת כֹּהֲנִים. אֲבָל אִם הָיָה לְקָדְשֵׁי קָדָשִׁים הַנֶּאֱכָלִים שְׁעַת הֶתֵּר וְאַחַר כָּךְ נִפְסְלוּ וְנֶאֶסְרוּ בַּאֲכִילָה הוֹאִיל וְהֻתְּרוּ שָׁעָה אַחַת אֵין מוֹעֲלִין בְּאוֹתוֹ דָּבָר שֶׁהָיָה רָאוּי לַאֲכִילָה כְּמוֹ שֶׁבֵּאַרְנוּ. כֵּיצַד. קָדְשֵׁי קָדָשִׁים שֶׁנִּפְסְלוּ קֹדֶם שֶׁיַּגִּיעַ הַדָּם לַמִּזְבֵּחַ כְּהִלְכָתָן כְּגוֹן שֶׁשְּׁחָטָן בַּדָּרוֹם אַף עַל פִּי שֶׁקִּבֵּל בַּצָּפוֹן אוֹ שֶׁשְּׁחָטָן בַּצָּפוֹן וְקִבֵּל בַּדָּרוֹם. אוֹ שֶׁשָּׁחַט בַּיּוֹם וְזָרַק בַּלַּיְלָה אוֹ שֶׁשָּׁחַט בַּלַּיְלָה וְזָרַק בַּיּוֹם. אוֹ שֶׁעֲשָׂאָן בְּמַחְשֶׁבֶת הַזְּמַן אוֹ בְּמַחְשֶׁבֶת הַמָּקוֹם. אוֹ שֶׁקִּבְּלוּ הַפְּסוּלִין אֶת דָּמָן אַף עַל פִּי שֶׁזְּרָקוּהוּ כְּשֵׁרִים. אוֹ שֶׁזְּרָקוּהוּ פְּסוּלִין אַף עַל פִּי שֶׁקִּבְּלוּהוּ כְּשֵׁרִים. אוֹ שֶׁיָּצָא הַדָּם וְהַבָּשָׂר כֻּלּוֹ קֹדֶם זְרִיקַת הַדָּם. אוֹ שֶׁלָּן הַדָּם. בְּכָל אֵלּוּ מוֹעֲלִין בְּכֻלָּן לְעוֹלָם שֶׁהֲרֵי לֹא הָיָה לָהֶן שְׁעַת הֶתֵּר. אֲבָל אִם הִגִּיעַ הַדָּם לַמִּזְבֵּחַ כְּמִצְוָתוֹ וְאַחַר כָּךְ לָן הַבָּשָׂר אוֹ הָאֵימוּרִין. אוֹ שֶׁנִּטְמָא הַבָּשָׂר אוֹ הָאֵימוּרִין. אוֹ שֶׁיָּצָא הַבָּשָׂר אוֹ הָאֵימוּרִין לַחוּץ. אוֹ שֶׁיָּצָא מִקְצָת הַבָּשָׂר קֹדֶם זְרִיקַת דָּמִים. בְּכָל אֵלּוּ וְכַיּוֹצֵא בָּהֶן אֵין מוֹעֲלִין בִּשְׁאָר בְּשָׂרָן שֶׁהֲרֵי הָיָה לוֹ שְׁעַת הֶתֵּר לַאֲכִילָה כְּמוֹ שֶׁבֵּאַרְנוּ:","קִבְּלוּ הַפְּסוּלִין אֶת הַדָּם וּזְרָקוּהוּ וְחָזְרוּ הַכְּשֵׁרִים לַעֲבוֹדָה וְקִבְּלוּ שְׁאָר דַּם הַנֶּפֶשׁ וּזְרָקוּהוּ אֵין מוֹעֲלִין בִּבְשָׂרָן. שֶׁאֵין הַפְּסוּלִין עוֹשִׂין שְׁאָר דַּם הַנֶּפֶשׁ שְׁיָרִים חוּץ מִן הַטָּמֵא הוֹאִיל וְרָאוּי לַעֲבוֹדַת צִבּוּר עוֹשֶׂה שְׁאָר דָּם שְׁיָרִים:","כֵּיצַד. קִבֵּל הַטָּמֵא וְזָרַק אַף עַל פִּי שֶׁחָזַר הַכָּשֵׁר וְקִבֵּל שְׁאָר דַּם הַנֶּפֶשׁ וּזְרָקוֹ הֲרֵי אֵלּוּ לֹא הָיְתָה לָהֶן שְׁעַת הֶתֵּר וּמוֹעֲלִין בְּכֻלָּן שֶׁזֶּה הַדָּם שְׁיָרִים הוּא וְאֵין זְרִיקַת הַשְּׁיָרִים מוֹעֶלֶת. כְּבָר בֵּאַרְנוּ שֶׁאֵין בְּקָדָשִׁים קַלִּים מְעִילָה לְעוֹלָם חוּץ מֵאֵימוּרֵיהֶן אַחַר זְרִיקַת הַדָּם וְהוּא שֶׁתִּהְיֶה זְרִיקָה הַמּוֹעֶלֶת. אֲבָל קָדָשִׁים קַלִּים שֶׁנִּתְפַּגְּלוּ אַף עַל פִּי שֶׁנִּזְרַק הַדָּם אֵין מוֹעֲלִין בְּאֵימוּרֵיהֶן. וְכֵן אִם יָצָא הַדָּם אַף עַל פִּי שֶׁהֶחְזִירוּ וְזָרְקוּ אֵין מוֹעֲלִין בְּאֵימוּרֵיהֶן:","כָּל חַטָּאוֹת הַמֵּתוֹת כְּגוֹן וְלַד חַטָּאת וּתְמוּרָתָהּ וְכַיּוֹצֵא בָּהֶן אָסוּר לֵהָנוֹת בָּהֶן וְאִם נֶהֱנָה לֹא מָעַל:","וְכָל חַטָּאת שֶׁתִּרְעֶה עַד שֶׁיִּפּל בָּהּ מוּם מוֹעֲלִין בָּהּ עַד שֶׁתִּפָּדֶה:","הַמַּפְרִישׁ חַטָּאתוֹ וְאָבְדָה וְהִפְרִישׁ אַחֶרֶת תַּחְתֶּיהָ וְאַחַר כָּךְ נִמְצֵאת הָרִאשׁוֹנָה וַהֲרֵי שְׁתֵּיהֶן עוֹמְדוֹת וְשָׁחַט שְׁתֵּיהֶן כְּאַחַת וְזָרַק דַּם אַחַת מֵהֶן. אֵין מוֹעֲלִין לֹא בִּבְשַׂר זוֹ שֶׁנִּזְרַק דָּמָהּ וְלֹא בִּבְשַׂר חֲבֶרְתָּהּ. וְאַף עַל פִּי שֶׁאֵינוֹ רָאוּי לַאֲכִילָה הוֹאִיל וְאִם רָצָה מִזֶּה זוֹרֵק וְאִם רָצָה מִזֶּה זוֹרֵק. אֲבָל אִם שָׁחַט זוֹ אַחַר זוֹ אֵין דָּמָהּ מוֹעִיל לִבְשַׂר חֲבֶרְתָּהּ וַאֲפִלּוּ לְאַחַר זְרִיקָה שֶׁהֲרֵי לֹא הָיְתָה לָהּ שָׁעָה הָרְאוּיָה לְהַתִּיר בְּשָׂרָהּ:","כָּל חַטַּאת עוֹף אוֹ עוֹלַת עוֹף שֶׁנִּפְסְלָה בְּשִׁנּוּי עֲשִׂיָּתָהּ אוֹ בְּשִׁנּוּי מְקוֹם עֲשִׂיָּתָהּ מוֹעֲלִין בָּהּ חוּץ מֵעוֹלַת הָעוֹף שֶׁנִּמְלַק לְמַטָּה כִּמְלִיקַת חַטָּאת לְשָׁם חַטָּאת שֶׁאַף עַל פִּי שֶׁלֹּא עָלְתָה לַבְּעָלִים לְשֵׁם חוֹבָה אֵין מוֹעֲלִין בָּהּ הוֹאִיל וְשִׁנָּה שְׁמָהּ וּמְקוֹם עֲשִׂיָּתָהּ וְשִׁנָּה מַעֲשֶׂיהָ לְשֵׁם דָּבָר שֶׁאֵין בּוֹ מְעִילָה:","מִנְחָה שֶׁנִּתְפַּגְּלָה אוֹ שֶׁנַּעֲשֵׂית בְּמַחְשֶׁבֶת הַמָּקוֹם. וְכֵן שְׁתֵּי הַלֶּחֶם וְלֶחֶם הַפָּנִים שֶׁנִּתְפַּגְּלוּ אוֹ שֶׁנִּפְסְלוּ בְּמַחְשֶׁבֶת הַמָּקוֹם. מוֹעֲלִין בָּהֶן שֶׁהֲרֵי לֹא הָיְתָה לָהֶן שְׁעַת הֶתֵּר:","וְכֵן קֹמֶץ שֶׁיָּצָא לַחוּץ אוֹ לָן וְחָזַר וְהִקְטִירוֹ מוֹעֲלִין בַּשְּׁיָרִים שֶׁהֲרֵי לֹא הָיָה שָׁם שְׁעַת הֶתֵּר. אֲבָל אִם נִטְמָא הַקֹּמֶץ וְהִקְטִירוֹ אֵין מוֹעֲלִין בַּשְּׁיָרִים שֶׁהַצִּיץ מְרַצֶּה עַל הַטָּמֵא וְאֵינוֹ מְרַצֶּה לֹא עַל הַלָּן וְלֹא עַל הַיּוֹצֵא. יָצְאוּ הַשְּׁיָרִים אוֹ נִטְמְאוּ וְאַחַר כָּךְ הִקְטִיר הַקֹּמֶץ אַף עַל פִּי שֶׁהֵן אֲסוּרִין בַּאֲכִילָה אֵין מוֹעֲלִין בָּהֶן שֶׁהֲרֵי קָרַב הַקֹּמֶץ כְּמִצְוָתוֹ:","הַנֶּהֱנֶה מִקָּדְשֵׁי קָדָשִׁים כֻּלָּם לִפְנֵי זְרִיקַת דָּמִים. אוֹ מֵאֵימוּרֵי קָדָשִׁים קַלִּים לְאַחַר זְרִיקָה. אוֹ שֶׁנֶּהֱנֶה מִן הָעוֹלָה כֻּלָּהּ אוֹ מִן הַקֹּמֶץ וְהַלְּבוֹנָה וּמִנְחַת כֹּהֲנִים וְהַחֲבִיתִין. יִפּל מַה שֶּׁנֶּהֱנָה לִנְדָבָה. מָעַל בְּקָרְבְּנוֹת הַצִּבּוּר יִפּל מַה שֶּׁנֶּהֱנָה לַלִּשְׁכָּה:","נֶהֱנָה קֹדֶם זְרִיקָה מִבְּשַׂר קָדְשֵׁי קָדָשִׁים שֶׁנִּטְמָא אוֹ שֶׁנֶּהֱנָה מֵאֵימוּרֵי קָדָשִׁים קַלִּים אַף עַל פִּי שֶׁהֶעֱלָן לְרֹאשׁ הַמִּזְבֵּחַ הֲרֵי זֶה פָּטוּר:","קָדְשֵׁי הַמִּזְבֵּחַ חֲלָבָן וּבֵיצֵיהֶן אָסוּר לֵהָנוֹת מֵהֶן וְהַנֶּהֱנֶה לֹא מָעַל לְפִיכָךְ וְלַד הַקָּדָשִׁים וְכֵן וְלַד הַמַּעֲשֵׂר לֹא יִינַק מֵאִמּוֹ אֶלָּא מִבְּהֵמָה אַחֶרֶת חֻלִּין. וְיֵשׁ לְאָדָם לְהִתְנַדֵּב וְלוֹמַר חֲלֵב בְּהֵמָה זוֹ הַחֻלִּין יִהְיֶה הֶקְדֵּשׁ לְוַלְדּוֹת הַקָּדָשִׁים שֶׁיִּינְקוּהוּ כְּדֵי שֶׁלֹּא יָמוּתוּ:","הִקְדִּישׁ בְּהֵמָה וְעוֹף לַמִּזְבֵּחַ קְדֻשַּׁת דָּמִים כְּגוֹן שֶׁאָמַר דְּמֵי בְּהֵמָה זוֹ לִנְסָכִים וּדְמֵי בֶּן יוֹנָה זֶה לִשְׁלָמִים הֲרֵי הֵן כְּקָדְשֵׁי בֶּדֶק הַבַּיִת וּמוֹעֲלִין בַּחֲלָבָן וּבְבֵיצֵיהֶן כְּמוֹ שֶׁיִּתְבָּאֵר:"],"Mishneh Torah, Vessels 15":["אֵין כְּלִי חֶרֶס מְקַבֵּל טֻמְאָה עַד שֶׁתִּגָּמֵר מְלַאכְתּוֹ. וּמֵאֵימתַי הוּא גְּמַר מְלַאכְתּוֹ מִשֶּׁיִּצְרְפוֹ בְּכִבְשָׁן. הַתַּנּוּר מִשֶּׁיַּסִּיקֶנּוּ לֶאֱפוֹת סֻפְגָּנִין. הַכִּירָה מִשֶּׁיַּסִּיקֶנָּה כְּדֵי לְבַשֵּׁל עָלֶיהָ בֵּיצַת הַתַּרְנְגוֹלִין טְרוּפָה וּנְתוּנָה בְּאִלְפָּס. הַכֻּפָּח אִם עֲשָׂאָהוּ לַאֲפִיָּה שִׁעוּרוֹ כְּתַנּוּר עֲשָׂאָהוּ לְבִשּׁוּל שִׁעוּרוֹ כְּכִירָה:","תַּנּוּר שֶׁהִתְחִיל לִבְנוֹתוֹ אִם הָיָה גָּדוֹל מִשֶּׁיַּתְחִיל בּוֹ אַרְבָּעָה טְפָחִים וְיַסִּיקֶנּוּ מְקַבֵּל טֻמְאָה. וְאִם הָיָה קָטָן מִשֶּׁיַּתְחִיל בּוֹ טֶפַח וְיַסִּיקֶנּוּ. הַכִּירָה מִשֶּׁיַּתְחִיל בָּהּ שָׁלֹשׁ אֶצְבָּעוֹת וְיַסִּיקֶנָּה. הַכֻּפָּח אִם עֲשָׂאָהוּ לַאֲפִיָּה הֲרֵי הוּא כְּתַנּוּר וְאִם לְבַשֵּׁל הֲרֵי הוּא כְּכִירָה:","תַּנּוּר שֶׁהֻסַּק מֵאֲחוֹרָיו אוֹ שֶׁהֻסַּק מִבֵּית הָאֻמָּן אוֹ שֶׁהֻסַּק שֶׁלֹּא לְדַעַת הוֹאִיל וְהֻסַּק מִכָּל מָקוֹם הֲרֵי זֶה מְקַבֵּל טֻמְאָה. מַעֲשֶׂה שֶׁנָּפְלָה דְּלֵקָה בְּתַנּוּר בִּכְפָר מִן הַכְּפָרִים וּבָא מַעֲשֶׂה לִפְנֵי בֵּית דִּין וְאָמְרוּ מְקַבֵּל טֻמְאָה:","תַּנּוּר שֶׁהִסִּיקוֹ לִהְיוֹת צוֹלֶה בּוֹ הֲרֵי זֶה מְקַבֵּל טֻמְאָה. לְלַבֵּן בּוֹ אוּנִין שֶׁל פִּשְׁתָּן טָהוֹר שֶׁאֵין זֶה עוֹשֶׂה מְלָאכָה בְּגוּף הַתַּנּוּר:","תַּנּוּר שֶׁחֲצָצוֹ לִשְׁנַיִם וְהִסִּיק אֶחָד מֵחֲלָקָיו וְנִטְמָא בְּמַשְׁקִין הוּא טָמֵא וַחֲבֵרוֹ טָהוֹר. נִטְמָא בְּשֶׁרֶץ וְכַיּוֹצֵא בּוֹ מִטֻּמְאוֹת שֶׁל תּוֹרָה הַכּל טָמֵא. וְעֹבִי שֶׁבֵּינֵיהֶן טָמֵא. הֻסְּקוּ שְׁנֵיהֶן וְנִטְמָא אֶחָד מֵהֶן בְּמַשְׁקִין בָּאֲוִיר חוֹלְקִין אֶת עָבְיוֹ הַמְשַׁמֵּשׁ לְטָמֵא טָמֵא לְטָהוֹר טָהוֹר. בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁחֲצָצוֹ וְאַחַר כָּךְ הִסִּיקוֹ. אֲבָל הִסִּיקוֹ וְאַחַר כָּךְ חֲצָצוֹ וְנִטְמָא אֶחָד מֵהֶן אֲפִלּוּ בְּמַשְׁקִין נִטְמָא הַכּל:","תַּנּוּר אוֹ כִּירָה שֶׁל אֶבֶן טְהוֹרִין לְעוֹלָם. וְשֶׁל מַתֶּכֶת טְהוֹרִין מִשּׁוּם תַּנּוּר וְכִירַיִם שֶׁנֶּאֱמַר (ויקרא יא לה) \"יֻתָּץ\" אֶת שֶׁיֵּשׁ לוֹ נְתִיצָה. וּמְטַמְּאִין מִשּׁוּם כְּלֵי מַתָּכוֹת. כֵּיצַד. אֵין מִתְטַמְּאִין מֵאֲוִירָן וְלֹא בִּמְחֻבָּר לַקַּרְקַע כְּתַנּוּר וְכִירַיִם וְאִם נָגְעָה בָּהֶן טֻמְאָה אֲפִלּוּ מֵאֲחוֹרֵיהֶן מִתְטַמְּאִין כִּשְׁאָר כְּלֵי מַתָּכוֹת וְאִם נִטְמְאוּ בְּמֵת נַעֲשִׂין אַב טֻמְאָה כִּשְׁאָר כְּלֵי מַתָּכוֹת וְיֵשׁ לָהֶן טָהֳרָה בְּמִקְוֶה:","תַּנּוּר שֶׁל מַתֶּכֶת שֶׁנִּקַּב אוֹ נִפְגַּם אוֹ נִסְדַּק וּסְתָמוֹ בְּטִיט אוֹ שֶׁעָשָׂה לוֹ טְפֵלָה שֶׁל טִיט אוֹ מוּסָף שֶׁל טִיט הֲרֵי זֶה מִתְטַמֵּא מִשּׁוּם תַּנּוּר. וְכַמָּה יִהְיֶה בַּנֶּקֶב. כְּדֵי שֶׁיֵּצֵא בּוֹ הָאוּר. וְכֵן בְּכִירָה. וְאִם עָשָׂה לַכִּירָה פִּטְפּוּטִים שֶׁל טִיט מִתְטַמְּאָה מִשּׁוּם כִּירָה. מֵרְחָהּ בְּטִיט בֵּין מִבִּפְנִים בֵּין מִבַּחוּץ עֲדַיִן אֵינָהּ מְקַבֶּלֶת טֻמְאָה:","תַּנּוּר שֶׁאֵינוֹ מְחֻבָּר בָּאָרֶץ אֲפִלּוּ תָּלוּי בְּצַוַּאר הַגָּמָל הֲרֵי זֶה טָמֵא מִשּׁוּם תַּנּוּר שֶׁנֶּאֱמַר (ויקרא יא לה) \"טְמֵאִים הֵם\" בְּכָל מָקוֹם:","כּוּר שֶׁל צוֹרְפֵי מַתָּכוֹת שֶׁיֵּשׁ בּוֹ בֵּית שְׁפִיתָה מִתְטַמֵּא כְּכִירָה וְכֵן כִּירָת שֶׁל עוֹשֵׂי זְכוּכִית אִם יֵשׁ בּוֹ בֵּית שְׁפִיתָה מְקַבֶּלֶת טֻמְאָה:","כִּבְשָׁן שֶׁל סַיָּדִין וְשֶׁל זוֹגְגִין וְשֶׁל יוֹצְרִין טְהוֹרִין. הַפּוּרְנָה אִם יֵשׁ לָהּ דֹּפֶן מִתְטַמְּאָה:","אֲבָנִים שֶׁחִבְּרָן זוֹ לָזוֹ וַעֲשָׂאָן תַּנּוּר אִם עָשָׂה לוֹ טְפֵלָה מִבִּפְנִים וּמִבַּחוּץ הֲרֵי זֶה כְּתַנּוּר לְכָל דָּבָר וּמִתְטַמֵּא מֵאֲוִירוֹ. וְאִם טְפָלוֹ מִבַּחוּץ בִּלְבַד מִתְטַמֵּא בְּמַגָּע וְלֹא בַּאֲוִיר. חִבֵּר אֲבָנִים לַתַּנּוּר וְלֹא חִבְּרָן זוֹ לָזוֹ מִתְטַמְּאוֹת עִם הַתַּנּוּר. חִבְּרָן זוֹ לָזוֹ וְלֹא חִבְּרָן לַתַּנּוּר הֲרֵי הֵן כְּטִירָה. חָפַר בָּאָרֶץ וְעָשָׂה טִירָה טָהוֹר. וְטִירַת הַכִּירָה טָהוֹר:","שְׁתֵּי חָבִיּוֹת וּשְׁנֵי אִלְפָּסִין שֶׁעֲשָׂאָן כִּירָה מִתְטַמְּאִין בַּאֲוִיר וּבְמַגָּע. וְתוֹכָן שֶׁל חָבִיּוֹת טָהוֹר. וָעֳבִי הֶחָבִיּוֹת חוֹלְקִין אוֹתוֹ הַמְשַׁמֵּשׁ אֶת הַכִּירָה טָמֵא וְהַמְשַׁמֵּשׁ אֶת תּוֹךְ הֶחָבִית טָהוֹר:","הָעוֹשֶׂה שְׁלֹשָׁה פִּטְפּוּטִין בָּאָרֶץ וְחִבְּרָן בְּטִיט לִהְיוֹת שׁוֹפֵת עֲלֵיהֶן אֶת הַקְּדֵרָה הֲרֵי זוֹ טְמֵאָה מִשּׁוּם כִּירָה. קָבַע שְׁלֹשָׁה מַסְמְרִין בָּאָרֶץ לִהְיוֹת שׁוֹפֵת עֲלֵיהֶן אֶת הַקְּדֵרָה אַף עַל פִּי שֶׁעָשָׂה בְּרֹאשָׁהּ מָקוֹם בְּטִיט שֶׁתֵּשֵׁב הַקְּדֵרָה הֲרֵי זוֹ טְהוֹרָה כְּכִירָה שֶׁל מַתֶּכֶת. וְכֵן אֲבָנִים שֶׁלֹּא מֵרְחָם בְּטִיט שֶׁהוּא שׁוֹפֵת עֲלֵיהֶן אֵינָן מְקַבְּלוֹת טֻמְאָה כְּאִלּוּ הִיא כִּירָה שֶׁל אֶבֶן:","הָעוֹשֶׂה שְׁתֵּי אֲבָנִים כִּירָה וְחִבְּרָן בְּטִיט מִתְטַמְּאָה. חִבֵּר אֶת הָאַחַת בְּטִיט וְהַשְּׁנִיָּה לֹא חִבְּרָהּ אֵינָהּ מְקַבֶּלֶת טֻמְאָה:","הָאֶבֶן שֶׁהוּא שׁוֹפֵת עָלֶיהָ וְעַל הַתַּנּוּר עָלֶיהָ וְעַל הַכִּירָה עָלֶיהָ וְעַל הַכֻּפָּח טְמֵאָה. עָלֶיהָ וְעַל הַכֹּתֶל עָלֶיהָ וְעַל הַסֶּלַע אֵינָהּ מְקַבֶּלֶת טֻמְאָה:","כִּירַת הַטַּבָּחִים שֶׁהוּא נוֹתֵן אֶבֶן בְּצַד אֶבֶן וְכֻלָּן מְחֻבָּרוֹת בְּטִיט נִטְמֵאת אַחַת מֵהֶן לֹא נִטְמְאוּ כֻּלָּן:","שָׁלֹשׁ אֲבָנִים שֶׁחִבְּרָן בְּטִיט וַעֲשָׂאָן שְׁתֵּי כִּירוֹת בֵּין שֶׁחִבְּרָן זוֹ לָזוֹ וְלֹא חִבְּרָן לַקַּרְקַע בֵּין שֶׁחִבְּרָן בַּקַּרְקַע וְלֹא חִבְּרָן זוֹ לָזוֹ אִם נִטְמֵאת אַחַת מִשְּׁתֵי הַכִּירוֹת הָאֶבֶן הָאֶמְצָעִית הַמְשַׁמֵּשׁ מִמֶּנָּה לַכִּירָה הַטְּמֵאָה טָמֵא וְהַמְשַׁמֵּשׁ מִמֶּנָּה לַכִּירָה הַטְּהוֹרָה טָהוֹר. נִטְּלָה הָאֶבֶן הַחִיצוֹנָה שֶׁל כִּירָה הַטְּהוֹרָה הֻחְלְטָה הָאֶמְצָעִית כֻּלָּהּ לְטֻמְאָה. נִטְּלָה הַחִיצוֹנָה שֶׁל כִּירָה הַטְּמֵאָה טָהֲרָה הָאֶבֶן הָאֶמְצָעִית כֻּלָּהּ. נִטְמְאוּ שְׁתֵּי הַחִיצוֹנוֹת אִם הָיְתָה הָאֶבֶן הָאֶמְצָעִית גְּדוֹלָה נוֹתֵן מִמֶּנָּה לְכִירָה זוֹ כְּדֵי שְׁפִיתָה מִצִּדָּהּ וְלַכִּירָה הַשְּׁנִיָּה כְּדֵי שְׁפִיתָה מִכָּאן וְהַשְּׁאָר טָהוֹר. וְאִם הָיְתָה קְטַנָּה הַכּל טָמֵא. נִטְּלָה הָאֶמְצָעִית אִם יָכוֹל לִשְׁפּוֹת עַל שְׁתַּיִם חִיצוֹנוֹת יוֹרָה גְּדוֹלָה הֲרֵי הִיא טְמֵאָה. הָיוּ מְרֻחָקִין יֶתֶר מִזֶּה טְהוֹרָה. הֶחֱזִיר אֶת הָאֶמְצָעִית הֲרֵי הַכּל טָהוֹר כְּשֶׁהָיָה. מֵרְחָהּ בְּטִיט מְקַבֵּל טֻמְאָה מִכָּאן וּלְהַבָּא וְהוּא שֶׁיַּסִּיקֶנָּה לְכָל אַחַת מֵהֶן כְּדֵי לְבַשֵּׁל עָלֶיהָ אֶת הַבֵּיצָה:","שְׁתֵּי אֲבָנִים שֶׁעֲשָׂאָן כִּירָה וְנִטְמֵאת וְסָמַךְ לְאֶבֶן זוֹ מִמֶּנָּה אֶבֶן אַחַת מִכָּאן וְלָזוֹ אֶבֶן אַחַת מִכָּאן הֲרֵי חֲצִי כָּל אֶבֶן מִשְּׁתֵי אַבְנֵי הַכִּירָה הָרִאשׁוֹנָה טָמֵא וַחֲצִי הָאֶבֶן טָהוֹר. נִטְּלוּ הַשְּׁתַּיִם הַטְּהוֹרוֹת שֶׁסָּמַךְ חָזְרוּ הַשְּׁתַּיִם שֶׁל כִּירָה לְטֻמְאָתָן:","דּוּכָן שֶׁל חֶרֶס שֶׁיֵּשׁ לוֹ בֵּית קִבּוּל הַקְּדֵרוֹת וְהָרֶמֶץ נָתוּן בְּתוֹכוֹ טָהוֹר מִשּׁוּם כִּירָה וְטָמֵא מִשּׁוּם כְּלִי קִבּוּל. לְפִיכָךְ אִם הָיָה מְחֻבָּר בָּאָרֶץ טָהוֹר כִּשְׁאָר הַכֵּלִים וְאִם נִקַּב אֵינוֹ מְקַבֵּל טֻמְאָה כִּכְלִי קִבּוּל. מַה שֶּׁאֵין כֵּן בְּכִירָה. הַצְּדָדִין שֶׁלּוֹ הַנּוֹגֵעַ בָּהֶן אֵינוֹ טָמֵא מִשּׁוּם כִּירָה. הָרָחָב שֶׁלּוֹ שֶׁיּוֹשְׁבִין עָלָיו בִּשְׁעַת בִּשּׁוּל מִתְטַמֵּא אִם נִטְמָא הַדּוּכָן. וְכֵן הַכּוֹפֶה אֶת הַסַּל וּבָנָה כִּירָה עַל גַּבָּהּ הֲרֵי זוֹ טְמֵאָה מִשּׁוּם כְּלִי עֵץ לֹא מִשּׁוּם כִּירָה לְפִיכָךְ אֵינָהּ מְקַבֶּלֶת טֻמְאָה מֵאֲוִירָהּ כְּכִירָה:"],"Mishneh Torah, Vessels 26":["כְּלִי עֵץ הָרָאוּי לְמִדְרָס שֶׁקְּבָעוֹ בְּכֹתֶל בְּתוֹךְ הַבִּנְיָן. קְבָעוֹ בַּכֹּתֶל וְלֹא בָּנָה עַל גַּבָּיו אוֹ בָּנָה עַל גַּבָּיו וְלֹא קְבָעוֹ עֲדַיִן מִתְטַמֵּא בְּמִדְרָס כְּשֶׁהָיָה. קְבָעוֹ בְּמַסְמְרִים וּבָנָה עָלָיו טָהוֹר. וְכֵן מַפָּץ שֶׁנְּתָנוֹ עַל גַּבֵּי הַקּוֹרוֹת קְבָעוֹ וְלֹא נָתַן עָלָיו אֶת הַמַּעֲזִיבָה אוֹ שֶׁנָּתַן עָלָיו אֶת הַמַּעֲזִיבָה וְלֹא קְבָעוֹ מִתְטַמֵּא בְּמִדְרָס. קְבָעוֹ וְנָתַן עָלָיו אֶת הַמַּעֲזִיבָה טָהוֹר:","סַפְסָל שֶׁנִּטַּל אֶחָד מֵרָאשָׁיו עֲדַיִן הוּא רָאוּי לְמִדְרָס. נִטַּל הַשֵּׁנִי טָהוֹר. וְאִם יֵשׁ בּוֹ גֹּבַהּ טֶפַח מִתְטַמֵּא בְּמִדְרָס:","כִּסֵּא שֶׁל כַּלָּה שֶׁנִּטְּלוּ חִפּוּיָיו טָהוֹר וְאִם לֹא הָיוּ חִפּוּיָיו יוֹצְאִים וְנִטְּלוּ עֲדַיִן הוּא רָאוּי לְמִדְרָס שֶׁכֵּן דַּרְכּוֹ לִהְיוֹת מַטֵּהוּ עַל צִדּוֹ וְיוֹשֵׁב עָלָיו:","כִּסֵּא שֶׁנִּטְּלוּ חִפּוּיָיו וַעֲדַיִן הוּא רָאוּי לִישִׁיבָה מִתְטַמֵּא. נִטְּלוּ שְׁנַיִם מֵחִפּוּיָיו זֶה בְּצַד זֶה טָהוֹר:","שִׁדָּה שֶׁנִּטַּל הָעֶלְיוֹן שֶׁלָּהּ טְמֵאָה מִפְּנֵי הַתַּחְתּוֹן שֶׁהוּא רָאוּי לְמִדְרָס. נִטַּל הַתַּחְתּוֹן טְמֵאָה מִפְּנֵי הָעֶלְיוֹן. נִטְּלוּ שְׁתֵּיהֶן הֲרֵי הַדַּפִּין טְהוֹרִין:","תֵּבָה שֶׁנִּפְחֲתָה מִצִּדָּהּ מִתְטַמְּאָה בְּמִדְרָס וּבִשְׁאָר טֻמְאוֹת מִפְּנֵי שֶׁרְאוּיָה אַף לִישִׁיבָה וְהַכּל יוֹשְׁבִין עָלֶיהָ. נִפְחֲתָה מִלְּמַעְלָה טְהוֹרָה מִן הַמִּדְרָס שֶׁהֲרֵי אֵינָהּ רְאוּיָה לִישִׁיבָה וּמִתְטַמְּאָה בִּשְׁאָר טֻמְאוֹת שֶׁעֲדַיִן הִיא מְקַבֶּלֶת. נִפְחֲתָה מִלְּמַטָּה טְהוֹרָה מִכָּל טֻמְאוֹת אַף עַל פִּי שֶׁאֶפְשָׁר לֵישֵׁב עָלֶיהָ בְּכִסֵּא מִפְּנֵי שֶׁעִקַּר מַעֲשֶׂיהָ לְקַבָּלָה וּכְבָר בָּטַל הָעִקָּר. וְהַמְּגוּרוֹת שֶׁלָּהּ מִתְטַמְּאוֹת וְאֵינָן חִבּוּר לָהּ. וְכֵן מַשְׁפֶּלֶת שֶׁנִּפְחֲתָה מִלְּקַבֵּל רִמּוֹנִים אַף עַל פִּי שֶׁרְאוּיָה לְמִדְרָס הֲרֵי הִיא טְהוֹרָה מִכְּלוּם מִפְּנֵי שֶׁעִקַּר מַעֲשֶׂיהָ לְקַבָּלָה וְהוֹאִיל וּבָטַל הָעִקָּר בָּטְלָה הַטְּפֵלָה:","עֲרֵבָה שֶׁל עֵץ שֶׁמְּגַבְּלִין בָּהּ הַבִּנְיָן אוֹ אֶת הַגְּפָסִים אַף עַל פִּי שֶׁמְּקַבֶּלֶת שְׁאָר טֻמְאוֹת אֵינָהּ מִתְטַמְּאָה בְּמִדְרָס. וְשֶׁלָּשִׁין בָּהּ אֶת הַבָּצֵק שֶׁמְּחַזֶּקֶת מִשְּׁנֵי לוֹגִין וְעַד תִּשְׁעָה קַבִּין שֶׁנִּסְדְּקָה עַד שֶׁאֵינוֹ יָכוֹל לִרְחֹץ בָּהּ רַגְלוֹ אַחַת מִפְּנֵי הַסֶּדֶק הֲרֵי זוֹ מִתְטַמְּאָה בְּמִדְרָס שֶׁסְּתָמָהּ שֶׁכּוֹפְתָהּ וְיוֹשֵׁב עָלֶיהָ לְפִי גָּדְלָהּ וְסֶדֶק שֶׁלָּהּ. הִנִּיחָהּ בַּגְּשָׁמִים עַד שֶׁנִּתְפְּחָה וְנִסְתַּם הַסֶּדֶק אֵינָהּ מִתְטַמְּאָה בְּמִדְרָס שֶׁהֲרֵי הִיא רְאוּיָה לָלוּשׁ בָּהּ וּתְחִלַּת מַעֲשֶׂיהָ לָלוּשׁ בָּהּ וּמְקַבֶּלֶת שְׁאָר טֻמְאוֹת. חָזַר וְהִנִּיחָהּ בַּקַּדִים וְנִפְתַּח הַסֶּדֶק חָזְרָה לְקַבֵּל טֻמְאַת מִדְרָס וּטְהוֹרָה מִשְּׁאָר טֻמְאוֹת:","עֲרֵבָה גְּדוֹלָה שֶׁהִיא יֶתֶר עַל תִּשְׁעָה קַבִּין שֶׁנִּפְחֲתָה מִלְּקַבֵּל רִמּוֹנִים וֶהֱכִינָהּ לִישִׁיבָה הֲרֵי זוֹ טְהוֹרָה אַף מִטֻּמְאַת מִדְרָס עַד שֶׁיַּקְצִיעַ שֶׁאֵין הַמַּחְשָׁבָה מוֹעֶלֶת בַּעֲרֵבָה גְּדוֹלָה שֶׁנִּפְחֲתָה עַד שֶׁיַּעֲשֶׂה בָּהּ מַעֲשֶׂה. עֲשָׂאָהּ אֵבוּס לִבְהֵמָה אַף עַל פִּי שֶׁקְּבָעָהּ בַּכֹּתֶל טְמֵאָה בְּכָל הַטֻּמְאוֹת:","מִטָּה שֶׁנִּטְּלוּ שְׁתֵּי אֲרֻכּוֹת שֶׁלָּהּ אַחַר שֶׁנִּטְמֵאת וְעָשָׂה לָהּ אֲרֻכּוֹת חֲדָשׁוֹת וְלֹא שִׁנָּה אֶת הַנְּקָבִים וְנִשְׁבְּרוּ הַחֲדָשׁוֹת עֲדַיִן הִיא בְּטֻמְאָתָהּ. נִשְׁתַּבְּרוּ הַיְשָׁנוֹת טְהוֹרָה שֶׁהַכּל הוֹלֵךְ אַחַר הַיְשָׁנוֹת:","מִטָּה שֶׁהָיְתָה טְמֵאָה מִדְרָס וְנִטְּלָה קְצָרָה וּשְׁתֵּי כְּרָעַיִם עֲדַיִן הִיא בְּטֻמְאָתָהּ שֶׁעֲדַיִן צוּרַת הַמִּטָּה עוֹמֶדֶת. נִטְּלָה אֲרֻכָּה וּשְׁתֵּי כְּרָעַיִם טְהוֹרָה:","קִצֵּץ שְׁתֵּי לְשׁוֹנוֹת שֶׁל מִטָּה בַּאֲלַכְסוֹן אוֹ שֶׁקִּצֵּץ שְׁתֵּי כְּרָעַיִם טֶפַח עַל טֶפַח בַּאֲלַכְסוֹן אוֹ שֶׁמִּעֲטָן פָּחוֹת מִטֶּפַח הֲרֵי זוֹ נִשְׁבְּרָה וּטְהוֹרָה. נִשְׁבְּרָה אֲרֻכָּה וְתִקְּנָהּ עֲדַיִן הִיא אַב טֻמְאָה כְּשֶׁהָיְתָה. נִשְׁבְּרָה הָאֲרֻכָּה הַשְּׁנִיָּה וְתִקְּנָהּ טְהוֹרָה מִן הַמִּדְרָס אֲבָל טְמֵאָה מַגַּע מִדְרָס. לֹא הִסְפִּיק לְתַקֵּן אֶת הָרִאשׁוֹנָה עַד שֶׁנִּשְׁבְּרָה הַשְּׁנִיָּה טְהוֹרָה:","מִטָּה שֶׁהָיְתָה טְמֵאָה מִדְרָס אוֹ בִּשְׁאָר טֻמְאוֹת וְנִגְנַב חֶצְיָהּ אוֹ אָבַד חֶצְיָהּ אוֹ שֶׁחִלְּקוּהָ אַחִין אוֹ שֻׁתָּפִין הֲרֵי זוֹ טְהוֹרָה שֶׁהֲרֵי זֶה כִּכְלִי שֶׁנִּשְׁבַּר. הֶחְזִירוּהָ מְקַבֶּלֶת טֻמְאָה מִכָּאן וּלְהַבָּא. הֲרֵי זֶה דּוֹמֶה לְמִי שֶׁעָשָׂה כְּלִי אֶחָד מִשִּׁבְרֵי כֵּלִים שֶׁנִּטְמָא שֶׁהוּא טָהוֹר וּמְקַבֵּל טֻמְאָה לְהַבָּא:","מִטָּה שֶׁנִּפְרְקוּ אֵיבָרֶיהָ אִם נִשְׁבְּרָה אֲרֻכָּה וּשְׁתֵּי כְּרָעַיִם אוֹ קְצָרָה וּשְׁתֵּי כְּרָעַיִם הֲרֵי אֵלּוּ מִתְטַמְּאִין מִפְּנֵי שֶׁרְאוּיִין לְסָמְכָן בַּכֹּתֶל וְלִישֹׁן עֲלֵיהֶן:","מִטָּה שֶׁנִּטְמֵאת כֻּלָּהּ אִם הִטְבִּילָהּ אֵיבָרִים אֵיבָרִים טְהוֹרָה:","הַמְפָרֵק אֶת הַמִּטָּה לְהַטְבִּילָהּ הַנּוֹגֵעַ בַּחֲבָלִים שֶׁלָּהּ טָהוֹר:"],"Mishneh Torah, Vessels of the Sanctuary and Those Who Serve Therein 2":["הַקְטֹרֶת נַעֲשֵׂית בְּכָל שָׁנָה וְשָׁנָה וַעֲשִׂיָּתוֹ מִצְוַת עֲשֵׂה שֶׁנֶּאֱמַר וְאַתָּה קַח לְךָ סַמִּים וְגוֹ'. וְנִתְפָּרְשׁוּ בַּתּוֹרָה אַרְבָּעָה מִסַּמְמָנֶיהָ. וְהֵן (שמות ל לד) \"נָטָף. וּשְׁחֵלֶת. וְחֶלְבְּנָה. וּלְבֹנָה\". וּשְׁאָר סַמְמָנֶיהָ הֲלָכָה לְמשֶׁה מִסִּינַי:","אַחַד עָשָׂר סַמְמָנִים נֶאֶמְרוּ לוֹ לְמשֶׁה מִסִּינַי. וְהֵם שֶׁעוֹשִׂין אוֹתָן בְּמִשְׁקָל מְכֻוָּן. וּמוֹסִיפִין עִמָּהֶן בְּלֹא מִשְׁקָל מֶלַח סְדוֹמִית וְכִפַּת הַיַּרְדֵּן. וְעֵשֶׂב אֶחָד שֶׁמַּעֲלֶה עָשָׁן. וְלֹא הָיוּ יוֹדְעִים אוֹתוֹ אֶלָּא אֲנָשִׁים יְדוּעִים וְהוּא הָיָה הֲלָכָה בְּיָדָם אִישׁ מִפִּי אִישׁ:","וְזֶהוּ מִשְׁקַל אַחַד עָשָׂר סַמָּנֶיהָ. נָטָף. וּשְׁחֵלֶת. וְחֶלְבְּנָה. וּלְבֹנָה. מִכָּל אֶחָד מִשְׁקַל שִׁבְעִים מָנֶה. וְהַמָּנֶה מֵאָה דִּינָרִין. וּמוֹר. וּקְצִיעָה. וְשִׁבּלֶת נֵרְדְּ. וְכַרְכֹּם. מִכָּל אֶחָד שִׁשָּׁה עָשָׂר מָנֶה. קֹשְׁטְ שְׁנֵים עָשָׂר מָנֶה. קִנָּמוֹן תִּשְׁעָה מָנִים. קִלּוּפָה שְׁלֹשָׁה מָנִים. מִשְׁקַל הַכּל שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וּשְׁמוֹנָה מָנֶה. שְׁחוּקִין הַכּל הָדֵק. מוֹסִיפִין לָהּ רֹבַע הַקַּב מֶלַח סְדוֹמִית. וְכִפַּת הַיַּרְדֵּן וּמַעֲלֶה עָשָׁן כָּל שֶׁהוּא. וּמַקְטִיר מִמֶּנָּה בְּכָל יוֹם עַל מִזְבַּח הַזָּהָב מָנֶה. שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה מָנֶה כְּנֶגֶד יְמוֹת הַחַמָּה. וְהַשְּׁלֹשָׁה מָנִים הַנִּשְׁאָרִים שׁוֹחֵק אוֹתָם עֶרֶב יוֹם הַכִּפּוּרִים דַּקָּה מִן הַדַּקָּה עַד שֶׁמּוֹצִיא מִמֶּנָּה מָלֵא חָפְנָיו לְהַקְטִיר בְּיוֹם הַכִּפּוּרִים. וְהַשְּׁאָר הוּא מוֹתַר הַקְּטֹרֶת שֶׁאָמַרְנוּ בִּשְׁקָלִים:","נָטָף הָאָמוּר בַּתּוֹרָה הוּא עֲצֵי הַקְּטָף שֶׁיּוֹצֵא מֵהֶן הַצֳּרִי. וְהַשְּׁחֵלֶת הִיא הַצִּפֹּרֶן שֶׁנּוֹתְנִין אוֹתָהּ בְּנֵי הָאָדָם בְּמֻגְמָרוֹת. וְהַחֶלְבְּנָה כְּמוֹ דְּבַשׁ שָׁחוֹר וְרֵיחוֹ קָשֶׁה וְהוּא שְׂרַף אִילָנוֹת בְּעָרֵי יָוָן. וְזֶהוּ שְׁמוֹת הַסַּמָּנִים בְּלָשׁוֹן עֲרָבִי. עוּד בְּלַסַאן וְאַצְפַאר טִיב. וּמִיעָה. וּלְכַאן. וּמוּסְקִי. וּקְצִיעָה. וְסַנְבְּלִי אַלְנַטוֹרִין. וְזַעֲפְרָן. וְקֹשְׁט. וְעוּד [הַיַּרְדִּי]. וְקַסַּר סְלִיכָה. וְעִנְבָּר:","כֵּיצַד מְפַטְּמִין אֶת הַקְּטֹרֶת. מֵבִיא תִּשְׁעָה קַבִּין בֹּרִית כַּרְשִׁינָה וְשָׁף בָּהּ אֶת הַצִּפֹּרֶן וְאַחַר כָּךְ שׁוֹרֶה אֶת הַצִּפֹּרֶן בְּאֶחָד וְעֶשְׂרִים קַב שֶׁל יֵין קַפְרִיסִין אוֹ יַיִן לָבָן יָשָׁן חָזָק בְּיוֹתֵר. וְאַחַר כָּךְ שׁוֹחֵק כָּל אֶחָד מִן הַסַּמָּנִים בִּפְנֵי עַצְמוֹ הָדֵק. וּכְשֶׁהוּא שׁוֹחֵק אוֹמֵר הָדֵק הֵיטֵב הָדֵק הֵיטֵב כָּל זְמַן שֶׁשּׁוֹחֵק וּמְעָרֵב הַכּל:","וְכָל מַעֲשֶׂיהָ בַּקֹּדֶשׁ בְּתוֹךְ הָעֲזָרָה וּמִשֶּׁל הַקֹּדֶשׁ. וְהַמְפַטֵּם אֶת הַקְּטֹרֶת מִן הַחֻלִּין אוֹ בִּכְלִי שֶׁל חֻלִּין פְּסוּלָה:","פַּעֲמַיִם בַּשָּׁנָה הָיוּ מַחֲזִירִין אוֹתוֹ לַמַּכְתֶּשֶׁת. בִּימוֹת הַחַמָּה הָיוּ מְפַזְּרִים אוֹתָהּ כְּדֵי שֶׁלֹּא תִּתְעַפֵּשׁ. וּבִימוֹת הַגְּשָׁמִים צוֹבְרִין אוֹתָהּ כְּדֵי שֶׁלֹּא יָפוּג רֵיחָהּ:","נָתַן לְתוֹכָהּ דְּבַשׁ כָּל שֶׁהוּא פְּסָלָהּ. חִסֵּר אֶחָד מִסַּמְמָנֶיהָ חַיָּב מִיתָה שֶׁהֲרֵי נַעֲשֵׂית קְטֹרֶת זָרָה. פִּטְּמָהּ מְעַט מְעַט בְּמַתְכֻּנְתָּהּ כְּשֵׁרָה אֲפִלּוּ פִּטֵּם פְּרָס בְּשַׁחֲרִית וּפְרָס בֵּין הָעַרְבַּיִם:","הָעוֹשֶׂה קְטֹרֶת מֵאַחַד עָשָׂר סַמְמָנִין אֵלּוּ לְפִי מִשְׁקָלוֹת אֵלּוּ כְּדֵי לְהָרִיחַ בָּהּ אַף עַל פִּי שֶׁלֹּא הֵרִיחַ חַיָּב כָּרֵת עַל עֲשִׂיָּתָהּ אִם עָשָׂה מֵזִיד. וּבְשׁוֹגֵג מֵבִיא חַטָּאת קְבוּעָה. אַף עַל פִּי שֶׁלֹּא עָשָׂה הַמִּשְׁקָל כֻּלּוֹ אֶלָּא חֶצְיוֹ אוֹ שְׁלִישׁוֹ. הוֹאִיל וְעָשָׂה לְפִי מִשְׁקָלוֹת אֵלּוּ חַיָּב כָּרֵת. שֶׁנֶּאֱמַר (שמות ל לז) \"בְּמַתְכֻּנְתָּהּ לֹא תַעֲשׂוּ לָכֶם\" (שמות ל לח) \"אִישׁ אֲשֶׁר יַעֲשֶׂה כָמוֹהָ לְהָרִיחַ בָּהּ וְנִכְרַת מֵעַמָּיו\":","עֲשָׂאָהּ לְהִתְלַמֵּד בָּהּ אוֹ לְמָסְרָהּ לַצִּבּוּר פָּטוּר. הֵרִיחַ בָּהּ וְלֹא עֲשָׂאָהּ אֵינוֹ חַיָּב כָּרֵת אֶלָּא דִּינוֹ כְּדִין כָּל הַנֶּהֱנֶה מִן הַהֶקְדֵּשׁ. לֹא חִיְּבָה תּוֹרָה כָּרֵת אֶלָּא לָעוֹשֶׂה בְּמַתְכֻּנְתָּהּ לְהָרִיחַ בָּהּ:","מִזְבַּח הַזָּהָב שֶׁבַּהֵיכָל עָלָיו מַקְטִירִין הַקְּטֹרֶת בְּכָל יוֹם. וְאֵין מַקְרִיבִין עָלָיו דָּבָר אַחֵר. וְאִם הִקְטִיר עָלָיו קְטֹרֶת אַחֶרֶת שֶׁאֵינָהּ כָּזוֹ. אוֹ שֶׁהִקְטִיר עָלָיו קְטֹרֶת כָּזוֹ שֶׁהִתְנַדֵּב אוֹתָהּ יָחִיד אוֹ רַבִּים. אוֹ הִקְרִיב עָלָיו קָרְבָּן. אוֹ הִסִּיךְ נֶסֶךְ. לוֹקֶה שֶׁנֶּאֱמַר (שמות ל ט) \"לֹא תַעֲלוּ עָלָיו קְטֹרֶת זָרָה וְעוֹלָה וּמִנְחָה\" וְגוֹ':","בְּעֵת שֶׁמּוֹלִיכִין אֶת הָאָרוֹן מִמָּקוֹם לְמָקוֹם אֵין מוֹלִיכִין אוֹתוֹ לֹא עַל הַבְּהֵמָה וְלֹא עַל הָעֲגָלוֹת אֶלָּא מִצְוָה לְנָטְלוֹ עַל הַכָּתֵף. וּלְפִי שֶׁשָּׁכַח דָּוִד וּנְשָׂאוֹ עַל הָעֲגָלָה נִפְרַץ פֶּרֶץ בְּעֻזָּא. אֶלָּא מִצְוָה לְנָשְׂאוֹ עַל הַכָּתֵף שֶׁנֶּאֱמַר (במדבר ז ט) \"כִּי עֲבֹדַת הַקֹּדֶשׁ עֲלֵיהֶם בַּכָּתֵף יִשָּׂאוּ\":","כְּשֶׁנּוֹשְׂאִים אוֹתוֹ עַל הַכָּתֵף נוֹשְׂאִין פָּנִים כְּנֶגֶד פָּנִים וַאֲחוֹרֵיהֶם לַחוּץ וּפְנֵיהֶם לְפָנִים. וְנִזְהָרִים שֶׁלֹּא יִשָּׁמְטוּ הַבַּדִּים מִן הַטַּבָּעוֹת. שֶׁהַמֵּסִיר אֶחָד מִן הַבַּדִּים מִן הַטַּבָּעוֹת לוֹקֶה. שֶׁנֶּאֱמַר (שמות כה טו) \"בְּטַבְּעֹת הָאָרֹן יִהְיוּ הַבַּדִּים לֹא יָסֻרוּ מִמֶּנּוּ\":"],"Mishneh Torah, Vows 10":["הַנּוֹדֵר אוֹ הַנִּשְׁבָּע שֶׁאֵינִי טוֹעֵם הַיּוֹם אֵינוֹ אָסוּר אֶלָּא עַד שֶׁתֶּחֱשַׁךְ. שֶׁאֵינִי טוֹעֵם יוֹם אֶחָד אָסוּר מֵעֵת לְעֵת מִשְּׁעַת נִדְרוֹ. לְפִיכָךְ הַנּוֹדֵר שֶׁאֲנִי טוֹעֵם הַיּוֹם אַף עַל פִּי שֶׁהוּא מֻתָּר מִשֶּׁתֶּחְשַׁךְ לֹא יֹאכַל מִשֶּׁתֶּחְשַׁךְ עַד שֶׁיִּשְׁאַל לְחָכָם. גְּזֵרָה שֶׁמָּא יִשָּׁבַע פַּעַם אַחֶרֶת יוֹם אֶחָד וְיֹאכַל מִשֶּׁתֶּחְשַׁךְ שֶׁהֲרֵי אֵין כָּל הָעָם יוֹדְעִים הֶפְרֵשׁ שֶׁבֵּין זֶה לָזֶה:","נָדַר שֶׁאֲנִי טוֹעֵם יוֹם הֲרֵי זֶה סָפֵק וְאָסוּר מֵעֵת לְעֵת כְּאוֹמֵר יוֹם אֶחָד. וְאִם אָכַל אַחַר שֶׁחֲשֵׁכָה אֵינוֹ לוֹקֶה. שֶׁאֲנִי טוֹעֵם שַׁבָּת זוֹ הֲרֵי זֶה אָסוּר בִּשְׁאָר יְמֵי הַשַּׁבָּת וּבְיוֹם הַשַּׁבָּת. וַהֲרֵי הוּא מֻתָּר מֵאֶחָד בְּשַׁבָּת. שֶׁאֲנִי טוֹעֵם שַׁבָּת אַחַת הֲרֵי זֶה אָסוּר שִׁבְעָה יָמִים מֵעֵת לְעֵת. אָמַר שַׁבָּת סְתָם וְלֹא פֵּרֵשׁ לֹא אַחַת וְלֹא זוֹ הֲרֵי סָפֵק וְאָסוּר שִׁבְעָה יָמִים מֵעֵת לְעֵת. וְאִם אָכַל אַחַר שַׁבָּת אֵינוֹ לוֹקֶה כְּמוֹ שֶׁבֵּאַרְנוּ:","שֶׁאֲנִי שׁוֹתֶה חֹדֶשׁ זֶה אָסוּר בִּשְׁאָר יְמֵי הַחֹדֶשׁ. אֲבָל בְּיוֹם רֹאשׁ חֹדֶשׁ יִהְיֶה מֻתָּר אַף עַל פִּי שֶׁהָיָה חֹדֶשׁ חָסֵר. שֶׁאֲנִי טוֹעֵם חֹדֶשׁ אֶחָד אָסוּר שְׁלֹשִׁים יוֹם גְּמוּרִים מֵעֵת לְעֵת. נָדַר חֹדֶשׁ סְתָם אָסוּר שְׁלֹשִׁים יוֹם מֵעֵת לְעֵת מִסָּפֵק:","שֶׁאֲנִי אוֹכֵל בָּשָׂר שָׁנָה זוֹ אֲפִלּוּ לֹא נִשְׁאַר מִן הַשָּׁנָה אֶלָּא יוֹם אֶחָד אֵין אָסוּר אֶלָּא אוֹתוֹ הַיּוֹם. וּבְיוֹם רֹאשׁ הַשָּׁנָה מֻתָּר. וְרֹאשׁ הַשָּׁנָה לִנְדָרִים הוּא יוֹם רֹאשׁ חֹדֶשׁ תִּשְׁרֵי. שֶׁאֲנִי אוֹכֵל שָׁנָה אַחַת הֲרֵי זֶה אָסוּר שָׁנָה תְּמִימָה מִיּוֹם לְיוֹם. וְאִם נִתְעַבְּרָה הַשָּׁנָה אָסוּר בָּהּ וּבְעִבּוּרָהּ. שֶׁאֲנִי אוֹכֵל שָׁנָה הֲרֵי זֶה אָסוּר שָׁנָה תְּמִימָה מִיּוֹם לְיוֹם מִסָּפֵק כְּמוֹ שֶׁבֵּאַרְנוּ:","שֶׁאֲנִי שׁוֹתֶה יַיִן שָׁבוּעַ זֶה אָסוּר בִּשְׁאָר שְׁנֵי הַשָּׁבוּעַ וּבִשְׁנַת הַשְּׁמִטָּה. וְאֵינוֹ מֻתָּר אֶלָּא מֵרֹאשׁ הַשָּׁנָה שֶׁל מוֹצָאֵי שְׁבִיעִית. שֶׁאֲנִי שׁוֹתֶה יַיִן שָׁבוּעַ אֶחָד אָסוּר שֶׁבַע שָׁנִים גְּמוּרוֹת מִיּוֹם לְיוֹם. אָמַר יוֹבֵל זֶה אָסוּר בִּשְׁאָר שְׁנֵי הַיּוֹבֵל וּבִשְׁנַת חֲמִשִּׁים עַצְמָהּ:","שֶׁאֲנִי שׁוֹתֶה יַיִן עַד רֹאשׁ אֲדָר אִם הָיְתָה שָׁנָה מְעֻבֶּרֶת וְלֹא יָדַע שֶׁהִיא מְעֻבֶּרֶת כְּשֶׁנָּדַר אֵינוֹ אָסוּר אֶלָּא עַד רֹאשׁ חֹדֶשׁ אֲדָר רִאשׁוֹן. וְאִם נָדַר עַד סוֹף אֲדָר הֲרֵי זֶה אָסוּר עַד סוֹף אֲדָר שֵׁנִי. וְאִם יָדַע שֶׁהַשָּׁנָה מְעֻבֶּרֶת וְנָדַר עַד רֹאשׁ אֲדָר אָסוּר עַד רֹאשׁ אֲדָר שֵׁנִי:","הָאוֹסֵר עַצְמוֹ בְּדָבָר עַד הַפֶּסַח בֵּין שֶׁאָמַר עַד פְּנֵי הַפֶּסַח בֵּין שֶׁאָמַר עַד הַפֶּסַח אֵינוֹ אָסוּר אֶלָּא עַד שֶׁיַּגִּיעַ בִּלְבַד. וְאִם אָמַר עַד שֶׁיִּהְיֶה הַפֶּסַח הֲרֵי אָסוּר עַד שֶׁיֵּצֵא הַפֶּסַח. אָמַר עַד הַקָּצִיר אוֹ עַד הַבָּצִיר אוֹ שֶׁאָמַר עַד שֶׁיִּהְיֶה הַבָּצִיר אוֹ הַקָּצִיר אֵינוֹ אָסוּר אֶלָּא עַד שֶׁיַּגִּיעַ:","זֶה הַכְּלָל כָּל שֶׁזְּמַנּוֹ קָבוּעַ וְנָדַר עָדָיו אֵין אָסוּר אֶלָּא עַד שֶׁיַּגִּיעַ. וְאִם נָדַר עַד שֶׁיִּהְיֶה הֲרֵי זֶה אָסוּר עַד שֶׁיֵּצֵא. וְכָל שֶׁאֵין לוֹ זְמַן קָבוּעַ כְּגוֹן זְמַן הַקָּצִיר וְהַבָּצִיר בֵּין שֶׁנָּדַר עָדָיו בֵּין שֶׁנָּדַר עַד שֶׁיִּהְיֶה אֵינוֹ אָסוּר אֶלָּא עַד שֶׁיַּגִּיעַ:","הָאוֹסֵר עַצְמוֹ בְּדָבָר עַד הַקַּיִץ הֲרֵי אָסוּר עַד שֶׁיַּתְחִילוּ אַנְשֵׁי הַמָּקוֹם שֶׁנָּדַר בּוֹ לְהַכְנִיס כַּלְכָּלוֹת תְּאֵנִים. עַד הַקָּצִיר עַד שֶׁיַּתְחִילוּ הָעָם לִקְצֹר קְצִיר חִטִּים אֲבָל לֹא קְצִיר שְׂעוֹרִים. פֵּרֵשׁ וְאָמַר עַד שֶׁיַּעֲבֹר הַקַּיִץ הֲרֵי זֶה אָסוּר עַד שֶׁיִּכְפְּלוּ הָעָם רֹב הַמַּחְצְלָאוֹת שֶׁבַּמֻּקְצֶה שֶׁמְּיַבְּשִׁין עֲלֵיהֶם תְּאֵנִים וַעֲנָבִים לַעֲשׂוֹתָם גְּרוֹגָרוֹת וְצִמּוּקִים הַכּל לְפִי מְקוֹם נִדְרוֹ שֶׁל נוֹדֵר:","כֵּיצַד. הֲרֵי שֶׁנָּדַר בְּבִקְעָה וְאָסַר עַצְמוֹ בַּדָּבָר עַד הַקַּיִץ וְעָלָה לָהָר אֵינוֹ מִסְתַּכֵּל בַּקַּיִץ שֶׁל מָקוֹם שֶׁהוּא בּוֹ עַתָּה אִם הִגִּיעַ אִם לֹא הִגִּיעַ. אֶלָּא בַּקַּיִץ שֶׁל מָקוֹם שֶׁנָּדַר בּוֹ וְעָלָיו הוּא סוֹמֵךְ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הָאוֹסֵר עַצְמוֹ בְּדָבָר עַד הַגֶּשֶׁם. הֲרֵי זֶה אָסוּר עַד זְמַן הַגְּשָׁמִים שֶׁהוּא בְּאֶרֶץ יִשְׂרָאֵל רֹאשׁ חֹדֶשׁ כִּסְלֵו. הִגִּיעַ זְמַן הַגְּשָׁמִים הֲרֵי זֶה מֻתָּר בֵּין יָרְדוּ גְּשָׁמִים בֵּין לֹא יָרְדוּ. וְאִם יָרְדוּ גְּשָׁמִים מִשִּׁבְעָה עָשָׂר בְּמַרְחֶשְׁוָן הֲרֵי זֶה מֻתָּר. וְאִם אָמַר עַד הַגְּשָׁמִים הֲרֵי זֶה אָסוּר עַד שֶׁיֵּרְדוּ הַגְּשָׁמִים. וְהוּא שֶׁיָּרְדוּ מִזְּמַן רְבִיעָה שְׁנִיָּה שֶׁהוּא בְּאֶרֶץ יִשְׂרָאֵל וּמְקוֹמוֹת הַסְּמוּכִין לָהּ מִכ\"ג בְּמַרְחֶשְׁוָן וְאֵילָךְ. וְאִם פֵּרֵשׁ וְאָמַר עַד שֶׁיִּפָּסְקוּ הַגְּשָׁמִים הֲרֵי זֶה אָסוּר עַד שֶׁיַּעֲבֹר הַפֶּסַח בְּאֶרֶץ יִשְׂרָאֵל וּבִמְקוֹמוֹת שֶׁהֵם כְּמוֹתָהּ:","מִי שֶׁהִדִּיר אֶת אִשְׁתּוֹ בְּמַרְחֶשְׁוָן וְאָמַר לָהּ שֶׁאֵין אַתְּ נֶהֱנֵית לִי מִכָּאן וְעַד הַפֶּסַח אִם תֵּלְכִי לְבֵית אָבִיךָ מֵהַיּוֹם וְעַד סֻכּוֹת הֲרֵי זוֹ אֲסוּרָה לֵהָנוֹת לוֹ מִיָּד גְּזֵרָה שֶׁמָּא תֵּלֵךְ. וְאִם הָלְכָה לִפְנֵי הַפֶּסַח וַהֲרֵי הוּא מְהַנֶּה אוֹתָהּ לִפְנֵי הַפֶּסַח הֲרֵי זֶה לוֹקֶה. עָבַר הַפֶּסַח אַף עַל פִּי שֶׁהָלַךְ הַתְּנַאי הֲרֵי זֶה אָסוּר לִנְהֹג חֻלִּין בְּנִדְרוֹ וּלְהַנִּיחָהּ שֶׁתֵּלֵךְ וְתֶהֱנֶה. אֶלָּא נוֹהֵג בָּהּ אִסּוּר עַד הֶחָג כְּמוֹ שֶׁנָּדַר. וְאַף עַל פִּי שֶׁתָּלָה הַנֵּדֶר בְּאִסּוּר זְמַן שֶׁעָבַר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְאִם הָלְכָה אַחַר הַפֶּסַח אֵינָהּ אֲסוּרָה מִלֵּהָנוֹת לוֹ:","אָמַר לָהּ שֶׁאֵין אַתְּ נֶהֱנֵית לִי עַד הֶחָג אִם תֵּלְכִי לְבֵית אָבִיךָ עַד הַפֶּסַח אֲסוּרָה לֵהָנוֹת מִיָּד. וְאִם הָלְכָה לִפְנֵי הַפֶּסַח וְנִמְצָא מְהַנֶּה אוֹתָהּ הֲרֵי זֶה לוֹקֶה וַאֲסוּרָה בַּהֲנָיָתוֹ עַד הֶחָג וּמֻתֶּרֶת לֵילֵךְ לְבֵית אָבִיהָ מִשֶּׁהִגִּיעַ הַפֶּסַח:"],"Mishneh Torah, Woman Suspected of Infidelity 1":["קִנּוּי הָאָמוּר בַּתּוֹרָה (במדבר ה יד) \"וְקִנֵּא אֶת אִשְׁתּוֹ\" הוּא שֶׁיֹּאמַר לָהּ בִּפְנֵי עֵדִים אַל תִּסָּתְרִי עִם אִישׁ פְּלוֹנִי. אֲפִלּוּ הָיָה אָבִיהָ אוֹ אָחִיהָ אוֹ עַכּוּ\"ם אוֹ עֶבֶד אוֹ שָׁחוּף הוּא הָאִישׁ שֶׁאֵינוֹ מִתְקַשֶּׁה וְאֵינוֹ מוֹלִיד:","הַסְּתִירָה הָאֲמוּרָה בַּתּוֹרָה (במדבר ה יג) \"וְנִסְתְּרָה\" הוּא שֶׁתִּסָּתֵר עִם אוֹתוֹ הָאִישׁ שֶׁאָמַר לָהּ אַל תִּסָּתְרִי עִמּוֹ בִּפְנֵי שְׁנֵי עֵדִים. אִם שָׁהֲתָה עִמּוֹ כְּדֵי טֻמְאָה שֶׁהוּא כְּדֵי לִצְלוֹת בֵּיצָה וּלְגָמְעָהּ הֲרֵי זוֹ אֲסוּרָה עַל בַּעְלָהּ עַד שֶׁתִּשְׁתֶּה מֵי הַמָּרִים וְיִבָּדֵק הַדָּבָר. וּבִזְמַן שֶׁאֵין שָׁם מֵי סוֹטָה תֵּאָסֵר עָלָיו לְעוֹלָם וְתֵצֵא בְּלֹא כְּתֻבָּה:","קִנֵּא לָהּ עַל שְׁנַיִם כְּאֶחָד וְאָמַר לָהּ אַל תִּסָּתְרִי עִם פְּלוֹנִי וּפְלוֹנִי. וְנִסְתְּרָה עִם שְׁנֵיהֶן כְּאֶחָד וְשָׁהֲתָה כְּדֵי טֻמְאָה. אֲפִלּוּ הֵם שְׁנֵי אַחֶיהָ אוֹ אָבִיהָ וְאָחִיהָ הֲרֵי זוֹ אֲסוּרָה עַד שֶׁתִּשְׁתֶּה:","אָמַר לָהּ בִּפְנֵי שְׁנַיִם אַל תְּדַבְּרִי עִם פְּלוֹנִי אֵין זֶה קִנּוּי. וְאַף עַל פִּי שֶׁנִּסְתְּרָה עִמּוֹ בְּעֵדִים וְשָׁהֲתָה כְּדֵי טֻמְאָה לֹא נֶאֶסְרָה עָלָיו וְאֵינָהּ שׁוֹתָה בְּקִנּוּי זֶה:","וְכֵן אִם אָמַר לָהּ אַל תִּסָּתְרִי עִמּוֹ וְרָאוּהָ מְדַבֶּרֶת עִמּוֹ אֵין זוֹ סְתִירָה. וְלֹא נֶאֶסְרָה וְלֹא שׁוֹתָה. וְכֵן אִם לֹא קָדַם קִנּוּי וּבָאוּ שְׁנַיִם וְהֵעִידוּ שֶׁנִּסְתְּרָה עִם זֶה וְשָׁהֲתָה כְּדֵי טֻמְאָה לֹא נֶאֶסְרָה עַל בַּעְלָהּ וְאֵינָהּ שׁוֹתָה:","אָמַר לָהּ לֹא תִּסָּתְרִי עִם אִישׁ פְּלוֹנִי וְהָיָה קָטָן פָּחוֹת מִבֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד. אוֹ שֶׁאָמַר לָהּ אַל תִּסָּתְרִי עִם בְּהֵמָה זוֹ אֵין זֶה קִנּוּי שֶׁנֶּאֱמַר (במדבר ה יג) \"וְשָׁכַב אִישׁ אֹתָהּ\" פְּרָט לְקָטָן וְלִבְהֵמָה שֶׁאֵין אוֹסְרִין אוֹתָהּ עָלָיו:","בַּעַל שֶׁמָּחַל עַל קִנּוּיוֹ קֹדֶם שֶׁתִּסָּתֵר קִנּוּיוֹ מָחוּל וּכְאִלּוּ לֹא קִנֵּא לָהּ מֵעוֹלָם. אֲבָל אִם מָחַל אַחַר שֶׁתִּסָּתֵר אֵינוֹ יָכוֹל לִמְחל. גֵּרְשָׁהּ הֲרֵי זֶה כְּמִי שֶׁמָּחַל וְאִם הֶחֱזִירָהּ צָרִיךְ לְקַנְּאוֹת קִנּוּי אַחֵר:","קִנֵּא לָהּ בִּפְנֵי שְׁנַיִם וְרָאָה אוֹתָהּ שֶׁנִּסְתְּרָה עִם זֶה שֶׁקִּנֵּא לָהּ עָלָיו וְשָׁהֲתָה כְּדֵי טֻמְאָה הֲרֵי זוֹ אֲסוּרָה עָלָיו וְיוֹצִיא וְיִתֵּן כְּתֻבָּה. שֶׁאֵינוֹ יָכוֹל לְהַשְׁקוֹתָהּ עַל פִּי עַצְמוֹ. וְכֵן אִם שָׁמַע הָעָם מְרַנְּנִין אַחֲרֶיהָ אַחַר הַקִּנּוּי וְהַסְּתִירָה עַד שֶׁשָּׁמַע מֵהַנָּשִׁים הַטּוֹוֹת לְאוֹר הַלְּבָנָה נוֹשְׂאוֹת וְנוֹתְנוֹת בָּהּ שֶׁזִּנְּתָה עִם הָאִישׁ שֶׁקִּנֵּא לָהּ עָלָיו הֲרֵי זֶה אָסוּר לְקַיְּמָהּ וְיוֹצִיא וְיִתֵּן כְּתֻבָּה:","בָּא עֵד אֶחָד וְהֵעִיד לוֹ שֶׁנִּסְתְּרָה עִמּוֹ אַחַר קִנּוּי וְשָׁהֲתָה כְּדֵי טֻמְאָה. אִם הוּא נֶאֱמָן לוֹ וְדַעְתּוֹ סוֹמֶכֶת עָלָיו יוֹצִיא וְיִתֵּן כְּתֻבָּה. וְאִם לָאו הֲרֵי אִשְׁתּוֹ מֻתֶּרֶת לוֹ:","וְאֵלּוּ שֶׁבֵּית דִּין מְקַנִּין לָהֶן. מִי שֶׁנִּתְחָרֵשׁ בַּעְלָהּ אוֹ שֶׁנִּשְׁתַּטָּה אוֹ שֶׁהָיָה בִּמְדִינָה אַחֶרֶת אוֹ שֶׁהָיָה חָבוּשׁ בְּבֵית הָאֲסוּרִין. לֹא לְהַשְׁקוֹתָהּ אֶלָּא לְפָסְלָהּ מִכְּתֻבָּתָהּ:","כֵּיצַד. שָׁמְעוּ בֵּית דִּין שֶׁהָעָם מְרַנְּנִין אַחֲרֶיהָ. קוֹרְאִין אוֹתָהּ וְאוֹמְרִין לָהּ אַל תִּסָּתְרִי עִם אִישׁ פְּלוֹנִי. בָּאוּ עֵדִים אַחַר כָּךְ שֶׁנִּסְתְּרָה עִמּוֹ וְשָׁהֲתָה כְּדֵי טֻמְאָה בֵּית דִּין אוֹסְרִין אוֹתָהּ עַל בַּעְלָהּ לְעוֹלָם וְקוֹרְעִין כְּתֻבָּתָהּ. וּכְשֶׁיָּבוֹא בַּעְלָהּ אוֹ יַבְרִיא אוֹ יָצָא מִבֵּית הָאֲסוּרִין נוֹתֵן לָהּ גֵּט. וְאֵינוֹ יָכוֹל לְהַשְׁקוֹתָהּ מִפְּנֵי שֶׁלֹּא קִנֵּא לָהּ הוּא:","שָׁתָת מֵי הַמָּרִים וְנִקְּתָה מֵהֶן וְחָזַר וְקִנֵּא לָהּ עִם הָאִישׁ שֶׁהִשְׁקָה עַל יָדוֹ וְנִסְתְּרָה עִמּוֹ אֵינוֹ יָכוֹל לְהַשְׁקוֹתָהּ עַל יָדוֹ פַּעַם שְׁנִיָּה אֶלָּא תֵּאָסֵר עָלָיו לְעוֹלָם וְתֵצֵא בְּלֹא כְּתֻבָּה. אֲבָל אִם קִנֵּא לָהּ עִם אַחֵר וְנִסְתְּרָה עִם הָאַחֵר בְּעֵדִים מַשְׁקִין אוֹתָהּ פַּעַם שְׁנִיָּה וַאֲפִלּוּ כַּמָּה פְּעָמִים. וְהוּא שֶׁיַּשְׁקֶה אוֹתָהּ בְּכָל פַּעַם בִּגְלַל אִישׁ אַחֵר:","הִשְׁקָה אוֹתָהּ וְגֵרְשָׁהּ וְנִשֵּׂאת לְאַחֵר וְקִנֵּא לָהּ עִם הָאִישׁ שֶׁהִשְׁקָה אוֹתָהּ הַבַּעַל הָרִאשׁוֹן בִּגְלָלוֹ וְנִסְתְּרָה עִמּוֹ בְּעֵדִים. הֲרֵי הַבַּעַל הַשֵּׁנִי מַשְׁקֶה אוֹתָהּ עַל יָדוֹ מִפְּנֵי שֶׁהוּא בַּעַל שֵׁנִי. וַאֲפִלּוּ מֵאָה וְנִשֵּׂאת לְזֶה אַחַר זֶה מַשְׁקִין אוֹתָהּ עַל יְדֵי אִישׁ אֶחָד. וְאֵין אוֹמְרִין וַדַּאי שֶׁהֻחְזְקָה לָזֶה וּטְמֵאָה עַד שֶׁיִּהְיֶה שָׁם עֵד:","הָאִשָּׁה שֶׁקִּנֵּא לָהּ בַּעְלָהּ וְנִסְתְּרָה אַחַר הַקִּנּוּי עִמּוֹ בְּעֵדִים וַהֲרֵי הִיא עוֹמֶדֶת לִשְׁתּוֹת וּבָא עֵד אֶחָד וְהֵעִיד עָלֶיהָ שֶׁנִּבְעֲלָה בְּפָנָיו עִם זֶה שֶׁקִּנֵּא לָהּ עִמּוֹ הֲרֵי זֶה אֲסוּרָה עַל בַּעְלָהּ לְעוֹלָם. וְאֵינָהּ שׁוֹתָה וְיוֹצֵאת בְּלֹא כְּתֻבָּה. וַאֲפִלּוּ הָיָה עֵד טֻמְאָה זֶה אֶחָד מֵעֵדֵי הַסְּתִירָה שֶׁנֶּאֱמַר (במדבר ה יג) \"וְעֵד אֵין בָּהּ\" וַהֲרֵי כָּאן עֵד:","אֲפִלּוּ אִשָּׁה וְעֶבֶד וְשִׁפְחָה וּפָסוּל לְעֵדוּת בַּעֲבֵרָה מִדִּבְרֵי סוֹפְרִים וַאֲפִלּוּ קָרוֹב נֶאֱמָן לְעֵדוּת סוֹטָה לְהָעִיד עָלֶיהָ שֶׁזִּנְּתָה וְתֵאָסֵר עַל בַּעְלָהּ לְעוֹלָם. וְאֵינָהּ שׁוֹתָה וְתֵצֵא בְּלֹא כְּתֻבָּה. הוֹאִיל וְקָדַם הַקִּנּוּי וְהַסְּתִירָה בְּעֵדִים כְּשֵׁרִים וְהַתּוֹרָה הֶאֱמִינָה עֵד אֶחָד בְּטֻמְאָה הֲרֵי כֻּלָּן כְּשֵׁרִין לְעֵדוּת טֻמְאָה. אַף חָמֵשׁ נָשִׁים שֶׁשּׂוֹנְאוֹת זוֹ אֶת זוֹ מְעִידוֹת זוֹ עַל זוֹ לוֹמַר שֶׁנִּטְמֵאת. וְנֶאֱמֶנֶת עָלֶיהָ לְאָסְרָהּ עַל בַּעְלָהּ וְשֶׁלֹּא לְהַשְׁקוֹתָהּ. אֲבָל לֹא לְהַפְסִידָהּ מִכְּתֻבָּתָהּ. אֶלָּא נוֹטֶלֶת כְּתֻבָּתָהּ וְיוֹצְאָה:","בָּא עֵד אֶחָד כָּשֵׁר וְאָמַר נִטְמֵאת הֲרֵי זוֹ אֵינָהּ שׁוֹתָה כְּמוֹ שֶׁבֵּאַרְנוּ. בָּא עֵד אֶחָד וְהִכְחִישׁוֹ וְאָמַר לֹא נִטְמֵאת אֵין שׁוֹמְעִין לוֹ. שֶׁעֵד אֶחָד בְּטֻמְאַת סוֹטָה כִּשְׁנַיִם. וְאֵין דְּבָרָיו שֶׁל אַחֲרוֹן דּוֹחִין דִּבְרֵי הָרִאשׁוֹן שֶׁהוּא כִּשְׁנַיִם:","בָּאוּ שְׁנֵיהֶן כְּאֶחָד זֶה אוֹמֵר נִטְמֵאת וְזֶה אוֹמֵר לֹא נִטְמֵאת. אוֹ שֶׁאָמַר אֶחָד נִטְמֵאת וּבָאוּ שְׁנַיִם אֲחֵרִים וְאָמְרוּ לֹא נִטְמֵאת הֲרֵי זוֹ שׁוֹתָה:","בָּא עֵד אֶחָד כָּשֵׁר וְנָשִׁים רַבּוֹת אוֹ פְּסוּלִין רַבִּים כְּאֶחָד. הָעֵד אוֹמֵר נִטְמֵאת וְהַנָּשִׁים אוֹ הַפְּסוּלִין אוֹמְרִים לֹא נִטְמֵאת הֲרֵי זוֹ שׁוֹתָה. שֶׁעֵד אֶחָד וּפְסוּלִין רַבִּים כְּמֶחֱצָה עַל מֶחֱצָה הֵם:","הָיוּ כֻּלָּן פְּסוּלִין הַלֵּךְ אַחַר הָרֹב. כֵּיצַד. שְׁתֵּי נָשִׁים אוֹמְרוֹת נִטְמֵאת וְשָׁלֹשׁ אוֹמְרוֹת לֹא נִטְמֵאת הֲרֵי זוֹ שׁוֹתָה. שָׁלֹשׁ אוֹמְרוֹת לֹא נִטְמֵאת וְאַרְבַּע אוֹמְרוֹת נִטְמֵאת הֲרֵי זוֹ אֵינָהּ שׁוֹתָה. הָיוּ מֶחֱצָה עַל מֶחֱצָה הֲרֵי זוֹ שׁוֹתָה:","כָּל סוֹטָה שֶׁאָמַרְנוּ שֶׁאֵינָהּ שׁוֹתָה מִפְּנֵי עֵדֵי טֻמְאָה הֲרֵי זוֹ אֲסוּרָה עַל בַּעְלָהּ לְעוֹלָם וְתֵצֵא בְּלֹא כְּתֻבָּה שֶׁהֲרֵי נֶאֶסְרָה בְּקִנּוּי וּסְתִירָה. וְהַשְּׁתִיָּה שֶׁתַּתִּירָהּ נִמְנְעָה שֶׁהֲרֵי יֵשׁ בָּהּ עֵד כְּמוֹ שֶׁבֵּאַרְנוּ:"]} as Record<string, string[]>;
